window.KG_BOOK=window.KG_BOOK||{};
window.KG_BOOK["07"]=[{"id":"1.1","t":"微生物的概念与类群范围","s":3,"c":"1. 微生物与微生物学","x":"微生物是一切肉眼不可见、必须借助光学显微镜或电子显微镜才能观察其个体形态的微小生物的总称。这一概念是\"人为的、非分类学的\"集合，其边界由观察手段决定，因此并非一个自然分类单元。按细胞结构，微生物包括属于原核生物的细菌（真细菌）、放线菌、蓝细菌、古菌、支原体、立克次氏体、衣原体、螺旋体，属于真核生物的酵母菌、霉菌、蕈菌、原生动物和单细胞藻类，以及属于非细胞生物的病毒、类病毒、拟病毒和朊病毒。微生物学是研究微生物的形态结构、生理代谢、遗传变异、生态分布与分类进化，并进而将其应用于工业、农业、医药与环境保护的一门学科。它的研究对象决定了它既是一门基础学科（提供模式生物与分子生物学基本原理），又是一门应用性极强的技术学科。类群细胞类型主要代表与人类的关系细菌原核大肠杆菌、枯草芽孢杆菌肠道正常菌群、工程菌、病原放线菌原核链霉菌、诺卡氏菌抗生素主要产生菌、土壤异味蓝细菌原核颤藻、鱼腥藻固氮、水华、叶绿体起源古菌原核甲烷杆菌、盐杆菌极端环境、沼气、进化研究真菌真核酵母菌、青霉、蘑菇发酵、抗生素、食品腐败原生动物真核草履虫、疟原虫水体指示生物、寄生虫病毒非细胞T4 噬菌体、HIV噬菌体治疗、传染病、载体"},{"id":"1.2","t":"共性一：体积小，面积大","s":3,"c":"1. 微生物与微生物学","x":"微生物最本质的特征是个体极小，由此导致其比面值（表面积与体积之比）极大；对一个直径 1 μm 的球菌，比面值可达 6×10⁴ cm²/cm³，而人体细胞比面值不足其百分之一。比面值之大意味着巨大的营养物质吸收面、代谢废物排泄面和环境信息交换面，因此这一条是其余四条共性的根源，也是理解微生物一切生理特性的起点。竞赛中常见的追问是\"为什么微生物代谢速率高、生长快、易于适应环境\"，答案都要回到小体积大面积这一几何学基础。"},{"id":"1.3","t":"共性二、三：吸收多转化快，生长旺繁殖快","s":3,"c":"1. 微生物与微生物学","x":"吸收多、转化快是指微生物单位重量在单位时间内催化转化的物质量远高于动植物：大肠杆菌在 1 h 内可分解相当于自身重量 1000~10000 倍的乳糖，产朊假丝酵母合成蛋白质的能力比大豆强 100 倍、比食用牛强 10 万倍。生长旺、繁殖快是指微生物在适宜条件下以指数方式增殖：大肠杆菌在的最适条件下每分裂一次仅需 12.5~20 min（竞赛常取 20 min），理论上每昼夜可分裂72 次，一个细胞可产生约 4.7×10²¹ 个子细胞，总重量可达数千吨。实际上由于营养耗尽、代谢产物积累与 pH 变化，这一数字永远不会实现，这正是理解生长曲线出现稳定期与衰亡期的关键。"},{"id":"1.4","t":"共性四：适应强，易变异","s":3,"c":"1. 微生物与微生物学","x":"微生物对高温、高酸、高碱、高盐、高压、高辐射和寡营养等极端环境具有惊人的适应能力，这一能力来自其多样的代谢类型、快速的基因表达调节以及庞大的种群基数。微生物的个体突变率并不高（一般为 10⁻⁵~10⁻¹⁰），但由于繁殖极快、世代极短，单位时间内产生的变异后代数量巨大，因而在短时间内即可筛选出适应新环境的类型。青霉素产量从最初约 20 U/mL 提高到 10 万U/mL 以上的育种史，以及临床病原菌耐药性的迅速蔓延，分别是这一共性在有益和有害两个方向上的经典例证。"},{"id":"1.5","t":"共性五：分布广，种类多","s":3,"c":"1. 微生物与微生物学","x":"微生物几乎无孔不入，从万米高空、大洋底部、地下数千米岩层到火山口、盐湖、强酸矿水都有分布，只有人为灭菌的场所和极少数高温熔岩中心才近乎无菌。种类多体现在五个层面：物种多样性（估计有 50 万至 600 万种，已记载描述约 20 万种）、生理代谢类型多样性、代谢产物多样性、遗传基因多样性和生态类型多样性。要注意\"已记载约 20 万种\"与\"估计 50 万~600 万种\"是两个不同性质的数字，前者是描述种数，后者是推测总数。"},{"id":"1.6","t":"微生物学的分科","s":1,"c":"1. 微生物与微生物学","x":"按研究对象可分为细菌学、真菌学、病毒学、藻类学、原生动物学和古菌学；按研究层次与过程可分为微生物形态学、生理学、生物化学、遗传学、生态学和分类学；按应用领域可分为工业微生物学、农业微生物学、医学微生物学、食品微生物学、土壤微生物学和环境微生物学。各分支相互交叉，例如医学微生物学同时依赖免疫学、遗传学与分子生物学的方法。理解分科体系的意义在于：竞赛中的\"微生物\"题往往跨分支命题，需要用同一套概念在结构、代谢、遗传与生态之间迁移。"},{"id":"2.1","t":"形态学时期：微生物的发现","s":2,"c":"2. 微生物学发展的四个阶段","x":"1665 年 Hooke 在《显微图谱》中描述了霉菌的子实体，\"microorganism\"一词的直观形象始于此。1676 年（常记为 1683 年发表）荷兰人 Leeuwenhoek 用自制的单式显微镜（放大 200~300 倍）首次观察到细菌、原生动物和酵母，称之为\"微小动物\"，他是公认的微生物学先驱。这一时期长达约二百年，特点是只能描述形态与计数，无法回答\"微生物从何而来、有什么生理作用\"，因为纯培养技术与灭菌技术尚未建立。"},{"id":"2.2","t":"生理学时期与 Pasteur 的贡献","s":3,"c":"2. 微生物学发展的四个阶段","x":"Pasteur 用曲颈瓶实验否定了自然发生说：瓶口弯曲使空气可自由进入而尘埃与菌体被阻留，肉汤长期不腐败；一旦折断曲颈或倾斜使肉汤接触弯管处的尘埃，腐败立即发生。这一设计的精髓在于\"既通空气又阻微生物\"，从而同时反驳了\"腐败需要空气中之生命力\"与\"腐败自发产生\"两种观点。他还证明酒精发酵、乳酸发酵均由特定微生物引起，发明了巴氏消毒法（60~65℃ 30 min或 72℃ 15 s），并研制出炭疽疫苗与 1885 年的狂犬病疫苗，因此被称为\"微生物学之父\"。"},{"id":"2.3","t":"生理学时期与 Koch 及柯赫法则","s":3,"c":"2. 微生物学发展的四个阶段","x":"Koch 于 1876 年首次证明炭疽杆菌是炭疽的病原，1882 年发现结核分枝杆菌，并创立了固体培养基分离纯培养（明胶改用琼脂）、细菌染色与显微摄影等技术，使\"一种疾病由一种特定微生物引起\"成为可检验的命题。柯赫法则包括四步：从患病机体中分离出病原体并纯培养；将该纯培养物接种健康易感宿主引起相同疾病；从人工发病宿主中重新分离到同一病原体；再次纯培养获得相同性状的菌株。该法则的例外包括无症状携带者、需动物模型才能复现的病原、以及活的非可培养状态（VBNC）细菌，现代分子版本以 PCR 或测序检出特异性基因替代第三步。"},{"id":"2.4","t":"生化遗传学时期","s":2,"c":"2. 微生物学发展的四个阶段","x":"20 世纪中叶，微生物成为揭示遗传物质本质的主角：1928 年 Griffith 用肺炎链球菌小鼠实验发现转化现象，1944 年 Avery 等证明转化因子是 DNA，1952 年 Hershey 与 Chase 用 32P 与 35S 标记噬菌体确证 DNA 为遗传物质；1941 年 Beadle 与 Tatum 用粗糙脉孢菌提出\"一基因一酶\"假说；1946 年Lederberg 与 Tatum 发现细菌接合；1953 年 Watson 与 Crick 提出 DNA 双螺旋。同一时期抗生素登上历史舞台：1928 年 Fleming 观察到青霉菌抑制葡萄球菌，1940 年代 Florey 与 Chain 实现青霉素的临床提取应用，1944 年Waksman 发现链霉素，结核病从此有了化疗手段。"},{"id":"2.5","t":"分子微生物学时期与 Woese 的三域系统","s":3,"c":"2. 微生物学发展的四个阶段","x":"1977 年 Woese 通过比较 16S rRNA 寡核苷酸序列（后发展为全序列比较）发现原核生物并非单一类群，而分为细菌与古菌两大分支，1990 年正式提出三域系统：Bacteria（细菌域）、Archaea（古菌域）、Eucarya（真核生物域）。三域系统的革命性在于用可定量的分子序列取代了以形态和营养方式为依据的旧分类，并把真核生物与古菌在系统树上拉近，为内共生学说提供了框架。此后的里程碑包括 1983 年 Mullis 发明 PCR、1995 年流感嗜血杆菌成为第一个被测序的自由生活生物全基因组、宏基因组学的兴起以及 CRISPRCas 机制的阐明。"},{"id":"2.6","t":"我国微生物学的发展","s":1,"c":"2. 微生物学发展的四个阶段","x":"伍连德在 1910 年东北鼠疫流行中通过隔离、消毒与口罩防护控制了疫情，是中国现代防疫实践的开端。汤飞凡于 1956 年在世界上首次分离培养成功沙眼衣原体（TE55 株），为衣原体研究奠定了基础。1953 年我国实现青霉素工业化生产，此后在谷氨酸发酵、维生素 C 两步发酵、农用抗生素与疫苗研发方面都有独立贡献。2020 年新冠疫情中我国率先完成病毒全基因组测定并开展多路线疫苗研发，体现了微生物学在国家公共卫生安全中的战略地位。阶段时间核心问题标志性人物与事件形态学时期17 世纪—19 世纪中叶微生物长什么样Leeuwenhoek 观察到细菌；Hooke 描述霉菌生理学时期19 世纪中叶—20 世纪初微生物做什么Pasteur 曲颈瓶与巴氏消毒；Koch 柯赫法则生化遗传学时期20 世纪初—1950 年代微生物的化学与遗传基础Avery 转化因子；Beadle 一基因一酶；Fleming 青霉素分子微生物学时期1970 年代至今序列、基因组与调控网络Woese 三域系统；PCR；CRISPR"},{"id":"3.1","t":"病原微生物与传染病","s":3,"c":"3. 微生物与人类","x":"在人类历史上，鼠疫（鼠疫耶尔森氏菌）、霍乱（霍乱弧菌）、结核（结核分枝杆菌）、天花（天花病毒）和疟疾（疟原虫）造成了远大于战争的死亡。近几十年新发传染病中约 70% 属于动物源性，如 HIV、SARS 冠状病毒、禽流感 H5N1/H7N9 与 COVID-19 的病原 SARS-CoV-2，提示人类活动范围扩张、野生动物贸易与气候变化是重要驱动因素。控制策略围绕三条主线：控制传染源、切断传播途径、保护易感人群，其微生物学基础分别是消毒灭菌、隔离防护与疫苗接种。"},{"id":"3.2","t":"微生物与工业发酵","s":2,"c":"3. 微生物与人类","x":"微生物是工业生物技术的细胞工厂：酿酒酵母生产乙醇，黑曲霉生产柠檬酸，谷氨酸棒杆菌生产味精（谷氨酸），产黄青霉与顶头孢霉生产青霉素与头孢菌素，阿舒假囊酵母生产维生素 B2，地衣芽孢杆菌生产 α-淀粉酶。选择生产菌种的基本要求包括：遗传性状稳定、生长繁殖快、营养要求粗放、产酶活性高、不产生有毒副产物、对噬菌体有抗性。工业发酵的核心指标是产率、转化率与产物浓度，其提升依赖菌种改良（诱变、代谢工程）与工艺控制（补料、恒化、固定化）。"},{"id":"3.3","t":"微生物与农业、环境","s":2,"c":"3. 微生物与人类","x":"农业上，根瘤菌与豆科植物的共生固氮每年固定大量氮素，丛枝菌根真菌提高作物对磷的吸收，苏云金芽孢杆菌（Bt）的杀虫晶体蛋白构成生物农药，白僵菌与绿僵菌用于虫害防治。环境上，微生物是污染物的主要分解者：活性污泥法处理污水，厌氧消化生产沼气，石油降解菌与重金属还原菌用于生物修复。理解这一类应用的关键，是把微生物的代谢多样性（分解各种天然与人工合成化合物的能力）与生态学原理（群落、竞争、共代谢）结合起来。"},{"id":"3.4","t":"微生物与人体共生","s":3,"c":"3. 微生物与人类","x":"人体皮肤、口腔、呼吸道、消化道和泌尿生殖道定植着大量微生物，近年估计人体细菌总数约 3.8×10¹³ 个，与人体自身细胞数（约 3.0×10¹³ 个）大致相当，其编码基因总数约为人体基因组的 100~150 倍，被称为\"人体第二基因组\"。肠道菌群参与膳食纤维发酵产生短链脂肪酸、合成维生素 K 与部分 B 族维生素、竞争性排斥病原菌并训练免疫系统，还通过肠—脑轴影响神经与行为。菌群失衡（dysbiosis）与肥胖、炎症性肠病、过敏和代谢综合征相关，粪菌移植已成为治疗艰难拟梭菌反复感染的有效手段。"},{"id":"3.5","t":"微生物作为模式生物","s":2,"c":"3. 微生物与人类","x":"微生物因世代短、基因组小、易于遗传操作而成为生命科学的模式系统：大肠杆菌与 T4 噬菌体确立了中心法则与遗传密码，粗糙脉孢菌用于一基因一酶假说，酿酒酵母是细胞周期与真核基因调控研究的主力，枯草芽孢杆菌是革兰阳性菌与芽孢分化的模型。分子生物学的重大发现几乎都以微生物为材料，这本身说明微生物学在生命科学中的基础地位。竞赛材料题中如需判断\"某实验结论能否推广到其他生物\"，应回到模式生物的适用边界来回答。"},{"id":"3.6","t":"微生物的危害与生物安全","s":1,"c":"3. 微生物与人类","x":"除致病外，微生物还引起食品腐败、材料霉变、金属腐蚀与农作物病害，造成巨大经济损失。实验室与工业生产中须按生物安全等级（BSL-1 至BSL-4）管理病原，BSL-4 用于埃博拉、马尔堡等无有效防治手段的高危病毒。耐药性已成为全球公共卫生危机，\"新德里金属 β-内酰胺酶\"（NDM-1）超级细菌几乎对所有 β-内酰胺类耐药，其根源在于抗生素滥用与耐药基因的水平转移。理解\"双刃剑\"这一判断，需要在每一章都同时看到益处与风险。第二篇 原核微生物形态与结构原核微生物是竞赛的绝对重点区，命题密度最高。复习时要建立\"由外到内\"的空间顺序：荚膜—细胞壁—细胞膜—细胞质—核区，再叠加两个特殊结构（鞭毛、芽孢）与两类附着结构（菌毛、糖被）。每提到一个结构，都要能说出三件事：由什么化学物质构成、有什么功能、与致病性或药物作用有什么关系。"},{"id":"4.1","t":"细菌的形态、大小与排列","s":3,"c":"4. 细菌的形态与细胞壁","x":"细菌的基本形态为球状、杆状和螺旋状三类，此外有丝状、三角形、方形和柄状等特殊形态。球菌按分裂面与分裂后是否分离分为单球菌、双球菌（如肺炎链球菌）、链球菌（如溶血性链球菌）、四联球菌、八叠球菌（如藤黄八叠球菌）和葡萄球菌；杆菌按长度与宽度比、两端形态、芽孢位置和排列方式描述，如单杆菌、双杆菌、链杆菌、棒状杆菌。多数细菌直径或宽度为 0.5~1μm，用测微尺测量，光学显微镜下需染色才能看清；螺旋菌按弯曲程度分为弧菌（不足一圈，如霍乱弧菌）与螺菌（多圈且刚性）。"},{"id":"4.2","t":"革兰阳性菌细胞壁：肽聚糖与磷壁酸","s":3,"c":"4. 细菌的形态与细胞壁","x":"肽聚糖（peptidoglycan，黏肽）由 N-乙酰葡糖胺（NAG）与 N-乙酰胞壁酸（NAM）以 β-1,4 糖苷键交替连接成聚糖骨架，四肽侧链连接于 NAM上，相邻侧链再通过肽桥交联成网状。革兰阳性菌的四肽侧链为 L-丙氨酸—D谷氨酸—L-赖氨酸—D-丙氨酸，肽桥为五个甘氨酸组成的五肽桥；革兰阴性菌的四肽侧链第三位是内消旋二氨基庚二酸（DAP），没有专门肽桥，侧链间直接交联。革兰阳性菌肽聚糖层厚 20~80 nm、可达 40 层，占细胞壁干重的60%~90%，且含有独特的磷壁酸（teichoic acid）：与肽聚糖共价连接的称壁磷壁酸，与质膜脂类相连的称脂磷壁酸（LTA）。磷壁酸使细胞壁带负电荷、可结合 Mg²⁺ 等阳离子、构成革兰阳性菌的表面抗原与噬菌体受体，并参与调节自溶素活性。"},{"id":"4.3","t":"革兰阴性菌细胞壁：外膜与脂多糖","s":3,"c":"4. 细菌的形态与细胞壁","x":"革兰阴性菌肽聚糖层薄，仅 2~3 nm、1~2 层，占细胞壁干重的5%~10%，且不含磷壁酸；其细胞壁的特征结构是外侧的外膜（outer membrane），由脂多糖（LPS）、磷脂和外膜蛋白组成。LPS 由类脂 A、核心多糖和 O-特异性多糖（O 抗原）三部分组成，类脂 A 是内毒素的活性中心，O 抗原决定菌体抗原（O 抗原）的血清型特异性。外膜中三聚体形式的孔蛋白（porin，如 OmpF、OmpC）形成亲水性通道，允许分子量小于约 600 的水溶性物质通过；外膜与肽聚糖之间的周质空间（periplasm）富含结合蛋白、水解酶与 β-内酰胺酶，是革兰阴性菌耐药的重要屏障。"},{"id":"4.4","t":"革兰染色的机制与意义","s":3,"c":"4. 细菌的形态与细胞壁","x":"革兰染色步骤为：结晶紫初染 1 min，碘液媒染形成结晶紫-碘大分子复合物，95% 乙醇脱色数十秒，最后番红（沙黄）复染。革兰阳性菌因肽聚糖层厚且交联致密，乙醇使细胞壁脱水、孔径缩小，复合物被阻留而呈紫色；革兰阴性菌肽聚糖层薄、外膜富含脂质，乙醇溶解脂质后细胞壁通透性剧增，复合物被洗脱，经复染呈红色。其意义有四：一是最基本的鉴别染色，把细菌分为两大类；二是与致病性相关（革兰阴性菌含内毒素，革兰阳性菌产外毒素为主）；三是与药物敏感性相关（青霉素抑制转肽酶，对肽聚糖层厚、代谢旺盛的革兰阳性菌作用更强，而外膜阻碍其进入革兰阴性菌）；四是与疫苗和血清学分类相关。注意\"脱色\"是决定结果的关键步骤，脱色过度会使阳性菌误判为阴性。"},{"id":"4.5","t":"缺壁细菌：L 型细菌与支原体","s":3,"c":"4. 细菌的形态与细胞壁","x":"缺壁细菌按成因分为四类：实验室或体内自发突变形成的 L 型细菌；用青霉素、溶菌酶或噬菌体处理人工去除细胞壁的原生质体（革兰阳性菌去壁）与球状体（革兰阴性菌去壁）；以及天然无壁的支原体。L 型细菌必须在高渗低琼脂环境中才能存活，呈高度多形性，在固体培养基上形成\"油煎蛋状\"微小菌落，去除诱导因素后可回复为有壁细菌，临床上与抗生素治疗后病情迁延、反复发作有关。支原体是迄今所知能独立生活的最小生物，直径 0.2~0.3 μm，基因组仅约 0.6~1.4 Mb，其质膜含其他原核生物罕见的甾醇（胆固醇），因此对两性霉素 B、皂素等作用于甾醇的物质敏感，也对 β-内酰胺类天然耐药。此外，分枝杆菌属细胞壁含大量分枝菌酸等蜡质，革兰染色不易着色，需用抗酸染色（Ziehl-Neelsen 法）鉴别。"},{"id":"4.6","t":"细胞壁的其他功能与抗细胞壁药物靶点","s":2,"c":"4. 细菌的形态与细胞壁","x":"细胞壁维持细胞形态、抵抗内部渗透压（细菌胞内渗透压可达 5~20 个大气压）、参与物质运输与致病过程（黏附、内毒素、抗吞噬）。凡抑制细胞壁合成的药物对细菌有选择性毒性，因为人体细胞无细胞壁：青霉素与头孢菌素抑制转肽酶（青霉素结合蛋白 PBP）催化的交联反应；万古霉素与肽聚糖前体末端 D-Ala-D-Ala 结合，阻断聚合与交联；环丝氨酸抑制丙氨酸消旋酶与 DAla-D-Ala 合成酶；杆菌肽抑制焦磷酸酶、阻断载体脂循环；溶菌酶水解 NAG与 NAM 之间的 β-1,4 糖苷键。理解这一组靶点，是回答\"为什么青霉素对静止期细菌效果差\"\"为什么支原体对青霉素不敏感\"的关键。比较项肽聚糖厚度革兰阳性菌革兰阴性菌肽聚糖占壁干重20~80 nm，可达 40 层60%~90% 2~3 nm，1~2 层5%~10%四肽侧链第三位氨基酸L-赖氨酸内消旋二氨基庚二酸肽桥五个甘氨酸无，侧链直接交联磷壁酸有（壁磷壁酸、脂磷壁酸）无外膜与脂多糖无有，含类脂 A 与 O 抗原周质空间不明显明显，含 β-内酰胺酶革兰染色结果紫色红色溶菌酶敏感性高较低（外膜阻挡）"},{"id":"5.1","t":"细胞膜与内膜系统","s":3,"c":"5. 细胞壁以内的构造","x":"细菌细胞膜由磷脂双分子层与镶嵌蛋白构成，一般不含胆固醇（支原体例外），厚度约 7~8 nm，无细胞器膜的分化。其功能包括：选择性控制物质进出、作为呼吸链与 ATP 合成酶的场所、参与细胞壁与荚膜等大分子合成、分泌胞外酶与毒素、承载趋化受体。原核细胞的膜可向细胞内陷形成内膜系统：间体（mesosome）与呼吸、分裂和 DNA 复制有关，光合细菌的载色体（chromatophore）由膜内褶形成并携带光合色素，硝化细菌与甲烷氧化菌的膜内褶则密集排布呼吸链组分，用以扩大产能面积。这一构造是\"原核细胞以膜内褶替代细胞器\"的典型例证。"},{"id":"5.2","t":"核区与染色体","s":3,"c":"5. 细胞壁以内的构造","x":"细菌没有核膜、核仁和有丝分裂器，遗传物质以一条环状双链 DNA 分子的形式集中于细胞质的一定区域，称核区（nucleoid）或拟核，经 Feulgen染色可显示。大肠杆菌染色体约 4.6 Mb、含约 4300 个基因，在细胞内高度折叠成环状结构域，其折叠依赖类组蛋白（如 HU、H-NS）而非真核的组蛋白八聚体。除核区外，细菌还有染色体外的遗传因子（质粒、噬菌体 DNA）与转座因子。重要辨析：细菌染色体是\"一条环状 DNA\"的通常情形，但放线菌、蓝细菌等有线性染色体，伯氏疏螺旋体甚至有线性染色体与线性质粒，因此不可把\"环状\"当作所有细菌的绝对特征。"},{"id":"5.3","t":"核糖体","s":3,"c":"5. 细胞壁以内的构造","x":"细菌核糖体为 70S，由 50S 大亚基与 30S 小亚基组成，分别含 23S、5S rRNA 与 16S rRNA。16S rRNA 基因既含高度保守区又含可变区，是细菌系统发育分析与分子鉴定的首选标记；23S rRNA 基因则用于属、种水平的精细鉴别。核糖体是许多抗生素的靶点：链霉素、四环素、卡那霉素作用于 30S 亚基，红霉素、氯霉素、林可霉素、大环内酯类作用于 50S 亚基，它们与真核80S 核糖体的结构差异构成选择性毒性的基础。注意肽聚糖、鞭毛、核糖体这三类结构的\"70S、30S、50S\"数字常被混淆，须成组记忆。"},{"id":"5.4","t":"质粒","s":3,"c":"5. 细胞壁以内的构造","x":"质粒是细菌染色体外能自主复制的小型共价闭合环状双链 DNA，大小从 1 kb 到数百 kb 不等，携带的基因对细菌在特定环境下的生存有利但非必需。重要类型包括：F 质粒（致育因子，编码性菌毛与接合能力）、R 质粒（耐药质粒，可携带多重耐药基因并通过接合在菌间传播）、Col 质粒（编码大肠菌素）、Ti 质粒（根癌农杆菌的致瘤质粒，是植物转基因载体的来源）以及降解质粒（编码降解樟脑、辛烷、甲苯等的能力）。两种质粒不能在同一细胞中稳定共存的现象称不相容性，据此可分 incompatibility 群；质粒还可整合到染色体上形成附加体，是接合与转导研究的关键。"},{"id":"5.5","t":"细胞质与内含物","s":2,"c":"5. 细胞壁以内的构造","x":"细胞质是膜内的胶状物质，含核糖体、质粒、酶类和各种储藏物。常见内含物包括：聚-β-羟基丁酸（PHB）作为碳源与能源储藏，可用于生产可降解塑料；糖原粒；聚磷酸盐（异染粒，用甲苯胺蓝或美蓝染色呈紫红色，与藻类\"异染\"现象同名）；硫粒（贝日阿托氏菌、硫细菌氧化硫化氢后暂存于胞内）；磁小体（趋磁细菌内的 Fe₃O₄ 晶体，沿地磁场定向）；气泡（蓝细菌与浮游细菌用以调节浮力）；羧酶体（自养细菌固定 CO₂ 的 RuBisCO 聚集处）。储藏物的意义在于缓冲营养波动，因此富营养条件下培养的菌体常含大量储藏颗粒，可用染色法作快速判断。"},{"id":"5.6","t":"细菌的分裂与细胞骨架","s":2,"c":"5. 细胞壁以内的构造","x":"细菌以二分裂方式繁殖，过程包括染色体复制、复制起点区移向两极、FtsZ 在细胞中部聚合成环（Z 环）并招募其他分裂蛋白、隔膜形成与细胞分开。FtsZ 与真核微管蛋白同源，MreB 与肌动蛋白同源，CreS 与中间纤维类似，说明细胞骨架在进化上高度保守。分裂后若子细胞不分离，即形成链状或簇状排列，这正是球菌排列方式（链球菌、葡萄球菌、八叠球菌）的成因。芽孢杆菌分裂时还需在隔膜形成后进行\"吞并\"式膜融合，这是芽孢形成的基础步骤。"},{"id":"6.1","t":"荚膜与黏液层","s":3,"c":"6. 细胞壁以外的构造","x":"荚膜是某些细菌向细胞壁外分泌的多糖（少数为多肽，如炭疽杆菌的聚-D谷氨酸）黏性物质，厚约 0.2 μm 以上，与细胞壁结合紧密、边界清晰，用负染色（墨汁）或荚膜染色可显示；边界不清、疏松附着于壁上的称黏液层。荚膜的功能包括：抗吞噬和抗杀菌物质（最主要的毒力因子，有荚膜的肺炎链球菌致病力远强于无荚膜株）、抗干燥、黏附于表面形成生物膜、储存养料，以及作为抗原用于血清学分型（如肺炎链球菌的荚膜肿胀反应 Quellung）。荚膜并非细菌生存必需，丧失荚膜后仍可存活，但毒力显著下降，这是\"毒力因子≠生存必需\"的重要例证。"},{"id":"6.2","t":"S 层与糖被的生态意义","s":2,"c":"6. 细胞壁以外的构造","x":"许多细菌与古菌的最外层具有由蛋白质或糖蛋白亚单位组成的表面层（S层），呈晶格状排列，起分子筛、保护、维持形状和黏附作用，在古菌中几乎普遍存在。糖被（glycocalyx）是荚膜与黏液层的统称，其生态意义突出表现在生物膜形成上：细菌先以糖被黏附于固体表面，再通过群体感应协调基因表达，形成含多糖基质、水通道和多种菌种的结构化群落，其对抗生素的耐受性可提高 100~1000 倍。医学上，导管、人工瓣膜和牙菌斑表面的生物膜是难治性感染的根源，也是理解\"浮游菌与生物膜菌表型不同\"的入口。"},{"id":"6.3","t":"鞭毛的结构","s":3,"c":"6. 细胞壁以外的构造","x":"细菌鞭毛是直径约 20 nm、长 15~20 μm 的细长运动器官，由基体、钩形鞘和鞭毛丝三部分组成。基体埋于细胞壁与质膜中，革兰阴性菌有 L、P、MS、C 四个环（分别对应外膜、肽聚糖层、质膜与细胞质），革兰阳性菌仅有MS 环与 C 环；钩形鞘连接基体与鞭毛丝；鞭毛丝由鞭毛蛋白（flagellin）亚单位螺旋排列而成，中空。鞭毛不是直的，而是呈波浪形螺旋，其装配是从远端向尖端输送亚单位的自组装过程。按鞭毛数目与分布分为单毛菌、双毛菌、丛毛菌和周毛菌，鞭毛的有无和排列是菌种鉴定的形态学依据之一。"},{"id":"6.4","t":"鞭毛运动与趋化性","s":3,"c":"6. 细胞壁以外的构造","x":"鞭毛的旋转由质膜上的 Mot 蛋白构成的定子环驱动，能量来源是质子动力势（PMF）而非直接水解 ATP，这是与真核鞭毛（依赖 ATP 的滑动微管机制）的本质区别。大肠杆菌周毛菌逆时针旋转时鞭毛聚成束、推动菌体直线游动，顺时针旋转时束散开、菌体翻滚改变方向。趋化性通过双组分系统实现：膜上甲基化趋化蛋白（MCP）感受天冬氨酸等吸引物或吲哚等排斥物，经CheA/CheY 磷酸化级联调节鞭毛转向频率，使细菌在有利浓度梯度中\"偏随机行走\"式向高浓度区聚集。测量运动速度可达 30~60 μm/s，相当于每秒游过数十倍体长。"},{"id":"6.5","t":"菌毛与性菌毛","s":3,"c":"6. 细胞壁以外的构造","x":"菌毛是菌体表面比鞭毛更短、更细、更直的纤毛状结构，按功能分两类。普通菌毛（fimbriae）数量可达每菌 100~500 根，直径约 7 nm，是黏附宿主细胞的工具，如大肠杆菌的 I 型菌毛结合甘露糖、K88 菌毛黏附猪小肠，其黏附常是感染的第一步，故为重要毒力因子。性菌毛（pili）每个细胞仅 1~4根，直径 9~10 nm、中空，由 F 质粒等接合质粒编码，是接合时 DNA 传递的通道，同时也是某些噬菌体（如 f2、MS2）的吸附受体。要严格区分：鞭毛管运动，菌毛管黏附与接合，三者不能混用；性菌毛的有无决定细菌是 F+ 还是F−。"},{"id":"6.6","t":"芽孢的结构与形成","s":3,"c":"6. 细胞壁以外的构造","x":"芽孢是芽孢杆菌属、梭菌属等革兰阳性菌在营养缺乏（尤其缺氮、碳）条件下形成的抗逆性休眠体。由外向内依次为：孢外壁（部分菌种有）、芽孢衣（富含二硫键的疏水蛋白层，抗酶与抗化学物质）、皮层（特化的肽聚糖，疏松交联，含大量吡啶二羧酸钙 DPA-Ca）、核心（含 DNA、核糖体、酶与DPA）。DPA-Ca 占芽孢干重的 5%~15%，核心含水量仅 10%~20%，两者共同构成抗热基础。形成过程为：DNA 浓缩成轴丝—隔膜内陷—母细胞膜吞并前芽孢—合成皮层—形成芽孢衣—成熟—母细胞自溶释放；按位置分中央芽孢、偏端芽孢与端生芽孢，可作鉴定特征。"},{"id":"6.7","t":"芽孢的抗性机制与萌发","s":3,"c":"6. 细胞壁以外的构造","x":"芽孢对高温、辐射、干燥和化学消毒剂的抗性远高于营养细胞，机制是多因素协同：核心低含水量使蛋白质在高温下不易变性；DPA-Ca 与皮层的高渗透压状态稳定大分子；小分子酸溶性蛋白（SASP）结合 DNA，使其处于抗紫外与抗酶解的构型；芽孢衣的致密蛋白层阻挡化学物质进入；胞内保留 DNA修复酶，可修复萌发时的损伤。因此灭菌必须以杀死芽孢为标准，高压蒸汽灭菌 121℃、15 min 以上正是针对嗜热脂肪芽孢杆菌芽孢的。萌发分三步：活化（热激等处理使芽孢具备萌发能力）—出芽（吸水、失去折光性与抗性、DPA释放）—生长（合成新细胞物质恢复繁殖）。核心辨析：芽孢是休眠体而非繁殖体，一个营养细胞只形成一个芽孢、一个芽孢只萌发成一个营养细胞，因此不能称为繁殖方式。比较项营养细胞芽孢含水量70%~80% 10%~20%（核心）吡啶二羧酸钙无或极少占干重 5%~15%抗热性60~70℃ 即死亡121℃ 需 15 min 以上折光性无强，镜下呈折光小体代谢活性旺盛极低，近乎休眠功能生长繁殖渡过不良环境，非繁殖"},{"id":"7.1","t":"放线菌","s":3,"c":"7. 其他原核微生物","x":"放线菌是革兰阳性、G+C 含量高（常大于 55%）的丝状原核生物，因菌丝放射状生长而得名，分类上属细菌。菌体由纤细（约 1 μm）的基内菌丝（营养菌丝）与气生菌丝组成，气生菌丝顶端分化出孢子丝，以横隔分裂形成分生孢子繁殖，孢子丝形态（直、波曲、螺旋、轮生）是链霉菌分类的重要依据。菌落干燥、致密、坚实、表面呈绒状或粉状，与培养基结合紧密不易挑起，并因产生土腥素（geosmin）而有泥腥味。放线菌最重要的意义在于产抗生素：已知抗生素中约三分之二以上由放线菌产生，链霉菌属贡献最大（链霉素、四环素、红霉素、土霉素）。"},{"id":"7.2","t":"丝状细菌","s":2,"c":"7. 其他原核微生物","x":"丝状细菌是细胞呈丝状、常连成链或包在鞘内的原核微生物。贝日阿托氏菌（Beggiatoa）与硫珠菌在含硫化氢的水中把硫粒储于胞内，是硫循环的参与者；球衣菌（Sphaerotilus）包在鞘内，是活性污泥法中出现\"污泥膨胀\"的常见原因；铁细菌（如嘉利翁氏菌、纤毛菌）氧化 Fe²⁺ 为 Fe³⁺ 并获得能量，其氧化物沉积形成铁锰结核与管道锈垢。这类菌的共同点是细胞间以隔膜相连、可滑行运动、生态上依赖特定底物，因此常用作水体污染与富营养化的指示生物。"},{"id":"7.3","t":"蓝细菌","s":3,"c":"7. 其他原核微生物","x":"蓝细菌（旧称蓝藻、蓝绿藻）是含叶绿素 a 与藻胆素（藻蓝素、别藻蓝素、藻红素）、进行放氧光合作用的原核生物，无叶绿体与双层膜细胞器，光合片层由质膜内褶形成。其细胞壁含肽聚糖，与革兰阴性菌相似，可被溶菌酶破坏；许多种类有气泡以调节浮力，有羧酶体浓缩 CO₂。丝状蓝细菌在缺氮时形成异形胞（heterocyst），其壁增厚含糖脂层以隔绝氧气，成为固氮的场所，因此同一丝状体可同时进行光合与固氮，这在自养生物中十分独特。生态上，蓝细菌是水体初级生产者，过量繁殖形成水华并释放微囊藻毒素，也是内共生学说中叶绿体起源于蓝细菌的证据来源。"},{"id":"7.4","t":"古菌的细胞壁与膜脂","s":3,"c":"7. 其他原核微生物","x":"古菌细胞壁不含胞壁酸和 D-氨基酸，因而对青霉素、溶菌酶天然不敏感；其壁可分为三类：含假肽聚糖（N-乙酰塔罗糖胺糖醛酸与 N-乙酰葡糖胺以β-1,3 键交替，肽链为 L-氨基酸）、含硫酸化多糖或蛋白质 S 层、以及完全无壁（如热原体）。古菌膜脂的标志性特征是甘油与烃链以醚键相连（细菌与真核为酯键），烃链由异戊二烯单位构成（植烷基），且部分超嗜热古菌的膜脂两端均连甘油，形成贯穿膜的四醚单分子层。醚键与分支烃链使古菌膜耐高温、耐酸、耐有机溶剂，这是\"古菌能在极端环境生存\"的化学基础，也是三域系统在生物化学层面的独立证据。"},{"id":"7.5","t":"古菌对极端环境的适应","s":2,"c":"7. 其他原核微生物","x":"按生境可分五类群：极端嗜盐菌（如盐杆菌），需 1.5~5 mol/L NaCl，其紫膜中的细菌视紫红质以光驱动质子泵产 ATP，是\"无叶绿素的光合\"；产甲烷菌，严格厌氧，以 H₂/CO₂、乙酸或甲酸产甲烷，存在于沼泽、瘤胃与厌氧消化器中；超嗜热菌（如激烈火球菌），最适 90~100℃、上限可达 121℃ 左右，靠耐热蛋白与四醚膜脂维持；热原体等无壁古菌，嗜热嗜酸（约 60℃、pH 2）；以及还原硫酸盐古菌。这些\"嗜极\"特性使古菌成为研究生命起源与地外生命的模型，其耐热酶（如 Pfu DNA 聚合酶）则是 PCR 的关键试剂。"},{"id":"7.6","t":"支原体、衣原体、立克次氏体与螺旋体","s":3,"c":"7. 其他原核微生物","x":"四类特殊原核生物均与传统细菌在寄生性或结构上有显著差异：支原体无细胞壁、含甾醇质膜、能在无生命培养基上生长、菌落呈油煎蛋状，是能独立生活的最小生物；衣原体严格活细胞内寄生（曾长期被误认为病毒），有原体（EB，感染型，小而致密）与网状体（RB，繁殖型，大而疏松）交替的独特发育周期，形成胞内包涵体；立克次氏体也是严格细胞内寄生、以节肢动物（虱、蚤、蜱、螨）为媒介传播，常引起斑疹伤寒与斑疹热；螺旋体细长螺旋状、有内鞭毛（轴丝）位于外膜下、能屈曲运动，梅毒螺旋体与伯氏疏螺旋体分别是梅毒与莱姆病的病原。比较要点：支原体有培养可能、衣原体与立克次氏体必须活细胞培养、螺旋体介于两者之间（部分可人工培养）。类群大小有无细胞壁寄生性代表与疾病支原体0.2~0.3 μm，最小无可人工培养肺炎支原体，支原体肺炎衣原体0.3~1 μm有，但缺肽聚糖典型结构严格活细胞内沙眼衣原体，沙眼、泌尿生殖道感染立克次氏体0.3~0.6 μm有严格活细胞内普氏立克次氏体，流行性斑疹伤寒螺旋体长 5~20 μm有，柔性部分可培养梅毒螺旋体，梅毒放线菌菌丝 1 μm 1~10 μm有，革兰阳性腐生为主链霉菌，产链霉素有，含肽聚糖自养鱼腥藻，固氮、水华蓝细菌第三篇 真核微生物与病毒真核微生物与病毒构成竞赛的第二个高频区。真核微生物的重点是\"与细菌的根本差异\"以及繁殖方式（无性孢子的类型、有性孢子的类型、酵母菌生活史的三种模式）；病毒的重点则是\"结构—对称型—复制周期—非增殖性感染\"这条主线，以及噬菌体研究衍生出的溶原性、转导、溶原转换三个概念。特别注意：病毒不是\"最小的微生物\"，它是非细胞生物；亚病毒更不是病毒，二者的本质差别在核酸的有无与是否具有衣壳。"},{"id":"8.1","t":"真菌的共同特征与酵母菌的形态结构","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"真菌是一大群具有真核、无叶绿体、以吸收方式营养、细胞壁主要由几丁质与葡聚糖构成的生物，包括酵母菌、霉菌和蕈菌。酵母菌是单细胞真菌，一般呈球形、卵圆形或圆柱形，直径 2.5~10 μm（通常 3~5 μm），比细菌大5~10 倍；细胞壁含葡聚糖、甘露聚糖和少量几丁质，出芽后留下环状出芽痕，可据此判断菌龄。细胞内有明显的液泡（含水解酶与储藏物）、线粒体、内质网与高尔基体，但无叶绿体，也没有鞭毛。菌落大而厚、圆形隆起、表面光滑湿润、多呈乳白色，常有酒香味，与细菌菌落相比更湿润黏稠，与霉菌菌落相比则细小得多。"},{"id":"8.2","t":"酵母菌的繁殖","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"酵母菌的无性繁殖有三种方式：芽殖最常见，母细胞表面形成芽体（芽基），细胞核分裂后一个子核进入芽体，芽体长大后脱落，留下出芽痕；裂殖见于裂殖酵母，细胞横向分裂为两个；芽裂是芽殖与裂殖的中间型，母细胞中部形成隔膜同时出芽。有性繁殖通过两个性细胞（或单倍体细胞）接合形成二倍体，二倍体细胞经减数分裂形成含 4 个（酿酒酵母）或 8 个（八孢裂殖酵母）子囊孢子的子囊。孢子萌发后再成为单倍体营养细胞。判断一个\"单细胞真菌\"是否为酵母菌，关键看有无子囊孢子与出芽痕，而非仅看形态。"},{"id":"8.3","t":"酵母菌生活史的三种类型","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"酿酒酵母的生活史以二倍体营养细胞为主：二倍体细胞出芽繁殖，营养不良时减数分裂形成子囊孢子，孢子萌发为单倍体，单倍体接合又恢复二倍体，故营养体以二倍体占优势。八孢裂殖酵母以单倍体营养细胞为主，仅在接合后短暂形成二倍体，随即减数分裂。路德类酵母则单倍体与二倍体都较长，且二倍体在子囊内直接出芽产生二倍体孢子。三种类型的比较是竞赛常见的图表题，答题时应抓住\"营养体以几倍体为主\"与\"减数分裂发生在哪个阶段\"两点，并注意酵母菌的接合型（a 与 α）由 MAT 基因座决定，属真核微生物的性别分化机制。"},{"id":"8.4","t":"霉菌的菌丝与菌落","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"霉菌是丝状真菌的统称，菌丝直径 2~10 μm，比放线菌粗 10 倍左右。菌丝分两类：有隔膜菌丝（如青霉、曲霉）由横隔分成多细胞，隔膜中央留孔使细胞质与核物质流通；无隔膜菌丝（如毛霉、根霉）为多核的长管状体，称共胞体。菌丝只在顶端生长，分枝形成菌丝体，分为深入基质的基内菌丝（吸收营养）与伸出表面的气生菌丝（常分化出繁殖结构）。霉菌菌落大而疏松、呈棉絮状或绒毛状、扩展快、表面有孢子颜色、正反面颜色常不同，与细菌和酵母菌的菌落形态构成三类典型对照。"},{"id":"8.5","t":"霉菌的无性繁殖","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"无性繁殖产生无性孢子，主要有四种：孢囊孢子由孢子囊内的原生质分裂形成，生于菌丝顶端膨大的孢子囊中（毛霉、根霉）；分生孢子由气生菌丝特化的分生孢子梗顶端以出芽或断裂方式形成，成熟后脱落（青霉、曲霉）；节孢子由菌丝断裂成短柱状细胞（地霉）；厚垣孢子由菌丝细胞壁增厚、原生质浓缩形成，用于渡过不良环境（总状共头霉）。此外还有芽孢子与游动孢子（水生真菌）。无性孢子数量大、产生快，是霉菌在自然界迅速扩散的主要方式，也是实验室鉴定的主要依据。"},{"id":"8.6","t":"霉菌的有性繁殖","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"有性繁殖经质配、核配与减数分裂三个阶段，最终形成四类有性孢子：卵孢子由雄器与藏卵器结合后在卵球内形成（水霉等卵菌，注意卵菌现归卵菌门而非真菌）；接合孢子由两个形态相似的同源或异源菌丝细胞接合形成厚壁休眠孢子（毛霉、根霉），分同宗配合与异宗配合；子囊孢子形成于囊状子囊内，通常 8 个，是子囊菌门（青霉、曲霉、酵母、脉孢菌）的标志；担孢子外生于担子小梗上，通常 4 个，是担子菌门（蘑菇、木耳）的标志。分类上\"有性孢子类型\"比\"菌丝形态\"更能反映亲缘关系，这是真菌分类的原则。"},{"id":"8.7","t":"常见霉菌代表属","s":3,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"毛霉与根霉属无隔膜菌丝，以孢囊孢子无性繁殖、接合孢子有性繁殖，根霉还有假根与匍匐枝的分化，二者是酒曲、腐乳与糖化酶生产菌，也是食品霉变的常见菌。曲霉属的分生孢子梗顶端膨大成顶囊，其上着生小梗与成串分生孢子，用于酱油酿造与有机酸、酶制剂生产，但黄曲霉产生的黄曲霉毒素是强致癌物。青霉属的分生孢子梗呈扫帚状分枝，产黄青霉是青霉素的产生菌，也是柑橘腐败的常见菌。脉孢菌（红色面包霉）因孢子呈红色、子囊孢子排列有序而成为遗传学经典材料；木霉是纤维素酶生产与生物防治菌。要注意\"霉菌\"不是分类单元，只是形态描述。"},{"id":"8.8","t":"蕈菌","s":2,"c":"8. 真菌：酵母菌、霉菌与蕈菌","x":"蕈菌是能形成大型子实体的真菌，多属担子菌门，少数属子囊菌门。其营养体为双核菌丝体（每个细胞含两个遗传上不同但相容的核），菌丝分裂时通过锁状联合保证双核同步分配；子实体（担子果）由菌丝扭结、分化而成，包括菌盖、菌褶、菌柄、菌环等部分，菌褶两侧的子实层上产生担子与 4 个外生担孢子。人工栽培的食用菌主要有双孢蘑菇、香菇、金针菇、平菇、木耳、银耳，栽培本质是控制温度、湿度、通风与光照以诱导子实体分化。毒蘑菇的鉴别不能依据颜色或虫咬，须依分类特征与毒素（鹅膏毒肽、毒蕈碱）判断。"},{"id":"9.1","t":"原生动物的主要类群","s":3,"c":"9. 原生生物、藻类与地衣","x":"原生动物是单细胞或单细胞群体的真核生物，无细胞壁，以鞭毛、纤毛或伪足运动，按运动器分为四类。鞭毛虫以鞭毛运动，如眼虫（含叶绿体，兼具自养与异养）、锥虫（非洲睡眠病）、利什曼原虫（黑热病）、贾第虫（腹泻）、阴道毛滴虫。肉足虫以伪足运动和摄食，如大变形虫，以及具钙质或硅质壳的有孔虫与放射虫（古生物学与地质年代判断的重要化石）。纤毛虫以纤毛运动，如草履虫，具有大核（营养核）与小核（生殖核）的双核结构，以横分裂繁殖并可进行接合生殖交换小核。孢子虫不具运动器，全为寄生，如疟原虫，顶端有顶复合器（顶复器）用以侵入宿主细胞。"},{"id":"9.2","t":"原生动物的营养、生殖与包囊","s":2,"c":"9. 原生生物、藻类与地衣","x":"原生动物营养方式多样：植物性营养（眼虫有叶绿体，光能自养）、动物性营养（吞噬细菌、藻类或有机物颗粒，形成食物泡消化）、腐生性营养（吸收溶解有机物）。繁殖以无性为主（二分裂、出芽、多分裂），有性生殖有接合生殖（草履虫）与配子生殖（疟原虫在蚊体内）。许多原生动物在不良环境下形成包囊：细胞变圆、分泌厚壁、代谢降低，包囊可抵抗干燥与胃酸，是传播与感染的阶段，如痢疾阿米巴包囊经粪—口传播。草履虫的伸缩泡通过收集管与中央泡排出多余水分，起渗透调节作用，是低渗环境下的适应性结构。"},{"id":"9.3","t":"藻类","s":2,"c":"9. 原生生物、藻类与地衣","x":"藻类是一大群含光合色素、能进行放氧光合作用的真核生物（蓝细菌除外），在微生物学中主要指单细胞或丝状微藻。按色素与贮存物质分为绿藻门（衣藻、栅藻、小球藻，含叶绿素 a、b 与淀粉）、硅藻门（硅质壳由两瓣组成、舟形，贮存油滴，是重要初级生产者与硅藻土来源）、褐藻门（海带、裙带菜，含墨角藻黄素）、红藻门（紫菜，含藻红素）、甲藻门（具两条鞭毛，赤潮的主要引发者，可产膝沟藻毒素等藻毒素）与金藻门。藻类的意义包括初级生产、水产饵料、生产琼脂与藻酸盐、固定 CO₂ 以及作为生物柴油原料，过量繁殖则形成赤潮与水华。"},{"id":"9.4","t":"黏菌","s":1,"c":"9. 原生生物、藻类与地衣","x":"黏菌是介于真菌与动物之间的真核微生物，营养阶段为多核的原质团（plasmodium），无细胞壁，能作变形运动并吞噬细菌与有机物，类似变形虫；繁殖阶段形成具柄的子实体，产生有壁的孢子。细胞黏菌（盘基网柄菌）的生活史更具特征：营养细胞以细菌为食独立生活，饥饿时聚集形成假原质团并分化为柄与孢子。黏菌因兼具\"动物式摄食\"与\"真菌式产孢\"而长期被争议归类，现多归入变形虫界。其研究价值在于细胞分化、趋化聚集与多细胞性起源的模型。"},{"id":"9.5","t":"地衣","s":3,"c":"9. 原生生物、藻类与地衣","x":"地衣是真菌（主要是子囊菌，少数担子菌）与藻类（绿藻或蓝细菌）形成的稳定共生体，形态上是一个独立的复合体而非简单混合。共生关系具有互惠性质：真菌以菌丝网络提供庇护、水分与矿质元素，藻类或蓝细菌通过光合作用提供有机碳，蓝细菌还可固氮。按形态分壳状、叶状和枝状三类，按结构分散层型与同层型。地衣生长极慢（每年仅 1~2 mm），耐干旱与严寒，常为裸岩上的先锋生物，并进行生物风化；同时对二氧化硫等大气污染物极为敏感，因而是大气污染的指示生物。地衣是\"共生\"概念最经典的例证，也是\"互利共生可形成新形态结构\"的重要说明。"},{"id":"9.6","t":"原生动物与人类疾病","s":2,"c":"9. 原生生物、藻类与地衣","x":"疟原虫的生活史最能体现原生动物的寄生适应：雌按蚊吸血时把孢子体注入人体，孢子体先侵入肝细胞进行红细胞外期裂体增殖，再进入红细胞进行红细胞内期裂体增殖（环状体、滋养体、裂殖体），部分虫体分化为雌雄配子体；按蚊吸血后配子体在蚊胃内形成合子、动合子、卵囊，最终产生孢子体。红细胞周期性破裂与裂殖体成熟同步，故临床呈周期性发热（间日疟 48 h、三日疟 72 h）。其他重要致病原生动物包括溶组织内阿米巴（包囊经粪—口传播，引起阿米巴痢疾与肝脓肿）、蓝氏贾第虫（水源性腹泻）、阴道毛滴虫（性传播）与弓形虫（猫科动物为终宿主，孕妇感染可致胎儿畸形）。防治依靠灭蚊、改善饮水卫生与药物治疗。"},{"id":"10.1","t":"病毒的定义与特点","s":3,"c":"10. 病毒的基本性质","x":"病毒是含一种核酸（DNA 或 RNA）、无细胞结构、专性活细胞内寄生、以复制方式增殖的非细胞生物。其特点可概括五点：个体极小（10~300 nm，需电子显微镜或滤过性试验证明）、无细胞结构（无核糖体、无产能酶系）、只含一种核酸（不以 DNA 与 RNA 同时作为遗传物质）、专性寄生（必须借助宿主细胞的核糖体、酶与能量）、以复制而非二分裂方式增殖。因此病毒介于生命与非生命之间：具有遗传、变异、进化与繁殖能力，却不具备独立代谢与应激性，通常不称其为\"微生物\"而称\"病毒体\"或\"毒粒\"。"},{"id":"10.2","t":"毒粒的形态与大小","s":3,"c":"10. 病毒的基本性质","x":"毒粒（virion）是病毒的细胞外感染性颗粒，由核酸与衣壳构成（有的还有包膜）。大小以纳米计：痘病毒最大（200~300 nm，光学显微镜勉强可见，是唯一可在光镜下看到的病毒），口蹄疫病毒与细小病毒最小（10~22 nm）。形态多样：球状（腺病毒、疱疹病毒）、杆状（烟草花叶病毒）、丝状（埃博拉病毒）、弹状（狂犬病病毒，一端圆一端平）、砖状（痘病毒）、蝌蚪状（T 偶数噬菌体，头呈二十面体、尾呈螺旋）。病毒形态是分类与鉴定的重要依据，也是\"滤过性\"概念（能通过细菌滤器）的来源。"},{"id":"10.3","t":"衣壳的对称型","s":3,"c":"10. 病毒的基本性质","x":"衣壳由衣壳粒（capsomere）按一定对称方式排列而成，有三种对称型：螺旋对称，衣壳粒沿螺旋轨迹排列、核酸嵌于螺旋沟中，如烟草花叶病毒（TMV）由 2130 个相同蛋白亚基包裹单链 RNA；二十面体对称（立体对称），衣壳粒排列成 20 个三角形面、12 个顶角，腺病毒即典型，其顶角上有纤突；复合对称，既有螺旋又有立体对称，如 T4 噬菌体的二十面体头部加螺旋的尾部。对称型由衣壳蛋白亚基的结构与核酸长度共同决定，二十面体对称能用最少的蛋白亚基包裹最大体积，是\"经济性\"的体现。"},{"id":"10.4","t":"包膜","s":3,"c":"10. 病毒的基本性质","x":"包膜是某些病毒在成熟释放时从宿主细胞膜（或核膜、内质网膜）获得的脂质双层膜，其上镶嵌着病毒基因编码的糖蛋白刺突，具有吸附受体、融合与抗原性功能（如流感病毒的血凝素 HA 与神经氨酸酶 NA、HIV 的gp120/gp41）。有包膜病毒对脂溶剂（乙醚、氯仿）、去污剂和胆盐敏感，易被破坏而失活，故这类病毒多经血液、体液或呼吸道传播且抵抗力较弱；无包膜病毒（裸病毒）不含脂质，对上述处理抵抗力较强，可耐消化道环境（如脊髓灰质炎病毒、甲肝病毒），因而可经粪—口传播。这一条把\"结构\"与\"传播途径、消毒方法\"直接连通，是竞赛综合题的常见落点。"},{"id":"10.5","t":"病毒的化学组成与核酸类型","s":3,"c":"10. 病毒的基本性质","x":"病毒主要由核酸与蛋白质组成，有的还有脂质与糖类：核酸构成基因组，蛋白质构成衣壳与包膜刺突，并包括病毒编码的酶（如逆转录酶、RNA 聚合酶）。核酸类型多样：双链 DNA（T4 噬菌体、疱疹病毒、痘病毒）、单链DNA（φX174、细小病毒）、双链 RNA（呼肠孤病毒）、正单链 RNA（可直接作 mRNA 翻译，如 TMV、脊髓灰质炎病毒、SARS-CoV-2）、负单链 RNA（须先转录，如流感病毒、狂犬病病毒）、以及逆转录型（HIV 的 RNA 经逆转录为 DNA；HBV 的部分双链 DNA 经 RNA 中间体逆转录）。巴尔的摩分类据此把病毒分为七类，竞赛中常以\"该病毒核酸能否直接指导翻译\"设问。"},{"id":"10.6","t":"病毒的培养与定量","s":2,"c":"10. 病毒的基本性质","x":"病毒必须用活细胞培养：实验室常用鸡胚尿囊腔接种、细胞培养（原代细胞、二倍体细胞、传代细胞系）与动物接种；噬菌体则用敏感菌的液体培养或双层琼脂平板。定量方法包括：噬菌斑计数（每个噬菌斑代表一个感染性颗粒，以 pfu 表示）、空斑试验（动物病毒，以 pfu 或 TCID50 表示）、半数致死量或半数感染量（LD50/ID50）、血凝试验（含血凝素的病毒凝集鸡红细胞，可快速半定量）以及电镜直接计数。滴度常用 10 的指数表示，\"病毒定量难\"的根源在于一个感染性颗粒不等于一个物理颗粒（后者含缺陷颗粒）。"},{"id":"10.7","t":"病毒的分类与命名","s":2,"c":"10. 病毒的基本性质","x":"国际病毒分类委员会（ICTV）采用目（-virales）、科（-viridae）、亚科（-virinae）、属（-virus）、种五级系统，种是分类的基本单位，种名采用双名法（属名 + 种加词）。命名规则包括：科名以 -viridae 结尾、属名以-virus 结尾、目名以 -virales 结尾，且病毒名与病名不同（如 HIV 是病毒名，艾滋病是疾病名）。分类依据包括核酸类型与链极性、衣壳对称型、有无包膜、基因组大小与结构、复制策略以及宿主范围。注意：传统上按宿主把病毒分为动物病毒、植物病毒、细菌病毒（噬菌体），这只是习惯分法，与ICTV 的系统分类不同层。"},{"id":"11.1","t":"烈性噬菌体与一步生长曲线","s":3,"c":"11. 噬菌体与病毒的感染","x":"烈性噬菌体感染宿主后立即进入复制循环，最终裂解宿主细胞释放子代，其增殖过程只能通过\"一步生长曲线\"研究：将高感染复数（MOI）的噬菌体与敏感菌混合，短时吸附后立即稀释以终止再感染，定时取样用双层平板测噬菌斑数，以时间为横轴、噬菌斑数为纵轴作图。曲线分三期：潜伏期（含隐晦期与胞内积累期，约 20~30 min，此时细胞内尚无成熟颗粒）、裂解期（胞外噬菌体数呈爆发式上升）、平稳期（宿主已耗尽，效价稳定）。由曲线可读出两个参数：潜伏期长度与裂解量（平均每个感染细胞释放的子代数，T 系噬菌体可达 100~200）。"},{"id":"11.2","t":"温和噬菌体与溶原性","s":3,"c":"11. 噬菌体与病毒的感染","x":"温和噬菌体感染后有两种命运：一是进入裂解循环，二是把基因组整合到宿主染色体上成为原噬菌体（prophage）并随染色体同步复制，后者称溶原性。含原噬菌体的细菌称溶原菌，它能正常生长繁殖并把噬菌体基因传给子代（溶原性的遗传），同时因原噬菌体编码的阻遏蛋白（如 λ 的 CI）抑制其他同源噬菌体的裂解基因表达而具有\"免疫性\"，即对同种噬菌体的再感染有抗性。在紫外线、丝裂霉素 C、温度剧变等诱变条件下，原噬菌体可被切离进入裂解循环，称诱导。溶原状态可稳定维持多代，也可自发（频率约 10⁻⁵）或诱发而切离。"},{"id":"11.3","t":"溶原转换","s":3,"c":"11. 噬菌体与病毒的感染","x":"溶原转换是指原噬菌体所携带的基因使宿主菌获得新的表型性状的现象，因为这些基因随原噬菌体稳定遗传给子代。经典例证包括：白喉棒状杆菌只有被携带 tox 基因的 β 噬菌体溶原化后才能产生白喉毒素，无此噬菌体的菌株无毒力；肉毒梭菌的肉毒毒素、化脓性链球菌的红疹毒素（致猩红热）、金黄色葡萄球菌的肠毒素 A、以及霍乱弧菌的 CTXφ 噬菌体编码的霍乱毒素都属此类。医学意义在于：毒力由\"菌株\"与\"噬菌体\"共同决定，因此无毒株可因溶原转换变成有毒株。这一概念与转导、接合并列为细菌水平基因转移的三种方式之一。"},{"id":"11.4","t":"转导","s":3,"c":"11. 噬菌体与病毒的感染","x":"转导是以噬菌体为媒介把供体菌的 DNA 转移到受体菌的过程，分两类。普遍转导由 P1、P22 等噬菌体介导，在包装时误把供体菌 DNA 的随机片段装入衣壳，形成转导颗粒，可转移任何供体基因，但只转移一小段、只形成部分二倍体，重组频率较低。局限转导由 λ、φ80 等温和噬菌体介导：原噬菌体切离时发生错误，把自身的部分基因替换为相邻的宿主基因，形成的缺陷噬菌体只能转移位于整合位点两侧的特定基因（如大肠杆菌半乳糖基因），分低频转导（LFT，需与辅助噬菌体共感染）与高频转导（HFT，缺陷噬菌体占多数）。转导在自然界是耐药基因与毒力基因扩散的重要途径。"},{"id":"11.5","t":"动物病毒的复制周期","s":3,"c":"11. 噬菌体与病毒的感染","x":"动物病毒的复制一般分五个阶段：吸附（病毒刺突或衣壳与宿主细胞受体特异性结合，受体决定宿主范围与组织嗜性）、穿入（有包膜病毒经膜融合或胞吞，无包膜病毒经受体介导的胞吞或直接穿入）、脱壳（释放核酸，有包膜病毒常与脱壳同步）、生物合成（早期基因编码调控蛋白与复制酶，晚期基因编码结构蛋白，DNA 病毒多在核内复制而痘病毒在胞质，RNA 病毒在胞质）、装配与释放（多数 DNA 病毒在核内装配，有包膜病毒以芽出方式释放且不立即裂解细胞，无包膜病毒裂解细胞释放）。注意这一过程与噬菌体的\"吸附—注入—复制—装配—裂解\"在名称上不完全对应，答题时宜用\"吸附、穿入、脱壳、生物合成、装配与释放\"。"},{"id":"11.6","t":"病毒的非增殖性感染","s":3,"c":"11. 噬菌体与病毒的感染","x":"非增殖性感染是指病毒侵入细胞后不能产生有感染性子代的感染，包括三类：顿挫感染（abortive infection），病毒进入非容纳细胞，因缺乏必要的酶或因子而不能完成复制，如人腺病毒在大鼠细胞中；缺损病毒（defective virus），病毒基因组缺失部分必需基因，必须依赖辅助病毒才能复制，如腺相关病毒依赖腺病毒、丁型肝炎病毒依赖乙型肝炎病毒；干扰缺损颗粒（DI 颗粒），由高感染复数连续传代产生的缺失型颗粒，能干扰同源完整病毒的复制，是病毒自我限制的一种机制。这三类概念常被混为一谈，辨析要点是\"缺失什么、由谁补偿\"。"},{"id":"11.7","t":"植物病毒与传播方式","s":2,"c":"11. 噬菌体与病毒的感染","x":"植物病毒无细胞表面受体，不能主动侵入，须通过伤口（机械摩擦、昆虫口器）进入，或由介体传播：蚜虫、叶蝉、飞虱、粉虱、蓟马等昆虫（多数呈非持久性或持久性传毒）、线虫、真菌（如禾谷多黏菌传播大麦黄花叶病毒）以及菟丝子等寄生植物。病毒在植物体内通过胞间连丝与维管束系统扩散，其运动蛋白可扩大胞间连丝孔径。症状表现为花叶、黄化、坏死、畸形、矮缩与丛枝。烟草花叶病毒（TMV）是第一个被结晶并证明由核酸与蛋白组成的病毒（Stanley，1935），也是第一个被测序的病毒；植物病毒防治主要靠脱毒苗、抗病品种与介体控制。"},{"id":"12.1","t":"类病毒","s":3,"c":"12. 亚病毒与病毒与宿主的关系","x":"类病毒（viroid）是仅由共价闭合环状单链 RNA 构成、长 246~399 个核苷酸、无蛋白质衣壳、不编码任何蛋白的感染性因子。其 RNA 通过形成棒状（杆状）二级结构并与宿主细胞核内的 RNA 聚合酶相互作用进行滚环复制，致病机制可能涉及 RNA 沉默途径的干扰。代表是马铃薯纺锤块茎类病毒（PSTVd），引起马铃薯减产；此外有柑橘裂皮类病毒、牛油果日灼病类病毒。类病毒只感染植物，是已知最小的病原体之一，其发现（Diener，1971）颠覆了\"病原体必有核酸与蛋白\"的观念。"},{"id":"12.2","t":"拟病毒与卫星 RNA","s":2,"c":"12. 亚病毒与病毒与宿主的关系","x":"拟病毒（virusoid）是包裹在辅助病毒衣壳内、与辅助病毒基因组无同源性的环状单链 RNA，须依赖辅助病毒复制，如绒毛烟斑驳病毒中的拟病毒（其本身类似类病毒，但被包装在杆状衣壳内）。卫星 RNA 是依赖辅助病毒复制、被包装在同一衣壳中的小 RNA，可显著改变症状严重程度（如黄瓜花叶病毒的卫星 RNA 能减轻症状）。卫星病毒则指具有自己的衣壳、但仍需辅助病毒提供部分功能的病毒。三者的共同点是\"缺陷性、依赖辅助病毒\"，区别在于是否有自己的衣壳以及核酸构型，属高频概念辨析点。"},{"id":"12.3","t":"朊病毒","s":3,"c":"12. 亚病毒与病毒与宿主的关系","x":"朊病毒（prion）是仅由蛋白质构成、不含核酸的感染性因子，其本质是宿主正常的朊蛋白 PrPC 发生构象转变形成富含 β 折叠、抗蛋白酶的异常型PrPSc。PrPSc 能作为模板诱导更多 PrPC 转变构象，从而在体内积累并形成淀粉样斑块、导致神经元空泡化，因此其\"增殖\"不依赖核酸复制，能抵抗核酸酶、甲醛与常规消毒，但对高温高压（134℃）、强碱与蛋白酶 K 部分敏感。所致疾病包括羊瘙痒病、牛海绵状脑病（疯牛病）、人类克雅氏病（CJD）、库鲁病与致死性家族性失眠症，统称传染性海绵状脑病。重要辨析：朊病毒不是病毒，不含核酸，其\"信息\"存于蛋白质构象之中。"},{"id":"12.4","t":"病毒与肿瘤","s":2,"c":"12. 亚病毒与病毒与宿主的关系","x":"估计约 15%~20% 的人类恶性肿瘤与病毒感染有关。明确相关的有：人乳头瘤病毒（HPV）16、18 型与宫颈癌（E6、E7 蛋白分别灭活 p53 与 Rb）；乙型与丙型肝炎病毒与肝细胞癌（慢性炎症与肝硬化作为促癌背景）；EB 病毒与鼻咽癌、伯基特淋巴瘤；人类 T 细胞白血病病毒 1 型（HTLV-1）与成人 T细胞白血病；卡波西肉瘤相关疱疹病毒（KSHV）与卡波西肉瘤。致癌机制包括病毒携带癌基因（v-onc）、插入激活宿主原癌基因、编码蛋白干扰抑癌蛋白以及慢性炎症微环境。HPV 疫苗是第一个以预防肿瘤为目标的病毒疫苗。"},{"id":"12.5","t":"病毒感染的类型与宿主反应","s":2,"c":"12. 亚病毒与病毒与宿主的关系","x":"按感染过程分：隐性感染（亚临床，最常见）、显性感染（出现症状）、潜伏感染（病毒长期潜伏，如 HSV 潜伏于神经节，应激时复发）、慢性感染（病毒持续存在并不断排出，如 HBV、HCV）与慢发病毒感染（极长潜伏期后发病，如 HIV 与朊病毒病）。宿主对病毒的反应包括干扰素系统（I 型干扰素诱导抗病毒蛋白降解病毒 mRNA）、NK 细胞与细胞毒性 T 细胞杀伤感染细胞、中和抗体阻断吸附，以及病毒逃避策略（抗原变异如流感 HA 漂移与转换、抑制 MHC 表达、编码干扰素拮抗蛋白）。这一部分与第八篇免疫学内容交叉，复习时应合并理解。"},{"id":"12.6","t":"病毒感染的诊断、预防与治疗","s":2,"c":"12. 亚病毒与病毒与宿主的关系","x":"诊断分四个层次：病毒分离培养（接种敏感细胞后观察致病变效应 CPE）是金标准但耗时；电镜直接观察适用于痘病毒等大颗粒；抗原检测（免疫荧光、ELISA）快速；核酸检测（PCR、qPCR、mNGS）灵敏度最高，是当前主力。血清学中 IgM 阳性提示近期感染、IgG 阳性提示既往感染或疫苗接种，双份血清抗体效价四倍升高具有诊断意义。预防以疫苗为核心，包括灭活疫苗、减毒活疫苗、亚单位疫苗、病毒载体疫苗与 mRNA 疫苗，被动免疫用免疫球蛋白。治疗药物按靶点分为：核苷类似物（阿昔洛韦抑制疱疹病毒 DNA聚合酶）、蛋白酶抑制剂（抗 HIV）、神经氨酸酶抑制剂（奥司他韦抗流感）、干扰素与单克隆抗体，多数抗病毒药只抑制复制而不能清除潜伏的病毒。病毒核酸类型代表病毒复制特点遗传物质意义双链 DNA T4 噬菌体、腺病毒、疱疹病毒半保留复制，多在核内稳定，突变率低单链 DNAφX174、细小病毒先合成互补链再复制基因组小，依赖宿主酶双链 RNA呼肠孤病毒转录后翻译，衣壳内完成分段基因组常见正单链 RNA TMV、脊髓灰质炎病毒、SARS-CoV-2 RNA 可直接作 mRNA感染性核酸负单链 RNA流感病毒、狂犬病病毒须先转录出正链 mRNA必须携带 RNA 聚合酶逆转录型HIV、乙型肝炎病毒RNA 逆转录为 DNA 后整合易与宿主基因组重组第四篇 微生物营养与代谢本篇的难点不在记忆而在\"能量与物质的流向\"。掌握三条线索即可贯通：一是碳源、氮源、能源、无机盐、生长因子五要素分别构成什么；二是葡萄糖经 EMP、TCA、电子传递链的产能与发酵产物分支；三是自养微生物如何把无机物氧化产生的能量与还原力用于固定 CO₂。竞赛常以\"某菌属于哪种营养类型\"\"某发酵产物比例\"\"某步骤净产 ATP\"设问，因此数目必须记清。"},{"id":"13.1","t":"碳源与氮源","s":3,"c":"13. 微生物的营养","x":"碳源是构成细胞碳骨架并常兼作能源的物质，分有机碳（糖类、醇类、有机酸、脂类、烃类）与无机碳（CO₂、碳酸盐），异养微生物最常用葡萄糖，自养微生物以 CO₂ 为唯一碳源。氮源是合成氨基酸、核酸、含氮辅酶与细胞壁成分的原料，分有机氮（蛋白胨、牛肉膏、酵母膏、氨基酸、尿素）与无机氮（铵盐、硝酸盐、亚硝酸盐、N₂）；铵盐与蛋白胨为速效氮源，硝酸盐为迟效氮源，因为需先还原为氨才能同化。氮源一般不作能源，但硝化细菌、氢细菌等以氨或亚硝酸的氧化取得能量，此时氮源兼作能源，这是\"营养要素功能可重叠\"的典型例子。"},{"id":"13.2","t":"能源、无机盐与生长因子","s":3,"c":"13. 微生物的营养","x":"能源是提供初始能量的物质：光能营养者利用光，化能营养者靠有机物或无机物的氧化。无机盐分大量元素（P、S、K、Mg、Ca、Na、Fe）与微量元素（Cu、Zn、Mn、Mo、Co、Ni、B），功能包括构成细胞物质（P 构成核酸与 ATP，S 构成含硫氨基酸与硫胺素）、作为酶的辅因子（Mg²⁺ 稳定核糖体与核酸、激活激酶，Fe 构成细胞色素与铁硫蛋白，Mo 为固氮酶与硝酸还原酶所需）、维持渗透压与 pH 以及作为某些微生物的电子受体。生长因子是微生物自身不能合成而必须外源提供的微量有机物，包括维生素（尤其 B 族）、氨基酸、嘌呤嘧啶与脂肪酸；凡需要某种生长因子的菌株即营养缺陷型，育种与遗传分析常利用它做选择标记。"},{"id":"13.3","t":"四种营养类型","s":3,"c":"13. 微生物的营养","x":"按碳源（自养以 CO₂ 为唯一碳源，异养以有机物为碳源）与能源（光能、化能）两个标准交叉，得到四种类型。光能自养型以光为能、CO₂ 为碳，如蓝细菌、紫硫细菌、绿硫细菌；光能异养型以光为能但需有机物作碳源或供氢体，如红螺菌；化能自养型氧化无机物（NH₄⁺、NO₂⁻、H₂S、S、Fe²⁺、H₂）获能并以 CO₂ 为碳，如硝化细菌、硫细菌、铁细菌、氢细菌；化能异养型氧化有机物获能并以有机物为碳，包括绝大多数细菌、全部真菌与原生动物。要提醒的是：化能自养菌产能效率低、生长慢、生物量小，但它们是自然界无机氮、硫、铁循环不可替代的推动者。"},{"id":"13.4","t":"培养基的类型与应用","s":3,"c":"13. 微生物的营养","x":"按成分来源分天然培养基（牛肉膏蛋白胨、麦芽汁、马铃薯培养基，成分不确定但营养丰富、生长快）与合成培养基（成分已知，如查氏培养基，用于精确研究）；按物理状态分固体（加 1.5%~2% 琼脂）、半固体（0.3%~0.5%，用于观察运动性与趋化性）与液体培养基；按用途分基础培养基、选择培养基、鉴别培养基与加富培养基。选择培养基通过加入抑制剂或特殊营养只允许目标菌生长（如含青霉素的培养基筛革兰阴性菌、SS 琼脂筛沙门氏菌、甘露醇高盐琼脂筛金黄色葡萄球菌）；鉴别培养基通过指示剂显示菌落特征以区分菌种（如伊红美蓝琼脂上大肠杆菌呈带金属光泽的紫黑色菌落、血琼脂观察溶血类型）；加富培养基通过增加特定营养使目标菌在混合样品中的比例升高（如碱性蛋白胨水增菌霍乱弧菌）。核心辨析：选择培养基靠\"抑制或限制\"起作用，鉴别培养基靠\"显示差异\"起作用，二者常被合并使用。"},{"id":"13.5","t":"单纯扩散与促进扩散","s":3,"c":"13. 微生物的营养","x":"单纯扩散（自由扩散）顺浓度梯度进行，不需载体、不耗能，只适用于水、O₂、CO₂、甘油、乙醇等小分子与脂溶性物质；扩散速率取决于膜两侧浓度差，当内外浓度相等即停止，因此不能使胞内积累高浓度物质。促进扩散（易化扩散）同样顺浓度梯度、不耗能，但必须借助膜上的特异性载体蛋白，具有饱和效应与竞争性抑制，如甘油、某些糖与 SO₄²⁻ 的运输；载体经构象改变把物质从外侧运到内侧，微生物中相对少见。二者的共同局限是不能逆浓度梯度积累，因而不满足微生物在寡营养环境中\"浓缩\"营养物质的需要。"},{"id":"13.6","t":"主动运输与基团转位","s":3,"c":"13. 微生物的营养","x":"主动运输逆浓度梯度进行，需特异性载体并消耗能量（ATP 或质子动力势），可使胞内浓度远高于胞外，是大多数营养物质进入细胞的主要方式，如K⁺、氨基酸、PO₄³⁻ 的吸收；载体蛋白经构象改变转运底物，能量偶联方式包括初级主动运输（直接水解 ATP，如 ABC 转运系统）与次级主动运输（借质子或钠梯度）。基团转位是原核生物特有的主动运输方式，物质在运输过程中被化学修饰，如磷酸烯醇式丙酮酸（PEP）依赖的磷酸转移酶系统（PTS）把葡萄糖磷酸化为 6-磷酸葡萄糖再进入细胞，每转运一分子葡萄糖消耗一分子PEP。其意义在于：进入细胞的产物已不再是原物，既维持了浓度梯度又使物质\"被激活\"进入代谢。膜泡运输则见于真核微生物的内吞与外排。比较项单纯扩散促进扩散主动运输基团转位浓度方向顺梯度顺梯度可逆梯度可逆梯度是否需要载体否是是是是否耗能否否是是运输后分子是否改变否否否是（被磷酸化等）典型实例H₂O、O₂、甘油甘油、部分糖K⁺、氨基酸、PO₄³⁻PTS 系统转运葡萄糖能否富集营养否否能能"},{"id":"14.1","t":"生物氧化的形式与能量产生","s":3,"c":"14. 微生物的代谢","x":"生物氧化是细胞内有机物或无机物被氧化并释放能量的过程，形式包括脱氢（最常见，需脱氢酶与辅酶 NAD⁺、NADP⁺、FAD）、失电子（如Fe²⁺→Fe³⁺）与加氧。释放的能量通过三种磷酸化方式转为 ATP：底物水平磷酸化（代谢中间产物把磷酸基直接转给 ADP，如糖酵解中 1,3-二磷酸甘油酸与磷酸烯醇式丙酮酸两处）、氧化磷酸化（电子沿呼吸链传递建立质子动力势，经 ATP 合成酶合成 ATP，是化能异养菌的主要产能方式）与光合磷酸化（光能驱动电子传递产生 ATP，见于光合微生物）。理解这一组概念是判断\"某微生物靠什么活\"的基础。"},{"id":"14.2","t":"发酵与乳酸发酵","s":3,"c":"14. 微生物的代谢","x":"发酵是厌氧条件下有机物既作电子供体又作电子受体的氧化方式，不需要外源电子受体，产能少（每分子葡萄糖净产 1~2 个 ATP）。同型乳酸发酵经EMP 途径把葡萄糖变为 2 分子乳酸，净产 2 ATP，代表菌为乳酸乳球菌、嗜酸乳杆菌；异型乳酸发酵经磷酸酮解酶途径产生乳酸、乙醇与 CO₂，净产 1 ATP，代表菌为肠膜明串珠菌；双歧杆菌则走特有的双歧途径，产物为乳酸与乙酸。乳酸发酵在食品工业上用于酸奶、泡菜、青贮饲料，在工业上用于生产聚乳酸前体。注意：同型与异型的关键差别在于碳流是否经过磷酸酮解酶裂解以及是否产 CO₂。"},{"id":"14.3","t":"乙醇发酵","s":3,"c":"14. 微生物的代谢","x":"酵母的乙醇发酵以 EMP 途径把葡萄糖降解为丙酮酸，丙酮酸脱羧生成乙醛与 CO₂，乙醛再被 NADH 还原为乙醇，净产 2 ATP，总反应为葡萄糖 → 2乙醇 + 2 CO₂。细菌中运动发酵单胞菌走 ED 途径（2-酮-3-脱氧-6-磷酸葡萄糖酸裂解为丙酮酸与 3-磷酸甘油醛），净产 1 ATP 但速率快、基因操作简便，是燃料乙醇研究的对象。发酵工艺上，酵母在厌氧、糖浓度适中（约10%~20%）、pH 4~5、30℃ 左右产乙醇最高；当溶氧充足时发生巴斯德效应，呼吸抑制发酵、菌体大量增殖而乙醇产率下降。乙醇发酵是\"发酵产物随培养条件改变\"的经典例证。"},{"id":"14.4","t":"混合酸发酵与丁酸发酵","s":3,"c":"14. 微生物的代谢","x":"大肠杆菌等进行混合酸发酵，产物为乳酸、乙酸、甲酸、CO₂ 与 H₂（甲酸经甲酸氢解酶分解为 H₂ 与 CO₂），因产酸量大而使甲基红（MR）试验阳性、VP 试验阴性，产气与否可用于区分大肠杆菌与不产气的伤寒沙门氏菌。产气肠杆菌则进行 2,3-丁二醇发酵，产物中性、VP 试验阳性、MR 阴性，这一对试验（IMViC 中的 MR 与 VP）正是基于发酵类型差异设计的鉴别手段。丁酸发酵由梭菌进行，产物为丁酸、乙酸、CO₂ 与 H₂；丙酮丁醇梭菌还可产生丙酮与丁醇，是 ABE（丙酮—丁醇—乙醇）发酵的工业菌。丙酸杆菌的丙酸发酵与氨基酸的 Stickland 反应则是厌氧分解氨基酸产能的特殊方式。"},{"id":"14.5","t":"有氧呼吸与三羧酸循环","s":3,"c":"14. 微生物的代谢","x":"有氧呼吸以分子氧为最终电子受体，有机物彻底氧化为 CO₂ 与 H₂O：葡萄糖经 EMP 生成丙酮酸，丙酮酸氧化脱羧为乙酰 CoA，进入三羧酸循环彻底氧化，产生的 NADH 与 FADH₂ 把电子交给呼吸链，经一系列细胞色素与醌类传递后交给 O₂，同时泵出质子驱动 ATP 合成酶。按经典计算每分子葡萄糖可产38 个 ATP，按现代修正（考虑质子漏与转运成本）约为 30~32 个，真核生物因线粒体转运损耗通常记为 36 个，答题时应说明采用哪一种计算口径。原核生物没有线粒体，其呼吸链位于细胞膜上，因此电子传递与 ATP 合成都在质膜完成。"},{"id":"14.6","t":"无氧呼吸","s":3,"c":"14. 微生物的代谢","x":"无氧呼吸以无机氧化物（NO₃⁻、SO₄²⁻、CO₂、Fe³⁺）或有机氧化物（延胡索酸）替代 O₂ 作为最终电子受体，电子传递链部分相同，但产能低于有氧呼吸。类型包括：硝酸盐呼吸（反硝化作用，假单胞菌、芽孢杆菌把 NO₃⁻ 逐步还原为 NO₂⁻、NO、N₂O、N₂，是氮循环中氮返回大气的关键步骤，也是污水处理脱氮的原理）；硫酸盐呼吸（脱硫弧菌把 SO₄²⁻ 还原为 H₂S）；碳酸盐呼吸（产甲烷菌以 CO₂ 为受体生成 CH₄）；延胡索酸呼吸（大肠杆菌厌氧时以延胡索酸为受体生成琥珀酸）。凡以无机物为电子受体的产能方式统称化能无机营养型呼吸，但要注意：硝化细菌是氧化无机物获能（化能自养），而反硝化细菌是氧化有机物、以硝酸盐为受体（化能异养），二者不可混淆。"},{"id":"14.7","t":"自养微生物的碳固定","s":3,"c":"14. 微生物的代谢","x":"自养微生物把 CO₂ 固定为细胞有机物有四条途径：卡尔文循环（CBB 循环）最普遍，由核酮糖二磷酸羧化酶/加氧酶（RuBisCO）催化 CO₂ 与核酮糖-1,5-二磷酸结合，经还原与再生阶段生成三碳糖，见于蓝细菌、紫硫细菌、硝化细菌与绝大多数化能自养菌，每固定 3 分子 CO₂ 消耗 9 ATP 与 6 NADPH；还原性三羧酸循环见于绿硫细菌，耗能较少但酶对氧敏感；还原性乙酰 CoA 途径（Wood-Ljungdahl 途径）见于产甲烷菌与硫酸盐还原菌，同时用于产能与固碳；3-羟基丙酸途径见于部分超嗜热古菌。化能自养菌必须大量氧化无机底物才能获得足够的 ATP 与还原力，这正是其生长慢、生物量低的原因。"},{"id":"14.8","t":"硝化作用与硫、铁的氧化","s":3,"c":"14. 微生物的代谢","x":"硝化作用是化能自养菌分两步把氨氧化为硝酸的过程：亚硝化细菌（亚硝化单胞菌、亚硝化球菌）把 NH₄⁺ 氧化为 NO₂⁻，硝化细菌（硝化杆菌）再把NO₂⁻ 氧化为 NO₃⁻，全过程释放的能量支持自养生长，是硝态氮形成的唯一生物途径，也是土壤氮素流失（硝酸盐淋溶）与水体富营养化的开端。硫细菌把H₂S 氧化为 S 与 SO₄²⁻（贝日阿托氏菌暂存硫粒），铁细菌把 Fe²⁺ 氧化为Fe³⁺ 并沉积为铁锈，氢细菌氧化 H₂。这些过程都属化能自养，且都是元素地球化学循环的关键环节；反硝化、硝化与固氮共同构成氮循环的生物环节，缺一不可。"},{"id":"14.9","t":"生物固氮","s":3,"c":"14. 微生物的代谢","x":"生物固氮是固氮微生物在固氮酶催化下把 N₂ 还原为 NH₃ 的过程，总反应为 N₂ + 8H⁺ + 8e⁻ + 16ATP → 2NH₃ + H₂ + 16ADP + 16Pi，可见固氮极为耗能并且必然伴随放氢。固氮酶由铁蛋白（提供电子）与钼铁蛋白（含 Fe-Mo 辅基，催化位点）组成，对氧极度敏感，因此固氮菌演化出多种保护机制：形成异形胞（蓝细菌）、与豆血红蛋白结合降低氧分压（根瘤菌）、呼吸保护与构象保护。固氮微生物包括自生固氮菌（固氮菌属、巴氏梭菌）、共生固氮菌（根瘤菌与豆科植物、弗兰克氏菌与放线菌根瘤、蓝细菌与满江红）与联合固氮菌（固氮螺菌）。根瘤菌结瘤依赖植物分泌的黄酮类物质诱导 Nod 因子合成，是宿主与细菌双向识别的范例。"},{"id":"14.10","t":"代谢调节与发酵的过度产物","s":3,"c":"14. 微生物的代谢","x":"微生物通过两种层次调节代谢：酶活性调节包括别构调节（末端产物结合酶调节亚基，如天冬氨酸转氨甲酰酶受 CTP 抑制）与共价修饰（磷酸化/去磷酸化）；酶合成调节包括诱导（底物诱导分解酶，如乳糖诱导 lac 操纵子）与阻遏（末端产物阻遏合成酶、分解代谢物阻遏即葡萄糖效应）。分支途径还演化出协同反馈抑制、累积反馈抑制与顺序反馈抑制，用以平衡多种末端产物的合成。育种上正是利用这些机制解除反馈控制：谷氨酸发酵需把生物素控制在亚适量使细胞膜不完整、谷氨酸大量排出；赖氨酸发酵用高丝氨酸缺陷型切断分支、使代谢流全部导向赖氨酸。所谓发酵过度产物（overflow），指碳源充足而生长受限时碳流溢入乙酸、乳酸等副产物，是高密度发酵需要控制的关键问题。第五篇 微生物生长与控制本篇是\"数量与条件\"的篇章，题目多为计算与实验判断：由生长曲线求代时、由稀释倍数与菌落数求菌浓度、给出一组消毒条件判断是否达到灭菌、给出氧关系判断菌的类群。务必把\"灭菌（杀死芽孢）\"与\"消毒（杀死病原体）\"这条分界线放在心中，因为它决定了几乎所有方法学问题的答案。"},{"id":"15.1","t":"计数法测定生长量","s":3,"c":"15. 生长测定与生长曲线","x":"平板计数法（活菌计数）把样品做 10 倍系列稀释后涂布或倾注于固体平板，培养后数菌落数（CFU），再乘稀释倍数推算原液浓度；因两个以上细胞相连只形成一个菌落，结果通常低于实际活菌数，且要求每板菌落在 30~300个之间才可靠。显微镜直接计数法用血细胞计数板在镜下数总菌数，快速但无法区分活菌与死菌，且样品中杂质会干扰。最大概率数（MPN）法用多管液体发酵的阳性管数查统计表推算，适合低浓度与只能液体培养的类群。比浊法用分光光度计测 OD600，快速、无损、可实时监测，但只在线性范围内与菌数成正比（约 10⁷~10⁹ 个/mL），且死菌与杂质同样计入。"},{"id":"15.2","t":"重量法与生理指标法","s":2,"c":"15. 生长测定与生长曲线","x":"重量法测菌体干重或湿重，适用于丝状真菌与大量培养物，结果反映生物量而非细胞数，需注意洗涤去除培养基残留。生理指标法测定呼吸强度（耗氧量或 CO₂ 释放量）、代谢产酸量、ATP 含量或特定成分（如含氮量、DNA 含量），间接反映活性生物量。选择测方法的依据是目的：要\"活菌数\"选平板计数，要\"总菌数\"选显微镜计数，要\"实时动态\"选比浊，要\"生物量\"选干重，要\"代谢活性\"选生理指标。竞赛题中如出现\"两种方法结果不一致\"，应首先判断是活菌与总菌的差别，还是线性范围与检出限的问题。"},{"id":"15.3","t":"生长曲线的四个时期","s":3,"c":"15. 生长测定与生长曲线","x":"以活菌数的对数为纵轴、培养时间为横轴，可得典型生长曲线。延滞期：菌数不增但细胞体积增大、RNA 与酶大量合成，是适应新环境的阶段，对抗生素等作用于繁殖过程的药物不敏感。对数期：菌数以几何级数增加，代时最短、形态与生理特征最典型，是实验与发酵的最佳种子期，也对青霉素等作用于细胞壁合成的药物最敏感。稳定期：新增与死亡数相等，菌数达峰值，营养耗尽、代谢产物（酸、醇、抗生素等次级代谢产物）积累并抑制生长，芽孢也在此时形成。衰亡期：死亡数超过新增数，菌体变形、自溶，活菌数骤降。四个时期的成因是\"营养、产物抑制、pH 与氧的联合作用\"，而不是单纯的\"细胞老化\"。"},{"id":"15.4","t":"比生长速率与代时","s":3,"c":"15. 生长测定与生长曲线","x":"比生长速率 μ 表示单位菌体在单位时间内的增量，以自然对数计：μ =(ln N₂ − ln N₁)/(t₂ − t₁)，单位 h⁻¹；对数期 μ 最大且恒定，称最大比生长速率μmax。代时（增代时间）g 是菌数增加一倍所需时间，g = ln2/μ = 0.693/μ。例如大肠杆菌代时 20 min（0.333 h），则 μ = 0.693/0.333 ≈ 2.08 h⁻¹。由任一组数据可推算增殖代数 n =(lg N₂ − lg N₁)/lg2。实际计算中常给出\"初始10³ 个/mL，培养 6 h 后达 10⁹ 个/mL\"，则由 2ⁿ = 10⁶ 得 n ≈ 20 代，代时 18 min。掌握这一组公式，生长曲线类计算题就不再是难点。"},{"id":"15.5","t":"连续培养与恒化器","s":2,"c":"15. 生长测定与生长曲线","x":"分批培养中营养不断消耗、产物不断积累，菌体只能经历一次生长曲线；连续培养则不断流入新鲜培养基并流出培养物，使菌体长期处于对数期。恒化器（chemostat）通过控制流速决定稀释率 D = F/V，稳定时菌体的比生长速率等于稀释率（μ = D），因此可用流速精确设定 μ，而由限制性营养的浓度决定菌浓度；恒浊器（turbidostat）则通过光电控制维持浊度恒定，菌体以接近μmax 的速率生长。连续培养的优点是效率高、菌体生理状态恒定、便于研究调控规律；难点在于长期运行易污染、菌株易退化、工艺控制复杂。工业上连续发酵与补料分批发酵各有适用场景。"},{"id":"15.6","t":"个体生长与群体生长","s":2,"c":"15. 生长测定与生长曲线","x":"微生物的生长有两个层次。个体生长指单个细胞体积增大并完成染色体复制、细胞壁扩增与分裂的全过程，其结果是产生两个子细胞，单细胞微生物的个体生长几乎与分裂同步，因此很难像多细胞生物那样\"长大而不增多\"。群体生长指群体数量与生物量的增加，用生长曲线描述，是发酵生产与微生物检验关注的对象。二者的关系是：群体生长是个体生长与分裂的统计结果，因此凡影响个体分裂速率的因素都会改变生长曲线的斜率。丝状真菌的群体生长另有特点：菌丝只在顶端延伸，菌落以近似恒定的速度向外扩展（线性生长），不能用指数增长模型简单描述。"},{"id":"16.1","t":"温度","s":3,"c":"16. 环境因素对生长的影响","x":"每种微生物都有最低、最适、最高三个 cardinal 温度，按最适温度分为：嗜冷菌（0~20℃，最适 ≤15℃）、嗜温菌（10~45℃，最适 20~40℃，绝大多数微生物与病原菌属此）、嗜热菌（45~80℃）、超嗜热菌（>80℃，多为古菌）。高温致死的原因是蛋白质不可逆变性、膜脂溶蚀与核酸损伤；低温只抑制代谢而不一定杀死，故菌种保藏常用 4℃、−20℃、−80℃ 与液氮（−196℃），并加甘油或二甲亚砜作保护剂。竞赛常考\"为什么冷藏只能保鲜不能灭菌\"\"为什么嗜热菌的酶能耐热\"，答案分别是低温的抑制作用与蛋白质结构（离子键、疏水核心、伴侣蛋白）的差异。"},{"id":"16.2","t":"pH 与水活度","s":3,"c":"16. 环境因素对生长的影响","x":"不同类群最适 pH 不同：细菌多为 6.5~7.5，放线菌 7.5~8.0，真菌 5~6，因此分离真菌常用酸性（pH 4~5）培养基以抑制细菌。嗜酸菌如氧化硫硫杆菌可在 pH 2 左右生长，嗜碱菌可在 pH 10~11 生长。培养基配制时需加缓冲对（K₂HPO₄/KH₂PO₄）或难溶碳酸钙以维持 pH，因为微生物产酸会使 pH 迅速下降而抑制自身。水活度（aw）表示可供微生物利用的水分，纯水为 1.00；多数细菌需 aw ≥0.90，酵母菌约 0.88，霉菌可低至 0.80，嗜盐菌需高盐环境。加盐、加糖、干燥之所以能保藏食品，本质是降低 aw 使微生物无法生长；这也是\"腌制与蜜饯防腐\"的微生物学原理。"},{"id":"16.3","t":"氧与微生物的关系","s":3,"c":"16. 环境因素对生长的影响","x":"按对氧的需求与耐受，微生物分五类：专性需氧（必须有氧，如结核分枝杆菌、铜绿假单胞菌）、专性厌氧（氧有毒，如破伤风梭菌、产甲烷菌）、兼性厌氧（有氧无氧均可，有氧时生长更好，如大肠杆菌、酿酒酵母）、微需氧（需 2%~10% 低氧，如幽门螺杆菌、弯曲菌）、耐氧厌氧（不需要氧但可耐受氧，如乳酸菌）。专性厌氧菌怕氧的机制是缺乏超氧化物歧化酶与过氧化氢酶，无法清除超氧阴离子与 H₂O₂，且缺乏以氧为末端受体的呼吸链。厌氧培养常用深层液体石蜡封盖、厌氧气袋（产气剂加指示剂）、厌氧手套箱或焦性没食子酸吸氧法。"},{"id":"16.4","t":"辐射、压力与渗透压","s":2,"c":"16. 环境因素对生长的影响","x":"紫外线以 260 nm 附近杀菌力最强，因核酸在此波长吸收峰最高，主要损伤是形成嘧啶二聚体使 DNA 复制受阻；其穿透力极弱，只能用于空气与物体表面消毒（超净工作台、接种室），且可见光可激活光复活酶修复损伤，故紫外照射后应避光。电离辐射（γ 射线、X 射线）能量高、穿透力强，通过产生自由基与直接打断 DNA 链杀菌，用于一次性塑料器械与部分食品的辐照灭菌。高压（深海嗜压菌）、高渗透压（嗜盐菌积累相容性溶质如甜菜碱、甘油以平衡渗透压）与低渗（细胞吸水膨胀、需细胞壁保护）都是重要的选择压力，其中低渗破裂正是\"溶菌酶处理后细菌易胀破\"的原因。"},{"id":"16.5","t":"营养物质浓度与限制","s":2,"c":"16. 环境因素对生长的影响","x":"营养物浓度与比生长速率的关系可用 Monod 方程描述：μ = μmax·S/(Ks+ S)，其中 S 为限制性营养浓度、Ks 为半饱和常数。Ks 反映菌对底物的亲和力，Ks 越小说明在极低浓度下仍能高速吸收，寡营养环境中的细菌 Ks 极低，这是它们能在微克级浓度下生存的原因。当 S 远大于 Ks 时 μ 趋近 μmax，此时生长由其他因素（氧、产物抑制）限制；当营养过量（如高糖、高盐）时反而出现底物抑制。恒化器正是利用这一关系：由流速设定 μ，再由 μ 与 S 的关系决定残余营养浓度与菌浓度。"},{"id":"16.6","t":"胁迫响应与交叉保护","s":2,"c":"16. 环境因素对生长的影响","x":"微生物面对高温、氧化、酸、渗透压等胁迫时启动一组保守的应急系统：热激蛋白（HSP，作为分子伴侣帮助变性蛋白重新折叠）、冷激蛋白、严谨反应（ppGpp 抑制 rRNA 合成以节省资源）、SOS 反应（修复 DNA）以及积累相容性溶质（甜菜碱、海藻糖、甘油）以平衡渗透压。亚致死的某种胁迫处理后，菌对其他胁迫的抗性也会提高，称交叉保护，其机制是胁迫蛋白的重叠。这解释了两个重要现象：稳定期与生物膜中的细菌对消毒剂和抗生素的抗性显著高于对数期细菌；食品加工中的\"亚致死损伤\"菌虽在选择性培养基上不生长，却仍可能修复后致病。"},{"id":"17.1","t":"灭菌、消毒、防腐与化疗的概念","s":3,"c":"17. 消毒灭菌与抗生素","x":"灭菌（sterilization）是杀死物体上一切微生物包括最耐热的芽孢，属绝对概念；消毒（disinfection）是杀死病原微生物及其他有害微生物，不要求杀死芽孢，属相对概念；防腐（antisepsis）是抑制微生物生长繁殖以防止腐败，主要用于活体表面或食品；化疗（chemotherapy）是用具有选择性毒性的化学药物杀灭体内病原体。杀菌与抑菌的区别在于前者不可逆致死，后者去除药物后菌仍可恢复，因此抑菌剂的效果判定需\"洗去药物后再培养\"。评价消毒效果常用 D 值（在特定条件下使菌数减少 90% 所需时间）与 F 值（在一定温度下杀灭一定数量芽孢所需时间）。"},{"id":"17.2","t":"高压蒸汽灭菌","s":3,"c":"17. 消毒灭菌与抗生素","x":"高压蒸汽灭菌是湿热灭菌中最可靠的方法，常规条件为 121℃、15~20 min（对应蒸汽表压约 0.1 MPa，即 1.05 kg/cm²）。其原理是：湿热穿透力强、蒸汽凝结时释放大量潜热，且水的存在使蛋白质更易变性凝固，因此在同样温度下湿热比干热高效得多。操作要点包括：锅内冷空气必须彻底排除（否则形成\"冷空气团\"使实际温度低于表压对应温度）、物品不能装得过满、含糖培养基改用 115℃、20~30 min 以防糖焦化、不耐热成分（维生素、某些抗生素、尿素）须过滤除菌。判断是否达到灭菌的标准是杀死嗜热脂肪芽孢杆菌的芽孢，这也是生物指示剂的原理。"},{"id":"17.3","t":"干热、煮沸、巴氏消毒与过滤","s":3,"c":"17. 消毒灭菌与抗生素","x":"干热灭菌用 160~170℃、2 h（或 180℃、1 h），靠氧化与脱水破坏细胞，用于玻璃器皿、金属器械与不能受潮的粉剂。煮沸消毒 100℃、5~10 min只能杀死营养细胞，芽孢仍存活，故不属灭菌；加 2% 碳酸钠可提高效果并防锈。巴氏消毒用 60~65℃、30 min（低温长时间）或 72℃、15 s（高温短时），可杀死牛奶中的结核分枝杆菌、沙门氏菌等病原菌而保留风味，但不能灭菌，须配合冷藏。间歇灭菌（Tyndall 法）用 100℃、30 min 连续三天，利用芽孢在间歇期萌发为营养细胞后再杀灭，适用于不耐高压的培养基。过滤除菌用于不耐热液体（血清、维生素溶液、抗生素液）与空气，滤膜孔径 0.22μm 可截留绝大多数细菌，但不能截留病毒与支原体（支原体需 0.1 μm）。"},{"id":"17.4","t":"化学消毒剂与防腐剂","s":3,"c":"17. 消毒灭菌与抗生素","x":"常用化学消毒剂按其作用机制分：醇类（70%~75% 乙醇使蛋白质变性并溶解膜脂，兼有脱水作用）、醛类（甲醛与戊二醛为烷化剂，与蛋白质氨基、巯基交联，戊二醛 2% 溶液属高效消毒剂，甲醛用于空间熏蒸）、酚类（苯酚、甲酚破坏膜并变性蛋白，受有机物影响小）、氧化剂（次氯酸钠、漂白粉、过氧化氢、过氧乙酸，氧化巯基与膜脂）、表面活性剂（季铵盐类为阳离子去污剂，作用于膜，对革兰阳性菌效果好，对结核分枝杆菌与芽孢无效）、重金属盐（汞、银、铜抑制巯基酶，多为抑菌）以及气体灭菌剂环氧乙烷（烷化 DNA 与蛋白，用于一次性塑料器械与不耐热器材）。影响效果的因素包括浓度、作用时间、温度、pH 与有机物（血清、脓液会显著降低效果，故器械须先清洗）。"},{"id":"17.5","t":"抗生素的作用靶点","s":3,"c":"17. 消毒灭菌与抗生素","x":"抗生素按作用靶点分四类。抑制细胞壁合成：青霉素与头孢菌素抑制转肽酶（PBP）、万古霉素结合 D-Ala-D-Ala、杆菌肽抑制载体脂循环、环丝氨酸抑制 D-Ala-D-Ala 合成、异烟肼抑制分枝菌酸合成，此类药物对生长旺盛的细菌最有效，对人体细胞无毒性（无细胞壁）。损伤细胞膜：多黏菌素 B 与膜脂多糖及磷脂结合（对革兰阴性菌强），两性霉素 B 与制霉菌素结合真菌膜上的麦角甾醇形成孔道。抑制蛋白质合成：氨基糖苷类（链霉素、卡那霉素）与四环素作用于 30S 亚基（前者致读码错误、后者阻 A 位），氯霉素、红霉素、克林霉素、利奈唑胺作用于 50S 亚基（分别抑制肽键形成、移位与起始）。抑制核酸合成：利福平抑制细菌 RNA 聚合酶，喹诺酮类抑制 DNA 旋转酶（拓扑异构酶Ⅱ），磺胺类与甲氧苄啶分别抑制二氢蝶酸合成酶与二氢叶酸还原酶（抗代谢物，双重阻断叶酸合成）。"},{"id":"17.6","t":"耐药机制与合理用药","s":3,"c":"17. 消毒灭菌与抗生素","x":"细菌耐药性的生化机制有五类：产生灭活酶（β-内酰胺酶水解青霉素与头孢菌素、氨基糖苷修饰酶、氯霉素乙酰转移酶）；靶点改变（PBP 结构变异使药物不能结合、rRNA 甲基化使大环内酯类失效、DNA 旋转酶突变使喹诺酮失效）；降低药物摄取（外膜孔蛋白缺失，见于铜绿假单胞菌）；主动外排（外排泵 AcrAB-TolC 等，可同时排出多种药物造成多重耐药）；形成生物膜与进入休眠状态（表型耐药）。耐药基因的来源是染色体突变与水平基因转移（接合、转导、转化），抗生素的选择压力使耐药株迅速富集。合理用药原则包括：依药敏试验选药、足量足疗程、避免无指征的预防与联合用药、限制畜牧业促生长用抗生素、实施医院感染监测与抗菌药物分级管理。方法高压蒸汽灭菌条件121℃，15~20 min效果类别灭菌适用范围培养基、玻璃器皿、废弃物干热灭菌160~170℃，2 h灭菌玻璃器皿、金属器械煮沸100℃，5~10 min消毒餐具、器械初步处理巴氏消毒62℃ 30 min 或 72℃ 15 s 100℃ 30 min，连续 3天消毒牛奶、啤酒、果汁灭菌不耐高压的培养基紫外线260 nm 照射表面消毒空气、超净台表面过滤除菌0.22 μm 滤膜除菌（不杀灭）血清、维生素、抗生素液环氧乙烷气体，常温灭菌一次性塑料器械70% 乙醇擦拭、浸泡消毒皮肤、器械表面间歇灭菌代表抗生素作用分子细胞壁靶点青霉素、头孢菌素转肽酶（PBP）多数革兰阳性菌、部分阴性菌主要抗菌谱细胞壁万古霉素D-Ala-D-Ala 前体革兰阳性菌（含MRSA）细胞膜多黏菌素 B LPS 与膜磷脂革兰阴性菌细胞膜两性霉素 B麦角甾醇真菌30S 亚基链霉素、四环素16S rRNA 与 A 位广谱50S 亚基红霉素、氯霉素23S rRNA、肽键形成广谱RNA 聚合酶利福平β 亚基结核分枝杆菌、革兰阳性菌DNA 旋转酶喹诺酮类拓扑异构酶Ⅱ广谱叶酸合成磺胺类、甲氧苄啶二氢蝶酸合成酶、二氢叶酸还原酶广谱第六篇 微生物遗传与基因工程微生物遗传是竞赛中\"最有区分度\"的部分。主线只有一条：遗传物质是什么（染色体、质粒、转座因子）—遗传物质如何变（突变与修复）—遗传物质如何交换（转化、接合、转导）—如何被人类利用（育种、基因工程、菌种保藏）。作图题（中断杂交、共转导）必须掌握\"时间或频率与距离成正比\"的定量关系，这是唯一需要动笔计算的地方。"},{"id":"18.1","t":"细菌染色体与基因组结构","s":3,"c":"18. 遗传物质与基因突变","x":"细菌通常只含一条环状双链 DNA 染色体，无组蛋白、无核膜，以拟核形式高度折叠；大肠杆菌基因组约 4.6 Mb、约 4300 个基因，枯草芽孢杆菌约4.2 Mb，最小的支原体仅约 0.58 Mb。细菌基因组的特点是基因密度高（约85%~90% 的序列编码蛋白）、几乎无内含子、功能相关的基因常成簇构成操纵子、GC 含量在种内相对稳定。此外，基因组中散布着水平转移获得的\"基因岛\"（如致病岛、抗性岛），其 GC 含量与密码子偏好常与主体序列不同，可据此识别外源片段。泛基因组概念（core genome 加 accessory genome）解释了同种不同菌株间基因数目的显著差异。"},{"id":"18.2","t":"质粒的不亲和性与转移","s":2,"c":"18. 遗传物质与基因突变","x":"质粒按复制机制与不相容群（incompatibility group）分类：两种亲缘相近的质粒不能在同一细胞中稳定共存，因为它们共用同一套复制与拷贝数控制元件而相互排斥，这一特性是质粒分类的重要依据。按转移能力，质粒分自我转移型（如 F、R 质粒，编码接合系统）与非自我转移型（如 ColE1）；按拷贝数分严紧型（1~2 个/细胞，与染色体同步复制）与松弛型（10~100 个/细胞，可被氯霉素扩增）。F 因子是最经典的接合质粒，可整合到染色体形成Hfr 株，也可在切离时误带宿主基因形成 F′ 因子；R 质粒因携带多重耐药基因并能在菌间高频转移，是临床耐药扩散的主要载体。"},{"id":"18.3","t":"基因突变的类型","s":3,"c":"18. 遗传物质与基因突变","x":"按表型分：营养缺陷型（丧失合成某种氨基酸或维生素的能力）、抗性突变型（对药物、噬菌体或重金属产生抗性）、条件致死突变型（如温度敏感型，在 42℃ 死亡而在 30℃ 正常）、发酵阴性突变型。按遗传物质改变分：碱基置换（转换是同类嘌呤或嘧啶互换，颠换是嘌呤与嘧啶互换，可造成同义、错义或无义突变）、移码突变（插入或缺失非 3 倍数的碱基，使读码框整体改变，后果通常最严重）、缺失、重复、倒位与易位。突变具有自发性（无定向、随机发生，选择只起筛选作用）、可逆性（回复突变）与稀有性，这些性质是\"突变—选择\"学说的实验基础。"},{"id":"18.4","t":"诱变的分子机制","s":3,"c":"18. 遗传物质与基因突变","x":"物理诱变剂中，紫外线主要产生嘧啶二聚体，X 射线与 γ 射线造成单双链断裂；化学诱变剂按机制分四类：碱基类似物（5-溴尿嘧啶代替胸腺嘧啶、2氨基嘌呤代替腺嘌呤，复制时引起错误配对）、烷化剂（亚硝基胍 NTG、甲基磺酸乙酯 EMS 使碱基烷基化而改变配对性质，NTG 是效率最高的诱变剂之一）、脱氨剂（亚硝酸使腺嘌呤脱氨为次黄嘌呤、胞嘧啶脱氨为尿嘧啶，造成转换）与嵌入剂（吖啶橙、溴化乙锭嵌入碱基之间，引起移码）。此外羟胺专一性地与胞嘧啶反应。判断某种诱变剂产生何种突变，关键是看它改变的是碱基配对性质（多为置换）还是改变碱基间距（多为移码）。"},{"id":"18.5","t":"DNA 损伤修复","s":3,"c":"18. 遗传物质与基因突变","x":"微生物有四种主要修复系统：光复活由 DNA 光解酶在可见光下直接切开嘧啶二聚体，是最简单的一种，说明紫外损伤并非不可逆；切除修复由uvrABC 核酸内切酶识别并切除损伤片段，再由 DNA 聚合酶Ⅰ与连接酶填补，是生物界最普遍的修复方式，切除修复缺陷会导致着色性干皮病；重组修复在复制遇到未修复损伤时通过 recA 介导的同源重组以完整链为模板绕过损伤，保留原有损伤但保证复制完成；SOS 修复是损伤严重时诱导的应急反应，由 recA 激活 LexA 自水解使 umuDC 等基因表达，用易错的跨损伤合成聚合酶强行复制，其代价是突变率大幅上升。此外还有错配修复（mutS、mutL、mutH）纠正复制错误。修复能力与突变率、与抗辐射性直接相关。"},{"id":"18.6","t":"诱变育种与筛选策略","s":3,"c":"18. 遗传物质与基因突变","x":"诱变育种的基本流程是：选择遗传稳定的单倍体、单核、产孢子丰富的出发菌株—制备单细胞悬液—用适宜剂量的诱变剂处理（常选致死率 70%~80%的剂量，以获得较高的正突变频率）—涂布平板初筛—摇瓶复筛—稳定性考察。筛选营养缺陷型需三步：诱变后淘汰野生型（用青霉素浓缩法，野生型在缺营养的培养基中生长而被青霉素杀死，缺陷型不生长而存活）、用完全培养基与基本培养基对照检出缺陷型、再用补充培养基鉴定缺陷型的种类。影印法（replica plating，Lederberg 设计）是检出缺陷型与抗性突变型的关键技术，其价值在于可以在不扰动菌落位置的前提下比较两种培养基上的生长情况。青霉素产量从约 20 U/mL 提高到 10 万 U/mL，正是诱变与筛选反复叠加的结果。"},{"id":"18.7","t":"转座因子","s":2,"c":"18. 遗传物质与基因突变","x":"转座因子是能在基因组内改变位置的 DNA 序列，分三类：插入序列（IS）最短，仅编码转座酶，两端有反向重复序列；转座子（Tn）含转座酶基因之外还携带耐药或毒力等标记基因；特殊类型包括噬菌体 Mu 与酵母的 Ty元件。转座机制有复制型（转座时先复制形成共整合体再解离，转座子拷贝数增加）与非复制型（剪切—粘贴，供体位点失去该序列）。转座的遗传效应包括：插入使基因失活（极性效应）、插入可激活邻近基因、通过同源序列引起缺失与倒位、携带耐药基因在染色体与质粒间迁移。因此转座因子既是基因组的\"破坏者\"，也是进化的\"原材料\"，是细菌多重耐药形成的重要机制之一。"},{"id":"19.1","t":"转化","s":3,"c":"19. 基因转移与重组","x":"转化是受体菌直接摄取供体菌游离 DNA 并使其遗传性状改变的过程。1928 年 Griffith 用肺炎链球菌小鼠实验发现：加热杀死的Ⅲ型（有荚膜、光滑型 S）菌与活的Ⅱ型（无荚膜、粗糙型 R）菌混合注射，小鼠死亡并分离出活的Ⅲ型菌，说明存在\"转化因子\"；1944 年 Avery 等用蛋白酶、RNA 酶与 DNA酶分别处理，只有 DNA 酶能取消转化活性，从而证明转化因子是 DNA。自然转化要求受体菌处于感受态，感受态由感受态刺激肽等诱导，出现在对数期后期；过程为双链 DNA 结合于细胞表面、一条链被降解、单链进入细胞并与染色体同源重组（依赖 RecA）。人工转化常用 CaCl₂ 加 heat shock 或电穿孔，是基因工程的基础操作。"},{"id":"19.2","t":"接合与 F 因子","s":3,"c":"19. 基因转移与重组","x":"接合是通过细胞间直接接触把 DNA 从供体转移到受体的过程，1946 年Lederberg 与 Tatum 把两种不同营养缺陷型的大肠杆菌 K12 混合培养后获得原养型重组体，首次发现接合；1952 年 Hayes 证明供体携带 F 因子，F+ 为供体、F− 为受体。接合时 F 因子以滚环方式复制，一条单链经性菌毛构成的通道进入受体，随后互补成双链，故 F+ × F− 后受体也变成 F+ 而供体的染色体并未转移。注意三点：接合必须有细胞接触（这与转化不同）；性菌毛由 F 质粒编码；F 因子在转移时优先自身转移，因此染色体基因的转移频率很低。"},{"id":"19.3","t":"Hfr 与中断杂交作图","s":3,"c":"19. 基因转移与重组","x":"Hfr（高频重组）菌株是 F 因子整合到细菌染色体上的结果，此时 F 因子能带动染色体从特定起点（插入位点）以固定方向转移到 F− 受体，但因 F 因子被染色体断开，只有极少数接合对能转移完整染色体，故受体大多仍为 F−却获得了供体的部分基因。Jacob 与 Wollman 用中断杂交技术作图：接合开始后每隔一定时间用组织搅拌器剧烈振荡以打断配对，再检测受体中已出现的供体基因，基因按进入时间先后排列，转移 1 分钟对应的 DNA 长度被定为一个图距单位，大肠杆菌完整环状图谱约 100 分钟。这一方法的精髓是\"时间即距离\"，与共转导的\"频率即距离\"形成对照。"},{"id":"19.4","t":"转导与共转导作图","s":3,"c":"19. 基因转移与重组","x":"转导以噬菌体为媒介转移宿主 DNA，普遍转导（P1、P22）可转移供体任意片段，局限转导（λ、φ80）只能转移整合位点附近的特定基因。转导作图利用共转导频率：两个基因被同一个转导颗粒同时包装并共同导入受体的频率越高，说明它们距离越近；共转导频率与距离的关系可近似为\"距离越近、共转导越频繁\"，据此可为基因排序。普遍转导颗粒的包装上限（P1 约 90~100 kb）决定了可共转导的最大范围，这一限制正是共转导只能用于近距离作图的物理原因。转导在自然界是耐药基因与毒力基因水平扩散的重要途径。"},{"id":"19.5","t":"酵母菌的接合型与线粒体遗传","s":2,"c":"19. 基因转移与重组","x":"酿酒酵母的单倍体有 a 与 α 两种接合型，由 MAT 基因座决定：MATa 编码 a 因子及其受体，MATα 编码 α 因子及其受体，两种信息素相互识别后细胞融合形成 a/α 二倍体，二倍体不再交配而转为产孢。接合型可发生转换，其机制是 HO 核酸内切酶在 MAT 位点造成双链断裂后以 HMLα 或 HMRa 为供体进行基因转换，这是\"基因组重排调控表型\"的经典例证。酵母的线粒体基因组成环状 DNA，其突变造成呼吸缺陷的\"小菌落\"（petite），表现为细胞质遗传（母系遗传），与核基因的孟德尔遗传形成鲜明对照。"},{"id":"19.6","t":"丝状真菌的准性生殖","s":2,"c":"19. 基因转移与重组","x":"准性生殖是真菌中不经过减数分裂而发生基因重组的现象，过程分三步：两个遗传上不同的单倍体菌丝融合形成异核体（同一细胞质内共存两种核）；两种核融合形成杂合二倍体核；二倍体核在增殖过程中发生体细胞交换（有丝分裂交换）与单倍体化，产生各种重组单倍体后代。构巢曲霉是研究准性生殖的模式菌。其遗传学意义在于：在缺乏有性生殖的种类中仍可通过准性生殖产生基因重组与多样性，因此不能把\"没有有性生殖\"等同于\"没有遗传重组\"。此概念与细菌的转化、接合、转导并列为原核与真核微生物中\"非减数分裂重组\"的例证。比较项转化接合转导媒介游离 DNA细胞间接触噬菌体是否需要接触否是否（但需噬菌体吸附）转移的 DNA供体 DNA 片段F 因子或染色体片段供体片段（普遍）或特定基因（局限）是否需感受态是RecA否否关键酶或结构性菌毛、滚环复制衣壳包装作图原理难以定量作图时间即距离共转导频率即距离"},{"id":"20.1","t":"工具酶与载体","s":3,"c":"20. 微生物基因工程与菌种保藏","x":"基因工程的工具酶包括：Ⅱ 型限制性内切核酸酶（识别回文序列并在特定位点切割，如 EcoRI 识别 GAATTC，产生黏性末端；同一种酶切割不同来源DNA 可产生互补末端，是拼接的基础）、DNA 连接酶（连接磷酸二酯键缺口）、逆转录酶（mRNA→cDNA）、Taq 等耐热 DNA 聚合酶（PCR）、碱性磷酸酶（去磷酸化防自连）与核酸酶 S1（切平末端）。载体必须具备三个条件：能自主复制、有可供筛选的标记、有单一限制酶切点（多克隆位点）。常用载体有质粒（pBR322、pUC 系列）、噬菌体 λ、柯斯质粒（cosmid，兼具质粒与 λ 的特点、容量约 45 kb）、细菌人工染色体（BAC）与酵母人工染色体（YAC，可容纳 Mb 级片段）；表达载体还需加启动子、核糖体结合位点（SD 序列）、终止子与标签序列。"},{"id":"20.2","t":"外源基因的导入与筛选","s":3,"c":"20. 微生物基因工程与菌种保藏","x":"导入方法包括：转化（CaCl₂ 加 heat shock、电穿孔）、转染（噬菌体DNA 或病毒核酸导入真核细胞）、显微注射、基因枪与农杆菌 Ti 质粒介导（植物）。筛选与鉴定分几个层次：以抗性基因或营养缺陷互补作初步选择；以蓝白斑筛选（lacZ α 互补，含插入片段的重组子在 X-gal 平板上呈白色）作重组子鉴别；用菌落原位杂交、PCR、限制酶图谱分析验证插入片段；最后用测序确证序列、用 SDS-PAGE 或免疫学方法检测表达产物。这一\"选择—鉴别—验证—确证\"的逻辑链条是分子克隆实验设计的通用框架，答题时应完整复述而不是只写\"用抗生素筛选\"。"},{"id":"20.3","t":"表达系统的选择","s":3,"c":"20. 微生物基因工程与菌种保藏","x":"大肠杆菌是最常用的原核表达系统，优点是生长快、成本低、遗传背景清楚、表达量高；缺点是缺乏糖基化等翻译后修饰、真核蛋白常折叠错误形成包涵体、内毒素难以完全去除。枯草芽孢杆菌与乳酸菌擅长把蛋白分泌到胞外，便于回收。真核系统中，酿酒酵母与毕赤酵母（甲醇诱导的 AOX1 启动子）可进行部分真核修饰但糖基化模式与人体不同（高甘露糖型）；昆虫杆状病毒系统表达量高；哺乳动物细胞（CHO、HEK293）糖基化最接近人体，是生产抗体与疫苗的主流，但成本高、周期长。选择表达系统的判据是：产物是否需要糖基化与正确折叠、是否需要分泌、产量与经济性要求。"},{"id":"20.4","t":"CRISPR-Cas 与细菌的免疫","s":3,"c":"20. 微生物基因工程与菌种保藏","x":"CRISPR-Cas 是细菌与古菌对噬菌体和质粒的适应性免疫系统，分三步：适应（Cas1-Cas2 把入侵 DNA 的一小段作为间隔序列整合到 CRISPR 阵列中）、表达（转录出 crRNA）、干扰（crRNA 引导 Cas 核酸酶识别并切割含互补序列的外源 DNA）。Ⅱ 型系统的 Cas9 需同时识别靶序列旁的 PAM（如SpCas9 识别 NGG），这一限制保证了自身 CRISPR 阵列不被切割。基于此发展的 CRISPR-Cas9 基因编辑技术只需更换 crRNA 序列即可靶向任意位点，已广泛用于基因敲除、碱基编辑、基因调控与核酸检测（如 SHERLOCK、DETECTR）。此外，细菌还有限制—修饰系统（R-M）作为非适应性免疫：限制酶切割未甲基化的外源 DNA，甲基化酶保护自身 DNA。CRISPR 是\"基础研究源自微生物\"的最佳案例。"},{"id":"20.5","t":"噬菌体展示与定向进化","s":2,"c":"20. 微生物基因工程与菌种保藏","x":"噬菌体展示把外源肽段或蛋白与丝状噬菌体（M13）的 pⅢ 或 pⅧ 衣壳蛋白融合，使多肽展示在噬菌体表面而编码基因藏在内部，实现\"表型与基因型统一\"。通过生物淘选（biopanning，以固定化靶分子反复吸附—洗脱—扩增），可从数十亿种序列中富集出与靶标高亲和结合的克隆，用于抗体库筛选、受体配体研究与疫苗表位鉴定。定向进化（如易错 PCR 结合高通量筛选、DNA shuffling）则通过随机突变与重组并结合筛选压力，获得性能改良的酶，是蛋白质工程的经典路径。二者共同的思想是\"建库—筛选\"，把筛选压力交给实验而非设计。"},{"id":"20.6","t":"菌种保藏","s":3,"c":"20. 微生物基因工程与菌种保藏","x":"菌种保藏的目标是保持菌株的存活、纯度与遗传性状稳定，防止变异、退化与污染。常用方法按保藏期由短到长包括：斜面低温保藏（4℃，数月，需定期移植但易退化）、液体石蜡覆盖（隔绝氧与减少水分蒸发，1~2 年）、沙土管干燥保藏（适用于产孢子的菌）、冷冻干燥（真空冻干，绝大多数微生物可保藏 10 年以上，是菌种保藏中心的常规方法）、超低温冷冻（−80℃ 加甘油或二甲亚砜，或液氮 −196℃）。保藏前应选对数期或稳定期的健壮培养物，并加保护剂以减轻冰晶损伤。国际上主要保藏机构有 ATCC（美国）、DSMZ（德国）、JCM（日本），我国有 CGMCC（中国普通微生物菌种保藏管理中心）、CCTCC 与 CMCC（医学真菌与细菌）。第七篇 微生物生态生态篇的命题方式是\"给一个生境或一种关系，问微生物扮演什么角色\"。复习时把三张网记住即可：空间分布网（土壤—水体—空气—极端环境—生物体）、种间关系网（互生—共生—拮抗—寄生—捕食）、物质循环网（碳—氮—硫磷）。这三张网交叉处就是综合题的落点，例如\"根瘤菌既是共生关系又是氮循环环节\"。"},{"id":"21.1","t":"土壤中的微生物","s":3,"c":"21. 微生物的分布与群落","x":"土壤是微生物最丰富的天然生境，每克表层土壤含细菌 10⁷~10⁹ 个、放线菌孢子与真菌菌丝数量巨大，真菌菌丝总长可达每克数十至数百米。垂直分布上以表层 5~30 cm 的耕作层最多，随深度增加因有机质与氧减少而急剧下降。土壤微生物参与有机质分解与腐殖质形成、固氮、硝化与反硝化、溶磷、铁锰转化，是土壤肥力的核心。影响其分布的因素包括有机质含量、水分、通气、pH、温度与耕作方式，因此\"土壤微生物数量与活性\"常作为土壤健康与污染程度的评价指标。放线菌在偏碱、干燥的土壤中比例较高，也是土壤特有泥腥味的来源。"},{"id":"21.2","t":"水体中的微生物","s":3,"c":"21. 微生物的分布与群落","x":"水体微生物的分布受营养、光照、温度、盐度与溶解氧控制：淡水湖沼中近岸与表层数量多，深层与沉积物中厌氧菌丰富；海水中每毫升约 10⁵~10⁶ 个细菌，近岸因陆源营养输入而高于大洋。按生活方式分浮游、附着（生物膜）与沉积三类；按营养分为自养（蓝细菌、硅藻、甲藻）与异养（分解者）。水体微生物是水体自净的主力，但当有机污染超过自净能力时会造成缺氧与富营养化。卫生学上以大肠菌群作为粪便污染指示菌，我国生活饮用水标准要求每100 mL 水样中不得检出总大肠菌群，这一指标的意义在于它来自肠道、数量大、易检测且存活期与病原菌相近。"},{"id":"21.3","t":"空气与极端环境中的微生物","s":2,"c":"21. 微生物的分布与群落","x":"空气本身不含固有微生物所需的营养与水分，其中的微生物全部来自土壤尘埃、水面飞沫与人类活动，因此室内多于室外、城市多于农村、近地面多于高空；直径小于 2~5 μm 的颗粒可长时间悬浮并随气流远距离传播，是呼吸道传染病（结核、流感、新冠）与霉菌孢子过敏的传播基础。空气微生物用沉降平板法或撞击式采样器测定。极端环境包括热泉（>80℃）、极地海冰、盐湖（饱和盐水）、酸性矿水（pH<2）、深海高压、高辐射区与寡营养深海，其中生存的主要是古菌与特殊的细菌类群，它们依靠特殊的膜脂、耐热酶、相容性溶质与修复系统维持生存，是研究生命极限与外泌生物技术的资源库。"},{"id":"21.4","t":"动植物体表与体内的微生物","s":3,"c":"21. 微生物的分布与群落","x":"植物体表（叶面、根际）与体内（内生菌）栖息着大量微生物，根际因根系分泌糖、有机酸与氨基酸而产生明显的\"根际效应\"，根际细菌数量可比非根际土壤高数十至数百倍。动物体表与腔道亦有特征性菌群：人体皮肤以葡萄球菌、丙酸杆菌、棒状杆菌为主（与皮脂和汗液有关），口腔以链球菌为主并形成牙菌斑生物膜，胃内以耐酸的螺杆菌与少量乳酸菌为主，小肠菌少而大肠菌最多（可达每克粪便 10¹¹ 个），女性阴道以产乳酸、维持酸性 pH 的乳杆菌为主。这些菌群与宿主形成稳定的互惠关系，其组成受饮食、年龄、用药（尤其抗生素）与免疫状态影响。"},{"id":"21.5","t":"生物膜","s":3,"c":"21. 微生物的分布与群落","x":"生物膜是微生物附着于固体表面后分泌胞外聚合物（EPS，含多糖、蛋白与 DNA）形成的结构化群落，形成过程为：可逆附着—不可逆附着（分泌黏附素）—微菌落形成与 EPS 积累—成熟的三维结构（含塔状结构与水通道）—分散释放。成熟生物膜内的细菌通过群体感应（如酰基高丝氨酸内酯 AHL 系统）协调基因表达，形成营养与氧的梯度，外层活跃、内层休眠。生物膜的医学意义在于抗性与耐受性显著提高（可达浮游菌的 100~1000 倍），是导管感染、牙菌斑、慢性伤口与人工瓣膜感染的根源；工程上则利用生物膜（滴滤池、生物转盘、生物膜反应器）处理污水。"},{"id":"21.6","t":"微生物群落与研究方法","s":2,"c":"21. 微生物的分布与群落","x":"群落研究要回答\"有哪些、各多少、在做什么\"。传统方法依赖培养，但自然环境中有 99% 以上的微生物至今不可培养，故\"平板计数\"只能反映极小部分。现代方法包括：荧光显微镜与 FISH（用 16S rRNA 探针原位识别类群）、DGGE/T-RFLP 等指纹图谱（比较群落结构差异）、高通量测序（16S rRNA 扩增子测序给出组成与丰度，宏基因组测序给出功能基因）、宏转录组与宏蛋白组（给出活性）、单细胞基因组与培养组学（获取未培养菌的基因组与纯培养）。方法选择的关键是区分\"组成\"与\"功能\"、\"潜在\"与\"活跃\"，这是材料题常设的陷阱。"},{"id":"22.1","t":"互生关系","s":3,"c":"22. 微生物间及与动植物的关系","x":"互生（protocooperation）是两种微生物相互提供有利条件、双方均受益但并非彼此必需的关系，分开后仍能独立生活。典型例子包括：固氮菌与纤维素分解菌共培养时，前者提供氮素、后者提供碳源而双方生长都好于单独培养；酵母与乳酸菌在发酵中互相提供维生素与代谢物；土壤中氨化细菌产氨供硝化细菌利用。互生与共生的区别在\"是否必需\"，把握这一点即可判断二者界限。互生在自然界极为普遍，是群落内代谢物交换、分工与稳定的基础，也是混合发酵（如白酒酿造的多菌种协同）的理论依据。"},{"id":"22.2","t":"共生关系：地衣、菌根与根瘤","s":3,"c":"22. 微生物间及与动植物的关系","x":"共生（mutualism）是双方紧密生活、相互依存、分开后难以正常生活的互利关系。地衣是真菌与藻类（或蓝细菌）的复合体，真菌提供庇护与矿质、藻类提供光合产物；菌根是土壤真菌与植物根系的共生，外生菌根（多为担子菌，包裹根尖形成菌套与哈氏网，见于森林树木）与丛枝菌根（球囊菌门，菌丝穿入根皮层细胞形成丛枝，见于约 80% 陆生植物）是两大类型，其功能是极大扩展根系吸收面积、尤其提高对磷的吸收，并增强抗旱抗病能力；根瘤是豆科植物与根瘤菌的共生，根瘤菌在类菌体状态下由豆血红蛋白维持低氧环境，固氮效率极高。三者共同说明：共生可以创造出单独一方无法实现的生态功能。"},{"id":"22.3","t":"拮抗、寄生与捕食","s":3,"c":"22. 微生物间及与动植物的关系","x":"拮抗是两种微生物通过竞争营养、改变 pH、分泌抗生素或细菌素等方式相互抑制的关系，是抗生素筛选与生物防治的理论基础（土壤中产抗生素的放线菌抑制病原菌）。寄生是一种微生物寄生于另一种微生物体内或表面并从中获取营养，如噬菌体寄生于细菌、蛭弧菌（Bdellovibrio）钻入革兰阴性菌周质空间繁殖并裂解宿主、真菌寄生真菌（木霉寄生立枯丝核菌）。捕食是直接吞食，如黏菌与变形虫吞食细菌、纤毛虫捕食细菌与藻类、食线虫真菌以菌环或黏性球捕获线虫。这三类关系共同限制种群数量、维持群落多样性，是\"生物防治\"与\"群落自我调节\"的机制来源。"},{"id":"22.4","t":"根际微生物与内生菌","s":2,"c":"22. 微生物间及与动植物的关系","x":"根际是根系周围受根系分泌物直接影响的薄层土壤，其中微生物数量与活性显著高于非根际土壤，形成以假单胞菌、芽孢杆菌、根瘤菌、菌根真菌为主的群落。根际微生物的功能包括：分解有机质释放养分、溶磷与解钾、固氮、产生植物激素（吲哚乙酸）促进生长、诱导植物系统抗性、抑制土传病原（生防菌）。内生菌是生活于植物组织内而不引起明显病害的微生物（多为细菌与真菌），可通过固氮、产次生代谢物（如紫杉醇类似物）与增强抗逆性使宿主受益，是天然产物发现的重要资源。用\"促生菌（PGPR）\"概念可统一描述这些有益根际细菌。"},{"id":"22.5","t":"瘤胃微生物与反刍动物","s":3,"c":"22. 微生物间及与动植物的关系","x":"瘤胃是一个 39~40℃ 的严格厌氧连续发酵罐，内含高密度的细菌（10¹⁰~10¹¹ 个/mL）、原虫（纤毛虫，10⁴~10⁶ 个/mL）、厌氧真菌与噬菌体，构成复杂的共生体系。其核心功能是把动物自身不能消化的纤维素、半纤维素发酵为挥发性脂肪酸（乙酸、丙酸、丁酸）供动物吸收，同时把非蛋白氮（尿素、铵盐）转化为微生物蛋白，随菌体流入皱胃与小肠被消化吸收，因此反刍动物可仅靠粗饲料与非蛋白氮维持氮平衡。副产物是 CO₂ 与 CH₄（甲烷），反刍动物是全球重要的甲烷排放源。瘤胃微生物区系对日粮变化高度敏感，突然更换饲料会引起酸中毒，这是生产实践中的常见问题。"},{"id":"22.6","t":"人体肠道菌群与微生态平衡","s":3,"c":"22. 微生物间及与动植物的关系","x":"人体肠道栖息着 400~1000 种、总数约 10¹³~10¹⁴ 个微生物，以拟杆菌门与厚壁菌门为主，其组成在个体间差异大但在个体内相对稳定。主要功能包括：发酵膳食纤维产生短链脂肪酸（乙酸、丙酸、丁酸）为肠上皮供能并调节免疫；合成维生素 K 与部分 B 族维生素；通过定植抵抗竞争性排斥病原菌；促进肠黏膜免疫系统成熟与免疫耐受；参与胆汁酸与药物代谢。菌群失衡（dysbiosis）与肥胖、炎症性肠病、过敏、代谢综合征相关。调节手段有益生菌（活的有益菌如双歧杆菌、乳杆菌）、益生元（选择性地促进有益菌生长的寡糖）与粪菌移植，后者对反复发作的艰难拟梭菌感染疗效确切。"},{"id":"23.1","t":"碳循环中的微生物","s":3,"c":"23. 物质循环与环境保护","x":"碳循环的微生物环节包括四个方向：光合固定（蓝细菌、藻类与光合细菌把 CO₂ 转为有机物）、分解与呼吸（异养微生物分解动植物残体，把有机碳氧化为 CO₂ 返回大气）、甲烷生成（产甲烷古菌在严格厌氧条件下以 H₂/CO₂ 或乙酸产 CH₄，是沼气发酵的末端步骤）、甲烷氧化（甲烷氧化菌以 CH₄ 为唯一碳源与能源，减缓温室效应）。此外碳酸盐的沉积与溶解也受微生物代谢影响。理解碳循环的关键在于：光合固定的碳与呼吸分解释放的碳在自然状态下大致平衡，而化石燃料燃烧与土地利用改变打破了这一平衡，导致大气 CO₂ 上升。"},{"id":"23.2","t":"氮循环中的微生物","s":3,"c":"23. 物质循环与环境保护","x":"氮循环有五个微生物驱动的过程：固氮（固氮菌、根瘤菌、蓝细菌把 N₂还原为 NH₃）、氨化（分解有机氮为 NH₃/NH₄⁺，由氨化细菌完成，是氮素重新可利用的起点）、硝化（亚硝化细菌与硝化细菌分两步把 NH₄⁺ 氧化为NO₃⁻）、反硝化（反硝化细菌以 NO₃⁻ 为电子受体逐步还原为 N₂ 返回大气）、厌氧氨氧化（anammox，浮霉菌门的厌氧氨氧化细菌以 NH₄⁺ 与NO₂⁻ 直接生成 N₂，是污水处理中节能脱氮的新工艺）。人类活动通过哈伯—博施合成氨与豆科种植大幅增加生物可利用氮，造成水体富营养化与氧化亚氮排放，这是氮循环被改变的核心问题。"},{"id":"23.3","t":"硫、磷循环与分解作用","s":2,"c":"23. 物质循环与环境保护","x":"硫循环的微生物环节包括：含硫有机物的分解产生 H₂S、硫细菌把 H₂S 氧化为 S 与 SO₄²⁻（硫化作用）、硫酸盐还原菌把 SO₄²⁻ 还原为 H₂S（反硫化作用，造成金属腐蚀与水体发黑发臭）、以及硫在沉积物中的矿化。磷循环没有气态环节，主要靠微生物把有机磷矿化为磷酸盐、以及溶磷菌分泌有机酸或质子溶解难溶性磷酸钙，此外菌根真菌极大扩展了植物获取磷的范围。分解作用是微生物最基础的生态功能：纤维素由纤维素酶（厌氧菌的纤维小体）水解，半纤维素与果胶由相应酶解聚，木质素主要靠白腐真菌的过氧化物酶降解，几丁质、蛋白质、脂肪与核酸也各有专性分解菌参与，最终产物进入腐殖质或矿化。"},{"id":"23.4","t":"微生物与环境污染治理","s":3,"c":"23. 物质循环与环境保护","x":"微生物治理污染有三条路径：一是生物降解，利用微生物的代谢多样性分解石油烃、多环芳烃、农药、塑料添加剂、表面活性剂等，其中共代谢（cometabolism）可使微生物在不能以其为唯一碳源时仍将其转化；二是生物转化与固定，如把剧毒的 Cr⁶⁺ 还原为低毒的 Cr³⁺、把汞甲基化或还原挥发、用生物吸附富集重金属；三是生物修复工程，分原位（投加营养即生物刺激、投加菌剂即生物强化、控制氧与电子受体）与异位（挖出后堆制或反应器处理）。限制因素通常是污染物生物可利用性低、电子受体或营养缺乏、以及共代谢底物不足，因此工程上常配合表面活性剂、通气与营养补充。"},{"id":"23.5","t":"微生物分子生态学与污染监测","s":2,"c":"23. 物质循环与环境保护","x":"分子生态学用核酸序列直接研究环境中的微生物，摆脱了培养依赖：16S rRNA 扩增子测序给出群落的组成与相对丰度，宏基因组给出功能基因库，宏转录组反映活跃表达，单细胞基因组可获取单个未培养菌的完整基因组。应用包括：污染物的生物指示（发光细菌抑制试验测急性毒性、Ames 试验测致突变性、群落结构变化指示生态胁迫）、生物修复过程的监控（跟踪降解菌丰度与降解基因表达）、以及环境与人体微生物组研究。要明确分子方法的局限：相对丰度不等于绝对数量，DNA 的存在不等于活性，因此结论常需与培养、显微观察或化学测定交叉验证。"},{"id":"23.6","t":"微生物与温室气体及气候变化","s":2,"c":"23. 物质循环与环境保护","x":"微生物同时是温室气体的源与汇。产甲烷古菌在厌氧环境（稻田、湿地、瘤胃、垃圾填埋场）产生 CH₄，而甲烷氧化菌在好氧界面把它氧化为 CO₂，二者的平衡决定净排放；硝化与反硝化过程会产生 N₂O，其单位质量增温潜势约为 CO₂ 的 273 倍，是臭氧层损耗与气候变暖的重要贡献者。海洋浮游微生物通过光合固定与颗粒沉降构成\"生物泵\"，把碳输送到深海，是全球碳循环的关键环节。气候变暖又会加速冻土有机质分解，形成正反馈。减排的微生物学途径包括稻田水分管理与间歇灌溉、硝化抑制剂、反刍动物饲料调控（减少产甲烷）以及沼气回收利用。循环关键微生物过程代表微生物生态或应用意义碳光合固定蓝细菌、藻类初级生产，固定 CO₂碳甲烷生成产甲烷古菌沼气发酵，温室气体碳甲烷氧化甲烷氧化菌减少甲烷排放氮固氮根瘤菌、固氮菌、蓝细菌提供生物可利用氮氮硝化亚硝化单胞菌、硝化杆菌形成硝酸盐，氮素流失氮反硝化假单胞菌、芽孢杆菌脱氮，返回大气氮氮厌氧氨氧化厌氧氨氧化细菌节能生物脱氮硫硫化与硫酸盐还原硫细菌、脱硫弧菌硫循环、金属腐蚀磷溶磷与矿化溶磷菌、菌根真菌提高磷有效性第八篇 感染与免疫本篇是医学微生物学与基础免疫学的交汇处，命题方式以\"比较\"和\"判断\"为主：内毒素与外毒素、非特异性免疫与特异性免疫、体液免疫与细胞免疫、四型超敏反应。复习时不要孤立背名词，而应把\"病原体如何突破防线\"与\"宿主如何逐层应对\"对应起来看，两者是同一场战争的两侧。"},{"id":"24.1","t":"正常菌群与条件致病菌","s":3,"c":"24. 病原微生物的致病机制","x":"正常菌群是定居于健康人体表与腔道、与宿主长期共生的微生物群，在特定部位形成相对稳定的组成，其生理意义包括生物拮抗（定植抵抗）、参与物质代谢与维生素合成、促进免疫系统成熟与抗原刺激。条件致病菌（机会致病菌）是正常菌群成员或环境中广泛存在的低毒力微生物，在宿主防御功能下降时致病，常见者有大肠杆菌、铜绿假单胞菌、金黄色葡萄球菌、表皮葡萄球菌、白色念珠菌与艰难拟梭菌。诱发条件包括：免疫抑制（激素、化疗、HIV）、广谱抗生素长期使用导致菌群失调与二重感染、侵入性诊疗操作（导管、插管、手术）、菌群寄居部位改变（如大肠杆菌进入泌尿道或腹腔）。医院感染多由此类菌引起，且常为多重耐药株。"},{"id":"24.2","t":"黏附与侵袭","s":3,"c":"24. 病原微生物的致病机制","x":"黏附是感染的第一步，病原体借助黏附素与宿主细胞受体特异性结合，如大肠杆菌的菌毛（Ⅰ 型菌毛结合甘露糖、P 菌毛结合糖脂）、化脓性链球菌的M 蛋白与脂磷壁酸、幽门螺杆菌的黏附素与尿素酶（分解尿素产氨中和胃酸）、流感病毒的 HA 与呼吸道上皮唾液酸受体。侵袭指病原体突破黏膜屏障进入组织并在其中扩散的能力，机制包括分泌侵袭性酶降解细胞外基质、诱导宿主细胞膜内陷（拉链式或触发式内化）以及经 M 细胞转运。侵袭力的强弱不等同于致病力的强弱：霍乱弧菌只停留在肠腔表面、不侵袭上皮却因产毒素而致病，说明\"黏附—产毒\"可以替代\"侵袭\"成为致病途径。"},{"id":"24.3","t":"外毒素与内毒素","s":3,"c":"24. 病原微生物的致病机制","x":"外毒素是革兰阳性菌与部分革兰阴性菌在生长过程中合成并分泌到胞外的蛋白质，热不稳定（60~80℃ 即失活）、毒性极强、对靶组织有高度特异性、抗原性强且可经甲醛处理脱毒制成类毒素。经典外毒素及其机制包括：白喉毒素抑制延伸因子 EF-2 从而阻断蛋白质合成；破伤风痉挛毒素阻断抑制性中间神经元释放抑制性递质，导致肌肉强直痉挛；肉毒毒素抑制胆碱能神经末梢释放乙酰胆碱，导致弛缓性麻痹；霍乱毒素激活肠上皮腺苷酸环化酶使 cAMP 升高、大量分泌氯与水；志贺毒素作用于 60S 核糖体阻断真核蛋白合成。内毒素是革兰阴性菌外膜的脂多糖，其活性中心为类脂 A，热稳定（需 160℃ 数小时才破坏）、毒性较弱且无种属特异性，引起发热、白细胞变化、休克与弥散性血管内凝血，不能制成类毒素。"},{"id":"24.4","t":"侵袭性酶、超抗原与免疫逃逸","s":2,"c":"24. 病原微生物的致病机制","x":"侵袭性酶包括透明质酸酶（分解结缔组织基质，促进扩散）、链激酶与链道酶（溶解纤维蛋白与 DNA，利于扩散）、胶原酶、血浆凝固酶（金黄色葡萄球菌产生，使纤维蛋白包裹菌体以抗吞噬）与 IgA 蛋白酶（淋球菌、脑膜炎球菌、流感嗜血杆菌破坏黏膜抗体）。超抗原（如金黄色葡萄球菌肠毒素、中毒性休克综合征毒素 TSST-1）不经加工即桥连 MHC Ⅱ 类分子与 TCR 的 Vβ区，可非特异激活 5%~20% 的 T 细胞，导致大量细胞因子释放与全身性炎症。免疫逃逸策略包括荚膜与蛋白 A 抗吞噬、抗原变异（流感 HA 漂移与转换、HIV 的 gp120 高变区）、抑制补体、分泌 IgA 蛋白酶、细胞内寄生（结核分枝杆菌阻止吞噬体与溶酶体融合、李斯特菌逃入胞质）以及形成生物膜。"},{"id":"24.5","t":"感染的类型与传播途径","s":3,"c":"24. 病原微生物的致病机制","x":"按临床表现分：隐性感染（亚临床，最常见，可产生免疫力）、显性感染（出现症状）、潜伏感染（病原体长期潜伏，如单纯疱疹病毒潜伏于神经节）、慢性感染（病程长、持续排菌，如乙型肝炎、结核）与带菌状态（恢复期或健康带菌者，是重要传染源）。按病原体来源分外源性感染与内源性感染（自身菌群）。传播途径包括：呼吸道（飞沫与气溶胶，如结核、流感、新冠）、消化道（粪—口，如霍乱、伤寒、甲肝）、接触（皮肤黏膜，如淋病、梅毒）、虫媒（蚊传疟疾与登革热、虱传斑疹伤寒、蜱传莱姆病）、血液与体液（乙肝、丙肝、HIV）、垂直传播（宫内、产道、哺乳）以及土壤与动物源性传播（破伤风、炭疽、布鲁氏菌病）。判断传播途径时要兼顾病原体的抵抗力与排出途径。"},{"id":"24.6","t":"医院感染与生物安全","s":2,"c":"24. 病原微生物的致病机制","x":"医院感染（又称院内感染、卫生保健相关感染）是患者或医务人员在医院环境中获得的感染，其病原体以条件致病菌与多重耐药株为主，常见者有耐甲氧西林金黄色葡萄球菌（MRSA）、铜绿假单胞菌、鲍曼不动杆菌、艰难拟梭菌与白色念珠菌。危险因素包括易感人群集中、广谱抗生素使用导致菌群失调、侵入性操作（导管、插管、内镜）、手术与免疫抑制治疗；传播方式包括交叉感染（人与人、医务人员手）、环境感染（器械、空气）与医源性感染（输血、注射）。防控依靠手卫生、规范消毒灭菌、隔离措施、抗菌药物分级管理与耐药监测。实验室与生产环节则按生物安全等级（BSL-1 至 BSL-4）管理，配合生物安全柜、负压与个人防护装备，BSL-4 用于无有效防治手段的高危病原。比较项外毒素内毒素来源革兰阳性菌与部分革兰阴性菌革兰阴性菌外膜化学本质蛋白质脂多糖，活性中心为类脂 A存在位置分泌至胞外或存于胞内细胞壁组分，菌裂解后释放热稳定性不稳定，60~80℃ 失活稳定，需 160℃ 数小时破坏毒性极强，有组织特异性较弱，无种属与组织特异性抗原性与类毒素强，可制成类毒素弱，不能制成类毒素典型效应白喉、破伤风、肉毒、霍乱发热、白细胞变化、休克、DIC"},{"id":"25.1","t":"非特异性免疫的屏障结构","s":3,"c":"25. 宿主的免疫防御","x":"非特异性（固有）免疫是先天具备、无抗原特异性、无免疫记忆的防御，作用迅速、范围广，是抗感染的第一道与第二道防线。屏障结构包括：皮肤与黏膜的机械阻挡（上皮紧密连接、纤毛摆动、黏液分泌与咳嗽反射）、化学屏障（皮肤脂肪酸与乳酸、胃酸 pH 1~2、泪液与唾液中的溶菌酶、阴道乳杆菌产生的乳酸）、微生物屏障（正常菌群的定植抵抗），以及体内的血脑屏障与胎盘屏障（保护中枢神经系统与胎儿）。屏障一旦破损（烧伤、创伤、留置导管）即成为感染门户，这解释了为什么院内感染多与侵入性操作相关。固有免疫不因再次接触同一病原体而增强，这是与适应性免疫最根本的差别。"},{"id":"25.2","t":"吞噬细胞的吞噬与杀灭","s":3,"c":"25. 宿主的免疫防御","x":"吞噬细胞包括中性粒细胞（急性炎症的主力）、单核—巨噬细胞（组织中的长期清道夫）与树突状细胞（专职抗原提呈）。吞噬过程分四步：趋化（沿补体 C5a、白三烯 B4 与细菌肽的浓度梯度移动）—识别与调理（直接识别PAMP，或经 IgG 的 Fc 段与 C3b 调理后识别，调理可显著提高吞噬效率）—吞入（伸出伪足包裹形成吞噬体，再与溶酶体融合为吞噬溶酶体）—杀灭与消化。杀灭机制分氧依赖与氧非依赖两类：氧依赖系统即呼吸爆发，NADPH 氧化酶产生超氧阴离子，再经超氧化物歧化酶与髓过氧化物酶生成 H₂O₂ 与次氯酸；氧非依赖系统包括溶菌酶、乳铁蛋白、防御素、蛋白酶与低 pH。慢性肉芽肿病患者因 NADPH 氧化酶缺陷而反复发生化脓性感染，正是这一机制的临床反证。"},{"id":"25.3","t":"炎症与体液免疫因子","s":2,"c":"25. 宿主的免疫防御","x":"炎症是固有免疫的重要表现形式，局部表现为红、肿、热、痛与功能障碍，其过程为血管扩张与通透性增加、血浆蛋白与白细胞渗出、吞噬与清除病原体、最后修复。介导炎症的分子包括组胺、前列腺素、白三烯以及细胞因子IL-1、IL-6 与 TNF-α（引起发热与急性期反应），还有急性期蛋白如 C 反应蛋白。体液中的抗微生物因子主要有：补体系统（经典途径由抗原抗体复合物激活、旁路途径由病原体表面直接激活、凝集素途径由甘露糖结合凝集素启动，最终形成膜攻击复合物 C5b-9 裂解细胞，C3b 兼具调理作用）、溶菌酶（水解肽聚糖）、防御素（阳离子抗菌肽，破坏膜）、干扰素与急性期蛋白。补体与吞噬细胞的协同是\"调理吞噬\"效率远高于直接吞噬的原因。"},{"id":"25.4","t":"NK 细胞与干扰素","s":3,"c":"25. 宿主的免疫防御","x":"自然杀伤（NK）细胞属固有免疫的淋巴细胞，其特点是不需抗原预先致敏、无 MHC 限制性、作用迅速，能直接杀伤病毒感染细胞与肿瘤细胞。其识别机制是\"缺失自我\"假说：NK 细胞表面同时具有活化受体与抑制性受体（识别MHC Ⅰ 类分子），当靶细胞 MHC Ⅰ 类分子表达下调（病毒感染的常见逃逸策略）时抑制信号减弱，杀伤被触发；NK 亦可通过 FcγRⅢ 介导 ADCC。干扰素分两型：Ⅰ 型（IFN-α/β）由病毒感染细胞产生，诱导邻近细胞合成 2'-5'寡腺苷酸合成酶与蛋白激酶 R，降解病毒 mRNA 并抑制翻译，形成\"抗病毒状态\"；Ⅱ 型（IFN-γ）由 Th1 与 NK 分泌，主要作用是激活巨噬细胞、增强MHC 表达，属免疫调节。"},{"id":"25.5","t":"抗原与抗体","s":3,"c":"25. 宿主的免疫防御","x":"抗原是能被 TCR 或 BCR 识别并诱导特异性免疫应答的物质，需兼具免疫原性与反应原性；只具反应原性而无免疫原性的小分子称半抗原，与蛋白载体结合后即成为完全抗原。抗原的免疫原性取决于分子量、化学组成复杂性、异物性以及进入途径，其与抗体结合的具体部位称抗原决定簇（表位）。抗体（免疫球蛋白）是 B 细胞分化为浆细胞后分泌的糖蛋白，基本结构为两条重链与两条轻链组成的 Y 形四肽链，分为可变区（决定特异性，构成抗原结合部位）与恒定区（决定类别与效应功能），木瓜蛋白酶水解得两个 Fab 与一个Fc，胃蛋白酶水解得 F(ab')₂ 与若干小片段。五类抗体功能各异：IgG 含量最高、是唯一能通过胎盘的抗体、再次应答的主力；IgM 分子量最大（五聚体）、初次应答最早出现、激活补体能力最强；IgA 以分泌型二聚体存在于黏膜表面与乳汁；IgE 含量最少、介导 I 型超敏反应；IgD 是 B 细胞成熟的表面标志。"},{"id":"25.6","t":"B 细胞与体液免疫","s":3,"c":"25. 宿主的免疫防御","x":"B 细胞以膜表面免疫球蛋白（BCR）识别天然抗原表位，其活化通常需要双信号：第一信号为抗原与 BCR 结合（胸腺依赖抗原还需 B 细胞内吞加工后以 MHC Ⅱ 类分子提呈给 Th 细胞），第二信号为 Th 细胞表面的 CD40L 与 B细胞 CD40 结合及细胞因子作用；胸腺非依赖抗原（如细菌多糖、脂多糖）可直接刺激 B 细胞产生以 IgM 为主的应答、不产生记忆。活化后的 B 细胞在生发中心经历增殖、体细胞高频突变与类别转换（IgM→IgG/IgA/IgE），亲和力逐轮提高，最终分化为分泌抗体的浆细胞与长寿的记忆 B 细胞。抗体的效应功能包括中和毒素与病毒、调理吞噬、激活补体经典途径、介导 ADCC 以及黏膜免疫（分泌型 IgA）。"},{"id":"25.7","t":"T 细胞、MHC 与细胞免疫","s":3,"c":"25. 宿主的免疫防御","x":"T 细胞不能识别游离抗原，只能识别由 MHC 分子提呈的抗原肽，这一限制称 MHC 限制性。MHC Ⅰ 类分子表达于所有有核细胞表面，提呈内源性（胞内合成的，如病毒蛋白）抗原肽给 CD8⁺ T 细胞；MHC Ⅱ 类分子主要表达于专职抗原提呈细胞（树突状细胞、巨噬细胞、B 细胞），提呈外源性抗原肽给 CD4⁺ T 细胞。CD4⁺ Th 细胞按分泌的细胞因子分化为 Th1（分泌 IFNγ，激活巨噬细胞，主导抗胞内菌与迟发型超敏）、Th2（分泌 IL-4、IL-5，辅助 B 细胞与抗寄生虫）、Th17（分泌 IL-17，招募中性粒细胞）与 Treg（抑制免疫，维持耐受）。CD8⁺ 细胞毒性 T 细胞（CTL）经穿孔素与颗粒酶、或经 Fas-FasL 途径诱导靶细胞凋亡。细胞免疫主要针对胞内寄生病原（结核、李斯特菌、病毒）与肿瘤，其效应可通过致敏 T 细胞转移而不能通过血清转移，这是与体液免疫鉴别的关键实验依据。"},{"id":"25.8","t":"免疫记忆与克隆选择","s":3,"c":"25. 宿主的免疫防御","x":"克隆选择学说（Burnet）认为机体预先存在大量特异性不同的淋巴细胞克隆，抗原进入后选择性地与相应克隆结合并使其活化、增殖、分化，而非抗原\"教导\"细胞产生抗体。免疫记忆是适应性免疫的标志：初次应答潜伏期长（数天至数周）、以 IgM 为主、效价低、维持时间短；再次应答潜伏期短（1~3 天）、以 IgG 为主、效价高数十至数百倍、维持数年甚至终身，原因是记忆细胞数量大且再激活阈值低。这一差异是疫苗加强免疫的理论基础，也是血清学诊断中\"检测 IgG 提示既往感染或恢复期、检测 IgM 提示近期感染\"的依据。此外，免疫系统通过胸腺的阴性选择清除自身反应性 T 细胞、通过外周耐受机制维持自身耐受，其失效则导致自身免疫病。"},{"id":"25.9","t":"超敏反应的四型","s":3,"c":"25. 宿主的免疫防御","x":"Ⅰ 型（速发型）由 IgE 介导：变应原交联肥大细胞与嗜碱性粒细胞表面的IgE，使其脱颗粒释放组胺、白三烯，引起过敏性鼻炎、哮喘、荨麻疹与过敏性休克，发生快（数分钟内），可用肾上腺素急救。Ⅱ 型（细胞毒型）由 IgG或 IgM 与靶细胞表面抗原结合后激活补体或招募效应细胞，导致细胞溶解，如ABO 血型不合的输血反应、新生儿溶血病、药物性溶血性贫血。Ⅲ 型（免疫复合物型）由中等大小可溶性免疫复合物沉积于血管壁与肾小球、激活补体并招募中性粒细胞引起炎症，如血清病、链球菌感染后肾小球肾炎、系统性红斑狼疮。Ⅳ 型（迟发型）由致敏 T 细胞介导，无抗体参与，发生慢（48~72 h），如结核菌素试验、接触性皮炎、移植排斥与部分药物疹。四型的判别要点是\"由什么介导、多快发生、能否用血清转移\"。"},{"id":"25.10","t":"免疫学的实际应用","s":2,"c":"25. 宿主的免疫防御","x":"免疫预防方面，疫苗类型包括灭活疫苗、减毒活疫苗（免疫原性强但需注意返祖风险）、亚单位与重组蛋白疫苗、类毒素（白喉、破伤风）、多糖与多糖结合疫苗、病毒载体疫苗与 mRNA 疫苗；接种后通过模拟自然感染诱导记忆，实现群体免疫。免疫治疗方面，抗毒素与免疫球蛋白用于被动免疫（如破伤风抗毒素、狂犬病免疫球蛋白），单克隆抗体（杂交瘤技术或噬菌体展示制备）用于肿瘤与自身免疫病靶向治疗。免疫诊断方面，ELISA（间接法测抗体、双抗体夹心法测抗原）、免疫荧光、凝集与沉淀试验、免疫层析试纸条（快速检测）以及 Western blot（确证）是微生物学检验的常规手段，其灵敏度依赖抗原抗体反应的特异性与信号放大系统。第九篇 微生物分类与鉴定分类篇的命题重心是\"用什么指标、在什么水平上做鉴定\"。要牢牢把握三个层次：表型（形态、染色、生化、血清学）用于常规鉴定；分子（16S rRNA、ITS、ANI）用于确定系统发育地位；基因组（全基因组、MLST）用于溯源与精细分型。伯杰氏手册的名称与用途、三域系统的提出者与依据，是最基础的两个记点。"},{"id":"26.1","t":"分类阶元与命名","s":3,"c":"26. 分类与鉴定","x":"微生物分类阶元自上而下为域、门、纲、目、科、属、种，种是分类的基本单位，种下可有亚种、变种、菌株、型与血清型等。原核生物的\"种\"是操作性定义：通常以 16S rRNA 基因序列相似性 ≥98.7%、DNA-DNA 杂交同源性≥70%、平均核苷酸一致性（ANI）≥95%~96% 作为同种的界定标准。命名采用林奈双名法：属名首字母大写、种加词全小写、整体排斜体，如Escherichia coli（大肠杆菌），文中再次出现可缩写为 E. coli；种名之后可附菌株号（如 E. coli K12）。国际细菌命名法规由国际原核生物系统学委员会维护，模式菌株（type strain）是名称的实物依据。"},{"id":"26.2","t":"三域系统与主要类群","s":3,"c":"26. 分类与鉴定","x":"Woese 依据 16S rRNA 序列把细胞生物分为细菌域、古菌域与真核生物域，三者在系统树上地位平等，古菌与真核生物亲缘关系更近。细菌域已知有数十个门，与人类关系密切的包括变形菌门（大肠杆菌、根瘤菌、假单胞菌、弧菌）、厚壁菌门（芽孢杆菌、梭菌、乳酸菌、葡萄球菌）、放线菌门（链霉菌、分枝杆菌、双歧杆菌）、拟杆菌门（肠道优势菌）、蓝细菌门、螺旋体门与衣原体门。古菌域主要包括广古菌门（产甲烷菌、极端嗜盐菌）、奇古菌门（含海洋氨氧化古菌）与阿斯加德古菌门（与真核生物起源相关）。真核生物域中的微生物包括真菌、原生动物与藻类。掌握\"门—代表属—代表特征\"的对应关系即可应对多数选择题。"},{"id":"26.3","t":"伯杰氏手册","s":2,"c":"26. 分类与鉴定","x":"《伯杰氏鉴定细菌学手册》以表型特征（形态、染色、生理生化、生态）为依据提供检索与鉴定路径，是实验鉴定的经典工具书；《伯杰氏系统细菌学手册》按系统发育关系编排，内容为各类群的详尽描述；目前二者已整合为在线的《伯杰氏古菌与细菌系统学手册》。两本手册的分工是常考点：鉴定手册回答\"这个菌是什么\"，按实用特征编排；系统学手册回答\"这个菌在进化上属于谁\"，按亲缘关系编排。使用时应先查系统学手册确定归属，再用鉴定手册的特征表逐项核对。"},{"id":"26.4","t":"经典鉴定方法","s":3,"c":"26. 分类与鉴定","x":"经典鉴定依赖四类特征：形态学（菌体形状、大小、排列、有无芽孢与荚膜、鞭毛数目与位置、菌落形态与色素、在半固体培养基中的运动性）；染色反应（革兰染色、抗酸染色、芽孢染色、荚膜染色、鞭毛染色）；生理生化反应（糖发酵与产气、氧化酶、过氧化氢酶、尿素酶、明胶液化、吲哚、硫化氢、柠檬酸盐利用、硝酸盐还原，其中 IMViC 试验即吲哚、甲基红、VP、柠檬酸盐利用四项，用于区分大肠杆菌与产气肠杆菌）；血清学与分型（凝集试验确定 O、H、K 抗原，噬菌体分型、细菌素分型）以及药敏谱。这一套方法虽然耗时，但至今仍是临床与食品检验的基础，因为其成本低、结果可判读、且与表型直接对应。"},{"id":"26.5","t":"分子鉴定与系统发育分析","s":3,"c":"26. 分类与鉴定","x":"分子鉴定的核心是选择合适标记：细菌用 16S rRNA 基因（约 1.5 kb，含保守区与可变区，通用引物可扩增几乎全部细菌）、真菌用 18S rRNA 基因与ITS 区（ITS 变异更快，是种级鉴定的首选）、部分类群用 rpoB、gyrB、recA 等持家基因；分型与溯源用 MLST（多位点序列分型）与全基因组单核苷酸多态性。系统发育树通过多序列比对与邻接法、最大似然法构建，bootstrap 值反映分支的可靠性。16S 的局限必须知道：多数细菌含多拷贝且拷贝间有差异、对近缘种（如大肠杆菌与志贺氏菌）分辨率不足、无法反映基因组的全部信息，因此现代分类主张\"多相分类\"，即综合表型、化学组分（脂肪酸、醌、极性脂）与基因型数据。"},{"id":"26.6","t":"快速检测技术","s":2,"c":"26. 分类与鉴定","x":"PCR 通过特异性引物扩增目标基因，可检出极少量病原；qPCR（实时荧光定量）以 Ct 值与标准曲线定量，并能区分病原载量；多重 PCR 一次检测多个靶标；LAMP 在恒温下扩增，适合现场与基层。MALDI-TOF 质谱把完整菌体的蛋白指纹与数据库比对，几分钟内完成鉴定，已成为临床实验室的主力方法，但对数据库未收录的种与近缘种分辨有限。高通量测序与纳米孔测序可实现未知病原的宏基因组检测（mNGS），在疫情溯源与新发病原识别中价值突出。免疫学快速检测（免疫层析试纸条、ELISA、免疫荧光）则以抗原抗体反应为基础，兼有速度快与成本低的优势。答题时应把方法与\"检测对象（核酸/蛋白/代谢物）\"对应起来。鉴定层次常用指标可分辨水平典型用途形态与染色菌体形态、革兰染色、芽孢、荚膜属或类群初步分群、教学与常规检验生理生化糖发酵、IMViC、酶活性种临床与食品微生物鉴定血清学O、H、K 抗原凝集血清型、株流行病学溯源、沙门氏菌分型分子标记16S rRNA、ITS、rpoB属至种系统发育与种级鉴定基因组ANI、dDDH、MLST、全基因组种与株新种界定、暴发溯源质谱蛋白指纹图谱种临床快速鉴定第十篇 应用微生物学应用篇的分值不高但易得分，命题多为\"某产品由什么菌生产\"\"某工艺的原理是什么\"。复习策略是建立\"产品—菌种—代谢途径—工艺要点\"的四元组，重点关注抗生素、氨基酸、有机酸、酶制剂、单细胞蛋白与食品发酵，并记住Bt、根瘤菌、沼气、活性污泥这几个高频实例。"},{"id":"27.1","t":"发酵方式与工艺","s":3,"c":"27. 工业发酵与食品微生物","x":"工业发酵按操作方式分：分批发酵（一次投料、一次收获，操作简单但存在底物抑制与产物反馈）、补料分批发酵（中途流加营养，解除底物抑制、延长产物合成期，是青霉素与谷氨酸生产的主流）、连续发酵（恒化器原理，效率高但易污染与菌种退化）以及固态发酵（以麸皮、秸秆等固体基质培养，适合霉菌产酶与传统酿造）。按是否需要氧分好氧发酵（抗生素、氨基酸、有机酸）与厌氧发酵（酒精、丙酮丁醇、乳酸）。工艺控制的关键参数是温度、pH、溶氧、搅拌、泡沫与补料速率；菌种要求是遗传稳定、生长快、营养要求粗放、产率高且不产毒。发酵动力学上要区分生长关联型产物（如乙醇、乳酸）与非生长关联型产物（如抗生素、次级代谢产物，主要在稳定期形成）。"},{"id":"27.2","t":"抗生素工业","s":3,"c":"27. 工业发酵与食品微生物","x":"抗生素是微生物在代谢中产生的、低浓度即可抑制或杀灭其他微生物的次级代谢产物，工业上主要来自放线菌（链霉菌属，如链霉素、四环素、红霉素）、真菌（产黄青霉产青霉素、顶头孢霉产头孢菌素）与细菌（芽孢杆菌产多黏菌素、杆菌肽）。生产流程为：菌种选育（诱变与筛选、代谢工程）—种子扩大培养—发酵（补料、控制 pH 与溶氧、添加前体如苯乙酸以提高青霉素G 比例）—提取纯化（溶剂萃取、离子交换、结晶）—效价测定。青霉素发酵的关键在于半合成改造（6-APA 母核）以获得耐酸、耐酶、广谱的衍生物。抗生素的过量使用与耐药性问题已在第五篇讨论，此处应把\"工业生产\"与\"合理使用\"两条线索连起来看。"},{"id":"27.3","t":"氨基酸与有机酸发酵","s":3,"c":"27. 工业发酵与食品微生物","x":"谷氨酸发酵以谷氨酸棒杆菌为菌种，关键控制点是生物素亚适量（使细胞膜磷脂合成不足、膜通透性增大，谷氨酸得以大量排出）以及适时供氧与 pH控制，产物即味精的主要成分。赖氨酸发酵利用高丝氨酸缺陷型菌株切断分支途径，使天冬氨酸半醛的代谢流全部导向赖氨酸，这是\"解除反馈抑制与切断分支\"的经典育种思路。柠檬酸发酵用黑曲霉，需高糖、低 pH（pH<2 抑制草酸生成）、充分供氧与微量铁的限制。乳酸发酵用乳酸菌或根霉，分为同型与异型。此外，丙酮丁醇发酵（ABE 工艺）、丁酸发酵与维生素 C 的两步发酵法（由葡萄糖经醋酸菌与棒状杆菌两步转化）都是竞赛常见的实例。判断\"某产物为何能大量积累\"，答案往往落在膜通透性、反馈抑制解除与分支途径切断三点上。"},{"id":"27.4","t":"酶制剂、维生素与单细胞蛋白","s":2,"c":"27. 工业发酵与食品微生物","x":"工业酶制剂主要来自微生物：α-淀粉酶由地衣芽孢杆菌、黑曲霉生产，用于淀粉糖化与洗涤剂；糖化酶由黑曲霉与根霉生产；纤维素酶由木霉生产；蛋白酶由芽孢杆菌与曲霉生产；果胶酶、脂肪酶、乳糖酶与葡萄糖异构酶（生产高果糖浆）也各有产生菌。维生素方面，维生素 B2 由阿舒假囊酵母或枯草芽孢杆菌生产，维生素 B12 由谢氏丙酸杆菌或假单胞菌生产，维生素 C 用两步发酵法。单细胞蛋白指以微生物菌体作为蛋白来源，可利用甲醇、甲烷、糖蜜甚至废弃物培养酵母或细菌，其优点是蛋白含量高、增殖快、不占耕地，限制因素是核酸含量高与生产成本。"},{"id":"27.5","t":"食品发酵","s":2,"c":"27. 工业发酵与食品微生物","x":"发酵食品按主要微生物分：细菌发酵（酸奶与泡菜由乳酸菌、纳豆由枯草芽孢杆菌、醋由醋酸菌）、酵母发酵（啤酒、葡萄酒、面包、清酒）与霉菌发酵（酱油与酱由米曲霉制曲后经酵母与乳酸菌共同发酵、腐乳由毛霉或根霉、豆豉）。传统酿造的共同原理是\"多菌种混合发酵\"：霉菌先把淀粉与蛋白质水解为糖与氨基酸，酵母再把糖转为乙醇与酯类风味物质，乳酸菌产酸抑制杂菌并形成风味，因此制曲（扩大培养霉菌）是风味与产量的关键。评价发酵食品的两个基本指标是微生物的安全性（无致病菌与毒素）与风味物质的形成，后者取决于菌种、温度、盐度与发酵时间。"},{"id":"27.6","t":"食品腐败与保藏","s":3,"c":"27. 工业发酵与食品微生物","x":"食品腐败是微生物分解食品中的蛋白质、脂肪与糖，产生胺、硫化氢、脂肪酸败与黏液等现象，主要由细菌（假单胞菌、芽孢杆菌、乳酸菌）、酵母与霉菌引起，其种类取决于食品的 aw、pH、氧、温度与营养组成。保藏原理都是控制微生物生长条件：低温冷藏（抑制而不灭菌）、冷冻（−18℃ 以下，抑制微生物与水活度）、加热灭菌与巴氏消毒、干燥与加盐加糖降低 aw、酸化（pH<4.5 抑制多数细菌）、真空与充气包装（改变氧分压，充氮或二氧化碳抑制需氧菌）、辐照、添加防腐剂（山梨酸钾、苯甲酸钠、乳酸链球菌素）。要特别注意：冷藏只能延缓而不能阻止嗜冷菌（如李斯特菌）生长，因此即食冷藏食品仍有风险。"},{"id":"28.1","t":"生物肥料","s":2,"c":"28. 农业、环境与极端微生物","x":"生物肥料是以活体微生物制剂的形式提供或活化养分的产品，其作用机制包括固氮（根瘤菌、自生固氮菌）、溶磷解钾（假单胞菌、芽孢杆菌分泌有机酸或质子溶解磷酸钙与钾长石）、促进根系吸收（菌根真菌扩大吸收面积）、产生植物激素与抗病（PGPR 分泌吲哚乙酸、铁载体与抗生素）。与化学肥料相比，生物肥料的优点是环境友好、改善土壤结构、提高肥料利用率，缺点是效果受土壤条件与菌株定植能力影响大、稳定性差。使用时须注意菌剂的活菌数、施用时机（避免与杀菌剂同时使用）与土壤水分温度条件。"},{"id":"28.2","t":"生物农药与 Bt","s":3,"c":"28. 农业、环境与极端微生物","x":"苏云金芽孢杆菌（Bt）在芽孢形成时产生伴胞晶体（δ-内毒素，由 cry 基因编码），被敏感昆虫（鳞翅目、双翅目、鞘翅目幼虫）取食后在中肠碱性环境下溶解，被蛋白酶水解为活性毒素片段，与中肠上皮细胞受体结合形成孔道，导致细胞裂解与昆虫死亡。Bt 的优点是对靶标专一、对人畜与天敌安全、无残留；局限是田间持效期短、紫外易降解、杀虫谱窄，因此发展出转 cry 基因的抗虫作物（如 Bt 棉花、Bt 玉米）。其他生物农药包括白僵菌与绿僵菌（真菌杀虫剂）、核多角体病毒（昆虫病毒杀虫剂）、农用抗生素（井冈霉素、春雷霉素）与木霉、荧光假单胞菌等生防菌。生物农药的推广本质是用生态关系替代化学毒杀。"},{"id":"28.3","t":"污水处理中的微生物","s":3,"c":"28. 农业、环境与极端微生物","x":"好氧处理以活性污泥法为代表：污水与含大量细菌、原生动物的活性污泥混合曝气，有机污染物被吸附与氧化分解为 CO₂ 与 H₂O，同时形成菌胶团，随后在二沉池中泥水分离，部分污泥回流。其微生物学指标是污泥的沉降性（SVI）、菌胶团形成与指示生物（钟虫、轮虫出现说明水质良好；丝状菌大量繁殖则发生污泥膨胀）。厌氧处理（厌氧消化、UASB）通过水解—产酸—产氢产乙酸—产甲烷四阶段把有机物转为 CH₄ 与 CO₂，适用于高浓度有机废水，优点是能耗低、产能源、污泥少。此外还有生物膜法（滴滤池、生物转盘、曝气生物滤池）与人工湿地。脱氮除磷依靠硝化—反硝化与厌氧释磷—好氧吸磷的聚磷菌工艺（A²/O）。"},{"id":"28.4","t":"沼气发酵与能源微生物","s":2,"c":"28. 农业、环境与极端微生物","x":"沼气发酵是在严格厌氧条件下由多种微生物协同完成的四阶段过程：水解发酵菌把大分子有机物水解并发酵为有机酸与醇；产氢产乙酸菌把丙酸、丁酸等转为乙酸、H₂ 与 CO₂；同型产乙酸菌生成乙酸；产甲烷古菌以乙酸（约占2/3）或 H₂/CO₂ 生成 CH₄。产甲烷菌生长慢、对氧与温度极其敏感，因此工艺上须保证密封、稳定温度（中温 35℃ 或高温 55℃）与适宜碳氮比。沼气的意义在于同时实现废弃物处理与能源回收，沼渣沼液还可用作肥料。此外，产氢发酵、微生物燃料电池与光合产氢是微生物能源研究的方向，甲烷氧化菌与产电菌（Geobacter）也是研究热点。"},{"id":"28.5","t":"极端微生物与资源开发","s":2,"c":"28. 农业、环境与极端微生物","x":"极端微生物按生境分嗜热、嗜冷、嗜盐、嗜酸、嗜碱、嗜压与嗜辐射等类群，主要分布在古菌与特殊细菌中。其资源价值体现在三方面：酶制剂（Taq、Pfu DNA 聚合酶来自嗜热水生菌与激烈火球菌，是 PCR 的关键；嗜冷酶用于低温洗涤与食品加工；嗜碱酶用于洗涤剂；嗜压酶用于高压合成）；特殊代谢产物（嗜盐菌的细菌视紫红质用于光存储与生物电池、极端菌的多糖与色素）；以及基础研究价值（耐热机制、膜脂结构、生命极限与地外生命探索）。开发策略包括原位富集培养、非培养法获取基因（宏基因组文库）、以及把极端酶基因转入常规宿主表达。"},{"id":"28.6","t":"微生物制药与生物技术产品","s":2,"c":"28. 农业、环境与极端微生物","x":"现代微生物制药以基因工程为核心：人胰岛素、人生长激素、干扰素、白细胞介素、促红细胞生成素、乙肝疫苗（重组 HBsAg）与 HPV 疫苗（重组 L1蛋白形成病毒样颗粒）都通过工程菌或工程细胞生产；单克隆抗体（如抗TNF-α、抗 PD-1）由哺乳动物细胞表达。其他产品包括维生素、氨基酸、有机酸、多糖（黄原胶、透明质酸、右旋糖酐）、生物可降解塑料（PHB）、生物表面活性剂与生物农药。基因工程药物相比传统提取法的优势是产量高、成本低、无动物病原污染风险。产业上还需注意基因工程菌的环境释放安全性与生物安全评价，这属于标准的科技伦理与安全考点。第十一篇 备考：辨析、速查与复习路线本篇是全书的使用性收口。辨析表的作用是\"排雷\"：凡是两个概念容易混淆的地方，都是命题者乐意设置的陷阱。速查表用于考前一周的最后回顾。复习路线则给出可执行的时间安排。建议的使用顺序是：先按前九篇顺序精读并自测，再用辨析表逐条自查，最后用速查表做限时回忆训练。"},{"id":"29.1","t":"结构与染色类辨析","s":3,"c":"29. 高频易错辨析","x":"本组辨析集中解决\"结构名称与功能对应错误\"\"革兰染色机制误述\"两类问题。判断革兰染色结果的关键不是\"细胞壁厚薄\"本身，而是\"脂质含量决定乙醇脱色程度\"这一因果链；判断细胞壁有无的关键则要区分\"天然缺壁\"与\"人工去壁\"。序号常见错误表述正确理解革兰阴性菌呈紫色革兰阴性菌肽聚糖薄、外膜含脂质，乙醇脱色后经番红复染呈红色；阳性菌呈紫色革兰阳性菌细胞壁厚所以染成紫色直接原因是肽聚糖层厚、交联致密，脱水后孔径缩小，结晶紫-碘复合物被阻留；脂质含量低也使脱色困难所有细菌都有细胞壁支原体天然无细胞壁；L 型细菌、原生质体与球状体为缺壁或去壁形式支原体属于病毒支原体有细胞结构、能独立生长繁殖，是能独立生活的最小生物；病毒无细胞结构内毒素是革兰阳性菌产生的内毒素是革兰阴性菌外膜的脂多糖，活性中心为类脂 A；革兰阳性菌主要产外毒素荚膜是细菌生存必需结构荚膜是毒力因子，失去后细菌仍可存活但毒力下降"},{"id":"29.2","t":"生长、灭菌与培养类辨析","s":3,"c":"29. 高频易错辨析","x":"本组辨析针对\"灭菌与消毒混用\"\"高压蒸汽温度记错\"\"选择与鉴别培养基不分\"三类高频错误。凡涉及\"能否杀死芽孢\"的判断，都要落到灭菌与消毒的分界线；凡涉及\"培养基用途\"的判断，都要问\"是抑制生长还是显示差异\"。常见错误表述正确理解序号高压蒸汽灭菌条件是 100℃、15 min常规为 121℃、15~20 min（表压约 0.1 MPa）；100℃ 煮沸只能消毒煮沸 10 min 即可灭菌煮沸只能杀死营养细胞，芽孢仍存活，属消毒紫外灯照射可以灭菌紫外穿透力极弱，只能做表面与空气消毒，且损伤可被光复活修复选择培养基就是鉴别培养基选择培养基靠抑制或限制非目标菌生长；鉴别培养基靠指示剂显示菌落差异，二者常配合使用平板上长出的菌落数就是活菌数相连细胞只形成一个菌落，平板计数结果通常低于实际活菌数，故以CFU 表示芽孢是细菌的繁殖方式芽孢是休眠体，一个细胞形成一个芽孢、一个芽孢萌发成一个细胞，数目不增加，不是繁殖延滞期细菌对抗生素最敏感延滞期代谢与分裂不活跃，对作用于细胞壁合成的青霉素不敏感；对数期最敏感低温可以杀死微生物低温只抑制代谢，菌种保藏即利用这一点；冷冻可长期保存活菌"},{"id":"29.3","t":"遗传与基因工程类辨析","s":3,"c":"29. 高频易错辨析","x":"本组辨析针对\"三种基因转移方式混淆\"\"作图原理记反\"两类问题。判断转移方式只需要问三个问题：有无细胞接触、有无噬菌体、有无感受态；判断作图原理则只需确认\"时间与距离成正比\"还是\"频率与距离成正比\"。序号常见错误表述正确理解转化需要细胞接触转化是摄取游离 DNA，不需接触；接合才必须有细胞间直接接触F+ × F− 后受体成为 Hfr受体只获得 F 因子而成为 F+；Hfr 是 F 因子整合到染色体上的供体菌株接合时供体染色体完整转移转导可转移任意大小片段Hfr 转移时 F 因子被断开，染色体常不能完整转移，故受体多为F−受衣壳容量限制（P1 约 90~100 kb），只能转移小片段共转导频率越低说明两基因越近频率越高说明距离越近；中断杂交才是\"时间（分钟）即距离\"诱变剂使细菌产生定向的有益突变突变是随机无定向的，诱变只提高频率，选择才决定方向质粒是细菌生存必需的结构质粒非必需，但可赋予抗性、毒力、降解等有利性状，且可丢失感受态是细菌与生俱来的永久状态感受态由感受态因子诱导、多见于对数期后期，是暂时的生理状态"},{"id":"29.4","t":"病毒与亚病毒类辨析","s":3,"c":"29. 高频易错辨析","x":"本组辨析针对\"病毒与非细胞因子混淆\"\"包膜与耐药性关系不清\"两类问题。牢记一条判据：有无核酸、有无衣壳、能否独立复制。朊病毒无核酸，类病毒无衣壳，二者都不同于病毒。序号常见错误表述正确理解病毒是最小的微生物病毒无细胞结构，属非细胞生物，一般不称\"微生物\"；支原体才是最小的细胞生物病毒同时含有 DNA 和 RNA一种病毒只含一种核酸；同一种病毒的颗粒内不会同时以两者作遗传物质朊病毒是一种小 RNA 病毒朊病毒只由蛋白质构成，不含核酸，其\"信息\"存于 PrPSc 的构象中类病毒有蛋白衣壳类病毒仅为环状单链 RNA，无衣壳、不编码蛋白，只感染植物有包膜病毒抵抗力更强包膜含脂质，对脂溶剂、去污剂敏感，抵抗力较弱；无包膜病毒抵抗力更强溶原性细菌一定会被裂解溶原菌可正常生长繁殖并把噬菌体基因传给子代，仅在诱导时才进入裂解循环溶原转换与转导是同一概念溶原转换是原噬菌体基因使宿主获得新性状；转导是噬菌体把宿主DNA 转移给另一宿主病毒能在人工培养基上生长病毒必须用活细胞（鸡胚、细胞培养、敏感动物）培养，不能在无生命培养基上增殖"},{"id":"29.5","t":"生态、营养与代谢类辨析","s":3,"c":"29. 高频易错辨析","x":"本组辨析针对\"营养类型划分依据不清\"\"循环过程与细菌类群错配\"两类问题。判断营养类型先看碳源再看能源；判断循环过程先确认\"是氧化还是还原、产物是什么\"。序号常见错误表述正确理解化能自养菌以有机物为碳源化能自养菌氧化无机物获能、以CO₂ 为唯一碳源，如硝化细菌、硫细菌硝化细菌进行反硝化作用硝化细菌把 NH₄⁺ 氧化为 NO₃⁻（化能自养）；反硝化细菌以NO₃⁻ 为电子受体还原为 N₂（多为化能异养）固氮作用不消耗能量固氮酶催化 N₂ 还原需 16 ATP 并必然放氢，是极耗能的过程专性厌氧菌只是\"不喜欢\"氧专性厌氧菌缺乏超氧化物歧化酶与过氧化氢酶，氧的代谢产物对其有毒，属绝对不耐氧70% 乙醇与 95% 乙醇效果相同70%~75% 乙醇杀菌效果最好；95% 使表面蛋白迅速凝固形成保护膜，反而降低效果大肠菌群是致病菌大肠菌群是粪便污染指示菌，其存在提示可能有肠道病原体，本身多为条件致病菌"},{"id":"29.6","t":"感染与免疫类辨析","s":3,"c":"29. 高频易错辨析","x":"本组辨析针对\"内毒素与外毒素错配\"\"四型超敏反应错判\"两类问题。判断超敏反应类型只需回答三个问题：由 IgE 还是 IgG/IgM 还是 T 细胞介导、发生快慢、能否用血清被动转移。常见错误表述正确理解序号内毒素可用甲醛脱毒制成类毒素内毒素为脂多糖、热稳定、抗原性弱，不能制成类毒素；外毒素可以结核菌素试验属 Ⅰ 型超敏反应属 Ⅳ 型迟发型超敏反应，由致敏T 细胞介导，48~72 h 出现硬结青霉素过敏性休克属 Ⅱ 型超敏反应属 Ⅰ 型 IgE 介导的速发型超敏反应；Ⅱ 型是抗体介导的细胞毒型抗体可以直接杀死胞内细菌抗体无法进入细胞，胞内菌主要靠细胞免疫（Th1 激活巨噬细胞、CTL 杀伤）清除NK 细胞杀伤具有 MHC 限制性NK 细胞无 MHC 限制、不需预先致敏；CTL 才有 MHC Ⅰ 类限制性再次应答以 IgM 为主再次应答以 IgG 为主、潜伏期短、效价高；初次应答以 IgM 为主"},{"id":"30.1","t":"原核微生物与真核微生物对比","s":3,"c":"30. 速查表","x":"本表用于快速区分两大类群的细胞学特征，重点在\"有无核膜与细胞器\"\"细胞壁成分\"\"核糖体大小\"\"有无有丝分裂\"。凡遇到\"某结构是否存在\"的判断，先确定类群再回答。比较项原核微生物真核微生物核膜与核仁无，只有核区有真正的细胞核染色体通常一条环状 DNA，无组蛋白多条线状 DNA，与组蛋白结合细胞器无线粒体、叶绿体、内质网、高尔基体有完整细胞器系统核糖体70S（50S + 30S）80S（60S + 40S）细胞壁多数含肽聚糖（古菌除外）几丁质（真菌）或纤维素（藻类），无肽聚糖细胞膜甾醇一般无（支原体例外）常含麦角甾醇或胆固醇分裂方式二分裂，无有丝分裂0.2~10 μm有丝分裂、减数分裂大小2 μm 至数米（菌丝、子实体）"},{"id":"30.2","t":"细胞壁与特殊结构对比","s":3,"c":"30. 速查表","x":"本表把细菌细胞壁、缺壁类型与特殊外部结构放在一起，便于记忆\"谁有谁无\"。考试中常见的组合问法是\"某菌对青霉素是否敏感\"\"某菌能否被溶菌酶破坏\"，答案都由细胞壁成分决定。对象主要成分关键特征对青霉素或溶菌酶的反应革兰阳性菌厚肽聚糖 + 磷壁酸肽桥为五甘氨酸，无外膜对青霉素与溶菌酶均敏感革兰阴性菌薄肽聚糖 + 外膜（LPS）含类脂 A、孔蛋白、周敏感性较低，外膜阻碍质空间药物进入分枝杆菌肽聚糖 + 大量脂质（分枝菌酸）抗酸染色阳性，革兰染色难着色对溶菌酶抵抗，需抗结核药物古菌假肽聚糖或 S 层无胞壁酸与 D-氨基酸，醚键膜脂对青霉素与溶菌酶天然不敏感支原体无细胞壁，膜含甾醇油煎蛋状菌落对青霉素天然耐药，对两性霉素敏感L 型细菌细胞壁缺陷高渗环境存活，可回复青霉素诱导形成，去除后可回复"},{"id":"30.3","t":"病毒分类速查","s":3,"c":"30. 速查表","x":"本表以核酸类型与有无包膜为轴，便于在选择题中快速定位。注意\"同一种病毒只含一种核酸\"这一铁律，凡选项同时给出 DNA 与 RNA 的，基本可判定为错误。核酸类型有无包膜代表病毒所致疾病或应用双链 DNA无腺病毒、T4 噬菌体腺病毒呼吸道感染、噬菌体研究双链 DNA有疱疹病毒、痘病毒单纯疱疹、水痘、天花单链 DNA无φX174、细小病毒 B19传染性红斑双链 RNA无呼肠孤病毒婴幼儿腹泻正单链 RNA无脊髓灰质炎病毒、甲肝病毒、TMV脊髓灰质炎、甲肝、植物花叶病正单链 RNA有SARS-CoV-2、登革病毒、风疹病毒新冠、登革热、风疹负单链 RNA有流感病毒、狂犬病病毒、埃博拉病毒流感、狂犬病、出血热逆转录型有HIV、乙型肝炎病毒艾滋病、乙型肝炎"},{"id":"30.4","t":"灭菌与消毒方法速查","s":3,"c":"30. 速查表","x":"本表按\"效果类别\"排序，最上面是能达到灭菌的，接着是只能消毒的，最后是不杀灭只去除的。遇到\"下列哪种方法能达到灭菌\"的题，只需核对是否具备\"杀死芽孢\"的条件。方法条件类别典型对象高压蒸汽121℃，15~20 min灭菌培养基、器械、废弃物干热160~170℃，2 h灭菌玻璃器皿、金属器械间歇灭菌100℃ 30 min，连续 3天灭菌不耐高压的培养基环氧乙烷常温气体灭菌一次性塑料器械煮沸100℃，5~10 min消毒餐具、器械初处理巴氏消毒62℃ 30 min 或 72℃ 15 s消毒牛奶、啤酒紫外线260 nm 照射表面消毒空气、工作台面70% 乙醇擦拭、浸泡消毒皮肤、器械表面过滤0.22 μm 滤膜除菌不杀灭血清、抗生素液、空气"},{"id":"30.5","t":"抗生素靶点速查","s":3,"c":"30. 速查表","x":"本表把药物、靶点、机制三者对齐，是\"为什么某药对某菌有效\"的答题依据。记忆技巧：作用于细胞壁的药物对革兰阳性菌更强（无外膜阻挡），作用于 30S 的主要影响读码，作用于 50S 的主要影响肽键与移位。靶点药物分子机制主要对象细胞壁青霉素、头孢菌素抑制转肽酶（PBP）交联革兰阳性菌为主细胞壁万古霉素结合 D-Ala-D-Ala，阻断聚合革兰阳性菌（含MRSA）细胞壁异烟肼抑制分枝菌酸合成结核分枝杆菌细胞膜多黏菌素 B与 LPS、膜磷脂结合成孔革兰阴性菌细胞膜两性霉素 B、制霉菌素结合麦角甾醇成孔真菌30S 亚基链霉素、卡那霉素致读码错误、抑制起始广谱，抗结核30S 亚基四环素阻断氨酰-tRNA 进入 A位广谱50S 亚基氯霉素、红霉素、克林霉素抑制肽键形成或移位广谱RNA 聚合酶利福平结合 β 亚基抑制转录结核、革兰阳性菌DNA 旋转酶喹诺酮类抑制拓扑异构酶Ⅱ广谱叶酸代谢磺胺类、甲氧苄啶双重阻断叶酸合成广谱"},{"id":"30.6","t":"免疫细胞与分子功能速查","s":3,"c":"30. 速查表","x":"本表用于\"哪种细胞负责什么\"的快速判断。核心区分是：固有免疫细胞反应快、无特异性、无记忆；适应性免疫细胞有特异性与记忆，且 T 细胞受MHC 限制。主要功能关键特征中性粒细胞细胞或分子固有免疫归属吞噬与杀灭细菌，急性炎症主力寿命短，含大量溶酶体酶巨噬细胞固有免疫吞噬、提呈抗原、分泌细胞因子可被 IFN-γ 激活树突状细胞固有免疫最强的专职抗原提呈细胞连接固有与适应性免疫NK 细胞固有免疫杀伤病毒感染细胞与肿瘤细胞无 MHC 限制，不需致敏B 细胞适应性免疫分化为浆细胞分泌抗体以 BCR 识别天然抗原浆细胞适应性免疫大量分泌特异性抗体不再分裂，寿命较短CD4⁺ Th 细胞适应性免疫分泌细胞因子辅助 B 细胞与巨噬细胞受 MHC Ⅱ 类限制CD8⁺ CTL适应性免疫杀伤感染细胞与肿瘤细胞受 MHC Ⅰ 类限制补体 C3b体液因子调理吞噬、参与 MAC 形成连接固有与适应性免疫抗体 IgG体液因子中和、调理、激活补体、过胎盘再次应答主力"},{"id":"30.7","t":"关键数字速记","s":3,"c":"30. 速查表","x":"本表集中收录全书中出现频率最高的数值，考前应能一次性默写。凡涉及单位的数字，务必连同单位一起记，因为命题常把\"20 min\"改成\"20 s\"或把\"121℃\"改成\"100℃\"来制造干扰。项目数值出处与要点大肠杆菌代时12.5~20 min最适条件下，理论每昼夜分裂 72次高压蒸汽灭菌121℃，15~20 min表压约 0.1 MPa，须排尽冷空气干热灭菌160~170℃，2 h玻璃器皿与金属器械巴氏消毒62℃ 30 min 或 72℃ 15 s 70%~75%牛奶、啤酒，不属灭菌约 260 nm 0.22 μm核酸吸收峰，形成嘧啶二聚体滤膜孔径细菌核糖体70S（50S + 30S）真核为 80S噬菌体一步生长曲线潜伏期约 20~30 min裂解量可达 100~200大肠杆菌基因组约 4.6 Mb，约 4300 基因环状双链 DNA原核生物同种标准16S ≥98.7%、ANI ≥95%多相分类综合判断人体细菌总数约 3.8×10¹³ 个与人体细胞数大致相当乙醇最适浓度紫外杀菌峰95% 效果反而差除菌，但不能截留病毒"},{"id":"31.1","t":"三轮复习法与时间分配","s":3,"c":"31. 复习路线与应试策略","x":"第一轮（约占 50% 时间）以本篇的篇、章为单元通读，目标是建立框架：能说出每一章的核心概念、结构名称与关键数据，能画出原核与真核细胞的结构对比草图。第二轮（约占 30%）以知识点为单位精读并做题，重点是数据、人名、机制因果链，尤其是细胞壁、芽孢、生长曲线、基因转移、免疫应答五个高频区。第三轮（约占 20%）只做三件事：用第 29 章的辨析表逐条自查、用第 30 章的速查表限时回忆、重做错题并整理错因。三轮之间应安排间隔重复，而不是连续突击同一内容。"},{"id":"31.2","t":"主线串联法","s":2,"c":"31. 复习路线与应试策略","x":"微生物学知识量大但线索清晰，建议用四条主线贯穿：结构线（由外到内的细胞结构→与染色、致病性、药物敏感性的关系）、能量线（营养类型→吸收方式→产能代谢→生长与产物形成）、信息线（染色体、质粒、突变、修复→转化、接合、转导→基因工程与育种）、关系线（分布→种间关系→物质循环→感染与免疫→应用）。任何一道综合题都可以落到其中一条主线上，找到主线就找到了答题的骨架。切忌按教材顺序死记，而应在每条主线上把分散的知识点重排一次。"},{"id":"31.3","t":"实验题的答题框架","s":3,"c":"31. 复习路线与应试策略","x":"微生物学实验题多见于联赛与国初，答题应按\"目的—原理—材料—步骤—结果—结论—讨论\"七要素组织。常见题型有三类：一是鉴别题（给未知菌，要求设计鉴定方案），答题思路是\"形态与染色初筛→生化反应定位→血清学或分子确证\"，并写明对照与重复；二是计数与生长题（要求测活菌数或求代时），答题要点是稀释梯度、平行样、30~300 个菌落的可计范围、以及对数期取样的理由；三是灭菌与无菌操作题，答题要点是明确\"灭菌还是消毒\"、说明为何选该方法（不耐热、需除芽孢、只能表面处理）、并指出关键操作（排尽冷空气、避免烫伤、火焰封口）。凡涉及对照实验，必须写出对照组设置与预期结果。"},{"id":"31.4","t":"高频失分点","s":3,"c":"31. 复习路线与应试策略","x":"第一类失分是概念边界模糊，如把灭菌与消毒、选择与鉴别、转化与接合混为一谈，这类错误源于只背定义未辨析。第二类是数据记错，如把 121℃ 记成 100℃、把 70% 乙醇记成 95%，命题者恰恰最爱在此设伏。第三类是因果颠倒，如把\"细胞壁厚\"直接当作革兰染色阳性的原因，而忽略了脱色机制这一中间环节。第四类是忽视了例外情形，如认为所有细菌都有细胞壁、所有病毒都有包膜、所有突变都有害。第五类是图表题读图不细，如把生长曲线中\"菌数的对数\"当成\"菌数\"读取，或把一步生长曲线的潜伏期与裂解期混淆。针对这五类问题，最有效的办法是把第 29 章的辨析表默写一遍。"},{"id":"31.5","t":"参考书使用与进度建议","s":1,"c":"31. 复习路线与应试策略","x":"主教材以沈萍、陈向东《微生物学》（第 8 版）为准，其结构与本纲要第二至第十篇对应最紧密；周德庆《微生物学教程》（第 3 版）篇幅精简、图表清晰，适合第一轮快速通读；需要英文术语与医学视角时查阅 Tortora 与Nester's，需要临床病原细节时查阅 Jawetz 与《医学微生物学》（八年制第 3版）。建议以\"一主一辅\"为原则：以沈萍本为精读主本，以周德庆本为复习提纲，其余作为查阅工具而非通读对象。每完成一篇即做一次自测，把错题标注在纲要对应知识点旁，形成个人化的薄弱点清单。"},{"id":"31.6","t":"常见题型与专项训练","s":2,"c":"31. 复习路线与应试策略","x":"竞赛中的微生物学题可分六类，各有应对方式。选择题常见三种设错手法：概念替换（把\"消毒\"换成\"灭菌\"）、数据篡改（121℃ 改 100℃）、例外抹平（称所有细菌都有细胞壁），应对办法是逐项核对而非凭印象。填空题重点在结构名与数值，答题时必须写规范术语，如\"肽聚糖\"不能写成\"黏肽层\"、\"磷壁酸\"不能写成\"磷壁质\"。判断题直接对照第 29 章的 42 条辨析。简答题要求要点式作答，先给结论再给依据，比较题用\"逐项对照\"结构（如内毒素与外毒素的六个维度）。实验设计题按\"目的—原理—材料—步骤—结果—结论\"七要素组织，并写明对照与重复。材料分析题考的是新情境迁移，遇到陌生物种或新技术时，先把它归入已知框架（结构、营养类型、代谢方式、生态位、传播途径），再调用相应知识作答。建议每周完成一次限时训练（40 道选择加 2 道简答），并把错题按\"概念边界、数据、因果、例外、读图\"五类归因。附录：知识库教材索引本纲要的体系编排与知识点表述，均以上述六部教材为依据进行核对与整合。凡涉及结构名称、数据数值与人物贡献的表述，均在教材中可查到出处；凡教材之间表述不完全一致处（如细菌 ATP 产量的计算口径、人体微生物细胞总数），已在正文中标注计算口径或\"估计\"性质，避免以单一数值作绝对结论。下表按\"在本纲要中的作用\"排列，而非按重要性排列，便于读者按需查阅。教材版次与出版信息在本纲要中的作用序号沈萍、陈向东主编《微生物学》第 8 版，高等教育出版社主教材，结构、生理、代谢、遗传、生态、分类的体系与术语基准第二至第十篇主要对应篇章周德庆编著《微生物学教程》第 3 版，高等教育出版社十大章体系与\"五大共性\"表述的参照，图表与小结宜作复习提纲第一至第六篇Tortora 等《Microbiology:An Introduction》14th ed.，Pearson，2023英文术语、教学框架与微生物与宿主相互作用部分的结构参照第二、三、八篇Nester's《Microbiology:A Human Perspective》10th ed.，McGraw Hill，以人体视角组织的病原与免疫内容，用于补充医学相关表述第八、十篇Jawetz, Melnick& Adelberg's《Medical Microbiology》29th ed.，McGraw Hill临床病原、耐药机制与实验室诊断的对照，用于校正医学细节第八、九、十篇《医学微生物学》（八年制临床医学专业教材）第 3 版，人民卫生出版社细菌、病毒、真菌致病性与检查方法的规范化表述第八、九篇使用本索引时应注意两点：其一，各教材的章节编号与本纲要的篇、章编号不对应，按主题词检索比按编号翻阅更有效；其二，教材版本更新会带来分类与命名的变化（如病毒分类随 ICTV 报告更新、原核生物高阶元随基因组数据修订），凡遇新旧表述并存，以最新版教材与专业委员会的规范名称为准，并在答题时说明依据。"}]
window.KG_BOOK["08"]=[{"id":"1.1","t":"内环境的概念","s":3,"c":"1. 内环境与稳态","x":"内环境即细胞外液，包括血浆、组织液、淋巴和脑脊液，是细胞直接生活的液体环境。按体重计，成年哺乳动物体液总量约占体重 60%，其中细胞内液约 40%、细胞外液约 20%（组织液约 15%、血浆约 5%，淋巴与跨细胞液少量）。内环境与细胞内液之间以细胞膜相隔，与外界之间以皮肤、黏膜、肺、肾等界面相隔。"},{"id":"1.2","t":"内环境的理化特性","s":3,"c":"1. 内环境与稳态","x":"血浆 pH 为 7.35~7.45，血浆渗透压约 300 mOsm/(kg·H₂O)（相当于 7 700 kPa，即 580 mmHg 左右），其中胶体渗透压仅约 1.5 mOsm，但对维持血容量起决定作用；血浆蛋白约 65~85 g/L，血糖 3.9~6.1 mmol/L，血浆 K⁺3.5~5.5 mmol/L、Na⁺ 135~145 mmol/L。细胞内液的特点是 K⁺ 高（约 140 mmol/L）、Na⁺ 低（约 10 mmol/L）、蛋白质多、pH 略低（7.0~7.2）。"},{"id":"1.3","t":"稳态及其维持","s":3,"c":"1. 内环境与稳态","x":"稳态（homeostasis）由 Cannon 于 1929 年提出，指内环境理化性质保持动态平衡的状态。稳态不是恒定不变，而是在调定点附近小幅波动，依靠负反馈控制回路维持；从分子（胞内 Ca²⁺ 约 100 nmol/L）、细胞、器官到整体各层次都存在稳态，因此稳态是生理学的核心概念。"},{"id":"1.4","t":"内环境稳定的生理意义","s":2,"c":"1. 内环境与稳态","x":"内环境的温度、pH、渗透压和离子浓度决定酶的活性、膜的通透性与细胞的兴奋性。失稳态即病理：酸中毒抑制心肌收缩力并降低儿茶酚胺反应性；高钾血症使骨骼肌和心肌静息电位绝对值减小、兴奋性先升后降并可引起心脏停搏；低钙血症降低阈电位与阈值的差距，引起手足搐搦。"},{"id":"1.5","t":"细胞内稳态与跨膜梯度","s":2,"c":"1. 内环境与稳态","x":"细胞内部同样需要稳态，最典型的是胞质 Ca²⁺ 稳态：胞外 Ca²⁺ 约 2 mmol/L，胞质游离 Ca²⁺ 仅约 100 nmol/L，跨膜梯度近万倍，由质膜 Ca²⁺ATP 酶（PMCA）与 Na⁺/Ca²⁺ 交换器（NCX）排出、由肌浆网/内质网SERCA 回收共同维持。胞内 pH、渗透压与细胞体积的调节（容积敏感性氯通道、Na⁺-K⁺-2Cl⁻ 同向转运）也是细胞稳态的内容。"},{"id":"1.6","t":"体液分布与水盐平衡的基本框架","s":2,"c":"1. 内环境与稳态","x":"体液在两区间交换遵循 Starling 力平衡：毛细血管处，毛细血管血压（动脉端约 30~35 mmHg）与组织液胶体渗透压促使滤过，血浆胶体渗透压（约25 mmHg）与组织液静水压（约 -3 mmHg）促使回流；约 90% 滤液在静脉端回流入血，其余 10% 经淋巴管回流，每日约 2~4 L。体液分区占体重比例主要离子特征备注细胞内液约 40% K⁺ 高、Na⁺ 低、蛋白质多占体液 2/3组织液约 15%与血浆相似、蛋白少经淋巴回流血浆约 5% Na⁺ 高、蛋白 65~85 g/L胶体渗透压 1.5 mOsm跨细胞液约 1%~2%脑脊液、消化液、关节液属细胞外液"},{"id":"2.1","t":"神经调节","s":3,"c":"2. 生命活动的调节方式","x":"神经调节的基本方式是反射，结构基础为反射弧，由感受器、传入神经、神经中枢、传出神经、效应器五个环节构成。其特点是快速、准确、短暂、定位明确，反应时间在毫秒至秒级，如减压反射、膝跳反射、眨眼反射。反射弧任一环节受损，反射即消失。"},{"id":"2.2","t":"体液调节","s":3,"c":"2. 生命活动的调节方式","x":"体液调节指化学物质经血液、淋巴或组织液运输而调节机体功能，主要执行者是内分泌腺和内分泌细胞分泌的激素，也包括 CO₂、H⁺、腺苷等代谢产物。特点是缓慢、广泛、持久，作用于秒至天级。按运输距离可分为内分泌（远距）、旁分泌（邻近）、自分泌（自身）和神经分泌（下丘脑肽能神经元将激素释放入血）。"},{"id":"2.3","t":"自身调节","s":3,"c":"2. 生命活动的调节方式","x":"自身调节指组织器官不依赖神经和体液，对局部刺激发生的适应性反应，范围局限、幅度较小。典型例子：肾血流量在动脉压 80~180 mmHg 范围内基本恒定（肌源性学说）；脑血流在灌注压 60~140 mmHg 内恒定；心肌的异长自身调节（Frank-Starling 定律）；血管平滑肌受牵张后收缩的肌源性反应。"},{"id":"2.4","t":"反馈调节","s":3,"c":"2. 生命活动的调节方式","x":"受控部分发出的信息反过来影响控制部分，称反馈。负反馈使输出向相反方向变化，是维持稳态的主要方式，如甲状腺激素对腺垂体 TSH 的负反馈、血糖升高引起胰岛素分泌。正反馈使输出进一步偏离，数量少但意义重大：分娩时子宫收缩刺激催产素释放、凝血过程、动作电位去极化时 Na⁺ 通道的再生性开放、排卵前雌激素对 LH 的正反馈峰。"},{"id":"2.5","t":"前馈调节","s":2,"c":"2. 生命活动的调节方式","x":"前馈指干扰信号在受控变量尚未偏离之前即通过条件性通路引起调节反应，使偏差不出现或减小。例：看到食物（视觉、嗅觉信号）即引起唾液和胃液分泌、胰岛素预分泌；赛前心率与血压提前上升。前馈比反馈更及时，但需要学习或先天经验作为基础。"},{"id":"2.6","t":"三种调节方式的比较","s":2,"c":"2. 生命活动的调节方式","x":"神经调节以电信号为主、有确定的线路；体液调节以化学信号为主、经血液广泛分布；自身调节限于局部。实际生理过程中三者常协同：如血压调节中，减压反射属神经调节（秒级）、RAAS 与肾上腺素属体液调节（分钟级）、血管肌源性反应属自身调节（即刻局部）。项目神经调节体液调节自身调节信息载体动作电位、递质激素、代谢物局部理化因素传递途径反射弧血液、组织液局部扩散速度快（ms~s）慢（s~d）快（即刻）范围精确、局限广泛局部持续时间短长短"},{"id":"3.1","t":"细胞膜的分子结构","s":3,"c":"3. 细胞膜的结构与跨膜转运","x":"细胞膜以液态镶嵌模型描述：磷脂双分子层为骨架，亲水头朝外、疏水尾相对；胆固醇嵌入脂质中调节流动性；膜蛋白以整合蛋白（跨膜）和外周蛋白形式分布；膜外表面有糖链形成糖萼（与细胞识别、免疫、受体功能有关）。膜具有不对称性和流动性（脂质侧向扩散快、翻转慢）。"},{"id":"3.2","t":"单纯扩散","s":3,"c":"3. 细胞膜的结构与跨膜转运","x":"单纯扩散指脂溶性小分子顺浓度梯度直接穿过脂质双层，不需膜蛋白与能量。物质包括 O₂、CO₂、N₂、乙醇、乙醚、类固醇激素、尿素等。扩散速率取决于膜两侧浓度差、脂溶性（油水分配系数）与分子大小，是气体交换与麻醉药作用的基础。"},{"id":"3.3","t":"经通道的易化扩散","s":3,"c":"3. 细胞膜的结构与跨膜转运","x":"离子经离子通道顺电化学梯度跨膜，速度极快（每秒 10⁶~10⁸ 个离子），具有离子选择性和门控性。按门控方式分为电压门控（Na⁺、K⁺、Ca²⁺ 通道）、化学门控（ACh 受体阳离子通道、GABA-A 的 Cl⁻ 通道）和机械门控（内耳毛细胞、触觉感受器）。河豚毒素 TTX 阻断电压门控 Na⁺ 通道，四乙基铵 TEA 阻断 K⁺ 通道。"},{"id":"3.4","t":"经载体的易化扩散","s":3,"c":"3. 细胞膜的结构与跨膜转运","x":"载体介导的易化扩散顺浓度梯度、不耗能，但具有饱和现象、竞争性抑制和结构特异性。典型为葡萄糖经 GLUT1~GLUT4 转运：GLUT2 存在于胰岛 B细胞和肝细胞（低亲和力、感受血糖），GLUT4 存在于骨骼肌与脂肪组织（受胰岛素调节转位）。速率明显慢于通道介导。"},{"id":"3.5","t":"原发性主动转运","s":3,"c":"3. 细胞膜的结构与跨膜转运","x":"钠泵（Na⁺/K⁺-ATP 酶）每水解 1 分子 ATP，将 3 个 Na⁺ 泵出、2 个 K⁺泵入，属生电性泵，对膜电位贡献约 -2~-4 mV。其他原发性主动转运包括肌浆网与质膜钙泵（SERCA、PMCA）、胃壁细胞 H⁺-K⁺-ATP 酶（泌酸）、肾小管上皮质子泵。"},{"id":"3.6","t":"继发性主动转运","s":3,"c":"3. 细胞膜的结构与跨膜转运","x":"继发性主动转运利用钠泵建立的 Na⁺ 梯度势能，逆浓度转运其他物质。同向转运（协同转运）：小肠和肾近端小管的 Na⁺-葡萄糖同向转运体 SGLT1（每 2 个 Na⁺ 带 1 个葡萄糖）、Na⁺-氨基酸、Na⁺-I- 同向转运（甲状腺摄碘）。逆向转运（交换）：Na⁺/Ca²⁺ 交换器 NCX、Na⁺/H⁺ 交换器 NHE。"},{"id":"3.7","t":"出胞与入胞","s":2,"c":"3. 细胞膜的结构与跨膜转运","x":"出胞（胞吐）是囊泡膜与质膜融合将内容物排出，见于神经递质释放、胰岛素分泌、消化酶分泌，需 Ca²⁺ 内流与 SNARE 复合体（突触囊泡蛋白synaptobrevin、突触融合蛋白 syntaxin、SNAP-25）。入胞（胞吞）包括吞噬（大颗粒、需肌动蛋白）、吞饮（液体）和受体介导的胞吞（LDL 经 LDL受体、转铁蛋白）。"},{"id":"3.8","t":"跨膜信号转导的基本类型","s":2,"c":"3. 细胞膜的结构与跨膜转运","x":"（1）离子通道型受体：递质结合直接开通道，反应以毫秒计，如nAChR、GABA-A 受体。（2）G 蛋白偶联受体：激活腺苷酸环化酶-cAMPPKA、磷脂酶 C-IP3/DG-Ca²⁺/PKC 通路，如 β 肾上腺素能受体、M 受体。（3）酪氨酸激酶型受体：胰岛素受体、生长因子受体，走 Ras-MAPK 与PI3K 通路。（4）胞内/核受体：类固醇激素、甲状腺激素直接调节基因转录。转运方式是否耗能是否需膜蛋白饱和现象典型物质单纯扩散否否无O₂、CO₂、类固醇通道介导否是（通道）不明显Na⁺、K⁺、Ca²⁺载体介导否是（载体）有葡萄糖（GLUT）原发性主动转运是（ATP）是（泵）有Na⁺、K⁺、Ca²⁺继发性主动转运间接耗能是（转运体）有葡萄糖（SGLT1）"},{"id":"4.1","t":"静息电位的数值与来源","s":3,"c":"4. 静息电位与动作电位","x":"静息电位是细胞安静时膜两侧的电位差，膜内为负。哺乳动物神经元约-70 mV，骨骼肌约 -90 mV，平滑肌约 -50~-60 mV，窦房结最大舒张电位约-70~-60 mV，红细胞约 -10 mV。其形成主要取决于 K⁺ 经非门控漏通道外流达到 K⁺ 平衡电位（Nernst 电位，神经元约 -90 mV），实际值因少量 Na⁺ 内流与生电性钠泵而偏离。"},{"id":"4.2","t":"动作电位的时相","s":3,"c":"4. 静息电位与动作电位","x":"典型神经动作电位：膜电位由 -70 mV 去极化至阈电位 -55 mV 后爆发，锋电位上升支达 +30~+40 mV（反极化/超射），随后复极化回静息水平，并出现超极化后电位。全过程 1~2 ms，其中锋电位 0.5~1 ms。骨骼肌动作电位持续时间约 2~5 ms，心肌工作细胞可达 200~300 ms。"},{"id":"4.3","t":"动作电位的离子机制","s":3,"c":"4. 静息电位与动作电位","x":"上升支由电压门控 Na⁺ 通道开放、Na⁺ 快速内流形成，接近 Na⁺ 平衡电位（约 +60 mV）；下降支由 Na⁺ 通道失活、电压门控 K⁺ 通道延迟开放、K⁺外流形成。Na⁺ 通道有激活门与失活门（“球-链”模型），失活状态是绝对不应期的分子基础。河豚毒素选择性阻断 Na⁺ 通道上升支，TEA 阻断 K⁺ 通道下降支。"},{"id":"4.4","t":"阈值与“全或无”","s":3,"c":"4. 静息电位与动作电位","x":"能使膜去极化达到阈电位的最小刺激称阈刺激，其强度为阈强度。刺激一旦达到阈值，动作电位幅度固定、波形一致，不随刺激强度增大而增大（全或无），且沿轴突不衰减传导。阈电位与静息电位的差值决定兴奋性：差值小则兴奋性高（低钙血症、高钾血症时兴奋性升高）。"},{"id":"4.5","t":"不应期","s":3,"c":"4. 静息电位与动作电位","x":"绝对不应期相当于 Na⁺ 通道处于失活状态，此期内任何刺激均不能引起新动作电位；相对不应期 Na⁺ 通道部分恢复，需超阈刺激。不应期决定神经元最高放电频率（绝对不应期约 1 ms，理论最高约 1 000 Hz，实际通常低于 500 Hz），也解释心肌不发生强直收缩（有效不应期约 200 ms，占整个收缩期）。"},{"id":"4.6","t":"钠泵的作用","s":3,"c":"4. 静息电位与动作电位","x":"钠泵每分解 1 分子 ATP 泵出 3 个 Na⁺、泵入 2 个 K⁺，其作用有四项：（1）维持 Na⁺、K⁺ 跨膜梯度，为动作电位和继发性主动转运提供势能；（2）生电性贡献约 -2~-4 mV 静息电位；（3）在动作电位后恢复离子分布；（4）参与细胞内渗透压与体积调节。脑组织耗氧量约占全身 20%，其中相当部分用于维持钠泵活动。"},{"id":"4.7","t":"兴奋性的影响因素","s":2,"c":"4. 静息电位与动作电位","x":"（1）静息电位与阈电位差距：高钾血症使静息电位绝对值减小，兴奋性先升后降甚至消失；（2）细胞外 Ca²⁺ 浓度降低使阈电位下移（靠近静息电位），兴奋性升高，故低钙引起搐搦；（3）细胞外 Na⁺ 浓度降低使动作电位幅度减小；（4）局部麻醉药阻断 Na⁺ 通道、低温降低通道开关速率，均使兴奋性下降；（5）pH 与缺氧通过影响代谢与泵功能改变兴奋性。电位典型数值主要离子机制备注神经元静息电位-70 mV K⁺ 外流为主骨骼肌静息电位-90 mV K⁺ 外流接近 K⁺ 平衡电位 -90 mV骨骼肌 K⁺ 通透性更高阈电位-55 mV Na⁺ 通道大量开放与静息电位差 15 mV动作电位峰值+30~+40 mV Na⁺ 内流接近 Na⁺ 平衡电位终板电位约 50~60 mV Na⁺、K⁺ 同开无全或无窦房结最大舒张电位-70~-60 mV If 起搏电流4 期自动去极化"},{"id":"5.1","t":"局部电位的特点","s":3,"c":"5. 局部电位与兴奋的传导","x":"局部电位是阈下刺激引起的、只向局部扩布的膜电位变化，特点为：（1）等级性，幅度随刺激强度增大；（2）电紧张性扩布，幅度随距离指数衰减（空间常数约 0.3~1 mm）；（3）可时间总和与空间总和；（4）无不应期，可叠加。包括感受器电位、终板电位、突触后电位、电紧张电位。"},{"id":"5.2","t":"电紧张扩布与膜常数","s":2,"c":"5. 局部电位与兴奋的传导","x":"局部电流沿轴突扩布时幅度按 e 的负指数衰减，空间常数 λ 反映衰减快慢（λ 与膜电阻成正比、与轴浆电阻成反比），时间常数 τ=RC 为 1~20 ms，反映膜电位变化的速度。λ 与 τ 越大，局部电位越易扩布到邻近区域达到阈电位，故粗大纤维、有髓纤维更易兴奋。"},{"id":"5.3","t":"动作电位的传导机制","s":3,"c":"5. 局部电位与兴奋的传导","x":"以局部电流学说解释：已兴奋区膜外为负、膜内为正，与邻近安静区形成局部电流，使邻近区去极化达阈值而爆发动作电位，如此逐段推进。无髓纤维为连续传导，速度 0.5~2 m/s；有髓纤维在郎飞结之间跳跃式传导，速度可达100~120 m/s，且更节能。"},{"id":"5.4","t":"兴奋传导的一般特征","s":2,"c":"5. 局部电位与兴奋的传导","x":"（1）生理完整性：需结构和功能均完整，麻醉、压迫、低温可阻断；（2）绝缘性：一条纤维的冲动不影响相邻纤维；（3）双向传导：离体神经纤维上兴奋可向两端传导（在体内因突触而呈单向）；（4）不衰减性：动作电位幅度不因距离而减小；（5）相对不疲劳性：连续刺激数小时仍能传导。"},{"id":"5.5","t":"神经干复合动作电位","s":2,"c":"5. 局部电位与兴奋的传导","x":"神经干由许多阈值、传导速度不同的纤维组成，复合动作电位的幅度取决于兴奋纤维的数目与放电的同步程度，因此不表现“全或无”，而是分级变化。随刺激增强可依次出现不同波幅（Aα、Aβ、Aγ、B、C 类纤维阈值不同），临床上用于测定神经传导速度。"},{"id":"5.6","t":"影响传导速度的因素","s":2,"c":"5. 局部电位与兴奋的传导","x":"（1）纤维直径：直径越大，轴浆电阻越小，速度越快；（2）髓鞘化：跳跃式传导显著加速；（3）温度：哺乳类神经在 37 ℃ 最快，降温减慢，降至5~10 ℃ 时传导阻滞（故低温麻醉与冬季变温动物反应迟缓）；（4）缺氧、pH 改变、药物（局麻药）均减慢或阻断传导。"},{"id":"6.1","t":"突触的类型","s":3,"c":"6. 突触传递","x":"按传递方式分为电突触与化学突触。电突触即缝隙连接（连接蛋白构成亲水通道），双向、几乎无延搁（<0.1 ms），见于心肌闰盘、平滑肌、某些中枢核团，意义是同步化活动。化学突触由突触前膜、突触间隙（20~40 nm）和突触后膜组成，单向传递，有 0.3~0.5 ms 的突触延搁。"},{"id":"6.2","t":"化学突触的传递过程","s":3,"c":"6. 突触传递","x":"动作电位传到突触前末梢 → 电压门控 Ca²⁺ 通道开放 → Ca²⁺ 内流 → 突触囊泡与突触前膜融合（SNARE 复合体介导）→ 递质以量子形式释放入间隙 →与突触后膜特异受体结合 → 离子通道开放 → 产生突触后电位。递质作用后被乙酰胆碱酯酶降解或被重摄取、扩散清除。"},{"id":"6.3","t":"EPSP 与 IPSP","s":3,"c":"6. 突触传递","x":"兴奋性突触后电位（EPSP）由 Na⁺、K⁺ 通透性同时增大（以 Na⁺ 内流为主）引起局部去极化，幅度约 0.5~1 mV，单个 EPSP 不足以达阈值，需总和；代表为谷氨酸作用于 AMPA 受体、ACh 作用于烟碱受体。抑制性突触后电位（IPSP）由 Cl⁻ 内流或 K⁺ 外流引起超极化，代表为 GABA 作用于GABA-A 受体、甘氨酸作用于脊髓 Renshaw 细胞突触。"},{"id":"6.4","t":"神经递质的种类","s":3,"c":"6. 突触传递","x":"（1）胆碱类：ACh；（2）单胺类：去甲肾上腺素、肾上腺素、多巴胺、5-羟色胺、组胺；（3）氨基酸类：谷氨酸（脑内主要兴奋性递质）、天冬氨酸、GABA（主要抑制性递质）、甘氨酸；（4）肽类：P 物质、内啡肽、血管活性肠肽、神经肽 Y；（5）气体与核苷酸：NO、CO、ATP、腺苷。递质须满足合成、释放、受体效应和失活四方面证据。"},{"id":"6.5","t":"递质受体与阻断剂","s":3,"c":"6. 突触传递","x":"胆碱能受体分烟碱型（N1 位于神经肌肉接头、N₂ 位于自主神经节）和毒蕈碱型（M1~M5，效应为副交感样）。肾上腺素能受体分 α1（血管收缩）、α2（突触前抑制）、β1（心率、心肌收缩力增强）、β2（支气管扩张、骨骼肌血管扩张）。工具药：筒箭毒碱阻断 N 受体、阿托品阻断 M 受体、酚妥拉明阻断 α 受体、普萘洛尔阻断 β 受体、六甲双铵阻断神经节 N 受体。"},{"id":"6.6","t":"突触后抑制与突触前抑制","s":3,"c":"6. 突触传递","x":"突触后抑制均由抑制性中间神经元释放抑制性递质引起，分两型：传入侧支性抑制（交互抑制，如伸肌兴奋同时屈肌抑制）与回返性抑制（Renshaw细胞抑制前角运动神经元自身）。突触前抑制发生在轴突-轴突式突触，通过使突触前末梢去极化、动作电位幅度减小、Ca²⁺ 内流减少而使递质释放减少，表现为 EPSP 减小而无 IPSP，多见于感觉传入通路。"},{"id":"6.7","t":"突触传递的特征","s":2,"c":"6. 突触传递","x":"（1）单向传递（突触前→突触后）；（2）突触延搁（0.3~0.5 ms，反射弧中神经元越多延搁越长）；（3）总和（时间与空间）；（4）兴奋节律的改变（输出频率与输入不同）；（5）对内环境变化敏感（缺氧、CO₂、pH、麻醉药、咖啡因、茶碱）；（6）易疲劳（递质耗竭），是中枢保护机制。"},{"id":"7.1","t":"神经-肌接头的结构","s":3,"c":"7. 神经-肌接头","x":"运动神经末梢在肌纤维表面形成膨大的接头前终末，其膜为接头前膜；肌膜特化为终板膜（接头后膜），其上密集分布烟碱型 ACh 受体（约每平方微米1 万个）；两者之间有 50 nm 的接头间隙，含乙酰胆碱酯酶。终板膜形成深沟（次级突触间隙），增大接触面积。"},{"id":"7.2","t":"传递过程","s":3,"c":"7. 神经-肌接头","x":"动作电位到达末梢 → 电压门控 Ca²⁺ 通道（P/Q 型）开放，Ca²⁺ 内流 →囊泡与接头前膜融合 → ACh 以量子方式释放 → ACh 与终板膜 nAChR 结合→ 受体阳离子通道同时开放 Na⁺ 与 K⁺（Na⁺ 内流为主）→ 产生终板电位 →局部电流使邻近肌膜去极化达阈电位 → 爆发肌膜动作电位 → 兴奋-收缩耦联。"},{"id":"7.3","t":"终板电位","s":2,"c":"7. 神经-肌接头","x":"终板电位是等级性局部电位，无“全或无”、可总和、无不应期，其幅度取决于释放的 ACh 量。正常一次神经冲动引起的终板电位远超阈值，存在安全系数（约 3~4 倍），故传递高度可靠；箭毒、重症肌无力时安全系数下降，出现传递阻滞。安静时自发的单个囊泡释放引起幅度约 0.5 mV 的微终板电位（MEPP）。"},{"id":"7.4","t":"传递的阻断与药物作用","s":3,"c":"7. 神经-肌接头","x":"（1）竞争性阻断 nAChR：筒箭毒碱、α-银环蛇毒（不可逆）；（2）持续去极化：琥珀酰胆碱（最初兴奋后阻滞）；（3）抑制 ACh 释放：肉毒杆菌毒素（裂解 SNARE）、缺 Ca²⁺、高 Mg²⁺；（4）促进释放：黑寡妇蜘蛛毒、路易斯气；（5）抑制胆碱酯酶：有机磷农药、新斯的明（故有机磷中毒表现为持续兴奋、肌束颤动、呼吸肌麻痹）；（6）受体自身免疫破坏：重症肌无力。"},{"id":"7.5","t":"量子释放学说","s":2,"c":"7. 神经-肌接头","x":"递质以囊泡为单位成批释放，每个囊泡含约 10⁴ 个 ACh 分子（一个量子），引起的电位变化幅度恒定。静息时的 MEPP 与神经冲动引起的终板电位均为量子的整数倍，说明释放是量子化的。Ca²⁺ 内流是触发量子释放的必要条件，递质释放概率与 Ca²⁺ 内流量正相关。"},{"id":"7.6","t":"肌松药的分类与应用","s":2,"c":"7. 神经-肌接头","x":"（1）非去极化型（竞争型）：筒箭毒碱、泮库溴铵、阿曲库铵，与 ACh竞争 nAChR 而不激活通道，作用可被胆碱酯酶抑制剂（新斯的明）部分拮抗，临床用于全麻时骨骼肌松弛；（2）去极化型：琥珀酰胆碱，先引起肌束颤动（持续去极化）再麻痹，作用不被新斯的明拮抗（反而加重），因起效快、时效短而用于气管插管。两类药物的鉴别要点是“是否先有肌束颤动”与“新斯的明能否拮抗”。此外氨基糖苷类抗生素、高镁血症、低钙血症均可抑制接头传递（抑制 Ca²⁺ 内流或降低终板敏感性），与肌松药合用需减量。"},{"id":"8.1","t":"骨骼肌的超微结构","s":3,"c":"8. 骨骼肌收缩","x":"肌原纤维由粗肌丝（肌球蛋白，含横桥头部 ATP 酶）和细肌丝（肌动蛋白、原肌球蛋白、肌钙蛋白 TnT/TnI/TnC）构成，功能单位为肌节（相邻 Z线之间），安静长度约 2.0~2.2 μm。肌膜向细胞内凹陷形成横管（T 管），肌浆网在 T 管两侧膨大形成终池，三者构成三联体，是兴奋-收缩耦联的结构基础。"},{"id":"8.2","t":"肌丝滑行学说","s":3,"c":"8. 骨骼肌收缩","x":"肌肉收缩时细肌丝向 M 线方向滑行，肌节缩短，粗、细肌丝长度不变。横桥周期：（1）横桥头部与肌动蛋白结合；（2）头部摆动（power stroke）拉动细肌丝；（3）ATP 结合使横桥与肌动蛋白解离；（4）ATP 水解使头部复位并储能。Ca²⁺ 与 ATP 缺一不可。"},{"id":"8.3","t":"兴奋-收缩耦联","s":3,"c":"8. 骨骼肌收缩","x":"肌膜动作电位沿 T 管传入 → T 管膜上二氢吡啶受体（DHPR，即 L 型Ca²⁺ 通道）发生构象改变 → 机械性激活肌浆网 RyR1 受体 → 终池释放Ca²⁺，胞质 Ca²⁺ 由 100 nmol/L 升至 1~10 μmol/L → Ca²⁺ 结合 TnC → 原肌球蛋白移位、暴露肌动蛋白结合位点 → 横桥结合并摆动。舒张时 Ca²⁺ 被SERCA 泵回肌浆网（占 90%）及经 NCX 排出。骨骼肌为机械耦联，心肌为钙触发钙释放（CICR）。"},{"id":"8.4","t":"Ca²⁺ 触发机制的种间差异","s":3,"c":"8. 骨骼肌收缩","x":"骨骼肌：DHPR 与 RyR1 直接机械耦联，不需胞外 Ca²⁺ 内流即可收缩（故离体骨骼肌在无钙液中短时仍可收缩）。心肌：胞外 Ca²⁺ 经 L 型通道内流触发 RyR2 释放肌浆网 Ca²⁺（CICR），收缩强度依赖胞外 Ca²⁺，故低钙灌流使心肌收缩迅速减弱（钙反常现象）。平滑肌：胞外 Ca²⁺ 内流与 IP3 诱导的肌浆网释放并重，经钙调蛋白途径收缩。"},{"id":"8.5","t":"单收缩与强直收缩","s":3,"c":"8. 骨骼肌收缩","x":"单收缩分潜伏期（约 10 ms，相当于兴奋-收缩耦联时间）、缩短期、舒张期。刺激频率增高，若后一刺激落在前一收缩的舒张期，出现不完全强直收缩；落在缩短期则融合为完全强直收缩，张力可达单收缩的 3~4 倍。心肌因平台期长、有效不应期几乎覆盖整个收缩期，不发生强直收缩，保证心脏充盈与射血。"},{"id":"8.6","t":"收缩的力学特性","s":2,"c":"8. 骨骼肌收缩","x":"（1）等长收缩（张力增加、长度不变，如维持姿势）与等张收缩（长度缩短、张力不变，如举物）；（2）长度-张力关系：最适初长 2.0~2.2 μm 时粗细肌丝重叠最佳，张力最大；（3）负荷-速度关系：负荷越大，缩短速度越慢，做功功率在中等负荷时最大；（4）运动单位与募集：慢运动单位（I 型，抗疲劳）先募集，快运动单位（IIa、IIx）后募集。"},{"id":"8.7","t":"收缩的能量供应与肌纤维类型","s":2,"c":"8. 骨骼肌收缩","x":"直接能源为 ATP，肌内 ATP 仅够数次收缩，由磷酸肌酸（CP）经肌酸激酶快速再生，再由糖酵解与氧化磷酸化补充；剧烈运动后需偿还氧债并清除乳酸。I 型（慢氧化型）纤维线粒体多、肌红蛋白多、抗疲劳，适于耐力；IIa 型（快氧化-糖酵解型）兼具；IIx（IIb）型糖酵解为主、收缩快、易疲劳，适于爆发运动。项目骨骼肌心肌平滑肌横纹有有无兴奋传递神经-肌接头闰盘缝隙连接缝隙连接/神经支配钙来源肌浆网（机械耦联）胞外内流触发 SR胞外内流 + IP3调节蛋白肌钙蛋白动作电位肌钙蛋白2~5 ms 200~300 ms（平台期）钙调蛋白 + MLCK 10~50 ms是否强直可不可可（部分）收缩特点快、强、易疲劳节律、不疲劳慢、持久、耗能少"},{"id":"9.1","t":"平滑肌的结构与收缩机制","s":3,"c":"9. 平滑肌与心肌的特点","x":"平滑肌无横纹，粗肌丝少且排列不规则，细肌丝一端附着于致密体（类似Z 线）和质膜。收缩机制为：胞质 Ca²⁺ 升高 → 结合钙调蛋白（CaM）→ 激活肌球蛋白轻链激酶（MLCK）→ 磷酸化肌球蛋白轻链 → 与肌动蛋白结合并摆动。舒张时 MLCK 失活、肌球蛋白轻链磷酸酶（MLCP）去磷酸化。"},{"id":"9.2","t":"平滑肌的电活动","s":3,"c":"9. 平滑肌与心肌的特点","x":"单位平滑肌（内脏、消化道）静息电位 -50~-60 mV，存在由 Na⁺ 内流与K⁺ 通透性周期性变化引起的慢波（基本电节律）：胃约 3 次/分、十二指肠约12 次/分、回肠约 8~9 次/分，慢波本身不引起收缩，但决定动作电位的发生部位与节律。动作电位以 Ca²⁺ 内流为主，常带平台。多单位平滑肌（虹膜、竖毛肌、大血管）无自发活动，由自主神经直接控制。"},{"id":"9.3","t":"平滑肌收缩的特点","s":2,"c":"9. 平滑肌与心肌的特点","x":"（1）收缩缓慢、持久，一次收缩可达数秒至数十秒，耗能少（维持张力所需 ATP 仅为骨骼肌的 1/300~1/10）；（2）具有可塑性，被牵拉后可缓慢适应而张力不显著增加（胃容纳性舒张）；（3）对化学刺激、缺氧、pH、温度敏感（组胺、ACh、NE、血管紧张素 II、前列腺素）；（4）牵张可引起肌源性收缩（血管、输尿管、淋巴管）；（5）可发生单个单位同步收缩。"},{"id":"9.4","t":"心肌细胞的结构与功能合胞体","s":3,"c":"9. 平滑肌与心肌的特点","x":"心肌工作细胞有横纹、单核、分支状，相邻细胞以闰盘相连，闰盘中的缝隙连接电阻极低，使整群心肌成为一个功能性合胞体（心房、心室各自为一合胞体，中间由纤维环绝缘）。故兴奋在心房或心室内几乎同步传导，符合“全或无”式整体收缩。"},{"id":"9.5","t":"心肌动作电位","s":3,"c":"9. 平滑肌与心肌的特点","x":"心室工作细胞：0 期由电压门控 Na⁺ 通道开放、快速内流（幅度约 120 mV）；1 期 K⁺ 外流（Ito）短暂复极；2 期平台期由 L 型 Ca²⁺ 通道内流与K⁺ 外流（IK）平衡形成，持续 100~150 ms；3 期 K⁺ 外流（IK1、IKr）复极；4 期为稳定静息电位（-90 mV）。窦房结细胞最大舒张电位 -70~-60 mV，4 期由 If（Na⁺ 为主的内向起搏电流）、T 型与 L 型 Ca²⁺ 内流引起自动去极化，0 期由 L 型 Ca²⁺ 内流形成（无 Na⁺ 通道参与，故 0 期去极慢、幅度小）。"},{"id":"9.6","t":"心肌收缩的特点","s":3,"c":"9. 平滑肌与心肌的特点","x":"（1）依赖胞外 Ca²⁺（CICR）；（2）不发生强直收缩（有效不应期约200 ms 覆盖收缩期）；（3）异长自身调节：前负荷（心室舒张末期容积）增大使初长增加、收缩力增强（Frank-Starling 定律），保证心输出量与回心血量匹配；（4）等长收缩为主，心肌张力变化明显而长度变化小；（5）收缩力受交感神经、儿茶酚胺和胞外 Ca²⁺ 浓度调节（等长自身调节）。"},{"id":"9.7","t":"心肌的代谢与特性","s":2,"c":"9. 平滑肌与心肌的特点","x":"心肌几乎完全依靠有氧氧化供能（脂肪酸占 60%~70%，葡萄糖与乳酸次之），线粒体占细胞体积 30%~35%，故对缺氧极敏感，缺血数分钟即损伤。心肌还具有自动节律性、传导性、兴奋性和收缩性四大生理特性，其中自律性来源于特殊传导系统（窦房结 100 次/分、房室交界 50 次/分、浦肯野纤维25~40 次/分）。第二篇 血液与循环"},{"id":"10.1","t":"血液的组成","s":3,"c":"10. 血液的组成与理化特性","x":"血液由血浆（约占 55%）和血细胞（约占 45%，即血细胞比容）组成。血浆中水占 90%~92%，固体成分中血浆蛋白占 6%~8%（65~85 g/L），其余为电解质、营养物质、代谢产物、激素和气体。血细胞包括红细胞、白细胞和血小板三类。成年哺乳动物血量约占体重的 7%~8%（约 70~80 mL/kg），其中循环血量与储存血量（肝、脾、肺、皮肤血池）保持动态平衡。"},{"id":"10.2","t":"血浆蛋白及其功能","s":3,"c":"10. 血液的组成与理化特性","x":"血浆蛋白用电泳分为白蛋白（40~50 g/L）、球蛋白（20~30 g/L，含α1、α2、β、γ）和纤维蛋白原（2~4 g/L）。功能：（1）形成血浆胶体渗透压（白蛋白分子小、数目多，贡献约 75%~80%），维持血容量；（2）运输：白蛋白运输脂肪酸、胆红素、多种药物，球蛋白运输脂类、激素、铁（转铁蛋白）；（3）免疫：γ 球蛋白即抗体；（4）凝血与抗凝：纤维蛋白原、凝血酶原等；（5）缓冲 pH：蛋白质钠盐/蛋白质缓冲对。"},{"id":"10.3","t":"血液的理化特性","s":3,"c":"10. 血液的组成与理化特性","x":"（1）颜色与比重：动脉血鲜红、静脉血暗红，全血比重 1.050~1.060；（2）黏滞性：全血约为水的 4~5 倍，血浆约 1.6~2.4 倍，取决于红细胞数目与血浆蛋白浓度，红细胞增多时黏滞性升高、血流阻力增大；（3）渗透压：血浆渗透压约 300 mOsm/(kg·H₂O)（约 7 700 kPa），其中晶体渗透压占 99.5%以上，主要由 Na⁺ 和 Cl⁻ 形成，决定细胞内外水的分布；胶体渗透压仅约 1.5 mOsm（约 3.3 kPa 即 25 mmHg），决定血管内外水的分布；（4）酸碱度：pH 7.35~7.45。"},{"id":"10.4","t":"血浆的缓冲系统","s":2,"c":"10. 血液的组成与理化特性","x":"血浆最重要的缓冲对是 NaHCO3/H2CO3（比值 20∶1，最为重要），其次为 Na2HPO4/NaH2PO4、蛋白质钠盐/蛋白质。红细胞内有血红蛋白缓冲对（KHb/HHb、KHbO₂/HHbO₂）和 KHCO3/H2CO3，承担约 50% 的碳酸氢盐缓冲任务。呼吸调节 CO₂ 排出（快，数分钟）、肾调节 HCO₃⁻ 重吸收与H⁺ 排泌（慢，数小时至数日）共同维持 pH。"},{"id":"10.5","t":"血液的功能","s":2,"c":"10. 血液的组成与理化特性","x":"（1）运输：O₂、CO₂、营养物质、代谢废物、激素、热；（2）缓冲与稳态：维持 pH、渗透压、体温（水的比热大）；（3）防御与免疫：白细胞、抗体、补体；（4）止血与凝血：血小板与凝血因子；（5）参与体温调节与内分泌运输（部分激素的载体）。项目正常值意义血量体重 7%~8%失血 >20% 出现循环障碍血细胞比容反映红细胞相对量血浆总蛋白男 40%~50%，女 37%~48% 65~85 g/L血浆渗透压pH约 300 mOsm/(kg·H₂O) 7.35~7.45胶体渗透压约 25 mmHg血液黏滞性水的 4~5 倍红细胞增多时升高白蛋白 40~50 g/L靠缓冲系统与肺肾调节"},{"id":"10.6","t":"失血与血液的补充","s":3,"c":"10. 血液的组成与理化特性","x":"失血 <10% 血量（约 500 mL）时，通过血管收缩、脾与肝储血释放、组织液回流与 RAAS 激活代偿，血压与心输出量基本不变，仅出现心率略快；失血 20%（约 1 000 mL）时出现血压下降、心率明显加快、皮肤苍白、尿量减少；失血 >30% 时可致失血性休克。血浆量的恢复靠肝合成白蛋白（需 1~2天）与 ADH、醛固酮保钠保水（数小时），红细胞的恢复需 EPO 刺激（2~3周恢复，故贫血纠正较慢）。临床对大出血先补晶体液/胶体液维持循环，再输成分血（浓缩红细胞、血浆、血小板），避免过量输全血引起循环超负荷。"},{"id":"11.1","t":"红细胞的形态与数量","s":3,"c":"11. 红细胞","x":"哺乳类成熟红细胞无核、无细胞器，呈双凹圆盘状（直径约 7~8 μm），表面积/体积比大而利于气体交换，且可变形通过毛细血管。数量：成年男性(4.5~5.5)×10¹²/L，女性 (3.8~4.6)×10¹²/L；血红蛋白浓度男性 120~160 g/L，女性 110~150 g/L。禽类、鱼类、两栖类红细胞有核，呈椭圆形。"},{"id":"11.2","t":"血红蛋白的结构与功能","s":3,"c":"11. 红细胞","x":"血红蛋白由 1 个珠蛋白（2 条 α 链、2 条 β 链）和 4 个血红素（含 Fe²⁺）构成，1 分子 Hb 可结合 4 分子 O₂。Fe²⁺ 与 O₂ 结合为氧合（不氧化），Fe³⁺为高铁血红蛋白而失去携氧能力。Hb 还运输 CO₂（形成氨基甲酰血红蛋白，占 CO₂ 运输的 7% 左右）并参与缓冲。每克 Hb 结合 O₂ 约 1.34~1.36 mL，故100 mL 动脉血含 O₂ 约 19~20 mL。"},{"id":"11.3","t":"红细胞的生成","s":3,"c":"11. 红细胞","x":"胚胎期由卵黄囊、肝、脾造血，出生后主要靠红骨髓（成人主要在扁骨、椎骨、胸骨、髂骨）。生成需要：（1）蛋白质与铁（成人每日需 20~25 mg，其中 95% 来自衰老红细胞破坏后的再利用，食物吸收 1~2 mg）；（2）叶酸与维生素 B12（参与 DNA 合成，缺乏引起巨幼红细胞性贫血）；（3）促红细胞生成素（EPO）；（4）雄激素、甲状腺激素、生长激素可促进造血。缺铁引起小细胞低色素性贫血。"},{"id":"11.4","t":"促红细胞生成素","s":3,"c":"11. 红细胞","x":"EPO 是一种糖蛋白激素，成人约 90% 由肾皮质肾小管周围间质细胞（及肾小球旁器）产生，肝脏产生少量。肾脏通过感受血液携 O₂ 量（而非 O₂ 分压本身）调节 EPO 分泌：贫血、高原低氧、失血、肺心病时 EPO 升高，刺激红系祖细胞增殖分化，使红细胞生成增加（需 5~7 天见效）。慢性肾病时 EPO减少是肾性贫血的主因。"},{"id":"11.5","t":"红细胞的破坏与寿命","s":3,"c":"11. 红细胞","x":"红细胞平均寿命约 120 天（大鼠约 60 天，兔约 60~70 天），衰老红细胞膜变形性下降、表面唾液酸减少，在脾（主要）、肝、骨髓中被巨噬细胞吞噬（“血管外破坏”，占 90%），血红蛋白分解为珠蛋白（降解为氨基酸）、铁（再利用）和胆红素（经肝排入胆汁）。少数在血管内破坏（机械损伤、补体、溶血毒素），释出 Hb 与 Hb 结合后经肝处理。"},{"id":"11.6","t":"红细胞的渗透脆性与溶血","s":2,"c":"11. 红细胞","x":"红细胞在低渗溶液中吸水膨胀，膜张力过大而破裂溶血，此特性称渗透脆性。正常红细胞在 0.42%~0.45% NaCl 溶液中开始溶血，0.30%~0.35% 时完全溶血；衰老红细胞脆性增大。临床用 0.9% NaCl 为等渗溶液（生理盐水）；高渗溶液使红细胞皱缩。溶血可因免疫（ABO 不合输血）、机械（人工心脏瓣膜）、生物（蛇毒、溶血性链球菌）和化学因素引起。"},{"id":"11.7","t":"红细胞的悬浮稳定性与血沉","s":2,"c":"11. 红细胞","x":"红细胞能较稳定地悬浮于血浆中，其沉降速度以血沉（ESR）表示，男性0~15 mm/h，女性 0~20 mm/h。血沉快慢主要取决于血浆成分（纤维蛋白原、球蛋白、胆固醇增多时加快，白蛋白、卵磷脂增多时减慢），而与红细胞本身关系较小。结核、风湿、恶性肿瘤时血沉加快，故为常用的非特异指标。项目红细胞数（男/女）数值(4.5~5.5)/(3.8~4.6)×10¹²/L高原居民偏高血红蛋白（男/女）120~160/110~150 g/L每克 Hb 结合 O₂ 1.34 mL说明红细胞寿命约 120 天主要在脾破坏每日生成量与破坏保持平衡渗透脆性起点约 2×10¹¹ 个0.42%~0.45% NaCl血沉（男/女）0~15/0~20 mm/h取决于血浆成分衰老红细胞增大"},{"id":"12.1","t":"白细胞的分类与数量","s":3,"c":"12. 白细胞与血小板","x":"成人白细胞总数 (4~10)×10⁹/L。中性粒细胞占 50%~70%（(2.5~7.5)×10⁹/L），吞噬化脓性细菌；嗜酸性粒细胞 0.5%~5%，参与抗寄生虫与过敏反应；嗜碱性粒细胞 0%~1%，释放组胺、肝素、白三烯；单核细胞 3%~8%，进入组织分化为巨噬细胞；淋巴细胞 20%~40%，分 T 细胞（细胞免疫）、B 细胞（体液免疫）、NK 细胞（自然杀伤）。"},{"id":"12.2","t":"白细胞的生理特性","s":2,"c":"12. 白细胞与血小板","x":"（1）变形运动与趋化性：沿化学梯度（补体 C5a、IL-8、细菌产物）定向迁移，变形运动依赖肌动蛋白；（2）吞噬作用：需调理素（IgG 的 Fc 段、补体 C3b）协助，吞噬后形成吞噬体与溶酶体融合，通过呼吸爆发（NADPH 氧化酶产生超氧阴离子）杀菌；（3）分泌功能：释放细胞因子、蛋白酶、活性氧。"},{"id":"12.3","t":"白细胞的生成与调节","s":2,"c":"12. 白细胞与血小板","x":"白细胞起源于骨髓造血干细胞：粒-巨噬系集落形成单位（CFU-GM）在粒细胞集落刺激因子（G-CSF）、粒-巨噬细胞集落刺激因子（GM-CSF）作用下分化成熟，淋巴细胞在骨髓（B 细胞）和胸腺（T 细胞）发育成熟。细菌感染时中性粒细胞增多（感染性白细胞升高），病毒、伤寒时可能减少；肾上腺素可使边缘池白细胞进入循环而短暂升高。"},{"id":"12.4","t":"血小板的形态与数量","s":3,"c":"12. 白细胞与血小板","x":"血小板由骨髓巨核细胞胞质脱落形成，无细胞核，呈双突圆盘状，直径2~4 μm，数量 (100~300)×10⁹/L（寿命 7~14 天）。膜表面有糖蛋白 GPIb（结合 vWF）、GPIIb/IIIa（结合纤维蛋白原，是抗血小板药作用靶点），胞内有 α 颗粒（纤维蛋白原、vWF、PF4、PDGF）、致密颗粒（ADP、5-HT、Ca²⁺）、溶酶体和收缩蛋白（血栓收缩）。"},{"id":"12.5","t":"血小板的生理特性","s":3,"c":"12. 白细胞与血小板","x":"（1）黏附：经 vWF 与胶原纤维结合；（2）释放（激活）：释放 ADP、5-HT、血栓素 A2（TXA2），ADP 与 TXA2 进一步激活其他血小板；（3）聚集：可逆第一相（ADP 引起）与不可逆第二相（TXA2、凝血酶引起），GPIIb/IIIa 与纤维蛋白原桥接；（4）收缩：血小板收缩蛋白使血块回缩、更牢固；（5）吸附：吸附凝血因子于表面，提高局部浓度。"},{"id":"12.6","t":"血小板的生成与破坏","s":2,"c":"12. 白细胞与血小板","x":"血小板生成由血小板生成素（TPO，主要由肝产生）调节，TPO 促进巨核细胞增殖分化。衰老血小板在脾（约 1/3 储存于脾）被巨噬细胞吞噬清除。特发性血小板减少性紫癜为自身抗体破坏血小板；弥散性血管内凝血（DIC）时血小板大量消耗而减少。细胞数量主要功能寿命红细胞(3.8~5.5)×10¹²/L运输 O₂ 与 CO₂约 120 天中性粒细胞50%~70%吞噬细菌循环 6~8 小时淋巴细胞20%~40%特异性免疫数天至数年单核细胞3%~8%分化为巨噬细胞循环约 1~3 天血小板(100~300)×10⁹/L止血、凝血7~14 天"},{"id":"13.1","t":"生理性止血的过程","s":3,"c":"13. 生理性止血与血液凝固","x":"（1）血管收缩：损伤引起血管平滑肌反射性收缩与局部肌源性收缩，持续约 15~30 分钟；（2）血小板止血栓形成：黏附、聚集形成松软白色血栓（初级止血）；（3）血液凝固：形成纤维蛋白网，网罗血细胞形成红色血栓（次级止血），并因血小板收缩使血块回缩、持久止血。出血时间正常 1~3 分钟（Duke 法），反映血小板与血管功能；凝血时间反映凝血因子功能。"},{"id":"13.2","t":"凝血因子","s":3,"c":"13. 生理性止血与血液凝固","x":"已知凝血因子 12 个（用罗马数字编号，因子 VI 被删除）。关键点：因子III 为组织因子（组织凝血活酶，来自损伤组织）；因子 IV 为 Ca²⁺；因子VIII 为抗血友病因子（缺乏致血友病 A）；因子 IX 缺乏致血友病 B；因子II、VII、IX、X 的合成需维生素 K（γ-羧化谷氨酸残基），故维生素 K 缺乏或长期用华法林可致出血。除因子 III 外，其余因子均存在于血浆。"},{"id":"13.3","t":"凝血过程的三阶段","s":3,"c":"13. 生理性止血与血液凝固","x":"（1）凝血酶原激活物形成：经内源性途径或外源性途径，最终形成因子Xa-Va-Ca²⁺-磷脂复合物；（2）凝血酶原（因子 II）转变为凝血酶（IIa）；（3）纤维蛋白原（因子 I）在凝血酶作用下变为纤维蛋白单体，再经因子XIIIa 与 Ca²⁺ 作用交联成不溶性纤维蛋白网。凝血酶还能正反馈激活因子 V、VIII、XI 和血小板。"},{"id":"13.4","t":"内源性与外源性凝血途径","s":3,"c":"13. 生理性止血与血液凝固","x":"内源性途径：因子 XII 接触带负电表面（胶原、玻璃）而激活 → XI →IX，IXa 与 VIIIa 在 Ca²⁺ 与磷脂（血小板 3 因子）表面形成复合物激活 X。全过程约需数分钟，参与因子多。外源性途径：组织损伤释放因子 III（组织因子）与 VII 结合成复合物，直接激活 X（也可激活 IX），反应快（约 10 余秒），是体内凝血的主要启动途径。两途径在因子 X 激活处汇合，称共同途径。"},{"id":"13.5","t":"抗凝物质","s":3,"c":"13. 生理性止血与血液凝固","x":"（1）抗凝血酶 III（AT-III）：血浆中最重要的抗凝物质，与凝血酶及Xa、IXa、XIa 结合而灭活，肝素可增强其活性 2 000 倍；（2）肝素：由肥大细胞和嗜碱性粒细胞产生，与 AT-III 结合增强抗凝，体内外均有抗凝作用；（3）蛋白质 C 系统：活化蛋白 C 灭活 Va、VIIIa；（4）组织因子途径抑制物（TFPI）。临床抗凝：草酸钾/柠檬酸钠（Ca²⁺ 络合剂，仅体外）、华法林（抑制维生素 K 依赖因子合成，体内）、肝素（体内外）。"},{"id":"13.6","t":"纤维蛋白溶解","s":2,"c":"13. 生理性止血与血液凝固","x":"纤溶系统由纤溶酶原、纤溶酶、纤溶酶原激活物（t-PA、u-PA）和抑制物（PAI-1、α2-抗纤溶酶）组成。纤溶酶降解纤维蛋白与纤维蛋白原，产生碎片，防止血栓扩大并溶解已形成的血栓。尿激酶、链激酶、t-PA 为溶栓药。纤溶亢进可致出血，减弱则促进血栓形成，两者在体内保持动态平衡。"},{"id":"13.7","t":"止血与凝血的调节与异常","s":2,"c":"13. 生理性止血与血液凝固","x":"促进因素：血小板激活（ADP、TXA2）、凝血因子激活、局部血流缓慢、Ca²⁺ 存在、维生素 K。抑制因素：抗凝血酶 III、肝素、蛋白质 C、纤溶系统、血流冲刷。异常：（1）血小板减少或功能障碍（紫癜）；（2）凝血因子缺乏（血友病 A 为 VIII 缺乏，X 连锁隐性遗传，表现为深部肌肉与关节出血）；（3）维生素 K 缺乏（新生儿出血症）；（4）DIC 时先凝血后出血；（5）血友病与血管性血友病的鉴别。项目启动条件内源性途径外源性途径起始因子血管内膜暴露、接触激活XII → XI → IX组织损伤释放因子 III III + VII参与因子数多（XII、XI、IX、VIII）少（III、VII）反应速度慢（数分钟）快（十余秒）生理意义体外凝血试验（试管法）体内凝血的主要启动共同终点因子 X 激活 → 凝血酶 → 纤维蛋同左白"},{"id":"14.1","t":"ABO 血型系统","s":3,"c":"14. 血型与输血","x":"按红细胞膜上 A、B 抗原（凝集原）与血清中抗 A、抗 B 抗体（凝集素）划分：A 型（A 抗原、抗 B）、B 型（B 抗原、抗 A）、AB 型（A、B 抗原、无抗体）、O 型（无抗原、抗 A 与抗 B）。我国汉族 O 型约 30%、A 型约28%、B 型约 30%、AB 型约 12%。抗 A、抗 B 属天然抗体（IgM，多为完全抗体），出生后 3~6 个月开始产生（由肠道菌群多糖诱导）。"},{"id":"14.2","t":"输血原则与配型","s":3,"c":"14. 血型与输血","x":"根本原则是同型输血。输血前须做 ABO 与 Rh 血型鉴定及交叉配血（主侧：供血者红细胞 + 受血者血清；次侧：受血者红细胞 + 供血者血清）。同型输血主、次侧均不凝集。紧急情况下 O 型血可少量输给其他型（“万能供血者”），AB 型可接受少量其他型血，但现代医学强调输同型成分血。输血反应表现为溶血、发热、过敏、休克，由抗原-抗体凝集反应引起。"},{"id":"14.3","t":"Rh 血型系统","s":3,"c":"14. 血型与输血","x":"Rh 抗原以 D 抗原抗原性最强，含 D 抗原者为 Rh 阳性（我国汉族约99%，其他民族约 85%），不含者阴性。与 ABO 不同，Rh 系统天然抗体少，免疫抗体（IgG）需经免疫刺激产生。Rh 阴性母体怀 Rh 阳性胎儿，分娩时胎血进入母体使母体产生抗 D 抗体，再次妊娠时 IgG 通过胎盘破坏胎儿红细胞，发生新生儿溶血病（Rh 不合溶血）。"},{"id":"14.4","t":"血型的遗传与意义","s":2,"c":"14. 血型与输血","x":"ABO 血型由 9 号染色体上 IA、IB、i 三个复等位基因决定，IA、IB 为共显性，i 为隐性，基因型 IAIA 或 IAi 为 A 型、IBIB 或 IBi 为 B 型、IAIB 为AB 型、ii 为 O 型。血型在法医学亲子鉴定、器官移植配型（HLA 配型）和群体遗传学中有意义。除 ABO、Rh 外还有 MN、Lewis、P 等 30 多个系统。"},{"id":"14.5","t":"白细胞与血小板的抗原","s":1,"c":"14. 血型与输血","x":"白细胞膜上有人类白细胞抗原（HLA），属共显性遗传的复杂系统，是器官移植免疫排斥的主要靶点，也是血小板输血配型的依据。多次输血或妊娠可产生针对 HLA 的免疫抗体，引起输血后发热性非溶血反应和血小板输注无效。"},{"id":"14.6","t":"血液的保存与代用品","s":1,"c":"14. 血型与输血","x":"血液保存液（ACD、CPD）以枸橼酸抗凝、葡萄糖供能、调节 pH，4 ℃可保存全血 21~35 天（红细胞 2,3-DPG 逐渐减少，故主张成分输血）。血小板需 22 ℃ 振荡保存 3~5 天，血浆 -20 ℃ 以下保存 1 年。人工血代用品包括氟碳化合物（携氧）和血红蛋白类载氧体，尚在研究阶段。"},{"id":"15.1","t":"心脏的结构","s":3,"c":"15. 心脏的结构与泵血功能","x":"心脏由四个腔（左右心房、左右心室）组成，泵血通路为：右心房 → 右心室 → 肺动脉 → 肺 → 肺静脉 → 左心房 → 左心室 → 主动脉 → 全身 → 腔静脉→ 右心房。右房室瓣为三尖瓣、左房室瓣为二尖瓣，另有主动脉瓣（三个半月瓣）和肺动脉瓣。瓣膜由纤维环锚定，只允许单向血流；乳头肌与腱索防止房室瓣在心室收缩时倒翻入心房。"},{"id":"15.2","t":"心肌的特殊传导系统与血液供应","s":2,"c":"15. 心脏的结构与泵血功能","x":"特殊传导系统由窦房结（正常起搏点，位于上腔静脉与右心房交界处）、房室交界（房室结，有延搁作用）、房室束（His 束）、左右束支和浦肯野纤维构成，使兴奋先心房后心室顺序传导。冠状动脉分左右两支，左前降支与左旋支供应左心室（心肌主要动脉为冠状动脉），冠状动脉血流量在舒张期为主（约占 70%~80%），故心率过快时冠脉供血减少。"},{"id":"15.3","t":"心动周期与时相","s":3,"c":"15. 心脏的结构与泵血功能","x":"以心率 75 次/分计，一个心动周期为 0.8 s。心房收缩期 0.1 s、心房舒张期 0.7 s；心室收缩期 0.3 s（等容收缩期 0.05 s、快速射血期 0.1 s、减慢射血期 0.15 s）、心室舒张期 0.5 s（等容舒张期 0.06~0.08 s、快速充盈期 0.11 s、减慢充盈期 0.22 s、心房收缩期 0.1 s）。心率加快时首先缩短的是舒张期（尤其快速充盈期），故心率过快时充盈不足、冠脉供血减少。"},{"id":"15.4","t":"心动周期中的压力与容积变化","s":3,"c":"15. 心脏的结构与泵血功能","x":"心室收缩期：室内压迅速升高超过心房压，房室瓣关闭（产生第一心音）；室内压仍低于主动脉压时房室瓣与动脉瓣均关（等容收缩期，容积不变、压力骤升）；室内压超过主动脉压时主动脉瓣开放、射血。舒张期：室内压低于主动脉压，主动脉瓣关闭（产生第二心音）；室内压仍高于心房压时两瓣均关（等容舒张期）；低于心房压时房室瓣开放、心室充盈（充盈量的约70% 靠心室舒张抽吸，30% 靠心房收缩）。"},{"id":"15.5","t":"心输出量与射血分数","s":3,"c":"15. 心脏的结构与泵血功能","x":"每搏输出量约 70 mL（60~80 mL），心率 60~100 次/分，心输出量 = 每搏输出量 × 心率 ≈ 5 L/min（4.5~6 L/min）。每分输出量女性比男性低约10%，剧烈运动时可达 25~35 L/min（运动员可达 40 L/min 以上）。射血分数 = 每搏输出量/心室舒张末期容积 = 70/120~130，约 55%~65%，是评价心功能最敏感的指标。心指数（心输出量/体表面积）约 3.0~3.5 L/(min·m²)。"},{"id":"15.6","t":"心脏做功与心力储备","s":2,"c":"15. 心脏的结构与泵血功能","x":"左心室每搏做功约 1 J（功 = 压力 × 容积），每分功约 75~80 J。心力储备指心输出量随机体需要而增加的能力，包括心率储备（可达 2~2.5 倍）与搏出量储备（收缩期储备约 35~40 mL、舒张期储备约 15 mL）。运动员以心肌收缩力增强（收缩期储备）为主，普通人以心率加快为主。"},{"id":"15.7","t":"心音","s":2,"c":"15. 心脏的结构与泵血功能","x":"第一心音：房室瓣关闭与心室肌收缩引起，音调低、持续时间长（0.1~0.12 s），标志心室收缩开始；第二心音：主动脉瓣与肺动脉瓣关闭引起，音调高、短促（0.08 s），标志心室舒张开始；第三心音为快速充盈期室壁振动（儿童可闻）；第四心音为心房收缩引起。瓣膜病变时出现杂音，如二尖瓣狭窄舒张期杂音。"},{"id":"15.8","t":"影响心输出量的因素","s":3,"c":"15. 心脏的结构与泵血功能","x":"（1）前负荷（心室舒张末期容积）：在一定范围内增大使搏出量增加（Frank-Starling 定律），但超过最适初长反而下降；（2）后负荷（动脉血压）：后负荷增大使射血阻力增加、搏出量暂时减少（继以代偿性增强）；（3）心肌收缩能力（等长自身调节）：交感神经与儿茶酚胺、胞外 Ca²⁺、洋地黄增强收缩力；（4）心率：心率过快使充盈不足、搏出量下降，过慢也使心输出量减少，适宜范围为 60~100 次/分。指标心率正常值备注60~100 次/分60~80 mL运动员可 40~50 次/分每搏输出量心输出量4.5~6 L/min平均 5 L/min射血分数55%~65%<50% 提示心功能减退心室舒张末期容积120~130 mL收缩末期约 50~60 mL心指数3.0~3.5 L/(min·m²)按体表面积校正平均约 70 mL"},{"id":"16.1","t":"心肌细胞的分类","s":3,"c":"16. 心肌电生理","x":"按电生理特性分为：（1）工作细胞（心房肌、心室肌）：无自律性，执行收缩，动作电位有平台期；（2）自律细胞（窦房结 P 细胞、房室交界、浦肯野纤维）：有 4 期自动去极化，几乎无收缩功能。按 0 期去极机制分为快反应细胞（Na⁺ 内流，包括心房肌、心室肌、浦肯野纤维）和慢反应细胞（Ca²⁺ 内流，包括窦房结、房室交界）。"},{"id":"16.2","t":"心室肌细胞的动作电位","s":3,"c":"16. 心肌电生理","x":"0 期（去极）：Na⁺ 快速内流，幅度约 120 mV，速度极快；1 期：瞬时外向 K⁺ 电流（Ito）引起短暂复极；2 期（平台）：L 型 Ca²⁺ 内流与 K⁺ 外流（IK）处于平衡，持续约 100~150 ms，是心肌特有的；3 期：K⁺ 外流增强（IK1、IKr）快速复极至 -90 mV；4 期：稳定静息电位（IK1 开放）。平台期使有效不应期延长，是心肌不产生强直收缩的根本原因。"},{"id":"16.3","t":"兴奋性及其周期性变化","s":3,"c":"16. 心肌电生理","x":"心肌兴奋后兴奋性依次经历：绝对不应期（0 期至 3 期 -55 mV，Na⁺ 通道失活，任何刺激无反应）→ 有效不应期（至 -60 mV，含绝对不应期，保证不产生强直收缩）→ 相对不应期（-60~-80 mV，需超阈刺激）→ 超常期（-80~-90 mV，阈下刺激可致兴奋）。期前收缩与代偿间歇：在相对不应期或超常期受到的额外刺激引起提前收缩，其后有较长代偿间歇（因窦房结下一次冲动落在有效不应期）。"},{"id":"16.4","t":"自律性与正常起搏点","s":3,"c":"16. 心肌电生理","x":"自律细胞 4 期自动去极化是自律性的基础。窦房结 P 细胞 4 期由 If（以Na⁺ 为主的内向起搏电流）、ICa-T、ICa-L 及 IK 衰减共同形成，自动去极化速率最快（约 0.1 V/s），自律性最高（100 次/分），成为正常起搏点；房室交界约 50 次/分、浦肯野纤维约 25~40 次/分，在正常情况下受窦房结“超速驱动”抑制（超速驱动压抑），只在窦房结功能低下时作为潜在起搏点（异位心律）。迷走神经兴奋使窦房结自律性降低（心率减慢），交感神经使其升高。"},{"id":"16.5","t":"传导性","s":3,"c":"16. 心肌电生理","x":"（1）心房内传导：经心房肌与结间束（约 0.3 m/s），0.06~0.1 s 传遍两心房；（2）房室交界传导最慢（约 0.02~0.05 m/s），形成房室延搁（0.1 s），保证心房收缩后心室才收缩、心室有充分充盈时间；（3）浦肯野纤维传导最快（2~4 m/s），保证两心室同步收缩。房室交界是正常兴奋由心房传入心室的唯一通路，故房室传导阻滞可致心室停搏。"},{"id":"16.6","t":"心肌收缩性与钙触发钙释放","s":3,"c":"16. 心肌电生理","x":"心肌 2 期 Ca²⁺ 内流触发肌浆网 RyR2 释放 Ca²⁺（CICR，钙触发钙释放），胞质 Ca²⁺ 升高 10 倍以上，与肌钙蛋白 C 结合引起收缩。心肌收缩依赖胞外 Ca²⁺，低钙时收缩减弱（钙反常）；交感神经通过 β1 受体增加 L 型 Ca²⁺通道磷酸化，增强收缩力（等长自身调节）；洋地黄抑制 Na⁺/K⁺-ATP 酶，使胞内 Na⁺ 升高、经 NCX 排出减少，间接提高胞内 Ca²⁺ 而增强心肌收缩力。"},{"id":"16.7","t":"心肌电生理与骨骼肌的比较","s":2,"c":"16. 心肌电生理","x":"（1）心肌有平台期、动作电位时程长（200~300 ms 对 2~5 ms）；（2）心肌有效不应期特别长，不产生强直收缩；（3）心肌为功能性合胞体，闰盘缝隙连接使兴奋同步；（4）心肌有自律性，骨骼肌无（除受神经支配外）；（5）心肌收缩依赖胞外 Ca²⁺（CICR），骨骼肌主要靠肌浆网（机械耦联）。细胞类型4 期自动去极0 期离子平台期自律性心室肌工作细胞无Na⁺ 内流有无心房肌工作细胞无Na⁺ 内流有（较短）无窦房结 P 细胞有（If）Ca²⁺ 内流无最高（100 次/分）房室交界细胞有Ca²⁺ 内流无50 次/分浦肯野纤维有Na⁺ 内流有25~40 次/分"},{"id":"17.1","t":"心电图的原理与导联","s":3,"c":"17. 心电图","x":"心电图记录体表两点间的电位差随时间变化，反映整个心脏兴奋的产生、传导与恢复过程。常用 12 导联：标准肢体导联 I、II、III，加压单极肢体导联aVR、aVL、aVF，胸前导联 V1~V6。心电图只反映电活动，不能直接反映机械收缩（如心肌收缩力），但可判断心律失常、心肌缺血与梗死、心房心室肥大及电解质紊乱（高钾时 T 波高尖、QRS 增宽）。"},{"id":"17.2","t":"各波的意义","s":3,"c":"17. 心电图","x":"P 波：两心房去极，历时 0.08~0.11 s，振幅 <0.25 mV；QRS 波群：两心室去极，历时 0.06~0.10 s；T 波：心室复极，方向与 QRS 主波一致，历时0.05~0.25 s；PR 间期（P 起点至 Q 起点）：0.12~0.20 s，反映房室传导时间；QT 间期：0.32~0.44 s，反映心室去极与复极总时间（与心率有关，心率快则缩短）；ST 段：反映心室缓慢复极，正常应位于等电位线。"},{"id":"17.3","t":"心电图的形成机制","s":2,"c":"17. 心电图","x":"心电图是大量心肌细胞电活动的代数和。P 波与心房去极对应（心房肌动作电位无长平台）；QRS 波群对应心室去极（快速、同步）；T 波对应心室复极（复极顺序与去极相反，从心外膜向心内膜推进，故 T 波方向与 QRS 主波同向）；心房复极波（Ta 波）被 QRS 掩盖。心室肌复极缓慢（平台期）是 T波低平宽大的原因。"},{"id":"17.4","t":"心电图的异常","s":2,"c":"17. 心电图","x":"（1）心律失常：房颤时 P 波消失代以 f 波、RR 间期绝对不齐；室性早搏为宽大畸形 QRS 无前导 P 波；房室传导阻滞表现为 PR 间期延长或 P 波后QRS 脱落；（2）心肌梗死：ST 段抬高（急性期）、病理性 Q 波、T 波倒置；（3）高钾血症：T 波高尖、QRS 增宽、P 波低平，严重时正弦波；（4）低钾血症：T 波低平、U 波明显；（5）低钙：QT 延长。"},{"id":"17.5","t":"心电与心音、心动周期的对应","s":2,"c":"17. 心电图","x":"心电图 P 波约在心房收缩前出现；QRS 波群起始略早于第一心音（心室开始收缩）；T 波结束约对应第二心音（心室舒张开始）。心电变化先于机械活动，故心电图上 QRS 出现后才有心室压力升高与瓣膜关闭。这一顺序关系是理解“电-机械耦联”和判断心律失常血流动力学后果的基础。"},{"id":"17.6","t":"心输出量的测量与心功能评价","s":1,"c":"17. 心电图","x":"经典方法为 Fick 原理：心输出量 = 每分氧耗量/(动脉血氧含量 - 静脉血氧含量)；临床多用超声心动图测心室舒张末期与收缩末期容积计算每搏量，或用染料稀释法、热稀释法。评价心功能还可测射血分数、心指数、BNP/NTproBNP（心室壁张力增高时分泌，心衰标志物）和心肌酶（肌钙蛋白 I/T 为心肌损伤特异性指标）。"},{"id":"18.1","t":"各类血管的功能特点","s":3,"c":"18. 血管生理","x":"（1）弹性贮器血管（主动脉、肺动脉大动脉）：管壁厚、弹性纤维多，缓冲收缩压、维持舒张压，使血流连续；（2）分配血管（中等动脉）：将血液分配至各器官；（3）阻力血管（小动脉、微动脉）：口径小、阻力大，是外周阻力的主要来源（约占 50%），调节器官血流量与血压；（4）交换血管（毛细血管）：管壁薄、仅一层内皮，是物质交换场所；（5）容量血管（静脉）：数量多、口径大、顺应性高，容纳 60%~70% 血量；（6）短路血管（动静脉吻合）：参与体温调节。"},{"id":"18.2","t":"动脉血压的形成与正常值","s":3,"c":"18. 血管生理","x":"动脉血压形成的四个条件：足够的血液充盈（循环系统平均充盈压约 7 mmHg）、心脏射血（提供能量）、外周阻力（使血液滞留于动脉）、大动脉弹性（缓冲）。我国成人收缩压 90~140 mmHg、舒张压 60~90 mmHg，脉压 30~40 mmHg，平均动脉压 ≈ 舒张压 + 1/3 脉压（约 100 mmHg）。血压随年龄升高，男性略高于女性，运动、情绪、体位（立位高于卧位）均影响血压。"},{"id":"18.3","t":"影响动脉血压的因素","s":3,"c":"18. 血管生理","x":"（1）每搏输出量：主要影响收缩压（搏出量增加→收缩压明显升高、脉压增大）；（2）心率：主要影响舒张压（心率加快→舒张期缩短、舒张压升高、脉压减小）；（3）外周阻力：主要影响舒张压（阻力增大→舒张压升高、脉压减小）；（4）大动脉弹性：弹性降低（老年）时收缩压升高、舒张压降低、脉压增大；（5）循环血量与血管容积的匹配：失血时血压下降。"},{"id":"18.4","t":"静脉血压与静脉回流","s":2,"c":"18. 血管生理","x":"中心静脉压（CVP）指右心房与胸腔内大静脉的血压，正常 4~12 cmH₂O，反映心脏射血能力与血容量，是临床补液的重要指标。影响静脉回流的因素：（1）体循环平均充盈压（血量决定）；（2）心脏收缩力（心衰时回流受阻）；（3）体位（直立时下肢静脉淤血）；（4）骨骼肌泵（肌肉收缩挤压静脉，静脉瓣防止倒流）；（5）呼吸泵（吸气时胸内负压增大使腔静脉回流增加）；（6）静脉瓣与静脉张力。"},{"id":"18.5","t":"血流阻力与泊肃叶定律","s":3,"c":"18. 血管生理","x":"血流阻力 R = 8ηL/(πr⁴)，与血液黏滞性 η 和血管长度 L 成正比，与血管半径的 4 次方成反比，故口径缩小一半阻力增大 16 倍（这是小动脉调节血压的关键）。血流量 Q = ΔP/R。全身体循环总外周阻力约 1.0~1.2 外周阻力单位（PRU）。层流时血管中心流速快、边缘慢；流速过快或口径突变时出现湍流（可听到杂音）。"},{"id":"18.6","t":"血流速度与微循环","s":3,"c":"18. 血管生理","x":"血流速度与血管总横截面积成反比：主动脉 40~50 cm/s（横截面积 2.5 cm²）→ 小动脉 → 毛细血管 0.03 cm/s（总横截面积约 2 500 cm²）→ 静脉逐渐加快，腔静脉约 15 cm/s。毛细血管缓慢血流利于物质交换。微循环由微动脉、后微动脉、毛细血管前括约肌、真毛细血管、通血毛细血管、动静脉吻合支和微静脉组成，有三条通路：迂回通路（物质交换）、直捷通路（血液快速回流）、动静脉短路（体温调节）。微循环的血流由局部代谢产物（组胺、腺苷、CO₂、H⁺、K⁺）与缺氧调节毛细血管前括约肌的舒缩，约每 2~8 秒交替开放。"},{"id":"18.7","t":"组织液的生成与淋巴回流","s":3,"c":"18. 血管生理","x":"有效滤过压 = （毛细血管血压 + 组织液胶体渗透压）-（血浆胶体渗透压 +组织液静水压）。动脉端约 +10 mmHg（滤过），静脉端约 -8 mmHg（重吸收），滤过略大于重吸收，多余的约 10% 组织液经淋巴管回流。水肿机制：（1）毛细血管血压升高（心衰、静脉阻塞）；（2）血浆胶体渗透压降低（营养不良、肾病综合征、肝病）；（3）淋巴回流受阻（丝虫病、淋巴结切除）；（4）毛细血管通透性增高（炎症、过敏）。淋巴回流还有脂肪吸收（乳糜管）、免疫与清除异物的功能。"},{"id":"18.8","t":"器官循环的特点","s":2,"c":"18. 血管生理","x":"（1）冠脉循环：血流量约 225 mL/min（占心输出量的 4%~5%），舒张期为主，动静脉血氧差最大（心肌摄氧率约 70%~80%），故心肌缺血时主要靠扩张冠脉而非增加摄氧；代谢产物（腺苷）是主要调节因素。（2）肺循环：低压（肺动脉压约 22/8 mmHg）、低阻、血流量大、血管顺应性高，参与血液储存；（3）脑循环：血流量约 750 mL/min，存在血脑屏障，脑血管在60~140 mmHg 灌注压下恒定，主要受 CO₂ 分压（PaCO₂ 升高使脑血管扩张）调节；（4）皮肤循环：参与体温调节。血管类型主要功能特点大动脉弹性贮器缓冲脉压、连续血流小动脉、微动脉阻力血管外周阻力主要来源毛细血管交换血管单层内皮、总横截面积最大静脉容量血管容纳 60%~70% 血量动静脉吻合短路血管体温调节"},{"id":"19.1","t":"神经调节的神经支配","s":3,"c":"19. 心血管活动的调节","x":"心脏受心交感神经（发自脊髓胸 1~5 侧角，末梢释放去甲肾上腺素，作用于 β1 受体，使心率加快、传导加速、收缩力增强，即“三正”）与心迷走神经（发自延髓疑核与背核，末梢释放 ACh，作用于 M 受体，使心率减慢、传导减慢、心房收缩力减弱，即“三负”，对心室肌影响小）双重支配。血管受交感缩血管神经（释放 NE，作用于 α 受体使血管收缩，体内多数血管只受交感缩血管神经支配）与舒血管神经（如支配骨骼肌的胆碱能交感舒血管神经、面神经与舌咽神经中的副交感舒血管纤维）支配。"},{"id":"19.2","t":"心血管中枢","s":3,"c":"19. 心血管活动的调节","x":"最基本的心血管中枢位于延髓，包括心交感中枢、心迷走中枢、缩血管中枢和舒血管中枢。延髓心血管中枢的紧张性活动受下丘脑、大脑皮质、小脑及外周传入（压力感受器、化学感受器）的调节。下丘脑是心血管活动的重要整合中枢（与体温、摄食、情绪、应激反应整合）；大脑皮质（边缘系统）参与情绪性心血管反应（如紧张时心率加快）。"},{"id":"19.3","t":"压力感受器反射（减压反射）","s":3,"c":"19. 心血管活动的调节","x":"感受器为颈动脉窦与主动脉弓血管壁外膜下的压力感受器（颈动脉窦由窦神经即舌咽神经传入，主动脉弓由降压神经即迷走神经传入）。血压升高使血管壁被牵张 → 传入冲动增多 → 延髓心迷走中枢兴奋、心交感中枢与缩血管中枢抑制 → 心率减慢、心肌收缩力减弱、血管舒张、外周阻力下降 → 血压回降。特点：负反馈；在 60~180 mmHg 范围内工作，最敏感于 100 mmHg 附近，属“缓冲”而非“维持”（不参与 24 小时血压长期水平决定）。血压持续升高时感受器发生适应（重调）。心肺容量感受器（低压力感受器）参与容量与血容量调节。"},{"id":"19.4","t":"化学感受器反射","s":3,"c":"19. 心血管活动的调节","x":"颈动脉体（由颈内、外动脉分叉处的迷走神经分支即窦神经传入）与主动脉体（经减压神经传入）为外周化学感受器，感受 PaO₂（需低于 60 mmHg才显著兴奋）、PaCO₂ 升高与 H⁺ 浓度升高，冲动传入延髓兴奋呼吸与心血管中枢。中枢化学感受器位于延髓腹外侧浅表部，对 CO₂（通过 H⁺）敏感，不感受低氧。低氧直接抑制中枢、兴奋外周，故窒息时先兴奋后抑制。轻度缺氧以化学感受器反射为主。"},{"id":"19.5","t":"肾素-血管紧张素-醛固酮系统","s":3,"c":"19. 心血管活动的调节","x":"肾血流量减少、肾小管远端 Na⁺ 量减少或交感神经兴奋时，肾小球旁器的球旁细胞分泌肾素（蛋白水解酶），将肝产生的血管紧张素原转为血管紧张素I（10 肽），经肺循环中血管紧张素转换酶（ACE）转为血管紧张素 II（8肽），后者：强烈收缩全身小动脉；刺激醛固酮分泌（保 Na⁺ 排 K⁺，增加血容量）；促进 ADH 分泌与渴觉；促进交感末梢释放 NE。血管紧张素 II 经氨基肽酶作用成为血管紧张素 III，仍有刺激醛固酮的作用，但缩血管作用减弱。ACE 抑制剂（卡托普利）是降压药的重要靶点。"},{"id":"19.6","t":"肾上腺素与去甲肾上腺素","s":3,"c":"19. 心血管活动的调节","x":"两者均由肾上腺髓质（受交感节前纤维支配）分泌（肾上腺素约占80%）。肾上腺素对 α、β 受体都有强作用（β 作用更强）：强心（心率加快、心肌收缩力增强、心输出量增加）、使骨骼肌与肝血管扩张、皮肤内脏血管收缩，总外周阻力变化不大，故临床作为强心药、抢救心搏骤停。去甲肾上腺素主要激动 α 受体：使全身小动脉强烈收缩、外周阻力明显升高、血压上升，同时因压力感受器反射使心率减慢，临床用作升压药。两者均促进糖原与脂肪分解，参与应激。"},{"id":"19.7","t":"其他体液因素与局部血流调节","s":2,"c":"19. 心血管活动的调节","x":"（1）血管升压素（ADH）：大剂量时收缩血管；（2）心房钠尿肽（ANP）：心房牵张时释放，利钠排尿、舒张血管、抑制肾素与醛固酮；（3）局部舒血管物质：腺苷（冠脉）、NO（内皮舒张因子，由 L-精氨酸经NOS 生成，激活鸟苷酸环化酶使 cGMP 升高）、前列环素（PGI2）、组胺（炎症与过敏）、缓激肽；（4）局部缩血管物质：内皮素（ET-1，最强的缩血管物质）、TXA2、5-HT；（5）动脉血 CO₂ 升高使脑血管扩张，O₂ 降低使冠脉与脑血管扩张。"},{"id":"19.8","t":"动脉血压的长期调节","s":2,"c":"19. 心血管活动的调节","x":"短时调节靠压力感受器反射与化学感受器反射（秒至分钟）；中期靠RAAS 与毛细血管液体转移（数分钟至数小时）；长期调节主要靠肾脏对水钠排出的调节（数小时至数日）：血压升高 → 肾灌注压升高 → 尿钠排出增加（压力-利尿钠）→ 血容量下降 → 血压回降。因此肾脏是动脉血压长期水平的最终决定者，这也是慢性高血压与肾功能密切相关的原因。运动时还通过局部代谢性舒血管与交感神经的“再分布”作用，使肌肉血流增加而内脏血流减少。调节因素来源/感受器主要效应减压反射颈动脉窦、主动脉弓血压升高时反射性降压化学感受器反射RAAS颈动脉体、主动脉体低氧、高 CO₂ 时升压并兴奋呼吸肾小球旁器释放肾素缩血管、保钠排钾、升高血压肾上腺素肾上腺髓质强心、增心输出量去甲肾上腺素ADH交感末梢、髓质缩血管、升外周阻力下丘脑视上核、室旁核抗利尿、大剂量升压ANP心房肌利钠排尿、舒张血管肾上腺素以外的局部因素内皮、代谢产物NO、腺苷舒血管，ET-1 缩血管第三篇 呼吸"},{"id":"20.1","t":"呼吸道的结构与功能","s":3,"c":"20. 呼吸道与肺通气","x":"呼吸道包括鼻、咽、喉（上呼吸道）和气管、支气管及分支（下呼吸道）。功能：（1）通气管道；（2）加温、湿润、过滤清洁（鼻甲黏膜、黏液纤毛运输系统，纤毛摆动频率约 1 000~1 500 次/分，将黏液送至咽部咳出或咽下）；（3）免疫防御（分泌型 IgA、溶菌酶、肺泡巨噬细胞）；（4）发声与嗅觉。从气管到终末细支气管的 16 级为传导区，不参与气体交换，其容积约150 mL 称解剖无效腔。"},{"id":"20.2","t":"气道阻力","s":2,"c":"20. 呼吸道与肺通气","x":"气道阻力占呼吸总阻力的 80%~90%，健康人约 1~3 cmH₂O/(L·s)。阻力与半径的 4 次方成反比，故口径变化影响巨大：交感神经与肾上腺素使支气管平滑肌舒张（β2 受体）；副交感（迷走）神经、组胺、5-HT、白三烯、冷空气使支气管收缩（哮喘时阻力显著增加，呼气性呼吸困难）。跨肺压增大时气道扩张，用力呼气时胸内压升高可压迫小气道（肺气肿时更明显）。"},{"id":"20.3","t":"呼吸运动","s":3,"c":"20. 呼吸道与肺通气","x":"平静呼吸时吸气为主动过程：膈肌收缩（贡献约 75%）使膈顶下移 1~2 cm（深吸气可达 7~10 cm）、肋间外肌收缩使肋骨上提外展，胸廓容积增大；呼气为被动过程，靠肺与胸廓的弹性回缩。用力呼吸时吸气还有胸锁乳突肌、斜角肌参与，呼气有腹肌与肋间内肌参与。呼吸频率成人 12~18 次/分（潮气量 500 mL），儿童较快。"},{"id":"20.4","t":"肺内压与胸膜腔内压","s":3,"c":"20. 呼吸道与肺通气","x":"肺内压（肺泡内压）平静吸气初约 -1~-2 mmHg（低于大气压，气体入肺），吸气末等于大气压；呼气初约 +1~+2 mmHg，呼气末等于大气压。胸膜腔内压 = 肺内压 - 肺回缩力，平静呼吸时始终为负压（吸气末约 -5~-6 mmHg，呼气末约 -2~-3 mmHg，即 -0.4~-0.8 kPa），其意义：（1）使肺保持扩张状态；（2）促进静脉血与淋巴液回流（吸气时负压增大，回心血量增加）；（3）有利于呕吐、排便。胸膜腔密闭性破坏（气胸）时负压消失、肺塌陷。"},{"id":"20.5","t":"肺泡表面活性物质","s":3,"c":"20. 呼吸道与肺通气","x":"由肺泡 II 型上皮细胞分泌，主要成分为二棕榈酰卵磷脂（DPPC）与表面活性蛋白（SP-A~D）。作用：（1）降低肺泡表面张力，防止肺泡萎陷（Laplace 定律 P=2T/r，若无活性物质小肺泡将向大肺泡排空）；（2）减少肺间质与肺泡内液体渗出（防止肺水肿）；（3）降低吸气阻力，增加肺顺应性。新生儿呼吸窘迫综合征即因缺乏表面活性物质；糖皮质激素可促进其合成。"},{"id":"20.6","t":"肺容积与肺容量","s":3,"c":"20. 呼吸道与肺通气","x":"潮气量 500 mL（400~600 mL）；补吸气量 1 500~2 000 mL；补呼气量900~1 200 mL；余气量（残气量）1 000~1 500 mL（不能呼出，与功能余气量共同维持肺泡气成分稳定）。肺活量 = 潮气量 + 补吸气量 + 补呼气量，男性约 3 500 mL、女性约 2 500 mL；肺活量不包含余气量，故不能反映全部肺容积。功能余气量 = 余气量 + 补呼气量 ≈ 2 500 mL；肺总容量 = 肺活量 + 余气量 ≈ 5 000 mL。用力肺活量与时间肺活量（FEV1 约占 83%，FEV2 96%，FEV3 99%）更能反映气道阻塞。"},{"id":"20.7","t":"肺通气量","s":3,"c":"20. 呼吸道与肺通气","x":"每分通气量 = 潮气量 × 呼吸频率 = 500 × 12~18 ≈ 6~9 L/min；最大随意通气量可达 120~170 L/min，是评价通气储备的指标。肺泡通气量 = （潮气量 - 无效腔气量）× 频率，无效腔约 150 mL，故 = (500-150)×12 ≈ 4.2 L/min，约占每分通气量的 70%。浅快呼吸时无效腔所占比例增大，肺泡通气量下降（如潮气量 250 mL、频率 24 次/分，每分通气量仍为 6 L，但肺泡通气量仅 2.4 L），故深慢呼吸效率更高。"},{"id":"20.8","t":"肺通气/血流比值","s":3,"c":"20. 呼吸道与肺通气","x":"每分钟肺泡通气量约 4.2 L，肺血流量约 5 L/min，故 V/Q 比值为 0.84（0.8~0.85）。比值增大（如肺栓塞、心输出量减少）相当于肺泡无效腔增大（死腔样通气），部分肺泡通气被浪费；比值减小（如支气管痉挛、肺不张、肺水肿）相当于功能性分流，部分静脉血未经氧合即回流入动脉（静脉血掺杂），导致低氧血症。肺上部 V/Q 较大（约 3.3）、下部较小（约 0.6）。指标正常值说明潮气量500 mL平静呼吸每次通气量肺活量（男/女）3 500/2 500 mL不含余气量余气量1 000~1 500 mL不能呼出功能余气量约 2 500 mL缓冲肺泡气成分解剖无效腔约 150 mL 6~9 L/min传导气道容积约 4.2 L/min 0.84 (潮气量-无效腔)×频率每分通气量肺泡通气量V/Q 比值潮气量×频率增大为死腔样通气"},{"id":"21.1","t":"气体分压与溶解","s":3,"c":"21. 气体交换","x":"气体交换的动力是分压差。海平面大气压 760 mmHg，PO₂ 159 mmHg、PCO₂ 0.3 mmHg；吸入气道后饱和水蒸气（47 mmHg），PO₂ 降至 149 mmHg；肺泡气 PO₂ 约 102 mmHg、PCO₂ 约 40 mmHg；动脉血PO₂ 100 mmHg、PCO₂ 40 mmHg；混合静脉血 PO₂ 40 mmHg、PCO₂ 46 mmHg。气体在液体中的溶解量 = 溶解度 × 分压（Henry 定律），CO₂ 溶解度约为 O₂ 的 24 倍，故同等分压下 CO₂ 弥散量更大。"},{"id":"21.2","t":"肺换气与组织换气","s":3,"c":"21. 气体交换","x":"肺换气：肺泡气与肺毛细血管血之间经呼吸膜（肺泡表面液层、肺泡上皮、上皮基底膜、间质、毛细血管基底膜、内皮）交换，膜厚仅 0.2~0.6 μm、面积约 70 m²，O₂ 由肺泡（102 mmHg）扩散入血至 100 mmHg，CO₂ 由血（46 mmHg）扩散至肺泡（40 mmHg），血液流经肺毛细血管约 0.75 s 即完成氧合（通常 0.25 s 已平衡，储备大）。组织换气：动脉血 O₂ 扩散入组织（细胞内 PO₂ 可低至 5~20 mmHg），CO₂ 入血。"},{"id":"21.3","t":"影响气体交换的因素","s":3,"c":"21. 气体交换","x":"（1）分压差：高原低氧、通气不足时肺泡 PO₂ 下降；（2）呼吸膜面积与厚度：肺气肿面积减小，肺水肿、纤维化厚度增加（弥散量降低）；（3）通气血流比值失调；（4）温度与溶解度；（5）气体分子量（Graham 定律，弥散速率 ∝ 溶解度/√分子量）；（6）血液与肺泡接触时间（运动时血流加快，接触时间缩短至 0.3 s 仍可代偿）。"},{"id":"21.4","t":"氧与二氧化碳弥散量的差异","s":2,"c":"21. 气体交换","x":"安静时肺的 O₂ 弥散容量约 20~30 mL/(min·mmHg)（教材通行值），CO₂ 约 400~500 mL/(min·mmHg)，CO₂ 的弥散能力约为 O₂ 的 20 倍。原因：CO₂ 在血浆中溶解度大、且可与水生成 HCO₃⁻ 不断被“消耗”，维持分压差。故临床上弥散功能障碍时先出现低氧血症而非高碳酸血症（CO₂ 弥散储备大）。"},{"id":"21.5","t":"肺泡气成分的稳定","s":2,"c":"21. 气体交换","x":"肺泡气 PO₂ 约 102 mmHg、PCO₂ 约 40 mmHg，其稳定依赖：（1）功能余气量的缓冲（每次呼吸仅更新肺泡气的 1/7 左右）；（2）连续通气与肺血流的匹配；（3）组织代谢率与呼吸、循环的协同调节。过度通气使肺泡与动脉PCO₂ 降低（呼吸性碱中毒），通气不足则 CO₂ 蓄积（呼吸性酸中毒）。吸入气中 O₂ 浓度升高至 100% 时，动脉血氧含量仅增加约 1.5~2 mL/dL（因 Hb已近饱和），故高压氧主要用于提高溶解氧。"},{"id":"21.6","t":"运动与高原时的气体交换","s":2,"c":"21. 气体交换","x":"运动时摄氧量可从 250 mL/min 增至 3 000~6 000 mL/min，靠增加通气量、心输出量（肌肉血流增加 4~5 倍）与组织摄取率（动静脉氧差由 5 mL/dL增至 15 mL/dL）实现；此时肺弥散容量由约 20 mL/(min·mmHg) 增至40~50 mL/(min·mmHg)，动脉血氧饱和度仍可维持 95% 以上。高原低氧（PaO₂ 下降）时先经化学感受器使通气增加（PaCO₂ 随之降低、pH 升高，形成呼吸性碱中毒，可经肾排 HCO3- 代偿），随后 2,3-DPG 增多使氧解离曲线右移、EPO 升高使红细胞与 Hb 增加、毛细血管增生、线粒体氧化酶活性提高；适应不良者可发生高原肺水肿（肺毛细血管压升高、通透性增加）与高原脑水肿。"},{"id":"22.1","t":"氧在血液中的存在形式","s":3,"c":"22. 氧的运输","x":"物理溶解氧仅占 1.5%（约 0.3 mL/dL），与 Hb 化学结合的氧占 98.5%（约 19.4 mL/dL）。氧容量指 100 mL 血中 Hb 能结合的最大 O₂ 量（约 20 mL/dL），氧含量为实际含量，氧饱和度为氧含量/氧容量 × 100%（动脉血约97%~98%，静脉血约 75%）。每克 Hb 结合 1.34~1.36 mL O₂，故 Hb 浓度直接决定氧容量。"},{"id":"22.2","t":"Hb 与 O₂ 结合的特征","s":3,"c":"22. 氧的运输","x":"（1）可逆、不需酶、迅速（毫秒级）；（2）Fe²⁺ 与 O₂ 结合后仍为二价（氧合而非氧化）；（3）呈氧合血红蛋白（HbO₂，鲜红）与去氧血红蛋白（暗红、紫蓝，故缺氧时发绀）；（4）结合时 1 个 O₂ 结合后促进其余亚基结合（正协同效应），故氧解离曲线呈 S 形；（5）受 CO₂、H⁺、温度、2,3DPG 调节。"},{"id":"22.3","t":"氧解离曲线的形态与意义","s":3,"c":"22. 氧的运输","x":"以 PO₂ 为横坐标、氧饱和度为纵坐标，曲线呈 S 形，P50 约 26.5 mmHg。上段（PO₂ 60~100 mmHg）：曲线平坦，PO₂ 从 100 降至 60 mmHg 时饱和度仅从 97% 降至 90%，保证肺部 PO₂ 波动时血液仍能携带足够 O₂；中段（40~60 mmHg）：较陡，组织 PO₂ 在此区间变化时释放 O₂ 明显；下段（15~40 mmHg）：最陡，PO₂ 稍降即大量解离，保证组织活动时供氧。曲线右移表示亲和力降低、释放氧增多（P50 增大）；左移相反。"},{"id":"22.4","t":"影响氧解离曲线的因素","s":3,"c":"22. 氧的运输","x":"右移（释放 O₂ 增多）：PCO₂ 升高、H⁺ 浓度升高（pH 降低）、温度升高、2,3-DPG 增多、ATP 增多。左移（亲和力升高、不利于释放）：PCO₂ 降低、pH 升高、温度降低、2,3-DPG 减少、COHb 与 HbF、老年红细胞。运动时肌肉局部 CO₂、H⁺、温度均升高，曲线右移促进供氧，此为适应性意义。"},{"id":"22.5","t":"波尔效应与霍尔丹效应","s":3,"c":"22. 氧的运输","x":"波尔效应：pH 降低或 PCO₂ 升高使 Hb 对 O₂ 亲和力降低（曲线右移），意义是组织代谢产生的 CO₂ 与 H⁺ 促进 O₂ 释放；在肺部则相反，CO₂ 排出使曲线左移，促进 O₂ 结合。霍尔丹效应：O₂ 与 Hb 结合促进 CO₂ 释放（在肺部），去氧 Hb 更易结合 CO₂ 与 H⁺（在组织），两者互为配合，提高气体运输效率。"},{"id":"22.6","t":"2,3-二磷酸甘油酸（2,3-DPG）","s":2,"c":"22. 氧的运输","x":"2,3-DPG 是红细胞糖酵解（Rapoport-Luebering 支路）的中间产物，与去氧 Hb 结合降低其氧亲和力，使曲线右移。高原低氧、贫血、慢性缺氧时2,3-DPG 升高，有利于组织供氧（但过量时又可妨碍肺部氧合）。库血保存1~2 周后 2,3-DPG 明显下降，曲线左移，大量输库血可影响组织供氧。"},{"id":"22.7","t":"一氧化碳中毒","s":3,"c":"22. 氧的运输","x":"CO 与 Hb 亲和力约为 O₂ 的 210~250 倍，且 COHb 一旦形成难以解离（解离速度极慢）。CO 中毒特点：（1）血液氧容量下降（Hb 被占据）；（2）CO 使剩余 Hb 对 O₂ 亲和力升高（曲线左移），组织释放 O₂ 困难；（3）动脉血 PO₂ 正常（故不出现发绀，皮肤呈樱桃红色，易误诊）；（4）治疗为吸入纯氧或高压氧（提高溶解氧、加速 CO 解离）。CO 还抑制细胞色素氧化酶。"},{"id":"22.8","t":"胎儿血红蛋白与肌红蛋白","s":2,"c":"22. 氧的运输","x":"胎儿血红蛋白（HbF，α2γ2）对 2,3-DPG 结合能力弱，氧亲和力高于成人 HbA（α2β2），P50 较低，有利于经胎盘从母血中摄取 O₂。肌红蛋白（Mb）含 1 个血红素，P50 约 2~3 mmHg，氧亲和力远高于 Hb，负责在肌细胞内储存与转运 O₂，故肌肉呈红色；潜水哺乳动物（鲸、海豹）肌肉中 Mb含量极高，利于长时间潜水。因素曲线移位对 O₂ 亲和力对组织供氧PCO₂ 升高右移降低增加pH 降低（H⁺ 升高）右移降低增加温度升高右移降低增加2,3-DPG 增多右移降低增加pH 升高、温度降低左移升高减少CO 中毒左移升高减少高原缺氧（DPG 增多）右移降低增加"},{"id":"23.1","t":"CO₂ 的运输形式","s":3,"c":"23. 二氧化碳的运输与酸碱平衡","x":"（1）物理溶解：约占 5%~7%；（2）氨基甲酰血红蛋白（HbNHCOOH）：约占 7%，CO₂ 与 Hb 的 α-氨基结合，受氧合状态调节（霍尔丹效应）；（3）碳酸氢盐（HCO₃⁻）：约占 88%，为主要形式，在红细胞内由碳酸酐酶催化 CO₂ + H₂O → H2CO3 → H⁺ + HCO₃⁻，HCO₃⁻ 顺浓度梯度扩散入血浆，同时 Cl⁻ 进入红细胞（氯转移），H⁺ 由 Hb 缓冲。"},{"id":"23.2","t":"碳酸酐酶与氯转移","s":3,"c":"23. 二氧化碳的运输与酸碱平衡","x":"碳酸酐酶（CA）主要存在于红细胞内（碳酸酐酶 II），催化 CO₂ 水化反应速率提高约 10⁴~10⁶ 倍，是 CO₂ 运输的关键酶。氯转移：HCO₃⁻ 出红细胞时 Cl⁻ 经 Band 3 阴离子交换蛋白进入，保持电中性并维持 CO₂ 持续摄取能力。组织中此过程向生成 HCO₃⁻ 方向进行，肺部则反向（HCO₃⁻ 进入红细胞、生成 CO₂ 呼出）。碳酸酐酶抑制剂（乙酰唑胺）可抑制此过程，用于治疗高原反应与青光眼。"},{"id":"23.3","t":"酸碱平衡的调节机制","s":3,"c":"23. 二氧化碳的运输与酸碱平衡","x":"（1）血液缓冲系统：NaHCO3/H2CO3 最重要（比值 20∶1，HCO₃⁻ 正常 22~27 mmol/L，H2CO3 由 PCO₂×0.03 计算），Hb 缓冲对、磷酸盐、血浆蛋白；（2）呼吸调节：PaCO₂ 升高或 pH 下降刺激外周与中枢化学感受器，通气量增加排出 CO₂（数分钟起效，为快速调节）；（3）肾调节：近端小管重吸收约 85% 的 HCO₃⁻，远端小管与集合管泌 H⁺ 与 NH₄⁺（泌 NH₃ 缓冲，可排 H⁺ 而不伴 HCO₃⁻ 丢失），泌 H⁺ 与泌 K⁺ 竞争（酸中毒时血 K⁺ 升高），数小时至数日见效，为慢而彻底的调节。"},{"id":"23.4","t":"酸碱失衡的类型","s":2,"c":"23. 二氧化碳的运输与酸碱平衡","x":"呼吸性酸中毒：通气不足（COPD、窒息、呼吸抑制），PaCO₂ 升高、HCO₃⁻ 代偿性升高；呼吸性碱中毒：过度通气（高原、癔症、发热），PaCO₂降低。代谢性酸中毒：固定酸产生过多（糖尿病酮症、乳酸酸中毒、尿毒症）或 HCO₃⁻ 丢失（严重腹泻），HCO₃⁻ 降低，代偿性呼吸加深加快（Kussmaul 呼吸）；代谢性碱中毒：剧烈呕吐丢失胃酸、大量用利尿剂，HCO₃⁻ 升高。pH 7.35~7.45 内为代偿性，超出则为失代偿。"},{"id":"23.5","t":"酸碱平衡与电解质、呼吸的相互作用","s":2,"c":"23. 二氧化碳的运输与酸碱平衡","x":"（1）H⁺ 与 K⁺ 的竞争：酸中毒时 H⁺ 进入细胞、K⁺ 出细胞，引起高钾血症；碱中毒引起低钾血症；反之，低钾血症时可引起代谢性碱中毒（细胞内H⁺ 进入、H⁺ 排出增多）。（2）CO₂ 与脑脊液：CO₂ 易透过血脑屏障，中枢化学感受器对 H⁺ 敏感，故 PaCO₂ 改变经脑脊液 pH 变化影响呼吸，但反应略滞后。（3）氯离子与 HCO₃⁻ 互相替代：低氯性碱中毒（呕吐）。"},{"id":"23.6","t":"缺氧的类型与呼吸反应","s":2,"c":"23. 二氧化碳的运输与酸碱平衡","x":"（1）低张性缺氧（高原、通气不足）：PaO₂ 降低，刺激外周化学感受器使通气增强；（2）血液性缺氧（贫血、CO 中毒、高铁血红蛋白血症）：PaO₂ 正常，不刺激化学感受器，故无通气增强，仅靠曲线右移代偿；（3）循环性缺氧（心衰、休克）：血流减少，动静脉氧差增大；（4）组织中毒性缺氧（氰化物抑制细胞色素氧化酶）。这四型区分是竞赛常考的辨析点。"},{"id":"24.1","t":"呼吸中枢","s":3,"c":"24. 呼吸的调节","x":"（1）脊髓：呼吸肌运动神经元所在，本身不能产生节律；（2）延髓：基本呼吸中枢所在，包括背侧呼吸组（DRG，孤束核附近，主要含吸气神经元，是产生基本节律的关键）、腹侧呼吸组（VRG，疑核与后疑核，含吸气与呼气神经元）、前包钦格复合体（pre-Bötzinger complex，现认为是最重要的呼吸节律起搏区）；（3）脑桥：调整中枢（臂旁内侧核与 Kölliker-Fuse 核，促进吸气向呼气转变）与长吸中枢；（4）高位脑：下丘脑、大脑皮质可随意调节呼吸。"},{"id":"24.2","t":"呼吸节律的形成","s":2,"c":"24. 呼吸的调节","x":"经典学说有“吸气切断机制”（吸气活动逐渐增强，达到阈值时切断吸气转为呼气）与“起搏神经元学说”（pre-Bötzinger complex 存在内在节律性放电的神经元）。目前认为两者结合：起搏神经元产生基本节律，网络中的抑制性与兴奋性连接（含 GABA 与甘氨酸能抑制、谷氨酸能兴奋）塑造呼吸的时相转换。呼吸节律由延髓产生，但受脑桥以上调制。"},{"id":"24.3","t":"肺牵张反射","s":3,"c":"24. 呼吸的调节","x":"（1）肺扩张反射（黑-伯反射，Hering-Breuer reflex）：肺扩张时气道平滑肌内牵张感受器受刺激，冲动经迷走神经传入延髓，抑制吸气神经原、切断吸气。成人阈值较高，平静呼吸时不参与，仅在潮气量 >1.5 L 时起作用；婴儿与动物较明显。（2）肺萎陷反射（肺缩小引起的吸气兴奋）：肺萎陷时兴奋吸气，防止肺不张。此外还有呼吸肌本体感受器反射（肋间肌肌梭）与 J 感受器（肺毛细血管旁感受器，肺水肿时引起急促浅快呼吸）。"},{"id":"24.4","t":"化学感受器与 CO₂ 的作用","s":3,"c":"24. 呼吸的调节","x":"中枢化学感受器位于延髓腹外侧浅表部，对 H⁺ 敏感而不直接感受 CO₂（CO₂ 透过血脑屏障后生成 H⁺），反应较慢但作用强（约占 CO₂ 通气效应的70%~80%）；外周化学感受器为颈动脉体与主动脉体，对 PaO₂ 降低（<60 mmHg）、PaCO₂ 升高、H⁺ 升高敏感，反应快。CO₂ 是调节呼吸最重要的生理性化学因素：吸入 CO₂ 浓度增至 2% 时通气量明显增加，4% 时倍增，超过7%~10% 则抑制中枢出现呼吸困难、头痛、意识模糊（CO₂ 麻醉）。"},{"id":"24.5","t":"低氧对呼吸的影响","s":3,"c":"24. 呼吸的调节","x":"低氧刺激外周化学感受器（颈动脉体为主）反射性兴奋呼吸，但低氧直接抑制中枢。PaO₂ 需降至 60~80 mmHg 以下才明显兴奋通气，降至 40 mmHg时通气量可达正常的 2 倍以上；严重低氧（PaO₂ <30 mmHg）时中枢抑制占优势，出现周期性呼吸甚至呼吸停止。慢性缺氧时外周化学感受器敏感性降低，故对慢性 CO₂ 潴留患者给高浓度氧要谨慎（可能抑制低氧驱动，导致呼吸抑制）。"},{"id":"24.6","t":"H⁺ 与呼吸","s":2,"c":"24. 呼吸的调节","x":"动脉血 H⁺ 浓度升高（pH 降低）主要刺激外周化学感受器，使通气量增加，CO₂ 排出增多，从而调节 pH（呼吸性代偿）。H⁺ 不易透过血脑屏障，故对中枢化学感受器作用弱而慢。代谢性酸中毒时因 H⁺ 刺激外周化学感受器及HCO₃⁻ 降低引起的代偿，出现深大呼吸（Kussmaul 呼吸）。"},{"id":"24.7","t":"运动时呼吸的变化与调节","s":2,"c":"24. 呼吸的调节","x":"运动时通气量可从 6 L/min 增至 80~100 L/min（甚至 150 L/min），与摄氧量、CO₂ 产生量成比例增加。调节因素：（1）神经机制：大脑皮质运动区的“前馈”冲动、肌肉与关节本体感受器传入；（2）体液机制：运动初期PaCO₂ 与 H⁺ 略升、体温升高、儿茶酚胺与乳酸；（3）动脉血 O₂ 与 CO₂ 的化学调节在中等强度以下并非主要，故“运动时呼吸增强完全由 CO₂ 升高引起”是错误的。运动后通气量逐渐恢复，并出现氧债偿还。化学因素主要感受器反应速度备注CO₂ 升高中枢（70%~80%）+ 外周中枢慢、外周快最重要生理调节因素H⁺ 升高外周为主快中枢作用弱（难透屏障）PaO₂ 降低外周（颈动脉体）快需 <60 mmHg 才明显运动（神经冲动）本体感受器、皮质即刻运动初期通气骤增第四篇 消化、吸收与代谢"},{"id":"25.1","t":"消化道平滑肌的一般特性","s":3,"c":"25. 消化道平滑肌的特性与运动形式","x":"（1）兴奋性较低、收缩缓慢（一次收缩数秒至数十秒）；（2）具有自动节律性，源于平滑肌本身的慢波与 Cajal 间质细胞（ICC，胃肠道的起搏细胞）；（3）富有伸展性，可容受大量食物而压力不显著升高；（4）紧张性（持续微弱收缩）维持胃肠形状与基础压力；（5）对化学、温度和牵张刺激敏感，对电刺激不敏感。"},{"id":"25.2","t":"慢波（基本电节律）","s":3,"c":"25. 消化道平滑肌的特性与运动形式","x":"消化道平滑肌静息电位 -50~-60 mV，其上叠加节律性去极化称慢波，由Cajal 间质细胞产生。频率：胃约 3 次/分、十二指肠约 12 次/分、回肠约 8~9次/分、结肠约 2~6 次/分（种属差异较大）。慢波本身不引起收缩，但决定动作电位出现的位点与时相，从而决定收缩的节律与最大频率。慢波频率异常是胃肠动力障碍的基础。"},{"id":"25.3","t":"消化道运动的神经与体液调节","s":3,"c":"25. 消化道平滑肌的特性与运动形式","x":"（1）内在神经丛：黏膜下神经丛（调节分泌与局部血流）与肌间神经丛（调节运动），构成“肠脑”，可在离体肠段完成局部反射；（2）外来神经：副交感（迷走、盆神经，ACh 兴奋运动与分泌）、交感（抑制运动、收缩括约肌）；（3）胃肠激素：胃动素（促进 MMC）、胃泌素（增强胃收缩）、CCK（抑制胃排空、促胆囊收缩）、促胰液素（抑制胃酸）、血管活性肠肽（舒张）、生长抑素（抑制）。"},{"id":"25.4","t":"消化道运动的形式","s":3,"c":"25. 消化道平滑肌的特性与运动形式","x":"（1）紧张性收缩：维持管腔内压与器官位置；（2）蠕动：由环形肌在纵行肌之后收缩形成，将内容物向前推进，速度 2~25 cm/s，可因食物性质改变；（3）分节运动：以环形肌为主的节律性收缩与舒张，使食糜与消化液充分混合而不推进，主要见于小肠；（4）容受性舒张：进食时胃底胃体肌肉反射性舒张，容纳食物而压力不升高（迷走神经肽能纤维、VIP 介导）；（5）移行性复合运动（MMC）：空腹时每 90~120 分钟一次的强力推进运动，起“清道夫”作用，由胃动素调节。"},{"id":"25.5","t":"括约肌及其功能","s":2,"c":"25. 消化道平滑肌的特性与运动形式","x":"消化道有食管下括约肌（LES，压力约 15~25 mmHg，防止胃内容物反流）、幽门括约肌（控制胃排空、防止十二指肠内容物反流）、回盲括约肌（防止结肠内容物反流入回肠、控制回肠排空）、肛门内（平滑肌、不随意）与外括约肌（骨骼肌、随意）。LES 张力降低引起反流性食管炎；幽门括约肌功能障碍可致胆汁反流性胃炎。"},{"id":"25.6","t":"消化液分泌的一般规律","s":2,"c":"25. 消化道平滑肌的特性与运动形式","x":"成人每日分泌消化液总量约 6~8 L（唾液 1~1.5 L、胃液 1.5~2.5 L、胰液1~2 L、胆汁 0.8~1 L、小肠液 1~3 L、大肠液少量），绝大部分在肠道被重吸收（“内源性循环”）。消化液的主要成分是水、电解质、消化酶、黏液，作用为稀释食物、改变 pH、水解营养物质、保护黏膜。分泌调节一般由神经（迷走）与激素双重控制，呈“头期—胃期—肠期”的时相性。"},{"id":"26.1","t":"唾液的性质与成分","s":3,"c":"26. 唾液分泌与咀嚼","x":"唾液为无色无味低渗液体，pH 6.6~7.1，成人每日 1~1.5 L。成分：（1）水约占 99%；（2）黏蛋白（使唾液黏稠、润滑）；（3）唾液淀粉酶（α-淀粉酶，最适 pH 约 6.9，将淀粉水解为麦芽糖，随食物入胃后被胃酸灭活）；（4）溶菌酶、乳铁蛋白、分泌型 IgA（防御）；（5）唾液酸与血型物质；（6）K⁺ 浓度高于血浆、Na⁺ 与 Cl⁻ 低于血浆（因导管重吸收 Na⁺、分泌K⁺）；（7）某些动物（蛇）唾液含毒素或抗凝物质。"},{"id":"26.2","t":"唾液分泌的调节","s":3,"c":"26. 唾液分泌与咀嚼","x":"唾液分泌完全为神经反射性调节，无激素的直接控制。基础分泌由口腔黏膜机械刺激引起；进食时“条件反射”（视觉、嗅觉、听觉、联想）与“非条件反射”（食物刺激口腔感受器）共同引起分泌。中枢为延髓的上涎核（分泌稀薄唾液）与下涎核（分泌黏稠唾液），传出为副交感（面神经鼓索支、舌咽神经）与交感神经。副交感兴奋使唾液量多而稀薄（有利消化），交感兴奋使唾液少而黏稠（应激时口干）；两者均促进分泌，但成分不同。"},{"id":"26.3","t":"咀嚼的功能","s":2,"c":"26. 唾液分泌与咀嚼","x":"咀嚼由咀嚼肌（咬肌、颞肌、翼内肌、翼外肌）有节律收缩完成，作用：（1）机械粉碎食物、增大表面积；（2）使食物与唾液混合形成食团、便于吞咽；（3）刺激口腔感受器反射性引起胃、胰、胆等消化器官的准备性分泌（头期）；（4）促进唾液淀粉酶初步消化淀粉。咀嚼还促进颌面发育；咀嚼不充分会增加胃肠负担。"},{"id":"26.4","t":"吞咽","s":2,"c":"26. 唾液分泌与咀嚼","x":"吞咽分三期：（1）口腔期（随意，舌将食团推入咽部）；（2）咽期（不随意，软腭上提封闭鼻咽、喉上提会厌封闭喉口、食管上括约肌舒张，食团进入食管，同时呼吸暂停）；（3）食管期（食管蠕动，由迷走神经支配，食管下括约肌舒张，食团入胃；重力在直立位有辅助作用）。吞咽反射中枢在延髓，会厌闭合不全可致误吸。"},{"id":"26.5","t":"唾液分泌的细胞机制","s":2,"c":"26. 唾液分泌与咀嚼","x":"唾液腺腺泡细胞分泌的初级唾液为等渗液，经导管时被修饰（导管细胞重吸收 Na⁺、Cl-、分泌 K⁺ 与 HCO3-），故终唾液低渗、K⁺ 高。分泌过程：副交感递质 ACh 作用于 M3 受体 → Gq → 磷脂酶 C → IP3 促内质网释放 Ca²⁺→ 激活 Cl- 通道（TMEM16A）使 Cl- 分泌入腔 → Na⁺ 顺电位差进入，水经AQP5 随渗透压进入腺腔；交感神经作用于 β 受体经 cAMP 促蛋白（淀粉酶）分泌。故副交感引起“量多而稀”、交感引起“量少而稠”。"},{"id":"26.6","t":"唾液分泌的种属差异与临床意义","s":2,"c":"26. 唾液分泌与咀嚼","x":"（1）反刍动物（牛、羊）每日分泌唾液可达 100~200 L，含大量碳酸氢盐与尿素，用于缓冲瘤胃发酵产生的酸并循环利用氮；（2）犬无汗腺，靠张口喘气与舌面唾液蒸发散热（故唾液分泌量大）；（3）蛇的唾腺特化为毒腺，毒液含蛋白酶、磷脂酶 A2、神经毒素，助捕食与消化；（4）食虫蝙蝠与部分鸟类唾液含抗凝物质。临床：舍格伦综合征（自身免疫性唾液腺与泪腺破坏）表现为口干、眼干与龋齿增多；腮腺炎（病毒）时腮腺肿痛，血、尿淀粉酶升高（唾液淀粉酶入血）。"},{"id":"27.1","t":"胃液的成分","s":3,"c":"27. 胃液分泌与胃运动","x":"纯净胃液为无色酸性液体，pH 0.9~1.5（H⁺ 浓度可达 150 mmol/L），成人每日 1.5~2.5 L。成分：（1）盐酸（由壁细胞分泌，H⁺ 由 H⁺-K⁺-ATP 酶泵入胃腔，Cl⁻ 顺电位差进入）；（2）胃蛋白酶原（主细胞分泌，被盐酸激活为胃蛋白酶，最适 pH 1.5~2.5，水解蛋白质为䏡与胨）；（3）内因子（壁细胞分泌的糖蛋白，与维生素 B12 结合，在回肠末端吸收）；（4）黏液与碳酸氢盐（形成黏液-碳酸氢盐屏障，表面 pH 约 7）；（5）胃泌素等激素。"},{"id":"27.2","t":"盐酸的生理作用","s":3,"c":"27. 胃液分泌与胃运动","x":"（1）激活胃蛋白酶原，提供酸性环境；（2）使蛋白质变性、便于水解；（3）杀灭随食物进入的细菌（胃酸是重要的非特异屏障）；（4）促进促胰液素与胆囊收缩素释放，进而促进胰液、胆汁分泌；（5）促进小肠对铁和钙的吸收（酸性环境使铁、钙保持可溶状态）；（6）胃酸分泌过少致消化不良、贫血；分泌过多（应激、幽门螺杆菌感染）可致溃疡。"},{"id":"27.3","t":"胃黏膜的防御机制","s":3,"c":"27. 胃液分泌与胃运动","x":"（1）黏液-碳酸氢盐屏障：表面黏液凝胶层厚 0.5~1 mm，含 HCO₃⁻，形成 pH 梯度（腔面 1~2、细胞面 7）；（2）黏膜上皮紧密连接与快速更新（3~5 天更新一次）；（3）黏膜血流充分（带走反渗的 H⁺）；（4）前列腺素（促进黏液与 HCO₃⁻ 分泌、增加血流）；（5）上皮生长因子。阿司匹林、酒精、应激、幽门螺杆菌破坏此屏障而致溃疡。"},{"id":"27.4","t":"胃液分泌的调节","s":3,"c":"27. 胃液分泌与胃运动","x":"刺激分泌的因素：（1）乙酰胆碱（迷走神经末梢，作用于壁细胞 M3 受体、G 细胞、ECL 细胞）；（2）胃泌素（G 细胞分泌，经血液作用于壁细胞，刺激胃酸分泌）；（3）组胺（ECL 细胞分泌，作用于壁细胞 H2 受体，是胃酸分泌的“最后共同通路”之一，西咪替丁等 H2 受体阻断剂可抑酸）。抑制因素：盐酸（负反馈抑制 G 细胞）、生长抑素、前列腺素、促胰液素、CCK、抑胃肽。"},{"id":"27.5","t":"消化期胃液分泌的三个时相","s":3,"c":"27. 胃液分泌与胃运动","x":"（1）头期：由食物刺激头面部感受器（视、嗅、味、咀嚼）引起，经迷走神经与胃泌素介导，分泌量约占 30%，酸度高、酶含量高、消化力强；（2）胃期：食物扩张胃底胃体（迷走-迷走长反射、壁内神经丛）与蛋白质消化产物刺激 G 细胞，分泌量占 60%，酸度与酶含量均高；（3）肠期：食糜进入十二指肠引起少量分泌（约 10%），以胃泌素与肠泌酸素介导，但十二指肠内的酸、脂肪、高渗液以抑制为主（肠-胃反射与促胰液素、CCK、GIP）。"},{"id":"27.6","t":"胃的运动与胃排空","s":3,"c":"27. 胃液分泌与胃运动","x":"胃运动形式：容受性舒张、紧张性收缩、蠕动（起始于胃中部，向幽门推进，频率约 3 次/分）。胃排空：食物入胃后 5 分钟开始排空，液体最快（水约1 小时）、糖类次之、蛋白质再次、脂肪最慢（可长达 4~6 小时）；混合食物完全排空需 4~6 小时。排空动力是胃内压与幽门两侧压力差，阻力为幽门括约肌。十二指肠通过肠-胃反射（酸、脂肪、高渗、机械扩张刺激）与 CCK、促胰液素、GIP 抑制胃排空，使排空速度与小肠消化吸收能力相适应。"},{"id":"27.7","t":"呕吐","s":2,"c":"27. 胃液分泌与胃运动","x":"呕吐是将胃内容物经口强力排出，是保护性反射：中枢在延髓呕吐中枢（第四脑室底），由催吐化学感受区（CTZ，对阿片、化疗药、尿毒症毒素敏感）与胃肠、前庭器官传入触发。过程：深吸气、声门关闭、腹肌与膈肌强烈收缩、胃逆蠕动、贲门与食管舒张。剧烈呕吐可致脱水、低钾、低氯性碱中毒（丢失胃酸）。"},{"id":"28.1","t":"胰液的成分与作用","s":3,"c":"28. 胰液与胆汁","x":"胰液是消化能力最强的消化液，无色碱性，pH 7.8~8.4，每日 1~2 L，渗透压与血浆相等。成分：（1）碳酸氢盐（由导管细胞分泌，中和胃酸、提供小肠最适 pH 7~8，保护肠黏膜）；（2）胰淀粉酶（水解淀粉为麦芽糖与寡糖，最适 pH 6.7~7.0）；（3）胰脂肪酶（需胆盐与辅酯酶协助，水解甘油三酯为脂肪酸与甘油一酯）；（4）胰蛋白酶原与糜蛋白酶原（由肠激酶激活胰蛋白酶原，后者再激活糜蛋白酶原与其他酶原，最适 pH 7.5~8.5）；（5）核糖核酸酶、脱氧核糖核酸酶、羧基肽酶、磷脂酶 A2。"},{"id":"28.2","t":"胰液分泌的调节","s":3,"c":"28. 胰液与胆汁","x":"（1）促胰液素（secretin，由十二指肠 S 细胞在盐酸、脂肪酸刺激下释放）：主要作用于胰腺导管上皮，促进大量水和 HCO₃⁻ 分泌（量多而酶少）；（2）胆囊收缩素（CCK，由 I 细胞在蛋白质分解产物与脂肪刺激下释放）：主要作用于腺泡，促进胰酶分泌，并促胆囊收缩、抑制胃排空；（3）迷走神经：直接促进胰液（以酶为主）分泌，并增强促胰液素与 CCK 的作用。胰液分泌以体液调节为主，这是与胃液（神经-激素并重）的差别。"},{"id":"28.3","t":"胆汁的成分与作用","s":3,"c":"28. 胰液与胆汁","x":"胆汁由肝细胞分泌（每日 800~1 000 mL），在非消化期储于胆囊（胆囊可浓缩 5~10 倍），消化期排入十二指肠。成分：水、胆盐、胆色素（胆红素、胆绿素）、胆固醇、卵磷脂、脂肪酸、无机盐，不含消化酶。作用：（1）胆盐乳化脂肪，增大脂肪与脂肪酶的接触面；（2）形成混合微胶粒，促进脂肪分解产物与脂溶性维生素（A、D、E、K）的吸收；（3）胆盐刺激肝分泌胆汁（正反馈）；（4）胆色素为血红蛋白分解产物，排出体外。"},{"id":"28.4","t":"胆汁分泌与排出的调节","s":3,"c":"28. 胰液与胆汁","x":"（1）食物刺激：高脂肪食物作用最强，高蛋白次之，糖类最弱；（2）CCK：引起胆囊强烈收缩、Oddi 括约肌舒张，促进胆汁排出（主要因素）；（3）促胰液素：增加胆汁中水和 HCO₃⁻ 的分泌；（4）胆盐：经肠肝循环（约 95% 在回肠末端被重吸收，每日循环 6~12 次）返回肝，刺激肝细胞分泌胆汁，是维持胆汁分泌的重要自身调节；（5）迷走神经：促进胆汁分泌与胆囊收缩。"},{"id":"28.5","t":"胆盐的肠肝循环","s":2,"c":"28. 胰液与胆汁","x":"胆盐在回肠末端（主动转运）约 95% 被重吸收，经门静脉回肝再利用，成人胆盐池约 3~5 g，每日随粪便排出约 0.5 g（由肝合成补充）。回肠切除或病变（克罗恩病）时胆盐丢失，引起脂肪泻与脂溶性维生素缺乏。胆盐还可被细菌作用生成脱氧胆酸等次级胆汁酸。"},{"id":"28.6","t":"胆结石与黄疸","s":2,"c":"28. 胰液与胆汁","x":"胆汁中胆固醇过饱和、胆盐与卵磷脂比例失调时，胆固醇结晶析出形成结石（主要成分胆固醇或混合结石）。胆道梗阻时结合胆红素反流入血，出现皮肤巩膜黄染、尿色深、粪色浅（阻塞性黄疸）；溶血时以非结合胆红素升高为主（溶血性黄疸）；肝细胞损伤时两者均升高（肝细胞性黄疸）。"},{"id":"29.1","t":"小肠的运动形式","s":3,"c":"29. 小肠运动与消化","x":"（1）分节运动：以环形肌为主的节律性收缩与舒张，使食糜反复分割、混合，不推进，频率上段约 12 次/分、下段约 8 次/分，空腹时消失；（2）蠕动：将食糜向大肠方向推进，速度较慢（0.5~2 cm/s），还有快速的“蠕动冲”（可在数分钟内将食糜推至回肠末端）；（3）紧张性收缩：维持肠腔内压，是其他运动的基础；（4）MMC：空腹时周期性推进，防止细菌过度生长。"},{"id":"29.2","t":"小肠运动的调节","s":2,"c":"29. 小肠运动与消化","x":"（1）肌间神经丛的局部反射（食糜扩张肠壁引起上段收缩、下段舒张）；（2）外来神经：迷走神经兴奋增强（但强刺激可抑制），交感神经抑制；（3）胃肠激素：胃动素促进 MMC、CCK 与胃泌素增强、促胰液素与胰高血糖素抑制；（4）化学因素：5-HT、P 物质、ACh 兴奋，VIP、NO 舒张。肠梗阻时出现阵发性腹痛、呕吐与肠鸣音亢进，麻痹性肠梗阻则肠鸣音消失。"},{"id":"29.3","t":"小肠液的成分与作用","s":3,"c":"29. 小肠运动与消化","x":"小肠液由肠腺（Lieberkühn 腺）分泌，每日 1~3 L，弱碱性（pH 7.6），含肠致活酶（肠激酶，激活胰蛋白酶原）、黏蛋白、免疫球蛋白和脱落的上皮细胞。小肠上皮刷状缘含多种消化酶：麦芽糖酶、蔗糖酶、乳糖酶（水解二糖为单糖）、氨基肽酶与二肽酶（水解短肽）、碱性磷酸酶、γ-谷氨酰转移酶。小肠液的分泌以局部反射（肌间与黏膜下神经丛）调节为主。"},{"id":"29.4","t":"三大营养物质的消化过程","s":3,"c":"29. 小肠运动与消化","x":"（1）糖类：口腔（唾液淀粉酶，少量）→ 小肠（胰淀粉酶水解为麦芽糖、麦芽三糖、α-糊精）→ 刷状缘（麦芽糖酶、蔗糖酶、乳糖酶水解为葡萄糖、果糖、半乳糖）；（2）蛋白质：胃（胃蛋白酶，约 10%~20% 水解）→小肠（胰蛋白酶、糜蛋白酶、羧基肽酶、弹性蛋白酶）→ 刷状缘（氨基肽酶、二肽酶水解为氨基酸）；（3）脂肪：口腔与胃（舌脂肪酶、胃脂肪酶，作用弱）→ 小肠（胆盐乳化 + 胰脂肪酶水解为 2-甘油一酯与脂肪酸，胆固醇酯酶、磷脂酶 A2 参与）。"},{"id":"29.5","t":"消化道的防御与菌群","s":1,"c":"29. 小肠运动与消化","x":"肠道是最大的免疫器官，含大量淋巴滤泡（Peyer 集结）、分泌型 IgA、抗菌肽（防御素）。结肠内菌群约 10¹⁴ 个，发酵未消化糖类产生短链脂肪酸（乙酸、丙酸、丁酸，供结肠上皮能量）、合成维生素 K 与部分 B 族维生素、参与胆汁酸转化。菌群失调与炎症性肠病、抗生素相关性腹泻有关。广谱抗生素长期使用可致维生素 K 缺乏。"},{"id":"29.6","t":"回盲瓣与大肠运动","s":2,"c":"29. 小肠运动与消化","x":"回盲瓣由回肠末端套入盲肠形成，防止结肠内容物反流入回肠，并控制回肠排空（进食后胃回肠反射使其舒张）。大肠运动形式：（1）袋状往返运动（分节，使内容物混合并促进水吸收）；（2）蠕动与多袋推进运动；（3）集团运动（mass movement，进食后胃结肠反射引起，每日 3~4 次，将内容物推入直肠引起便意）。排便反射：粪便扩张直肠壁 → 盆神经传入骶髓排便中枢→ 副交感使降结肠、乙状结肠与直肠收缩、肛门内括约肌舒张，同时大脑皮质控制肛门外括约肌（可随意延迟）。膳食纤维通过增加容积、刺激集团运动、被菌群发酵产短链脂肪酸而促进排便。"},{"id":"30.1","t":"吸收的部位与结构基础","s":3,"c":"30. 吸收","x":"吸收的主要部位是小肠（十二指肠与空肠上段吸收能力最强），因为小肠长 5~7 m、有环状皱襞、绒毛与微绒毛（使吸收面积增大约 600 倍，达 200 m² 左右）、绒毛内有丰富的毛细血管与中央乳糜管、食物在小肠内已被充分消化、停留时间长（3~8 小时）。口腔与食管几乎不吸收（仅少量药物如硝酸甘油），胃吸收少量水、乙醇和某些药物，大肠吸收水分与无机盐（每日约1~2 L）。"},{"id":"30.2","t":"糖的吸收","s":3,"c":"30. 吸收","x":"糖以单糖形式吸收，主要为葡萄糖与半乳糖（经 SGLT1 继发性主动转运，与 2 个 Na⁺ 同向），果糖经 GLUT5 易化扩散。进入上皮后经基底侧GLUT2 进入血液，经门静脉入肝。吸收速率：半乳糖 > 葡萄糖 > 果糖 > 甘露糖。葡萄糖与 Na⁺ 的吸收相互促进，故口服补液盐（葡萄糖 + 盐水）能有效纠正腹泻脱水。纤维素不能被消化吸收，但可促进肠蠕动、提供容积、吸附胆盐。"},{"id":"30.3","t":"蛋白质的吸收","s":3,"c":"30. 吸收","x":"以氨基酸和少量二肽、三肽形式吸收。氨基酸经 Na⁺ 依赖的继发性主动转运（中性、碱性、酸性氨基酸各有载体），二肽/三肽经 PepT1（H⁺ 依赖）吸收后在胞内水解。婴幼儿可吸收少量完整蛋白质（母乳中的抗体，获得被动免疫），成人吸收完整蛋白可引起过敏。未被吸收的蛋白质在结肠被细菌分解（腐败作用）产生胺、氨、吲哚等。"},{"id":"30.4","t":"脂肪的吸收","s":3,"c":"30. 吸收","x":"脂肪消化产物（2-甘油一酯、脂肪酸）与胆盐形成混合微胶粒（直径约3~10 nm），经微绒毛的静水层扩散至膜表面，脂肪酸以单体形式进入上皮细胞。长链脂肪酸（>12 碳）在上皮内重新合成甘油三酯，与载脂蛋白 B48 组装成乳糜微粒，经中央乳糜管→淋巴→胸导管→左锁骨下静脉入血（故脂肪吸收不经门静脉）。中短链脂肪酸（<10~12 碳）可直接经门静脉入血，故中链甘油三酯用于脂肪吸收不良患者。胆固醇以乳糜微粒形式吸收。"},{"id":"30.5","t":"水与无机盐的吸收","s":3,"c":"30. 吸收","x":"（1）水：每日摄入约 2 L，消化液分泌约 7 L，共约 9 L，其中小肠吸收约8 L、结肠吸收约 1 L，随粪便排出约 0.1~0.2 L。水吸收为被动过程，依赖Na⁺、葡萄糖等溶质吸收造成的渗透压差。（2）钠：小肠每日吸收 25~35 g（含分泌），通过 Na⁺ 通道、Na⁺-葡萄糖/氨基酸同向转运、Na⁺/H⁺ 交换等方式主动吸收，结肠 Na⁺ 吸收受醛固酮调节。（3）氯：被动跟随 Na⁺ 或经HCO₃⁻/Cl⁻ 交换。"},{"id":"30.6","t":"铁的吸收","s":3,"c":"30. 吸收","x":"铁主要在十二指肠与空肠上段吸收，每日从食物吸收 1~2 mg（食物含铁10~15 mg，吸收率仅 5%~10%）。血红素铁（来自肉类）吸收率高于非血红素铁（植物）。Fe²⁺ 比 Fe³⁺ 易吸收，故维生素 C、果糖、胃酸促进吸收，植酸、鞣酸（茶）、磷酸、钙、膳食纤维抑制吸收。吸收量受体内铁储备调节（铁蛋白与转铁蛋白受体系统），缺铁时吸收率可提高数倍。铁经转铁蛋白运至骨髓造血，多余储存于肝、脾、骨髓。"},{"id":"30.7","t":"钙的吸收","s":3,"c":"30. 吸收","x":"钙主要在十二指肠与空肠上段吸收，分为主动转运（经钙结合蛋白 CaBPD9k，依赖 1,25-(OH)2-维生素 D）与被动扩散。促进因素：维生素 D、乳糖、酸性环境（乳酸、氨基酸）、适量蛋白质；抑制因素：草酸（菠菜）、植酸、磷酸盐、过量脂肪（形成钙皂）、碱性环境。吸收率约 20%~30%，儿童与孕妇较高。血钙水平受 PTH、降钙素与维生素 D 三重调节（见第 46 章）。"},{"id":"30.8","t":"维生素的吸收","s":2,"c":"30. 吸收","x":"水溶性维生素（B 族、C）经扩散或与 Na⁺ 偶联的载体吸收；维生素 B12必须与内因子结合后在回肠末端经受体介导吸收（故胃切除或内因子缺乏引起巨幼红细胞性贫血）；脂溶性维生素（A、D、E、K）随脂肪经乳糜微粒吸收，需胆盐，脂肪吸收不良时随之缺乏。维生素 B12 与叶酸均参与 DNA 合成。营养物质主要吸收部位吸收机制途径葡萄糖、半乳糖小肠SGLT1 继发主动转运门静脉果糖小肠GLUT5 易化扩散门静脉氨基酸小肠Na⁺ 依赖载体、PepT1门静脉长链脂肪酸小肠混合微胶粒 → 乳糜微粒淋巴中短链脂肪酸小肠直接扩散门静脉铁十二指肠主动转运（Fe²⁺）门静脉钙十二指肠、空肠主动转运（维生素 D 依赖）门静脉维生素 B12回肠末端内因子-受体介导门静脉"},{"id":"31.1","t":"胃肠激素的概念与特点","s":3,"c":"31. 胃肠激素","x":"胃肠激素由散在于胃肠道黏膜内的内分泌细胞（APUD 细胞）分泌，也存在于中枢神经系统（脑肠肽）。特点：（1）多数为肽类；（2）经血液运输（内分泌）或局部扩散（旁分泌）、或作为神经递质（神经分泌）；（3）除调节消化外还影响其他系统（如胃泌素促进胃酸分泌、也能刺激胃肠运动）。从胃泌素、促胰液素、CCK 的发现史（Bayliss 与 Starling，1902 年发现促胰液素）开始了内分泌学。"},{"id":"31.2","t":"胃泌素","s":3,"c":"31. 胃肠激素","x":"由胃窦与十二指肠的 G 细胞分泌，主要有大胃泌素（G-34）与小胃泌素（G-17，活性强）。刺激因素：蛋白质消化产物（肽、氨基酸）、胃扩张、迷走神经（ACh 及胃泌素释放肽 GRP）、碱性环境、咖啡因、酒精。作用：促进胃酸与胃蛋白酶原分泌、促进胃与肠运动、促进黏膜生长（营养作用）、促进胰液与胆汁分泌。抑制因素：胃内 pH <2.5（负反馈）、生长抑素、促胰液素、CCK、GIP。胃泌素瘤（Zollinger-Ellison 综合征）引起胃酸大量分泌与多发溃疡。"},{"id":"31.3","t":"促胰液素","s":3,"c":"31. 胃肠激素","x":"由十二指肠与空肠的 S 细胞分泌，是第一个被发现的激素。刺激因素：十二指肠内 pH <4.5（胃酸）、脂肪酸。作用：促进胰液大量分泌水和 HCO₃⁻（作用于导管细胞）、促进胆汁中 HCO₃⁻ 分泌、抑制胃酸与胃运动、促进胃蛋白酶原分泌。不促进胰酶分泌。"},{"id":"31.4","t":"胆囊收缩素（CCK）","s":3,"c":"31. 胃肠激素","x":"由十二指肠与空肠的 I 细胞分泌。刺激因素：蛋白质分解产物（最强）、脂肪酸、盐酸。作用：促进胆囊强烈收缩与 Oddi 括约肌舒张（促胆汁排出）、促进胰酶分泌（作用于腺泡）、抑制胃排空、促进小肠与结肠运动、增强胰促胰液素的作用、引起饱感（中枢作用）。CCK 与促胰液素协同是胰液分泌的“双激素调节”。"},{"id":"31.5","t":"其他胃肠激素","s":2,"c":"31. 胃肠激素","x":"（1）抑胃肽（GIP）：由 K 细胞分泌，由葡萄糖、脂肪刺激释放，抑制胃酸与胃运动，并刺激胰岛素分泌（肠促胰岛素效应，约占餐后胰岛素分泌的50%~70%）；（2）胃动素：由 Mo 细胞分泌，促进 MMC；（3)血管活性肠肽（VIP）：广泛分布于肠神经系统，舒张血管与平滑肌、促进肠液分泌（VIP瘤引起水样泻）；（4）生长抑素：D 细胞分泌，抑制几乎所有胃肠激素与分泌；（5）P 物质、神经降压素、促胃液素释放肽（GRP）、瘦素与食欲调节肽（ghrelin 促食欲）。"},{"id":"31.6","t":"胃肠激素的作用方式与临床","s":2,"c":"31. 胃肠激素","x":"作用方式包括内分泌（经血）、旁分泌（作用于邻近细胞）、神经分泌（作为递质）、外分泌（进入胃肠腔）与自分泌。临床相关：胃泌素瘤（胃酸过多、多发溃疡）、VIP 瘤（水样泻低钾无胃酸综合征）、类癌（5-HT 过多引起腹泻与面部潮红）、Zollinger-Ellison 综合征。测定空腹血清胃泌素有助于诊断。主要刺激主要作用胃泌素激素G 细胞（胃窦）分泌细胞与部位蛋白产物、扩张、ACh促胃酸、促运动、营养黏膜促胰液素S 细胞（十二指肠）盐酸（pH<4.5）促胰液 HCO₃⁻ 与水量胆囊收缩素I 细胞（十二指肠）蛋白产物、脂肪胆囊收缩、促胰酶、抑胃排空抑胃肽K 细胞（小肠）葡萄糖、脂肪抑胃酸、促胰岛素胃动素Mo 细胞空腹、碱性启动 MMC血管活性肠肽肠神经元迷走反射舒张平滑肌、促分泌"},{"id":"32.1","t":"肝脏的代谢功能","s":3,"c":"32. 肝脏的功能","x":"（1）糖代谢：合成与分解肝糖原（肝糖原约 100 g）、糖异生（维持空腹血糖，肝是糖异生的主要器官），调节血糖；（2）蛋白质代谢：合成血浆白蛋白、纤维蛋白原、凝血酶原及多数凝血因子、多种载脂蛋白与转运蛋白；脱氨基生成尿素（尿素循环，肝是唯一能合成尿素的器官）；（3）脂肪代谢：合成胆固醇、甘油三酯、磷脂与脂蛋白（VLDL），脂肪酸 β 氧化供能，是酮体生成的器官之一。"},{"id":"32.2","t":"肝脏的胆汁分泌功能","s":3,"c":"32. 肝脏的功能","x":"肝细胞每日分泌胆汁 800~1 000 mL，胆汁既是消化液（胆盐乳化脂肪）又是排泄途径（胆红素、胆固醇、药物、重金属）。胆红素来自衰老红细胞破坏（每日约 250~350 mg），在肝细胞内与葡萄糖醛酸结合成结合胆红素后随胆汁排入肠腔；肠内细菌还原为尿胆原，大部分随粪便排出（粪胆素），小部分经肠肝循环回肝或经肾排出（尿胆原）。"},{"id":"32.3","t":"肝脏的解毒与生物转化","s":3,"c":"32. 肝脏的功能","x":"外源性与内源性非营养物质的生物转化在肝进行，分两相：第一相氧化、还原、水解（细胞色素 P450 单加氧酶系，存在于滑面内质网），第二相结合反应（与葡萄糖醛酸、硫酸、谷胱甘肽、乙酰基结合，使其水溶性增加便于排出）。意义：多数物质毒性降低、活性减弱（失活），少数被转化为毒性更强的中间产物（如对乙酰氨基酚过量产生 NAPQI 致肝坏死）。肝功能不全时药物清除减慢，易蓄积中毒。"},{"id":"32.4","t":"肝脏的储存与防御功能","s":2,"c":"32. 肝脏的功能","x":"储存：肝糖原、维生素 A（肝储量为全身 90% 以上）、维生素 D、维生素B12、铁（以铁蛋白形式）、铜。防御：肝内库普弗细胞（Kupffer 细胞，属单核-巨噬细胞系统）吞噬血中的细菌、异物、衰老红细胞与内毒素；肝血窦内皮细胞与 NK 细胞也参与。胎儿期肝是主要造血器官（约 6 周至 6 个月）。"},{"id":"32.5","t":"肝功能评价指标","s":2,"c":"32. 肝脏的功能","x":"（1）蛋白合成：血清白蛋白（正常 40~50 g/L）、凝血酶原时间（PT，反映维生素 K 依赖因子）、前白蛋白（半衰期短，敏感）；（2）肝细胞损伤：ALT（丙氨酸氨基转移酶，较特异）、AST（天冬氨酸氨基转移酶，严重损伤或心肌损伤时升高）、LDH；（3）胆红素代谢：总胆红素、直接与间接胆红素；（4）胆汁淤积：碱性磷酸酶（ALP）、γ-谷氨酰转肽酶（GGT）；（5）合成与储备：胆碱酯酶、胆固醇。"},{"id":"32.6","t":"肝与物质代谢的整体联系","s":2,"c":"32. 肝脏的功能","x":"肝是物质代谢的中枢：餐后血糖升高，肝摄取葡萄糖合成糖原、转化为脂肪（VLDL 输出）；空腹时肝糖原分解、糖异生，输出葡萄糖；氨基酸在肝脱氨合成尿素；脂肪动员产生的游离脂肪酸部分在肝氧化生成酮体供脑、心等利用。肝功能障碍时出现低血糖、低白蛋白血症与水肿、凝血障碍、黄疸、高氨血症（肝性脑病）。"},{"id":"33.1","t":"能量的来源、转移与利用","s":3,"c":"33. 能量代谢","x":"糖、脂肪、蛋白质氧化释放能量，其中约 50% 以上以热能散失，其余储存在 ATP 高能磷酸键（约 30.5 kJ/mol）中供生命活动使用。能量平衡：摄入能量 = 消耗能量 + 储存能量。三大营养物质的体外燃烧热（物理热价）与在体内氧化释放的能量（生物热价）有差异（蛋白质在体内不完全氧化，生物热价小于物理热价）。1 g 糖 ≈ 17.2 kJ、1 g 脂肪 ≈ 39.8 kJ、1 g 蛋白质 ≈ 18.0 kJ（体内约 16.7 kJ）。"},{"id":"33.2","t":"呼吸商","s":3,"c":"33. 能量代谢","x":"一定时间内机体呼出 CO₂ 量与吸入 O₂ 量的比值（RQ = CO₂/O₂）称呼吸商。糖氧化 RQ = 1.00；脂肪（如三油酸甘油酯）RQ ≈ 0.71；蛋白质 RQ ≈0.80；混合膳食 RQ ≈ 0.85。RQ 反映能量来源：糖类为主时接近 1，脂肪为主时接近 0.71，长期饥饿或糖尿病时糖利用障碍、RQ 可低至 0.70 以下；过度通气、剧烈运动（乳酸生成，CO₂ 排出增多）时 RQ 可大于 1（非代谢性）。计算非蛋白呼吸商时先扣除蛋白质代谢部分（由尿氮推算），可更准确推算糖与脂肪的消耗比例。"},{"id":"33.3","t":"基础代谢与基础代谢率","s":3,"c":"33. 能量代谢","x":"基础代谢指人体在清醒、静卧、空腹（禁食 12~14 小时）、室温 20~25℃、无精神紧张状态下的能量代谢，以每小时每平方米体表面积的产热量表示（kJ/(m²·h)），即基础代谢率（BMR）。我国成年男性约 154~168 kJ/(m²·h)、女性约 146~155 kJ/(m²·h)（通常女性比男性低 5%~10%）。BMR 与体表面积成正比（Rubner 定律），跨种比较则与体重的 0.75 次方成正比（Kleiber 定律）。正常范围 ±15%，超过 ±20% 视为病理。甲状腺功能亢进时 BMR 明显升高，甲状腺功能减退、肾上腺皮质功能减退时降低；发热时每升高 1 ℃ BMR 约增加 13%。"},{"id":"33.4","t":"影响能量代谢的因素","s":3,"c":"33. 能量代谢","x":"（1）肌肉活动：最显著，剧烈运动时产热可达安静时的 10~20 倍；（2）环境温度：20~30 ℃ 最稳定，低温时寒战产热、高温时发汗与循环加快；（3）食物的特殊动力效应：进食后额外产热，蛋白质约 30%、糖 6%、脂肪4%，混合膳食约 10%，持续 2~8 小时；（4）精神活动与应激：交感兴奋、肾上腺素与甲状腺激素增加产热；（5）年龄与性别：儿童高于成人，老年降低；激素：甲状腺激素 > 肾上腺素 > 生长激素与睾酮；（6）睡眠时降低10%~15%；（7）体重与体成分（肌肉比例高者 BMR 高）。"},{"id":"33.5","t":"测定方法与间接测热法","s":2,"c":"33. 能量代谢","x":"直接测热法用测热装置测散热，设备复杂。间接测热法（临床常用）依据化学反应的定比关系：测一定时间内的 O₂ 消耗量与 CO₂ 产生量，求出呼吸商，查表得氧热价（糖 21.1 kJ/L、脂肪 19.6 kJ/L、蛋白质 18.8 kJ/L），再乘以氧耗量即得产热量。简化法：混合膳食氧热价约 20.2 kJ/L。便携式代谢仪测定静息能量消耗（REE）用于营养评估。"},{"id":"33.6","t":"能量代谢与体温的关系","s":2,"c":"33. 能量代谢","x":"机体产热与散热平衡，体温才能恒定。产热器官：安静时以肝、脑等内脏为主（肝约占 30%），运动时骨骼肌产热可占 90% 以上。散热量与皮肤温度、环境温度、湿度、风速有关。能量代谢率高的动物（小型恒温动物如鼩鼱）体表面积/体重比大，单位体重散热多，故需高代谢率维持体温；大型动物（象、鲸）反之，这是体表面积定律在生态学上的体现。物质呼吸商氧热价 kJ/L生理热价 kJ/g糖1.00 21.1 17.2脂肪0.71 19.6 39.8蛋白质0.80 18.8约 16.7（体内）混合膳食0.85 20.2—"},{"id":"34.1","t":"体温的正常值与测量","s":3,"c":"34. 体温调节","x":"恒温动物（鸟类、哺乳类）体温相对恒定。人的直肠温度 36.9~37.9 ℃（最接近体核温度）、口腔温度 36.7~37.7 ℃、腋窝温度 36.0~37.4 ℃（最低但最常用）。体温的生理波动：清晨 2~6 时最低、午后 1~6 时最高，差值不超过 1 ℃（昼夜节律）；女性排卵后体温升高 0.3~0.5 ℃（孕激素作用，可用于判断排卵）；儿童略高于成人，老年略低；运动、进食、情绪使体温升高。"},{"id":"34.2","t":"体热平衡：产热","s":3,"c":"34. 体温调节","x":"产热器官：安静时肝、脑、心、肾等内脏（肝最多），运动时骨骼肌（可占总产热 90%）。产热方式：（1）战栗产热：骨骼肌不随意的节律性收缩（寒战），产热可达安静时的 4~5 倍，由下丘脑（后部）通过躯体运动神经引起；（2）非战栗产热（代谢产热）：棕色脂肪组织（BAT）通过解偶联蛋白UCP1 使氧化磷酸化解偶联，产热而不生成 ATP，新生儿与冬眠动物尤为重要；甲状腺激素与肾上腺素长期或短期提高代谢率。"},{"id":"34.3","t":"体热平衡：散热","s":3,"c":"34. 体温调节","x":"散热途径：皮肤（约占 90%）、呼吸、排尿排便。方式：（1）辐射：约占 60%，取决于皮肤与环境温度差；（2）传导与对流：约占 15%，受风速影响大；（3）蒸发：约占 25%，包括不感蒸发（每日约 1 000 mL，其中皮肤600~800 mL、呼吸道 200~400 mL）与发汗（可感蒸发，汗腺受交感胆碱能纤维支配，每蒸发 1 g 水散热约 2.43 kJ）。环境温度升高接近或超过皮肤温度时，蒸发成为唯一有效的散热方式；湿度高时蒸发受阻。产热与散热的平衡由下丘脑整合。"},{"id":"34.4","t":"体温调节中枢与调定点","s":3,"c":"34. 体温调节","x":"体温调节的基本中枢位于下丘脑，视前区-下丘脑前部（PO/AH）是整合中心，其中的温度敏感神经元（热敏神经元与冷敏神经元）对局部温度敏感，并能接受皮肤、内脏温度感受器的传入。调定点学说：PO/AH 设定了约 37 ℃的调定点，当体温偏离调定点时，通过效应器（皮肤血管、汗腺、骨骼肌、棕色脂肪、内分泌）调节产热与散热，把体温拉回。致热原（细菌内毒素、IL-1、IL-6、TNF）使下丘脑合成前列腺素 E2（PGE2），使调定点上移，引起发热（先寒战后高热）；阿司匹林抑制环氧合酶减少 PGE2，使调定点回降而退热。"},{"id":"34.5","t":"体温调节的效应方式","s":2,"c":"34. 体温调节","x":"冷环境：皮肤血管收缩（减少散热）、战栗（增加产热）、非战栗产热（BAT）、竖毛肌收缩（毛发竖立，人类作用小）、甲状腺激素与肾上腺素分泌增加、行为性调节（增添衣物、蜷缩）。热环境：皮肤血管舒张（增加散热）、发汗、呼吸加快、食欲下降、活动减少、行为调节（乘凉、避晒）。体温升高超过 40~41 ℃ 时细胞代谢紊乱、酶变性，出现中暑（热射病），汗腺功能衰竭后体温急剧升高、危及生命。"},{"id":"34.6","t":"变温动物与恒温动物的体温策略","s":3,"c":"34. 体温调节","x":"变温动物（鱼类、两栖类、爬行类、无脊椎动物）体温随环境变化，通过行为调节（晒太阳、寻找阴凉、选择适宜深度）与代谢调节有限地影响体温；其代谢率随温度升高而升高（Q10 约 2~3），低温时活动减少。恒温动物（鸟类、哺乳类）靠高代谢率与产热散热调节维持恒定体温，代价是能量消耗大（小型恒温动物每日进食量可达体重的 50% 以上）。异温动物（冬眠的蝙蝠、刺猬、熊的浅冬眠）在冬眠时体温显著下降、代谢率降至正常的 1/50~1/100，以节约能量。"},{"id":"34.7","t":"温度感受器与适应","s":2,"c":"34. 体温调节","x":"外周温度感受器分布在皮肤、黏膜、内脏（冷感受器多于热感受器，冷点在皮肤上分布更密）；中枢温度感受器位于脊髓、脑干、下丘脑、网状结构。传入通路经脊髓丘脑束到丘脑，再投射到 PO/AH 与大脑皮质。长期生活在寒冷或炎热环境可产生习服（如寒冷习服者战栗阈值降低、非战栗产热增强），但调定点不变。第五篇 排泄与渗透调节"},{"id":"35.1","t":"肾脏的大体结构","s":3,"c":"35. 肾单位的结构与肾血流","x":"肾由被膜、皮质和髓质构成，髓质由 8~18 个肾锥体组成，锥体尖端为肾乳头，开口于肾小盏、肾大盏、肾盂，经输尿管入膀胱。皮质包含肾小体与曲小管，髓质包含髓袢与集合管。肾的基本功能单位是肾单位（每侧肾约 100 万个），集合管不属于肾单位但参与尿液浓缩。鱼类的肾为原肾/中肾，肾单位结构较简单、缺少髓袢；鸟类与哺乳类有髓袢与浓缩尿能力。"},{"id":"35.2","t":"肾单位的结构","s":3,"c":"35. 肾单位的结构与肾血流","x":"肾单位由肾小体与肾小管组成。肾小体包括肾小球（毛细血管球）与肾小囊（鲍曼囊，有脏层足细胞与壁层），是滤过部位；肾小管分近端小管（近曲小管、近直小管）、髓袢（降支细段、升支细段、升支粗段）、远端小管（远曲小管、远直小管），最后汇入集合管。近端小管上皮有密集的刷状缘与大量线粒体（重吸收功能强）；升支粗段上皮细胞含 Na⁺-K⁺-2Cl⁻ 同向转运体，是袢利尿剂的作用位点。"},{"id":"35.3","t":"皮质肾单位与近髓肾单位","s":2,"c":"35. 肾单位的结构与肾血流","x":"（1）皮质肾单位占 85%~90%，位于皮质外层，髓袢短（仅达外髓），出球小动脉细、入球小动脉粗，肾素含量高，主要参与滤过与肾素分泌；（2）近髓肾单位占 10%~15%，髓袢长（可达内髓），出球小动脉与入球小动脉口径相近，出球小动脉还发出直小血管，主要参与尿液浓缩与稀释。长髓袢是产生高渗髓质的前提，故沙漠动物（如更格卢鼠）髓袢特别长。"},{"id":"35.4","t":"球旁器","s":3,"c":"35. 肾单位的结构与肾血流","x":"球旁器位于入球小动脉与远曲小管相邻处，由三种细胞组成：（1）球旁（颗粒）细胞，位于入球小动脉壁，含分泌颗粒，分泌肾素；（2）致密斑，为远曲小管起始部的高柱状上皮，感受小管液中 NaCl 含量变化（管球反馈），NaCl 减少时刺激肾素释放；（3）球外（系膜）细胞，起支持和传递信号作用。球旁器是肾素-血管紧张素系统的起点。"},{"id":"35.5","t":"肾脏的血液供应","s":3,"c":"35. 肾单位的结构与肾血流","x":"肾动脉 → 叶间动脉 → 弓形动脉 → 小叶间动脉 → 入球小动脉 → 肾小球毛细血管网（第一次毛细血管，压力高，用于滤过）→ 出球小动脉 → 肾小管周围毛细血管网（第二次毛细血管，压力低、胶体渗透压高，用于重吸收）→ 小静脉 → 肾静脉。肾血流量约 1.1~1.2 L/min，占心输出量的 20%~25%，其中皮质占 94%、髓质仅 6%。两套毛细血管串联是肾脏“先滤过后重吸收”的结构基础。"},{"id":"35.6","t":"肾脏的主要功能","s":3,"c":"35. 肾单位的结构与肾血流","x":"（1）排泄代谢废物（尿素、尿酸、肌酐、氨、药物、毒物）；（2）调节水与电解质平衡（Na⁺、K⁺、Cl⁻、Ca²⁺、磷）；（3）调节酸碱平衡（排H⁺、重吸收 HCO₃⁻、泌 NH₄⁺）；（4）调节细胞外液容量与渗透压（通过ADH、醛固酮）；（5）内分泌功能：分泌肾素、促红细胞生成素（EPO）、活性维生素 D（1,25-(OH)2D3）、前列腺素与激肽，肾也是 ADH、PTH、胰岛素等的降解部位。"},{"id":"36.1","t":"滤过膜的结构与屏障作用","s":3,"c":"36. 肾小球的滤过","x":"滤过膜由三层构成：毛细血管内皮（有窗孔，直径 70~90 nm）、基膜（微纤维网，主要机械屏障）、肾小囊脏层足细胞的裂孔膜（裂孔直径 4~11 nm）。屏障有两重：（1）机械（大小）屏障，有效半径 <2.0 nm 的物质可自由通过（葡萄糖、尿素、肌酐、电解质），>4.2 nm 不能通过（白蛋白有效半径约 3.6 nm，仅少量滤过）；（2）电学屏障，滤过膜含唾液酸蛋白带负电，阻碍带负电的血浆蛋白。肾小球肾炎时负电荷减少，出现蛋白尿。"},{"id":"36.2","t":"有效滤过压","s":3,"c":"36. 肾小球的滤过","x":"有效滤过压 = 肾小球毛细血管血压 -（血浆胶体渗透压 + 肾小囊内压）。正常值：毛细血管血压约 45 mmHg（入球端）、血浆胶体渗透压约 25 mmHg、囊内压约 10 mmHg，故有效滤过压约 10 mmHg（出球端因胶体渗透压升高，有效滤过压降至 0，滤过停止）。由于肾小球毛细血管血压远高于其他毛细血管，故能克服胶体渗透压而大量滤过。"},{"id":"36.3","t":"肾小球滤过率与滤过分数","s":3,"c":"36. 肾小球的滤过","x":"单位时间内两肾生成的超滤液量称肾小球滤过率（GFR），正常成人约125 mL/min（约 180 L/日），女性略低 10%。肾血浆流量约 600 mL/min，故滤过分数 = 125/600 ≈ 20%，即流经肾的血浆约 1/5 被滤过。GFR 是评价肾功能最重要的指标，可用菊粉清除率（金标准）或肌酐清除率测定；血肌酐升高提示 GFR 下降。"},{"id":"36.4","t":"影响滤过率的因素","s":3,"c":"36. 肾小球的滤过","x":"（1）肾小球毛细血管血压：动脉压 80~180 mmHg 内通过自身调节保持恒定，低于 80 mmHg 时 GFR 下降（大失血时少尿）；（2）血浆胶体渗透压：血浆蛋白减少（肾病、肝病）时升高有效滤过压、GFR 增加；（3）囊内压：尿路结石、肿瘤压迫使囊内压升高、GFR 下降；（4）滤过膜面积与通透性：肾炎时面积减小、通透性增大（出现蛋白尿、血尿）；（5）肾血浆流量：血流加快时滤过增加，严重减少时 GFR 下降。"},{"id":"36.5","t":"尿量与原尿成分","s":2,"c":"36. 肾小球的滤过","x":"正常成人每日尿量 1~2 L（平均 1.5 L），比重 1.015~1.025。多尿指 >2.5 L/日，少尿指 100~400 mL/日，无尿指 <100 mL/日（24 小时）。原尿成分除大分子蛋白外与血浆基本一致（葡萄糖、氨基酸、Na⁺、K⁺、Cl⁻、尿素、尿酸、肌酐），终尿中葡萄糖与氨基酸消失、肌酐浓缩 100 倍以上（因不被重吸收）、尿素浓缩约 60 倍、Na⁺ 排出约为滤过量的 1%。"},{"id":"36.6","t":"清除率及其应用","s":3,"c":"36. 肾小球的滤过","x":"清除率指单位时间内肾能将多少毫升血浆中的某物质完全清除，C =(U×V)/P（U 为尿中浓度、V 为每分钟尿量、P 为血浆浓度）。（1）菊粉可自由滤过而不被重吸收或分泌，其清除率即 GFR（约 125 mL/min）；（2）对氨基马尿酸（PAH）经滤过与分泌几乎全部被清除，其清除率反映有效肾血浆流量（约 600 mL/min）；（3）葡萄糖清除率为 0（全部重吸收），出现糖尿时升高；（4）肌酐清除率接近 GFR，临床常用内生肌酐清除率估算肾功能（CKD 分期依据）；（5）尿素清除率小于 GFR（被重吸收）。由 GFR 与肾血浆流量之比可得滤过分数约 20%。"},{"id":"37.1","t":"重吸收概述","s":3,"c":"37. 肾小管与集合管的重吸收和分泌","x":"原尿中 99% 的水、全部葡萄糖与氨基酸、大部分 Na⁺、Cl⁻、HCO₃⁻ 被重吸收，K⁺ 约 90% 被重吸收。重吸收方式包括主动（原发与继发）与被动。近端小管重吸收约 65%~70% 的 Na⁺ 与水、全部葡萄糖与氨基酸、85% 的HCO₃⁻，且为等渗性重吸收；髓袢重吸收约 20% 的 Na⁺ 与水；远端小管与集合管重吸收约 10%，且受激素调节（醛固酮、ADH），是决定终尿量与成分的关键部位（“精细调节段”）。"},{"id":"37.2","t":"近端小管的重吸收","s":3,"c":"37. 肾小管与集合管的重吸收和分泌","x":"（1）Na⁺：基侧膜 Na⁺/K⁺-ATP 酶将 Na⁺ 泵出，形成管内负电位与 Na⁺浓度梯度，Na⁺ 经顶端膜的 Na⁺-葡萄糖（SGLT2）、Na⁺-氨基酸同向转运与Na⁺/H⁺ 交换进入细胞（“泵-漏”模式）；（2）水：随溶质等渗重吸收（AQP1），不受 ADH 调节；（3）葡萄糖：SGLT2 继发主动转运全部重吸收；（4）HCO₃⁻：以 CO₂ 形式扩散入细胞（依赖碳酸酐酶），85% 在此重吸收；（5）K⁺：大部分被动重吸收。"},{"id":"37.3","t":"髓袢的重吸收","s":3,"c":"37. 肾小管与集合管的重吸收和分泌","x":"降支细段：对水通透（AQP1）、对 NaCl 与尿素不通透，故小管液在下行中逐渐浓缩（渗透压从 300 升至 1 200 mOsm）。升支细段：对水不通透、对NaCl 通透，NaCl 被动扩散出管（小管液变稀）。升支粗段：Na⁺-K⁺-2Cl⁻ 同向转运体主动重吸收 NaCl（依赖基侧膜钠泵），对水不通透，是“稀释段”，也是袢利尿剂（速尿）的作用位点。髓袢通过“单效”（只重吸收NaCl 不重吸收水）建立髓质渗透梯度。"},{"id":"37.4","t":"远端小管与集合管的重吸收与分泌","s":3,"c":"37. 肾小管与集合管的重吸收和分泌","x":"远曲小管与集合管：Na⁺ 重吸收受醛固酮调节（主细胞顶端膜 Na⁺ 通道ENaC 与基侧膜钠泵），并伴随 K⁺ 分泌（Na⁺ 重吸收与 K⁺ 分泌耦联，故保钠同时排钾）；主细胞分泌 K⁺（受血 K⁺ 浓度、醛固酮、小管液流速影响）；闰细胞（A 型）泌 H⁺（H⁺-ATP 酶）与重吸收 Cl⁻；集合管对水的通透性由ADH 经 V2 受体-cAMP-AQP2 水通道调节，是决定终尿渗透压的关键。"},{"id":"37.5","t":"葡萄糖的重吸收与肾糖阈","s":3,"c":"37. 肾小管与集合管的重吸收和分泌","x":"葡萄糖重吸收依赖 SGLT2（近端小管前段，低亲和力大容量）与 SGLT1（后段，高亲和力）。当血糖超过 10 mmol/L（180 mg/dL）时，部分肾单位的转运体饱和，尿中出现葡萄糖，此血糖浓度称肾糖阈；血糖继续升高至 16.7 mmol/L（300 mg/dL）左右全部肾单位饱和，达最大转运率（Tm，约 375 mg/min 男性）。糖尿病时血糖超过肾糖阈出现糖尿，并因渗透性利尿而多尿。"},{"id":"37.6","t":"肾小管的分泌功能","s":3,"c":"37. 肾小管与集合管的重吸收和分泌","x":"（1）H⁺：近端小管 Na⁺/H⁺ 交换、远端与集合管 H⁺-ATP 酶；（2）K⁺：远端与集合管主细胞分泌（受醛固酮、血 K⁺、酸碱状态影响，酸中毒时泌 K⁺ 减少）；（3）NH₃/NH₄⁺：近端小管上皮由谷氨酰胺生成 NH₃，与 H⁺结合成 NH₄⁺ 排出，是排酸的重要方式；（4）有机酸与有机碱：近端小管主动分泌青霉素、头孢菌素、水杨酸、组胺等，与蛋白结合率高的药物竞争，故丙磺舒可延长青霉素作用。"},{"id":"37.7","t":"尿的理化性质","s":2,"c":"37. 肾小管与集合管的重吸收和分泌","x":"正常尿液淡黄透明，比重 1.015~1.025，pH 5.0~7.0（受饮食影响，肉食偏酸、素食偏碱），渗透压 50~1 200 mOsm/(kg·H₂O)。成分：水96%~99%、尿素、尿酸、肌酐、Na⁺、K⁺、Cl⁻、磷酸盐、硫酸盐、少量激素与代谢产物。异常：糖尿、蛋白尿、血尿、血红蛋白尿、酮尿、胆红素尿；尿比重固定在 1.010 左右提示肾浓缩功能严重受损。"},{"id":"38.1","t":"逆流倍增机制","s":3,"c":"38. 尿液的浓缩与稀释","x":"髓质渗透压由外髓向内髓递增（300 → 1 200 mOsm），形成的前提是：（1）髓袢升支粗段主动重吸收 NaCl 而对水不通透（单效重吸收），使外髓组织液高渗；（2）髓袢降支细段对水通透、对 NaCl 不通透，小管液在下行中浓缩；（3）内髓高渗由 NaCl 与尿素共同形成（尿素从内髓集合管扩散入组织液，再经直小血管与髓袢循环）。逆流倍增使小管液在髓袢内的渗透压呈“U”形变化：降支末可达 1 200 mOsm，升支末端降至约 100 mOsm（低渗）。"},{"id":"38.2","t":"直小血管的逆流交换","s":3,"c":"38. 尿液的浓缩与稀释","x":"直小血管呈发夹状伴随髓袢，下行支与上行支之间进行逆流交换：下降时摄取溶质、上升时又把溶质带回，从而既为髓质供血又不把溶质冲走，维持髓质高渗梯度。直小血管血流增加（如高血压、利尿剂过量）时会“洗脱”髓质溶质，使浓缩能力下降。"},{"id":"38.3","t":"尿素的再循环","s":2,"c":"38. 尿液的浓缩与稀释","x":"尿素由内髓集合管经尿素转运体（UT-A1、UT-A3，受 ADH 调节）扩散入内髓组织液，再进入髓袢升支细段与直小血管，形成再循环，是内髓高渗的重要成分（约占内髓渗透压的 40%~50%）。长期高蛋白饮食者尿素生成多，浓缩能力较强；低蛋白饮食者髓质尿素减少，浓缩能力下降。"},{"id":"38.4","t":"ADH 与尿的浓缩","s":3,"c":"38. 尿液的浓缩与稀释","x":"ADH（血管升压素）由下丘脑视上核与室旁核合成，经下丘脑-垂体束运至神经垂体储存释放，是九肽。作用：与集合管主细胞基侧膜 V2 受体结合 →激活腺苷酸环化酶 → cAMP 升高 → PKA 磷酸化 → AQP2 水通道插入顶端膜（“穿梭”机制）→ 水在髓质高渗驱动下大量重吸收 → 尿浓缩（尿量减少、渗透压升高至 1 200 mOsm）。ADH 缺乏（中枢性尿崩症）或肾对 ADH 不敏感（肾性尿崩症）时排出大量低渗尿（每日可达 10~20 L）。"},{"id":"38.5","t":"尿的稀释","s":3,"c":"38. 尿液的浓缩与稀释","x":"当血浆渗透压降低（大量饮水）时 ADH 分泌减少，集合管对水不通透，同时髓袢升支粗段继续重吸收 NaCl 而不重吸收水，故小管液被稀释至 100 mOsm 以下，形成低渗尿排出（水利尿）。饮水 1 L 后约 30 分钟尿量开始增加、2 小时达高峰，尿渗透压可降至 50 mOsm。"},{"id":"38.6","t":"影响尿液浓缩的因素","s":2,"c":"38. 尿液的浓缩与稀释","x":"（1）髓袢长度（近髓肾单位比例、种属差异）；（2）髓质血流（直小血管）；（3）尿素浓度（蛋白质摄入）；（4）ADH 水平与受体敏感性；（5）髓袢升支粗段转运功能（袢利尿剂破坏浓缩）；（6）集合管对水的通透性。正常尿最大渗透压 1 200 mOsm、最低 50 mOsm，尿/血浆渗透压比可达 4~5倍；沙漠动物可达 20 倍以上。部位对水通透性主要转运激素调节近端小管高（AQP1）65%~70% Na⁺、全部葡萄糖无（等渗重吸收）髓袢降支细段高水外流，NaCl 不通透无髓袢升支粗段低Na⁺-K⁺-2Cl⁻ 主动重吸收无（稀释段）远曲小管低Na⁺ 重吸收、K⁺ 分泌醛固酮集合管可调（AQP2）Na⁺ 重吸收、尿素转运ADH、醛固酮"},{"id":"39.1","t":"肾血流与 GFR 的自身调节","s":3,"c":"39. 肾功能的调节","x":"（1）肌源性机制：入球小动脉平滑肌在灌注压升高时受牵张而收缩，使阻力增加、血流与 GFR 保持恒定；（2）管球反馈：远曲小管致密斑感受 NaCl浓度，NaCl 增加时释放腺苷等使入球小动脉收缩、肾素释放减少，从而降低GFR。自身调节范围为动脉压 80~180 mmHg，超出此范围（如大失血、休克）则 GFR 随血压下降，是急性肾损伤的机制之一。"},{"id":"39.2","t":"神经调节","s":3,"c":"39. 肾功能的调节","x":"肾交感神经兴奋（剧烈运动、失血、疼痛、情绪激动）：（1）入球与出球小动脉收缩（α 受体），肾血流量与 GFR 下降；（2）刺激球旁细胞 β1 受体释放肾素；（3）直接促进近端小管与髓袢重吸收 Na⁺（α1 受体）。肾副交感神经作用不明显。睡眠、安静时交感张力低，肾血流量增加。"},{"id":"39.3","t":"肾素-血管紧张素-醛固酮系统对肾的调节","s":3,"c":"39. 肾功能的调节","x":"肾素释放的刺激：肾灌注压下降、致密斑 NaCl 减少、交感神经兴奋（β1）。血管紧张素 II 使出球小动脉收缩（维持 GFR）、刺激醛固酮分泌、促进近端小管 Na⁺ 重吸收与 ADH 分泌、引起渴觉。醛固酮作用于远端小管与集合管主细胞：促进 Na⁺ 重吸收（ENaC 与钠泵）、促进 K⁺ 分泌、促进 H⁺分泌，故保钠、排钾、排 H⁺（可致碱中毒）。血 K⁺ 升高是刺激醛固酮分泌最强的因素。"},{"id":"39.4","t":"血管升压素（ADH）","s":3,"c":"39. 肾功能的调节","x":"ADH 释放的调节：（1）血浆晶体渗透压升高（最敏感，升高 1%~2% 即引起释放，由下丘脑渗透压感受器感受）；（2）循环血量减少（降低5%~10% 时经心肺容量感受器反射性增加 ADH）；（3）动脉压下降（压力感受器）；（4）其他：疼痛、情绪紧张、尼古丁、某些药物促进释放，乙醇抑制释放（故饮酒多尿）。ADH 通过 V2 受体-AQP2 增加水重吸收，通过 V1 受体收缩血管。"},{"id":"39.5","t":"心房钠尿肽与其他激素","s":2,"c":"39. 肾功能的调节","x":"心房钠尿肽（ANP）在心房容积增大（血容量增加）时释放，作用于肾：舒张入球小动脉、收缩出球小动脉使 GFR 增加；抑制集合管 Na⁺ 重吸收；抑制肾素与醛固酮分泌；抑制 ADH 释放，从而利钠、利尿、降血压。其他：PTH 促进远端小管 Ca²⁺ 重吸收、抑制近端小管磷酸盐重吸收；前列腺素（PGE2、PGI2）在交感兴奋或肾缺血时舒张肾血管、维持肾血流；缓激肽促进水钠排出。"},{"id":"39.6","t":"水与钠平衡的整合调节","s":2,"c":"39. 肾功能的调节","x":"细胞外液渗透压主要由 ADH 调节（水平衡），细胞外液容量主要由醛固酮-RAAS 与 ANP 调节（钠平衡）。失水（渗透压升高）时 ADH 升高、尿浓缩、口渴饮水；失盐（容量减少）时 RAAS 激活、醛固酮升高、尿钠减少。二者相互配合维持渗透压与容量的双重稳定，但“容量优先”：严重失血时即使渗透压降低，ADH 也因容量减少而升高（维持血压）。"},{"id":"40.1","t":"肾在酸碱平衡中的作用","s":3,"c":"40. 酸碱平衡的调节","x":"肾通过三个机制排酸保碱：（1）近端小管的 Na⁺/H⁺ 交换（约 85% 的HCO₃⁻ 重吸收依赖此），每排 1 个 H⁺ 回收 1 个 HCO₃⁻；（2）远端小管与集合管闰细胞的 H⁺-ATP 酶泵泌 H⁺（可对抗 1 000 倍浓度差），同时重吸收HCO₃⁻；（3） NH₄⁺ 的生成与排出：近端小管由谷氨酰胺生成 NH₃ 与NH₄⁺，NH₄⁺ 随尿排出（每排出 1 个 NH₄⁺ 相当于回收 1 个 HCO₃⁻），慢性酸中毒时此途径显著增强，是排 H⁺ 的主要方式。"},{"id":"40.2","t":"酸碱失衡时肾的代偿","s":2,"c":"40. 酸碱平衡的调节","x":"酸中毒：泌 H⁺、泌 NH₄⁺ 增加，HCO₃⁻ 重吸收增加，尿呈酸性（可滴定酸与 NH₄⁺ 增加），新生成 HCO₃⁻ 补充碱储备。碱中毒：泌 H⁺ 减少、HCO₃⁻ 排出增加（尿呈碱性），同时 K⁺ 排出增多（低钾）。肾的代偿缓慢（数小时至数日）但彻底，是长期酸碱平衡的最终调节者；呼吸代偿快（数分钟）但幅度有限。"},{"id":"40.3","t":"H⁺ 分泌与 K⁺ 的竞争","s":3,"c":"40. 酸碱平衡的调节","x":"远端小管与集合管的 H⁺ 与 K⁺ 分泌存在竞争：酸中毒时泌 H⁺ 增加、泌K⁺ 减少，引起高钾血症；碱中毒相反。反之，血 K⁺ 升高刺激醛固酮并抑制泌H⁺，可致酸中毒；低钾血症时 H⁺ 分泌增多，可致代谢性碱中毒。这一关系是“酸碱-电解质”关联的核心。"},{"id":"40.4","t":"肾脏对 HCO₃⁻ 的调节与酸碱指标","s":2,"c":"40. 酸碱平衡的调节","x":"HCO₃⁻ 的重吸收与再生（通过泌 H⁺ 与 NH₄⁺ 排出）使血浆 HCO₃⁻ 维持在 22~27 mmol/L。指标：pH 7.35~7.45、PaCO₂ 35~45 mmHg、HCO₃⁻22~27 mmol/L、碱剩余（BE）-3~+3 mmol/L、阴离子间隙（AG）8~16 mmol/L。AG 增大提示固定酸蓄积（酮症、乳酸、尿毒症、水杨酸中毒）；AG 正常提示 HCO₃⁻ 丢失（腹泻）或肾小管性酸中毒。"},{"id":"40.5","t":"阴离子间隙与混合型酸碱失衡","s":2,"c":"40. 酸碱平衡的调节","x":"阴离子间隙（AG）= Na⁺ - (Cl- + HCO3-)，正常 8~16 mmol/L，代表未测定的阴离子（白蛋白、乳酸、酮酸、磷酸盐、硫酸盐）。AG 增大提示固定酸蓄积（乳酸酸中毒、酮症酸中毒、尿毒症、水杨酸中毒）；AG 正常提示HCO3- 丢失（腹泻、肾小管性酸中毒）或大量输入生理盐水（稀释性）。混合型失衡常见于重症患者，如“高 AG 代谢性酸中毒 + 呼吸性碱中毒”（脓毒症）、“代谢性碱中毒 + 呼吸性酸中毒”（COPD 用利尿剂）。判断步骤：先看 pH 定酸或碱，再看 PaCO₂ 与 HCO3- 谁与 pH 同向变化（同向为原发），最后用预计代偿公式判断是否为混合型。"},{"id":"40.6","t":"肺与肾在酸碱调节中的分工","s":2,"c":"40. 酸碱平衡的调节","x":"肺调节快（数分钟至数小时）、只针对挥发性酸（CO₂），靠改变通气量调节 PaCO₂；肾调节慢（数小时至数日）、针对固定酸与碱的排出，靠重吸收HCO3-、泌 H⁺、泌 NH₄⁺。二者协同：代谢性酸中毒时先由呼吸加深加快代偿（PaCO₂ 下降），再由肾排 H⁺ 增加、HCO3- 再生；呼吸性酸中毒时肾代偿性增加 HCO3- 重吸收（需 3~5 天达最大）。代偿是“有限度的”，代偿后pH 仍略偏原方向，故“完全代偿”极为少见；代偿过度则提示混合型失衡。"},{"id":"41.1","t":"鱼类的鳃","s":3,"c":"41. 其他排泄器官","x":"鳃是鱼类的主要排泄与渗透调节器官：鳃丝上皮富含线粒体细胞（氯细胞/泌盐细胞），含大量 Na⁺/K⁺-ATP 酶。淡水鱼通过鳃主动吸收 Na⁺、Cl⁻（对抗浓度差）、排出大量 NH₃（占氮排泄的 60%~90%）与 CO₂；海水硬骨鱼通过氯细胞主动分泌 Na⁺、Cl⁻（泌盐）。鳃的逆流交换系统（水流与血流方向相反）使 O₂ 提取率达 80% 以上。氨的排出以 NH₃ 扩散与 NH₄⁺/Na⁺ 交换两种方式进行。"},{"id":"41.2","t":"盐腺","s":3,"c":"41. 其他排泄器官","x":"海鸟（信天翁、海鸥）、海龟、海蛇、鳄、鬣蜥等有盐腺（海鸟位于眼眶上方，又称鼻腺），分泌高渗 NaCl 溶液（浓度可达 800~1 000 mmol/L 以上），受副交感（胆碱能）神经支配，血流与分泌同步增加。盐腺使这些动物能饮用海水、摄食高盐食物并维持水平衡，其分泌量可达每日体重的 10%。鲨鱼直肠腺也具泌盐功能。"},{"id":"41.3","t":"昆虫的马氏管与直肠","s":3,"c":"41. 其他排泄器官","x":"马氏管是昆虫的主要排泄器官，为细长盲管，一端浸浴血淋巴、另一端开口于中后肠交界处，上皮细胞通过主动转运（K⁺ 泵）将 K⁺、Na⁺、尿酸、氨基酸与水排入管腔形成原尿，再经后肠（回肠、结肠、直肠）重吸收水分与有用物质，尿酸以结晶形式排出，实现“节水型”排泄。昆虫直肠垫（rectal pad）能主动重吸收水与离子，是强大的保水结构；沙漠甲虫可吸收空气中的水汽。其他排泄结构：蚜虫的蜜露、甲壳类的触角腺/绿腺。"},{"id":"41.4","t":"皮肤与汗腺","s":3,"c":"41. 其他排泄器官","x":"皮肤通过汗腺分泌汗液（低渗，含 Na⁺、Cl⁻、K⁺、尿素、乳酸、氨基酸），每日不感蒸发约 600~800 mL、可感蒸发（发汗）可达数升。汗腺受交感胆碱能纤维支配（与一般交感神经的肾上腺素能不同，是重要的例外），醛固酮可促进汗腺导管重吸收 Na⁺（长期热适应后汗液变淡，减少钠丢失）。皮肤还排泄少量尿素、尿酸与药物，并参与体温调节和维生素 D 合成。"},{"id":"41.5","t":"肺、消化道与肝的排泄","s":2,"c":"41. 其他排泄器官","x":"（1）肺：排出 CO₂、挥发性物质（乙醇、丙酮、麻醉气体）与水蒸气；（2）消化道：排出胆色素、胆固醇、部分药物与重金属，经粪便排出；（3）肝：通过胆汁排泄胆红素、胆汁酸与药物；（4）大肠：分泌 K⁺、HCO₃⁻，长期腹泻可致低钾。这些器官与肾共同构成机体的排泄系统，其中肾是排泄代谢终产物（尿素、尿酸、肌酐）的主要器官。动物类群主要排泄器官主要含氮终产物特点淡水鱼鳃、肾氨排氨型，吸水盐、排稀尿海水硬骨鱼鳃、肾氨吞海水、泌盐、少尿软骨鱼肾、直肠腺尿素保留尿素维持等渗两栖类（成体）肾尿素皮肤辅助呼吸与排泄爬行类、鸟类肾、盐腺尿酸尿酸不溶于水，节水昆虫马氏管尿酸直肠重吸收水哺乳类肾尿素髓袢浓缩尿，ADH 调节"},{"id":"41.6","t":"无脊椎动物的排泄器官","s":2,"c":"41. 其他排泄器官","x":"（1）甲壳类（虾、蟹）：触角腺（绿腺）或壳腺，由体腔囊演变而来，经主动转运排 K⁺、Na⁺ 与水，并调节离子平衡；（2）软体动物：肾脏（鲍雅氏器）由后肾管演变，排出氨（水生）或尿酸（陆生蜗牛）；（3）环节动物：后肾管（每体节一对），由肾口漏斗收集体腔液，经肾管重吸收后排出；（4）扁形动物与轮虫：原肾管与焰细胞（负压过滤，排氨与水）；（5）昆虫与蛛形纲：马氏管（昆虫）与基节腺（蛛形纲）。这些结构共同体现了“过滤—重吸收—排出”的基本模式，与脊椎动物肾单位在功能上高度趋同。"},{"id":"42.1","t":"淡水硬骨鱼的渗透调节","s":3,"c":"42. 水盐平衡策略","x":"淡水鱼体液渗透压约 300 mOsm，高于环境（约 10 mOsm），水不断渗入、盐不断流失。策略：（1）不饮水（或极少饮水）；（2）肾小球发达、排尿量大（可达体重的 5~10%/日）且尿稀（低渗）；（3）鳃的氯细胞主动吸收Na⁺、Cl⁻；（4）食物提供部分盐分。结果是水入与排出平衡、盐摄入与流失平衡，体液略高渗。"},{"id":"42.2","t":"海水硬骨鱼的渗透调节","s":3,"c":"42. 水盐平衡策略","x":"海水鱼体液约 300~400 mOsm，低于海水（约 1 000 mOsm），水不断渗出、盐不断渗入。策略：（1）大量吞饮海水（每日可达体重的 10%）；（2）肾小球退化、排尿少（1~2 mL/(kg·h)）且尿近等渗；（3）鳃氯细胞主动分泌 Na⁺、Cl⁻（Na⁺/K⁺-ATP 酶与 NKCC 协同）；（4）肠道吸收水而排出多余二价离子（Mg²⁺、SO₄²⁻ 随粪便排出）。"},{"id":"42.3","t":"软骨鱼与广盐性鱼类","s":2,"c":"42. 水盐平衡策略","x":"软骨鱼（鲨、鳐）血液中保留尿素（约 350~400 mmol/L）与氧化三甲胺（TMAO），使体液渗透压略高于海水，故水自动渗入，只需少量排尿，多余的盐由直肠腺排出（“等渗型”）。广盐性鱼类（鲑、鳟、鳗、罗非鱼）可在淡水与海水间迁移，通过改变鳃氯细胞形态（淡水型与海水型）、调整饮水与排尿量、改变肾小球滤过率来适应，由皮质醇与催乳素等激素调控。"},{"id":"42.4","t":"两栖类、爬行类与鸟类","s":2,"c":"42. 水盐平衡策略","x":"两栖类成体主要排尿素，皮肤通透性高、水分散失大，故需潮湿环境；蛙在陆地时膀胱可重吸收水（膀胱水囊作用）。爬行类与鸟类排尿酸（不溶于水，以半固体形式随粪排出），大大减少失水，是真正陆生的重要适应；鸟类缺少膀胱、尿与粪混合排出，海鸟另有盐腺。爬行类的肾为后肾、缺少髓袢（尿不能高度浓缩），故以尿酸形式弥补。"},{"id":"42.5","t":"陆生哺乳类的保水机制","s":3,"c":"42. 水盐平衡策略","x":"（1）髓袢与直小血管形成高渗髓质，可浓缩尿至 1 200 mOsm（沙漠啮齿类可达 6 000~9 000 mOsm）；（2）ADH 调节集合管 AQP2，口渴引起饮水行为；（3）皮肤角质层与皮脂减少不感蒸发；（4）肾小管对尿素的再循环利用；（5）排尿素而非尿酸（需较多水，故哺乳类保水依赖浓缩能力而非尿酸）。沙漠动物（骆驼、更格卢鼠）还通过减少尿量、干燥粪便、储水（驼峰脂肪代谢产水）适应干旱。"},{"id":"42.6","t":"渗透压调节类型的比较","s":2,"c":"42. 水盐平衡策略","x":"按体液与环境的关系分为：（1）变渗动物（osmoconformer，多数海洋无脊椎动物，体液与海水等渗）；（2）恒渗动物（osmoregulator，淡水鱼、海水硬骨鱼、鸟类、哺乳类，主动维持体液渗透压）。按含氮终产物分为排氨型（水生，毒性大但省能）、排尿素型（两栖类、哺乳类、软骨鱼，毒性低、需一定水）、排尿酸型（鸟类、爬行类、昆虫，最节水但耗能）。这一“能量-水”权衡是生态生理学的核心问题。第六篇 内分泌"},{"id":"43.1","t":"激素的分类","s":3,"c":"43. 激素的分类与作用机制","x":"（1）肽类与蛋白质激素（下丘脑释放激素、垂体激素、胰岛素、胰高血糖素、PTH、胃肠激素）：水溶性，作用于膜受体；（2）类固醇激素（肾上腺皮质激素、性激素、维生素 D）：脂溶性，作用于核受体；（3）胺类激素（甲状腺激素、儿茶酚胺）：甲状腺激素虽为胺类但作用如类固醇（核受体），儿茶酚胺作用如肽类（膜受体）；（4）脂肪酸衍生物（前列腺素、白三烯、血栓素）。"},{"id":"43.2","t":"激素作用的一般特征","s":3,"c":"43. 激素的分类与作用机制","x":"（1）特异性：只作用于有受体的靶细胞；（2）信息传递作用：作为“信使”调节代谢速度与方向，不提供能量、不参与结构、不产生新反应；（3）高效能：浓度极低（10⁻¹²~10⁻⁹ mol/L）即可显著作用，经逐级放大（1 个激素分子可促生成数千个 cAMP）；（4）协同与拮抗：如胰高血糖素与肾上腺素协同升糖，胰岛素与胰高血糖素拮抗；（5）允许作用：糖皮质激素本身不升糖，但使儿茶酚胺的升糖、缩血管作用得以实现。"},{"id":"43.3","t":"膜受体-cAMP 通路","s":3,"c":"43. 激素的分类与作用机制","x":"激素（如胰高血糖素、肾上腺素 β 型、ADH V2、TSH、ACTH）与受体结合 → 激活 Gs 蛋白 → 腺苷酸环化酶（AC）→ ATP 生成 cAMP → 激活蛋白激酶 A（PKA）→ 磷酸化靶蛋白（酶、通道、转录因子）→ 生理效应。cAMP由磷酸二酯酶（PDE）降解，咖啡因、茶碱抑制 PDE 而增强作用；霍乱毒素持续激活 Gs、百日咳毒素抑制 Gi。"},{"id":"43.4","t":"膜受体-磷脂酶 C 通路","s":3,"c":"43. 激素的分类与作用机制","x":"激素（如 ADH V1、α1 肾上腺素能、TRH、GnRH）→ Gq 蛋白 → 磷脂酶 C（PLC）→ 水解 PIP2 生成 IP3 与 DG：IP3 促内质网释放 Ca²⁺（经 IP3受体），DG 激活蛋白激酶 C（PKC）。Ca²⁺ 与钙调蛋白（CaM）结合调节多种酶（如平滑肌 MLCK），形成“双信使”系统。此通路在平滑肌收缩、腺体分泌、血小板活化中常见。"},{"id":"43.5","t":"酪氨酸激酶受体与受体酶通路","s":2,"c":"43. 激素的分类与作用机制","x":"胰岛素与 IGF-1 受体为酪氨酸激酶型：配体结合使受体自磷酸化 → 磷酸化 IRS-1 → 激活 PI3K-Akt 通路（促使 GLUT4 转位、糖原合成、蛋白合成）与 Ras-MAPK 通路（促增殖）。心房钠尿肽受体为膜结合型鸟苷酸环化酶，生成 cGMP 激活 PKG；NO 也通过可溶性鸟苷酸环化酶升高 cGMP 使血管舒张（硝酸甘油的机制）。"},{"id":"43.6","t":"核受体通路","s":3,"c":"43. 激素的分类与作用机制","x":"类固醇激素、甲状腺激素、维生素 D、视黄酸等脂溶性激素直接穿过细胞膜，与胞内或核内受体（受体超家族，含锌指 DNA 结合域）结合，受体二聚化后与靶基因的激素反应元件（HRE）结合，调节基因转录（增加或减少mRNA），进而改变酶与蛋白质的合成。特点是潜伏期长（数小时至数天）、作用持久、需合成新蛋白质；甲状腺激素核受体亲和力高，故 T3 的效应强而慢。"},{"id":"43.7","t":"激素分泌的调节方式","s":3,"c":"43. 激素的分类与作用机制","x":"（1）下丘脑-腺垂体-靶腺轴的逐级调节与负反馈（如TRH-TSH-T3/T4）；（2）神经调节（交感-肾上腺髓质、迷走-胰岛素）；（3）血浆某物质浓度的直接调节（血糖-胰岛素、血钙-PTH、渗透压-ADH）。此外激素的分泌有节律（皮质醇晨高夜低、GH 深睡时分泌峰、褪黑素夜间高），并受年龄、性别、应激影响。激素类型代表受体位置第二信使/机制起效速度肽类胰岛素、胰高血糖素膜受体cAMP 或酪氨酸激酶分钟儿茶酚胺肾上腺素膜受体（α、β）cAMP、IP3/DG秒~分钟类固醇皮质醇、雌二醇核受体基因转录小时~天甲状腺激素T3、T4 PGE2核受体基因转录cAMP天脂肪酸衍生物膜受体分钟"},{"id":"44.1","t":"下丘脑-腺垂体的联系","s":3,"c":"44. 下丘脑-垂体轴","x":"下丘脑与腺垂体之间通过垂体门脉系统（正中隆起毛细血管网 → 垂体门脉→ 腺垂体血窦）联系，属“血管联系”；下丘脑肽能神经元将释放激素或抑制激素分泌入正中隆起毛细血管，经门脉到达腺垂体调节其分泌。与神经垂体之间为“神经联系”（下丘脑-垂体束）。这是神经调节与体液调节相互衔接的关键结构。"},{"id":"44.2","t":"下丘脑调节肽","s":3,"c":"44. 下丘脑-垂体轴","x":"促甲状腺激素释放激素（TRH，三肽）、促性腺激素释放激素（GnRH，十肽，脉冲式释放）、促肾上腺皮质激素释放激素（CRH，41 肽）、生长激素释放激素（GHRH）与生长抑素（GHIH）、催乳素释放因子与抑制因子（多巴胺为主要的生理性抑制因子）、促黑激素释放与抑制因子。下丘脑还产生 ADH 与催产素（运输至神经垂体）。"},{"id":"44.3","t":"腺垂体激素","s":3,"c":"44. 下丘脑-垂体轴","x":"腺垂体（垂体前叶）分泌 7 种激素：生长激素（GH）、促甲状腺激素（TSH）、促肾上腺皮质激素（ACTH）、促卵泡激素（FSH）、黄体生成素（LH）、催乳素（PRL）、促黑激素（MSH）。其中 TSH、ACTH、FSH、LH 分别作用于甲状腺、肾上腺皮质、性腺（“促激素”），GH 与 PRL 直接作用于多种组织。腺垂体的分泌受下丘脑释放激素与靶腺激素负反馈的双重调节。"},{"id":"44.4","t":"生长激素的作用与调节","s":3,"c":"44. 下丘脑-垂体轴","x":"GH 是 191 个氨基酸的蛋白质激素，分泌呈脉冲式（深睡时出现大峰）。作用：（1）促进生长：经肝脏生成 IGF-1（生长介素）促进软骨与骨生长（骨骺未闭合时），故幼年缺乏致侏儒症、过多致巨人症，成年后过多致肢端肥大症；（2）促进蛋白质合成（正氮平衡）；（3）促进脂肪分解、抑制糖利用（升高血糖，“抗胰岛素”作用，过量可致垂体性糖尿）；（4）参与应激。调节：GHRH 促进、生长抑素抑制，IGF-1 与 GH 本身负反馈，低血糖、饥饿、运动、深睡、雌激素促进分泌。"},{"id":"44.5","t":"神经垂体激素","s":3,"c":"44. 下丘脑-垂体轴","x":"神经垂体（垂体后叶）不合成激素，只储存与释放下丘脑合成的两种九肽：（1）抗利尿激素（ADH，血管升压素，主要由视上核合成）：增加集合管水通透性（V2-AQP2）、大剂量收缩血管（V1）；（2）催产素（主要由室旁核合成）：分娩时刺激子宫平滑肌收缩（正反馈）、射乳反射（吸吮刺激乳头→传入→下丘脑→释放→乳腺肌上皮收缩射乳）。两者均经神经垂体释放入血。"},{"id":"44.6","t":"催乳素的作用","s":2,"c":"44. 下丘脑-垂体轴","x":"PRL 由腺垂体嗜酸性细胞分泌，作用：（1）促进乳腺发育（与雌激素、孕激素、GH、皮质醇协同）与泌乳（妊娠期高雌激素抑制泌乳，分娩后抑制解除而泌乳）；（2）促进黄体形成与维持（啮齿类）；（3）抑制 GnRH 释放（哺乳期闭经的机制）；（4）参与应激与免疫调节。调节以抑制性为主：下丘脑分泌多巴胺经门脉抑制 PRL 分泌，故切断垂体柄或服用多巴胺受体拮抗剂（氯丙嗪）时 PRL 升高。"},{"id":"44.7","t":"腺垂体功能异常","s":2,"c":"44. 下丘脑-垂体轴","x":"（1）垂体性侏儒症：幼年 GH 缺乏，身材匀称矮小、智力正常；（2）巨人症与肢端肥大症：GH 过多（骨骺闭合前/后）；（3）席汉综合征：产后大出血致垂体缺血坏死，出现无乳、闭经、甲状腺与肾上腺功能减退；（4）垂体瘤压迫视交叉引起双颞侧偏盲；（5）尿崩症：ADH 缺乏（中枢性）或肾不敏感（肾性），表现为多尿、烦渴、低渗尿。下丘脑激素腺垂体激素靶腺/组织主要效应TRH TSH甲状腺合成与释放 T3、T4 CRH ACTH肾上腺皮质束状带分泌皮质醇GnRH性腺配子发生与性激素分泌GHRH / 生长抑素FSH、LH GH肝、骨、肌肉生长、蛋白合成、升糖多巴胺（抑制）PRL乳腺泌乳—（神经垂体）ADH肾集合管水重吸收—（神经垂体）催产素子宫、乳腺分娩、射乳"},{"id":"45.1","t":"甲状腺激素的合成","s":3,"c":"45. 甲状腺激素","x":"甲状腺滤泡上皮细胞经钠-碘同向转运体（NIS）主动摄碘（“碘捕获”，可浓缩 25~50 倍）；在滤泡腔内甲状腺过氧化物酶（TPO）催化碘活化（I- →I2 或活性碘）并使酪氨酸残基碘化，生成一碘酪氨酸（MIT）与二碘酪氨酸（DIT），再偶联成 T4（DIT+DIT）与 T3（MIT+DIT）；以甲状腺球蛋白（Tg）形式储存在胶质中。释放时滤泡细胞吞饮胶质，经溶酶体水解酶释放T4（约 90%）与 T3（约 10%）入血，血中 T3 约 80% 由 T4 在外周（肝、肾）经 5'-脱碘酶转化而来。"},{"id":"45.2","t":"甲状腺激素的运输与储存","s":2,"c":"45. 甲状腺激素","x":"血中 99% 以上的 T4、T3 与甲状腺素结合球蛋白（TBG）、前白蛋白、白蛋白结合，游离部分（FT4 约 0.03%、FT3 约 0.3%）才具生物活性。甲状腺是体内唯一大量储存激素的内分泌腺，储存量可供 2~3 个月需要，故甲状腺功能减退的症状出现缓慢。T3 的生物活性约为 T4 的 3~5 倍，起效快、半衰期短（T3 约 1 天、T4 约 7 天）。"},{"id":"45.3","t":"甲状腺激素的生理作用","s":3,"c":"45. 甲状腺激素","x":"（1）促进能量代谢：提高全身组织耗氧量与产热量（BMR 升高），促进线粒体氧化磷酸化（部分解偶联）；（2）促进生长发育：尤其对神经系统（胎儿与婴幼儿期缺乏致智力低下）与骨骼（促进骨骺生长）；（3）蛋白质代谢：适量促进合成（正氮平衡），过量促进分解（负氮平衡、肌萎缩）；（4）糖代谢：促进糖吸收与糖异生，使血糖升高；（5）脂肪代谢：促进脂肪分解与胆固醇降解（甲减时血胆固醇升高）；（6）对心血管：提高心肌对儿茶酚胺的敏感性（受体上调）、心率加快、心输出量增加；（7）对神经系统：维持中枢兴奋性（甲亢易激动、失眠，甲减淡漠、嗜睡）。"},{"id":"45.4","t":"甲状腺功能的调节","s":3,"c":"45. 甲状腺激素","x":"（1）下丘脑-腺垂体-甲状腺轴：TRH → TSH（促进甲状腺摄碘、合成与释放激素、促进腺体增生与血管生成）→ T3/T4 → 负反馈抑制 TRH 与 TSH；（2）甲状腺的自身调节：碘供应过多时抑制激素合成（Wolff-Chaikoff 效应，可解释高碘性甲状腺肿）；（3）自主神经：交感促进、副交感抑制分泌；（4）其他：雌激素使 TBG 升高（妊娠期总 T4 升高但游离 T4 正常），严重应激、饥饿抑制 T4 转化为 T3（反向 T3 增多）。"},{"id":"45.5","t":"甲状腺疾病","s":3,"c":"45. 甲状腺激素","x":"（1）甲状腺功能亢进（甲亢）：Graves 病由 TSH 受体抗体（TRAb）刺激引起，表现为 BMR 升高、怕热多汗、心悸、消瘦、突眼、甲状腺肿大，血T3/T4 升高、TSH 降低；（2）甲状腺功能减退（甲减）：黏液性水肿（黏多糖沉积）、怕冷、淡漠、BMR 降低，幼年发病为呆小症（克汀病，智力与身材均落后）；（3）地方性甲状腺肿（碘缺乏，山区“大脖子病”），补碘可预防；（4）甲状腺髓样癌（来自滤泡旁 C 细胞，分泌降钙素）；（5）甲状腺炎（桥本甲状腺炎为自身免疫性，后期甲减）。"},{"id":"45.6","t":"碘代谢与甲状腺疾病的关系","s":2,"c":"45. 甲状腺激素","x":"碘是合成甲状腺激素的必需元素，成人每日需碘约 150 μg（孕妇 200μg），世界卫生组织推荐食盐加碘（我国曾用 1/2 万~1/5 万碘盐）。缺碘时甲状腺激素合成不足、TSH 代偿性升高、甲状腺代偿性肿大；长期严重缺碘影响胎儿脑发育（地方性克汀病）。碘过量也可致甲状腺肿或诱发自身免疫性甲状腺炎。"},{"id":"46.1","t":"甲状旁腺激素（PTH）","s":3,"c":"46. 甲状旁腺与钙磷调节","x":"PTH 由甲状旁腺主细胞分泌，为 84 肽，是升高血钙的最重要激素。作用靶器官：（1）骨：促进破骨细胞活动（经成骨细胞介导）、骨钙释放（快速相为骨细胞性溶骨，慢相为破骨细胞性骨吸收）；（2）肾：促进远端小管重吸收Ca²⁺、抑制近端小管重吸收磷酸盐（尿磷增加、血磷降低）、促进 1α-羟化酶生成活性维生素 D；（3）肠：通过活性维生素 D 间接促进钙吸收。调节：血Ca²⁺ 降低刺激 PTH 分泌（最敏感因素），血磷升高、1,25-(OH)2D3 升高抑制其分泌。"},{"id":"46.2","t":"降钙素（CT）","s":3,"c":"46. 甲状旁腺与钙磷调节","x":"降钙素由甲状腺滤泡旁细胞（C 细胞）分泌，32 肽，作用与 PTH 相反：抑制破骨细胞活动（骨钙释放减少）、促进骨钙沉积、抑制肾小管重吸收钙与磷（尿钙磷增加）。调节：血 Ca²⁺ 升高刺激分泌（作用快而短暂），胃泌素、CCK、胰高血糖素也促进。降钙素在成人日常钙调节中作用较小（主要在高钙时保护），在鱼类（鳃体）与鸟类作用较强。临床用鲑鱼降钙素治疗高钙血症与骨质疏松。"},{"id":"46.3","t":"维生素 D","s":3,"c":"46. 甲状旁腺与钙磷调节","x":"皮肤中 7-脱氢胆固醇经紫外线（290~315 nm）照射生成维生素 D3，或由食物摄入 D2/D3；经肝 25-羟化酶生成 25-(OH)D3（体内主要储存形式，也是评价营养状况的指标），再经肾近端小管 1α-羟化酶生成 1,25-(OH)2D3（活性形式，即钙三醇）。作用：促进小肠吸收钙与磷（诱导钙结合蛋白 CaBP）、促进骨矿化与骨重建（既促骨形成又促吸收）、促进远端小管重吸收钙磷。PTH 促进 1α-羟化酶，故 PTH 与维生素 D 协同升钙。"},{"id":"46.4","t":"血钙磷的整合调节","s":3,"c":"46. 甲状旁腺与钙磷调节","x":"血钙正常 2.25~2.75 mmol/L（9~11 mg/dL），其中约 50% 为游离钙（离子钙，生理活性部分），约 40% 与蛋白结合，10% 与阴离子结合。血钙降低 → PTH 分泌增加 → 骨钙释放、肾保钙排磷、活性维生素 D 增加 → 肠钙吸收增加 → 血钙回升；血钙升高 → 降钙素分泌增加 → 抑制骨吸收、促尿钙排出 → 血钙下降。血钙与血磷呈相反关系（PTH 排磷、CT 排磷、维生素 D 吸收两者）。"},{"id":"46.5","t":"钙磷代谢疾病","s":2,"c":"46. 甲状旁腺与钙磷调节","x":"（1）甲状旁腺功能减退：血钙降低、血磷升高，出现手足搐搦（低钙使神经肌肉兴奋性升高）、喉痉挛；（2）甲状旁腺功能亢进：骨痛、骨质疏松、肾结石（“骨、石、腹、精神”），血钙升高、血磷降低；（3）维生素 D 缺乏：儿童佝偻病（骨骺软骨增生、方颅、鸡胸、O 型腿）、成人骨软化症；（4）骨质疏松：骨量减少、易骨折，与雌激素下降、钙与维生素 D 不足、缺乏运动有关。激素PTH来源血钙血磷骨肾肠甲状旁腺主细胞升高降低溶骨、释放钙保钙排磷间接促吸收降钙素甲状腺 C 细胞降低降低抑制破骨、促钙沉积排钙排磷无直接作用1,25(OH)2D3肾生成（皮肤+肝参与）升高升高促矿化与重建促重吸收促吸收钙磷"},{"id":"46.6","t":"钙的生理功能与血钙稳定的意义","s":3,"c":"46. 甲状旁腺与钙磷调节","x":"体内钙约 1 000~1 200 g，99% 以羟基磷灰石形式储存于骨（骨钙库），仅约 1% 存在于细胞外液。钙的生理功能：（1）维持神经肌肉兴奋性（血钙降低使阈电位下移、兴奋性升高，出现手足搐搦、喉痉挛；血钙过高则兴奋性降低、肌无力、心律失常）；（2）参与兴奋-收缩耦联与肌肉收缩；（3）作为第二信使参与激素分泌、神经递质释放与信号转导；（4）参与血液凝固（因子IV）；（5）维持细胞膜通透性与黏附；（6）构成骨骼与牙齿。故血钙必须严格稳定在 2.25~2.75 mmol/L，由 PTH、降钙素与维生素 D 三重调节，其中PTH 是升钙的主导激素。"},{"id":"47.1","t":"肾上腺皮质的分层与激素","s":3,"c":"47. 肾上腺","x":"肾上腺皮质由外向内分三层：（1）球状带（占 15%）：分泌醛固酮（盐皮质激素），受 RAAS 与血 K⁺ 调节；（2）束状带（占 78%）：分泌皮质醇（糖皮质激素），受 ACTH 调节；（3）网状带（占 7%）：分泌雄激素（脱氢表雄酮、雄烯二酮）与少量雌激素，受 ACTH 调节。三层共同结构特征是含大量脂滴（类固醇合成原料为胆固醇）。"},{"id":"47.2","t":"糖皮质激素的作用","s":3,"c":"47. 肾上腺","x":"（1）糖代谢：促进糖异生（肝）、抑制外周组织摄取与利用葡萄糖，使血糖升高；（2）蛋白质代谢：促进肝外蛋白分解（肌萎缩、皮肤变薄）；（3）脂肪代谢：促进脂肪分解，但使脂肪重新分布（向心性肥胖、满月脸、水牛背）；（4）对心血管：允许作用——维持血管对儿茶酚胺的反应性；（5）抗炎、抗免疫、抗过敏：抑制炎症介质（前列腺素、白三烯）生成、抑制淋巴细胞与巨噬细胞功能、减少抗体生成；（6）对血细胞：使红细胞、中性粒细胞、血小板增多，淋巴细胞与嗜酸性粒细胞减少；（7）对骨：抑制成骨细胞、促进骨吸收（长期使用致骨质疏松）；（8）应激时大量分泌，维持血压与血糖。"},{"id":"47.3","t":"糖皮质激素分泌的调节","s":3,"c":"47. 肾上腺","x":"CRH → ACTH → 皮质醇，皮质醇负反馈抑制 CRH 与 ACTH。ACTH 还促进肾上腺皮质增生与维持其对刺激的反应性。分泌呈昼夜节律（清晨 6~8 时最高、午夜最低，与 ACTH 节律一致），故临床用糖皮质激素宜在清晨给药以减少对 HPA 轴的抑制。长期大剂量使用糖皮质激素后突然停药，可致肾上腺皮质功能不全（医源性肾上腺皮质萎缩），必须逐渐减量。"},{"id":"47.4","t":"盐皮质激素（醛固酮）的作用","s":3,"c":"47. 肾上腺","x":"醛固酮作用于肾远端小管与集合管主细胞：增加顶端膜 Na⁺ 通道（ENaC）与基侧膜 Na⁺/K⁺-ATP 酶表达，促进 Na⁺ 重吸收（伴水潴留）、K⁺ 分泌与 H⁺ 分泌，故“保钠、排钾、排氢”。也作用于汗腺、唾液腺与结肠促 Na⁺ 重吸收。调节：RAAS（血管紧张素 II 最强）、血 K⁺ 升高（直接刺激，最敏感）、血 Na⁺ 降低、ACTH（弱）。醛固酮过多引起低钾性碱中毒与高血压。"},{"id":"47.5","t":"肾上腺髓质激素","s":3,"c":"47. 肾上腺","x":"肾上腺髓质嗜铬细胞受交感节前纤维（内脏大神经）直接支配，分泌肾上腺素（约 80%）与去甲肾上腺素（约 20%），属“交感-肾上腺髓质系统”。作用见第 19 章：肾上腺素强心、升血糖、舒张骨骼肌与支气管（β2），去甲肾上腺素强烈缩血管升压（α）。髓质激素的分泌受交感神经、ACTH 与糖皮质激素（促进甲基化生成肾上腺素）调节，在应激（恐惧、寒冷、低血糖、创伤）时大量释放，与糖皮质激素协同构成“应激反应”的两大系统。"},{"id":"47.6","t":"肾上腺疾病","s":2,"c":"47. 肾上腺","x":"（1）库欣综合征（皮质醇过多）：向心性肥胖、满月脸、紫纹、高血压、高血糖、骨质疏松、易感染；（2）艾迪生病（原发性肾上腺皮质功能减退）：低血压、低血糖、低血钠、高血钾、皮肤色素沉着（ACTH 升高）、乏力；（3）原发性醛固酮增多症（Conn 综合征）：高血压、低血钾、碱中毒；（4）先天性肾上腺皮质增生（21-羟化酶缺陷）：皮质醇合成不足、ACTH 升高、雄激素过多（女性男性化）；（5）嗜铬细胞瘤：阵发性高血压、心悸、多汗；（6）应激性溃疡与长期激素治疗的副作用。"},{"id":"48.1","t":"胰岛的细胞组成","s":3,"c":"48. 胰岛","x":"胰岛（朗格汉斯岛）散在于胰腺外分泌部之间，成人约 100 万个。细胞类型：B（β）细胞占 60%~70%，分泌胰岛素；A（α）细胞占 20%~25%，分泌胰高血糖素；D（δ）细胞占 5%~10%，分泌生长抑素；PP 细胞分泌胰多肽；D1 细胞分泌 VIP。胰岛内有丰富的缝隙连接与血管，细胞间相互调节（旁分泌）。"},{"id":"48.2","t":"胰岛素的合成与分泌","s":3,"c":"48. 胰岛","x":"胰岛素由 B 细胞合成，先合成前胰岛素原 → 胰岛素原（86 肽）→ 在高尔基体裂解为胰岛素（51 肽，A 链 21 肽 + B 链 30 肽，由二硫键连接）与 C 肽（31 肽），二者等量释放入血，故测 C 肽可反映内生胰岛素分泌。分泌调节：血糖升高是最主要的刺激（>5.5 mmol/L 开始，10~15 mmol/L 达最大），氨基酸（精氨酸、亮氨酸）、胃肠激素（GIP、GLP-1，肠促胰岛素效应）、迷走神经与 β2 受体激动促进；肾上腺素（α2）、生长抑素、胰岛素本身抑制。"},{"id":"48.3","t":"胰岛素的作用","s":3,"c":"48. 胰岛","x":"胰岛素是唯一降低血糖的激素。作用：（1）糖代谢：促进肌肉与脂肪组织摄取葡萄糖（GLUT4 转位）、促进肝与肌糖原合成、抑制糖异生与糖原分解，使血糖下降；（2）脂肪代谢：促进脂肪合成与储存、抑制脂肪分解（缺乏时脂肪动员、酮体生成）；（3）蛋白质代谢：促进氨基酸摄取与蛋白合成、抑制蛋白分解；（4）促进 K⁺ 进入细胞（与葡萄糖同用可纠正高钾血症）；（5）促进细胞生长（与 IGF-1 受体交叉作用）。靶器官主要为肝、肌肉、脂肪。"},{"id":"48.4","t":"胰高血糖素的作用与调节","s":3,"c":"48. 胰岛","x":"胰高血糖素由 A 细胞分泌，29 肽，作用与胰岛素相反：（1）强烈促进肝糖原分解与糖异生，升高血糖；（2）促进脂肪分解与酮体生成；（3）促进蛋白质分解；（4）增强心肌收缩力（不依赖 β 受体，临床用于 β 阻滞剂过量）。调节：血糖降低（<3.9 mmol/L）刺激分泌、血氨基酸升高刺激、交感与肾上腺素促进、胰岛素与生长抑素抑制。血糖的稳定依赖胰岛素与胰高血糖素（以及肾上腺素、皮质醇、GH）的平衡。"},{"id":"48.5","t":"糖尿病","s":3,"c":"48. 胰岛","x":"（1）1 型（胰岛素依赖型）：自身免疫破坏 B 细胞，胰岛素绝对缺乏，多见于青少年，易发生酮症酸中毒，需终身注射胰岛素；（2）2 型（非胰岛素依赖型）：胰岛素抵抗伴分泌相对不足，与肥胖、遗传、生活方式有关，占 90%以上，治疗用二甲双胍（抑制肝糖输出、改善胰岛素敏感性）、磺脲类（促胰岛素分泌）、GLP-1 受体激动剂等。典型症状“三多一少”（多饮、多食、多尿、体重减少），因血糖超过肾糖阈引起渗透性利尿。并发症：视网膜病变、肾病、神经病变、动脉粥样硬化、糖尿病足。"},{"id":"48.6","t":"血糖的调节与正常值","s":3,"c":"48. 胰岛","x":"空腹血糖 3.9~6.1 mmol/L（葡萄糖氧化酶法），餐后 2 小时 <7.8 mmol/L。升糖激素：胰高血糖素、肾上腺素、糖皮质激素、生长激素、甲状腺激素（五者作用环节不同：糖原分解、糖异生、抑制外周利用）；降糖激素：仅胰岛素（以及运动与餐后肠道激素的辅助）。血糖低于 2.8 mmol/L 出现低血糖反应（交感兴奋、出汗、心悸，继而中枢抑制、昏迷），低于 1 mmol/L 可致不可逆脑损伤。激素来源对血糖主要机制胰岛素胰岛 B 细胞降低促摄取、促合成、抑分解胰高血糖素胰岛 A 细胞升高糖原分解、糖异生肾上腺素肾上腺髓质升高糖原分解、抑胰岛素糖皮质激素肾上腺皮质束状带升高促糖异生、抑外周利用生长激素腺垂体升高抗胰岛素、促脂肪分解甲状腺激素甲状腺升高促糖吸收与糖异生"},{"id":"49.1","t":"雄激素","s":3,"c":"49. 性腺与生殖激素","x":"睾酮由睾丸间质（Leydig）细胞在 LH 刺激下合成（胆固醇 → 孕烯醇酮→ 睾酮），每日约 4~9 mg。作用：（1）胚胎期促进沃尔夫管发育与男性外生殖器形成；（2）青春期促进精子发生、附性器官发育、第二性征（喉结、变声、肌肉发达、体毛）、骨骼生长与骨骺闭合；（3）促进蛋白质合成（同化作用）与红细胞生成（促 EPO）；（4）维持性欲与攻击性行为。部分睾酮在靶组织经 5α-还原酶转为双氢睾酮（DHT，作用更强），或经芳香化酶转为雌二醇。"},{"id":"49.2","t":"雌激素与孕激素","s":3,"c":"49. 性腺与生殖激素","x":"雌激素（雌二醇为主）由卵泡颗粒细胞（经 FSH 刺激，与卵泡膜细胞“双细胞学说”协作）和黄体分泌。作用：（1）促进卵泡发育与子宫内膜增生期变化；（2）促进女性第二性征与乳腺导管发育；（3）促进骨钙沉积（故绝经后易骨质疏松）；（4）降低血胆固醇、保护心血管；（5）对下丘脑-垂体呈双相调节（低浓度负反馈、排卵前高浓度正反馈引起 LH 峰）。孕激素（黄体酮）由黄体与胎盘分泌：使子宫内膜转为分泌期、降低子宫平滑肌兴奋性（保胎）、促进乳腺腺泡发育、使基础体温升高 0.3~0.5 ℃、抑制 GnRH 与 LH 分泌。"},{"id":"49.3","t":"抑制素与松弛素","s":2,"c":"49. 性腺与生殖激素","x":"抑制素（inhibin）由卵泡颗粒细胞与睾丸支持（Sertoli）细胞分泌，选择性抑制腺垂体 FSH 分泌（对 LH 影响小），是调节精子发生与卵泡发育的重要负反馈激素；激活素（activin）作用相反，促进 FSH 分泌。松弛素由黄体与胎盘分泌，松弛骨盆韧带与耻骨联合、软化宫颈，利于分娩。"},{"id":"49.4","t":"下丘脑-垂体-性腺轴","s":3,"c":"49. 性腺与生殖激素","x":"GnRH 以脉冲方式（约每 60~90 分钟一次）释放，经门脉刺激腺垂体分泌FSH 与 LH。FSH：男性作用于支持细胞促进精子发生与抑制素、ABP 生成；女性促进卵泡发育与雌激素合成。LH：男性刺激间质细胞分泌睾酮；女性排卵前引起排卵与黄体形成。性激素负反馈抑制 GnRH 与 FSH/LH（女性在卵泡晚期有正反馈）。持续而非脉冲给予 GnRH 类似物会使受体下调，用于治疗前列腺癌、子宫内膜异位症。"},{"id":"49.5","t":"胎盘激素","s":3,"c":"49. 性腺与生殖激素","x":"胎盘是妊娠期重要的内分泌器官，分泌：（1）人绒毛膜促性腺激素（hCG，由滋养层细胞分泌，作用类似 LH，维持黄体、妊娠早期可测出，是早孕诊断指标）；（2）人胎盘催乳素（hPL，促进乳腺发育与母体代谢适应）；（3）雌激素与孕激素（妊娠 8~10 周后取代黄体成为主要来源）；（4）促肾上腺皮质激素释放激素、抑制素等。胎盘激素由胎儿-胎盘单位共同合成（胎儿肾上腺提供前体）。"},{"id":"49.6","t":"性激素的合成与临床应用","s":2,"c":"49. 性腺与生殖激素","x":"性激素合成途径：胆固醇 →（P450scc）孕烯醇酮 → 孕酮、17α-羟孕酮→ 雄烯二酮 → 睾酮 →（芳香化酶）雌二醇；卵巢以“卵泡膜细胞合成雄激素、颗粒细胞芳香化为雌激素”的双细胞方式完成，胎盘因缺乏 17α-羟化酶需胎儿肾上腺提供前体（胎儿-胎盘单位）。临床应用：（1）复方口服避孕药含雌激素与孕激素，通过负反馈抑制 FSH/LH、改变宫颈黏液与子宫内膜而避孕；（2）激素替代治疗用于绝经综合征与骨质疏松，但有血栓与乳腺风险；（3）芳香化酶抑制剂（来曲唑）用于乳腺癌与促排卵；（4）抗雄激素（氟他胺）与 GnRH 类似物用于前列腺癌；（5）睾酮制剂用于男性性腺功能减退，但可抑制精子发生。"},{"id":"50.1","t":"应激的概念与分期","s":3,"c":"50. 应激与应激激素","x":"应激（stress）指机体受到各种内外环境因素（创伤、感染、寒冷、缺氧、饥饿、精神紧张、剧烈运动）刺激时产生的非特异性全身反应。Selye 提出“一般适应综合征”分三期：（1）警觉期（alarm，交感-肾上腺髓质系统立即激活，糖皮质激素开始升高）；（2）抵抗期（resistance，HPA 轴持续激活、皮质醇维持高水平，抗炎抗休克能力增强但易感染）；（3）衰竭期（exhaustion，适应能力耗竭，出现应激性溃疡、免疫抑制、多器官功能衰竭）。"},{"id":"50.2","t":"应激时的主要激素变化","s":3,"c":"50. 应激与应激激素","x":"（1）CRH-ACTH-皮质醇系统激活（最重要，皮质醇可升高数倍至数十倍），维持血糖、血压与循环对儿茶酚胺的反应性；（2）交感-肾上腺髓质系统激活，儿茶酚胺升高，心率加快、血压升高、血液重新分配（保证心脑供血）；（3）GH、PRL、ADH、β-内啡肽、胰高血糖素升高；（4）胰岛素、性激素、甲状腺激素（T3）降低（“节省能量”）；（5）肾素-血管紧张素-醛固酮系统激活，保钠保水。"},{"id":"50.3","t":"应激的生理意义与危害","s":2,"c":"50. 应激与应激激素","x":"意义：动员能量（血糖升高、脂肪分解）、维持循环（升高血压、增加心输出量）、抑制炎症（防止过度的炎症损伤）、提高中枢兴奋性，是适应与防御反应。危害：长期慢性应激导致免疫功能抑制（易感染、肿瘤易发）、应激性溃疡（胃黏膜缺血 + 糖皮质激素抑制前列腺素）、心血管疾病（高血压、心律失常）、代谢紊乱（向心性肥胖、胰岛素抵抗）、精神障碍（抑郁、焦虑）与生长发育迟缓。"},{"id":"50.4","t":"应激与免疫、炎症的相互作用","s":2,"c":"50. 应激与应激激素","x":"急性应激增强免疫（儿茶酚胺使免疫细胞从边缘池动员入血、皮肤与淋巴结），慢性应激抑制免疫（糖皮质激素抑制淋巴细胞增殖与细胞因子产生、诱导淋巴细胞凋亡）。炎症时细胞因子（IL-1、IL-6、TNF-α）通过血脑屏障或经迷走神经传入中枢，激活 HPA 轴（“免疫-内分泌轴”），形成负反馈抑制炎症；这一机制受损（如糖皮质激素抵抗）时可致炎症失控。"},{"id":"50.5","t":"应激时的代谢与食欲改变","s":2,"c":"50. 应激与应激激素","x":"应激时能量动员优先保证心、脑、骨骼肌：皮质醇促进肝糖异生、抑制外周葡萄糖利用，儿茶酚胺促进糖原分解与脂肪分解，GH 与胰高血糖素协同，结果出现应激性高血糖（“应激性糖尿”）；蛋白质分解加速（负氮平衡、肌肉消耗、伤口愈合延迟）。食欲调节：CRH 与瘦素抑制食欲，皮质醇与神经肽Y 促进食欲与腹部脂肪沉积，故慢性应激常致向心性肥胖与胰岛素抵抗（代谢综合征）。急性严重应激还可抑制胃酸分泌与胃肠运动（“应激性溃疡”的机制之一）。"},{"id":"50.6","t":"应激的动物生产与生态意义","s":2,"c":"50. 应激与应激激素","x":"生产动物常面临运输、混群、高温、拥挤、断奶等应激，导致采食量下降、增重减慢、肉质下降（PSE 肉、DFD 肉）、免疫力降低与繁殖障碍（母猪乏情、奶牛产奶量下降）。热应激时动物增加呼吸频率、减少采食、增加饮水，可通过喷淋、通风、调整饲喂时间缓解。生态上，捕食风险、食物短缺、气候极端均引起糖皮质激素升高，长期高皮质醇抑制生长与繁殖、缩短寿命；因此粪便或毛发中的皮质醇代谢物被用作野生动物与家畜应激水平的无创指标，是动物福利评价的重要内容。"},{"id":"51.1","t":"负反馈调节","s":3,"c":"51. 激素分泌的调节","x":"（1）长反馈：靶腺激素（T3/T4、皮质醇、性激素）反馈抑制下丘脑与腺垂体；（2）短反馈：腺垂体激素（TSH、ACTH）反馈抑制下丘脑释放激素；（3）超短反馈：下丘脑激素反馈抑制自身神经元。负反馈是维持激素水平稳态的核心，故临床测“激素 + 促激素”组合可定位病变部位：如 T3/T4 升高而TSH 降低提示原发性甲亢（靶腺病变），T3/T4 降低而 TSH 升高提示原发性甲减，两者均低提示垂体或下丘脑病变。"},{"id":"51.2","t":"正反馈调节","s":2,"c":"51. 激素分泌的调节","x":"正反馈使激素分泌进一步增强，数量少但作用关键：（1）排卵前雌激素高峰对 GnRH 与 LH 的正反馈，引起 LH 峰与排卵；（2）分娩时子宫收缩刺激催产素释放，催产素又增强子宫收缩（直至分娩结束）；（3）吸吮刺激引起催乳素与催产素释放（射乳反射）；（4）血液凝固与动作电位的再生性去极化也是正反馈。"},{"id":"51.3","t":"神经调节与血浆物质调节","s":2,"c":"51. 激素分泌的调节","x":"（1）神经调节：交感神经调节肾上腺髓质（节前纤维）、胰岛（α 与 β 细胞）、肾素释放、松果体褪黑素（受视交叉上核与颈上神经节调控，光照抑制、黑暗促进）；（2）血浆物质直接调节：血糖-胰岛素/胰高血糖素、血钙PTH/降钙素、渗透压-ADH、血 K⁺-醛固酮、血 Na⁺、脂肪酸、氨基酸。"},{"id":"51.4","t":"激素的允许作用、协同与拮抗","s":3,"c":"51. 激素分泌的调节","x":"（1）允许作用：某激素的存在使另一激素的效应得以实现，如糖皮质激素对儿茶酚胺的缩血管作用、甲状腺激素对儿茶酚胺的产热作用、胰岛素对 GH促生长作用；（2）协同：胰高血糖素与肾上腺素共同升糖、GH 与胰岛素共同促蛋白合成、PTH 与维生素 D 共同升血钙；（3）拮抗：胰岛素与胰高血糖素、PTH 与降钙素、雌激素与孕激素在子宫兴奋性上的相反作用。"},{"id":"51.5","t":"激素的节律、代谢与检测","s":2,"c":"51. 激素分泌的调节","x":"激素分泌具节律性：皮质醇（晨高夜低）、GH（深睡峰）、褪黑素（夜间高）、GnRH/LH（脉冲，女性有周期）、胰岛素（餐后峰）、PTH（夜间略高）。激素在肝、肾灭活，部分经尿排出（故尿中激素代谢物可作检测指标）。临床检测应注意采血时间、体位、是否空腹；激素的半衰期差异极大（肾上腺素数分钟、甲状腺激素数天），这决定其作用的时间特点。"},{"id":"51.6","t":"受体的调节与激素抵抗","s":2,"c":"51. 激素分泌的调节","x":"激素的效应取决于血中浓度与靶细胞受体数目/亲和力。受体上调：激素水平长期降低时受体数目增加（如去神经后效应器对递质敏感性升高）；受体下调：激素长期升高时受体数目减少或磷酸化脱敏（如持续高胰岛素血症使胰岛素受体下调，是 2 型糖尿病的机制之一；持续给予 GnRH 类似物使垂体GnRH 受体下调，用于治疗前列腺癌）。激素抵抗指激素水平正常或升高而效应减弱，常见原因：受体基因突变（如雄激素不敏感综合征、家族性高胆固醇血症的 LDL 受体缺陷）、受体抗体（如 TSH 受体抗体可激动引起甲亢、也可阻断引起甲减）、受体后信号缺陷（胰岛素抵抗的 PI3K-Akt 通路障碍）、抗激素抗体。第七篇 神经系统的整合功能"},{"id":"52.1","t":"神经元的结构与分类","s":3,"c":"52. 神经元与神经胶质细胞","x":"神经元由胞体（含核、尼氏体、线粒体）、树突（接受信息，增大表面积）和轴突（传导冲动，长度可达 1 m，轴突内有轴浆运输：顺向快运输约400 mm/日、慢运输 1~5 mm/日，逆向运输由动力蛋白执行）组成。按功能分感觉（传入）神经元、运动（传出）神经元、中间（联络）神经元；按突起数目分假单极、双极、多极神经元；按轴突有无髓鞘分有髓与无髓纤维；按递质分胆碱能、肾上腺素能、肽能等。"},{"id":"52.2","t":"神经纤维的轴浆运输与营养作用","s":2,"c":"52. 神经元与神经胶质细胞","x":"轴浆运输：顺向（胞体→末梢，kinesin 驱动，供递质与膜结构）与逆向（末梢→胞体，dynein 驱动，运送神经营养因子与病毒，如狂犬病毒、破伤风毒素沿此途径上行）；快速运输依赖微管与 ATP，慢速运输输送细胞骨架成分。此外神经末梢可释放神经营养因子（NGF、BDNF），对效应组织有营养作用，故神经损伤后肌肉萎缩。"},{"id":"52.3","t":"神经胶质细胞","s":3,"c":"52. 神经元与神经胶质细胞","x":"中枢神经胶质细胞数量为神经元的 10~50 倍：（1）星形胶质细胞：构成血脑屏障（诱导内皮紧密连接）、参与 K⁺ 与谷氨酸的缓冲（“钾空间缓冲”）、提供代谢底物、修复瘢痕；（2）少突胶质细胞：形成中枢髓鞘；（3）小胶质细胞：免疫吞噬（中枢的巨噬细胞）；（4）室管膜细胞：衬覆脑室、产生脑脊液。周围神经的髓鞘由施万细胞形成。胶质细胞不产生动作电位，但可经缝隙连接与 Ca²⁺ 波进行信息交流。"},{"id":"52.4","t":"血脑屏障与脑脊液","s":2,"c":"52. 神经元与神经胶质细胞","x":"血脑屏障由毛细血管内皮（紧密连接）、基膜与星形胶质细胞足突构成，限制大分子与极性物质通过，允许 O₂、CO₂、葡萄糖、脂溶性物质与部分氨基酸通过（特定转运体介导）。意义：维持脑内环境稳定、保护免受毒素与病原侵害，但也阻碍药物（如多巴胺、多数抗生素）进入。脑脊液由脉络丛分泌（每日约 500 mL，总量约 150 mL，每 6~8 小时更新一次），缓冲保护、提供营养、运走代谢产物。"},{"id":"52.5","t":"中枢神经元的联系方式","s":2,"c":"52. 神经元与神经胶质细胞","x":"（1）辐散：一个神经元轴突通过分支与多个神经元联系（扩大影响范围）；（2）聚合：多个神经元轴突与同一个神经元联系（总和）；（3）环状（回返）：形成正反馈或负反馈环路（如 Renshaw 抑制环路）；（4）链锁状：逐级传递（如感觉通路）；（5）局部环路：中间神经元构成的微环路（前馈抑制、侧抑制）。这些联系方式是中枢整合的结构基础。"},{"id":"52.6","t":"反射与反射弧","s":3,"c":"52. 神经元与神经胶质细胞","x":"反射是神经系统活动的基本方式。反射弧五环节：感受器 → 传入神经 →神经中枢 → 传出神经 → 效应器。反射分非条件反射（先天、固定、皮层下中枢完成，如膝跳反射、吸吮反射）与条件反射（后天、需大脑皮质、可消退，如“望梅止渴”）。反射协调的机制包括交互抑制、最后公路原则、优势现象、扩散与集中、反馈调节。"},{"id":"53.1","t":"突触可塑性的类型","s":3,"c":"53. 突触可塑性与递质共存","x":"突触可塑性指突触传递效能随活动而改变：（1）短时程（数秒至数分钟）：突触易化、强直后增强（PTP，与 Ca²⁺ 蓄积促进递质释放有关）、短时程抑制；（2）长时程：长时程增强（LTP）与长时程抑制（LTD），是学习记忆的细胞基础。LTP 主要在海马 CA1 区研究，表现为高频刺激后 EPSP 持久增强（数小时至数天）。"},{"id":"53.2","t":"LTP 的机制","s":3,"c":"53. 突触可塑性与递质共存","x":"海马 CA1 区 LTP 需要谷氨酸作用于 AMPA 与 NMDA 受体：静息时NMDA 通道被 Mg²⁺ 阻塞；高频刺激使 AMPA 通道大量去极化，解除 Mg²⁺阻塞，Ca²⁺ 经 NMDA 通道内流，激活 CaMKII、PKC、酪氨酸激酶，导致（1）AMPA 受体磷酸化与数量增加（早期相）；（2）CREB 激活、基因转录与新蛋白合成（晚期相，突触结构改变、树突棘增大）。NMDA 受体是“coincidence detector”，同时检测突触前（谷氨酸）与突触后（去极化）活动。"},{"id":"53.3","t":"LTD 与突触修剪","s":2,"c":"53. 突触可塑性与递质共存","x":"低频刺激引起突触后 Ca²⁺ 小幅升高，激活磷酸酶（钙调磷酸酶），使AMPA 受体去磷酸化并内吞，产生长时程抑制（LTD），是“用进废退”与记忆清除的机制。发育期突触大量形成后又经经验依赖性修剪（“ prune”），保留活跃突触，形成高效的神经环路，此过程受感觉经验影响（如视觉剥夺导致眼优势柱改变）。"},{"id":"53.4","t":"神经递质共存","s":2,"c":"53. 突触可塑性与递质共存","x":"同一神经元可合成并释放两种或以上递质（经典递质 + 神经肽），共存递质可协同作用（如 ACh 与 VIP 在副交感神经元、NE 与 NPY 在交感神经元、谷氨酸与 P 物质）。意义：（1）一种递质作用于快通道产生快速效应，另一种经第二信使产生缓慢持久效应；（2）不同刺激频率下释放比例不同，实现“频率编码”；（3）突触前受体可差异调节释放。"},{"id":"53.5","t":"神经调质与容积传递","s":2,"c":"53. 突触可塑性与递质共存","x":"神经调质本身不一定直接引起电位变化，但调节突触传递效率（如多巴胺、5-HT、ACh 的某些作用、神经肽）。容积传递指递质经组织液扩散作用于较远靶点（如 NO、神经肽、单胺），作用范围广、时间慢，与“点对点”的经典突触传递互补，参与睡眠、觉醒、情绪与摄食的整体调节。"},{"id":"53.6","t":"突触可塑性与神经疾病、成瘾","s":2,"c":"53. 突触可塑性与递质共存","x":"（1）药物成瘾：反复给药使伏隔核多巴胺系统发生突触重塑（AMPA 受体数目增加、树突棘改变、ΔFosB 转录因子蓄积），产生耐受、依赖与复吸（“记忆性”渴求）；（2）慢性疼痛：脊髓后角 C 纤维末梢反复激活引起“中枢敏化”（NMDA 受体磷酸化、突触前递质释放增加），是痛觉过敏的机制；（3）阿尔茨海默病：β-淀粉样蛋白寡聚体抑制 LTP、促进 LTD 与突触清除，早期即出现突触丢失；（4）抑郁症：慢性应激使海马 BDNF 与神经营养下降、树突萎缩，抗抑郁药（SSRI）促进 BDNF 与海马神经发生，起效需2~4 周与突触重塑时间一致；（5）癫痫：兴奋性突触增强与抑制性突触减弱导致异常同步放电。"},{"id":"54.1","t":"感受器与感觉器官","s":3,"c":"54. 感觉系统的一般规律","x":"感受器是能将各种刺激能量转换为神经电信号（感受器电位）的结构。按刺激类型分：机械感受器（触、压、牵张、听觉毛细胞）、温度感受器、化学感受器、光感受器、痛感受器（伤害性感受器，游离神经末梢）。感觉器官 =感受器 + 附属结构（如眼的折光系统、耳的传音系统）。感受器的换能过程依赖离子通道开放（机械门控、化学门控）产生的去极化感受器电位。"},{"id":"54.2","t":"感受器的一般生理特性","s":3,"c":"54. 感觉系统的一般规律","x":"（1）适宜刺激：每种感受器对特定形式的能量最敏感（眼的适宜刺激是380~760 nm 光波）；（2）换能作用：将刺激能量转为感受器电位（等级性、可总和）；（3）编码作用：刺激的性质由专用传入通路与感受器种类决定，强度由动作电位的频率与参与纤维数目编码；（4）适应现象：持续刺激时传入冲动减少（快适应/位相型感受器如触觉小体，慢适应/紧张型如肌梭、痛感受器）；（5）对比与侧抑制：增强空间分辨。"},{"id":"54.3","t":"感觉通路的一般结构","s":3,"c":"54. 感觉系统的一般规律","x":"感觉传入通路一般为三级神经元接替：（1）第一级感觉神经元（背根神经节或脑神经节）；（2）第二级神经元（脊髓后角或脑干核团，交叉到对侧）；（3）第三级神经元（丘脑，主要是腹后核）→ 大脑皮质感觉区。感觉投射系统分：（1）特异性投射系统（点对点，至皮层特定区域，引起清晰感觉）；（2）非特异性投射系统（经脑干网状结构弥散投射至皮层，维持觉醒，损伤则昏睡）。"},{"id":"54.4","t":"感受器的适应与阈值","s":2,"c":"54. 感觉系统的一般规律","x":"快适应感受器（触觉、嗅觉）在刺激持续时迅速减少放电，利于检测变化（“变化检测器”）；慢适应感受器（痛、肌梭、颈动脉窦压力感受器）持续放电，利于监测持续状态。感觉阈值分绝对阈值（刚能引起感觉的最小刺激）与差别阈值（能分辨的最小差异，Weber 定律：ΔI/I 为常数）。感觉强度与刺激强度的关系近似幂函数（Stevens 定律）。"},{"id":"54.5","t":"感觉的编码与中枢整合","s":2,"c":"54. 感觉系统的一般规律","x":"刺激的性质靠“标记线”（专用通路与皮层代表区）编码；强度靠动作电位频率与募集纤维数目；部位靠感受野与拓扑投射（皮层“地图”）；时间靠放电的时相。中枢对感觉信息有聚合、对比（侧抑制增强边界）、特征提取（皮层细胞的方位、运动方向选择性）与“忽略”（持续无关刺激）等整合，最终形成主观感觉。"},{"id":"54.6","t":"感觉、知觉与感觉的整合","s":2,"c":"54. 感觉系统的一般规律","x":"感觉是对刺激属性的初步分辨（性质、强度、部位），知觉是大脑对感觉信息进行组织与解释后形成的整体认识（需要学习与经验）。整合机制包括：（1）特征提取：皮层神经元对特定方位、运动方向、频率有选择性地反应；（2）侧抑制与对比增强（马赫带现象）；（3）多感觉整合（视觉与前庭、听觉与视觉在顶叶与上丘整合，如“腹语效应”、McGurk 效应）；（4）经验依赖性重塑（长期训练改变皮层代表区，如盲人触觉与听觉代表区扩大、弦乐手的左手代表区增大）。幻觉与幻肢痛说明感觉体验不完全依赖外周输入，而依赖于中枢的预测与重建。"},{"id":"55.1","t":"眼的结构与折光系统","s":3,"c":"55. 视觉","x":"眼由眼球壁（纤维膜：角膜、巩膜；血管膜：虹膜、睫状体、脉络膜；视网膜）、内容物（房水、晶状体、玻璃体）和附属结构（眼睑、泪器、眼外肌）构成。折光系统包括角膜（提供约 2/3 的折光力，约 43 D）、房水、晶状体（可调节，约 19 D）与玻璃体，总折光力约 59 D。正常眼在安静状态下 6 m 以外物体成像于视网膜（物像缩小、倒立、左右反置）。"},{"id":"55.2","t":"眼的调节","s":3,"c":"55. 视觉","x":"视近物时的调节：（1）晶状体变凸（睫状肌收缩、悬韧带松弛，晶状体靠弹性变凸，折光力增加）；（2）瞳孔缩小（减少球面像差与色像差、增加景深）；（3）双眼会聚（内直肌收缩，使物像落于两眼视网膜对应点）。近点（能看清的最近距离）随年龄增长而远移（10 岁约 8.3 cm，60 岁约 83 cm），因晶状体弹性下降（老视/老花）。近视因眼轴过长或折光力过强，需凹透镜矫正；远视因眼轴过短，需凸透镜；散光因角膜曲度不均，用柱面镜矫正。"},{"id":"55.3","t":"视网膜的结构与感光细胞","s":3,"c":"55. 视觉","x":"视网膜由外向内：色素上皮层、感光细胞层（视杆与视锥）、双极细胞层、神经节细胞层，光线需先穿过神经节细胞与双极细胞才到感光细胞（“倒置”视网膜）。视杆细胞约 1.2 亿个，含视紫红质，对弱光敏感（暗视觉，无色觉），主要分布于视网膜周边；视锥细胞约 600 万个，含三种视蛋白，司明视觉与色觉，集中于中央凹（中央凹只有视锥细胞，视觉最敏锐）。视神经乳头（视盘）无感光细胞，形成生理盲点。"},{"id":"55.4","t":"光化学反应与感受器电位","s":3,"c":"55. 视觉","x":"视杆细胞外段含视紫红质（11-顺视黄醛 + 视蛋白）。光照使 11-顺视黄醛异构为全反视黄醛，激活视蛋白 → 激活转导蛋白（Gt）→ 激活磷酸二酯酶（PDE）→ 分解 cGMP → cGMP 门控 Na⁺ 通道关闭 → 细胞超极化（感受器电位为超极化，与一般感受器相反）→ 谷氨酸释放减少 → 双极细胞与神经节细胞去极化 → 产生动作电位。暗处 cGMP 高、Na⁺ 通道开放（“暗电流”），持续释放谷氨酸。维生素 A 缺乏影响视黄醛再生，导致夜盲症。"},{"id":"55.5","t":"色觉学说","s":3,"c":"55. 视觉","x":"三原色学说：视网膜有三种视锥细胞，分别对 420 nm（蓝）、531 nm（绿）、558 nm（红）最敏感，不同比例兴奋产生各种色觉。色盲与色弱：红绿色盲为 X 连锁隐性遗传（红、绿视蛋白基因位于 X 染色体），男性发病率约5%~8%，女性约 0.5%；全色盲罕见（视锥细胞缺失）。拮抗色学说（Hering）解释负后像与对比现象（红-绿、黄-蓝拮抗），现代认为两者在视网膜与中枢不同水平均成立。"},{"id":"55.6","t":"视敏度、视野与暗适应","s":2,"c":"55. 视觉","x":"视敏度（视力）以能分辨的最小视角表示，正常为 1 分角（1.0）；中央凹最高，周边迅速下降。视野：白色视野最大，颞侧 > 鼻侧、下 > 上，蓝色 > 红色 > 绿色（颜色视野较小）。暗适应：从明处入暗处，感受性逐渐升高的过程（约 30~40 分钟完成，早期视锥细胞、后期视杆细胞参与）；明适应则迅速（数分钟）。视杆细胞的光敏感度高于视锥细胞约 1 000 倍。"},{"id":"55.7","t":"眼的折光异常与瞳孔反射","s":2,"c":"55. 视觉","x":"折光异常：近视（凹透镜）、远视（凸透镜）、散光（柱面镜）、老视（近点远移，看近需凸透镜）。瞳孔对光反射：强光照射一侧眼引起双侧瞳孔缩小（患侧为直接反射、对侧为间接反射），中枢在中脑，通路为视网膜 → 视神经 → 顶盖前区 → 双侧动眼神经副核（E-W 核）→ 睫状神经节 → 瞳孔括约肌。瞳孔近反射：看近物时瞳孔缩小。瞳孔对光反射消失提示中脑损伤或脑死亡评估。"},{"id":"56.1","t":"耳的传音装置","s":3,"c":"56. 听觉与平衡","x":"外耳（耳廓、外耳道，共振频率约 2 000~3 000 Hz）收集声波；中耳（鼓膜、听小骨链：锤骨-砧骨-镫骨、咽鼓管）将声波传入内耳，听小骨链的杠杆作用与鼓膜/卵圆窗面积比（约 17~20∶1）使声压放大约 22 倍（约 25~27 dB），实现阻抗匹配（空气→液体）。咽鼓管平衡中耳与外界气压（吞咽、打呵欠时开放），阻塞时引起鼓膜内外压差、听力下降。声波还可经颅骨传导（骨传导），但正常以气传导为主。"},{"id":"56.2","t":"耳蜗的结构与行波理论","s":3,"c":"56. 听觉与平衡","x":"耳蜗由前庭阶、蜗管、鼓阶三个腔构成，蜗管内的基底膜上有螺旋器（Corti 器），含内、外毛细胞（约 1.6 万个）与支持细胞，毛细胞顶部纤毛与盖膜接触。行波理论（Békésy）：声波经卵圆窗使基底膜产生行波，从蜗底向蜗顶传播，不同频率的声波在基底膜不同部位出现最大振幅——高频在蜗底（靠近卵圆窗、基底膜窄而硬）、低频在蜗顶（宽而软），形成频率-部位编码（位置原则）。耳蜗毛细胞经机械门控（纤毛束偏转牵拉 tip link 打开 K⁺ 通道，内淋巴高 K⁺ 流入使毛细胞去极化）换能，释放谷氨酸兴奋螺旋神经节。"},{"id":"56.3","t":"听觉的强度与频率编码","s":2,"c":"56. 听觉与平衡","x":"频率编码：低频（<400 Hz）靠听神经纤维放电与声波同步（频率原则），高频靠基底膜部位（位置原则），中频两者兼有。强度编码：声强增大使基底膜振动幅度增大、兴奋的毛细胞与神经纤维数目增多、单纤维放电频率增高。人耳听阈频率 20~20 000 Hz，最敏感 1 000~3 000 Hz；听阈声压约0.000 2 dyn/cm²（0 dB SPL），痛阈约 120 dB SPL。"},{"id":"56.4","t":"耳蜗的传出控制与耳声发射","s":1,"c":"56. 听觉与平衡","x":"耳蜗受橄榄耳蜗束（内侧为外侧毛细胞、外侧为内毛细胞）的胆碱能抑制性控制，可降低噪声环境中的背景响应、提高信号/噪声比。外毛细胞有电致运动（electromotility）能力，可主动放大基底膜振动，产生耳声发射（otoacoustic emission），临床用于新生儿听力筛查。耳毒性药物（氨基糖苷类抗生素、顺铂、利尿剂）损伤毛细胞导致感音神经性耳聋。"},{"id":"56.5","t":"前庭器官与平衡","s":3,"c":"56. 听觉与平衡","x":"前庭器官包括三个半规管（感受角加速度）、椭圆囊与球囊（感受直线加速度与头部位置）。半规管壶腹内的毛细胞纤毛插入壶腹帽，内淋巴流动使壶腹帽偏转；椭圆囊与球囊的耳石膜（含碳酸钙结晶）在重力与直线加速度作用下位移，牵拉毛细胞纤毛。传入经前庭神经（第 VIII 对脑神经）至前庭核，再至小脑、眼外肌核（前庭眼反射，稳定视网膜像）与脊髓（前庭脊髓反射，维持姿势）。"},{"id":"56.6","t":"前庭反应与晕动病","s":2,"c":"56. 听觉与平衡","x":"前庭反应包括：（1）前庭姿势反射（调节肌紧张维持平衡）；（2）前庭眼反射（旋转时眼球震颤，慢相为前庭驱动、快相为中枢矫正，用于判断前庭功能）；（3）前庭自主神经反应（恶心、呕吐、出汗、面色苍白、心率改变），即晕动病（晕车、晕船、晕机），因视觉与前庭信息冲突所致。旋转试验与冷热水试验用于检查前庭功能；耳石脱落可引起良性阵发性位置性眩晕（BPPV）。"},{"id":"57.1","t":"嗅觉","s":3,"c":"57. 化学感觉","x":"嗅上皮位于鼻腔上鼻道与鼻中隔上部（面积约 5 cm²），含约 1 000 万~2 000 万个嗅细胞（双极神经元，其轴突直接入嗅球，是唯一不换元直接入中枢的感觉神经元）。嗅物质（挥发性、脂溶性小分子）与嗅细胞纤毛上的受体结合 → G 蛋白（Golf）→ 腺苷酸环化酶 → cAMP → 打开环核苷酸门控阳离子通道 → Na⁺、Ca²⁺ 内流 → 去极化（感受器电位）→ 动作电位。嗅觉适应快（约50% 在数秒内），且对一种气味适应后对其他气味敏感度不变。"},{"id":"57.2","t":"嗅觉通路与信息处理","s":2,"c":"57. 化学感觉","x":"嗅细胞轴突经筛板入嗅球，与僧帽细胞（mitral cell）形成突触（嗅小球），经嗅束投射至梨状皮质、杏仁核、内嗅皮质，不经丘脑直接到皮质（是唯一不经过丘脑的感觉通路），故气味易唤起情绪与记忆。嗅觉与味觉共同构成“风味”；嗅觉对觅食、避险、性行为（信息素，经犁鼻器-副嗅球）有重要作用。嗅觉障碍见于鼻炎、颅脑外伤（筛板骨折）、帕金森病早期。"},{"id":"57.3","t":"味觉","s":3,"c":"57. 化学感觉","x":"味蕾分布于舌（轮廓乳头、菌状乳头）、软腭、咽部，每个味蕾含 50~100个味细胞。五种基本味觉：甜（糖类，能量标志）、咸（Na⁺，电解质）、酸（H⁺）、苦（生物碱，警示毒物）、鲜（谷氨酸，蛋白质）。舌的不同部位对味觉敏感度有差异（并非严格的“味觉地图”）。传导：面神经（鼓索，舌前2/3）、舌咽神经（舌后 1/3）、迷走神经（咽部）→ 孤束核 → 丘脑 → 岛叶皮质。味觉适应快；味觉阈值受温度、年龄（老年减退）、锌缺乏影响。"},{"id":"57.4","t":"其他化学感觉","s":1,"c":"57. 化学感觉","x":"（1）三叉神经化学感受（薄荷的凉、辣椒的辣，经 TRPM8 与 TRPV1 通道）；（2）犁鼻器（vomeronasal organ）感受信息素，见于多数哺乳动物与爬行类，人类退化；（3）鱼类的味觉分布广泛（皮肤、触须、鳍），用于觅食；（4）昆虫的味觉感受器分布于口器、足、触角，蜜蜂可辨别甜度与花蜜质量。"},{"id":"57.5","t":"化学感觉的种属差异","s":2,"c":"57. 化学感觉","x":"（1）嗅觉：犬的嗅上皮面积约 150 cm²（人约 5 cm²）、嗅细胞约 2 亿个，嗅觉阈值比人低 10⁴~10⁶ 倍；鲨鱼可感知 10⁻¹⁰ mol/L 的血液成分；昆虫的嗅觉感受器位于触角，信息素（性外激素）可被雄蛾在数千米外感知（家蚕醇）。（2）味觉：猫缺乏甜味受体基因（Tas1r2 假基因）而对甜味不敏感，但也不能感受鲜味的部分成分；牛、羊味蕾数量多于人；蝇类味觉感受器分布于足，落在食物上即以足“尝味”；（3）鱼类味蕾分布于唇、触须、鳃与体表，形成“体表味觉”，帮助觅食。"},{"id":"57.6","t":"化学感觉与摄食、繁殖行为","s":2,"c":"57. 化学感觉","x":"（1）味觉厌恶学习（Garcia 效应）：一次致病的食物味道即可形成长期厌恶，具“准备性”（对味道与气味特别易学），是动物避毒的重要机制；（2）嗅觉与信息素：多数哺乳类经犁鼻器与副嗅球感知信息素，参与性识别、动情同步（Whitten 效应）、妊娠阻断（Bruce 效应）与母性行为；（3）择食调节：血糖降低、蛋白质缺乏（大鼠对缺乏必需氨基酸的饲料有选择性回避）、钠缺乏（肾上腺切除动物出现特异性嗜盐）说明营养状态可改变味觉敏感性；（4）嗅觉障碍可作为帕金森病与阿尔茨海默病的早期征象。"},{"id":"58.1","t":"躯体感觉的分类","s":3,"c":"58. 躯体感觉通路","x":"（1）浅感觉：触-压觉、温度觉、痛觉（皮肤与黏膜）；（2）深感觉：本体感觉（位置觉、运动觉、振动觉）与深部压觉，来自肌肉、关节、肌腱（肌梭、腱器官）；（3）内脏感觉：经交感与副交感传入，定位模糊，可引起牵涉痛。痛觉按来源分躯体痛（皮肤、肌肉、关节）与内脏痛，按性质分快痛（锐痛，Aδ 纤维，定位明确）与慢痛（灼痛，C 纤维，定位模糊、伴情绪反应）。"},{"id":"58.2","t":"浅感觉传导通路","s":3,"c":"58. 躯体感觉通路","x":"（1）精细触觉与本体感觉（后索-内侧丘系）：第一级神经元在背根神经节 → 经后索（薄束、楔束）上行 → 延髓薄束核、楔束核换元 → 交叉（内侧丘系交叉）→ 内侧丘系 → 丘脑腹后外侧核 → 中央后回；（2）痛温觉与粗触觉（脊髓丘脑侧束）：第一级神经元背根神经节 → 后角换元 → 经脊髓前连合交叉到对侧 → 脊髓丘脑侧束（痛温觉）与前束（粗触觉）→ 丘脑 → 中央后回。故脊髓半横断（Brown-Séquard 综合征）时，伤侧本体感觉与精细触觉丧失、对侧痛温觉丧失。"},{"id":"58.3","t":"丘脑与感觉投射系统","s":3,"c":"58. 躯体感觉通路","x":"丘脑是除嗅觉外所有感觉传入的重要接替站。核团分三类：（1）感觉接替核（腹后外侧核、腹后内侧核、外侧膝状体、内侧膝状体）→ 特异性投射至皮层特定区；（2）联络核（丘脑前核、腹外侧核、枕核）参与感觉与运动的整合；（3）非特异性核（髓板内核群）→ 经脑干网状结构弥散投射至皮层，维持觉醒状态。特异性投射引起特定感觉、激发皮层发放冲动；非特异性投射维持皮层兴奋性，二者相互配合。"},{"id":"58.4","t":"大脑皮质感觉代表区","s":3,"c":"58. 躯体感觉通路","x":"第一体感区（SⅠ）位于中央后回（3、1、2 区），其投射规律：（1）交叉投射（一侧皮层接受对侧躯体感觉，头面部为双侧）；（2）倒置分布（下肢在顶部、头面在底部，但头面部本身为正立）；（3）面积与感觉精细程度成正比（手、唇、舌的代表区很大，躯干小）。第二体感区（SⅡ）位于中央后回下方与岛叶，双侧投射、定位模糊，与痛觉的情绪成分有关。内脏感觉代表区在SⅡ 与边缘系统。"},{"id":"58.5","t":"痛觉与镇痛机制","s":3,"c":"58. 躯体感觉通路","x":"痛觉感受器为游离神经末梢（伤害性感受器），致痛物质包括 K⁺、H⁺、组胺、缓激肽、5-HT、前列腺素、P 物质、ATP（组织损伤、炎症、缺血时释放）。痛觉传入脊髓后角（Rexed Ⅱ、Ⅴ 层）经脊髓丘脑束上行。内源性镇痛系统：中脑中央灰质 → 中缝大核（5-HT）→ 脊髓后角，以及内啡肽、脑啡肽、强啡肽作用于阿片受体，抑制痛觉传入。闸门控制学说：粗纤维（Aβ）兴奋可抑制细纤维（Aδ、C）传递的痛信号（故按摩、电刺激可镇痛）。阿司匹林抑制前列腺素合成而镇痛；吗啡激动阿片受体。"},{"id":"58.6","t":"牵涉痛与内脏痛","s":2,"c":"58. 躯体感觉通路","x":"内脏痛特点：定位不明确、性质为钝痛或绞痛、对牵拉、缺血、炎症敏感而对切割烧灼不敏感、常伴自主神经反应（恶心、出汗、血压变化）与情绪反应。牵涉痛：内脏病变引起体表特定部位疼痛（心绞痛放射至左肩左臂尺侧、胆囊炎至右肩、阑尾炎初期至脐周、肾结石至腹股沟），机制为内脏与体表传入纤维在脊髓后角同一神经元会聚（convergence），大脑误判来源。会聚学说与易化学说是其主要解释。"},{"id":"59.1","t":"脊髓的功能与脊休克","s":3,"c":"59. 脊髓反射","x":"脊髓是躯体与内脏反射的低级中枢（牵张反射、屈肌反射、排尿排便反射、血管张力反射），也是感觉与运动的传导通路。脊休克：脊髓与高位中枢突然离断后，断面以下的脊髓反射暂时消失（数分钟至数周，人类数周至数月），表现为骨骼肌弛缓性瘫痪、感觉与反射消失、血压下降、排尿排便失禁。机制是失去高位中枢的易化性影响（而非损伤本身），恢复后反射亢进（释放现象）。动物越低级恢复越快（蛙数分钟）。"},{"id":"59.2","t":"肌梭与腱器官","s":3,"c":"59. 脊髓反射","x":"肌梭：位于骨骼肌内、与肌纤维平行的梭形感受器，感受肌肉长度变化（牵张），传入为 Ia 类（初级，动态敏感）与 II 类（次级，静态）纤维；梭内肌纤维受 γ 运动神经元支配，可调节肌梭敏感性。腱器官：位于肌腱内、与肌纤维串联，感受肌张力变化，传入为 Ib 类纤维，作用是抑制同一肌肉（防止牵张过度）。二者共同构成“长度-张力”双重监测。"},{"id":"59.3","t":"牵张反射","s":3,"c":"59. 脊髓反射","x":"牵张反射指骨骼肌受到牵拉时反射性收缩。分两类：（1）腱反射（位相性、快反射）：快速叩击肌腱引起肌肉一次快速收缩，如膝跳反射（叩击髌韧带 → 股四头肌收缩，中枢在 L2~L4）、跟腱反射（S1~S2）、肱二头肌反射（C5~C6），反射弧为单突触（Ia → α 运动神经元），临床用于检查反射弧完整性与中枢状态；（2）肌紧张（紧张性、慢反射）：重力持续牵拉肌肉引起缓慢持续的收缩，是维持姿势（抗重力）的基础，属多突触反射，受脑干易化区与抑制区调节。"},{"id":"59.4","t":"γ 环路（α-γ 共同激活）","s":3,"c":"59. 脊髓反射","x":"γ 运动神经元兴奋使梭内肌纤维收缩、肌梭感受末梢被牵拉、Ia 传入增加，反射性使 α 运动神经元兴奋、肌纤维收缩（γ 环路）。意义：使肌梭在肌肉收缩时仍保持敏感性（若只有 α 兴奋，肌肉缩短会使肌梭松弛而失去监测能力）。临床上“γ 僵直”（如帕金森病的肌强直）源于 γ 运动神经元活动过强。"},{"id":"59.5","t":"屈肌反射与交叉伸肌反射","s":3,"c":"59. 脊髓反射","x":"伤害性刺激肢体皮肤引起同侧屈肌收缩、伸肌舒张（屈肌反射，多突触，属保护性反射，中枢在脊髓）；刺激强度增大时引起对侧伸肌收缩（交叉伸肌反射，维持姿势与平衡）。屈肌反射的传入经脊髓后角，通过抑制性中间神经元实现交互抑制。屈肌反射在人类婴儿中明显（Babinski 征阳性），成人皮质脊髓束成熟后被抑制。"},{"id":"59.6","t":"脊髓的传导功能与损伤表现","s":2,"c":"59. 脊髓反射","x":"脊髓半横断（Brown-Séquard 综合征）：同侧损伤平面以下本体感觉与精细触觉丧失（后索损伤）、同侧痉挛性瘫痪（皮质脊髓束）、对侧痛温觉丧失（脊髓丘脑束在节段内交叉）。脊髓完全横断：损伤平面以下运动与感觉全失、反射消失（休克期后反射亢进）、膀胱直肠功能障碍。前角病变（脊髓灰质炎）表现为弛缓性瘫痪而无感觉障碍；后索病变（脊髓痨）表现为位置觉与振动觉丧失、感觉性共济失调。"},{"id":"60.1","t":"脑干的组成与功能","s":3,"c":"60. 脑干与肌紧张","x":"脑干包括中脑、脑桥、延髓，内有第 III~XII 对脑神经核、上下行传导束与网状结构。功能：（1）传导（感觉上行、运动下行）；（2）反射中枢：呼吸、心血管、吞咽、呕吐、咳嗽、瞳孔对光反射、角膜反射、前庭反射；（3）网状结构调节肌紧张与觉醒；（4）整合内脏活动。脑干损伤（如脑疝、出血）可致呼吸循环衰竭而死亡（“生命中枢”）。"},{"id":"60.2","t":"去大脑僵直","s":3,"c":"60. 脑干与肌紧张","x":"在中脑上、下丘之间横断脑干（去大脑动物），动物立即出现四肢伸直、头尾昂起、脊柱挺硬（角弓反张）的抗重力肌紧张亢进，称去大脑僵直。机制：切断了大脑皮质与纹状体下行至脑干网状结构抑制区的纤维，使抑制区活动减弱而易化区相对占优势，伸肌紧张加强。分 α 僵直（α 运动神经元直接兴奋增强）与 γ 僵直（γ 运动神经元兴奋增强，经 γ 环路）两种成分，切断相应后根可使僵直消失（证明其反射性质）。"},{"id":"60.3","t":"脑干网状结构对肌紧张的调节","s":3,"c":"60. 脑干与肌紧张","x":"（1）易化区：范围广（中脑被盖、脑桥被盖、延髓网状结构背外侧、下丘脑、丘脑板内核），刺激后肌紧张增强，其活动依赖感觉传入；（2）抑制区：范围小（延髓网状结构腹内侧、大脑皮质运动区、纹状体、小脑前叶蚓部），刺激后肌紧张减弱。两者通过网状脊髓束下行调节 α 与 γ 运动神经元。正常时易化与抑制平衡，维持适度肌紧张；平衡破坏（如去大脑僵直、帕金森病）则出现肌张力异常。"},{"id":"60.4","t":"脑干对姿势的调节","s":2,"c":"60. 脑干与肌紧张","x":"姿势反射包括：（1）状态反射：头部位置改变引起四肢肌紧张重新分配（迷路紧张反射与颈紧张反射）；（2）翻正反射：动物被推倒后恢复正常姿势的一系列反射（视觉、迷路、躯体感觉参与，中脑动物可完成）；（3）跳跃反应与放置反应。这些反射在中脑动物（切除大脑皮质）仍存在，是脑干整合姿势的基础。"},{"id":"60.5","t":"脑干的其他整合功能","s":2,"c":"60. 脑干与肌紧张","x":"（1）觉醒与睡眠：网状上行激活系统维持皮层觉醒，损伤或受压（如脑干出血）导致昏迷；（2）内脏活动：延髓心血管中枢、呼吸中枢、呕吐中枢、咳嗽与吞咽中枢；（3）控制摄食、体温、情绪的下丘脑通过脑干下行通路实现；（4）脑干听觉与视觉反射（惊跳反射、瞳孔反射、眼球运动）。"},{"id":"60.6","t":"脑干损伤的定位与临床","s":2,"c":"60. 脑干与肌紧张","x":"（1）中脑损伤（Weber 综合征）：同侧动眼神经麻痹（眼睑下垂、瞳孔散大、眼球外斜）伴对侧偏瘫（大脑脚锥体束）；（2）脑桥损伤：同侧面神经与展神经麻痹伴对侧偏瘫（Millard-Gubler 综合征）、针尖样瞳孔（交感下行纤维受损）；（3）延髓损伤（Wallenberg 综合征）：同侧面部痛温觉丧失、共济失调、Horner 征伴对侧躯体痛温觉丧失（小脑后下动脉闭塞）；（4）脑干受压（脑疝）：意识障碍、瞳孔先缩小后散大、呼吸节律改变（Cheyne-Stokes 呼吸、共济失调性呼吸）、血压升高伴心率减慢（Cushing反应），是颅内压增高的危象，提示脑干功能衰竭。"},{"id":"61.1","t":"基底神经节的组成","s":3,"c":"61. 基底神经节","x":"基底神经节包括尾状核、豆状核（壳核与苍白球）、底丘脑核、黑质（致密部与网状部），纹状体 = 尾状核 + 壳核。主要环路：大脑皮质 → 纹状体 →苍白球内侧部/黑质网状部 → 丘脑（腹前核、腹外侧核）→ 大脑皮质（“皮质基底节-丘脑-皮质”环路），参与运动的启动、程序化、肌紧张调节与认知。"},{"id":"61.2","t":"直接与间接通路","s":3,"c":"61. 基底神经节","x":"（1）直接通路：纹状体（D1 受体）→ 苍白球内侧部/黑质网状部抑制 →丘脑去抑制 → 皮层兴奋，促进运动；（2）间接通路：纹状体（D2 受体）→苍白球外侧部 → 底丘脑核 → 苍白球内侧部兴奋 → 丘脑抑制，抑制运动。黑质致密部多巴胺能神经元对直接通路（兴奋 D1）与间接通路（抑制 D2）的双向作用，净效应是促进运动。多巴胺减少则运动减少（帕金森病），增多则运动过多（舞蹈病）。"},{"id":"61.3","t":"帕金森病","s":3,"c":"61. 基底神经节","x":"黑质致密部多巴胺能神经元变性（减少 80% 以上）导致：（1）静止性震颤（4~6 Hz，“搓丸样”）；（2）肌强直（铅管样或齿轮样）；（3）运动迟缓（启动困难、面具脸、写字变小）；（4）姿势平衡障碍（慌张步态）。机制为直接通路减弱、间接通路增强，丘脑受抑制。治疗用左旋多巴（L-DOPA，可透过血脑屏障）、多巴胺受体激动剂、MAO-B 抑制剂、深部脑刺激（DBS）。"},{"id":"61.4","t":"亨廷顿舞蹈病与手足徐动","s":2,"c":"61. 基底神经节","x":"亨廷顿舞蹈病：常染色体显性遗传（4 号染色体 IT15 基因 CAG 重复扩增），纹状体 GABA 能神经元变性，表现为不自主的舞蹈样动作、肌张力降低、痴呆，多在中年发病。手足徐动症（athetosis）表现为缓慢扭曲的肢体运动，病变在纹状体。偏身投掷（hemiballismus）因底丘脑核病变，出现对侧肢体的剧烈投掷样动作。"},{"id":"61.5","t":"基底神经节与认知、奖赏","s":1,"c":"61. 基底神经节","x":"除运动外，基底神经节参与习惯学习（纹状体-黑质环路）、奖赏与动机（伏隔核-多巴胺系统，成瘾的神经基础）、强迫行为（皮质-纹状体环路过度活动）与 Tourette 综合征（抽动）。因此基底神经节病变不仅有运动症状，也可有情绪与认知障碍。"},{"id":"61.6","t":"基底神经节的递质平衡与药物","s":2,"c":"61. 基底神经节","x":"纹状体内 ACh（兴奋性中间神经元）与多巴胺（黑质传入、抑制性）保持平衡，类似“油门与刹车”。帕金森病时多巴胺减少、ACh 相对过强，故抗胆碱药（苯海索、安坦）可缓解震颤与强直，但改善运动迟缓的作用弱。用药要点：（1）左旋多巴需与外周脱羧酶抑制剂（卡比多巴）合用，减少外周转化与副作用；（2）维生素 B6 是脱羧酶辅酶，可加速左旋多巴外周降解，故应避免大剂量同服；（3）多巴胺受体激动剂（普拉克索）直接激动 D2 受体；（4）MAO-B 抑制剂（司来吉兰）减少多巴胺降解；（5）长期左旋多巴治疗出现“开关现象”与异动症；（6）抗精神病药（阻断 D2 受体）可引起药源性帕金森综合征，停药可逆。"},{"id":"62.1","t":"小脑的分区与功能","s":3,"c":"62. 小脑","x":"（1）前庭小脑（绒球小结叶与原小脑）：维持身体平衡，接受前庭传入，损伤后出现平衡障碍、步态蹒跚（但无肌力障碍）；（2）脊髓小脑（小脑前叶与后叶蚓部、中间部）：调节肌紧张、协调随意运动，损伤后出现肌张力降低、意向性震颤、共济失调；（3）大脑小脑（新小脑，后叶外侧部）：参与运动的计划、序列化与学习，损伤后出现运动起始延迟、辨距不良、轮替运动障碍。"},{"id":"62.2","t":"小脑的学习与误差校正","s":2,"c":"62. 小脑","x":"小脑是运动学习的“比较器”：爬行纤维（来自下橄榄核）传递“误差”信号，苔状纤维（来自脑桥核等）传递“实际运动状态”，两者在浦肯野细胞上会聚，经 LTD（平行纤维-浦肯野细胞突触减弱）修改运动程序，使动作逐渐精确（如学习弹琴、骑车、瞄准）。小脑损伤后无法通过练习改善动作（运动学习障碍）。"},{"id":"62.3","t":"小脑损伤的典型表现","s":3,"c":"62. 小脑","x":"（1）共济失调（ataxia）：动作不稳、步态蹒跚、指鼻试验不准；（2）意向性震颤（intention tremor）：动作接近目标时抖动加剧（与帕金森病的静止性震颤相反）；（3）辨距不良（dysmetria）：动作幅度过大或不足；（4）轮替运动障碍（dysdiadochokinesia）：快速交替动作笨拙；（5）肌张力降低（hypotonia）；（6）眼球震颤、构音障碍（吟诗样语言）；（7）Romberg 征：闭眼时平衡障碍加重（本体感觉性）而小脑性者睁眼闭眼均不稳。"},{"id":"62.4","t":"小脑的传出与脊髓小脑束","s":2,"c":"62. 小脑","x":"小脑接受大量本体感觉传入（脊髓小脑后束、前束，经下小脑脚与上小脑脚），传出经齿状核 → 丘脑腹外侧核 → 大脑皮质运动区，以及经红核、前庭核、网状结构下行至脊髓（调节肌紧张与姿势）。因此小脑是“运动协调的中枢”，而非运动发起者（运动由皮质发起）。"},{"id":"62.5","t":"小脑皮质的神经环路","s":2,"c":"62. 小脑","x":"小脑皮质由外向内分分子层、浦肯野细胞层与颗粒层。传入纤维两种：（1）苔状纤维（来自脊髓、脑桥核、前庭核）兴奋颗粒细胞 → 平行纤维兴奋浦肯野细胞（简单锋电位）；（2）爬行纤维（来自下橄榄核）直接攀附浦肯野细胞，一次冲动引起一个“复杂锋电位”。浦肯野细胞是小脑皮质唯一的传出神经元，通过 GABA 抑制深部核团（齿状核、间位核、顶核）。平行纤维与浦肯野细胞的突触可发生 LTD（需 Ca²⁺ 与 cGMP/PKC），是比较器式运动学习的细胞基础。"},{"id":"62.6","t":"小脑的非运动功能","s":1,"c":"62. 小脑","x":"近年研究发现小脑参与多种非运动功能：（1）认知（小脑-丘脑-前额叶环路参与工作记忆、语言流畅性）；（2）情绪与社交（小脑蚓部与边缘系统连接，损伤可出现情感淡漠、社交障碍）；（3）内脏调节（通过前庭核与脑干影响呼吸、循环）；（4）癫痫的调制（小脑刺激可抑制癫痫放电）。小脑发育异常与孤独症谱系障碍、精神分裂症的部分表现相关，故小脑被视为“运动与认知的协调器”。"},{"id":"63.1","t":"大脑皮质运动区","s":3,"c":"63. 大脑皮层运动区","x":"主要运动区为中央前回（4 区）与运动前区（6 区），功能特征：（1）交叉支配（头面部多为双侧，下半面与舌为对侧）；（2）倒置分布（下肢在顶部、头面在底部）；（3）面积与运动的精细复杂程度成正比（手与发音器官代表区最大）；（4）刺激引起个别肌肉的收缩（精细定位）。运动前区参与运动的计划与序列组织，损伤后出现运动计划障碍（失用）。"},{"id":"63.2","t":"锥体系与锥体外系","s":3,"c":"63. 大脑皮层运动区","x":"（1）锥体系：皮质脊髓束（起自 4 区、6 区等，经内囊、大脑脚、脑桥、延髓锥体，约 80% 在锥体交叉处交叉形成皮质脊髓侧束，其余为前束）与皮质脑干束（至脑神经运动核）。功能：执行随意运动，尤其精细的独立运动（手指）。上运动神经元损伤表现为痉挛性瘫痪（硬瘫）、腱反射亢进、Babinski征阳性、肌萎缩不明显；（2）锥体外系：皮质-基底节-丘脑-皮质环路与皮质脑桥-小脑-皮质环路，功能为调节肌紧张、协调运动、维持姿势与习惯性运动。下运动神经元损伤表现为弛缓性瘫痪（软瘫）、腱反射消失、肌萎缩明显、病理反射阴性。"},{"id":"63.3","t":"运动单位与运动程序的执行","s":2,"c":"63. 大脑皮层运动区","x":"α 运动神经元及其支配的肌纤维构成运动单位。运动时按“大小原则”募集：先小运动单位（慢肌、抗疲劳）后大运动单位（快肌、力量大），力量随募集与放电频率增加而增大。随意运动的发起：皮质运动区（意图）→ 基底节与小脑（程序与协调）→ 皮质脊髓束 → 脊髓 α 运动神经元 → 肌肉。反馈（肌梭、腱器官、皮肤感受器）实时修正动作。"},{"id":"63.4","t":"大脑皮质的功能一侧优势","s":2,"c":"63. 大脑皮层运动区","x":"两侧大脑半球功能有分工：左半球（多数人）优势于语言（Broca 区 44、45 区，运动性语言；Wernicke 区 22 区，感觉性语言）、逻辑分析、右手技巧；右半球优势于空间知觉、音乐、情绪、面容识别。一侧优势与遗传及后天（利手训练）有关。胼胝体切断（裂脑人）后，两半球信息不能互通，可出现“分离”现象（左手不能说出所持物品名称）。"},{"id":"63.5","t":"上、下运动神经元损伤的鉴别与定位","s":3,"c":"63. 大脑皮层运动区","x":"锥体束不同部位损伤表现不同：（1）内囊损伤：对侧偏瘫（含下半面与舌），常伴偏身感觉障碍与偏盲（“三偏”）；（2）锥体交叉以上损伤：对侧肢体硬瘫；（3）锥体交叉以下（延髓以下）损伤：同侧肢体硬瘫；（4）脊髓前角或周围神经损伤（下运动神经元）：弛缓性瘫痪、肌萎缩明显、腱反射消失、病理反射阴性、肌电图示失神经电位。上运动神经元损伤的特点是“硬瘫+ 反射亢进 + 病理反射阳性 + 肌萎缩轻”，因失去对下运动神经元的抑制，α与 γ 神经元活动增强。Babinski 征（跖反射由屈变伸）是锥体束损伤的重要体征。"},{"id":"63.6","t":"运动的反馈控制与内部模型","s":2,"c":"63. 大脑皮层运动区","x":"随意运动依赖三级控制：（1）前馈控制：大脑皮质与基底节、小脑在运动前预设运动程序与“内部模型”，预测运动后果并预先调整姿势（如提重物前先增加肌张力）；（2）反馈控制：肌梭（长度）、腱器官（张力）、关节感受器与皮肤感受器实时传入，经脊髓与皮质修正动作偏差（如持杯时手被推仍能稳住）；（3）适应与学习：小脑通过比较“预期”与“实际”感觉反馈，反复修正内部模型（如戴上棱镜后视觉-运动逐渐重新对齐）。内部模型受损时出现辨距不良与意向性震颤（小脑）、运动启动困难（基底节）。"},{"id":"64.1","t":"自主神经系统的组成","s":3,"c":"64. 自主神经系统","x":"自主神经（植物性神经）支配心肌、平滑肌与腺体，分交感与副交感两部分：（1）交感：节前纤维短（起自胸腰段 T1~L2 侧角），节后纤维长，经交感链或椎前神经节换元，分布广泛（几乎全身）；（2）副交感：节前纤维长（起自脑干第 III、VII、IX、X 对脑神经核与骶段 S2~S4），节后纤维短，神经节位于器官旁或壁内，分布局限（瞳孔、唾液腺、心肺、胃肠、膀胱、生殖器）。此外还有肠神经系统（“第三部分”）。"},{"id":"64.2","t":"递质与受体","s":3,"c":"64. 自主神经系统","x":"全部自主神经节前纤维、副交感节后纤维、支配汗腺的交感节后纤维释放ACh（胆碱能）；多数交感节后纤维释放去甲肾上腺素（肾上腺素能）；肾上腺髓质直接分泌肾上腺素与去甲肾上腺素入血。受体：N1（神经肌肉接头）、N₂（自主神经节）、M（副交感效应器、汗腺）；α1（血管收缩、瞳孔开大）、α2（突触前抑制）、β1（心）、β2（支气管、骨骼肌血管、子宫）、β3（脂肪分解）。"},{"id":"64.3","t":"交感与副交感的生理作用","s":3,"c":"64. 自主神经系统","x":"交感（“应急-动员”）：心率加快、心肌收缩力增强、血压升高、支气管扩张、瞳孔开大、胃肠运动与分泌抑制、括约肌收缩、膀胱逼尿肌舒张、糖原分解与脂肪分解、汗腺分泌增加、竖毛肌收缩。副交感（“休息-消化-储能”）：心率减慢、支气管收缩、瞳孔缩小、唾液与消化液分泌增加、胃肠运动增强、括约肌舒张、膀胱逼尿肌收缩、胰岛素分泌增加。多数器官受双重支配且作用拮抗，交感兴奋时全身动员、副交感兴奋时多为局部活动。"},{"id":"64.4","t":"自主神经的中枢调节","s":2,"c":"64. 自主神经系统","x":"（1）脊髓：完成排尿、排便、勃起等基本反射；（2）脑干：延髓心血管中枢与呼吸中枢、脑桥排尿中枢、唾液核；（3）下丘脑：自主神经的最高整合中枢，调节体温、摄食、水平衡、性行为、情绪与应激的自主反应；（4）大脑皮质与边缘系统：通过下丘脑影响内脏活动（情绪性心率加快、紧张性排尿）。内脏传入主要经迷走神经与交感神经传入孤束核，再上传。"},{"id":"64.5","t":"自主神经的功能特点","s":2,"c":"64. 自主神经系统","x":"（1）双重支配与拮抗（但汗腺、肾上腺髓质、多数血管仅受交感支配）；（2）紧张性发放：切断神经后效应器出现“去神经”改变（如心率加快、瞳孔缩小），说明平时有持续张力；（3）受效应器状态影响：同一递质在不同器官效应不同（ACh 使胃肠收缩、心肌抑制）；（4）交感反应常为“全或无”式的整体动员（mass discharge），副交感多为局部精细调节。器官交感作用副交感作用受体心脏心率加快、收缩力增强心率减慢、心房收缩减弱β1 / M支气管平滑肌舒张平滑肌收缩β2 / M瞳孔开大肌收缩（扩大）括约肌收缩（缩小）α1 / M胃肠运动与分泌抑制、括约肌收缩运动与分泌增强、括约肌舒张αβ / M膀胱逼尿肌舒张、括约肌收缩逼尿肌收缩、括约肌舒张β/M汗腺分泌增加（胆碱能）无M肾上腺髓质分泌肾上腺素无N₂"},{"id":"64.6","t":"自主神经功能的药物与临床","s":2,"c":"64. 自主神经系统","x":"常用药物：（1）M 受体阻断剂阿托品：扩瞳、抑制唾液与汗腺分泌、解除胃肠痉挛、加快心率，用于术前给药与有机磷中毒解救；（2）β 受体阻断剂普萘洛尔：减慢心率、降低心肌耗氧，用于心律失常、心绞痛与甲亢对症治疗；（3）α 受体阻断剂酚妥拉明：用于嗜铬细胞瘤与血管痉挛；（4）胆碱酯酶抑制剂新斯的明：用于重症肌无力与术后肠麻痹；（5）β2 激动剂沙丁胺醇：舒张支气管，用于哮喘。自主神经功能紊乱的表现：体位性低血压（交感缩血管反射障碍）、Horner 综合征（一侧瞳孔缩小、眼睑下垂、面部无汗）、无汗症、胃轻瘫、神经源性膀胱。糖尿病自主神经病变是常见并发症。"},{"id":"65.1","t":"脑电图的波形","s":3,"c":"65. 脑电与睡眠","x":"在头皮记录的大脑皮质电活动（EPSP 与 IPSP 的同步化总和）显示四种基本波形：（1）α 波：8~13 Hz，20~100 μV，清醒、安静、闭眼时在枕叶最明显，睁眼或注意时消失（α 波阻断）；（2）β 波：14~30 Hz，5~20 μV，睁眼、精神活动时出现，额叶为主；（3）θ 波：4~7 Hz，困倦、入睡初期与儿童常见；（4）δ 波：0.5~3 Hz，深睡、婴儿与极度疲劳时出现，成人清醒时出现提示脑病变。"},{"id":"65.2","t":"脑电波形成的机制","s":2,"c":"65. 脑电与睡眠","x":"EEG 主要反映大量皮质锥体细胞顶端树突的突触后电位（EPSP/IPSP）同步总和，而非单个神经元的动作电位。同步化由丘脑非特异性投射系统（丘脑皮质环路）与皮质内中间神经元网络驱动：丘脑节律性放电驱动皮质产生 α 节律，网状上行激活系统兴奋时去同步化（α 波消失、β 波出现）。诱发电位可反映特定感觉通路的传导与处理。"},{"id":"65.3","t":"睡眠的两种时相","s":3,"c":"65. 脑电与睡眠","x":"（1）慢波睡眠（SWS，非快速眼动睡眠 NREM）：分 N1~N3（N3 为深睡，δ 波占 20% 以上），脑电为高幅慢波，肌张力降低、心率呼吸减慢、体温下降、生长激素分泌峰出现、蛋白质合成与组织修复增强，占睡眠的75%~80%；（2）快速眼动睡眠（REM，异相睡眠）：脑电呈低幅快波（类似清醒），出现快速眼球运动、肌张力极度降低（除眼肌与膈肌）、心率呼吸不规则、阴茎勃起，做梦多发生于此期，占 20%~25%，与记忆巩固（尤其程序性记忆与情绪记忆）有关。睡眠周期约 90 分钟，一夜 4~6 个周期。"},{"id":"65.4","t":"睡眠的发生机制","s":2,"c":"65. 脑电与睡眠","x":"（1）觉醒维持：网状上行激活系统（ACh、NE、5-HT、组胺、orexin神经元）；（2）睡眠启动：下丘脑视前区（VLPO）GABA 能神经元抑制觉醒系统，腺苷蓄积（长时间觉醒）促进睡眠；（3）REM 的调控：脑桥胆碱能神经元（REM-on）与蓝斑 NE 能、中缝 5-HT 能神经元（REM-off）的交替；（4）昼夜节律：视交叉上核（SCN）经松果体褪黑素调节睡眠-觉醒周期，光照经视网膜-下丘脑束同步 SCN。发作性睡病与 orexin 缺乏有关。"},{"id":"65.5","t":"睡眠的生理意义","s":2,"c":"65. 脑电与睡眠","x":"（1）恢复体力与脑力（能量储备、清除代谢废物，如 β-淀粉样蛋白经脑内类淋巴系统清除）；（2）促进生长发育（SWS 的 GH 峰）；（3）记忆巩固（REM 与 SWS 均参与）；（4）免疫调节（睡眠时免疫细胞活性与细胞因子分泌增强）；（5）情绪调节。长期睡眠剥夺导致认知下降、免疫功能降低、代谢紊乱与心血管风险增加。"},{"id":"65.6","t":"脑电的临床应用与睡眠障碍","s":2,"c":"65. 脑电与睡眠","x":"（1）癫痫：发作间期可见棘波、尖波、棘慢复合波，发作时脑电广泛高幅放电，脑电是癫痫诊断与定位的核心手段；（2）脑外伤与脑病：弥漫性慢波（δ 波）提示脑功能受损，脑电静息（<2 μV）是脑死亡的判定标准之一；（3）麻醉深度监测与昏迷评估（诱发电位、双频指数）；（4）睡眠监测（多导睡眠图 PSG 记录脑电、眼电、肌电、呼吸与血氧）。睡眠障碍：失眠（入睡困难、早醒，与过度觉醒相关）、阻塞性睡眠呼吸暂停（打鼾、反复低氧与觉醒，致白天嗜睡与心血管风险）、发作性睡病（orexin 神经元缺失，表现为日间突发睡眠、猝倒、入睡幻觉、睡眠瘫痪）、REM 睡眠行为障碍（肌张力未消失而“演出梦境”，常为帕金森病前驱表现）。"},{"id":"66.1","t":"学习与记忆的类型","s":3,"c":"66. 学习、记忆与情绪","x":"学习类型：非联合学习（习惯化、敏感化）、联合学习（经典条件反射、操作式条件反射）、观察学习与洞察学习（灵长类）。记忆按时间分：（1）感觉记忆（数百毫秒）；（2）短时记忆（数秒至数分钟，容量 7±2 个组块，依赖电活动与磷酸化）；（3）长时记忆（数天至数年，需新蛋白合成与突触结构改变）。按内容分陈述性记忆（事实与事件，依赖海马与内侧颞叶）与非陈述性记忆（技能、习惯、条件反射，依赖纹状体、小脑、杏仁核）。"},{"id":"66.2","t":"记忆的神经机制","s":3,"c":"66. 学习、记忆与情绪","x":"（1）突触可塑性：LTP/LTD 是记忆的细胞模型，海马是陈述性记忆形成的关键（海马损伤患者 H.M. 不能形成新的陈述性记忆，但能学会新技能，说明两类记忆系统分离）；（2）分子机制：CaMKII 自身磷酸化（“记忆分子”）、CREB 依赖的基因转录、新突触形成与树突棘增大；（3）记忆的巩固与再巩固：睡眠中记忆被“重放”与整合，回忆起记忆后再巩固需要蛋白合成；（4）系统巩固：记忆逐渐由海马转移到新皮质存储。"},{"id":"66.3","t":"突触前与突触后机制在记忆中的作用","s":2,"c":"66. 学习、记忆与情绪","x":"突触前机制：递质释放概率增加（与 Ca²⁺ 通道、突触囊泡数量有关），见于短时程易化（如海兔缩鳃反射的敏感化，5-HT 经 cAMP-PKA 磷酸化 K⁺通道、延长动作电位、增加 Ca²⁺ 内流）。突触后机制：受体数量与敏感性改变、树突棘形态变化（LTP 后棘增大，称为“记忆的形态学基础”）。两者共同实现记忆的存储。"},{"id":"66.4","t":"情绪与情感的神经基础","s":3,"c":"66. 学习、记忆与情绪","x":"（1）杏仁核：恐惧与威胁检测、恐惧条件反射的形成与表达（杏仁核损伤者不能形成恐惧条件反射）；（2）下丘脑与脑干：情绪的自主神经与内分泌表达（心率、血压、脸红、出汗）；（3）前额叶皮质：情绪的调控与抑制（腹内侧前额叶损伤者情绪失控、决策障碍）；（4）伏隔核与多巴胺系统：奖赏与愉快感（成瘾的基础）；（5）扣带回与岛叶：疼痛的情绪成分与内脏感受。"},{"id":"66.5","t":"情绪与健康的相互关系","s":2,"c":"66. 学习、记忆与情绪","x":"情绪通过自主神经、内分泌与免疫影响健康：长期焦虑与抑郁使交感张力升高、皮质醇升高，导致高血压、冠心病风险增加、免疫功能下降（伤口愈合慢、易感染）、睡眠障碍与代谢紊乱。反之，躯体疾病（甲亢、糖尿病、慢性疼痛）也引起情绪障碍。这一“心理-神经-内分泌-免疫网络”是竞赛常考的整体观内容。"},{"id":"66.6","t":"发育关键期与经验依赖性可塑","s":2,"c":"66. 学习、记忆与情绪","x":"发育早期存在“关键期”（critical period），特定经验必须在限定时间内获得，否则相应功能难以恢复正常：（1）视觉：单眼剥夺（遮盖）可使视皮质眼优势柱偏向未剥夺眼，成年后不可逆（Hubel 与 Wiesel 的实验）；（2）语言：语言习得关键期约在青春期前，关键期后学习第二语言难以达到母语水平，早期失聪者若未及时植入人工耳蜗则语言发育受限；（3）依恋与社交：母婴分离、孤儿院养育可致长期情绪与认知障碍（“印随”是禽类关键期学习的典型，Lorenz 的实验）；（4）性行为的组织化作用：早期性激素影响下丘脑的性别分化。关键期的机制与突触修剪、抑制性中间神经元成熟、髓鞘化与表观遗传调控有关，成年后可塑性下降但未完全消失。第八篇 生殖与发育"},{"id":"67.1","t":"雄性生殖器官","s":3,"c":"67. 生殖器官与配子发生","x":"雄性生殖器官包括睾丸（生精与内分泌）、附睾（精子成熟与储存，约 2周）、输精管（输送、储存）、精囊腺（分泌果糖等，占精液 60%）、前列腺（分泌碱性液体与前列腺素）、尿道球腺（分泌黏液）。精液由精子与精浆组成，一次射精 2~5 mL，含精子 1 亿~2 亿个/mL（低于 2 000 万/mL 为少精症）。精子在附睾获得运动与受精能力，在女性生殖道获能（capacitation）后才能受精。"},{"id":"67.2","t":"精子的发生","s":3,"c":"67. 生殖器官与配子发生","x":"精原细胞（2n）经有丝分裂增殖，部分分化为初级精母细胞（2n）→ 减数第一次分裂为次级精母细胞（n）→ 减数第二次分裂为精细胞（n）→ 经变态（形成顶体与尾）成为精子（n）。支持细胞（Sertoli 细胞）提供营养与血睾屏障，分泌雄激素结合蛋白（ABP）与抑制素。全过程约 64~74 天。温度对生精至关重要：阴囊温度比体温低 1~2 ℃，隐睾（睾丸未降）因温度过高导致不育。"},{"id":"67.3","t":"雌性生殖器官与卵子发生","s":3,"c":"67. 生殖器官与配子发生","x":"雌性生殖器官包括卵巢（产生卵子与分泌激素）、输卵管（拾卵、受精与早期胚胎发育场所，受精多在壶腹部）、子宫（胚胎着床与发育）、阴道与外生殖器。卵子发生：卵原细胞（2n）在胎儿期已完成增殖并进入第一次减数分裂前期的双线期，出生时约 100 万~200 万个初级卵母细胞，青春期约 30 万个，一生排卵 400~500 个，其余退化（卵泡闭锁）。排卵前完成第一次减数分裂（排出第一极体），受精时才完成第二次减数分裂。"},{"id":"67.4","t":"卵泡的发育与排卵","s":3,"c":"67. 生殖器官与配子发生","x":"卵泡发育：原始卵泡 → 初级卵泡 → 次级卵泡（出现卵泡腔、卵泡膜）→成熟卵泡（格拉夫卵泡）。颗粒细胞分泌雌激素，卵泡膜细胞在 LH 作用下合成雄激素，后者在颗粒细胞经芳香化酶转为雌激素（“双细胞双促性腺激素学说”）。排卵：LH 峰引起卵泡壁破裂、卵子与放射冠排出，卵泡塌陷形成黄体（分泌孕激素与雌激素）。若未受精，黄体退化为白体；若受精，黄体在hCG 作用下成为妊娠黄体。"},{"id":"67.5","t":"生殖管的周期性变化","s":2,"c":"67. 生殖器官与配子发生","x":"子宫内膜在卵巢激素作用下呈周期性变化（见第 68 章）；输卵管黏膜与子宫颈黏液也呈周期变化（排卵期宫颈黏液稀薄、拉丝度大、羊齿状结晶，利于精子通过；黄体期黏稠）。阴道上皮在雌激素作用下角化、糖原含量增加（乳酸杆菌分解产酸，维持酸性环境防御）。"},{"id":"67.6","t":"生殖的神经内分泌调控","s":3,"c":"67. 生殖器官与配子发生","x":"下丘脑 GnRH（脉冲式）→ 腺垂体 FSH 与 LH → 性腺（配子发生与性激素分泌）→ 性激素负反馈（或排卵前正反馈）于下丘脑与垂体。青春期启动与下丘脑对性激素负反馈的敏感性降低、kisspeptin 神经元激活有关。松果体褪黑素在长日照动物（如马、雪貂）抑制、短日照动物（羊）促进繁殖活动，是季节繁殖的神经内分泌基础。"},{"id":"68.1","t":"月经周期的分期","s":3,"c":"68. 生殖周期","x":"以 28 天计，分：（1）月经期（第 1~5 天）：黄体退化、雌激素与孕激素骤降，子宫内膜脱落出血（30~80 mL），伴前列腺素引起的子宫收缩；（2）增生期（卵泡期，第 6~14 天）：卵泡发育、雌激素升高，子宫内膜基底层细胞增生、腺体增长；（3）分泌期（黄体期，第 15~28 天）：黄体分泌孕激素，子宫内膜继续增厚、腺体分泌糖原、血管增多、水肿，为着床准备。若未受精，黄体退化，进入下一个月经期。"},{"id":"68.2","t":"激素的周期性波动","s":3,"c":"68. 生殖周期","x":"（1）FSH 在卵泡早期略升高，促进卵泡发育；（2）雌激素在卵泡晚期达第一个高峰（约 200~400 pg/mL），对下丘脑-垂体产生正反馈，引起 LH 峰（排卵前 24~36 小时）与 FSH 小峰；（3）排卵后黄体分泌孕激素，孕激素在黄体中期（第 21 天）达峰（约 10~30 ng/mL），雌激素出现第二个较低高峰；（4）若无妊娠，黄体退化，雌、孕激素下降，撤除对 FSH/LH 的抑制，新的周期开始。"},{"id":"68.3","t":"排卵与黄体的调控","s":3,"c":"68. 生殖周期","x":"LH 峰是排卵的直接触发因素：LH 峰使卵母细胞恢复减数分裂、卵泡壁蛋白酶（胶原酶、纤溶酶原激活物）活性升高、前列腺素增加引起卵泡收缩，卵泡破裂排出卵子。排卵后颗粒细胞与卵泡膜内层细胞黄体化，形成黄体，分泌孕激素与雌激素。黄体寿命约 14 天（固定），故黄体期长度恒定，卵泡期长度可变，这决定月经周期的长短差异。"},{"id":"68.4","t":"基础体温与排卵判断","s":2,"c":"68. 生殖周期","x":"孕激素使下丘脑体温调定点略升高，故排卵后基础体温升高 0.3~0.5 ℃ 并持续至月经前，呈双相曲线，可用于判断有无排卵（单相提示无排卵）。临床还用宫颈黏液、血孕酮（黄体中期 >3 ng/mL 提示排卵）、超声监测卵泡。"},{"id":"68.5","t":"其他动物的生殖周期","s":3,"c":"68. 生殖周期","x":"（1）动情周期（发情周期）：多数哺乳动物（牛、羊、猪、鼠）有季节性或不间断的动情周期，分动情前期、动情期（接受交配）、动情后期、动情间期；无月经（子宫内膜不脱落或少量吸收），出血见于犬、灵长类；（2）季节繁殖：羊、鹿、马等受日照长度调控（短日照或长日照），野生哺乳动物多在食物丰富、气候适宜的季节繁殖；（3）诱导排卵：兔、猫、骆马等需交配刺激才排卵（反射性排卵）；（4）灵长类（人、猴）有月经周期，子宫内膜周期性脱落出血。"},{"id":"68.6","t":"月经周期异常","s":1,"c":"68. 生殖周期","x":"（1）无排卵性月经：青春期与更年期常见，因无黄体形成、孕激素缺乏，表现为周期紊乱、经量异常；（2）痛经：前列腺素使子宫过度收缩；（3）闭经：妊娠、哺乳、过度运动、体重过低（体脂率过低影响 GnRH 脉冲）、高PRL 血症、卵巢早衰；（4）多囊卵巢综合征（PCOS）：雄激素升高、LH/FSH 比值升高、持续无排卵、胰岛素抵抗。"},{"id":"69.1","t":"受精与着床","s":3,"c":"69. 妊娠与分娩","x":"受精：精子经获能后穿过放射冠与透明带（顶体反应，释放透明质酸酶等），与卵细胞膜融合，精卵结合后卵细胞完成第二次减数分裂、释放第二极体，形成雌雄原核融合的受精卵（zygote）。皮质反应与透明带反应阻止多精入卵。受精部位在输卵管壶腹部。着床：受精卵经卵裂（第 3 天为桑椹胚、第4~5 天为囊胚）进入子宫，约第 6~7 天透明带消失后滋养层附着并侵入子宫内膜（植入），滋养层分泌 hCG 维持黄体。"},{"id":"69.2","t":"胎盘的结构与功能","s":3,"c":"69. 妊娠与分娩","x":"胎盘由胎儿侧的绒毛膜绒毛与母体侧的基蜕膜构成，是母胎间物质交换的界面（“胎盘屏障”，多数小分子可过，大分子与多数病原体不能过，但酒精、药物、病毒如风疹、HIV、梅毒可过）。功能：（1）交换：O₂、CO₂、营养物质、抗体（IgG 可过，新生儿被动免疫）、药物；（2）内分泌：hCG、hPL、雌激素、孕激素（见第 49 章）；（3）屏障与免疫豁免（滋养层不表达经典 MHC，避免母体排斥）。"},{"id":"69.3","t":"妊娠期的母体变化","s":2,"c":"69. 妊娠与分娩","x":"（1）生殖系统：子宫增大（容积从 10 mL 至 5 L）、乳腺发育；（2）心血管：血容量增加 40%~50%（血浆增加多于红细胞，出现生理性血液稀释与“妊娠期贫血”）、心输出量增加 30%~50%、心率增快；（3）呼吸：潮气量增加、残气量减少，因膈肌上抬呈过度通气（PaCO₂ 略低）；（4）代谢：体重增加 10~12 kg（胎儿、胎盘、羊水、子宫、乳腺、血容量、脂肪），基础代谢率升高，胰岛素抵抗增加（妊娠期糖尿病风险）；（5）肾：GFR 增加50%，血肌酐降低；（6）内分泌：hCG、hPL、雌激素、孕激素、皮质醇、醛固酮升高。"},{"id":"69.4","t":"分娩的机制","s":3,"c":"69. 妊娠与分娩","x":"分娩分三期：（1）第一产程（宫口扩张期）：规律宫缩使宫颈扩张至 10 cm，历时 8~12 小时（初产妇更长）；（2）第二产程（胎儿娩出期）：腹肌与膈肌配合宫缩娩出胎儿；（3）第三产程（胎盘娩出期）：胎儿娩出后 5~15分钟胎盘剥离排出。启动机制：胎儿下丘脑-垂体-肾上腺轴成熟、CRH 与皮质醇升高 → 胎盘雌激素合成增加、孕激素相对下降（孕激素/雌激素比值降低）→ 子宫肌兴奋性升高、催产素受体与前列腺素增加 → 宫缩。正反馈：宫缩刺激宫颈 → 反射性催产素释放 → 更强宫缩（Ferguson 反射）。松弛素软化宫颈与骨盆韧带。"},{"id":"69.5","t":"分娩的激素调节与临床","s":2,"c":"69. 妊娠与分娩","x":"催产素（子宫收缩）、前列腺素（PGE2、PGF2α，促宫缩与宫颈成熟）、雌激素（增加子宫对催产素敏感性）、松弛素（软化产道）。临床用缩宫素引产或加强宫缩，用前列腺素制剂促宫颈成熟，用 β2 激动剂（利托君）或钙通道阻滞剂抑制早产宫缩，用糖皮质激素促胎肺成熟（早产时）。"},{"id":"69.6","t":"妊娠诊断与异常","s":1,"c":"69. 妊娠与分娩","x":"诊断：hCG 检测（尿或血，受精后约 10 天可测出）、超声（5~6 周见妊娠囊）、胎心（10~12 周可闻及）。异常：（1）异位妊娠（输卵管妊娠，破裂出血危及生命）；（2）妊娠高血压综合征（子痫前期，高血压、蛋白尿、水肿）；（3）胎盘前置与胎盘早剥；（4）Rh 血型不合溶血（见第 14 章）；（5）妊娠期糖尿病；（6）自然流产。"},{"id":"70.1","t":"乳腺的发育","s":3,"c":"70. 泌乳","x":"乳腺由 15~20 个腺叶组成，腺泡为分泌单位，经小导管、大导管开口于乳头。发育分阶段：胚胎期基础发育 → 青春期在雌激素（导管）、GH、皮质醇、甲状腺激素作用下发育 → 妊娠期在雌激素与孕激素（腺泡）、hPL、PRL作用下充分发育。乳腺发育需要多种激素协同，其中雌激素促导管、孕激素促腺泡。"},{"id":"70.2","t":"泌乳的启动与维持","s":3,"c":"70. 泌乳","x":"分娩后胎盘娩出、雌激素与孕激素水平骤降，解除对 PRL 的抑制，PRL促进腺泡上皮合成与分泌乳汁（泌乳启动，产后 2~3 天“下奶”）。持续泌乳依赖吸吮刺激：吸吮乳头 → 传入（肋间神经、T4~T6）→ 下丘脑 → 抑制多巴胺释放 → PRL 分泌增加（吸吮后 10~20 分钟出现高峰），同时催产素脉冲释放引起射乳（let-down）。"},{"id":"70.3","t":"射乳反射","s":3,"c":"70. 泌乳","x":"吸吮或触觉、听觉（婴儿啼哭）刺激 → 下丘脑室旁核 → 神经垂体释放催产素 → 乳腺肌上皮细胞收缩 → 乳汁从腺泡排入导管 → 射出。射乳反射是典型的神经内分泌反射，可被紧张、疼痛、焦虑抑制（交感兴奋抑制射乳），故“放松有助于哺乳”。催产素还对子宫有收缩作用（哺乳促子宫复旧）。"},{"id":"70.4","t":"乳汁的成分","s":3,"c":"70. 泌乳","x":"初乳（产后 1~5 天）：色黄、含大量免疫球蛋白（sIgA）、乳铁蛋白、白细胞，蛋白质高、脂肪与乳糖低，有轻泻作用（促胎粪排出）。成熟乳：蛋白质约 1.2%、脂肪 3.5%、乳糖 7%，比例适合婴儿；含免疫球蛋白、溶菌酶、双歧因子、生长因子与激素。与牛奶相比，人乳蛋白质低但乳清蛋白比例高（易消化）、乳糖高、铁虽少但吸收率高。泌乳量每日约 600~800 mL。"},{"id":"70.5","t":"哺乳期与生殖的关系","s":2,"c":"70. 泌乳","x":"哺乳期高 PRL 抑制 GnRH 脉冲释放，导致排卵受抑制与闭经（哺乳期闭经，lactational amenorrhea），是自然的避孕机制（但非绝对可靠）。长期哺乳与骨质疏松风险的关系（高 PRL 抑制雌激素）也值得注意。PRL 瘤引起闭经-溢乳综合征。"},{"id":"70.6","t":"泌乳的种属差异与生产应用","s":2,"c":"70. 泌乳","x":"（1）奶牛：分娩后进入泌乳期（约 305 天），随后干奶期 60 天；产奶量受遗传、营养、挤奶频率（每日 2~3 次）、环境与激素影响；（2）挤奶反射与射乳反射相似，需在安静环境下进行，应激（肾上腺素）抑制射乳而降低产奶量；（3）母猪的放乳为周期性（约每小时一次），仔猪吸吮刺激催产素释放；（4）乳的成分因种属差异极大：鲸与海豹乳脂率可达 30%~50%（利于幼仔在寒冷环境快速积累脂肪），兔乳蛋白极高，人乳乳糖高；（5）乳腺炎多由金黄色葡萄球菌、链球菌经乳头侵入，引起乳汁中体细胞数升高与产量下降，挤奶卫生与干奶期抗生素治疗是防控关键。"},{"id":"71.1","t":"繁殖策略的类型","s":3,"c":"71. 动物繁殖策略与季节繁殖","x":"（1）r 选择（机会型）：小型、寿命短、繁殖力强、后代多而缺乏照料（昆虫、鱼类、鼠类），种群数量受密度制约小；（2）K 选择（平衡型）：大型、寿命长、产仔少而投入大（象、鲸、灵长类），种群接近环境容纳量。繁殖投入与寿命之间存在权衡（trade-off）；一次性繁殖（semelparity，如鲑鱼洄游产卵后死亡、竹开花后死亡、部分昆虫）与多次繁殖（iteroparity）。"},{"id":"71.2","t":"季节繁殖与环境信号","s":3,"c":"71. 动物繁殖策略与季节繁殖","x":"多数野生动物在特定季节繁殖，使幼体在食物丰富、气候适宜时出生。环境信号：（1）光周期（最重要，通过视网膜-视交叉上核-松果体褪黑素通路，长日照动物在春夏繁殖如马、仓鼠，短日照动物在秋冬繁殖如羊、鹿）；（2）温度（鱼类产卵需积温、爬行类孵化温度决定性别——温度依赖型性别决定TSD）；（3）食物与降雨（热带动物雨季繁殖）；（4）社会因素（群体密度、性信息素，如群居啮齿类同步动情）。"},{"id":"71.3","t":"繁殖行为的神经内分泌基础","s":2,"c":"71. 动物繁殖策略与季节繁殖","x":"性激素（睾酮、雌二醇、孕酮）作用于下丘脑与边缘系统（内侧视前区、杏仁核），易化性行为与攻击行为；犁鼻器感受信息素；多巴胺与阿片系统调节性奖赏。季节繁殖动物的生殖轴在非繁殖季处于抑制状态（GnRH 分泌减少、性腺萎缩），切除松果体或改变光照可改变其繁殖季节。"},{"id":"71.4","t":"各类动物的繁殖特点","s":3,"c":"71. 动物繁殖策略与季节繁殖","x":"（1）鱼类：多数体外受精、卵生，产卵量巨大（鲤鱼可达数十万粒），部分有护卵行为；（2）两栖类：体外受精、卵生，需水环境，幼体变态；部分有抱对、育幼行为；（3）爬行类：体内受精、卵生或卵胎生，TSD 现象；（4）鸟类：体内受精、卵生，有求偶、筑巢、孵卵与育雏行为，多为一夫一妻，海鸟盐腺；（5）哺乳类：体内受精、胎生（单孔类除外）、哺乳，后代存活率高，有发情周期与季节繁殖。"},{"id":"71.5","t":"性选择与配偶竞争","s":2,"c":"71. 动物繁殖策略与季节繁殖","x":"性选择（Darwin）指通过与同性竞争或异性选择获得繁殖优势：（1）同性竞争（雄性争斗，选择体型、角、犬齿等武器）；（2）异性选择（雌性选择装饰、鸣声、求偶炫耀，如孔雀尾羽、极乐鸟、蛙鸣）；（3）精子竞争与隐蔽选择。解释性二型（雄雌外形差异）与“累赘特征”的进化，是动物学与生理学交叉的常考内容。"},{"id":"71.6","t":"生殖调控与人工繁殖技术","s":2,"c":"71. 动物繁殖策略与季节繁殖","x":"（1）人工授精：采集精液、稀释保存（液态 15~18 ℃ 保存 1~3 天，冷冻-196 ℃ 可长期保存），输精于发情期，广泛用于牛、猪；（2）同期发情：用孕激素缓释装置或前列腺素 F2α 使群体母畜发情同步，便于集中配种与管理；（3）超数排卵与胚胎移植：用 FSH/PMSG 促多卵泡发育、配种后冲洗子宫回收胚胎，移植给同期发情的受体母畜（牛、羊），提高优良母畜的繁殖效率；（4）体外受精与克隆（核移植）、性别控制（流式分选 X/Y 精子）；（5）诱导分娩：前列腺素或糖皮质激素诱发分娩，便于接产管理。这些技术的生理基础是生殖轴的激素反馈、卵泡发育与早期胚胎的子宫内环境。"},{"id":"72.1","t":"胚胎发育的基本阶段","s":3,"c":"72. 胚胎发育基本过程与变态","x":"（1）受精（精子获能、顶体反应、皮质反应）；（2）卵裂：受精卵经多次有丝分裂形成桑椹胚（卵裂球体积不增加，总体积不变）；（3）囊胚形成：出现囊胚腔，哺乳类为囊胚（内细胞团 + 滋养层）；（4）原肠形成：细胞迁移形成外胚层、中胚层、内胚层（三胚层动物），形成原肠腔与胚孔；（5）器官形成（neurulation 神经胚形成、器官原基）；（6）生长与分化。"},{"id":"72.2","t":"三胚层的发育命运","s":3,"c":"72. 胚胎发育基本过程与变态","x":"外胚层：表皮与其附属器、神经系统（神经管与神经嵴衍生物：周围神经、肾上腺髓质、黑色素细胞、颅面骨）、眼晶状体、内耳上皮。中胚层：肌肉、骨骼、真皮、循环系统（心、血管、血细胞）、泌尿生殖系统（肾、性腺）、体腔膜、肾上腺皮质。内胚层：消化道上皮、肝、胰、肺与鳃的上皮、甲状腺、甲状旁腺、胸腺、膀胱上皮。卵黄囊与尿囊参与胎盘形成。"},{"id":"72.3","t":"胚胎诱导与发育调控","s":3,"c":"72. 胚胎发育基本过程与变态","x":"胚胎诱导指一部分组织（诱导者）促使邻近组织改变发育方向，如脊索中胚层诱导外胚层形成神经管（Spemann 与 Mangold 的“组织者”实验，1924）；晶状体诱导（视泡诱导表面外胚层形成晶状体）；中胚层诱导形成肢体（顶外胚层嵴 AER 与极化活性带 ZPA）。分子基础：Hox 基因决定体节的空间身份与前后轴、Sonic hedgehog（Shh，脊索与 ZPA）、BMP 与Noggin/Chordin 的拮抗决定背腹轴、Wnt、FGF、Nodal 等信号通路。"},{"id":"72.4","t":"变态发育","s":3,"c":"72. 胚胎发育基本过程与变态","x":"（1）两栖类：蝌蚪（水生、有尾、鳃呼吸、草食）→ 蛙（陆生、无尾、肺呼吸、肉食），变态由甲状腺激素（T3/T4）触发，催乳素拮抗，表现为尾部吸收（细胞凋亡）、四肢长出、鳃退化、肠道缩短；（2）昆虫完全变态（卵-幼虫-蛹-成虫，如蛾、蝶、蝇、蜂）由保幼激素（JH）与蜕皮激素（20羟基蜕皮酮）共同调控：JH 高时蜕皮为幼虫、JH 低时化蛹、JH 消失时羽化为成虫；不完全变态（卵-若虫-成虫，如蝗虫、蝉）；（3）棘皮动物、海鞘、软体动物的幼虫变态。"},{"id":"72.5","t":"发育与环境的相互作用","s":2,"c":"72. 胚胎发育基本过程与变态","x":"环境因素影响发育：（1）温度决定爬行类性别（TSD，如鳄、龟，孵化温度高多为雌或雄，因芳香化酶表达差异）；（2）营养与激素影响性腺发育与体长（如蜜蜂幼虫喂蜂王浆者成蜂王，因 DNA 甲基化差异）；（3）幼体环境可影响成体表型（“发育可塑性”，如蝌蚪在捕食者存在时长出更大的尾肌）；（4）内分泌干扰物（DDT、双酚 A、雌激素类药物）干扰发育与生殖（如鳄的性逆转、鱼类雌化）。"},{"id":"72.6","t":"再生与衰老","s":2,"c":"72. 胚胎发育基本过程与变态","x":"再生分：（1）变形再生（morphallaxis，如涡虫、水螅，残存组织重塑）；（2）新建再生（epimorphosis，如蝾螈肢体、斑马鱼鳍，形成芽基后增殖重演发育过程）。哺乳类再生能力有限（肝、皮肤、外周神经），中枢神经与心肌基本不能再生成熟。衰老的机制包括端粒缩短（细胞复制性衰老，端粒酶在生殖细胞与肿瘤中活跃）、氧化损伤（自由基学说）、DNA 损伤累积、干细胞耗竭与慢性低度炎症；限制能量摄入可延长多种动物寿命（与胰岛素/IG F-1、mTOR 通路相关）。第九篇 备考"},{"id":"73.1","t":"细胞与神经肌肉部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）动作电位去极化是 Na⁺ 内流（不是 K⁺ 外流，也不是 Ca²⁺ 内流），复极化是 K⁺ 外流；（2）静息电位主要由 K⁺ 外流形成，但实际值（-70 mV）比 K⁺ 平衡电位（约 -90 mV）小，因少量 Na⁺ 内流与生电性钠泵；（3）Na⁺通道有失活过程，K⁺ 通道没有，绝对不应期源于 Na⁺ 通道失活；（4）动作电位“全或无”指同一细胞、同一条件下的幅度不变，神经干复合动作电位不呈全或无；（5）终板电位是局部电位（无全或无），不是动作电位；（6）神经肌接头递质是 ACh，受体是 N 型（烟碱型），筒箭毒碱阻断、琥珀酰胆碱持续去极化；（7）骨骼肌兴奋-收缩耦联靠 DHPR-RyR1 机械耦联（不依赖胞外Ca²⁺ 内流），心肌靠 CICR（依赖胞外 Ca²⁺）；（8）骨骼肌舒张靠 SERCA泵回 Ca²⁺，能量不足（ATP 缺乏）时肌肉不能舒张（尸僵）；（9）心肌不会发生强直收缩是因有效不应期长，不是因没有 Ca²⁺；（10）平滑肌收缩的调节蛋白是钙调蛋白（CaM）与 MLCK，不是肌钙蛋白。"},{"id":"73.2","t":"血液与循环部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）血浆胶体渗透压主要由白蛋白形成，晶体渗透压主要由 Na⁺、Cl⁻ 形成；（2）失血时先出现心率加快与血管收缩，血量丢失 20% 以上才明显血压下降；（3）红细胞生成刺激是 EPO，来源于肾（成人约 90%），缺铁致小细胞低色素性贫血、缺叶酸/B12 致巨幼细胞贫血；（4）红细胞内部无氧酵解供能，故不耗氧；（5）内源性凝血起于 XII 接触激活，外源性起于 III，体内以组织因子途径启动为主，二者在 X 处汇合；（6）维生素 K 依赖因子是 II、VII、IX、X（不是 VIII），血友病 A 是 VIII 缺乏；（7）肝素须与抗凝血酶III 结合，体内外均有效；柠檬酸钠只在体外（体内可被代谢）；（8）ABO 抗体是天然 IgM（不能过胎盘），Rh 抗体是免疫性 IgG（能过胎盘）；（9）心动周期中，心室射血时房室瓣关闭、动脉瓣开放，心音由瓣膜关闭引起（不是开放）；（10）射血分数 = 搏出量/舒张末期容积，不是搏出量/收缩末期容积；（11）心肌平台期是 Ca²⁺ 内流与 K⁺ 外流平衡，窦房结 0 期是 Ca²⁺ 内流（无 Na⁺ 参与）；（12）平均动脉压 ≈ 舒张压 + 1/3 脉压；（13）外周阻力主要取决于小动脉口径（与 r 的 4 次方成反比），不是大动脉；（14）组织液生成的有效滤过压中，血浆胶体渗透压是“对抗滤过”的力量；（15）肾上腺素使骨骼肌血管舒张（β2）、皮肤内脏血管收缩（α），总外周阻力变化不大；去甲肾上腺素以缩血管升压为主。"},{"id":"73.3","t":"呼吸部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）胸膜腔内压 = 肺内压 - 肺回缩力，平静呼吸时始终为负压；（2）肺泡表面活性物质由 II 型细胞分泌，降低表面张力、防止肺不张，不是 I 型细胞；（3）肺活量不包含余气量，不能反映全部肺容积；（4）肺泡通气量 =（潮气量 - 无效腔）× 频率，浅快呼吸使肺泡通气量下降；（5）氧的运输主要靠 Hb 化学结合（98.5%），不是溶解；（6）氧解离曲线右移的因素：PCO₂ 升高、H⁺ 升高、温度升高、2,3-DPG 增多；左移：低温、碱中毒、CO中毒、HbF；（7）波尔效应是 pH/CO₂ 影响 Hb 对 O₂ 亲和力，不是影响 Hb与 CO₂ 结合；（8）CO₂ 运输的主要形式是 HCO₃⁻（88%），不是氨基甲酰血红蛋白；（9）CO 中毒时动脉血 PO₂ 正常、不出现发绀，氧容量下降且曲线左移；（10）CO₂ 是调节呼吸最重要的生理因素，低氧经外周化学感受器兴奋呼吸，但严重低氧直接抑制中枢；（11）中枢化学感受器对 H⁺ 敏感而非直接对CO₂ 敏感（CO₂ 需先水化为 H⁺），且不感受低氧；（12）肺牵张反射（黑-伯反射）在成人平静呼吸时基本不参与。"},{"id":"73.4","t":"消化与代谢部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）胃酸由壁细胞分泌（H⁺-K⁺-ATP 酶），内因子也由壁细胞分泌，胃蛋白酶原由主细胞分泌；（2）胃泌素由 G 细胞（胃窦）分泌，促胰液素由 S细胞、CCK 由 I 细胞（十二指肠）分泌；（3）胃液分泌的三个时相中胃期量最大（约 60%），头期酸度与酶含量最高；（4）胃排空最慢的是脂肪，最快的是水；（5）胰液是最强的消化液，其 HCO₃⁻ 由导管细胞分泌（受促胰液素调节），酶由腺泡分泌（受 CCK 调节）；（6）胆汁不含消化酶，胆盐的作用是乳化脂肪与形成微胶粒；（7）肠激酶（肠致活酶）激活胰蛋白酶原，胰蛋白酶再激活其他酶原；（8）长链脂肪酸经淋巴（乳糜微粒）吸收，中短链脂肪酸经门静脉；（9）铁在十二指肠吸收、以 Fe²⁺ 形式、维生素 C 促进；钙吸收依赖维生素 D；（10）维生素 B12 需内因子在回肠末端吸收，故胃切除可致巨幼细胞性贫血；（11）呼吸商：糖 1.00、脂肪 0.71、蛋白质 0.80、混合 0.85；长期饥饿或糖尿病时 RQ 降低；（12）基础代谢率与体表面积成正比，甲亢升高、甲减降低，发热每升高 1 ℃ 增加约 13%；（13）体温调定点上移是发热的机制（致热原→PGE2），阿司匹林使调定点回降；（14）棕色脂肪产热靠UCP1 解偶联，不是靠战栗；（15）汗腺受交感胆碱能纤维支配（例外）。"},{"id":"73.5","t":"排泄与渗透调节部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）肾小球滤过率 125 mL/min（180 L/日），滤过分数约 20%；（2）有效滤过压 = 毛细血管血压 - 血浆胶体渗透压 - 囊内压 ≈ 10 mmHg；（3）近端小管重吸收约 65%~70% 的 Na⁺ 与水，为等渗重吸收，不受 ADH 调节；（4）葡萄糖重吸收在近端小管（SGLT2），肾糖阈约 10 mmol/L（180 mg/dL）；（5）髓袢升支粗段主动重吸收 NaCl 而对水不通透（稀释段），袢利尿剂作用于此；（6）髓质高渗由 NaCl 与尿素共同形成，直小血管的逆流交换维持梯度（不是破坏梯度）；（7）ADH 作用于集合管 V2 受体，经 cAMP使 AQP2 插入顶端膜（不是作用于近端小管）；（8）醛固酮“保钠排钾排氢”，作用于远端小管与集合管；（9）酸中毒时泌 K⁺ 减少→高钾血症；碱中毒时低钾；（10）肾的自身调节范围是 80~180 mmHg（肌源性 + 管球反馈）；（11）淡水鱼不饮水、排稀尿、鳃吸盐；海水硬骨鱼吞海水、少尿、鳃泌盐；软骨鱼保留尿素维持等渗；（12）昆虫排泄器官是马氏管，鸟类/爬行类排尿酸（节水），哺乳类排尿素；（13）海鸟盐腺分泌高渗 NaCl，受副交感胆碱能支配。"},{"id":"73.6","t":"内分泌部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）神经垂体只储存与释放 ADH 与催产素，不合成激素（合成为下丘脑视上核、室旁核）；（2）腺垂体通过垂体门脉（血管）与下丘脑联系，神经垂体通过下丘脑-垂体束（神经）联系；（3）甲状腺激素是唯一含碘的激素，储存在滤泡腔胶质中，T3 活性大于 T4；（4）甲状腺激素受体在核内（虽为胺类），儿茶酚胺受体在膜上；（5）甲状旁腺素升血钙、降血磷；降钙素降血钙、降血磷；维生素 D 升血钙、升血磷；（6）胰岛 B 细胞分泌胰岛素（降糖），A 细胞分泌胰高血糖素（升糖），D 细胞分泌生长抑素；（7）胰岛素是唯一降血糖激素，升糖激素有多种（胰高血糖素、肾上腺素、糖皮质激素、GH）；（8）糖皮质激素的“允许作用”指其本身无直接效应但使其他激素效应得以实现；（9）醛固酮由球状带分泌、受 RAAS 与血 K⁺ 调节；皮质醇由束状带分泌、受 ACTH 调节；（10）肾上腺素主要激动 β 受体（强心），去甲肾上腺素主要激动 α 受体（升压）；（11）hCG 作用类似 LH，维持黄体，是早孕诊断指标；（12）GnRH 需脉冲式释放才有效，持续给药反而抑制（受体下调）。"},{"id":"73.7","t":"神经、感官与生殖部分的易错点","s":3,"c":"73. 高频易错辨析","x":"（1）动作电位在单根神经纤维上双向传导，在反射弧中单向（因突触）；（2）突触前抑制使 EPSP 减小但不产生 IPSP，突触后抑制产生 IPSP；（3）牵张反射的感受器是肌梭（感受长度），腱器官感受张力并抑制同一肌肉；（4）去大脑僵直是“抑制区活动减弱、易化区相对占优”，不是易化区被切断；（5）基底节直接通路促进运动、间接通路抑制运动，帕金森病是多巴胺减少致运动减少；（6）小脑损伤出现意向性震颤与共济失调，帕金森病为静止性震颤；（7）交感神经节前纤维短、副交感节前纤维长；汗腺受交感胆碱能纤维支配；（8）视杆细胞感受器电位是超极化（光照使 Na⁺ 通道关闭），与一般感受器去极化相反；（9）视锥细胞司明视觉与色觉，中央凹只有视锥细胞，视盘无感光细胞；（10）高频声波在耳蜗底部、低频在顶部产生最大振动；（11）半规管感受角加速度，耳石器（椭圆囊、球囊）感受直线加速度与重力；（12）嗅觉是唯一不经过丘脑直接到皮质的感觉；（13）浅感觉（痛温觉）在脊髓内交叉、深感觉在延髓交叉，故脊髓半横断表现交叉性障碍；（14）月经周期中排卵由 LH 峰触发，黄体期长度固定（约 14 天）；（15）孕激素使基础体温升高，雌激素在排卵前对 LH 为正反馈。"},{"id":"73.8","t":"判断题中常见的绝对化陷阱","s":3,"c":"73. 高频易错辨析","x":"（1）“一定”“完全”“全部”类表述多为错误，如“动作电位幅度随刺激强度增大而增大”错误；（2）混淆“浓度”与“分压”、“含量”与“容量”、“渗透压”与“渗透压差”；（3）混淆“促进分泌”与“促进释放”、“合成”与“分泌”；（4）混淆“直接作用”与“间接作用”（如PTH 对肠钙吸收是间接经维生素 D）；（5）混淆“首次”与“主要”（如CO₂ 主要运输形式是 HCO₃⁻，O₂ 主要运输形式是 HbO₂）；（6）忽视“负反馈”与“正反馈”的方向（排卵前雌激素是正反馈）；（7）忽视种属差异（哺乳类与鱼类、鸟类的排泄与渗透调节完全不同）；（8）把“神经调节”与“体液调节”的速度与范围弄反。"},{"id":"74.1","t":"各系统调节总表","s":3,"c":"74. 速查表","x":"各系统的主要调节方式与关键激素、反射如下表，用于横向对照记忆。神经调节主要激素/体液因素关键反射或机制循环系统心交感（β1）、心迷走（M）、交感缩血管（α）肾上腺素、NE、RAAS、ADH、ANP、NO减压反射、化学感受器反射呼吸延髓呼吸中枢、迷走（肺牵张）CO₂、H⁺、O₂黑-伯反射、中枢/外周化学感受器消化迷走（ACh）、交感（NE）、肠神经系统胃泌素、促胰液素、CCK、GIP、胃动素头期/胃期/肠期、肠-胃反射排泄交感（β1 促肾素、α 缩血管）ADH、醛固酮、ANP、PTH肌源性调节、管球反馈体温下丘脑 PO/AH、躯体运动（战栗）、交感（血管、汗腺）甲状腺激素、肾上腺素、PGE2调定点、产热与散热平衡内分泌下丘脑-垂体轴、自主神经各靶腺激素长/短/超短负反馈、正反馈生殖下丘脑 GnRH 脉冲、性反射FSH、LH、性激素、PRL、催产素、hCG排卵 LH 峰、射乳反射、分娩正反馈"},{"id":"74.2","t":"激素功能速查表","s":3,"c":"74. 速查表","x":"下表按“来源—主要作用—调节”三栏整理高频激素。激素来源主要作用调节因素GH腺垂体促生长（IGF-1）、促蛋白合成、升糖GHRH 促、生长抑素抑、IGF-1 负反馈TSH腺垂体促甲状腺激素合成与释放TRH 促、T3/T4 负反馈ACTH腺垂体促皮质醇分泌、维持皮质CRH 促、皮质醇负反馈ADH下丘脑（神经垂体释放）集合管 AQP2、水重吸收血浆渗透压升高、血容量减少催产素下丘脑（神经垂体释放）子宫收缩、射乳分娩与吸吮刺激（正反馈）T3/T4甲状腺产热、促生长发育、提高代谢率TSH 促、碘供应、自身调节降钙素PTH甲状腺 C 细胞降血钙、抑破骨血钙升高甲状旁腺升血钙、降血磷、促活性维生素 D血钙降低皮质醇肾上腺束状带升糖、抗炎、允许作用、应激ACTH 促、昼夜节律醛固酮肾上腺球状带保钠排钾排氢RAAS、血 K⁺ 升高肾上腺素肾上腺髓质强心、升糖、舒张支气管交感节前纤维胰岛素胰岛 B 细胞降血糖、促合成血糖升高、GIP/GLP-1胰高血糖素胰岛 A 细胞升血糖、脂肪动员血糖降低、氨基酸睾酮睾丸间质细胞精子发生、第二性征、同化作用LH 促雌二醇卵巢颗粒细胞子宫内膜增生、第二性征、正反馈FSH 促孕酮黄体、胎盘内膜分泌期、保胎、升温LH（黄体）、hCG 维持hCG胎盘滋养层维持黄体（类 LH）妊娠早期升高ANP心房肌利钠排尿、舒血管心房牵张（血容量增加）"},{"id":"74.3","t":"离子通道与电位速查表","s":3,"c":"74. 速查表","x":"下表汇总高频通道、阻断剂与电位数值，用于选择题快速判断。通道/电位主要分布功能阻断剂/数值电压门控 Na⁺ 通道神经元、骨骼肌、心肌工作细胞动作电位 0 期去极TTX、局麻药；阈电位-55 mV电压门控 K⁺ 通道广泛复极、维持静息电位TEA；神经静息 -70 mV L 型 Ca²⁺ 通道心肌、平滑肌、内分泌细胞平台期、CICR、分泌维拉帕米、硝苯地平化学门控阳离子通道神经-肌接头终板膜筒箭毒碱GABA-A 受体 Cl⁻ 通道RyR1/RyR2中枢ACh 引起 Na⁺、K⁺ 同开IPSP骨骼肌/心肌肌浆网Ca²⁺ 释放兰尼碱If 起搏通道窦房结4 期自动去极化铯、伊伐布雷定AQP2 水通道集合管主细胞ADH 调节水重吸收锂、去甲金霉素（抑制）Na⁺-K⁺-2Cl⁻ 同向转运体髓袢升支粗段NaCl 主动重吸收速尿（呋塞米）Na⁺/K⁺-ATP 酶全身细胞维持 Na⁺、K⁺ 梯度哇巴因、洋地黄荷包牡丹碱"},{"id":"74.4","t":"消化液与消化酶速查表","s":3,"c":"74. 速查表","x":"下表汇总消化液成分、pH、分泌量、调节与关键酶，用于消化系统的综合题。消化液分泌量（L/日）pH关键成分主要调节唾液1~1.5 6.6~7.1唾液淀粉酶、黏蛋白、溶菌酶、sIgA副交感（面神经、舌咽神经）反射胃液1.5~2.5 0.9~1.5盐酸、胃蛋白酶原、内因子、黏液迷走、胃泌素、组胺胰液1~2 7.8~8.4胰淀粉酶、胰脂肪酶、蛋白酶原、HCO₃⁻促胰液素（HCO₃⁻）、CCK（酶）胆汁0.8~1 7.4（肝）胆盐、胆色素、胆固醇（无消化酶）CCK（胆囊收缩）、促胰液素小肠液1~3 7.6肠致活酶、黏蛋白、刷状缘酶局部反射、迷走大肠液少量8.3~8.4黏液、HCO₃⁻局部反射"},{"id":"74.5","t":"常用生理数值速查表","s":3,"c":"74. 速查表","x":"下表汇总竞赛中最常考的定量指标，建议考前反复默写。指标数值指标数值神经元静息电位-70 mV骨骼肌静息电位-90 mV阈电位（神经）-55 mV动作电位峰值+30~+40 mV心输出量5 L/min每搏输出量70 mL射血分数55%~65%心率血压（收缩/舒张）90~140/60~90 mmHg中心静脉压60~100 次/分4~12 cmH₂O潮气量500 mL肺活量（男/女）3 500/2 500 mL肺泡通气量4.2 L/min通气血流比0.84肾小球滤过率125 mL/min滤过分数肾血浆流量600 mL/min每日尿量约 20% 1~2 L肾糖阈10 mmol/L（180 mg/dL）血糖（空腹）3.9~6.1 mmol/L血浆渗透压约 300 mOsm/L 2.25~2.75 mmol/L血浆 pH 7.35~7.45红细胞寿命约 120 天血钙"},{"id":"74.6","t":"反射与调节通路速查表","s":3,"c":"74. 速查表","x":"下表按“感受器—传入—中枢—传出—效应”整理高频反射弧，便于整体记忆。感受器传入神经减压反射反射颈动脉窦、主动脉弓窦神经、减压神经延髓心血管中枢迷走/交感 → 心率、血管化学感受器反射颈动脉体、主动脉体窦神经、减压神经延髓呼吸与心血管中枢呼吸肌、交感 → 通气与血压肺牵张反射支气管平滑肌牵张感受器迷走神经延髓迷走 → 吸气切断膝跳反射肌梭（股四头肌）Ia 类纤维脊髓 L2~L4（单突触）α 运动神经元 → 股四头肌收缩屈肌反射皮肤痛感受器Aδ、C 纤维脊髓（多突触）屈肌收缩、伸肌舒张中枢传出与效应排尿反射膀胱壁牵张感受器盆神经骶髓（受脑桥与皮质调控）盆神经 → 逼尿肌收缩、括约肌舒张射乳反射乳头触觉感受器肋间神经下丘脑 → 神经垂体催产素 → 肌上皮收缩瞳孔对光反射视网膜视神经中脑顶盖前区与动眼神经副核动眼神经 → 瞳孔括约肌收缩"},{"id":"75.1","t":"三轮复习的时间安排","s":3,"c":"75. 复习路线","x":"第一轮（基础，约 6~8 周）：按九篇顺序通读，每章先看结构（解剖、组织）再看功能与调节，画出机制流程图，每章做 10 道基础题，目标是“能说出机制链的环节”。第二轮（强化，约 4~6 周）：以知识点标题为提问清单自测，重点做跨系统综合题（如运动时循环、呼吸、体温、代谢的整合）与实验分析题，建立“稳态—调节—整合”的分析框架。第三轮（冲刺，约 2~3周）：只看第九篇的易错辨析与速查表，反复做历年真题与模拟题，整理错题本，考前 3 天只回顾错题与数值表。"},{"id":"75.2","t":"主线记忆法：以稳态为纲","s":3,"c":"75. 复习路线","x":"动物生理学的总纲是“稳态及其调节”。建议以“内环境变量”为主线串联各篇：渗透压→ADH、醛固酮、肾；血糖→胰岛素、胰高血糖素、肾上腺素、皮质醇；血钙→PTH、降钙素、维生素 D；血压→减压反射、RAAS、ANP、局部血流；体温→产热散热、调定点、甲状腺激素；pH→缓冲系统、呼吸、肾；O₂/CO₂→Hb、呼吸调节。每条主线都按“感受器—传入—中枢—传出—效应器—反馈”梳理，可覆盖 70% 以上的综合题。"},{"id":"75.3","t":"比较记忆法：抓差异与例外","s":3,"c":"75. 复习路线","x":"竞赛题偏爱比较与例外：（1）三类肌（骨骼肌、心肌、平滑肌）的钙来源、调节蛋白、能否强直；（2）两类突触（电、化学）的延搁与方向；（3）两种感觉通路（浅、深）的交叉部位；（4）两类渗透调节（淡水鱼、海水鱼）的饮水与排尿；（5）两种呼吸化学感受器（中枢、外周）的敏感因素；（6）两种糖尿病（1 型、2 型）的机制与治疗；（7）两种受体（膜受体、核受体）的起效速度；（8）交感与副交感的支配与递质例外（汗腺）。例外点往往是命题的“陷阱”，需单独列表。"},{"id":"75.4","t":"实验与数据分析题的准备","s":2,"c":"75. 复习路线","x":"常见实验设计：离体神经干动作电位、蛙心灌流（离子与递质对心率的影响）、影响尿生成的因素（静脉注射生理盐水、葡萄糖、ADH、NE）、呼吸的调节（吸入不同气体）、胰液分泌的调节、反射弧分析（脊蛙）、激素对血糖的影响。分析要点：（1）明确自变量与因变量；（2）控制变量（温度、pH、离子浓度、灌流速度）；（3）预期结果与机制解释要对应；（4）注意“先快后慢”“一过性”“剂量依赖”等表述的机制（如注射高渗葡萄糖后尿量先增多后减少，先因渗透性利尿、后因血糖下降 ADH 回升）。"},{"id":"75.5","t":"答题规范与常见失分点","s":2,"c":"75. 复习路线","x":"（1）机制题必须写全环节（“某激素→受体→第二信使→效应酶→生理效应”），不能只写结论；（2）方向性词（升高/降低、内流/外流、收缩/舒张）必须准确；（3）数值要带单位（mV、mL/min、mmol/L、mmHg）；（4）比较题要“分点对应”，先相同后不同；（5）图表题先看坐标轴与单位，再描述趋势与拐点，最后解释机制；（6）遗传与生理交叉题（如性激素与性连锁、ABO 与亲子鉴定）注意条件限定；（7）答题字数与分值匹配，宁可多写环节不要漏关键步骤。"},{"id":"75.6","t":"考场策略与题型应对","s":2,"c":"75. 复习路线","x":"（1）选择题：先排除绝对化与方向错误的选项，注意“最主要”“直接”“首先”等限定词；计算题（心输出量、GFR、清除率、呼吸商、滤过分数）先写公式再代数，注意单位；（2）识图题：先看坐标轴与单位，再找起点、拐点与平台，最后对应机制（如氧解离曲线、动作电位、心动周期压力容积环）；（3）实验题：先写实验目的与原理，再写步骤（分组、控制变量、观察指标），最后写预期结果与结论，注意设对照组；（4）简答与论述：用“结构—功能—调节—意义”四段式或“环节链”式作答，分点编号，先总述后展开；（5）跨学科题（生理与动物学、生态学、进化学交叉）：先判断动物类群与其生活环境，再套用相应的渗透调节、呼吸或繁殖策略。时间分配建议：选择题不超过总时长的 40%，留 20% 检查方向性表述与单位。附录：知识库教材索引本总纲的知识点体系与数值标准，主要依据以下五个生物竞赛知识库中的教材整理，各书在知识库中均有完整或分册藏本，可按需查阅原文核对表述。序号教材版次与作者在本总纲中的主要对应内容《人体及动物生理学》第 4 版，左明雪主编（主教材）全书骨架；细胞生理、神经与肌肉、循环、呼吸、消化、代谢与体温、排泄、内分泌、生殖各篇体系《动物生理学》第 3 版（及第 2 版），陈守良动物界比较生理内容：细胞膜转运、神经兴奋与传导、渗透调节与排泄、感觉器官、动物繁殖《人体及动物生理学》第 3 版，王玢、左明雪前五章细胞生理学与后十一章系统生理学的结构，激素信号转导与分泌调节章节《人体生理学》第 3 版（上、下册），姚泰主编循环、呼吸、消化、能量代谢与体温、尿生成与排出、神经与感官的机制细节与临床联系《动物生理学》第 2 版，欧阳五庆家畜与家禽（牛、羊、猪、鸡）生理特点、生殖与泌乳、生产动物生理指标使用说明：（1）本总纲以第 1 本（左明雪第 4 版）的章节顺序与术语为主，其余四本用于补充动物学特有内容（鱼类渗透调节、昆虫马氏管、鸟类盐腺、季节繁殖）与医学机制细节；（2）凡数值在各书略有差异者（如心率、肺活量、GFR），本总纲采用竞赛与教材通行值，答题时以所在教材版本为准并注明单位；（3）建议将本总纲的九篇与上述教材的章目录做一次对照标注，形成“总纲—教材—真题”三向索引，便于查漏补缺。"}]
window.KG_BOOK["09"]=[{"id":"1.1","t":"植物生理学的定义与研究对象","s":3,"c":"1. 植物生理学的研究内容","x":"植物生理学是研究植物生命活动规律及其与环境相互关系的科学，核心是植物体内物质转化、能量转换和信息传递三大过程。研究层次以个体为主，向下深入到细胞与分子，向上延伸到群体与生态系统，因此它既是植物学的分支，也是与生物化学、细胞生物学、分子生物学高度交叉的学科。"},{"id":"1.2","t":"植物生理学的五大板块","s":3,"c":"1. 植物生理学的研究内容","x":"（1）水分与矿质营养，解决“水和离子从哪里来、怎样进入、怎样散失”；（2）光合作用与物质代谢，解决“有机物与能量从哪里来”；（3）呼吸作用与同化物运输，解决“能量怎样释放、物质怎样分配”；（4）生长发育与生长物质，解决“植物怎样长大、怎样开花结实”；（5）逆境生理，解决“环境胁迫下植物怎样存活”。五个板块之间以“源—流—库”和“信号—响应”两条线索连接。板块核心问题代表内容对应篇章水分与矿质营养水与离子如何吸收、运输、散失水势、蒸腾、必需元素、离子拮抗第二篇光合作用有机物与能量如何产生光反应、碳同化、C₄ 与CAM、光呼吸第三篇呼吸与运输能量如何释放、物质如何分配呼吸途径、抗氰呼吸、压力流动学说第四篇生长物质与发育生长与分化如何被调控五大激素、光周期、春化、ABC 模型第五、六篇逆境生理胁迫下如何维持生存与产量渗透调节、LEA 蛋白、活性氧清除第七篇"},{"id":"1.3","t":"植物生理学的研究方法","s":3,"c":"1. 植物生理学的研究内容","x":"常用方法包括溶液培养与砂基培养（控制营养、制造缺素症）、同位素示踪（¹⁵ N 示踪氮素去向、³² P 示踪磷的运输、¹⁴ CO₂ 示踪光合产物分配）、离体器官与组织培养、嫁接与环割（判断运输途径与信号来源）、显微与显微摄影技术、以及近年来普及的突变体筛选与转录组、蛋白组分析。方法是答题的“工具箱”，凡遇“如何证明”类问题，先想能否用嫁接、环割、离体培养或同位素示踪四种手段中的一种。"},{"id":"1.4","t":"模式植物与突变体的价值","s":2,"c":"1. 植物生理学的研究内容","x":"拟南芥因基因组小、世代短、自交结实多而成为植物生理与发育研究的第一模式植物，水稻是单子叶模式植物，烟草用于组织培养与病毒研究，玉米用于 C₄ 光合与籽粒发育研究，番茄用于果实成熟研究。自发或诱发突变体往往是机制研究的突破口，例如赤霉素合成缺陷的矮生豌豆、光周期不敏感的拟南芥、乙烯不敏感突变体 etr1，都是相关通路被阐明的关键材料。"},{"id":"1.5","t":"学科发展史上的关键节点","s":2,"c":"1. 植物生理学的研究内容","x":"1865 年 Sachs 出版《植物生理学讲义》，标志学科形成；1640 年 van Helmont 的柳树盆栽实验首次用定量方法研究植物生长；1771 年 Priestley发现植物可更新空气，1779 年 Ingenhousz 证明需要光照；1864 年 Sachs 证明光合产物是淀粉；1937 年 Hill 发现希尔反应；1950 年代 Calvin 用 ¹⁴ C 示踪阐明卡尔文循环；1966 年 Hatch 与 Slack 提出 C₄ 途径；1959 年 Butler 发现光敏色素。生长素方面，1880 年达尔文父子发现胚芽鞘向光性，1928 年Went 建立燕麦胚芽鞘弯曲测定法，1934 年 Kögl 从人尿中分离出 IAA。"},{"id":"1.6","t":"与中学生物学教材的衔接","s":2,"c":"1. 植物生理学的研究内容","x":"高中必修内容已经给出光合作用、细胞呼吸、水分与矿质吸收、植物激素的“结论层”，竞赛要求补上“机制层”与“定量层”：例如高中只说“气孔关闭减少水分散失”，竞赛要求说出钾离子泵假说与 ABA 引起保卫细胞去极化、阴离子外流的完整链条。复习时以高中结论为骨架，逐条追问“为什么”和“有多少”，是最省力的升级路径。"},{"id":"1.7","t":"概念—机制—调节—应用四层学习法","s":2,"c":"1. 植物生理学的研究内容","x":"任何一个生理过程都可按四层掌握：是什么（概念与生理意义）、怎样发生（部位、途径、关键酶、能量与物质变化）、受什么调控（内部因素与外部因素、信号通路）、生产上怎么用（栽培、贮藏、育种、植物生长调节剂）。四层齐全才算真正掌握，考场上遇到陌生情境题时，也是按这四层去组织答案。"},{"id":"1.8","t":"常用单位与量级","s":3,"c":"1. 植物生理学的研究内容","x":"水势的单位是 MPa，细胞水势常在 -0.5 至 -2.0 MPa，土壤溶液水势约-0.05 MPa，干旱土壤可达 -2 MPa 以下；光合速率以 µmol CO₂·m⁻²·s⁻¹计，C₃ 植物 10 至 25，C₄ 植物 25 至 50；蒸腾系数即制造 1 g 干物质所消耗的水量，C₃ 作物 400 至 900，C₄ 作物 250 至 350。1 mol 光子（1 爱因斯坦）在可见光区的能量约 170 至 260 kJ，550 nm 绿光处约 218 kJ，400 nm 蓝光处259 kJ，700 nm 红光处 172 kJ。物理量常用单位典型数值水势MPa叶片 -0.5~-2.0，土壤约 -0.05渗透势MPa细胞液 -0.5~-1.5光合速率µmol CO₂·m⁻²·s⁻¹蒸腾速率mmol H₂O·m⁻²·s⁻¹C₃ 10~25，C₄ 25~50 1~5蒸腾系数g 水/g 干物质C₃ 400~900，C₄ 250~350"},{"id":"2.1","t":"植物细胞区别于动物细胞的三大结构","s":3,"c":"2. 植物细胞的构造与细胞壁","x":"植物细胞具有细胞壁、质体和中央大液泡，这三大结构决定了植物生理的三个特点：细胞壁限制了细胞的无限膨胀，使膨压得以建立；质体中的叶绿体使植物成为自养生物；中央大液泡储存水分、离子、糖与色素，是渗透调节与细胞伸长的核心装置。此外植物细胞间存在胞间连丝，使整个植株在物质运输上连成一体。"},{"id":"2.2","t":"细胞壁的分层结构","s":3,"c":"2. 植物细胞的构造与细胞壁","x":"细胞壁自外向内分为胞间层（中层）、初生壁和次生壁。胞间层主要由果胶质构成，黏合相邻细胞，果胶酶降解即导致果实软化与器官脱落；初生壁薄而有弹性，含纤维素、半纤维素与果胶，允许细胞伸长；次生壁在细胞停止生长后沉积于初生壁内侧，含大量纤维素与木质素，坚硬而缺乏延展性，分外层、中层、内层三层，木质部导管、管胞与纤维细胞具有厚的次生壁。层次主要成分特点与功能胞间层果胶质黏合细胞，可被果胶酶降解初生壁纤维素、半纤维素、果胶、伸展蛋白薄、有弹性，允许伸长次生壁纤维素、木质素厚、坚硬，提供支持与输导"},{"id":"2.3","t":"细胞壁的化学组成与网络模型","s":3,"c":"2. 植物细胞的构造与细胞壁","x":"纤维素微纤丝构成骨架，由 β-1,4-葡聚糖链以氢键平行聚集成微纤丝，抗张强度极高；半纤维素（木葡聚糖、阿拉伯木聚糖等）以氢键连接微纤丝，形成柔性的“系链”；果胶（多聚半乳糖醛酸）构成基质，带负电荷，可结合Ca²⁺ 形成“蛋盒”结构，影响壁的孔隙度与黏弹性；伸展蛋白是富含羟脯氨酸的结构蛋白；木质素由苯丙烷类聚合而成，疏水且抗降解。这套“钢筋—系链—水泥”模型是理解细胞伸长与壁松弛的基础。"},{"id":"2.4","t":"胞间连丝与共质体、质外体","s":3,"c":"2. 植物细胞的构造与细胞壁","x":"胞间连丝是穿越细胞壁、连接相邻细胞原生质的通道，内有连丝微管与actin 构成的收缩结构，可限制大分子通过，其通透性受钙与发育状态调节。由此把植物体分为两个运输空间：以胞间连丝相连的原生质体系称为共质体，以细胞壁、细胞间隙与导管组成的连续体系称为质外体。水分与无机离子既可走共质体途径，也可走质外体途径，而蔗糖的韧皮部装载在不同植物中分别利用这两条途径。"},{"id":"2.5","t":"细胞壁的生理功能","s":2,"c":"2. 植物细胞的构造与细胞壁","x":"（1）机械支撑，维持细胞形状与植株直立；（2）限制原生质体无限吸水，使膨压得以建立，是草本植物支撑力的来源；（3）作为选择性通透屏障，参与水分与离子运输的调控；（4）含有识别分子与酶，参与细胞间的识别、防御病原物与细胞壁物质的就地代谢；（5）储存部分钙与硼，参与信号传递。"},{"id":"2.6","t":"细胞膜的流动镶嵌模型与膜脂组成","s":3,"c":"2. 植物细胞的构造与细胞壁","x":"细胞膜以磷脂双分子层为骨架，蛋白质镶嵌、贯穿或附着其上，膜具有流动性、不对称性与选择透性。植物膜脂除磷脂外还含有糖脂（单半乳糖甘油二酯、双半乳糖甘油二酯）与甾醇，糖脂主要存在于叶绿体被膜与类囊体膜。膜脂中不饱和脂肪酸比例越高，相变温度越低，抗冷性越强，这一点是第七章抗寒生理的分子基础。"},{"id":"2.7","t":"膜上的三类运输蛋白","s":3,"c":"2. 植物细胞的构造与细胞壁","x":"（1）通道蛋白，形成亲水孔道，顺电化学梯度转运离子或水，速度快、不耗能，如钾通道与水通道蛋白；（2）载体蛋白，与被转运物质结合并发生构象变化，可顺梯度（协助扩散）也可逆梯度（主动运输），具饱和动力学与竞争性抑制；（3）泵（离子泵 ATP 酶），直接消耗 ATP 逆梯度转运，如质膜 H⁺ATP 酶、液泡膜 V-ATP 酶与 Ca²⁺-ATP 酶。质膜 H⁺-ATP 酶把 H⁺ 泵出细胞，建立跨膜质子电化学梯度，是离子吸收、韧皮部装载与细胞伸长的共同动力源。"},{"id":"2.8","t":"细胞器的分工","s":2,"c":"2. 植物细胞的构造与细胞壁","x":"叶绿体进行光反应与碳同化，线粒体进行三羧酸循环与氧化磷酸化，过氧化物酶体参与光呼吸与脂肪酸 β-氧化，乙醛酸循环体存在于油料种子萌发的子叶中，负责把脂肪转化为糖，液泡承担渗透调节、离子区隔化、水解酶储藏与色素储存，内质网与高尔基体负责蛋白质与多糖的合成、加工与运输。"},{"id":"3.1","t":"水势的概念与单位","s":3,"c":"3. 水势与植物细胞的水分关系","x":"水势（Ψw）是指在同温同压、同高度下，体系中每偏摩尔体积水的化学势与纯水化学势之差，用能量观点衡量水的“做功能力”。纯水的水势规定为0，溶液中溶质降低水势，故溶液水势为负值，且溶液浓度越高水势越低。水势单位为 MPa，也可用 bar（1 bar = 0.1 MPa）表示。水分总是从水势高处自发流向水势低处，这一条是全部水分生理的总纲。"},{"id":"3.2","t":"水势的组成","s":3,"c":"3. 水势与植物细胞的水分关系","x":"植物细胞水势由三部分组成：Ψw = Ψs + Ψp + Ψm，其中 Ψs 为渗透势（溶质势），由细胞液中溶质引起，恒为负值；Ψp 为压力势，由细胞壁对原生质体的反作用（膨压）引起，通常为正值；Ψm 为衬质势，由细胞中胶体物质（蛋白质、细胞壁多糖）吸水引起，为负值。具有中央大液泡的成熟细胞，Ψm 很小可忽略，故 Ψw ≈ Ψs + Ψp；干燥种子与未形成液泡的分生细胞以Ψm 为主。"},{"id":"3.3","t":"渗透势与衬质势的实际数值","s":3,"c":"3. 水势与植物细胞的水分关系","x":"细胞液渗透势一般为 -0.5 至 -1.5 MPa，随溶质浓度与温度变化，温度升高时绝对值略减小。衬质势在干燥种子中可低达 -100 MPa 量级，这正是干种子能强烈吸胀吸水的原因；而当细胞形成大液泡后，衬质势降到 -0.01 MPa 以下，可忽略。答题时务必区分：干种子吸水靠衬质势，成熟细胞吸水靠渗透势。"},{"id":"3.4","t":"压力势与膨压","s":3,"c":"3. 水势与植物细胞的水分关系","x":"当细胞吸水膨胀、原生质体压迫细胞壁时，细胞壁产生大小相等方向相反的反作用力，使细胞内产生静水压即膨压，此时 Ψp 为正值，可达 0.5 至 1.0 MPa。膨压是草本植物机械支撑、气孔张开、细胞伸长与叶片舒展的直接原因。当细胞失水至初始质壁分离时，膨压降为 0，Ψp = 0，此时 Ψw = Ψs。导管中的水处于负压状态（张力），压力势为负值。"},{"id":"3.5","t":"水势的测定方法","s":2,"c":"3. 水势与植物细胞的水分关系","x":"（1）压力室法，对离体枝叶加压至切口出现水膜，所加压力即为该部位水势的负值，是田间最常用的方法；（2）露点微伏计（热电偶湿度计）法，通过测定平衡蒸气压求得水势，精度高但需恒温；（3）质壁分离法，用一系列浓度蔗糖溶液浸泡组织，找出引起 50% 细胞初始质壁分离的浓度，换算成渗透势；（4）染料法与小液流法，用于测定单个细胞的渗透势。"},{"id":"3.6","t":"水分移动的方向与速率","s":3,"c":"3. 水势与植物细胞的水分关系","x":"水分移动的方向由水势差决定，移动速率与 ΔΨ 成正比、与阻力成反比，可写成水流量 = 水势差 / 阻力。土壤—植物—大气连续体中，水势依次下降：土壤约 -0.05 MPa，根木质部 -0.2 至 -0.4 MPa，叶细胞 -0.5 至 -2.0 MPa，大气水势低达 -100 MPa（相对湿度 50% 时约 -94 MPa），因此蒸腾拉力的最终驱动者是大气的水势亏缺。"},{"id":"3.7","t":"细胞吸水的三种方式","s":3,"c":"3. 水势与植物细胞的水分关系","x":"（1）渗透吸水，成熟细胞主要方式，依靠 Ψs 与 Ψp 的差值吸水；（2）吸胀吸水，干种子与死细胞依靠亲水胶体的衬质势吸水，无选择性、可导致体积显著增大并产生巨大压力；（3）降压吸水，因 Ψp 降低（如蒸腾使叶肉细胞膨压下降、气孔保卫细胞失水）而引起的水分内流。三种方式可在同一细胞的不同发育时期依次出现。"},{"id":"3.8","t":"水势组分的符号判断法","s":3,"c":"3. 水势与植物细胞的水分关系","x":"判断某状态下各组分符号，只需记住三条：渗透势永远为负（除纯水）；压力势在正常膨压细胞中为正、在初始质壁分离点为零、在导管张力下为负；衬质势为负且随含水量下降而绝对值增大。若某题给出“细胞水势 -0.8 MPa，渗透势 -1.2 MPa”，则可推算 Ψp = +0.4 MPa，说明细胞处于紧张状态；若给出 Ψp = 0，则该细胞正处于初始质壁分离。状态ΨsΨpΨw紧张细胞（吸水饱和）-1.0 MPa+0.6 MPa-0.4 MPa初始质壁分离-1.0 MPa-1.0 MPa干种子约 -100 MPa（Ψm 主导）极低-0.5 MPa-0.5 MPa导管水柱（张力）"},{"id":"4.1","t":"等渗、低渗与高渗溶液","s":3,"c":"4. 细胞的渗透行为与质壁分离","x":"把细胞置于溶液中，依溶液与细胞液渗透势的相对大小分为三种情况：等渗溶液（渗透势相等）时细胞体积基本不变，但并非最适，因细胞仍需要一定膨压；低渗溶液时细胞吸水、膨压升高，植物细胞因有细胞壁不会被胀破，动物细胞则会溶血；高渗溶液时细胞失水、膨压下降，发生质壁分离。植物细胞的“最适”是略低渗，即能维持一定膨压的溶液。"},{"id":"4.2","t":"质壁分离与质壁分离复原","s":3,"c":"4. 细胞的渗透行为与质壁分离","x":"成熟植物细胞在高渗溶液中失水，原生质体收缩并与细胞壁分离，称质壁分离；把已质壁分离的细胞重新移入清水或低渗溶液，原生质体吸水恢复原状，称质壁分离复原。该现象是“原生质层具有选择透性、细胞壁是全透性、细胞液具有一定渗透势”三个事实的直接证明，也是判断细胞死活的经典方法：死细胞的原生质层失去选择透性，不发生质壁分离。"},{"id":"4.3","t":"质壁分离的两种形式","s":2,"c":"4. 细胞的渗透行为与质壁分离","x":"凹形质壁分离：原生质体在多个位点与细胞壁分离，形成凹形空隙，为多数薄壁细胞的常见形式。凸形质壁分离：原生质体收缩成球形，只在少数点与壁相连，多见于细胞壁较厚或原生质黏度较大的细胞。此外还有“痉挛式”质壁分离，表现为原生质体先出现不规则收缩再分开，与细胞壁的黏附程度有关。"},{"id":"4.4","t":"用质壁分离法测定细胞渗透势","s":3,"c":"4. 细胞的渗透行为与质壁分离","x":"配制 0.1 至 1.0 mol/L 系列蔗糖溶液，分别观察一定数量细胞，记录发生初始质壁分离的细胞比例，取 50% 细胞发生初始质壁分离的溶液浓度，按 Ψs= -iCRT 计算渗透势（蔗糖 i = 1，R = 0.0083 L·MPa·mol⁻¹·K⁻¹，T 为绝对温度）。例如 0.3 mol/L 蔗糖在 27 ℃ 时 Ψs ≈ -0.75 MPa。此法要求细胞具有明显液泡与色素或有色组织，便于观察。"},{"id":"4.5","t":"细胞水势与体积的关系","s":2,"c":"4. 细胞的渗透行为与质壁分离","x":"细胞失水时体积减小、溶质浓缩，Ψs 绝对值增大；同时膨压下降，Ψp 减小，两者共同使 Ψw 下降，于是细胞能从更干燥的环境中吸水。细胞壁的弹性用弹性模量衡量，弹性模量小的细胞（壁柔软）在同样失水量下膨压下降更快、水势下降更多，因而“持水能力”较弱但“吸水能力”较强，这是耐旱性差异的一个细胞学基础。"},{"id":"4.6","t":"萎蔫的两种类型","s":3,"c":"4. 细胞的渗透行为与质壁分离","x":"（1）暂时萎蔫：蒸腾强烈而吸水不足引起，傍晚蒸腾减弱后可自行恢复，此时细胞仍存活；（2）永久萎蔫：土壤水分已降至永久萎蔫系数以下，即使放在饱和水汽中也无法恢复，需灌溉才能解除。永久萎蔫系数指植物发生永久萎蔫时土壤含水量的百分数，其水势约为 -1.5 MPa，是灌溉的临界指标。"},{"id":"4.7","t":"质壁分离原理的应用","s":2,"c":"4. 细胞的渗透行为与质壁分离","x":"（1）鉴定细胞死活与细胞膜完整性；（2）测定细胞液渗透势与细胞水势；（3）判断植物细胞的耐旱、耐盐能力，耐盐植物在同样盐浓度下质壁分离程度轻；（4）解释施肥过量造成“烧苗”，因土壤溶液水势过低使根细胞失水；（5）解释盐渍化土壤上作物出苗困难与种子吸水受阻。"},{"id":"5.1","t":"水分跨膜运输的两条途径","s":3,"c":"5. 水分跨膜运输与水通道蛋白","x":"水分子可以通过磷脂双分子层以简单扩散方式穿过膜，但速度慢，且膜脂疏水尾部的阻力使纯脂双层对水的通透系数很低；更主要的方式是经水通道蛋白（aquaporin，AQP）的协助扩散，速度快、受调控。二者都不直接消耗ATP，驱动力都是水势差（更严格地说是跨膜的渗透压差与静水压差）。"},{"id":"5.2","t":"水通道蛋白的家族与定位","s":3,"c":"5. 水分跨膜运输与水通道蛋白","x":"植物水通道蛋白属于主要内在蛋白（MIP）超家族，分为四个亚家族：质膜内在蛋白（PIP）定位于质膜，液泡膜内在蛋白（TIP）定位于液泡膜，NOD26 样内在蛋白（NIP）多定位在内质网与质膜，小分子碱性内在蛋白（SIP）定位在内质网。每个单体含六个跨膜螺旋，四个单体组成四聚体，每个单体中央形成独立的水通道，部分成员还可通透甘油、尿素、硼酸、硅酸、CO₂ 或 H₂O₂。"},{"id":"5.3","t":"水通道蛋白的活性调节","s":3,"c":"5. 水分跨膜运输与水通道蛋白","x":"调节方式有四种：（1）磷酸化/去磷酸化，如 PIP2;1 在特定丝氨酸被磷酸化后开放，受 ABA 与钙依赖蛋白激酶调控；（2）门控，胞质 pH 降低或 Ca²⁺升高可使通道关闭；（3） trafficking，通过内吞与外排改变膜上通道数量，是快速调节的主要方式；（4）转录水平调节，干旱、盐胁迫会改变 PIP 基因表达。因此水通道蛋白不是“永远打开的孔”，而是可调的阀门。"},{"id":"5.4","t":"渗透水通透性与反射系数","s":2,"c":"5. 水分跨膜运输与水通道蛋白","x":"膜对水的通透性用渗透水通透系数（Pf）表示，单位 cm·s⁻¹；若膜对某溶质完全不通透，该溶质的反射系数 σ = 1，产生的有效渗透压为该溶质渗透压的全值；若膜对该溶质完全通透，σ = 0，不产生有效渗透压。实际计算水流的公式为 Jv = Lp(ΔΨp - σΔΨs)，这一公式解释了为什么高透性溶质（如尿素、甘油）进入细胞后不会造成持久的水分外流。"},{"id":"5.5","t":"水通道蛋白的生理意义","s":3,"c":"5. 水分跨膜运输与水通道蛋白","x":"（1）使细胞能在数秒至数分钟内改变透水性，快速响应干旱与盐胁迫；（2）参与根系径向吸水，PIP 在根内皮层与外皮层的高表达决定了根的水力导度；（3）参与细胞伸长，伸长区细胞需要快速进水维持膨压；（4）参与气孔运动与叶片运动（叶枕细胞快速失水）；（5）参与种子萌发吸胀与果实发育。敲除 PIP 基因的植株水力导度显著下降、生长受阻，是直接证据。"},{"id":"5.6","t":"水势差驱动水流的定量关系","s":2,"c":"5. 水分跨膜运输与水通道蛋白","x":"跨膜水流的速率与跨膜水势差成正比，与膜阻力成反比；对整个植株而言，蒸腾流的水通量与水势梯度之比称为水力导度。木质部的水力导度受导管直径的四次方影响（哈根—泊肃叶定律），导管直径增大一倍，导水能力提高约 16 倍，因此大导管树种输水效率高但更易发生栓塞。"},{"id":"6.1","t":"信号转导的四个基本环节","s":3,"c":"6. 植物细胞信号转导","x":"（1）信号感知，受体与配体（激素、光、病原物激发子、温度）结合；（2）跨膜转换，受体构象改变并把信号传给膜内侧的组分，如受体激酶自磷酸化、G 蛋白活化、离子通道开放；（3）胞内信号转导网络，通过第二信使与蛋白磷酸化级联放大并整合信号；（4）细胞响应，改变酶活性或基因表达，最终表现为生理效应。植物信号通路的一个显著特点是大量采用“双重负调控”，即通过降解或钝化抑制因子来开启响应。"},{"id":"6.2","t":"受体的主要类型","s":3,"c":"6. 植物细胞信号转导","x":"（1）受体激酶，如油菜素内酯受体 BRI1、系统素受体 SR160，具胞外配体结合域、跨膜域与胞内激酶域；（2）G 蛋白偶联受体样蛋白，如拟南芥中的GPA1 参与 ABA 与糖信号；（3）离子通道型受体，如谷氨酸受体样通道参与钙信号与防御；（4）胞内受体，如生长素受体 TIR1（F-box 蛋白）、赤霉素受体 GID1（可溶蛋白）、脱落酸受体 PYR/PYL（START 蛋白）。注意植物激素受体多数不是膜受体，这是与动物激素作用方式的重大区别。"},{"id":"6.3","t":"钙信号与钙调素","s":3,"c":"6. 植物细胞信号转导","x":"胞质游离 Ca²⁺ 浓度静息时约 0.1 µmol/L，受刺激后可升高 10 至 100 倍，形成“钙峰”“钙振荡”，其信息编码在振幅、频率与持续时间的时空模式中。Ca²⁺ 的效应通过三类钙结合蛋白实现：钙调素（CaM）、钙调素样蛋白（CML）与钙依赖蛋白激酶（CDPK/CPK）。钙泵（Ca²⁺-ATP 酶）与Ca²⁺/H⁺ 反向转运体把 Ca²⁺ 泵回液泡与质外体，使信号能够终止，这种“升高—解码—清除”的循环是钙信号工作的基本模式。"},{"id":"6.4","t":"脂质信号分子 IP₃ 与 DAG","s":2,"c":"6. 植物细胞信号转导","x":"质膜上的磷脂酶 C 水解磷脂酰肌醇-4,5-二磷酸（PIP₂），产生肌醇-1,4,5三磷酸（IP₃）与二酰甘油（DAG）。IP₃ 为水溶性，可扩散至液泡膜打开 IP₃门控钙通道，引起胞质 Ca²⁺ 升高；DAG 留在膜上，可激活蛋白激酶 C 类似物。此外磷脂酸（PA）、溶血磷脂等也是重要的脂质信使，参与 ABA 与逆境信号。"},{"id":"6.5","t":"活性氧与一氧化氮作为信号分子","s":2,"c":"6. 植物细胞信号转导","x":"呼吸爆发氧化酶同源蛋白（RBOH）在质膜上产生超氧阴离子，经歧化生成 H₂O₂，H₂O₂ 可经水通道蛋白跨膜，作为信号触发防御反应、气孔关闭与根毛生长。一氧化氮（NO）由硝酸还原酶或 NO 合酶样酶产生，参与生长素信号、防御反应与气孔关闭。活性氧与 NO 都是“双刃剑”，低浓度作信号，高浓度造成氧化伤害。"},{"id":"6.6","t":"蛋白质可逆磷酸化与 MAPK 级联","s":3,"c":"6. 植物细胞信号转导","x":"蛋白激酶把 ATP 的磷酸基转移到 Ser/Thr/Tyr 残基上，蛋白磷酸酶则水解磷酸基，二者共同决定靶蛋白的活性状态。促分裂原活化蛋白激酶（MAPK）级联由 MAPKKK—MAPKK—MAPK 三级组成，每一级都放大信号，最终磷酸化转录因子。MAPK 级联广泛参与逆境响应、气孔发育、细胞分裂与防御反应，是植物信号网络的“主干道”。"},{"id":"6.7","t":"泛素—蛋白酶体途径与激素受体","s":3,"c":"6. 植物细胞信号转导","x":"泛素活化酶 E1、结合酶 E2 与连接酶 E3 依次把泛素链加到靶蛋白上，26S蛋白酶体识别多泛素化蛋白并将其降解。SCF 型 E3 复合体由 Skp1、Cullin、F-box 蛋白与 RBX1 组成，其中 F-box 蛋白决定底物特异性。生长素受体TIR1 就是一种 F-box 蛋白，生长素充当“分子胶水”，促进 TIR1 与Aux/IAA 阻遏蛋白结合，使后者被泛素化降解，从而解除对 ARF 转录因子的抑制。赤霉素、茉莉酸信号也采用相同的“受体即 F-box + 降解阻遏蛋白”策略。"},{"id":"6.8","t":"植物信号转导的独特性","s":2,"c":"6. 植物细胞信号转导","x":"与动物相比，植物信号系统有三个特点：（1）以双重负调控为主，通过钝化或降解抑制因子实现“去抑制”；（2）缺少动物式的第二信使 cAMP 主通路，改以 Ca²⁺、活性氧、脂质分子与蛋白磷酸化为核心；（3）细胞不能移动，因此信号必须通过胞间连丝、韧皮部与挥发性物质在细胞间与植株间传递，并广泛存在系统获得性抗性、系统素这类“整体预警”机制。信号组分代表成员主要作用受体TIR1、GID1、PYR/PYL、BRI1、ETR1识别配体并启动通路第二信使Ca²⁺、IP₃、DAG、H₂O₂、NO放大并传递信号激酶级联MAPK、CDPK、SnRK2磷酸化靶蛋白转录因子ARF、EIN3、HY5、WRKY改变基因表达蛋白降解SCF、26S 蛋白酶体去除阻遏蛋白"},{"id":"7.1","t":"五大类激素的分工","s":3,"c":"7. 植物激素信号概要","x":"生长素（IAA）主司细胞伸长、极性建立与顶端优势；赤霉素（GA）主司节间伸长、种子萌发与果实发育；细胞分裂素（CTK）主司细胞分裂、侧芽生长与延缓衰老；脱落酸（ABA）主司气孔关闭、种子休眠与逆境响应；乙烯（ETH）主司果实成熟、器官脱落与三重反应。油菜素甾醇（BR）、茉莉酸（JA）、水杨酸（SA）、独脚金内酯（SL）等作为“第六类以后”的激素参与生长调控与防御。"},{"id":"7.2","t":"生长素信号通路","s":3,"c":"7. 植物激素信号概要","x":"核心是“TIR1/AFB—Aux/IAA—ARF”模块。低生长素时，Aux/IAA 与ARF 结合抑制其转录活性；生长素浓度升高后与 TIR1 结合，TIR1 作为 Fbox 蛋白招募 Aux/IAA 使其泛素化降解，ARF 被释放，启动下游基因（如GH3、SAUR、Aux/IAA 自身）表达。SAUR 蛋白通过抑制蛋白磷酸酶 2C 促进 H⁺-ATP 酶磷酸化，导致细胞壁酸化与细胞伸长，这条链把信号与酸生长假说连接起来。"},{"id":"7.3","t":"赤霉素信号通路","s":3,"c":"7. 植物激素信号概要","x":"GA 与可溶性受体 GID1 结合，GID1 构象改变后与 DELLA 蛋白结合，形成 GID1-GA-DELLA 复合体，进而被 SCF 型 E3 泛素化并经 26S 蛋白酶体降解。DELLA 是生长抑制因子，其降解即解除抑制，故 GA 的效应是“去掉刹车”。GA 缺陷型（ga1）与 GA 不敏感型（gid1、gid2）均表现矮化，说明通路中任一环节缺失都导致同一表型，这是判断激素通路的经典遗传学证据。"},{"id":"7.4","t":"细胞分裂素信号通路","s":2,"c":"7. 植物激素信号概要","x":"CTK 与质膜上的组氨酸激酶受体（如 CRE1/AHK4）结合，引发受体的自磷酸化与磷酸中继，把磷酸基传给胞质中的磷酸转移蛋白 AHP，再传给核内的反应调节因子（ARR）。A 型 ARR 是响应的负反馈因子，B 型 ARR 是激活下游基因的转录因子。该“双元信号系统”与细菌的渗透感受系统同源，体现了信号模块的进化保守性。"},{"id":"7.5","t":"脱落酸信号通路","s":3,"c":"7. 植物激素信号概要","x":"ABA 与胞质可溶性受体 PYR/PYL/RCAR 结合，受体构象改变后与蛋白磷酸酶 2C（PP2C，如 ABI1）结合并抑制其活性；PP2C 原本使 SnRK2 激酶去磷酸化而失活，被抑制后 SnRK2 自磷酸化激活，进而磷酸化下游的转录因子（ABF/AREB）、阴离子通道 SLAC1 与 NADPH 氧化酶 RBOHF。结果是气孔关闭与抗逆基因表达。这条通路的要点是“抑制抑制者”，即 ABA 通过抑制PP2C 而释放 SnRK2。"},{"id":"7.6","t":"乙烯信号通路","s":3,"c":"7. 植物激素信号概要","x":"乙烯与内质网膜上的受体 ETR1 等结合后，使受体失活，进而使 CTR1（一种 Raf 样激酶）失活；CTR1 失活后不再磷酸化 EIN₂，EIN₂ 的 C 端被切割并进入细胞核，稳定 EIN3/EIL 转录因子，启动下游响应。因此乙烯的作用同样是解除抑制：ctr1 突变体表现为组成型三重反应，是乙烯通路的经典组成型突变。"},{"id":"7.7","t":"油菜素甾醇信号通路","s":2,"c":"7. 植物激素信号概要","x":"BR 与质膜受体激酶 BRI1 结合，促使 BRI1 与其共受体 BAK1 形成复合体并相互磷酸化，随后磷酸化并激活 BSU1 磷酸酶，抑制激酶 BIN₂；BIN₂ 原本磷酸化转录因子 BZR1/BES1 使其被磷酸化滞留或降解，BIN₂ 被抑制后 BZR1去磷酸化入核，激活生长相关基因。BR 促进细胞伸长与分裂、维管束分化、花粉管生长并提高抗逆性。"},{"id":"7.8","t":"激素信号通路的共性总结","s":3,"c":"7. 植物激素信号概要","x":"（1）受体多样，既有膜受体也有可溶性胞内受体；（2）多数通路以“降解或钝化阻遏蛋白”为核心，属双重负调控；（3）转录重编程是共同终点，最终通过 ARF、BZR1、EIN3、ABF、ARR 等转录因子改变基因表达；（4）通路之间存在大量交叉，如 ABA 与 GA 在种子萌发上相互拮抗，生长素与 CTK在顶端优势与器官发生中相互制约。第二篇 水分与矿质营养"},{"id":"8.1","t":"根系吸水的部位","s":3,"c":"8. 根系吸水与水分运输","x":"吸水的主要部位是根尖的根毛区（成熟区），该区已分化出导管、根毛密集、表面积大、细胞水势低，是吸水最活跃的区域；分生区与伸长区吸水能力较弱，根冠与根毛区以上的木栓化区域几乎不吸水。作物移栽时损伤根毛区会导致“缓苗”，育苗移栽带土、剪叶减少蒸腾，正是为保护与代偿这一吸水区。"},{"id":"8.2","t":"被动吸水与主动吸水","s":3,"c":"8. 根系吸水与水分运输","x":"（1）被动吸水：由蒸腾产生的叶部水势下降通过木质部水柱传导至根部，驱动水分被动进入根系，可占全部吸水量的 90% 以上，与根系代谢无直接关系，用呼吸抑制剂或杀死根系后仍能进行；（2）主动吸水：由根系的代谢活动（离子主动吸收、根压）驱动，与呼吸作用密切相关，抑制剂可抑制。夜间或蒸腾微弱时，主动吸水成为主要方式，表现为伤流与吐水。"},{"id":"8.3","t":"根压、伤流与吐水","s":3,"c":"8. 根系吸水与水分运输","x":"根压是根系主动吸水产生的正压力，一般为 0.05 至 0.5 MPa，可使木质部液流上升。伤流是植物茎或叶柄被切断后从伤口流出液体的现象，伤流量可作为根系活力的指标；吐水是未受伤叶片尖端或边缘的水孔排出水滴的现象，多发生在清晨高温高湿、蒸腾微弱时。三者共同证明了主动吸水的存在，是根压存在的经典证据。"},{"id":"8.4","t":"水分在根中的径向运输途径","s":3,"c":"8. 根系吸水与水分运输","x":"水分从根毛进入导管有两条途径：（1）质外体途径，经细胞壁与细胞间隙自由扩散，速度快，但在内皮层被凯氏带阻断，必须转入共质体；（2）共质体途径，经胞间连丝在细胞间传递，受细胞膜透性调控。凯氏带是内皮层细胞壁径向与横向壁的木质化与栓质化加厚，迫使水分与溶质必须通过内皮层细胞膜，从而使根系能对进入中柱的物质进行选择，是根系“选择性吸收”的结构基础。"},{"id":"8.5","t":"内聚力—张力学说","s":3,"c":"8. 根系吸水与水分运输","x":"该学说由 Dixon 与 Joly 于 1894 年提出，解释高大树木的水分上升：（1）蒸腾使叶肉细胞水势降低，产生向上拉力；（2）木质部水柱因水的内聚力（可达数十 MPa）与对管壁的附着力而连续不断；（3）水柱处于张力（负压）状态，从叶到根形成连续的水势梯度。该学说得到三项证据支持：木质部液流存在负压、高大树木的极限高度与内聚力大小相符、水柱一旦断裂（栓塞）即失去输水能力。"},{"id":"8.6","t":"导管与管胞的结构与输水效率","s":3,"c":"8. 根系吸水与水分运输","x":"管胞是单个细长、两端尖斜的细胞，靠具缘纹孔的纹孔膜输水，阻力大，见于裸子植物；导管由多个导管分子纵向连接而成，端壁穿孔形成穿孔板，输水阻力小，见于被子植物。导管直径一般为 20 至 200 µm，管胞仅 10 至 30µm。依哈根—泊肃叶定律，导水能力与半径的四次方成正比，故导管输水效率远高于管胞，这也是被子植物能形成高大乔木并具有高蒸腾能力的原因之一。"},{"id":"8.7","t":"空穴化与栓塞的修复","s":2,"c":"8. 根系吸水与水分运输","x":"当木质部张力过大（强蒸腾、干旱）或发生冻融时，溶解气体逸出形成气泡，水柱断裂称空穴化，气泡阻塞导管称栓塞。植物有若干应对机制：气孔关闭降低张力、根压夜间重新充水、纹孔膜上的微孔限制气泡向邻近导管扩散、部分物种可主动排出导管内气体。栓塞是干旱致死的直接原因之一，也解释了为什么干旱期后大导管树种更易枯梢。"},{"id":"8.8","t":"水分运输的速度与阻力","s":2,"c":"8. 根系吸水与水分运输","x":"木质部液流速度一般为 1 至 45 m/h，草本植物快于木本，导管树种快于管胞树种；水分从根到叶的运输时间在草本中约数十分钟，在百米高的乔木中约需数天至数周。运输阻力主要来自三处：根径向运输、木质部导管内的摩擦阻力、叶柄与叶脉的细端阻力，其中叶脉末端阻力最大，是整条通路的水力瓶颈。"},{"id":"9.1","t":"蒸腾作用的部位与方式","s":3,"c":"9. 蒸腾作用","x":"蒸腾是水分以水蒸气状态从植物体表面散失的过程，方式包括：（1）气孔蒸腾，占 80% 至 90% 以上，是主要方式；（2）角质层蒸腾，幼嫩叶片角质层薄时可达 10% 至 20%，成熟叶仅占很小比例；（3）皮孔蒸腾，木本植物枝条通过皮孔散失，比例极小。蒸腾的实质是液态水汽化，需吸收汽化潜热，每克水在 25 ℃ 汽化约需 2.44 kJ，因此蒸腾具有显著的降温效应。"},{"id":"9.2","t":"气孔的结构与类型","s":3,"c":"9. 蒸腾作用","x":"气孔由两个保卫细胞围成，中间为气孔孔道，双子叶植物的保卫细胞呈肾形，内壁厚、外壁薄，膨胀时因壁厚不均而向外弯曲，气孔张开；禾本科等单子叶植物的保卫细胞呈哑铃形，两端膨大、中间狭窄，两侧各有副卫细胞。气孔数目与分布在上下表皮差异很大，多数双子叶植物下表皮气孔多于上表皮，水生浮叶植物气孔只存在于上表皮，沉水植物则无气孔。"},{"id":"9.3","t":"气孔运动的钾离子泵假说","s":3,"c":"9. 蒸腾作用","x":"这是解释气孔开闭的主导学说：（1）光照下保卫细胞质膜 H⁺-ATP 酶被激活，把 H⁺ 泵出细胞，膜超极化；（2）超极化打开内向 K⁺ 通道，K⁺ 顺电化学梯度进入保卫细胞，同时 Cl⁻ 与苹果酸根等阴离子进入或合成以平衡电荷；（3）保卫细胞渗透势降低、水势下降，水分经水通道蛋白进入，膨压升高，气孔张开。黑暗中或 ABA 作用时，阴离子通道（SLAC1）开放使 Cl⁻ 与苹果酸根外流，膜去极化打开外向 K⁺ 通道，K⁺ 外流，保卫细胞失水，膨压下降，气孔关闭。"},{"id":"9.4","t":"气孔运动的其他调节机制","s":2,"c":"9. 蒸腾作用","x":"（1）苹果酸代谢：K⁺ 进入时伴随苹果酸合成，作为平衡电荷的有机阴离子；（2）蔗糖渗透调节：部分植物（如蚕豆）在气孔开张后期以蔗糖替代 K⁺作为主要渗透物质，淀粉—蔗糖互变参与其中；（3）水通道蛋白：PIP 的通透性变化直接影响保卫细胞快速失水；（4）ABA 通过 PYR/PYL-PP2C-SnRK2通路激活 SLAC1 与 RBOH，产生 H₂O₂ 与 NO，促使气孔关闭；（5）CO₂ 浓度升高与蓝光受体（向光素）共同调节气孔开度。"},{"id":"9.5","t":"蒸腾系数的概念与数值","s":3,"c":"9. 蒸腾作用","x":"蒸腾系数（蒸腾比）指植物每制造 1 g 干物质所消耗的水量（g），其倒数为水分利用效率。C₃ 作物一般为 400 至 900（小麦约 500，水稻可达 700 至1000），C₄ 作物 250 至 350（玉米约 350，高粱约 300），CAM 植物最低。若以摩尔比表示，C₃ 植物每同化 1 mol CO₂ 蒸腾 450 至 950 mol 水，C₄ 植物250 至 350 mol，CAM 植物仅 18 至 125 mol。植物类型C₃ 植物光合速率（µmol CO₂·m⁻²·s⁻¹）10~25蒸腾比（mol 水/molCO₂）450~950蒸腾系数（g 水/g 干物质）400~900 C₄ 植物25~50 250~350 250~350 CAM 植物0.6~2.5 18~125 50~150"},{"id":"9.6","t":"影响蒸腾的内外因素","s":3,"c":"9. 蒸腾作用","x":"外部因素：（1）光照，既提供气孔开张的信号又提高叶温，是最主要因素；（2）大气湿度，湿度越低蒸腾越强，蒸汽压亏缺是直接驱动力；（3）温度，升高叶温增大叶内外蒸汽压差；（4）风速，微风促进蒸腾，强风引起气孔关闭反而抑制；（5）土壤水分，缺水时气孔关闭、蒸腾锐减。内部因素：气孔密度与开度、叶面积、角质层厚度、叶片形态与气孔下陷程度、根系供水能力。"},{"id":"9.7","t":"蒸腾作用的生理意义","s":3,"c":"9. 蒸腾作用","x":"（1）是水分吸收与运输的主要动力，维持木质部液流；（2）降低叶温，避免高温灼伤，每蒸发 1 g 水可带走约 2.44 kJ 热量；（3）促进矿质元素随蒸腾流在体内运输与分布；（4）有利于 CO₂ 的吸收，因为气孔必须开放。其代价是散失大量水分，故植物必须在“碳 gain”与“水 loss”之间权衡，这一权衡是气孔调节与 C₄、CAM 途径进化的根本原因。"},{"id":"9.8","t":"抗蒸腾剂与蒸腾的人工调控","s":2,"c":"9. 蒸腾作用","x":"抗蒸腾剂分三类：（1）代谢型，如苯汞乙酸（PMA）、脱落酸，通过引起气孔关闭降低蒸腾；（2）薄膜型，如硅氧烷、十六醇，在叶面形成薄膜阻碍水分散失；（3）反射型，如高岭土，反射光能降低叶温。生产上用于苗木移栽、果树抗旱与草坪节水，但薄膜型可能同时阻碍 CO₂ 进入而降低光合，需权衡使用。"},{"id":"10.1","t":"必需元素的三条标准","s":3,"c":"10. 植物必需元素","x":"判断某元素是否为植物必需，须同时满足 Arnon 与 Stout（1939）提出的三条标准：（1）缺乏该元素时植物不能完成生活史；（2）缺乏时表现出特有的缺素症，且只有补充该元素才能预防或恢复；（3）该元素在植物代谢中具有直接作用，而非仅仅改善其他元素的有效性或拮抗毒性。依此标准，目前公认的必需元素共 17 种。"},{"id":"10.2","t":"十七种必需元素及其来源","s":3,"c":"10. 植物必需元素","x":"17 种必需元素为碳、氢、氧、氮、磷、钾、钙、镁、硫、铁、锰、硼、锌、铜、钼、氯、镍。其中碳、氢、氧来自 CO₂ 与水，为非矿质元素；其余 14种由根系从土壤中吸收，为必需矿质元素。钠与硅对多数植物非必需，但对某些植物（盐生植物、水稻）有显著有益作用，称为有益元素；钴为豆科植物共生固氮所必需，硒对富硒植物有益。"},{"id":"10.3","t":"大量元素与微量元素的划分","s":3,"c":"10. 植物必需元素","x":"按植物需要量划分：大量元素 9 种，占植物体干重 0.1% 以上，即碳、氢、氧、氮、磷、钾、钙、镁、硫；微量元素 8 种，占干重 0.01% 以下，即铁、锰、硼、锌、铜、钼、氯、镍。注意“微量”指的是需要量而非重要性，微量元素稍多即产生毒害。氮、磷、钾因土壤中常供应不足而被称为“肥料三要素”。类别元素占干重主要来源大量元素C、H、O、N、P、K、Ca、Mg、S大于 0.1% CO₂、水、土壤矿质微量元素Fe、Mn、B、Zn、Cu、Mo、Cl、Ni小于 0.01%土壤矿质、螯合物"},{"id":"10.4","t":"氮的生理功能与缺素症","s":3,"c":"10. 植物必需元素","x":"氮以 NO₃⁻、NH₄⁺ 或尿素形式吸收，是蛋白质、核酸、磷脂、酶、ATP、辅酶、叶绿素、多种激素与维生素的组成成分。缺氮时有机物合成受阻，植株矮小、分枝分蘖少、叶片小而薄，因糖类积累转化为花色素苷而使叶色黄白或发红，老叶先表现症状，易落花落果，产量下降。氮素过多则叶色深绿、徒长、晚熟、抗逆性下降、易倒伏。"},{"id":"10.5","t":"磷与钾的功能及缺素症","s":3,"c":"10. 植物必需元素","x":"磷以 H₂PO₄⁻ 或 HPO₄²⁻ 吸收，是核酸、核蛋白、磷脂、ATP 与植酸的成分，参与糖类运输与细胞液缓冲。缺磷时蛋白质合成受阻、植株矮小、分蘖少，叶呈暗绿或紫红色（糖积累形成花色素苷），成熟延迟，老叶先发病。钾几乎全部以离子态存在，是 60 多种酶的活化剂，参与蛋白质与糖的合成与运输、调节渗透势与跨膜电位、增强保水与抗倒伏能力。缺钾时叶缘先焦枯坏死、叶片缺绿、生长缓慢、抗逆性差，症状也先出现于老叶。"},{"id":"10.6","t":"钙、镁、硫的功能与缺素症","s":3,"c":"10. 植物必需元素","x":"钙是细胞壁胞间层果胶酸钙的成分，维持膜稳定性，作为第二信使（Ca²⁺CaM）参与信号转导，并参与有丝分裂与水解酶活化。因钙在体内移动性差，缺钙时生长点与幼叶先受害，表现为叶尖钩状弯曲、生长点坏死、根系腐烂丛生，番茄“脐腐病”、白菜“干烧心”即典型。镁是叶绿素分子中心原子、多种酶的活化剂，参与氨基酸活化与核酸合成，缺镁时老叶脉间失绿后坏死。硫是含硫氨基酸、蛋白质与辅酶 A、硫脂的成分，缺硫时蛋白质减少、幼叶黄白或发红（与缺氮的老叶先黄相反）。"},{"id":"10.7","t":"八种微量元素的生理功能","s":3,"c":"10. 植物必需元素","x":"（1）铁，是细胞色素、铁硫蛋白与固氮酶的成分，激活叶绿素合成相关酶，缺铁时幼叶黄白（脉间失绿）；（2）锰，参与水的光解（放氧复合体Mn₄CaO₅ 的组成），激活多种酶，缺锰时嫩叶脉间出现缺绿杂斑；（3）硼，促进花粉形成与受精、糖的运输，缺硼时花药花丝萎缩、油菜“花而不实”、棉花“蕾而不花”、顶芽坏死；（4）锌，是色氨酸合成酶与碳酸酐酶的成分，缺锌时幼叶小而簇生（小叶病）；（5）铜，是质体蓝素与多酚氧化酶的成分，缺铜时叶黑绿、坏死卷皱；（6）钼，是硝酸还原酶与固氮酶的成分，缺钼时叶小、失绿坏死卷曲，豆科植物固氮受阻；（7）氯，参与水的光解与渗透调节，缺氯时叶小、萎蔫；（8）镍，是脲酶的成分，缺镍时尿素积累导致叶尖坏死。"},{"id":"10.8","t":"缺素症的可再利用性与症状部位","s":3,"c":"10. 植物必需元素","x":"元素在体内的移动性决定了症状出现的部位。可再利用元素（氮、磷、钾、镁、锌等）在缺乏时能从老叶转移到幼嫩组织，故症状先在老叶出现；不可再利用元素（钙、硼、铁、锰、铜等）一旦沉积在老组织中便难以转移，故症状先在幼嫩组织与生长点出现。因此“看部位判元素”是缺素诊断的第一判据：老叶先病多为氮、磷、钾、镁；新叶先病多为钙、硼、铁、锰、铜。"},{"id":"11.1","t":"根系吸收矿质的特点","s":3,"c":"11. 矿质元素的吸收、运输与诊断","x":"（1）选择性吸收，根系对离子的吸收与土壤溶液中离子的比例不成正比，番茄吸收钙、镁多而吸收硅少，水稻则相反；（2）单盐毒害与离子拮抗，溶液中只有一种金属离子时植物受害，加入少量其他金属离子（如 Ca²⁺）可减轻毒害，称离子拮抗，原因是不同离子在膜上的结合位点相互竞争、维持膜结构稳定；（3）吸收与呼吸相关，缺氧或呼吸抑制剂显著抑制离子吸收，说明主动吸收依赖呼吸供能；（4）根对离子的吸收与吸水不成比例，二者相对独立。"},{"id":"11.2","t":"主动吸收与载体、离子泵","s":3,"c":"11. 矿质元素的吸收、运输与诊断","x":"离子逆电化学梯度进入细胞依靠主动运输。质膜 H⁺-ATP 酶把 H⁺ 泵到膜外，形成膜外高 H⁺ 与内负外正的膜电位（约 -120 至 -160 mV），这一质子动力势驱动两类过程：一是 H⁺ 与离子（如 NO₃⁻、H₂PO₄⁻、SO₄²⁻）的同向运输，二是经离子通道的被动内流（如 K⁺）。载体蛋白具有饱和效应与竞争性抑制，其数量与活性受离子供应状况诱导，这是“饥饿后吸收能力增强”的原因。"},{"id":"11.3","t":"根际与菌根","s":2,"c":"11. 矿质元素的吸收、运输与诊断","x":"根际是根系周围受根分泌物影响的微域土壤，根系分泌的有机酸（柠檬酸、苹果酸）可酸化根际、活化难溶性磷与铁，质子分泌与根系分泌的螯合物（植物铁载体）是禾本科植物获取铁的重要方式。菌根是根系与真菌形成的共生体：丛枝菌根（AM）通过外生菌丝扩大吸收面积，显著提高磷、锌、铜的吸收，约 80% 的陆生植物具有 AM；外生菌根多见于木本植物（松、栎）。菌根还提高抗旱性与抗病性。"},{"id":"11.4","t":"根瘤与生物固氮","s":3,"c":"11. 矿质元素的吸收、运输与诊断","x":"豆科植物与根瘤菌形成根瘤，根瘤菌把 N₂ 还原为 NH₃，反应由固氮酶催化，需大量 ATP（约 16 至 24 个 ATP 还原 1 分子 N₂）与强还原条件，并由豆血红蛋白维持低氧环境保护固氮酶。共生具有特异性，由植物凝集素与细菌结瘤因子（Nod 因子）相互识别启动；低氮、适量磷钾与中性 pH 有利于结瘤，高氮则抑制结瘤。非豆科植物中，放线菌共生的树木（如桤木）与蓝藻共生（如满江红）也能固氮。"},{"id":"11.5","t":"叶片吸收与根外施肥","s":2,"c":"11. 矿质元素的吸收、运输与诊断","x":"叶片可通过角质层与气孔吸收矿质，尤其吸收尿素、磷酸二氢钾、微量元素与生长调节剂。根外施肥（叶面喷施）的特点是见效快、用量省，适合微量元素缺乏与生长后期的磷钾补充，但吸收量有限、易被雨水淋失，不能替代土壤施肥。喷施宜在清晨或傍晚进行，加入少量表面活性剂可提高附着与渗透。"},{"id":"11.6","t":"矿质元素在体内的运输与分配","s":3,"c":"11. 矿质元素的吸收、运输与诊断","x":"矿质元素经根木质部随蒸腾流向上运输，部分可在韧皮部向下再运输。氮主要以氨基酸与酰胺形式运输，磷以磷酸根与磷酸胆碱形式运输，硫以硫酸根与半胱氨酸形式运输，钙主要在木质部随蒸腾流运输且几乎不能再分配，硼以硼酸形式随蒸腾流运输、移动性也差。元素在体内的分配遵循“优先供应生长中心”的原则，因此果实与顶端在供应不足时仍能获取较多养分，而老叶先被“抽调”。"},{"id":"11.7","t":"无土栽培与营养液","s":2,"c":"11. 矿质元素的吸收、运输与诊断","x":"无土栽培是以营养液供给矿质元素而不依赖土壤的栽培方式，分溶液培养、基质培养（蛭石、珍珠岩、岩棉、椰糠）与雾培。营养液的基本要求是：含全部必需元素、离子比例合理、pH 5.5 至 6.5、总盐浓度适宜（电导率可作指标）、铁以螯合态（EDTA-Fe）供应以防沉淀。无土栽培可控性强，广泛用于设施蔬菜、草莓与花卉生产，也是研究缺素症的经典手段。"},{"id":"11.8","t":"缺素诊断与合理施肥的生理指标","s":3,"c":"11. 矿质元素的吸收、运输与诊断","x":"诊断路径为：先看部位（老叶还是新叶），再看症状特征（脉间失绿、叶缘焦枯、坏死斑点、生长点坏死、花而不实），最后用补充试验验证（叶面喷施该元素观察是否恢复，或溶液培养重现症状）。合理施肥的生理指标包括：叶片营养诊断（临界浓度法）、叶绿素含量（SPAD 值）、植株养分携出量与土壤养分平衡、形态诊断（叶色卡）。施肥原则是“看天、看地、看苗”，重视有机肥与化肥配合，避免过量造成土壤次生盐渍化与水体富营养化。第三篇 光合作用"},{"id":"12.1","t":"光合作用的总反应与意义","s":3,"c":"12. 光合色素与叶绿体","x":"光合作用的总反应可写作 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O（简式 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂），其中 O₂ 全部来自水的光解，可用H₂¹⁸O 标记实验证明。光合作用把光能转化为稳定的化学能，每年固定约 1000亿吨碳，是生物圈能量与物质的源头，同时维持大气氧与二氧化碳的平衡。"},{"id":"12.2","t":"叶绿体的结构与光合膜","s":3,"c":"12. 光合色素与叶绿体","x":"叶绿体由双层被膜包裹，内部为基质与类囊体系统。类囊体是扁平囊状结构，多个类囊体堆叠成基粒，基粒之间由基质类囊体（基质片层）相连，形成连续的光合膜系统。光反应在类囊体膜上进行，碳同化在基质中进行。叶绿体含有自身的环状 DNA、70S 核糖体，能合成部分蛋白质，属半自主性细胞器，其起源符合内共生学说。"},{"id":"12.3","t":"光合色素的种类","s":3,"c":"12. 光合色素与叶绿体","x":"高等植物含两类光合色素：（1）叶绿素，包括叶绿素 a（蓝绿色）与叶绿素 b（黄绿色），前者是所有光合生物共有的中心色素，后者为辅助色素；（2）类胡萝卜素，包括胡萝卜素（橙黄色）与叶黄素（黄色），既辅助吸光又起光保护作用。藻类还含藻胆素（藻蓝蛋白、藻红蛋白）。叶绿素 a/b 比值可作判断植物类型的指标：C₃ 植物约 2.8±0.4，C₄ 植物约 3.9±0.6，CAM 植物2.5 至 3.0，阴生植物比值较低以增强对蓝紫光的利用。"},{"id":"12.4","t":"叶绿素的化学结构与光学性质","s":3,"c":"12. 光合色素与叶绿体","x":"叶绿素是含镁的卟啉环化合物，由四个吡咯环通过次甲桥连成大环，中心配位一个 Mg²⁺，环上带一条疏水的植醇长链，使其能插入类囊体膜的脂相。叶绿素 a 的分子式为 C₅₅H₇₂O₅N₄Mg，叶绿素 b 仅在吡咯环Ⅱ上以醛基代替甲基。吸收光谱上，叶绿素在蓝紫光区（约 430 nm）与红光区（约 660 nm）各有一吸收峰，绿光吸收最少而反射最多，所以叶片呈绿色；吸收光谱与作用光谱（以光合速率为纵坐标）基本吻合，是色素参与光合的直接证据。"},{"id":"12.5","t":"荧光现象与能量传递","s":2,"c":"12. 光合色素与叶绿体","x":"叶绿素溶液在透射光下呈绿色，在反射光下呈暗红色，称荧光现象。原因是色素分子吸收光能后由基态跃迁至单线激发态，部分能量以热散失后回到基态时发出波长更长的红光。在完整的叶绿体中，激发能几乎全部以共振方式在色素分子间传递（传递效率可达 90% 以上），最终传给反应中心色素 P680 或P700 引发电荷分离，因此活体叶片荧光很弱；逆境下光能利用受阻，荧光增强，叶绿素荧光参数（Fv/Fm）因此成为判断光抑制与胁迫程度的常用指标。"},{"id":"12.6","t":"类胡萝卜素的功能","s":3,"c":"12. 光合色素与叶绿体","x":"（1）辅助吸光，吸收 400 至 500 nm 的蓝紫光并把能量传给叶绿素 a，扩大可利用光谱；（2）光保护，淬灭三线态叶绿素与单线态氧，防止光氧化损伤；（3）参与叶黄素循环（紫黄质—玉米黄质互变），在强光下耗散多余激发能，是非光化学淬灭的主要机制；（4）作为脱落酸等物质的合成前体。缺少类胡萝卜素的突变体在强光下迅速漂白死亡，说明其光保护不可替代。"},{"id":"12.7","t":"色素蛋白复合体与天线系统","s":2,"c":"12. 光合色素与叶绿体","x":"类囊体膜上的色素与蛋白结合形成复合体：光系统Ⅱ核心复合体含 P680与放氧复合体，其外周有 LHCⅡ 等捕光天线；光系统Ⅰ核心含 P700 与铁硫簇，外围有 LHCI。天线色素把能量汇聚到反应中心，反应中心每吸收一个光子即完成一次电荷分离，把电子传给原初电子受体。天线的另一种重要调节是状态转换：LHCⅡ 在两种光系统之间移动以平衡激发能分配。"},{"id":"12.8","t":"叶片颜色变化的原因","s":2,"c":"12. 光合色素与叶绿体","x":"秋叶变黄是因为叶绿素降解而类胡萝卜素较稳定，黄色显现；变红是因为糖分积累促进花色素苷（花青素）合成，在酸性液泡中呈红色；缺氮、缺镁、缺铁造成的黄化是叶绿素合成受阻；高温、强光或病害造成的“漂白”是色素被光氧化破坏。理解色素稳定性与合成条件，可解释大多数叶色异常现象。"},{"id":"13.1","t":"光反应的基本内容","s":3,"c":"13. 光反应","x":"光反应在类囊体膜上进行，包括光能吸收、电荷分离、电子传递、水的光解与光合磷酸化五个环节，最终产物为 ATP 与 NADPH（合称同化力）以及O₂。每同化 1 分子 CO₂ 需消耗 3 个 ATP 与 2 个 NADPH；水的光解每释放 1分子 O₂ 需转移 4 个电子，同时向类囊体腔内释放 4 个 H⁺。"},{"id":"13.2","t":"光系统Ⅱ与水的光解","s":3,"c":"13. 光反应","x":"PSⅡ 位于基粒类囊体膜上，反应中心色素为 P680，吸收 680 nm 红光后发生电荷分离，电子经去镁叶绿素、质体醌 Q_A、Q_B 传给质体醌库，同时从放氧复合体（OEC，含 Mn₄CaO₅ 簇）夺取电子。OEC 累积 4 次氧化当量后把2 分子水裂解为 1 分子 O₂、4 个 H⁺ 与 4 个电子，此即水的光解，也称希尔反应，可用人工电子受体（如 DCPIP）在离体叶绿体中证实。PSⅡ 是光抑制的主要作用位点，其 D1 蛋白受损后需快速周转修复。"},{"id":"13.3","t":"光系统Ⅰ与铁氧还蛋白","s":3,"c":"13. 光反应","x":"PSⅠ 位于基质类囊体与基粒边缘，反应中心色素为 P700，吸收 700 nm远红光。激发态 P700 把电子传给 A₀、A₁、铁硫簇，最终传给铁氧还蛋白（Fd）；在铁氧还蛋白-NADP⁺ 还原酶（FNR）催化下，2 个电子与 1 个 H⁺还原 NADP⁺ 生成 NADPH。PSⅠ 的特点是仅需光即可完成从细胞色素 b₆f 到NADP⁺ 的电子传递，且可与循环电子流偶联。"},{"id":"13.4","t":"Z 图式","s":3,"c":"13. 光反应","x":"把各电子载体的氧化还原电位按顺序排列，可画出从水到 NADP⁺的“Z”形能量图：P680 被激发后电位变得极负（约 -0.8 V），电子逐级下落到质体醌、细胞色素 b₆f、质体蓝素（电位逐渐升高即能量降低），P700 再次被激发使电位进一步降低（约 -1.2 V），电子经 Fd 传给 NADP⁺。两个光系统串联、两次激发，使电子能从水（+0.82 V）逆势传到 NADP⁺（-0.32 V），这是“双光系统串联”的核心逻辑，也是红光促进效应（爱默生增益效应）的解释。"},{"id":"13.5","t":"非循环电子流与循环电子流","s":3,"c":"13. 光反应","x":"非循环（非环式）电子流：水→PSⅡ→质体醌→细胞色素 b₆f→质体蓝素→PSⅠ→Fd→NADP⁺，产物为 ATP、NADPH 与 O₂，是主要的电子传递方式。循环（环式）电子流：Fd 把电子交回细胞色素 b₆f（经质体醌），再回到PSⅠ，不产生 NADPH 也不放氧，只形成跨膜质子梯度产生 ATP。循环电子流在 ATP 需求超过 NADPH 时（如 C₄ 植物维管束鞘细胞、强光下）被激活，用于调节 ATP/NADPH 比例。"},{"id":"13.6","t":"光合磷酸化","s":3,"c":"13. 光反应","x":"依化学渗透学说，电子传递过程中 H⁺ 从基质泵入类囊体腔（水的光解也在腔内释放 H⁺，NADP⁺ 还原消耗基质中 H⁺），形成跨膜 pH 差（可达 3 个单位）与膜电位，二者合成质子动力势。H⁺ 经 ATP 合酶（CF₀-CF₁）回流时驱动 ADP 与 Pi 合成 ATP。按每对电子传递泵出的 H⁺ 数与 ATP 合酶 c 亚基数目计算，非循环电子流大约产生 2.5 至 3 个 ATP，略低于同化 1 分子 CO₂ 所需的 3 个 ATP，缺口由循环电子流等补充。"},{"id":"13.7","t":"同化力的比例与调节","s":2,"c":"13. 光反应","x":"按化学计量，卡尔文循环需要 ATP/NADPH 为 3 : 2，而非循环电子流提供的比例约为 2.57 : 2，ATP 相对不足，因此植物通过四条途径补足 ATP：（1）循环电子流；（2）水—水循环（Mehler 反应）；（3）线粒体呼吸向叶绿体输出 ATP；（4）叶绿体 ATP 合酶的灵活运转。这一“化学计量缺口”是解释光呼吸、非光化学淬灭与光合调节的重要出发点。"},{"id":"13.8","t":"光抑制与光保护","s":3,"c":"13. 光反应","x":"当吸收的光能超过光合利用能力时，PSⅡ 的 D1 蛋白受损，光合速率下降，称光抑制；严重时发生光氧化破坏，色素漂白、膜脂过氧化。保护机制包括：（1）叶黄素循环耗散多余能量（非光化学淬灭）；（2）状态转换平衡两个光系统的激发；（3）D1 蛋白快速周转修复；（4）Mehler 反应与抗坏血酸—谷胱甘肽循环清除活性氧；（5）叶片运动与叶绿体移动减少吸光。阴生植物光饱和点低，更易发生光抑制。项目光系统Ⅱ光系统Ⅰ反应中心色素P680 P700膜上位置基粒类囊体基质类囊体与基粒边缘原初电子供体水（经 OEC）质体蓝素原初电子受体去镁叶绿素、Q_A A₀、铁硫簇、Fd最终产物电子、H⁺、O₂NADPH（经 FNR）"},{"id":"14.1","t":"C₃ 途径的三个阶段","s":3,"c":"14. 碳同化与光呼吸","x":"卡尔文循环分三阶段：（1）羧化，RuBP 在 Rubisco 催化下与 CO₂ 结合生成 2 分子 3-磷酸甘油酸（PGA），这是 CO₂ 进入有机物的第一个稳定产物；（2）还原，PGA 在 PGA 激酶作用下消耗 ATP 生成 1,3-二磷酸甘油酸，再经甘油醛-3-磷酸脱氢酶消耗 NADPH 还原为甘油醛-3-磷酸（GAP）；（3）再生，每 5 分子 GAP 中的 1 分子作为净产物输出，其余 5 分子经一系列转酮、转醛与异构反应并消耗 ATP 再生 3 分子 RuBP。总反应为 3CO₂ + 9ATP +6NADPH → 1 分子 GAP + 9ADP + 6NADP + 8Pi。"},{"id":"14.2","t":"Rubisco 的结构与双功能","s":3,"c":"14. 碳同化与光呼吸","x":"核酮糖-1,5-二磷酸羧化酶/加氧酶（Rubisco）占叶片可溶性蛋白的 20%至 50%，是地球上含量最多的蛋白，由 8 个大亚基（叶绿体基因编码）与 8 个小亚基（核基因编码）组成。它同时催化两个反应：羧化（RuBP + CO₂）与加氧（RuBP + O₂），两者竞争同一活性位点，相对速率取决于 CO₂/O₂ 浓度比。Rubisco 催化效率低（转换数每秒约 3 至 10 次）且不能区分 CO₂ 与 O₂，这是 C₃ 植物光合效率受限的根本原因，也是 C₄ 与 CAM 途径进化的驱动力。"},{"id":"14.3","t":"卡尔文循环的调节","s":3,"c":"14. 碳同化与光呼吸","x":"调节方式有四类：（1）光的间接调节，光反应使基质 pH 从 7 升至 8、Mg²⁺ 浓度升高，激活 Rubisco 与果糖-1,6-二磷酸酶；（2）硫氧还蛋白系统，铁氧还蛋白还原的硫氧还蛋白使 4 种关键酶（FBPase、SBPase、PRK、GAPDH）的还原态活化；（3）Rubisco 活化酶，ATP 依赖地把抑制性糖磷酸从 Rubisco 活性位点移除，是 Rubisco 活化的必需环节；（4）夜间的抑制，黑暗中核酮糖-1,5-二磷酸合成停止，某些酶被氧化而失活，从而避免无谓消耗 ATP。这套“光下开启、暗中关闭”的机制使碳同化与光反应严格偶联。"},{"id":"14.4","t":"光合产物的去向","s":3,"c":"14. 碳同化与光呼吸","x":"白天光合产物主要以淀粉形式暂存于叶绿体，夜间降解为麦芽糖与葡萄糖运出叶绿体，在胞质中合成蔗糖，经韧皮部运往库器官；同时一部分磷酸丙糖留在叶绿体用于合成淀粉。叶绿体膜上的磷酸转运器以 Pi 交换磷酸丙糖，是“淀粉 vs 蔗糖”分配的关键调节点。淀粉与蔗糖的分配比例影响产量与品质，例如马铃薯需要更多的淀粉、甘蔗需要更多的蔗糖。"},{"id":"14.5","t":"光呼吸的生化途径","s":3,"c":"14. 碳同化与光呼吸","x":"光呼吸的全称是二碳光呼吸碳氧化环（C₂ 循环），其过程跨越三个细胞器：（1）叶绿体中 Rubisco 加氧生成磷酸乙醇酸，经磷酸酶脱磷酸生成乙醇酸；（2）过氧化物酶体中乙醇酸氧化酶把乙醇酸氧化为乙醛酸并产生 H₂O₂，过氧化氢酶分解 H₂O₂，转氨酶把乙醛酸变为甘氨酸；（3）线粒体中 2 分子甘氨酸缩合生成 1 分子丝氨酸并释放 CO₂ 与 NH₃；（4）回到过氧化物酶体生成甘油酸，再进入叶绿体经甘油酸激酶磷酸化为 PGA 进入卡尔文循环。全过程消耗 O₂、释放 CO₂，且消耗 ATP 与还原力，故称“光合的无效耗散”。"},{"id":"14.6","t":"光呼吸的生理意义","s":3,"c":"14. 碳同化与光呼吸","x":"（1）回收碳，C₂ 循环把 75% 的乙醇酸碳回收为 PGA，避免碳的完全损失；（2）消耗多余的能量与还原力，防止光抑制与光氧化，是强光下的保护阀；（3）参与氮代谢，甘氨酸—丝氨酸转化与转氨反应联系氮素代谢；（4）产生 H₂O₂ 与 H₂O₂ 信号，参与信号传导与防御。完全缺失光呼吸的突变体在正常空气中不能存活，说明其并非纯粹的“浪费”。"},{"id":"14.7","t":"光呼吸的影响因素与调控","s":2,"c":"14. 碳同化与光呼吸","x":"影响因素：（1）O₂ 浓度，从 21% 降至 2% 时光呼吸几乎消失，故测定光合常用低氧条件；（2）CO₂ 浓度，升高 CO₂ 抑制光呼吸，是“CO₂ 施肥”增产的机制之一；（3）温度，高温降低 CO₂ 溶解度并提高 Rubisco 对 O₂ 的亲和，光呼吸增强；（4）光照强度，光呼吸随光强增加而增强。调控途径包括：提高 Rubisco 对 CO₂ 的特异性、在叶绿体中引入乙醇酸代谢旁路（如乙醇酸脱氢酶途径）、把 C₄ 途径元件导入 C₃ 作物，这些是光合改良的前沿方向。"},{"id":"14.8","t":"C₃ 植物的碳同位素特征","s":2,"c":"14. 碳同化与光呼吸","x":"C₃ 植物因 Rubisco 对 ¹³ CO₂ 的歧视作用较强，δ¹³C 值约为 -35‰ 至-20‰；C₄ 植物因 PEP 羧化酶几乎不歧视 ¹³ C，δ¹³C 约 -15‰ 至 -9‰；CAM植物居中偏正。碳同位素比值因此成为判断植物光合类型、追溯食物网与古气候的常用指标，也是竞赛中判断未知植物类型的重要依据。"},{"id":"15.1","t":"C₄ 途径的发现与基本特征","s":3,"c":"15. C₄ 途径与 CAM 植物","x":"C₄ 途径由 Hatch 与 Slack 于 1966 年阐明，其特点是在空间上把 CO₂ 的初次固定与卡尔文循环分开：叶肉细胞中以 PEP 羧化酶固定 CO₂ 生成四碳二羧酸（草酰乙酸、苹果酸、天冬氨酸），运到维管束鞘细胞脱羧释放 CO₂，再由 Rubisco 进入卡尔文循环。由于 PEP 羧化酶对 CO₂ 亲和力极高且不与 O₂反应，相当于一个“CO₂ 泵”，使维管束鞘细胞内 CO₂ 浓度提高 10 至 20 倍，从而几乎抑制光呼吸。"},{"id":"15.2","t":"PEP 羧化酶与脱羧反应","s":3,"c":"15. C₄ 途径与 CAM 植物","x":"磷酸烯醇式丙酮酸羧化酶（PEPC）对 HCO₃⁻ 的 Km 很低（约 1 至 5µmol/L），且不受 O₂ 竞争，是 C₄ 光合高效的第一个关键。四碳二羧酸进入维管束鞘细胞后按三种方式脱羧：（1）NADP-苹果酸酶型（NADP-ME），在叶绿体中脱羧产生 CO₂ 与丙酮酸，见于玉米、甘蔗；（2）NAD-苹果酸酶型（NAD-ME），在线粒体中脱羧，见于黍、狗尾草；（3）PEP 羧激酶型（PCK），在胞质中脱羧，见于大黍等。脱羧后的 C₃ 骨架返回叶肉细胞，消耗 ATP 再生 PEP，因此 C₄ 每同化 1 分子 CO₂ 需 5 个 ATP（C₃ 为 3 个）。"},{"id":"15.3","t":"花环结构","s":3,"c":"15. C₄ 途径与 CAM 植物","x":"C₄ 植物的叶片具有“花环状”（Kranz）解剖结构：一圈维管束鞘细胞被一层叶肉细胞环绕，维管束鞘细胞体积大、含大量叶绿体（NADP-ME 型者叶绿体无基粒或基粒发育差）、细胞壁厚且与叶肉细胞之间有大量胞间连丝。叶肉细胞与维管束鞘细胞之间形成“代谢隔室”，是空间分离的结构基础。C₄ 植物叶脉间距小、叶脉密度高，有利于四碳二羧酸的快速往返运输。"},{"id":"15.4","t":"CAM 植物的代谢特点","s":3,"c":"15. C₄ 途径与 CAM 植物","x":"景天酸代谢（CAM）植物在时间上分离两个步骤：夜间气孔开放，PEPC固定 CO₂ 生成草酰乙酸并还原为苹果酸，储存于液泡（液泡 pH 可降至 3 左右）；白天气孔关闭，苹果酸运出液泡脱羧释放 CO₂ 供卡尔文循环使用，同时PEPC 活性被抑制。因此 CAM 植物白天关闭气孔以减少水分散失，蒸腾比仅18 至 125 mol 水/mol CO₂，是三类植物中水分利用效率最高的。CAM 植物光合速率低（0.6 至 2.5 µmol CO₂·m⁻²·s⁻¹），生长缓慢，常见于干旱、盐碱与附生环境（仙人掌、凤梨、景天、菠萝）。"},{"id":"15.5","t":"兼性与诱导型 CAM","s":2,"c":"15. C₄ 途径与 CAM 植物","x":"部分植物可根据水分状况在 C₃ 与 CAM 之间切换，称兼性 CAM 或诱导型CAM，如冰叶日中花（冰叶菊）、落地生根。干旱时 CAM 特征增强，水分充足时以 C₃ 方式光合，这种可塑性是植物适应多变环境的典型例证，也提示光合类型并非绝对固定。"},{"id":"15.6","t":"三类植物的系统比较","s":3,"c":"15. C₄ 途径与 CAM 植物","x":"C₃ 植物占多数（约 85% 的物种），CO₂ 补偿点高（30 至 70 mg/L），光呼吸明显，蒸腾系数大；C₄ 植物约占被子植物的 3%，多分布于热带亚热带高温强光环境，CO₂ 补偿点低于 10 mg/L，几乎无光呼吸，光合速率高，蒸腾系数小；CAM 植物分布于极端干旱环境，夜间固定 CO₂，白天关闭气孔，CO₂补偿点在暗中低于 5 mg/L，光合速率最低但水分利用效率最高。项目初次固定产物C₃ 植物C₄ 植物CAM 植物3-磷酸甘油酸Rubisco草酰乙酸等四碳酸草酰乙酸、苹果酸PEP 羧化酶 + Rubisco PEP 羧化酶 + Rubisco空间分离（花环结构）时间分离（昼夜）CO₂ 补偿点无分离30~70 mg/L暗中小于 5 mg/L每分子 CO₂ 耗 ATP小于 10 mg/L光合速率10~25 25~50 5 以上0.6~2.5典型植物小麦、水稻、大豆玉米、甘蔗、高粱仙人掌、菠萝关键酶分离方式"},{"id":"15.7","t":"C₄ 与 CAM 的生态与进化意义","s":2,"c":"15. C₄ 途径与 CAM 植物","x":"C₄ 途径在低 CO₂ 浓度、高温强光、干旱环境中具有优势，地质历史上 C₄植物在新生代晚期随大气 CO₂ 下降而扩张，形成了热带草原。CAM 途径在极端干旱中优势最大，但以低生长速率与低光合速率为代价。两者的共同点是“在 Rubisco 之前用 PEPC 先把 CO₂ 浓缩”，因此只要环境使光呼吸的代价增大，浓缩机制就会被自然选择保留。"},{"id":"16.1","t":"光强与光饱和点、光补偿点","s":3,"c":"16. 影响光合作用的因素","x":"光合速率随光强增加而上升，在低光区近似线性（受光反应限制），随后增速趋缓并达到光饱和点，再增加光强不再提高甚至引起光抑制。光补偿点是光合速率与呼吸速率相等时的光强，此时净光合为零。阳生植物光补偿点约 9至 18 µmol·m⁻²·s⁻¹、光饱和点 360 至 450 µmol·m⁻²·s⁻¹ 或更高；阴生植物光补偿点低于 9、光饱和点 90 至 180 µmol·m⁻²·s⁻¹。注意单位：光合有效辐射常用 µmol 光子·m⁻²·s⁻¹，与 W·m⁻² 不能直接等同。"},{"id":"16.2","t":"CO₂ 浓度与 CO₂ 补偿点","s":3,"c":"16. 影响光合作用的因素","x":"CO₂ 是羧化反应的底物，其浓度在光饱和条件下成为限制因素。CO₂ 补偿点是光合速率等于呼吸速率时的 CO₂ 浓度，C₃ 植物 30 至 70 mg/L，C₄ 植物低于 10 mg/L，CAM 植物暗中低于 5 mg/L。C₄ 植物 CO₂ 补偿点低的原因正是 PEPC 的高亲和力与“CO₂ 泵”。设施栽培中人工增施 CO₂ 至 800 至 1000µL/L 可显著增产，但过高会抑制气孔开张与呼吸。"},{"id":"16.3","t":"温度对光合的影响","s":3,"c":"16. 影响光合作用的因素","x":"光合作用有三基点温度：最低温、最适温、最高温。C₃ 植物最适温约 15至 25 ℃、C₄ 植物约 30 至 40 ℃，这与 PEPC 的热稳定性及 C₄ 的 CO₂ 浓缩能力有关。高温使 Rubisco 对 CO₂ 亲和力下降、光呼吸增强、膜脂流动性过大、PSⅡ 受损；低温使酶活性下降、膜脂相变、磷酸转运受阻。昼夜温差大利于积累，因为白天高温利于光合、夜间低温减少呼吸消耗。"},{"id":"16.4","t":"水分对光合的影响","s":3,"c":"16. 影响光合作用的因素","x":"水分亏缺通过三条途径抑制光合：（1）气孔限制，气孔关闭使 CO₂ 供应不足，胞间 CO₂ 浓度下降；（2）非气孔限制，叶肉细胞光合能力下降、Rubisco 活性降低、ATP 供应不足；（3）叶片扩展与面积减少、叶绿素降解。判断以哪种限制为主，可用胞间 CO₂ 浓度（Ci）变化：Ci 下降说明气孔限制为主，Ci 升高而光合下降说明非气孔限制为主。水分过多则根系缺氧、气孔关闭、光合下降。"},{"id":"16.5","t":"矿质营养对光合的影响","s":2,"c":"16. 影响光合作用的因素","x":"氮是 Rubisco 与叶绿素的主要成分，叶片氮含量与光合能力高度正相关，施氮可提高光合速率与叶面积；磷参与 ATP 与糖的运输，缺磷时光合下降、糖运输受阻；钾调节气孔开闭与光合产物运输；镁是叶绿素中心原子；铁、锰、铜参与电子传递与水的光解；硼影响糖的运输。矿质缺乏往往先降低叶片扩展与叶绿素含量，再影响光化学反应。"},{"id":"16.6","t":"内部因素对光合的影响","s":2,"c":"16. 影响光合作用的因素","x":"（1）叶龄，幼叶光合能力低（叶绿体发育不完全），展开后迅速上升，成熟叶最高，衰老时下降；（2）叶位与叶面积指数，群体叶面积指数过大时下部叶片受光不足，净光合反而下降；（3）源库关系，去除库器官（如摘果）会导致叶片光合产物积累而反馈抑制光合；（4）气孔密度与叶片厚度、比叶重，阳生叶比叶重高、光合能力强。"},{"id":"16.7","t":"光合速率的测定方法","s":2,"c":"16. 影响光合作用的因素","x":"（1）气体交换法，用红外 CO₂ 分析仪测定叶片进出气流的 CO₂ 差值，可同时测蒸腾与气孔导度，是标准方法；（2）氧电极法，测定离体叶绿体或细胞的放氧速率；（3）半叶法，对称叶片一半遮光，比较干重增加，经典但粗糙；（4）同位素法，用 ¹⁴ CO₂ 标记后测放射性；（5）叶绿素荧光法，快速无损，用于估算电子传递速率与胁迫程度。"},{"id":"17.1","t":"光能利用率的概念","s":3,"c":"17. 光合效率与作物产量","x":"光能利用率指光合作用贮存的化学能占投射到单位土地面积上太阳辐射能的比例。理论上，扣除反射、透射、非光合色素吸收与非光合有效波长后，最大理论值约 5% 至 6%；实际农田生育期光能利用率一般仅 1% 至 2%，高产田可达 3% 以上。提高光能利用率是作物产量提升的根本途径，也是“光合作用与产量”这一主题的核心。"},{"id":"17.2","t":"光合性能的五个方面","s":3,"c":"17. 光合效率与作物产量","x":"作物产量取决于光合性能的五个方面：（1）光合面积，主要是叶面积及其动态；（2）光合时间，即光合期长短与叶片寿命；（3）光合速率，即单位叶面积同化能力；（4）呼吸消耗，包括光呼吸与暗呼吸；（5）光合产物的分配，即经济系数。这五项的乘积决定经济产量，因此育种与栽培都要围绕“扩源、畅流、增库”展开。"},{"id":"17.3","t":"生物产量与经济系数","s":3,"c":"17. 光合效率与作物产量","x":"生物产量是作物一生积累的干物质总量，经济产量是其中有经济价值的部分，经济系数（收获指数）= 经济产量 / 生物产量。禾谷类经济系数一般为 0.3至 0.5，矮秆育种使经济系数从 0.3 提高到 0.5，是“绿色革命”增产的重要机制。进一步增产需同时提高生物产量与经济系数，前者依赖光合能力与生育期，后者依赖物质向籽粒的分配。"},{"id":"17.4","t":"提高光能利用率的途径","s":3,"c":"17. 光合效率与作物产量","x":"（1）选育高光效品种，理想株型、叶片直立、光合能力强、光呼吸低；（2）合理密植与冠层优化，使叶面积指数在生育中期达到 4 至 6 并及时“上挺下展”，减少漏光；（3）改善田间 CO₂ 供应，增施有机肥、通风、设施内CO₂ 施肥；（4）延长光合期，适时早播、防止早衰、保护后期功能叶；（5）减少呼吸消耗与光呼吸损失；（6）防治病虫草害与逆境，减少光合面积损失。"},{"id":"17.5","t":"冠层结构与群体光合","s":2,"c":"17. 光合效率与作物产量","x":"群体光合不是单叶光合的简单相加。冠层内光强自上而下按比尔定律衰减，叶面积指数越大衰减越快，下层叶片可能低于光补偿点而成为净消耗者。理想冠层要求上层叶片直立、透光好，中下层叶片平展、受光均匀，并且“源”（功能叶）与“库”（籽粒）在时间上匹配。去叶、剪半叶与遮光实验常用于研究源库限制。"},{"id":"17.6","t":"光合作用的改良前景","s":2,"c":"17. 光合效率与作物产量","x":"（1）改造 Rubisco，提高其催化速率与对 CO₂ 的特异性；（2）在 C₃ 作物中构建 C₄ 途径（C₄ 水稻计划）；（3）引入光呼吸旁路，减少碳与能量的损失；（4）优化叶绿素含量与冠层光分布，让更多光到达下层叶片；（5）改良RuBP 再生与三碳糖磷酸转运能力。这些方向都基于本篇的机制知识，是竞赛中“综合运用”类题目的常见落点。第四篇 呼吸作用与同化物运输"},{"id":"18.1","t":"呼吸作用的概念与类型","s":3,"c":"18. 呼吸作用的途径","x":"呼吸作用是指细胞内的有机物在酶的催化下逐步氧化分解、释放能量并生成 ATP 的过程。分有氧呼吸与无氧呼吸：有氧呼吸把糖彻底氧化为 CO₂ 与H₂O，释放能量多（1 mol 葡萄糖彻底氧化约释放 2870 kJ，其中约 40% 贮存于 ATP）；无氧呼吸产生乙醇与 CO₂ 或乳酸，释放能量少（约 100 kJ）。呼吸作用的生理意义是提供能量、提供合成代谢所需的中间产物（有机酸、氨基酸碳架）以及作为物质转化的枢纽。"},{"id":"18.2","t":"糖酵解","s":3,"c":"18. 呼吸作用的途径","x":"糖酵解在细胞质中进行，1 分子葡萄糖经 10 步反应生成 2 分子丙酮酸，净得 2 个 ATP 与 2 个 NADH。关键调节酶是己糖激酶、磷酸果糖激酶（PFK）与丙酮酸激酶，其中 PFK 是最重要的限速酶，受 ATP、柠檬酸抑制，受AMP、果糖-2,6-二磷酸激活。植物糖酵解的特殊之处在于存在不依赖 UDP 的途径与焦磷酸依赖性磷酸果糖激酶（PFP），使反应在低 Pi 条件下仍能进行。"},{"id":"18.3","t":"三羧酸循环","s":3,"c":"18. 呼吸作用的途径","x":"丙酮酸经丙酮酸脱氢酶复合体氧化脱羧生成乙酰 CoA（产生 1 个 NADH与 1 个 CO₂），乙酰 CoA 与草酰乙酸缩合成柠檬酸进入三羧酸循环（TCA 循环、柠檬酸循环、Krebs 循环）。每轮循环产生 3 个 NADH、1 个 FADH₂、1个 GTP（植物中为 ATP）并释放 2 个 CO₂，同时把草酰乙酸再生。循环的中间产物（α-酮戊二酸、草酰乙酸、琥珀酸）是氨基酸与次生物质合成的碳架，因此 TCA 循环既是“分解途径”也是“两用代谢途径”。"},{"id":"18.4","t":"电子传递与氧化磷酸化","s":3,"c":"18. 呼吸作用的途径","x":"NADH 与 FADH₂ 把电子交给线粒体内膜上的呼吸链：复合体Ⅰ（NADH脱氢酶）、复合体Ⅱ（琥珀酸脱氢酶）、泛醌（UQ）、复合体Ⅲ（细胞色素bc₁ 复合体）、细胞色素 c、复合体Ⅳ（细胞色素氧化酶），最终把电子交给O₂ 生成 H₂O。电子传递过程中 H⁺ 被泵到膜间隙，形成质子动力势，H⁺ 经ATP 合酶回流驱动 ADP 磷酸化生成 ATP。植物呼吸链的 P/O 比约为 2.5（NADH）与 1.5（FADH₂）。"},{"id":"18.5","t":"交替途径（抗氰呼吸）","s":3,"c":"18. 呼吸作用的途径","x":"植物线粒体内膜上存在交替氧化酶（AOX），可从泛醌直接接受电子交给O₂，绕过复合体Ⅲ与Ⅳ，因此不被氰化物（CN⁻）抑制，称抗氰呼吸。其特点是电子传递与 ATP 合成不偶联（只生成 1 个 ATP 或完全不生成），能量以热的形式释放。抗氰呼吸在植物中广泛存在，在雌花开放期（天南星科植物可升温至 40 ℃ 以上）、果实成熟、种子萌发、抗病与低温胁迫时增强，意义在于产热（吸引传粉昆虫、促进挥发物扩散）、消耗多余还原力、维持碳代谢运转与抵御氧化胁迫。"},{"id":"18.6","t":"戊糖磷酸途径","s":3,"c":"18. 呼吸作用的途径","x":"戊糖磷酸途径（PPP、HMP 途径）在细胞质与质体中运行，6-磷酸葡萄糖经氧化脱羧生成 5-磷酸核酮糖，产生 2 个 NADPH 与 1 个 CO₂。其意义是为合成代谢提供 NADPH（脂肪酸、甾醇、次生物质合成所需）与核糖（核苷酸合成），并与糖酵解通过转酮、转醛反应相连。植物在抗病、受伤与分化时 PPP活性显著增强，因为需要大量还原力与碳架。"},{"id":"18.7","t":"其他末端氧化酶系统","s":2,"c":"18. 呼吸作用的途径","x":"除细胞色素氧化酶外，植物还有多条末端氧化途径：（1）交替氧化酶；（2）多酚氧化酶，氧化酚类物质，与褐变、抗病有关；（3）抗坏血酸氧化酶；（4）乙醇酸氧化酶（光呼吸）；（5）过氧化物酶。多条途径并存使植物在不同环境与发育阶段都能维持电子传递，也解释了为什么氰化物对植物毒性远低于动物。"},{"id":"18.8","t":"无氧呼吸与发酵","s":3,"c":"18. 呼吸作用的途径","x":"缺氧时丙酮酸脱羧生成乙醛，再由乙醇脱氢酶还原为乙醇（酒精发酵），或由乳酸脱氢酶还原为乳酸。发酵只产生少量 ATP，且乙醇与乳酸积累会造成细胞毒害，故涝渍条件下根系受害主要来自“能量危机 + 有毒产物 + 缺氧”。植物耐涝品种往往具有较高的乙醇脱氢酶活性、较强的糖酵解通量以及发达的通气组织。途径发生部位产物特点糖酵解细胞质丙酮酸、ATP、NADH有氧无氧均可进行三羧酸循环线粒体基质NADH、FADH₂、CO₂、ATP需氧，提供碳架氧化磷酸化线粒体内膜ATP、H₂O与电子传递偶联交替途径线粒体内膜热、少量 ATP抗氰，不偶联戊糖磷酸途径细胞质、质体NADPH、核糖、CO₂供还原力与碳架"},{"id":"19.1","t":"呼吸商的概念","s":3,"c":"19. 呼吸商与影响呼吸的因素","x":"呼吸商（RQ）指单位时间内释放的 CO₂ 与吸收的 O₂ 的摩尔比（体积比），反映呼吸底物的种类。以糖为底物完全氧化时 RQ = 1；以脂肪为底物时RQ 约为 0.7（因脂肪含氧少、需更多 O₂）；以蛋白质为底物时约 0.8；以有机酸（如苹果酸、草酸）为底物时 RQ 大于 1（因其已高度含氧，甚至可释放CO₂ 而不耗 O₂）。测定 RQ 可判断呼吸底物的性质以及是否发生无氧呼吸（RQ 大于 1 也可能因发酵）。"},{"id":"19.2","t":"不同器官与发育时期的呼吸强度","s":3,"c":"19. 呼吸商与影响呼吸的因素","x":"呼吸强度（以单位鲜重每小时释放的 CO₂ 量表示）在不同器官差异极大：幼嫩、生长旺盛的组织（分生区、幼叶、萌发种子）呼吸强；休眠种子、老熟组织、干燥器官呼吸弱。同一器官中，花、幼果的呼吸强度高于叶、根、茎。这种差异与蛋白质合成、细胞分裂的活跃程度一致，说明呼吸强度是代谢活性的指标。"},{"id":"19.3","t":"内部因素对呼吸的影响","s":2,"c":"19. 呼吸商与影响呼吸的因素","x":"（1）年龄与发育阶段，幼嫩组织呼吸强、衰老组织减弱，但成熟果实会出现呼吸跃变；（2）器官类型与结构，含分生组织多的器官呼吸强；（3）含水量，干种子含水量低、呼吸极弱，含水量一旦超过临界值（淀粉种子约 14% 至15%）呼吸强度陡增，这是种子安全贮藏的关键；（4）伤害与机械损伤，切割、摩擦使呼吸显著增强（伤呼吸），与修复与防御有关。"},{"id":"19.4","t":"外界因素对呼吸的影响","s":3,"c":"19. 呼吸商与影响呼吸的因素","x":"（1）温度，呼吸随温度升高而增强，最适温一般 25 至 35 ℃，超过 40 ℃后迅速下降（酶变性、膜受损）；温度系数 Q₁₀ 在 0 至 30 ℃ 内约为 2，故低温贮藏可显著降低呼吸消耗。（2）O₂ 浓度，存在“氧饱和点”，通常大气氧浓度已接近饱和；氧浓度低于 5% 至 10% 时呼吸受抑，生产上利用低氧（2%至 5%）贮藏果蔬，但过低会导致无氧呼吸产生异味。（3）CO₂ 浓度，超过5% 至 10% 抑制呼吸，可用于气调贮藏。（4）水分，干种子呼吸随含水量升高而陡增。"},{"id":"19.5","t":"呼吸作用与抗病性","s":3,"c":"19. 呼吸商与影响呼吸的因素","x":"植物受病原物侵染后呼吸增强（呼吸爆发），意义在于：（1）提供合成植保素、木质素、富含羟脯氨酸糖蛋白的能量与碳架；（2）PPP 途径增强，提供 NADPH 用于还原与合成；（3）产生大量活性氧，直接毒害病原物并加固细胞壁；（4）交替途径增强，耗散过多还原力、减少活性氧产生。因此呼吸增强既是受害的表现，也是抗病的机制。"},{"id":"19.6","t":"呼吸跃变与果实贮藏","s":3,"c":"19. 呼吸商与影响呼吸的因素","x":"呼吸跃变是果实成熟过程中呼吸强度先急剧上升后下降的现象。具呼吸跃变的果实称跃变型果实（苹果、香蕉、番茄、芒果、鳄梨），其成熟受乙烯触发，成熟后迅速软化衰老；不具跃变的称非跃变型果实（柑橘、葡萄、草莓、菠萝），成熟过程平缓。贮藏策略也因此不同：跃变型果实应在呼吸跃变前采收、低温并配合乙烯吸收剂或 1-MCP 处理；非跃变型果实采收成熟度可更高。"},{"id":"19.7","t":"呼吸作用的调控","s":2,"c":"19. 呼吸商与影响呼吸的因素","x":"呼吸作用受到多层次的调控：（1）底物供应，糖的可用性通过己糖激酶与PFP 影响通量；（2）关键酶调节，PFK 受 ATP/AMP 比、柠檬酸与果糖-2,6二磷酸调节，丙酮酸脱氢酶复合体受乙酰 CoA 与 NADH 反馈抑制；（3）腺苷酸能荷调节，能荷 = (ATP + 0.5ADP) / (ATP + ADP + AMP)，能荷低则呼吸加速；（4）氧化磷酸化与交替途径的电子分流；（5）基因表达水平调节，如 AOX 基因受冷害、胁迫诱导。"},{"id":"19.8","t":"呼吸作用在农业生产中的应用","s":3,"c":"19. 呼吸商与影响呼吸的因素","x":"（1）种子贮藏，种子必须干燥（淀粉种子含水量低于 13%）、低温、密闭，防止发热霉变；（2）果蔬保鲜，低温、气调（低 O₂ 高 CO₂）、乙烯吸收、1-MCP 处理、涂膜，都以降低呼吸为手段；（3）种子播前的浸种催芽，通过提供水分与适宜温度促进呼吸与物质动员；（4）中耕松土、排水防涝，改善土壤通气以维持根系有氧呼吸；（5）抗病育种与诱导抗性，利用呼吸爆发的防御功能。"},{"id":"20.1","t":"运输的途径与方向","s":3,"c":"20. 同化物的运输与分配","x":"同化物（主要是蔗糖，还有氨基酸、有机酸、激素与部分矿质）在韧皮部中运输。环割实验证明：环割树皮后切口上方膨大、下方饥饿，说明同化物经韧皮部向下运输；同位素示踪显示运输是双向的，但同一筛管分子中通常只有一个方向，方向由源库关系决定。韧皮部运输速度为 0.2 至 2 m/h，远慢于木质部（1 至 45 m/h）。"},{"id":"20.2","t":"韧皮部的结构","s":3,"c":"20. 同化物的运输与分配","x":"韧皮部由筛管分子、伴胞、韧皮薄壁细胞与韧皮纤维组成。筛管分子成熟后无细胞核与液泡、细胞质稀薄、具筛板与筛孔，靠伴胞提供蛋白与 ATP 维持生命活动；筛板上的筛孔可被胼胝质堵塞，受伤时防止内容物外流。伴胞与筛管分子之间有大量胞间连丝，形成“筛管—伴胞复合体”，是装载与卸出的功能单位。P 蛋白（韧皮蛋白）可封堵损伤部位。"},{"id":"20.3","t":"韧皮部装载","s":3,"c":"20. 同化物的运输与分配","x":"蔗糖从叶肉细胞进入筛管—伴胞复合体有两条途径：（1）共质体途径，经胞间连丝直接进入，见于部分植物（如南瓜），速度快但无法形成浓度梯度；（2）质外体途径，蔗糖先经转运蛋白出叶肉细胞进入质外体，再由蔗糖—H⁺同向转运体（SUT/SUC）借质子动力势主动进入伴胞，可在筛管中形成高浓度蔗糖（可达 0.8 至 1.0 mol/L）。质外体装载是多数作物的主要方式，也是“畅流”调控的关键点。"},{"id":"20.4","t":"韧皮部卸出与库细胞利用","s":2,"c":"20. 同化物的运输与分配","x":"同化物从筛管进入库细胞同样有共质体与质外体两种方式：库器官（如幼叶、根、块茎）多为共质体卸出；种子（如小麦、玉米籽粒）因与母体无胞间连丝连接，必须经质外体卸出，再由胚乳或子叶细胞主动吸收。蔗糖进入库细胞后可转化为淀粉（块茎、籽粒）、蔗糖（甘蔗茎）或用于呼吸与生长（幼叶、根尖）。卸出能力决定“库强”，是限制产量的重要因素。"},{"id":"20.5","t":"压力流学说","s":3,"c":"20. 同化物的运输与分配","x":"Münch 提出的压力流（压力流动）学说解释韧皮部运输：（1）源端叶肉细胞把蔗糖主动装入筛管，使筛管水势下降，水分从木质部渗入，源端膨压升高；（2）库端蔗糖被卸出或被转化，筛管水势升高，水分流出，膨压降低；（3）源库之间的膨压差驱动筛管内的集流，使同化物随液流一并移动。该学说得到三点支持：蚜虫口针刺入筛管时汁液自动流出（正压力）、韧皮部汁液蔗糖浓度远高于周围组织、源库之间可测得膨压差；其局限在于无法解释双向运输与高速运输。"},{"id":"20.6","t":"源、库、流的关系","s":3,"c":"20. 同化物的运输与分配","x":"源是光合产物的供应者（成熟叶），库是消耗或贮存同化物的器官（根、茎、果实、幼叶、种子），流是连接二者的韧皮部运输系统。源库关系有三种情形：源限制（源不足，如叶面积小、早衰）、库限制（库容量不足，如籽粒少）、运输限制（流的通畅性差）。去叶减少源、去果减少库，都会引起光合速率的反馈变化，说明源库相互调节。"},{"id":"20.7","t":"同化物分配的规律","s":3,"c":"20. 同化物的运输与分配","x":"（1）优先供应生长中心，即当时生长最旺盛的器官（分蘖期供分蘖、开花期供花、灌浆期供籽粒）；（2）就近供应，同一方位的叶片优先供应同侧的芽、果（纵向同侧运输）；（3）按比例分配与功能优先，受伤或受害部位可改变分配方向；（4）可逆性，贮藏器官中的物质可在需要时重新动员（如小麦灌浆期茎秆贮藏物质向籽粒转移）。理解这些规律可解释整枝、摘心、疏花疏果的增产原理。"},{"id":"20.8","t":"影响同化物运输的因素","s":2,"c":"20. 同化物的运输与分配","x":"（1）温度，影响酶活性与黏度，过高过低都降低运输速率；（2）光照与光合速率，决定源的供应能力；（3）水分与矿质，特别是磷、钾、硼，缺硼时糖运输受阻（形成“花而不实”）；（4）激素，生长素、赤霉素、细胞分裂素可提高库强、促进同化物向处理部位运输（如涂抹 GA 于果实可增加其“吸引力”）；（5）源库比例与韧皮部健康状况。"},{"id":"21.1","t":"种子的贮藏物质","s":3,"c":"21. 贮藏物质代谢","x":"种子贮藏物质主要有淀粉（禾谷类，占干重 60% 至 70%）、蛋白质（豆类，20% 至 40%）、脂肪（油料作物，30% 至 50%），此外还有植酸（磷的贮藏形式）、半纤维素（胚乳细胞壁，如椰枣、柿）与灰分。贮藏物质以不溶或高度浓缩的形式存在，既节省空间又降低渗透压，避免胚细胞过度吸水。"},{"id":"21.2","t":"淀粉的合成与降解","s":3,"c":"21. 贮藏物质代谢","x":"合成：ADP-葡萄糖焦磷酸化酶（AGPase）把葡萄糖-1-磷酸转为 ADP-葡萄糖，再由淀粉合酶加到淀粉引物上，分支酶引入 α-1,6 分支。降解：α-淀粉酶随机水解 α-1,4 键，β-淀粉酶从非还原端切下麦芽糖，脱支酶水解分支点，最终生成麦芽糖与葡萄糖供胚利用。萌发种子中 α-淀粉酶由糊粉层在 GA 诱导下合成并分泌到胚乳，是“GA 诱导水解酶”的经典事例。"},{"id":"21.3","t":"脂肪的转化","s":3,"c":"21. 贮藏物质代谢","x":"油料种子萌发时，脂肪在脂肪酶作用下水解为甘油与脂肪酸，脂肪酸经 β氧化生成乙酰 CoA，乙酰 CoA 进入乙醛酸循环（存在于乙醛酸循环体）生成琥珀酸，再经 TCA 循环生成苹果酸，运出后经糖异生转为蔗糖供胚生长。乙醛酸循环的关键酶是异柠檬酸裂解酶与苹果酸合酶，它使乙酰 CoA 净生成四碳二羧酸而不释放 CO₂，因此脂肪可以净转化为糖，这是油料种子萌发期 RQ 低于1 的原因之一。"},{"id":"21.4","t":"蛋白质的降解与 mobilization","s":2,"c":"21. 贮藏物质代谢","x":"种子萌发时贮藏蛋白在蛋白酶作用下水解为氨基酸，运至胚用于合成新蛋白。豆科种子的贮藏蛋白以球蛋白为主，其中含大量酰胺态氮，需经天冬酰胺酶与谷氨酰胺酶转化后运输。蛋白质降解产生的氮素运输形式主要是天冬酰胺与谷氨酰胺，因为其含氮量高、毒性低、便于运输。"},{"id":"21.5","t":"种子萌发时的物质转化顺序","s":3,"c":"21. 贮藏物质代谢","x":"萌发早期以吸水与呼吸启动为主，随后淀粉、脂肪、蛋白质依次被动员；禾谷类种子以淀粉动员为主，油料种子以脂肪动员为主，豆类以蛋白质动员为主。动员产生的蔗糖与氨基酸运往胚轴与胚根，支持细胞分裂与伸长。干物质总量在萌发初期并不增加（甚至因呼吸消耗而略降），直到幼苗转绿开始光合才净增加，这是“萌发不是生长而是转化”的关键判断。"},{"id":"21.6","t":"果实成熟时的物质变化","s":3,"c":"21. 贮藏物质代谢","x":"（1）淀粉水解为可溶性糖，甜度上升；（2）有机酸（苹果酸、柠檬酸）减少或被转化，酸度下降；（3）单宁与涩味物质减少，果胶被果胶酶降解致果实软化；（4）色素变化，叶绿素降解、花色素苷与类胡萝卜素积累；（5）芳香物质生成；（6）乙烯大量生成，呼吸跃变出现。这些变化共同构成“色、香、味、软”的成熟标志。"},{"id":"21.7","t":"贮藏器官的次生生长与物质积累","s":2,"c":"21. 贮藏物质代谢","x":"块茎（马铃薯）、块根（甘薯）、鳞茎（洋葱）、球茎等贮藏器官在发育后期成为强“库”，大量同化物输入并以淀粉或蔗糖形式贮存。马铃薯块茎形成受短日照与低温诱导，赤霉素抑制块茎形成而细胞分裂素与 ABA 促进；洋葱鳞茎形成受长日照诱导。掌握“环境信号—激素—器官形成”的链条，可解释南北引种时的适应性问题。第五篇 植物生长物质"},{"id":"22.1","t":"生长素的发现史","s":3,"c":"22. 生长素类","x":"1880 年达尔文父子观察到金丝雀虉草胚芽鞘在单侧光下向光弯曲，遮住尖端则不弯曲，推测尖端产生某种“影响”向下传递；1913 年 Boysen-Jensen用明胶与云母片证明该物质可扩散；1928 年 Went 把切下的胚芽鞘尖端放在琼脂块上，再将琼脂块偏置于去尖端胚芽鞘一侧，引起弯曲，并建立燕麦弯曲定量测定法；1934 年 Kögl 等从人尿与玉米油中分离出吲哚乙酸（IAA）。这段历史是“观察—假说—分离—鉴定”研究范式的经典范例。"},{"id":"22.2","t":"生长素的存在形式与分布","s":3,"c":"22. 生长素类","x":"天然生长素主要是 IAA，此外还有苯乙酸、吲哚丁酸（IBA）等。IAA 在植物体内以游离态（活性）与结合态（与糖、氨基酸、蛋白质结合，为贮藏或钝化形式）两种形式存在，结合态可水解释放。生长素在生长旺盛的部位含量高，如胚芽鞘尖端、幼叶、发育中的种子与果实；一般侧生器官含量高于顶端，但仍表现顶端优势，说明“含量”不等于“效应”，还与运输与敏感性有关。"},{"id":"22.3","t":"极性运输","s":3,"c":"22. 生长素类","x":"生长素在细胞间的运输具有极性，只能从形态学上端向下端运输（茎尖→基部），不能逆转，速度约 5 至 20 mm/h，是逆浓度梯度的主动运输，需能量与氧气。分子机制是“化学渗透模型”：IAA 分子（pKa 4.8）在酸性细胞壁中部分以未解离形式存在，可自由穿过膜进入细胞；在细胞质（pH 约 7）中解离为阴离子 IAA⁻，不能自由出膜，必须由输出载体 PIN 蛋白定向运出。输入载体 AUX1 负责把 IAA⁻ 输入细胞，PIN 在细胞基部的极性定位决定了运输方向。"},{"id":"22.4","t":"生长素的合成与降解","s":2,"c":"22. 生长素类","x":"IAA 合成有依赖色氨酸与不依赖色氨酸两条途径，依赖色氨酸途径又分四条支路（IPA 途径、TAM 途径、IAM 途径、吲哚乙醛肟途径），其中 IPA 途径是拟南芥中的主要途径。降解方式包括与氨基酸结合钝化、氧化脱羧（过氧化物酶催化）与光氧化。IAA 氧化酶（DAO）与 GH3 基因家族参与维持生长素的稳态，生长素过量时 GH3 被诱导，形成负反馈。"},{"id":"22.5","t":"生长素的双重效应","s":3,"c":"22. 生长素类","x":"生长素对生长的影响具有浓度两重性：低浓度促进生长，高浓度抑制生长甚至杀死植物；不同器官对生长素的敏感程度不同，根最敏感（最适约 10⁻¹⁰mol/L）、芽次之（约 10⁻⁸）、茎最不敏感（约 10⁻⁴）。同一浓度对不同器官可产生相反效果，这一“敏感性差异”是顶端优势、根的向重力性与除草剂选择性的共同基础。双重效应的机制涉及高浓度诱导乙烯生成与细胞壁松弛失控。"},{"id":"22.6","t":"生长素的主要生理作用","s":3,"c":"22. 生长素类","x":"（1）促进细胞伸长（不是促进细胞分裂），引起胚芽鞘与茎的伸长；（2）维持顶端优势，抑制侧芽生长；（3）促进插条生根，尤其与 IBA 配合使用；（4）促进果实发育与单性结实，子房中的生长素来自发育中的种子；（5）参与向光性与向重力性反应；（6）促进维管束分化与形成层活动；（7）高浓度诱导乙烯产生、促进脱落。"},{"id":"22.7","t":"生长素受体与信号","s":3,"c":"22. 生长素类","x":"受体 TIR1/AFB 是核内 SCF 型 E3 泛素连接酶的 F-box 亚基，本身不是激酶。生长素作为“分子胶水”嵌入 TIR1 与 Aux/IAA 之间的界面，增强两者亲和力，使 Aux/IAA 被泛素化并经 26S 蛋白酶体降解，从而释放 ARF 转录因子，激活早期响应基因（Aux/IAA、GH3、SAUR）。SAUR 通过抑制 PP2C型磷酸酶提高质膜 H⁺-ATP 酶活性，导致细胞壁酸化与酸化生长，把“信号”与“细胞伸长”连接起来。"},{"id":"22.8","t":"生长素在农业上的应用","s":3,"c":"22. 生长素类","x":"（1）促进扦插生根，用 NAA 或 IBA 处理插穗基部；（2）防止落花落果，用低浓度 2,4-D 或防落素喷施番茄；（3）获得无子果实，用 IAA 或 GA处理未受精子房；（4）疏花疏果，用高浓度萘乙酸在盛花期处理；（5）作为除草剂，2,4-D 与二甲四氯选择性地杀死双子叶杂草（浓度过高干扰核酸与蛋白质代谢）；（6）组织培养中与细胞分裂素配合诱导根与芽的分化。项目方向生长素（IAA）运输其他激素运输多为非极性，随维管束速度极性，形态学上端到下端5~20 mm/h机制化学渗透模型，PIN 载体韧皮部或木质部流动能量需 ATP 与 O₂部分需能较快，随蒸腾流或韧皮部"},{"id":"23.1","t":"赤霉素的发现与结构","s":3,"c":"23. 赤霉素类","x":"赤霉素因引起水稻“恶苗病”植株徒长而被发现，1935 年薮田贞治郎从稻恶苗病菌中分离出赤霉素结晶，1958 年确定其化学结构。赤霉素是含 19 或 20个碳的双萜酸，目前已发现 130 余种，编号为 GA₁、GA₃……，其中 GA₃（赤霉酸）活性最高、应用最广。赤霉素的基本结构是 ent-赤霉素烷环，活性形式需要 C-3 位的羟基与 C-6 位的羧基、C-19 位的内酯。"},{"id":"23.2","t":"赤霉素的合成、运输与钝化","s":3,"c":"23. 赤霉素类","x":"GA 在幼芽、幼根、未成熟种子与胚中合成，前体是牻牛儿牻牛儿基焦磷酸（GGPP），经内根—贝壳杉烯、内根—贝壳杉烯酸等一系列步骤生成GA₁₂，再经羟基化生成活性形式。GA 的运输不具极性，可经木质部与韧皮部双向运输。钝化方式包括 2β-羟基化（生成无活性 GA₂₉ 等）、与糖结合形成糖苷/糖酯（贮藏或运输形式）以及甲基化。GA 合成受发育阶段与环境（长日照、低温）调节。"},{"id":"23.3","t":"赤霉素促进茎伸长的机制","s":3,"c":"23. 赤霉素类","x":"GA 促进细胞伸长而非细胞分裂，其机制包括：（1）GA 使 DELLA 蛋白降解，解除对 PIF 转录因子与细胞壁松弛基因的抑制；（2）提高细胞壁伸展性，诱导扩张蛋白与木葡聚糖内糖基转移酶表达；（3）促进生长素运输与合成，二者协同；（4）提高质膜 H⁺-ATP 酶活性，使细胞壁酸化。经典证据是“矮生豌豆”型突变体（GA 合成缺陷）外施 GA 后恢复正常高度，而 GA 不敏感突变体（gid1）无响应。"},{"id":"23.4","t":"赤霉素诱导 α-淀粉酶的形成","s":3,"c":"23. 赤霉素类","x":"大麦种子萌发时，胚产生 GA 并运至糊粉层，GA 与糊粉层细胞受体 GID1结合，使 DELLA 降解，解除对 GAMYB 转录因子的抑制，GAMYB 激活 α-淀粉酶基因表达，酶分泌到胚乳水解淀粉，供胚利用。这是“激素—基因表达—酶分泌—物质动员”的完整链条，也是啤酒工业制麦芽（用 GA 促进糖化）的原理。注意 α-淀粉酶由糊粉层产生而非胚乳细胞。"},{"id":"23.5","t":"赤霉素与种子萌发、休眠","s":3,"c":"23. 赤霉素类","x":"GA 能打破种子休眠、促进萌发，对需光种子可替代光照，对需要低温层积的种子可部分替代低温处理。其机制是提高水解酶活性、促进胚的生长势、降低胚周围组织的机械阻力。与 ABA 的关系是拮抗的：ABA 维持休眠、促进耐脱水性，GA 打破休眠、促进萌发，二者比值决定种子是否萌发。"},{"id":"23.6","t":"赤霉素与成花、性别分化","s":2,"c":"23. 赤霉素类","x":"GA 可替代长日照诱导某些长日植物（如拟南芥、菠菜）在短日照下成花，也能促进多种植物开花，但对部分植物（如苹果、菊花）无效果甚至抑制。GA 还影响性别分化，黄瓜等葫芦科植物中 GA 促进雄花形成，而乙烯与CTK 促进雌花形成，生产上可用 GA 或乙烯利调节性别以提高产量。"},{"id":"23.7","t":"赤霉素的农业应用","s":3,"c":"23. 赤霉素类","x":"（1）促进茎叶生长，用于芹菜、菠菜增产与烟草、牧草增产；（2）打破休眠与促进萌发，用于马铃薯种薯催芽、种子播前处理；（3）诱导无子果实，用于葡萄（花后处理使果粒增大、无子）与柑橘；（4）促进开花与减少落果；（5）促进麦芽糖化，用于啤酒工业；（6）延缓果实衰老，用于柑橘留树保鲜。使用注意浓度与时期，过量会引起徒长、倒伏与品质下降。"},{"id":"24.1","t":"细胞分裂素的种类与结构","s":3,"c":"24. 细胞分裂素类","x":"天然细胞分裂素是腺嘌呤的衍生物，N⁶ 位侧链不同构成不同种类：玉米素（ZT）、二氢玉米素、异戊烯基腺嘌呤（iP）及其核糖苷，此外还有人工合成的激动素（KT）与 6-苄基腺嘌呤（6-BA）。CTK 在酸性条件下稳定、碱性下易失活，耐热。其活性取决于侧链结构，iP 与 ZT 活性最高。"},{"id":"24.2","t":"合成部位与运输","s":3,"c":"24. 细胞分裂素类","x":"CTK 主要在根尖分生组织合成，经木质部随蒸腾流向上运输到地上部分，因此根系活力直接影响地上部的衰老与生长；幼胚、发育中的种子与果实也能合成 CTK。运输形式主要是玉米素核苷与异戊烯基腺苷。根冠比变化时 CTK供应改变，是“根深叶茂”的生理基础之一。"},{"id":"24.3","t":"促进细胞分裂与器官分化","s":3,"c":"24. 细胞分裂素类","x":"CTK 促进细胞分裂（与生长素协同，CTK 促胞质分裂、生长素促核分裂），促进细胞扩大（促进细胞壁松弛与溶质积累）与侧芽生长（解除顶端优势）。在组织培养中，生长素与 CTK 的比例决定分化方向：比值高时诱导生根，比值低时诱导生芽，中间比值形成愈伤组织，这一规律来自 Skoog 与Miller 的经典实验。"},{"id":"24.4","t":"延缓衰老的机制","s":3,"c":"24. 细胞分裂素类","x":"CTK 延缓叶片衰老的机制包括：（1）抑制蛋白水解酶与核酸酶活性，减少叶绿素与蛋白质降解；（2）吸引同化物向处理部位运输，形成“移动库”；（3）提高超氧化物歧化酶等抗氧化酶活性，减少自由基伤害；（4）促进气孔开张与光合维持。经典实验是“叶片涂抹 CTK 可延缓局部黄化”，与去掉幼果导致叶片早衰形成对照。"},{"id":"24.5","t":"CTK 与顶端优势、侧芽生长","s":2,"c":"24. 细胞分裂素类","x":"生长素在茎尖抑制侧芽生长，CTK 在侧芽局部促进其生长，二者相互拮抗。最新研究表明生长素通过细胞分裂素（在茎中合成并被限制运输）与独脚金内酯共同抑制侧芽的萌发，而摘心去除了生长素来源，CTK 与糖供应增加，侧芽迅速生长。这一解释比单一激素说更符合实验事实。"},{"id":"24.6","t":"细胞分裂素信号与双元系统","s":2,"c":"24. 细胞分裂素类","x":"CTK 与质膜上组氨酸激酶受体（CRE1/AHK4、AHK2、AHK3）结合，引发受体自磷酸化并向胞内磷酸转移蛋白（AHP）传递磷酸基，AHP 进入核内磷酸化 B 型 ARR 转录因子，激活下游基因；A 型 ARR 被诱导表达后又会抑制响应，构成负反馈。此通路与细菌双元系统同源，是信号模块进化的例证。"},{"id":"24.7","t":"CTK 的农业应用","s":2,"c":"24. 细胞分裂素类","x":"（1）蔬果保鲜，用 6-BA 或玉米素处理叶菜、青椒、花椰菜，延缓黄化；（2）促进侧芽萌发与苗期生长；（3）组织培养中调节芽的分化；（4）提高坐果率，用于苹果、梨等；（5）提高抗逆性，CTK 处理可减轻干旱与低温伤害。注意 6-BA 在部分蔬菜上的残留限制。"},{"id":"25.1","t":"脱落酸的化学与分布","s":3,"c":"25. 脱落酸","x":"脱落酸（ABA）是含 15 个碳的倍半萜（一种具有环氧结构的脂肪酸），最初因促进棉铃脱落而被发现，后证明其更重要功能是诱导气孔关闭与种子休眠。ABA 在叶绿体、根与果实中合成，衰老与胁迫时含量急剧升高；在细胞内主要分布于叶绿体与胞质，酸性形式（ABA）可透过膜，阴离子形式（ABA⁻）不能，因此 pH 分区影响其跨膜移动。"},{"id":"25.2","t":"ABA 的合成与代谢","s":3,"c":"25. 脱落酸","x":"ABA 合成有两条途径：C₁₅ 直接途径（由法尼基焦磷酸直接环化，见于真菌等）与 C₄₀ 间接途径（胡萝卜素/类胡萝卜素裂解途径），后者是植物主要途径：玉米黄质→紫黄质→新黄质→9-顺式环氧类胡萝卜素→黄质醛→ABA。关键限速酶是 9-顺式环氧类胡萝卜素双加氧酶（NCED），干旱时 NCED 基因迅速上调，是 ABA 积累的限制步骤。ABA 的钝化主要通过氧化为红花菜豆酸（PA）及其葡萄糖酯（贮存形式）。"},{"id":"25.3","t":"ABA 的生理作用","s":3,"c":"25. 脱落酸","x":"（1）诱导气孔关闭、减少水分散失，是最快的抗旱响应；（2）促进种子成熟时的胚休眠与耐脱水性（LEA 蛋白积累）；（3）抑制种子萌发与营养生长；（4）促进器官脱落（与乙烯协同）；（5）提高抗逆性（冷、盐、旱）；（6）促进根系生长、抑制地上部生长，改变根冠比。"},{"id":"25.4","t":"气孔关闭的 ABA 机制","s":3,"c":"25. 脱落酸","x":"ABA 与保卫细胞质膜或胞质受体 PYR/PYL 结合，抑制 PP2C（ABI1/ABI2），使 SnRK2.6（OST1）激酶激活；OST1 磷酸化并激活阴离子通道 SLAC1，Cl⁻ 与苹果酸根外流使膜去极化，进而打开外向 K⁺ 通道，K⁺外流；同时 OST1 磷酸化 RBOHF 产生 H₂O₂，H₂O₂ 促进 Ca²⁺ 内流与通道激活；保卫细胞渗透势升高、失水，膨压下降，气孔关闭。这一链条是“激素—激酶—离子通道—膨压”的经典范例，也是干旱下叶片 K⁺ 含量下降的原因。"},{"id":"25.5","t":"ABA 与种子休眠、萌发","s":3,"c":"25. 脱落酸","x":"种子成熟后期 ABA 含量升高，诱导胚进入休眠并积累 LEA 蛋白与贮藏物质，提高耐脱水性；种子吸胀时若 ABA 仍高，则抑制 α-淀粉酶合成与胚生长，维持休眠。休眠的解除需降低 ABA 水平或提高 GA 水平，低温层积、光照、赤霉素处理均通过改变 ABA/GA 比值起作用。ABA 缺陷突变体（aba、nced）种子在穗上提前萌发（穗发芽），是农业生产中的严重问题。"},{"id":"25.6","t":"ABA 与逆境信号","s":2,"c":"25. 脱落酸","x":"ABA 被称为“逆境激素”：干旱、盐渍、低温、渗透胁迫都迅速诱导ABA 积累，进而引起气孔关闭、逆境基因表达、渗透调节物质合成与 LEA 蛋白积累。ABA 还通过增加根系水力导度与促进根生长提高吸水能力。ABA 信号与 Ca²⁺、活性氧、MAPK 级联交叉，构成逆境响应的核心网络。"},{"id":"25.7","t":"ABA 的应用","s":2,"c":"25. 脱落酸","x":"（1）无公害抗蒸腾剂，喷施低浓度 ABA 提高苗木移栽成活率；（2）促进种子成熟与提高耐贮藏性；（3）花期调控与疏花疏果；（4）作为研究逆境生理的常用工具试剂。由于 ABA 价格高、易光解，生产上多用其类似物或ABA 信号激动剂。"},{"id":"26.1","t":"乙烯的发现与基本性质","s":3,"c":"26. 乙烯","x":"乙烯（ETH）是含两个碳的烯烃气体，常温下为气态，是最简单的植物激素，也是唯一的气体激素。很早人们就发现煤气灯泄漏使温室植物落叶、照明气中的乙烯使豌豆苗徒长，1901 年 Neijubow 证明乙烯能引起黄化苗三重反应。乙烯在水中溶解度低、扩散快，因此既能在植物体内短距离作用，也能作为“群体信号”在植株间传播；果实与花朵释放的乙烯可催熟邻近个体。"},{"id":"26.2","t":"乙烯的生物合成","s":3,"c":"26. 乙烯","x":"合成途径为：甲硫氨酸（Met）→S-腺苷甲硫氨酸（SAM）→1-氨基环丙烷-1-羧酸（ACC）→乙烯。第一步由 ACC 合酶（ACS）催化，是限速步骤；第二步由 ACC 氧化酶（ACO，又称乙烯形成酶 EFE）催化，需 O₂ 与抗坏血酸为共底物。因此缺 O₂ 或高温抑制 ACO 会阻碍乙烯生成，这是“低氧贮藏”与“热水处理”保鲜的机制之一。ACC 还可与丙二酰基结合形成 MACC而钝化，或经 ACC 脱氨酶分解。"},{"id":"26.3","t":"乙烯合成的调控","s":3,"c":"26. 乙烯","x":"（1）发育调控，果实成熟、器官脱落、衰老时 ACS 与 ACO 基因大量表达；（2）逆境诱导，机械伤害、涝渍、病害、低温、金属离子都迅速诱导“逆境乙烯”，是胁迫信号；（3）自我催化，跃变型果实中乙烯诱导自身合成，形成爆发式上升；（4）抑制因素，低 O₂、高 CO₂、低温、AVG（氨基乙氧基乙烯基甘氨酸）与 AOA 抑制 ACS，Co²⁺ 抑制 ACO；（5）生长素高浓度可诱导乙烯生成，解释生长素的“抑制效应”。"},{"id":"26.4","t":"三重反应","s":3,"c":"26. 乙烯","x":"黄化豌豆幼苗在乙烯作用下出现三种典型形态变化：（1）上胚轴横向增粗（抑制伸长）；（2）横向生长（偏上生长）；（3）茎的顶端弯钩加剧（成钩）。三重反应是乙烯生物测定的经典指标，也是判断乙烯信号通路是否正常的重要表型；ctr1 突变体在无乙烯时也表现三重反应，说明 CTR1 是信号的负调控因子。"},{"id":"26.5","t":"乙烯的主要生理作用","s":3,"c":"26. 乙烯","x":"（1）促进果实成熟（跃变型果实的关键调控者）；（2）促进器官脱落与衰老，诱导离层形成与叶绿素降解；（3）促进偏上生长（叶片下垂）；（4）抑制茎的伸长、促进横向增粗；（5）促进不定根与根毛形成；（6）参与向地性反应（水平放置的茎上侧乙烯增多导致偏上生长）；（7）参与防御反应与伤害响应；（8）促进某些植物开花（菠萝）与雌花分化（黄瓜）。"},{"id":"26.6","t":"乙烯信号通路","s":3,"c":"26. 乙烯","x":"乙烯与内质网膜上的受体（ETR1、ERS1、ETR2、EIN4、ERS2）结合，使受体失活；受体原本激活 CTR1（Raf 样激酶），CTR1 失活后不再磷酸化EIN₂，EIN₂ 的 C 端被切割并转运入核，稳定 EIN3/EIL 转录因子，激活 ERF等下游基因。因此“有乙烯时受体关闭、抑制解除”是典型的双重负调控。乙烯受体需要铜离子作为辅因子，银离子（Ag⁺）可占据受体而阻断乙烯作用，这就是鲜花保鲜用硫代硫酸银的原理。"},{"id":"26.7","t":"乙烯的农业应用","s":3,"c":"26. 乙烯","x":"（1）催熟，用乙烯利（2-氯乙基膦酸，在植物体内释放乙烯）处理番茄、香蕉、柿子、棉花促进脱叶与吐絮；（2）促进橡胶树排胶（乙烯利涂割口）；（3）促进菠萝开花与黄瓜雌花分化；（4）疏花疏果；（5）保鲜与延缓成熟，用 1-MCP（1-甲基环丙烯）封闭乙烯受体，或用高锰酸钾吸收乙烯；（6）抑制发芽，用于洋葱、马铃薯贮藏。"},{"id":"27.1","t":"油菜素甾醇","s":3,"c":"27. 其他植物生长物质","x":"油菜素甾醇（BR）是聚羟基化的甾体化合物，1979 年从油菜花粉中分离出油菜素内酯（BL）。它在植物界广泛存在，极低浓度（纳摩尔级）即可促进细胞伸长与分裂、维管束分化、花粉管生长、种子萌发与抗逆性。受体是质膜受体激酶 BRI1，与共受体 BAK1 形成复合体后经 BSU1—BIN₂—BZR1 通路传递信号。BR 合成或信号缺陷的突变体表现矮化、去黄化异常与雄性不育。"},{"id":"27.2","t":"茉莉酸类","s":3,"c":"27. 其他植物生长物质","x":"茉莉酸（JA）及其甲酯（MeJA）、茉莉酸异亮氨酸（JA-Ile）由亚麻酸经十八碳烷途径合成，是“伤害激素”与“防御激素”。其生理作用包括：诱导蛋白酶抑制剂与次生物质合成、促进叶片衰老与气孔关闭、抑制根生长与种子萌发、参与机械伤害与虫害响应、与乙烯协同促进脱落。JA 信号的核心是受体COI1（F-box 蛋白）在 JA-Ile 存在时降解 JAZ 阻遏蛋白，释放 MYC 类转录因子。"},{"id":"27.3","t":"水杨酸","s":2,"c":"27. 其他植物生长物质","x":"水杨酸（SA）是酚类化合物，在植物防御中起核心作用：病原物侵染后局部 SA 积累，诱导病程相关蛋白（PR 蛋白）表达与系统获得性抗性（SAR），并可通过韧皮部向全株传递信号。SA 还参与产热（天南星科植物）、开花诱导、气孔调节与逆境响应。外源 SA 处理可提高抗病性与抗逆性，但高浓度会造成伤害。SA 信号依赖 NPR1 蛋白的核转位。"},{"id":"27.4","t":"多胺","s":2,"c":"27. 其他植物生长物质","x":"多胺包括腐胺、亚精胺与精胺，由鸟氨酸或精氨酸脱羧合成，带正电荷，可与核酸、膜磷脂结合，参与 DNA 复制、蛋白质合成、膜稳定与自由基清除。多胺促进细胞分裂与伸长、延缓衰老、提高抗逆性；其含量在旺盛生长的组织中高，在胁迫下常升高。多胺与乙烯共用 SAM 前体，二者合成存在竞争关系，这是“胁迫下乙烯与多胺此消彼长”的生化基础。"},{"id":"27.5","t":"独脚金内酯","s":3,"c":"27. 其他植物生长物质","x":"独脚金内酯（SL）是类胡萝卜素衍生的萜内酯，最初因刺激列当（独脚金）种子萌发而被发现。其生理作用有三：（1）抑制侧芽分枝（与生长素、CTK 共同调控顶端优势）；（2）促进丛枝菌根真菌分枝，是共生信号；（3）促进根系发育与磷饥饿响应。SL 在磷缺乏时分泌增加，帮助植物吸引菌根真菌获取磷。受体是 α/β 水解酶 D14，信号依赖 MAX2（F-box 蛋白）。"},{"id":"27.6","t":"其他信号分子与肽激素","s":1,"c":"27. 其他植物生长物质","x":"（1）一氧化氮（NO），参与生长素信号、气孔关闭与防御；（2）系统素，由 18 个氨基酸组成的肽，受伤时在韧皮部移动并激活 JA 合成，是“伤害预警”信号；（3）CLE 肽，参与维管束分化与根瘤数量调控；（4）胞外 ATP与谷氨酸，作为损伤相关分子模式触发免疫；（5）独脚金内酯以外的strigolactone 类似物与 karrikin（烟雾信号）参与种子萌发。"},{"id":"27.7","t":"激素作用的分子共性","s":2,"c":"27. 其他植物生长物质","x":"多数植物激素通过“受体—阻遏蛋白降解—转录因子释放”的模式发挥作用：生长素降解 Aux/IAA，GA 降解 DELLA，JA 降解 JAZ，SL 降解 SMXL，乙烯切割并激活 EIN₂。这种“去除抑制”的设计使信号响应迅速且可逆，也便于与其他通路交叉整合，是理解全部激素作用机制的“万能钥匙”。生长素激素受体TIR1/AFB核心阻遏蛋白Aux/IAA赤霉素GID1 DELLA茉莉酸COI1 JAZ独脚金内酯D14 SMXL乙烯CTR1（激酶）脱落酸ETR1 等PYR/PYL分枝抑制因子EIN3/EIL PP2C（磷酸酶）ABF/AREB油菜素甾醇BRI1 BIN₂（激酶）BZR1/BES1关键转录因子ARF PIF、GAMYB MYC2"},{"id":"28.1","t":"激素间的协同与拮抗","s":3,"c":"28. 激素间的相互作用与生长调节剂","x":"协同的例子：GA 与生长素共同促进茎伸长（GA 促进生长素合成与运输）；CTK 与生长素共同促进细胞分裂（分别促胞质分裂与核分裂）；乙烯与ABA 共同促进脱落与成熟。拮抗的例子：ABA 与 GA 在种子萌发、气孔运动上相互对立；生长素与 CTK 在顶端优势、根芽分化上相互制约；乙烯与生长素在细胞伸长上相互抑制（高浓度生长素通过诱导乙烯抑制伸长）。"},{"id":"28.2","t":"激素在发育过程中的时序变化","s":3,"c":"28. 激素间的相互作用与生长调节剂","x":"种子萌发期以 GA 为主导（ABA 下降），幼苗生长期以生长素与 BR 主导伸长、CTK 促进分枝，成花期以 GA、CTK、FT 信号共同作用，果实发育期生长素、GA、CTK 依次主导（细胞分裂期以 CTK 为主、细胞膨大期以 GA 与生长素为主），成熟期乙烯（跃变型）或 ABA 主导，衰老脱落期乙烯与 ABA升高、CTK 下降。掌握这条时序可把“激素—发育阶段”对应起来，是简答题的常用答题框架。"},{"id":"28.3","t":"激素平衡与器官分化","s":3,"c":"28. 激素间的相互作用与生长调节剂","x":"组织培养中生长素与 CTK 的比值决定器官发生：比值高诱导生根，比值低诱导生芽，中间比值维持愈伤组织；比值极端（如 2,4-D 高浓度）诱导胚性愈伤。这一规律广泛用于快速繁殖、脱毒苗生产与单倍体育种（花药培养）。此外 GA 与 ABA 的比值决定种子萌发与否，乙烯与生长素的比值影响脱落与偏上生长。"},{"id":"28.4","t":"植物生长调节剂的种类","s":3,"c":"28. 激素间的相互作用与生长调节剂","x":"（1）生长素类，如 IAA、IBA、NAA、2,4-D、防落素；（2）赤霉素类，如 GA₃、GA₄₊₇；（3）细胞分裂素类，如 6-BA、KT、氯吡脲（CPPU）；（4）乙烯释放剂与抑制剂，如乙烯利、1-MCP、AVG；（5）脱落酸类，如 ABA、诱抗素；（6）生长延缓剂与抑制剂，如矮壮素（CCC）、多效唑（PP333）、比久（B9）、缩节胺（DPC），它们抑制 GA 合成或干扰其作用，用于防止徒长、培育壮苗；（7）其他，如芸苔素内酯、复硝酚钠、三十烷醇。"},{"id":"28.5","t":"使用技术与药害","s":3,"c":"28. 激素间的相互作用与生长调节剂","x":"使用要点：（1）浓度，多在 10 至 1000 mg/L 范围，浓度过高易产生药害；（2）时期，须在敏感期使用（如花期防落、花后促膨大）；（3）方法，喷施、浸蘸、涂抹、注射、土壤处理；（4）环境，避免高温强光与雨前施用；（5）混合使用需注意酸碱性与拮抗。常见药害表现为叶片畸形卷曲、徒长或僵苗、落花落果、果实畸形与残留超标（如氯吡脲过量导致猕猴桃畸形）。"},{"id":"28.6","t":"生产应用与安全性","s":2,"c":"28. 激素间的相互作用与生长调节剂","x":"生长调节剂的应用包括：培育壮苗（多效唑控旺）、防止徒长与倒伏（缩节胺用于棉花）、促进生根（插条处理）、控花控果（疏花疏果、保花保果）、催熟与保鲜（乙烯利、1-MCP）、提高抗逆性（芸苔素内酯、诱抗素）、无子果实生产（GA 处理葡萄）。安全性方面需遵循登记作物与剂量、遵守安全间隔期，禁止使用未经登记的“膨大剂”类物质，避免残留超标与品质下降。第六篇 植物的生长发育"},{"id":"29.1","t":"种子的活力与寿命","s":2,"c":"29. 种子萌发","x":"种子活力指种子在田间条件下萌发并长成正常植株的能力，比单纯发芽率更能反映生产价值。种子寿命因种类差异极大：柳、杨种子寿命仅数周，多数农作物种子 2 至 5 年，莲子在适宜条件下可存活上千年。寿命长短与含水量、贮藏温度、种皮透性及胚的保护机制（如抗氧化系统、LEA 蛋白）有关，超干贮藏与低温贮藏可显著延长寿命。"},{"id":"29.2","t":"吸胀吸水与吸水三阶段","s":3,"c":"29. 种子萌发","x":"种子萌发的第一步是吸胀吸水，其动力是亲水胶体（蛋白质、淀粉、纤维素）的衬质势，与种子死活无关（死种子同样吸胀）。吸水曲线呈三阶段：第一阶段为急剧的物理吸胀（快，数小时）；第二阶段为滞缓期（吸水停滞，此期代谢活跃，酶活化与物质动员开始）；第三阶段为渗透吸水（胚根突破种皮后随生长大量吸水）。三阶段的划分是判断萌发进程的重要依据。阶段持续时间吸水动力主要事件Ⅰ 急剧吸胀数小时衬质势物理吸水、呼吸启动Ⅱ 滞缓期数小时至数天水势趋于平衡酶活化、GA 与 ABA 调整Ⅲ 渗透吸水胚根突破后渗透势胚生长、物质动员加速"},{"id":"29.3","t":"酶的活化与贮藏物质动员","s":3,"c":"29. 种子萌发","x":"种子吸胀后，酶由两种方式产生：一是原有酶原的活化（如 β-淀粉酶由结合态释放），二是新酶的合成（如 α-淀粉酶、蛋白酶、脂肪酶）。禾谷类种子中，胚分泌的 GA 运输到糊粉层，诱导 α-淀粉酶与蛋白酶合成并分泌到胚乳，把淀粉水解为麦芽糖与葡萄糖，把蛋白质水解为氨基酸，供胚生长。动员效率决定出苗速度与整齐度。"},{"id":"29.4","t":"需光性与光敏色素的作用","s":3,"c":"29. 种子萌发","x":"部分种子萌发需要光照（需光种子，如莴苣、烟草、拟南芥），部分被光抑制（嫌光种子，如洋葱、番茄部分品种），多数对光不敏感。感受光的色素主要是光敏色素：红光（660 nm）把 Pr 转为活性型 Pfr 促进萌发，远红光（730 nm）把 Pfr 转回 Pr 抑制萌发，因此“红光促进—远红光逆转”的反复处理可作为光敏色素参与的证据。Pfr 通过调控 GA 合成与 ABA 降解提高GA/ABA 比值，从而促进萌发。"},{"id":"29.5","t":"种子休眠的类型与原因","s":3,"c":"29. 种子萌发","x":"休眠是活种子在适宜条件下仍不萌发的现象，分两类：（1）初生休眠，种子在成熟过程中形成，原因包括胚未成熟（形态或生理后熟）、种皮不透水或不透气（硬实）、种皮机械束缚、存在萌发抑制物（ABA、香豆素、酚类）；（2）次生休眠，已非休眠的种子在不良条件下重新进入休眠。打破休眠的方法有低温层积、变温处理、机械或酸蚀破皮、激素处理（GA）、光照处理与冲洗抑制物。"},{"id":"29.6","t":"萌发的外界条件","s":3,"c":"29. 种子萌发","x":"（1）水分，需达到临界含水量（淀粉种子约 25% 至 30%，油料种子较低）；（2）温度，有最低、最适、最高三基点，多数作物最适 25 至 30 ℃，变温常优于恒温；（3）氧气，需有氧呼吸供能，土壤板结或积水会导致缺氧烂种；（4）光照，因种而异。此外还受土壤 pH、盐分与病原物影响。"},{"id":"29.7","t":"GA 与 ABA 对萌发的调控","s":3,"c":"29. 种子萌发","x":"GA 与 ABA 是萌发调控的核心一对：ABA 维持休眠、抑制水解酶合成与胚生长；GA 打破休眠、诱导 α-淀粉酶与蛋白酶、促进胚的生长势。两者的平衡由环境（光、温、水分）通过合成与代谢途径调节。分子层面，GA 通过降解 DELLA 释放 GAMYB，ABA 通过 PYR/PYL-SnRK2 激活 ABF 抑制水解酶基因，二者在同一启动子上相互竞争，这是“信号整合”的典型例子。"},{"id":"30.1","t":"光形态建成与黄化苗","s":3,"c":"30. 幼苗生长与光形态建成","x":"光不仅提供光合作用的能量，还作为信号调控植物的形态建成，称光形态建成（光控发育）。黑暗中萌发的幼苗表现黄化苗特征：茎细长、顶端弯钩、叶片不展开、叶绿体不发育、下胚轴快速伸长；见光后转为去黄化：下胚轴伸长受抑、弯钩打开、叶片展开、叶绿体发育、花青素积累。黄化苗—去黄化的转变是光信号调控基因表达的经典模型。"},{"id":"30.2","t":"光敏色素的结构与光转换","s":3,"c":"30. 幼苗生长与光形态建成","x":"光敏色素是由两个相同亚基组成的可溶性色素蛋白，每个亚基含一个线性四吡咯发色团（藻蓝胆素）与一个脱辅基蛋白。它有两种可互相转换的形式：Pr（吸收红光，660 nm）与 Pfr（吸收远红光，730 nm）。红光照射使 Pr 转为 Pfr，远红光使 Pfr 转为 Pr，黑暗下 Pfr 缓慢暗逆转为 Pr。Pfr 是生理活性形式，其比例反映环境中红光/远红光比值（R/FR），因此光敏色素本质上是“R/FR 比值探测器”。"},{"id":"30.3","t":"光敏色素介导的生理反应","s":3,"c":"30. 幼苗生长与光形态建成","x":"（1）种子萌发（红光促进）；（2）幼苗去黄化；（3）避荫反应，冠层遮荫使 R/FR 下降、Pfr 比例降低，茎快速伸长、分枝减少、叶片上举；（4）成花诱导中的光周期计时（见第 33 章）；（5）块茎形成、休眠与脱落；（6）花青素合成与基因表达调节。光敏色素反应分快反应（数分钟内离子流动与基因表达）与慢反应（数小时至数天的形态变化）。"},{"id":"30.4","t":"隐花色素与向光素","s":3,"c":"30. 幼苗生长与光形态建成","x":"（1）隐花色素（CRY1、CRY2）是黄素蛋白，吸收蓝光，调控下胚轴伸长抑制、开花时间（CRY2 在长日照下稳定并促进成花）、生物钟与气孔开张；（2）向光素（phot1、phot2）是蓝光受体激酶，介导向光性、叶绿体移动与气孔开张；（3）UVR8 吸收紫外光 B，调控紫外保护基因表达。蓝光受体使植物能够感知光的方向与质量，是向光性与气孔运动的基础。"},{"id":"30.5","t":"光信号转导的核心模块","s":3,"c":"30. 幼苗生长与光形态建成","x":"光敏色素与隐花色素被光激活后，抑制 E3 泛素连接酶复合体 COP1-SPA的活性。COP1 在黑暗中把转录因子 HY5 泛素化降解；光照下 COP1 被抑制，HY5 蛋白积累，激活光形态建成相关基因（叶绿体发育、花青素合成、下胚轴伸长抑制）。因此“COP1 是暗形态建成的开关、HY5 是光形态建成的正调控因子”，cop1 突变体在黑暗中表现组成型光形态（矮小、子叶展开），是经典证据。"},{"id":"30.6","t":"光形态建成的生态意义","s":2,"c":"30. 幼苗生长与光形态建成","x":"光形态建成使幼苗在出土前把能量主要用于下胚轴伸长（尽快见光），出土后立即转向光合与展开叶片，避免无谓消耗。避荫反应使植物在竞争中优先长高，但以降低抗倒伏性与产量为代价；农业生产中合理密植与株型育种正是要在“竞争性伸长”与“群体产量”之间取得平衡。"},{"id":"30.7","t":"光与其他信号的整合","s":2,"c":"30. 幼苗生长与光形态建成","x":"光信号与激素信号高度交叉：光敏色素通过调控 GA 合成与 DELLA 稳定性影响伸长；COP1 与 HY5 影响生长素运输载体 PIN 的表达与分布；蓝光抑制下胚轴伸长部分依赖 BR 信号；光还通过生物钟（CCA1、LHY、TOC1）调节激素与代谢的昼夜节律，使“何时生长”与“是否生长”统一起来。"},{"id":"31.1","t":"向性运动的概念与类型","s":3,"c":"31. 植物的运动","x":"向性运动是植物器官对外界刺激发生的定向生长反应，其方向与刺激方向有关，运动由不均匀生长引起，不可逆。类型包括：向光性、向重力性（向地性与背地性）、向触性、向化性、向水性、向温性、向电性。与之相对的是感性运动（如感夜性、感震性），其方向与刺激方向无关，由膨压变化引起，可逆。"},{"id":"31.2","t":"向光性","s":3,"c":"31. 植物的运动","x":"茎尖或胚芽鞘受单侧光照射后向光弯曲。经典解释是生长素在尖端向背光侧横向运输，背光侧生长素浓度高、生长快，导致向光弯曲。现代研究表明，向光素（phot1）介导向光性，且生长素运输载体 PIN3 在蓝光下重新定位、调控横向运输；此外根也有向光性（通常为负向光性或向光性因物种而异）。注意：向光弯曲发生在尖端以下的伸长区，尖端是感光部位。"},{"id":"31.3","t":"向重力性","s":3,"c":"31. 植物的运动","x":"根表现正向重力性（向下生长），茎表现负向重力性（向上生长）。感受部位是根冠中央的柱细胞（含淀粉体的平衡石），淀粉体在重力作用下沉降到细胞下侧，压迫内质网并触发 Ca²⁺ 信号与生长素运输载体（PIN3）的重新定位，使生长素向器官下侧运输。根对生长素极敏感，下侧高浓度抑制生长，故根向下弯曲；茎不敏感，下侧高浓度促进生长，故茎向上弯曲。同一机制、相反结果，原因是器官敏感性不同，这是高频考点。"},{"id":"31.4","t":"向触性与向化性","s":2,"c":"31. 植物的运动","x":"向触性是器官对机械接触发生的定向生长反应，如黄瓜卷须接触支架后缠绕、根遇到障碍物后改变方向。向化性是器官对化学物质浓度梯度的定向生长，如花粉管向胚珠方向生长（向化性）、根系向肥料与水分丰富处生长（向化性、向水性）。这些运动使植物能在固着生活中主动获取资源。"},{"id":"31.5","t":"感性运动","s":2,"c":"31. 植物的运动","x":"（1）感夜性，如合欢、酢浆草叶片昼开夜合，由叶枕细胞膨压变化引起，受生物钟调控；（2）感震性，如含羞草受触碰后小叶闭合、叶柄下垂，由叶枕细胞快速失水（K⁺ 与 Cl⁻ 外流）引起，伴随动作电位传播；（3）感触性，如捕虫草、捕蝇草的捕虫运动；（4）气孔运动与花朵开合也属感性运动。感性运动可逆、反应快，是膨压驱动运动的典型。"},{"id":"31.6","t":"膨压运动与细胞学基础","s":2,"c":"31. 植物的运动","x":"感性运动的共同机制是运动细胞（叶枕细胞、保卫细胞）快速改变渗透物质含量，导致水分进出与膨压变化。关键环节包括 K⁺ 与 Cl⁻ 的跨膜流动、水通道蛋白的通透性变化、Ca²⁺ 与动作电位的传递。含羞草的快速运动依赖叶枕细胞中 K⁺ 与 Cl⁻ 大量外流、水分迅速排出，其速度可达秒级，是植物中最快的运动之一。"},{"id":"32.1","t":"生长的三个时期","s":3,"c":"32. 细胞伸长与生长的调控","x":"细胞生长分三期：（1）分裂期，细胞数量增加，体积变化小，受 CTK 与生长素促进；（2）伸长（扩大）期，细胞体积显著增大，伴随液泡形成与细胞壁松弛，是器官生长的主要来源，受生长素、GA、BR 促进；（3）分化期，细胞结构与功能特化，形成各类组织。分生组织按位置分顶端、居间、侧生三类，分别决定高生长、节间伸长与加粗。"},{"id":"32.2","t":"酸生长假说","s":3,"c":"32. 细胞伸长与生长的调控","x":"该假说认为生长素促进细胞伸长的第一步是使细胞壁酸化：生长素激活质膜 H⁺-ATP 酶，H⁺ 泵入细胞壁使 pH 由约 5.5 降至 4.5 至 5.0；酸性条件激活细胞壁中的扩张蛋白（expansin），后者打断纤维素微纤丝与半纤维素之间的氢键，使壁松弛；在膨压驱动下细胞不可逆伸长。证据包括：酸性缓冲液可模拟生长素促进伸长、H⁺-ATP 酶激活剂与抑制剂影响伸长、扩张蛋白基因表达与伸长同步。"},{"id":"32.3","t":"扩张蛋白与细胞壁松弛","s":2,"c":"32. 细胞伸长与生长的调控","x":"扩张蛋白是细胞壁中的一类蛋白，能在不水解多糖的前提下削弱纤维素—半纤维素网络，使壁在酸性条件下“蠕变”（应力松弛），是酸生长的执行者。此外木葡聚糖内糖基转移酶/水解酶（XTH）、果胶甲酯酶、 extensin 过氧化物酶也参与壁的修饰。壁松弛之后必须有新的壁物质合成与交联，否则细胞无法维持形状，因此“松弛—合成—定向”三者共同决定伸长的方向与限度。"},{"id":"32.4","t":"细胞伸长的限制与调控","s":2,"c":"32. 细胞伸长与生长的调控","x":"（1）膨压，是伸长的驱动力，缺水时膨压下降，伸长首先停止；（2）壁的伸展性，由壁组成与酶活性决定；（3）温度，影响酶活性与膜流动性，存在三基点温度；（4）光，通过光敏色素与蓝光受体抑制下胚轴伸长；（5）激素，生长素、GA、BR 促进，乙烯与 ABA 抑制；（6）机械刺激，风与触碰会使茎变短变粗（接触形态建成）。"},{"id":"32.5","t":"生长的相关性","s":3,"c":"32. 细胞伸长与生长的调控","x":"（1）极性，器官两端在形态与生理上的差异，如插条形态学下端生根、上端发芽；（2）再生，受伤后重新形成器官的能力，与激素与营养供应有关；（3）顶端优势，顶芽抑制侧芽生长，原因是生长素抑制与 CTK、SL 的共同作用，摘心可解除；（4）根冠比，即根与冠的相对重量，受水分、氮素、光照与温度调节，干旱与缺氮提高根冠比；（5）大小依存关系，“根深叶茂”，地下部与地上部相互依存。"},{"id":"32.6","t":"植物生长的度量与分析方法","s":2,"c":"32. 细胞伸长与生长的调控","x":"（1）生长曲线，以时间为横轴、干重或体积为纵轴，呈 S 形，可区分对数生长期、线性生长期与衰老期；（2）生长速率与相对生长速率，后者便于比较不同大小植株；（3）叶面积指数与净同化率，用于群体分析；（4）同位素示踪与去叶去果实验，用于分析源库关系；（5）显微测量与标记法，用于单细胞伸长研究。掌握这些方法可应对实验设计类题目。"},{"id":"33.1","t":"幼年期与花熟状态","s":3,"c":"33. 成花诱导","x":"植物在能够感受成花诱导之前必须经历一段营养生长时期，称幼年期（童期）；幼年期结束、具备成花能力的状态称花熟状态。幼年期长短因种而异：草本数天至数周，木本果树数年（苹果 3 至 10 年，银杏更长）。幼年期的标志是叶片形态、插条生根能力与对光周期的不敏感性，生产上常用嫁接、环割、矮化砧来缩短幼年期。"},{"id":"33.2","t":"春化作用","s":3,"c":"33. 成花诱导","x":"春化作用是低温对成花的诱导作用。冬小麦、冬黑麦、白菜、萝卜等需经一定时间的低温（一般为 0 至 10 ℃，2 至 8 周）才能在长日照下开花。感受部位是茎尖或胚的分生组织，可用“局部冷冻”与“种子春化”实验证明；春化效果可通过细胞分裂传递给子细胞，但不能通过嫁接传递（与此不同，光周期诱导产生的开花信号可通过嫁接传递）。高温可解除春化，称去春化。按对低温的需求分为专性（绝对需要）与兼性（可被其他条件替代）两类。"},{"id":"33.3","t":"光周期现象与植物类型","s":3,"c":"33. 成花诱导","x":"光周期现象是植物对昼夜相对长度变化的反应。按对光周期的需求分为：（1）长日植物（短夜植物），如小麦、大麦、菠菜、拟南芥，日长超过临界日长时开花；（2）短日植物（长夜植物），如水稻、玉米、大豆、菊花，日长短于临界日长时开花；（3）日中性植物，如番茄、黄瓜、棉花，开花不受日长显著影响；（4）双重日长（长短日）植物，如萝卜、大戟，需先长日后短日；（5）中间型与短长日类型。代表植物引种提示长日植物类型日长大于临界日长临界条件小麦、大麦、菠菜、豌豆南种北引宜引晚熟品种短日植物日长小于临界日长水稻、玉米、大豆、菊花北种南引需注意晚熟日中性植物对日长不敏感番茄、黄瓜、棉花引种适应范围较广双重日长植物需先长日后短日萝卜、部分大戟引种难度大"},{"id":"33.4","t":"临界日长与临界暗期","s":3,"c":"33. 成花诱导","x":"临界日长是长日植物开花所必须超过的最短日长，也是短日植物开花所必须不超过的最长日长，其数值因种而异（如菠菜约 13 h，菊花约 12 h）。关键结论是：控制开花的真正因素是暗期长度而非日长。用光中断实验可证明：在长夜的中间给予短暂红光照射，短日植物（如大豆、苍耳）不开花而长日植物开花；红光中断后立即给远红光则可逆转，说明光敏色素参与计时。因此短日植物实质上是“长夜植物”，长日植物是“短夜植物”。"},{"id":"33.5","t":"感受部位与开花信号的传导","s":3,"c":"33. 成花诱导","x":"感受光周期的部位是叶片，而不是芽或茎尖。经典实验是：把短日植物的叶片置于短日照下而芽置于长日照下，植株仍能开花；反之则不能。叶片感受光后产生开花刺激物，经韧皮部运输到茎尖（顶端分生组织），引起由营养生长向生殖生长的转变。这一信号可通过嫁接从已诱导植株传到未诱导植株，因此被称为“开花素”，但长期未能分离出单一物质。"},{"id":"33.6","t":"光敏色素与开花的计时机制","s":3,"c":"33. 成花诱导","x":"光敏色素以 Pr/Pfr 两种形式充当“夜长计”。白天 Pfr 比例高；进入夜间Pfr 逐渐暗逆转为 Pr。长夜（短日条件下的夜晚）使 Pfr 降到足够低，短日植物得以开花；短夜则 Pfr 保持较高，长日植物得以开花。不同植物对 Pfr 水平的响应不同，这就是同一种色素能区分长短日的机制。隐花色素与生物钟（昼夜节律）共同参与，使植物能在没有外界光暗变化时仍维持约 24 h 的内源节律。"},{"id":"33.7","t":"开花素与 FT 蛋白","s":3,"c":"33. 成花诱导","x":"现代研究表明，叶片在诱导条件下由 CO 与 FT 基因整合光周期与春化信号，FT 蛋白（一种可移动的磷脂酰乙醇胺结合蛋白类小蛋白）在韧皮部中运输到茎尖，与 FD 蛋白相互作用，激活花分生组织特征基因（AP1、LFY、SOC1），启动花芽分化。因此 FT 是“开花素”的主要候选物质。春化则通过表观遗传沉默开花抑制基因 FLC（组蛋白修饰）来解除对 FT 的抑制。"},{"id":"33.8","t":"其他成花途径","s":2,"c":"33. 成花诱导","x":"（1）自主途径，独立于光周期与低温，通过抑制 FLC 促进开花，如拟南芥 fide 突变体；（2）赤霉素途径，GA 可替代长日诱导部分长日植物成花，通过上调 LFY 与 SOC1；（3）糖与年龄途径，糖供应充足与植株达到一定年龄（miR156-SPL 模块）促进成花；（4）温度途径，适度高温促进开花，持续高温抑制；（5）逆境诱导开花，干旱、低温等胁迫可诱导“应急开花”。"},{"id":"33.9","t":"成花调控在农业生产中的应用","s":3,"c":"33. 成花诱导","x":"（1）引种，短日作物北种南引时因日照变短而提前开花、产量下降，南种北引则晚熟，应结合品种光周期敏感性选择；（2）花期调控，菊花用遮光或延长光照控制花期上市，一品红用短日处理；（3）春化处理，小麦、白菜种子或幼苗低温处理以通过春化，用于育种加代；（4）打破或利用休眠与幼年期，用嫁接、环割、GA 处理促进果树早花；（5）制种，利用光周期不敏感型的育性转换实现两系杂交稻制种。"},{"id":"34.1","t":"花原基的形成与成花决定","s":3,"c":"34. 花器官发育、受精与结实","x":"茎尖分生组织在受到 FT-FD 信号后，由营养型转为生殖型，形成花原基。此过程涉及分生组织特征基因（AP1、LFY、SOC1）的激活与营养基因（如TFL1）的抑制，一旦决定即不可逆。成花决定的实质是分生组织“身份”的改变，之后才依次形成花萼、花瓣、雄蕊与心皮。"},{"id":"34.2","t":"ABC 模型","s":3,"c":"34. 花器官发育、受精与结实","x":"花器官发育的 ABC 模型由 Coen 与 Meyerowitz 提出，认为三类同源异型基因决定四轮花器官身份：A 类基因单独作用形成萼片（第 1 轮），A+B 共同作用形成花瓣（第 2 轮），B+C 共同作用形成雄蕊（第 3 轮），C 类单独作用形成心皮（第 4 轮）。A 与 C 相互拮抗，A 突变则 A 轮花器官变为心皮、C轮不受影响；C 突变则雄蕊与心皮变为花瓣与萼片。拟南芥 AP1、AP2 为 A类，AP3、PI 为 B 类，AG 为 C 类。基因类别代表基因第1轮第2轮第3轮第4轮A AP1、AP2萼片花瓣——B AP3、PI—花瓣雄蕊—C AG——雄蕊心皮"},{"id":"34.3","t":"ABCDE 模型与四因子模型","s":2,"c":"34. 花器官发育、受精与结实","x":"后续研究发现 D 类基因（如 AG 亚家族成员）决定胚珠身份，E 类基因（SEP1-4）为各类基因提供必需的合作因子，于是形成 ABCDE 模型：萼片=A+E，花瓣=A+B+E，雄蕊=B+C+E，心皮=C+E，胚珠=D+E。四因子模型进一步指出，同一轮中不同 MADS-box 蛋白形成四聚体决定器官身份，使模型具有生化基础。这一体系解释了重瓣花、花器官突变体的形成。"},{"id":"34.4","t":"性别分化","s":2,"c":"34. 花器官发育、受精与结实","x":"雌雄同株（玉米、黄瓜）、雌雄异株（大麻、菠菜、银杏）、雌雄同花（多数被子植物）由遗传与环境共同决定。环境因素中，短日照与低温常促进雌花形成（玉米、黄瓜），长日照与高温促进雄花；激素方面，GA 促进雄花（黄瓜），乙烯与 CTK 促进雌花，生长素亦有作用。生产上用乙烯利处理黄瓜增加雌花、用 GA 增加雄花用于制种。"},{"id":"34.5","t":"授粉与花粉萌发","s":3,"c":"34. 花器官发育、受精与结实","x":"花粉落到柱头上后，经识别（亲和与不亲和）后吸水萌发形成花粉管，花粉管沿花柱引导组织向下生长，经珠孔进入胚囊，完成双受精。花粉管的定向生长依赖向化性（胚珠产生的信号如 γ-氨基丁酸、LURE 肽）。花粉萌发需要硼（缺硼时花粉管生长受阻、花粉畸形），这是缺硼导致“花而不实”的直接原因。"},{"id":"34.6","t":"双受精与自交不亲和","s":3,"c":"34. 花器官发育、受精与结实","x":"被子植物的双受精指一个精细胞与卵细胞融合形成合子（2n），另一个精细胞与中央细胞的次生核融合形成初生胚乳核（3n）。自交不亲和是防止近交衰退的机制，分配子体型（S 位点蛋白与花粉 S 决定子识别，如茄科）与孢子体型（如十字花科，由 S 受体激酶与 SRK/SCR 介导），结果是花粉不能萌发或花粉管生长受阻。"},{"id":"34.7","t":"果实发育与单性结实","s":3,"c":"34. 花器官发育、受精与结实","x":"果实由子房（有时连同花托）发育而成。授粉受精后，子房中生长素、GA、CTK 含量升高，成为强“库”，吸引同化物并刺激细胞分裂与膨大，形成真果；假果由花托或花萼参与形成（苹果、梨、草莓）。单性结实指不经受精而结实的现象，分天然单性结实（无子香蕉、无子柑橘、无子葡萄）与诱导单性结实（用 GA、生长素或 CPPU 处理未受精子房），后者是生产无子果实的常用手段。"},{"id":"34.8","t":"果实发育的生理规律","s":2,"c":"34. 花器官发育、受精与结实","x":"果实生长多呈 S 形或双 S 形曲线，分细胞分裂期（数量增加）、细胞膨大期（体积增大，水分与糖大量积累）、成熟期（物质转化与品质形成）。果实发育与种子发育紧密相关，种子产生的激素是果实生长的信号；果实发育与营养生长存在竞争，需通过疏花疏果与合理施肥调节“库”的大小。"},{"id":"35.1","t":"种子成熟生理","s":3,"c":"35. 成熟、休眠、衰老与脱落","x":"种子成熟过程包括：（1）干物质积累，同化物以淀粉、蛋白质、脂肪形式贮存；（2）含水量下降，由 70% 至 80% 降至 10% 至 20%，进入耐脱水状态；（3）ABA 含量升高，诱导休眠与 LEA 蛋白合成；（4）代谢由合成转向贮藏，呼吸下降；（5）种皮硬化。成熟期的异常高温或干旱会导致“逼熟”，粒重下降；穗发芽则与 ABA 不足或休眠弱有关。"},{"id":"35.2","t":"呼吸跃变与果实成熟调控","s":3,"c":"35. 成熟、休眠、衰老与脱落","x":"跃变型果实成熟时呼吸强度先升后降，乙烯自我催化形成爆发峰，触发淀粉水解、果胶降解、色素变化与香气生成；非跃变型果实无呼吸跃变，成熟由ABA 与其他因子缓慢调控。乙烯合成中 ACS 与 ACO 的诱导是跃变的核心，抑制乙烯受体（1-MCP）或抑制合成（AVG、低温）均可延缓成熟。"},{"id":"35.3","t":"果实成熟的物质变化","s":3,"c":"35. 成熟、休眠、衰老与脱落","x":"（1）糖，淀粉水解为可溶性糖，甜度上升；（2）酸，有机酸被氧化或转化，酸度下降；（3）色素，叶绿素分解、花青素与类胡萝卜素积累；（4）质地，果胶甲酯酶与多聚半乳糖醛酸酶使果胶降解、细胞壁松弛而软化；（5）香气，酯类、醛类、萜类挥发物生成；（6）涩味，单宁聚合或氧化而减弱；（7）维生素与抗氧化物质变化。掌握这些变化即可解释“为什么香蕉与苹果放在一起熟得快”。"},{"id":"35.4","t":"休眠的类型与生理机制","s":3,"c":"35. 成熟、休眠、衰老与脱落","x":"休眠是植物在不利季节到来前主动降低代谢、停止生长的适应现象，包括种子休眠（第 29 章）与芽休眠（温带木本植物越冬）。芽休眠分预休眠（由短日与低温诱导，即使回到适宜条件也不萌发）与后休眠（需一定低温积累解除，即需冷量）。休眠的生理基础是 ABA 升高、GA 与 CTK 下降、呼吸与酶活性降低、含水量下降、抑制物积累。解除休眠的方法有低温处理、破眠剂（如石灰氮、单氰胺）、温汤处理等。"},{"id":"35.5","t":"衰老的类型与机制","s":3,"c":"35. 成熟、休眠、衰老与脱落","x":"衰老是细胞、器官或整个植株生理功能衰退、最终死亡的过程，分整体衰老（一次结实植物如小麦、竹）、地上部衰老（多年生草本）、器官衰老（叶、花、果）与细胞衰老。机制方面有若干学说：自由基与活性氧伤害、蛋白质与核酸降解、膜脂过氧化、激素失衡（CTK 下降、ABA 与乙烯升高）、营养撤离。叶片衰老时叶绿素与蛋白质降解，氮磷钾向籽粒或贮藏器官转移，因此“适时早衰”会降低产量。"},{"id":"35.6","t":"脱落的机制与离层","s":3,"c":"35. 成熟、休眠、衰老与脱落","x":"器官脱落在离层发生。离层位于叶柄、果柄基部，其薄壁细胞在脱落前分泌果胶酶与纤维素酶，降解胞间层与细胞壁，使细胞间连接减弱，在重力与风的作用下脱落；离层下方形成保护层（木栓化）防止水分散失与病原侵入。脱落受激素调控：乙烯与 ABA 促进脱落（乙烯促进离层形成与水解酶合成），生长素与 CTK 抑制脱落，且生长素的作用取决于其浓度梯度——“远轴端高、近轴端低”抑制脱落，反之促进。"},{"id":"35.7","t":"程序性细胞死亡","s":2,"c":"35. 成熟、休眠、衰老与脱落","x":"程序性细胞死亡（PCD）是由基因控制的主动死亡过程，与坏死（被动死亡）不同。植物中的典型例子包括导管与管胞分化时的细胞自溶、糊粉层在萌发后的消失、胚乳发育中的细胞死亡、叶片衰老、HR（过敏反应）中受侵染细胞的局部死亡。其形态特征包括染色质凝聚、细胞质浓缩、DNA 梯状断裂、形成凋亡小体样结构。PCD 是“为了整体牺牲局部”的策略。"},{"id":"35.8","t":"衰老与脱落的农业调控","s":2,"c":"35. 成熟、休眠、衰老与脱落","x":"（1）延缓衰老，喷施 CTK 类（6-BA）、芸苔素内酯或合理施氮，保持功能叶寿命（小麦后期“一喷三防”）；（2）促进成熟与脱落，用乙烯利催熟棉花、番茄，便于机械采收；（3）防止落花落果，用生长素类或 GA 在花期处理；（4）疏花疏果，用 NAA 或乙烯利在盛花期处理；（5）贮藏保鲜，低温、气调、1-MCP 与 CTK 类处理延缓衰老。"},{"id":"36.1","t":"初生代谢与次生代谢","s":3,"c":"36. 植物次生代谢产物","x":"初生代谢产物是维持生命活动必需的物质，包括糖类、脂类、蛋白质、核酸与氨基酸；次生代谢产物是由初生代谢中间产物衍生、非生长发育必需但对适应环境有重要作用的物质，包括萜类、酚类与含氮化合物三大类。次生代谢物常以“量大而结构多样”为特征，是天然药物、香料与工业原料的主要来源。"},{"id":"36.2","t":"萜类化合物","s":3,"c":"36. 植物次生代谢产物","x":"萜类由异戊二烯（C5）单位构成，按单位数分为单萜（C10，如薄荷醇、柠檬烯）、倍半萜（C15，如脱落酸、青蒿素）、二萜（C20，如赤霉素、紫杉醇）、三萜（C30，如甾醇、皂苷）、四萜（C40，如类胡萝卜素）与多萜（如橡胶）。合成途径有甲羟戊酸（MVA）途径与甲基赤藓醇磷酸（MEP）途径，前者在胞质、后者在质体。萜类的生态功能包括吸引传粉者、驱避害虫、抗病原，青蒿素与紫杉醇是重要药物。"},{"id":"36.3","t":"酚类化合物","s":3,"c":"36. 植物次生代谢产物","x":"酚类含一个或多个芳香环上的羟基，包括简单酚、酚酸（咖啡酸、阿魏酸）、香豆素、木质素、类黄酮（花青素、黄酮醇、异黄酮）与单宁。其合成起点是苯丙氨酸，经苯丙氨酸解氨酶（PAL）脱氨生成肉桂酸，再进入苯丙烷代谢途径。功能包括：提供色素（花青素决定花色与果色）、抗紫外（黄酮类）、防御病虫害（单宁使蛋白沉淀、异黄酮为植保素前体）、木质化加固细胞壁、作为信号（水杨酸、独脚金内酯前体）。"},{"id":"36.4","t":"含氮次生化合物","s":3,"c":"36. 植物次生代谢产物","x":"包括生物碱、氰苷、芥子油苷与非蛋白氨基酸。生物碱含氮杂环，如烟碱、吗啡、咖啡因、秋水仙碱、长春花碱，多以氨基酸为前体，具有强烈的生理活性与毒性，是植物防御的重要武器，也是重要药物。氰苷在组织破损时水解释放氢氰酸（如木薯、苦杏仁），是防御性毒素。芥子油苷存在于十字花科，水解产生异硫氰酸酯（辛辣味），与癌症预防研究相关。"},{"id":"36.5","t":"次生代谢的生态功能与诱导","s":2,"c":"36. 植物次生代谢产物","x":"（1）防御植食动物，如蛋白酶抑制剂、单宁、生物碱、挥发物吸引天敌；（2）抗病原微生物，如植保素、木质素、PR 蛋白；（3）吸引传粉者与种子传播者，如花色、花香、花蜜；（4）竞争与化感作用，如胡桃醌、水稻化感物质；（5）共生信号，如类黄酮诱导根瘤菌结瘤；（6）抗逆境，如抗氧化与紫外吸收物质。次生代谢常受诱导，伤害、病原、光强与营养状况都可显著改变其含量。"},{"id":"36.6","t":"次生代谢与人类利用","s":2,"c":"36. 植物次生代谢产物","x":"（1）药物，青蒿素（抗疟）、紫杉醇（抗癌）、长春花碱（抗癌）、麻黄碱、黄连素；（2）香料与色素，薄荷、香草、辣椒红、栀子黄；（3）工业原料，天然橡胶、生漆、鞣质、纤维；（4）食品与保健，茶多酚、白藜芦醇、异黄酮、皂苷；（5）农药，除虫菊酯、鱼藤酮、印楝素。通过细胞培养、毛状根培养与代谢工程提高产量，是植物次生代谢研究的重要应用方向。第七篇 逆境生理"},{"id":"37.1","t":"逆境的概念与类型","s":3,"c":"37. 逆境与抗性概论","x":"逆境（胁迫）是指对植物生存与生长发育不利的各种环境因子的总称。按性质分为：物理逆境（干旱、水涝、高温、低温、辐射、机械伤害）、化学逆境（盐碱、酸雨、重金属、农药、空气污染）、生物逆境（病害、虫害、杂草）与人为逆境。胁迫可分原初胁迫（直接作用）与次生胁迫（如干旱引起的氧化胁迫、渗透胁迫），后者往往伤害更大，这也是“活性氧伤害”成为共性机制的原因。"},{"id":"37.2","t":"抗性的三种策略","s":3,"c":"37. 逆境与抗性概论","x":"（1）避性，通过改变生活史或形态避开胁迫，如干旱时落叶、缩短生育期（避旱）、深根性、气孔下陷；（2）御性（忍耐性），通过屏障或调节机制阻止胁迫进入或减轻其影响，如角质层厚、盐腺排盐、细胞壁吸附重金属；（3）耐性，在胁迫已造成影响时仍能维持代谢与生存，如渗透调节、抗氧化系统、膜稳定性、蛋白质保护。答题时按“避—御—耐”三层组织，条理清晰且不易遗漏。"},{"id":"37.3","t":"胁迫的共同效应","s":3,"c":"37. 逆境与抗性概论","x":"不同胁迫常导致相似的原初伤害：（1）膜系统受损，膜脂过氧化、膜透性增大、电解质外渗；（2）活性氧爆发，超氧阴离子、H₂O₂、羟自由基积累；（3）蛋白质变性或降解，酶失活；（4）光合下降，气孔关闭、PSⅡ 受损、Rubisco 失活；（5）呼吸异常，先升后降；（6）渗透胁迫与水分失衡；（7）激素失衡，ABA 升高、CTK 与生长素下降；（8）生长受抑，生物量与产量下降。"},{"id":"37.4","t":"渗透调节","s":3,"c":"37. 逆境与抗性概论","x":"渗透调节是植物在水分胁迫或盐胁迫下主动积累溶质、降低渗透势以维持吸水与膨压的过程。参与的溶质分两类：无机离子（K⁺、Na⁺、Cl⁻，主要区隔于液泡）与有机亲和性溶质（脯氨酸、甜菜碱、可溶性糖、多元醇如甘露醇与山梨醇）。有机溶质的特点是低浓度下即可显著提高渗透压、不干扰酶活性、还能保护膜与蛋白（“渗透保护剂”）。渗透调节能力与抗旱、抗盐性正相关，脯氨酸积累量常作为抗逆性指标。"},{"id":"37.5","t":"逆境蛋白与 LEA 蛋白","s":3,"c":"37. 逆境与抗性概论","x":"植物在胁迫下合成一组新的蛋白，称逆境蛋白，包括热激蛋白（HSP）、低温诱导蛋白、盐胁迫蛋白、病程相关蛋白（PR）与胚胎发育晚期丰富蛋白（LEA）。LEA 蛋白富含亲水氨基酸、高度可溶、具有高度亲水性，能在脱水条件下保护膜结构、稳定蛋白、结合离子、形成玻璃化基质，从而维持细胞在极度脱水下的完整性。LEA 蛋白的积累与种子耐脱水性、抗旱耐盐性密切相关。"},{"id":"37.6","t":"交叉适应","s":2,"c":"37. 逆境与抗性概论","x":"植物经过一种胁迫锻炼后对其他胁迫的抗性也提高的现象称交叉适应。例如经轻度干旱处理的植株对低温、盐害的抗性增强；热锻炼提高耐热性同时增强抗旱性。其机制是不同胁迫诱导的信号通路（ABA、Ca²⁺、活性氧、MAPK）与保护性物质（LEA、抗氧化酶、渗透调节物质）大量重叠，说明抗逆性具有“共享底盘”。"},{"id":"38.1","t":"干旱的类型与旱害机制","s":3,"c":"38. 抗旱与抗涝","x":"干旱分大气干旱（空气干燥、蒸腾过强）、土壤干旱（土壤有效水不足）与生理干旱（土壤有水但因低温、盐分、通气不良而无法吸收）。旱害的原初效应是细胞脱水，继而引起膜脂相变与膜透性增大、蛋白质变性、活性氧爆发、光合下降（气孔限制与非气孔限制）、呼吸异常、有毒物质（NH₃、乙醇）积累，最终生长停止与死亡。"},{"id":"38.2","t":"避旱与耐旱的机制","s":3,"c":"38. 抗旱与抗涝","x":"避旱（逃旱）：缩短生育期、在旱季前完成生活史、落叶减少蒸腾、深根与高根冠比、气孔快速关闭、角质层厚与叶片卷曲。耐旱：渗透调节维持膨压、发达的根系吸水、细胞壁弹性大、LEA 蛋白与脱水素保护、抗氧化系统强、光合途径适应（C₄、CAM）、休眠与复苏能力（复苏植物）。区分“避”与“耐”的关键是：避是减少胁迫暴露，耐是承受胁迫伤害而不死亡。"},{"id":"38.3","t":"干旱下气孔与光合的响应","s":3,"c":"38. 抗旱与抗涝","x":"轻度干旱时气孔部分关闭，胞间 CO₂ 浓度下降，光合受“气孔限制”；严重干旱时叶肉细胞光合能力下降（Rubisco 活性降低、ATP 供应不足、PSⅡ受损），胞间 CO₂ 浓度反而升高，转为“非气孔限制”。同时 ABA 积累、叶片卷曲、叶面积减小。这一“由气孔限制向非气孔限制转变”的判断是竞赛与实验题的常见考点，判据就是胞间 CO₂ 浓度的升降方向。"},{"id":"38.4","t":"提高抗旱性的途径","s":2,"c":"38. 抗旱与抗涝","x":"（1）抗旱锻炼（播前“双芽法”或蹲苗），提高渗透调节与根系活力；（2）增施磷钾肥与有机肥，提高保水与根系发育；（3）应用抗蒸腾剂（ABA、薄膜型）；（4）覆盖保墒、节水灌溉（滴灌、亏缺灌溉）；（5）选育抗旱品种（深根、气孔调节快、渗透调节强、LEA 表达高）；（6）种子包衣与化学调控（如用氯化钙、甜菜碱浸种）。"},{"id":"38.5","t":"涝害与缺氧伤害","s":3,"c":"38. 抗旱与抗涝","x":"涝害的本质是土壤水分饱和导致根系缺氧：（1）有氧呼吸受阻，ATP 供应不足，无氧呼吸产生乙醇、乳酸与乙醛，造成毒害与细胞质酸化；（2）根系吸收能力下降，出现生理干旱与缺素（尤其氮、磷、钾、锌）；（3）土壤中Fe²⁺、Mn²⁺、H₂S 等还原性有毒物质积累；（4）ABA 与乙烯大量合成，气孔关闭、叶片黄化脱落。因此“涝死”常是“饿死 + 毒死”的复合结果。"},{"id":"38.6","t":"抗涝的形态与代谢适应","s":3,"c":"38. 抗旱与抗涝","x":"（1）通气组织形成，皮层细胞程序性死亡形成溶生性气道，把氧气从地上部输送到根部；（2）形成不定根与皮孔膨大，增加吸收与通气；（3）地上部伸长（“避淹”伸长），使叶片露出水面；（4）代谢适应，提高乙醇脱氢酶与乳酸脱氢酶活性、积累苹果酸与丙氨酸等无毒发酵产物、提高抗氧化能力；（5）激素响应，乙烯积累是通气组织形成的触发信号。"},{"id":"38.7","t":"湿害与耐涝性评价","s":2,"c":"38. 抗旱与抗涝","x":"湿害指土壤上层滞水、根系长期处于过湿状态的危害，症状较涝害轻但更隐蔽，表现为根系浅、黄化、早衰。耐涝性评价指标包括淹水后的存活率、叶片黄化程度、不定根与通气组织形成量、乙醇脱氢酶活性、根系活力与产量损失。水稻是最耐涝的作物之一，其通气组织发达且有胚芽鞘伸长等避淹机制。"},{"id":"39.1","t":"冷害与冻害的区别","s":3,"c":"39. 抗寒与抗热","x":"冷害指冰点以上低温（0 至 15 ℃）对喜温植物的伤害，表现为叶片萎蔫、变色、生长缓慢，机制是膜脂相变、酶活性下降、光合与呼吸受阻、物质运输停滞。冻害指冰点以下低温使组织结冰造成的伤害，分胞间结冰（细胞外结冰，使细胞失水、机械压迫）与胞内结冰（更致命，直接破坏原生质与膜）。二者机制不同，抗性机制也不同：抗冷性依赖膜脂不饱和度，抗冻性依赖过冷与冰核控制。"},{"id":"39.2","t":"膜脂相变与冷害机制","s":3,"c":"39. 抗寒与抗热","x":"冷害的原初反应是生物膜发生相变：温度降低到膜脂的相变温度以下，膜脂由液晶态变为凝胶态，膜收缩出现裂隙，膜透性增大，离子外渗，膜上酶（如 ATP 酶）失活，代谢紊乱。膜脂中不饱和脂肪酸比例越高、脂肪酸链越短，相变温度越低，抗冷性越强。因此“膜脂脂肪酸不饱和度”是抗冷性的重要生化指标，抗冷植物（如小麦、油菜）的不饱和度高于喜温植物（如水稻、黄瓜）。"},{"id":"39.3","t":"抗冷性的提高途径","s":2,"c":"39. 抗寒与抗热","x":"（1）低温锻炼（逐步降温），诱导膜脂去饱和酶基因表达、增加不饱和脂肪酸、积累可溶性糖与脯氨酸、提高抗氧化酶活性；（2）增施磷钾肥，减少氮肥；（3）化学调控，用 ABA、氯化钙、多效唑、芸苔素内酯处理；（4）选育抗冷品种；（5）栽培措施，如地膜覆盖、适时播种、灌水调温。"},{"id":"39.4","t":"冻害的机制与抗冻性","s":3,"c":"39. 抗寒与抗热","x":"冻害的关键是结冰引起的脱水与机械损伤。胞间结冰时，胞外冰晶使细胞间隙水势骤降，细胞内水分外流，造成“生理性干旱”，严重时蛋白质变性、膜破裂；胞内结冰则直接损伤细胞器。植物抗冻机制包括：（1）过冷，通过清除冰核物质使细胞液在 -5 ℃ 以下仍不结冰；（2）抗冻蛋白（AFP），吸附于冰晶表面抑制冰晶生长与重结晶；（3）深过冷与玻璃化，胞质高度浓缩形成玻璃态；（4）积累糖、脯氨酸、甜菜碱等保护物质；（5）低温驯化改变膜脂与蛋白组成。"},{"id":"39.5","t":"抗冻蛋白与低温驯化","s":2,"c":"39. 抗寒与抗热","x":"抗冻蛋白通过“吸附抑制”机制降低冰点而不显著改变熔点，造成热滞现象；还可抑制重结晶、保护膜与酶。低温驯化（cold acclimation）是植物在秋末逐渐降温过程中获得抗冻性的过程，涉及 CBF/DREB 转录因子家族的快速诱导，进而激活 COR（冷诱导）基因，合成 LEA 类蛋白、去饱和酶与渗透保护物质。驯化需要数天至数周，且依赖短日照与低温两个信号。"},{"id":"39.6","t":"热害与热激蛋白","s":3,"c":"39. 抗寒与抗热","x":"高温使蛋白质变性聚集、膜脂流动性过大、光合与呼吸失衡、活性氧增加、蒸腾失水，导致叶片灼伤、落花落果、灌浆期缩短。植物的响应是合成热激蛋白（HSP），按分子量分为 HSP100、HSP90、HSP70、HSP60 与小分子 HSP，它们作为分子伴侣帮助变性蛋白重新折叠、防止聚集、促进降解。HSP 的合成由热激转录因子（HSF）调控，HSF 在高温下与 HSE 元件结合启动转录。"},{"id":"39.7","t":"提高抗热性的途径","s":2,"c":"39. 抗寒与抗热","x":"（1）热锻炼，短时间高温预处理诱导 HSP 与抗氧化系统；（2）合理灌溉与遮阴，降低叶温；（3）增施磷钾与钙，稳定膜结构；（4）应用生长调节剂（ABA、水杨酸、芸苔素内酯）诱导抗性；（5）选育耐热品种（气孔调节快、蒸腾强、HSP 表达高、C₄ 或耐热酶系）；（6）调整播期避开高温敏感期。"},{"id":"40.1","t":"盐害的三种机制","s":3,"c":"40. 抗盐、抗病与污染伤害","x":"（1）渗透胁迫，土壤溶液水势过低使根系吸水困难，出现“生理干旱”；（2）离子毒害，过量 Na⁺ 与 Cl⁻ 进入细胞，破坏膜结构、抑制酶活性、干扰K⁺ 与 Ca²⁺ 的吸收与功能，Na⁺ 还抑制光合与蛋白质合成；（3）营养失衡，Na⁺ 与 K⁺、Ca²⁺、Mg²⁺ 竞争吸收位点，导致缺素。此外盐胁迫还引起氧化胁迫与渗透调节紊乱。盐害症状表现为生长受抑、叶尖焦枯、叶片厚而深绿、根系短粗。"},{"id":"40.2","t":"盐胁迫的信号与响应","s":2,"c":"40. 抗盐、抗病与污染伤害","x":"盐胁迫首先引起细胞外渗透势下降（渗透信号）与 Na⁺ 进入（离子信号），触发 Ca²⁺ 内流与活性氧产生，激活 SOS 通路：Ca²⁺ 与钙感受器 SOS3（CBL）结合，激活 SOS2（CIPK）激酶，磷酸化并激活质膜 Na⁺/H⁺ 反向转运体 SOS1，把 Na⁺ 排出细胞；液泡膜上的 NHX 转运体把 Na⁺ 区隔入液泡。同时 HKT 转运体调控 Na⁺ 的长距离运输，减少 Na⁺ 向地上部（尤其叶片）积累。"},{"id":"40.3","t":"拒盐、排盐与离子区隔化","s":3,"c":"40. 抗盐、抗病与污染伤害","x":"（1）拒盐，根系对 Na⁺ 通透性低、以 K⁺ 选择性吸收（如大麦的某些品种）；（2）排盐，通过盐腺（如柽柳、滨藜）或盐囊泡主动分泌盐分到叶面，再被雨水冲走；（3）离子区隔化，把 Na⁺ 与 Cl⁻ 贮存于液泡，使胞质维持低盐浓度，同时合成有机溶质平衡液泡渗透势；（4）离子再运输，把盐分运至老叶并随落叶排除。"},{"id":"40.4","t":"耐盐性与提高抗盐性的途径","s":2,"c":"40. 抗盐、抗病与污染伤害","x":"耐盐机制的核心是“限制进入 + 区隔化 + 渗透调节 + 抗氧化”。提高抗盐性的途径包括：选育耐盐品种（利用野生近缘种）、种子引发与抗盐锻炼、施用石膏（改良碱土）、增施有机肥与磷钾肥、应用 Ca²⁺ 与硅（缓解 Na⁺ 毒害）、利用耐盐植物进行生物修复与海水灌溉。"},{"id":"40.5","t":"抗病性的类型与机制","s":3,"c":"40. 抗盐、抗病与污染伤害","x":"抗病性分：（1）避病与抗侵入，如角质层厚、气孔结构、伤口木栓化；（2）抗扩展，即过敏反应（HR），受侵染细胞迅速死亡形成坏死斑，限制病原物扩展，伴随活性氧爆发与植保素积累；（3）抗毒素与解毒，降解病原物毒素；（4）系统获得性抗性（SAR），局部侵染后全株获得广谱抗性，依赖水杨酸信号与 PR 蛋白积累，可通过韧皮部传递信号。"},{"id":"40.6","t":"抗病的化学防御","s":3,"c":"40. 抗盐、抗病与污染伤害","x":"（1）植保素，侵染后新合成的抗菌物质（如类黄酮、萜类、芪类）；（2）PR 蛋白，包括 β-1,3-葡聚糖酶、几丁质酶、蛋白酶抑制剂、溶菌酶样蛋白；（3）细胞壁加固，木质素与胼胝质沉积、富含羟脯氨酸糖蛋白交联；（4）活性氧爆发，直接毒害病原并加固细胞壁、诱导 HR；（5）酶类，多酚氧化酶、过氧化物酶、苯丙氨酸解氨酶活性升高。抗病反应是“识别—信号—防御物质合成”的整体过程，识别依赖抗病基因（R 基因）与病原无毒基因（avr）的“基因对基因”关系。"},{"id":"40.7","t":"环境污染对植物的伤害","s":2,"c":"40. 抗盐、抗病与污染伤害","x":"（1）二氧化硫，经气孔进入，溶于水形成亚硫酸，破坏叶绿素、抑制光合，典型症状为叶脉间“暗绿色水渍斑”后转褐白；（2）氟化物，积累于叶尖与叶缘，造成坏死；（3）臭氧，破坏膜脂与气孔功能，引起叶片褐色斑点与早衰；（4）酸雨，酸化土壤、淋失盐基离子、释放 Al³⁺ 毒害根系；（5）重金属，抑制酶活性、干扰营养吸收、诱导活性氧，镉、铅、汞毒性强；（6）农药与除草剂，干扰特定代谢途径。植物也可吸收与降解部分污染物，用于环境修复（植物修复）。"},{"id":"41.1","t":"活性氧的种类与产生部位","s":3,"c":"41. 活性氧与逆境信号","x":"活性氧（ROS）包括超氧阴离子（O₂⁻）、过氧化氢（H₂O₂）、羟自由基（·OH）与单线态氧（¹ O₂）。产生部位主要有：叶绿体（PSⅠ 与 PSⅡ 的电子泄漏，Mehler 反应）、线粒体（电子传递链复合体Ⅰ与Ⅲ）、过氧化物酶体（光呼吸与脂肪酸氧化）、质膜（RBOH/NADPH 氧化酶）、细胞壁过氧化物酶与质外体。正常条件下 ROS 的产生与清除处于平衡，浓度很低（H₂O₂ 约10⁻⁷ mol/L 量级）。"},{"id":"41.2","t":"氧化胁迫的伤害","s":3,"c":"41. 活性氧与逆境信号","x":"（1）膜脂过氧化，自由基攻击不饱和脂肪酸，产生丙二醛（MDA），使膜透性增大、电解质外渗；（2）蛋白质氧化，羧化、交联、断裂，酶失活；（3）核酸损伤，DNA 断裂与突变；（4）光合与呼吸受损，Rubisco 与 PSⅡ尤其敏感；（5）加速衰老与细胞死亡。丙二醛含量、相对电导率与 ROS 水平是衡量逆境伤害程度的常用指标。"},{"id":"41.3","t":"酶促抗氧化系统","s":3,"c":"41. 活性氧与逆境信号","x":"（1）超氧化物歧化酶（SOD），把 O₂⁻ 歧化为 H₂O₂，是“第一道防线”，分 Cu/Zn-SOD、Mn-SOD、Fe-SOD；（2）过氧化氢酶（CAT），主要在线粒体与过氧化物酶体中分解高浓度 H₂O₂；（3）抗坏血酸过氧化物酶（APX），叶绿体中清除 H₂O₂ 的主要酶，亲和力高；（4）谷胱甘肽过氧化物酶（GPX）；（5）单脱氢抗坏血酸还原酶与谷胱甘肽还原酶（GR），维持抗坏血酸与谷胱甘肽的还原态。抗坏血酸—谷胱甘肽循环（AsA-GSH 循环）是叶绿体清除 H₂O₂ 的核心系统。"},{"id":"41.4","t":"非酶抗氧化物质","s":2,"c":"41. 活性氧与逆境信号","x":"包括抗坏血酸（维生素 C）、谷胱甘肽（GSH）、类胡萝卜素、α-生育酚（维生素 E）、类黄酮、脯氨酸与甘露醇。它们直接淬灭活性氧、再生其他抗氧化剂、稳定膜与蛋白。类胡萝卜素可淬灭单线态氧与三线态叶绿素，是光保护的关键；脯氨酸除渗透调节外还可清除羟自由基。"},{"id":"41.5","t":"活性氧作为信号分子","s":3,"c":"41. 活性氧与逆境信号","x":"低浓度 ROS 是重要的信号：H₂O₂ 可氧化特定半胱氨酸残基，改变蛋白构象与活性（如激活 MAPK、抑制磷酸酶），从而调控气孔关闭、防御反应、根毛发育与程序性细胞死亡。RBOH 产生的质外体 H₂O₂ 是“呼吸爆发”的核心，其信号通过水通道蛋白进入细胞。因此 ROS 具有“低浓度信号、高浓度伤害”的双重身份，与钙信号、ABA 信号高度耦合。"},{"id":"41.6","t":"逆境信号网络","s":3,"c":"41. 活性氧与逆境信号","x":"逆境信号的一般通路是：感受（膜张力、离子通道、受体）→Ca²⁺ 内流与ROS 产生 →激活激酶级联（CDPK、MAPK、SnRK2）→转录因子（DREB/CBF、ABF、NAC、WRKY）→功能基因（LEA、抗氧化酶、渗透调节酶、离子转运体）表达 →生理适应。ABA 依赖型与 ABA 非依赖型两条通路共同作用，DREB/CBF 通路是低温与干旱响应的核心。"},{"id":"41.7","t":"抗逆基因工程与诱导抗性","s":2,"c":"41. 活性氧与逆境信号","x":"已应用的策略包括：导入抗氧化酶基因（SOD、APX）、LEA 与脱水素基因、渗透调节物质合成酶基因（脯氨酸、甜菜碱、甘露醇）、离子转运体基因（SOS1、NHX）、转录因子基因（DREB1A、CBF）。诱导抗性方面，利用化学诱抗剂（水杨酸类似物、茉莉酸甲酯、芸苔素内酯、壳寡糖）激活植物自身防御，是绿色防控的重要方向。主要原初伤害关键适应机制干旱逆境细胞脱水、气孔关闭渗透调节、LEA、深根、气孔快速关闭相对含水量、脯氨酸、根冠比涝渍缺氧、无氧发酵毒害通气组织、不定根、避淹伸长不定根数、ADH 活性、存活率低温冷害膜脂相变、酶失活膜脂不饱和度高、糖积累相对电导率、脂肪酸不饱和度冻害结冰脱水、机械损伤过冷、抗冻蛋白、玻璃化半致死温度、可溶性糖高温蛋白变性、膜流动性过大HSP、蒸腾降温、抗氧化HSP 表达、冠层温度盐害渗透胁迫、离子毒害拒盐排盐、离子区隔化、SOS 通路叶 Na⁺/K⁺ 比、存活率病害侵染与毒素HR、SAR、PR 蛋白、病斑面积、PR 蛋白活性常用抗性指标植保素第八篇 备考：辨析、速查与复习路线"},{"id":"42.1","t":"水势与渗透势的符号","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：纯水水势为 0，任何溶液的水势与渗透势都是负值，且浓度越高越负（绝对值越大）。常见错误：把渗透势写成正值，或认为“水势越低说明水越多”。判据：水势是“水的化学势差”，溶质只会降低水的能量，因此必为负；水从水势高处流向低处，因此干旱土壤的水势比湿润土壤更低。"},{"id":"42.2","t":"膨压与压力势的关系","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：膨压是细胞吸水后对细胞壁产生的压力，压力势 Ψp 是细胞壁对原生质体的反作用力，二者大小相等、方向相反；正常细胞 Ψp 为正，初始质壁分离时 Ψp = 0。常见错误：认为质壁分离时 Ψp 为负。判据：只有处于张力状态的水柱（如导管）才有负的压力势，细胞在质壁分离后只是 Ψp = 0，而不是负数。"},{"id":"42.3","t":"根压与蒸腾拉力","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：蒸腾拉力是被动吸水的主要动力（占 90% 以上），根压是主动吸水的表现（0.05 至 0.5 MPa），在夜间或蒸腾微弱时更重要。常见错误：认为根压是高大树木水分上升的主要动力。判据：根压最多只能把水柱推高约 5至 50 m 的等效高度，且随蒸腾增强而相对减弱，无法解释百尺高树的水分供应。"},{"id":"42.4","t":"蒸腾系数、蒸腾比与蒸腾速率","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：蒸腾系数是“每制造 1 g 干物质消耗的水量（g）”，是比值；蒸腾比是“每同化 1 mol CO₂ 蒸腾的水的摩尔数”，也是比值；蒸腾速率是“单位时间单位叶面积散失的水量”，是速率。常见错误：三者混用或以数值大小判断抗旱性。判据：抗旱性强表现为蒸腾系数小（或蒸腾比小）与水分利用效率高，但耐旱品种不一定蒸腾速率低。"},{"id":"42.5","t":"质壁分离能否判断细胞死活","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：只有活细胞（原生质层具选择透性）才能发生质壁分离与复原，死细胞不发生。常见错误：认为“不发生质壁分离说明细胞壁不透水”。判据：细胞壁是全透性的，高渗液可自由通过；不发生分离的原因是原生质层失去选择透性、细胞内外的溶质自由扩散，无法形成渗透势差。"},{"id":"42.6","t":"吸胀吸水与渗透吸水","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：吸胀吸水靠亲水胶体的衬质势，死种子同样能吸胀；渗透吸水靠液泡与细胞液的渗透势，只有活细胞能进行。常见错误：用“吸胀”解释成熟细胞吸水，或用“渗透”解释干种子吸水。判据：看有无大液泡，干种子与分生细胞以 Ψm 为主，成熟细胞以 Ψs + Ψp 为主。"},{"id":"42.7","t":"必需元素与有益元素","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：必需元素共 17 种，须满足“不能完成生活史、有特有缺素症、有直接作用”三条标准；钠、硅、钴、硒等对部分植物有益但非普遍必需，称有益元素。常见错误：把钠或硅算入 17 种必需元素，或把铁、锰误判为大量元素。判据：铁的需要量虽小但为必需，属微量元素；钠对多数植物可部分替代钾，但不是必需。"},{"id":"42.8","t":"缺素症的部位判断","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：症状先出现于老叶的元素是移动性强的元素（氮、磷、钾、镁、锌）；先出现于幼叶与生长点的是移动性差的元素（钙、硼、铁、锰、铜）。常见错误：认为缺铁先使老叶黄化，或缺钙先使老叶坏死。判据：钙在木质部随蒸腾流运输且不能从老组织再调运，新叶与生长点蒸腾弱、供钙少，故先受害。"},{"id":"42.9","t":"光饱和点与光补偿点","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：光补偿点是净光合为零时的光强，反映“收支平衡”；光饱和点是光合速率不再随光强增加而上升时的光强，反映“能力上限”。常见错误：认为阳生植物光补偿点高于阴生植物。判据：阳生植物呼吸强，但光合能力更强，其光补偿点略高于阴生植物，光饱和点则显著更高（360 至 450 对比90 至 180 µmol·m⁻²·s⁻¹）。"},{"id":"42.10","t":"光合速率与光能利用率","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：光合速率是单位叶面积单位时间的 CO₂ 同化量（µmol CO₂·m⁻²·s⁻¹）；光能利用率是贮存的化学能占投射辐射能的比例，是群体与全生育期的概念。常见错误：用单叶光合速率直接比较品种产量。判据：产量还取决于光合面积、光合时间、呼吸消耗与分配（经济系数），单叶速率高不等于群体产量高。"},{"id":"42.11","t":"呼吸商与呼吸速率","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：呼吸商 RQ 是释放 CO₂ 与吸收 O₂ 的摩尔比，用于判断底物；呼吸速率是单位时间单位重量（或面积）的 CO₂ 释放量或 O₂ 吸收量。常见错误：认为 RQ 越大呼吸越强。判据：RQ 只反映底物性质与是否发生无氧呼吸，与强度无关；脂肪 RQ 约 0.7，糖为 1，有机酸大于 1。"},{"id":"42.12","t":"生物产量与经济系数","s":3,"c":"42. 概念与符号类易错辨析","x":"正确理解：生物产量是全株干物质总量，经济产量是有经济价值部分，经济系数是二者之比（禾谷类 0.3 至 0.5）。常见错误：认为经济系数越高越好，或把经济系数当成“光合效率”。判据：经济系数超过 0.6 已接近极限，进一步提高需增加生物产量；光合效率是生理指标，经济系数是分配指标。"},{"id":"43.1","t":"光呼吸与呼吸作用（暗呼吸）的区别","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：光呼吸发生在光下、底物是乙醇酸、场所为叶绿体—过氧化物酶体—线粒体三个细胞器、消耗 O₂ 并释放 CO₂、不产生 ATP 反而消耗 ATP；暗呼吸以糖为底物、场所为细胞质与线粒体、产生 ATP。常见错误：把光呼吸当成“有光时的呼吸作用”，或认为光呼吸产生 ATP。判据：光呼吸的关键酶是 Rubisco（加氧）与乙醇酸氧化酶，暗呼吸的关键酶是 PFK 与细胞色素氧化酶。"},{"id":"43.2","t":"光呼吸释放 CO₂ 的部位","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：光呼吸的 CO₂ 在线粒体中释放，由两分子甘氨酸缩合为丝氨酸时产生。常见错误：认为 CO₂ 在叶绿体或过氧化物酶体中释放。判据：叶绿体中发生的是 Rubisco 加氧与甘油酸磷酸化，过氧化物酶体中是乙醇酸氧化产生H₂O₂，只有线粒体的甘氨酸脱羧反应释放 CO₂ 与 NH₃。"},{"id":"43.3","t":"C₄ 与 CAM 的分离机制","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：C₄ 途径是空间分离（叶肉细胞固定、维管束鞘细胞脱羧），CAM 途径是时间分离（夜间固定、白天脱羧）。常见错误：把两者对调，或认为 CAM 也有花环结构。判据：C₄ 需要花环结构与两种细胞，CAM 只需一种细胞但依赖液泡贮酸与昼夜 pH 变化（夜间液泡酸化）。"},{"id":"43.4","t":"两类光系统的电子传递顺序","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：电子由水→PSⅡ（P680）→质体醌→细胞色素 b₆f→质体蓝素→PSⅠ（P700）→铁氧还蛋白→NADP⁺；PSⅡ 在基粒类囊体、PSⅠ 在基质类囊体与基粒边缘。常见错误：认为 PSⅠ 在前、PSⅡ 在后（编号顺序与发现顺序一致，但电子传递顺序相反）。判据：水在 PSⅡ 被裂解，故 PSⅡ 是电子源头；P700 的激发态电位比 P680 更负，位于通路末端。"},{"id":"43.5","t":"循环与非循环电子流的产物","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：非循环电子流产生 ATP、NADPH 与 O₂；循环电子流只产生ATP，不产生 NADPH、不放氧。常见错误：认为循环电子流也产生 NADPH或放氧。判据：循环电子流中电子由 Fd 返回细胞色素 b₆f，不经过水的光解，也不到达 NADP⁺。"},{"id":"43.6","t":"抗氰呼吸的意义","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：交替途径绕过复合体Ⅲ与Ⅳ，与 ATP 合成不偶联，能量以热释放；其意义是产热（天南星科开花升温）、耗散多余还原力、维持碳代谢运转、减轻氧化胁迫，而不是“产生更多 ATP”。常见错误：认为抗氰呼吸提高能量效率或增强抗病是因为产生更多能量。判据：抗氰呼吸的 P/O 比接近 1 或为 0，能量效率低于正常呼吸链。"},{"id":"43.7","t":"糖酵解与三羧酸循环的 ATP 产量","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：糖酵解净得 2 ATP 与 2 NADH；每分子丙酮酸氧化脱羧产生 1 NADH，每轮 TCA 产生 3 NADH、1 FADH₂、1 ATP；按 P/O 比 2.5 与 1.5计算，1 分子葡萄糖彻底氧化净得约 30 至 32 ATP。常见错误：忘记把胞质NADH 穿梭进入线粒体的消耗算入，或把 TCA 每轮记为 2 ATP。判据：植物中 TCA 的底物水平磷酸化产物为 ATP（动物为 GTP）。"},{"id":"43.8","t":"淀粉与蔗糖的合成部位","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：淀粉在叶绿体（白天）与造粉体（贮藏器官）中合成，蔗糖在细胞质中合成，经韧皮部运输。常见错误：认为蔗糖在叶绿体中合成或淀粉在细胞质中合成。判据：蔗糖合成酶（磷酸蔗糖合酶）位于胞质，ADP-葡萄糖焦磷酸化酶位于质体；叶绿体膜上的磷酸转运器以 Pi 交换磷酸丙糖决定二者分配。"},{"id":"43.9","t":"Rubisco 的双功能与 CO₂/O₂ 竞争","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：Rubisco 既能催化 RuBP 羧化也能催化其加氧，二者竞争同一活性位点，比例取决于 CO₂/O₂ 浓度比与温度；加氧反应启动光呼吸。常见错误：认为 Rubisco 只固定 CO₂，或认为提高 O₂ 浓度可促进光合。判据：把 O₂从 21% 降至 2% 时光呼吸几乎消失、净光合上升，这是最直接的证据。"},{"id":"43.10","t":"光合磷酸化与氧化磷酸化的比较","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：二者都依化学渗透机制、都靠 ATP 合酶、都由跨膜质子梯度驱动；区别在于光合磷酸化在类囊体膜上、质子泵入膜内（腔），电子最终来自水；氧化磷酸化在线粒体内膜上、质子泵到膜间隙，电子最终来自 NADH，受氰化物抑制。常见错误：认为两者共用同一套电子载体或同一方向泵质子。"},{"id":"43.11","t":"呼吸商大于 1 的含义","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：RQ 大于 1 可能因为底物是有机酸（含氧多、耗氧少而释放较多 CO₂），也可能因为同时进行无氧发酵（释放 CO₂ 而不耗 O₂）。常见错误：认为 RQ 大于 1 说明呼吸底物是脂肪。判据：脂肪的 RQ 约为 0.7，最低；蛋白质约 0.8；糖为 1；有机酸与发酵可大于 1。"},{"id":"43.12","t":"韧皮部运输的“双向”与压力流","s":3,"c":"43. 代谢与途径类易错辨析","x":"正确理解：不同筛管可同时进行方向相反的同化物运输（双向），但同一筛管中运输方向单一，动力是源库之间的膨压差。常见错误：认为压力流学说可以解释同一筛管内的双向运输，或认为韧皮部运输靠蒸腾拉力。判据：环割后切口上方积累、下方饥饿；蚜虫口针刺入筛管时汁液自动溢出，说明筛管内为正压力，与木质部的负压相反。"},{"id":"44.1","t":"生长素促进的是伸长还是分裂","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：生长素主要促进细胞伸长（使细胞壁松弛、细胞体积增大），细胞分裂主要由细胞分裂素促进；二者在组织培养中协同（生长素促核分裂、CTK 促胞质分裂）。常见错误：把“生长素促进生长”理解为“促进细胞分裂”。判据：生长素处理的胚芽鞘切片中细胞数目不增加而长度增加，酸生长假说也说明其作用点是细胞壁。"},{"id":"44.2","t":"生长素的两重性","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：低浓度促进、高浓度抑制；不同器官敏感度不同，根最敏感（最适约 10⁻¹⁰ mol/L）、芽次之（10⁻⁸）、茎最不敏感（10⁻⁴）。常见错误：认为“同一浓度对一切器官都促进”，或认为高浓度抑制是因为“毒性”。判据：高浓度生长素诱导乙烯生成，乙烯抑制伸长，这才是抑制的机制；除草剂 2,4-D 正是利用双子叶植物敏感度高的特点。"},{"id":"44.3","t":"顶端优势的原因","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：顶芽产生的生长素向下运输，抑制侧芽生长；同时生长素维持茎中独脚金内酯的合成（抑制侧芽萌发），并限制 CTK 向侧芽运输；摘心后生长素来源消失、CTK 与糖供应增加，侧芽萌发。常见错误：认为顶端优势只由生长素一种激素决定，或认为“侧芽处生长素浓度高所以被抑制”。判据：直接向侧芽施加生长素并不能完全替代顶芽的抑制作用，而施加 CTK 或细胞分裂素可促进侧芽生长。"},{"id":"44.4","t":"GA 打破休眠与 ABA 维持休眠","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：ABA 在种子成熟期积累，诱导并维持休眠、提高耐脱水性；GA 打破休眠、诱导 α-淀粉酶与蛋白酶合成、促进胚生长。二者在萌发上相互拮抗，其比值决定是否萌发。常见错误：把二者作用对调，或认为 ABA 只促进脱落。判据：ABA 缺陷突变体表现为穗发芽，GA 缺陷突变体表现为矮化且需外施 GA 才能恢复萌发能力。"},{"id":"44.5","t":"“脱落酸”并非主要的脱落激素","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：促进器官脱落的主要激素是乙烯（促进离层细胞产生纤维素酶与果胶酶），ABA 的作用是间接与协同的；ABA 的核心功能是气孔关闭、休眠与抗逆。常见错误：顾名思义认为脱落酸是“脱落激素”。判据：外施乙烯或乙烯利可迅速引起落叶落果，而外施 ABA 引起的脱落远不如乙烯显著；离层形成伴随乙烯释放高峰。"},{"id":"44.6","t":"生长素与脱落的关系","s":2,"c":"44. 激素与发育类易错辨析","x":"正确理解：生长素抑制脱落，其效果取决于浓度梯度——远轴端（离层远侧，如叶片侧）生长素浓度高于近轴端时抑制脱落，反之促进脱落；乙烯促进脱落。常见错误：认为生长素一律促进脱落或一律抑制脱落。判据：去叶后叶柄远轴端生长素来源消失，梯度反转，离层形成而脱落；涂抹生长素于去叶叶柄可延缓脱落。"},{"id":"44.7","t":"光周期的感受部位","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：感受光周期的部位是叶片（成熟叶），开花信号由叶片产生并运输到茎尖引起成花。常见错误：认为芽或茎尖是感受部位。判据：把短日植物叶片置于短日照而芽置于长日照，植株仍开花；反之不开花。这一点与春化不同，春化的感受部位是茎尖或胚的分生组织。"},{"id":"44.8","t":"临界日长与临界暗期","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：真正起决定作用的是暗期长度，短日植物实质是“长夜植物”，长日植物是“短夜植物”；临界日长只是一个便于比较的日长阈值。常见错误：认为短日植物需要“短日照”本身。判据：光中断实验——在长夜中间给予几分钟红光，短日植物（如苍耳、大豆）不开花，长日植物开花；随后给远红光可逆转，说明光敏色素（Pfr）参与计时。"},{"id":"44.9","t":"春化与光周期信号的传递方式","s":2,"c":"44. 激素与发育类易错辨析","x":"正确理解：春化效果只能通过细胞分裂传递给子细胞，不能通过嫁接传递给未春化的植株；光周期诱导产生的开花信号可以通过嫁接传递。常见错误：认为春化素可以嫁接传递。判据：将已春化的植株与未春化植株嫁接，后者仍不能开花；而把已受光周期诱导的叶片嫁接到未诱导植株上，可使后者开花。"},{"id":"44.10","t":"向光性与向重性的生长素机制","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：向光性中生长素向背光侧横向运输，背光侧浓度高、生长快，茎向光弯曲；向重性中生长素向下侧运输，根对生长素敏感，下侧高浓度抑制生长而向下弯曲，茎不敏感，下侧高浓度促进生长而向上弯曲。常见错误：认为根向下弯曲是因为“下侧生长快”。判据：同一浓度对根是抑制、对茎是促进，理解“敏感性差异”即可避免混淆。"},{"id":"44.11","t":"单性结实与无子果实","s":2,"c":"44. 激素与发育类易错辨析","x":"正确理解：单性结实是不经受精而发育成果实，分天然（无子香蕉、无子柑橘）与诱导（用 GA、生长素、CPPU 处理未受精子房）；无子果实还可来自受精后胚败育（如无子西瓜通过三倍体）。常见错误：认为“无子即单性结实”。判据：三倍体无子西瓜需授粉刺激才能坐果，属于“授粉但胚败育”，不是单性结实。"},{"id":"44.12","t":"呼吸跃变与果实类型","s":3,"c":"44. 激素与发育类易错辨析","x":"正确理解：跃变型果实（苹果、香蕉、番茄、芒果）成熟时有呼吸跃变、乙烯自我催化，可用 1-MCP 与乙烯吸收剂延缓；非跃变型果实（柑橘、葡萄、草莓、菠萝）无跃变，成熟缓慢。常见错误：把柑橘、葡萄当作跃变型果实，或认为“所有果实都靠乙烯催熟”。判据：外施乙烯可催熟跃变型果实，但对非跃变型果实的效果有限，其成熟更多受 ABA 与发育程序调控。"},{"id":"45.1","t":"必需元素功能与缺素症速查表","s":3,"c":"45. 速查表","x":"下表将 17 种必需元素的作用、缺素症状与症状部位汇总，可用于快速判断缺素类型，注意“看部位定元素、看特征定种类”的两步法。主要生理功能典型缺素症N元素蛋白质、核酸、叶绿素成分植株矮小，叶小而黄白或发红老叶P核酸、磷脂、ATP、糖运输叶暗绿或紫红，成熟延迟老叶K 60 多种酶活化剂，渗透调节叶缘焦枯、易倒伏老叶Ca细胞壁果胶钙、第二信使生长点坏死、脐腐、干烧心幼叶与生长点Mg叶绿素中心原子、酶活化脉间失绿后坏死老叶S含硫氨基酸、辅酶 A蛋白质减少，幼叶黄白或发红幼叶Fe细胞色素、铁硫蛋白、叶绿素合成脉间失绿呈黄白化幼叶Mn水的光解、酶活化脉间缺绿杂斑嫩叶至中龄叶B花粉形成与受精、糖运输花而不实、蕾而不花、顶芽坏死幼叶与花器Zn色氨酸合成酶、碳酸酐酶小叶病、节间缩短新叶或老叶Cu质体蓝素、多酚氧化酶叶黑绿、坏死卷皱幼叶Mo硝酸还原酶、固氮酶叶小、失绿坏死卷曲中下部叶Cl水的光解、渗透调节叶小、萎蔫全株Ni脲酶成分尿素积累、叶尖坏死叶尖症状部位"},{"id":"45.2","t":"五大激素对比速查表","s":3,"c":"45. 速查表","x":"下表横向对比五类主要激素的合成部位、运输特点、代表效应与典型应用，是简答题与选择题的高频依据。合成部位运输方式代表效应典型应用生长素 IAA激素茎尖、幼叶、发育中的种子极性运输（形态学上端到下端）促进伸长、顶端优势、生根、单性结实NAA 生根、2,4-D除草赤霉素 GA幼芽、幼根、未熟种子非极性，木质部与韧皮部促进节间伸长、打破休眠、诱导 α-淀粉酶无子葡萄、麦芽糖化细胞分裂素 CTK根尖分生组织木质部随蒸腾流促进分裂、侧芽生长、延缓衰老蔬菜保鲜、组培生芽脱落酸 ABA叶绿体、根、成熟种子木质部与韧皮部气孔关闭、种子休眠、抗逆抗蒸腾剂、提高耐贮性乙烯 ETH全株，成熟果实最多气体扩散果实成熟、脱落、三重反应乙烯利催熟、1MCP 保鲜"},{"id":"45.3","t":"光合三类植物对比速查表","s":3,"c":"45. 速查表","x":"下表把 C₃、C₄、CAM 植物的关键差别集中列出，重点记住“分离方式”“CO₂ 补偿点”“每分子 CO₂ 耗 ATP”三项。项目分离方式C₃C₄CAM无Rubisco空间分离（花环结构）时间分离（昼夜）初次固定酶PEP 羧化酶PEP 羧化酶CO₂ 补偿点30~70 mg/L小于 10 mg/L暗中小于 5 mg/L ATP 需求3 个/CO₂5 个/CO₂5 个以上/CO₂光呼吸蒸腾比明显450~950很弱250~350很弱18~125光合速率10~25 25~50 0.6~2.5"},{"id":"45.4","t":"逆境适应速查表","s":3,"c":"45. 速查表","x":"下表汇总主要逆境的伤害机制、适应策略与判断指标，答题时按“伤害—适应—指标”三段展开即可。逆境初伤害适应策略判断指标干旱脱水、气孔关闭渗透调节、LEA、深根、避旱相对含水量、脯氨酸、根冠比涝渍缺氧、发酵毒害通气组织、不定根、避淹伸长不定根数、ADH 活性冷害膜脂相变膜脂不饱和度高、糖积累相对电导率、脂肪酸不饱和度冻害结冰脱水过冷、抗冻蛋白、玻璃化半致死温度高温蛋白变性HSP、蒸腾降温HSP 表达、冠层温度盐害渗透胁迫、离子毒害SOS 排钠、区隔化、拒盐叶 Na⁺/K⁺ 比病害侵染与毒素HR、SAR、PR 蛋白病斑面积、PR 活性"},{"id":"45.5","t":"水分生理公式与参数速查表","s":3,"c":"45. 速查表","x":"下表集中列出水势公式与常考数值，务必熟记符号与单位，避免把 MPa与 bar、把渗透势与压力势混淆。水势组成项目表达式或数值Ψw = Ψs + Ψp + Ψm渗透势Ψs = -iCRT成熟细胞 Ψm 可忽略R = 0.0083 L·MPa·mol⁻¹·K⁻¹说明水流公式Jv = Lp(ΔΨp - σΔΨs)σ 为反射系数叶水势-0.5~-2.0 MPa干旱时可更低土壤水势永久萎蔫系数约 -1.5 MPa根压约 -0.05 MPa 0.05~0.5 MPa蒸腾系数C₃ 400~900，C₄ 250~350 g 水/g 干物质主动吸水指标"},{"id":"45.6","t":"呼吸与运输参数速查表","s":2,"c":"45. 速查表","x":"下表汇总呼吸作用与同化物运输的常考数值和结论，便于在综合题中快速引用。项目数值或结论备注葡萄糖彻底氧化约 2870 kJ/mol，约 30~32 ATP能量效率约 40%呼吸商糖 1.0，脂肪 0.7，蛋白质 0.8有机酸可大于 1温度系数 Q₁₀约 2（0~30 ℃）0.2~2 m/h低温贮藏依据韧皮部运输速度筛管蔗糖浓度可达 0.8~1.0 mol/L靠主动装载建立安全贮藏含水量淀粉种子低于 13%超过 14%~15% 呼吸陡增木质部 1~45 m/h"},{"id":"46.1","t":"三轮复习法","s":3,"c":"46. 复习路线","x":"第一轮按本篇顺序通读，目标是建立框架，做到“看到章名能说出 6 至 12个知识点”；第二轮按专题横向串联，重点是“水—光合—呼吸—运输”的代谢链与“激素—发育”的调控链；第三轮只看第八篇的辨析与速查表，并做真题与错题回顾。三轮的着力点依次是“广、联、准”，切忌第一轮就死背数字。"},{"id":"46.2","t":"两条主线贯穿全书","s":3,"c":"46. 复习路线","x":"第一条主线是“源—流—库”：光合制造同化物（源）、韧皮部运输（流）、器官贮存与生长（库），水分与矿质沿木质部上行、同化物沿韧皮部下行，产量取决于三者的匹配。第二条主线是“信号—响应”：光、温度、水分、激素作为信号，经受体、Ca²⁺、活性氧、磷酸化级联与转录因子，最终改变酶活性与基因表达。任何一道综合题都可以先归入这两条主线之一。"},{"id":"46.3","t":"图表与公式清单","s":3,"c":"46. 复习路线","x":"必须自己能画的图包括：水势组分示意图与质壁分离过程、气孔开闭的钾离子泵模型、Z 图式与两个光系统的电子传递、卡尔文循环三阶段、C₄ 与CAM 的碳流图、光呼吸的三细胞器途径、韧皮部压力流模型、五大激素的信号通路简图、光周期与春化调控开花的模型、ABC 模型四轮花器官。必须会用的公式包括：Ψw = Ψs + Ψp + Ψm、Ψs = -iCRT、RQ = CO₂/O₂、经济系数 =经济产量/生物产量、蒸腾系数与水分利用效率。"},{"id":"46.4","t":"实验题的准备","s":3,"c":"46. 复习路线","x":"植物生理的实验题多集中在四类：（1）证明性实验，如证明光合放氧来自水（H₂¹⁸O 标记）、证明同化物经韧皮部运输（环割、同位素）、证明光周期感受部位（叶片与芽分开处理）、证明顶端优势（去顶与涂抹生长素）；（2）测定性实验，如质壁分离法测渗透势、红外法测光合、压力室测水势、氧电极测呼吸；（3）探究性实验，如探究某元素是否为必需、探究某激素浓度对生根的影响，注意设置对照、重复与适宜浓度梯度；（4）分析与纠错题，重点检查自变量、因变量、无关变量与对照设置是否合理。"},{"id":"46.5","t":"计算题的准备","s":2,"c":"46. 复习路线","x":"常考计算包括：（1）水势与渗透势，用 Ψs = -iCRT 计算并注意温度用开尔文、浓度用 mol/L；（2）呼吸商与呼吸底物判断；（3）光合与呼吸的净量计算（净光合 = 总光合 - 呼吸）；（4）产量计算，经济系数与生物产量、干物质分配比例；（5）蒸腾系数与水分利用效率的换算；（6）遗传与生理结合题中的比例计算。计算题的关键是单位统一与有效数字，写清公式再代入。"},{"id":"46.6","t":"应试策略与时间分配","s":3,"c":"46. 复习路线","x":"（1）先做基础题与图像识别题，确保概念题不丢分；（2）综合题按“先定性后定量”的顺序作答，先用一句话给出结论，再补机制与数据；（3）遇到陌生情境题，回到两条主线与四层法（是什么、怎样发生、受什么调控、怎么应用）组织答案；（4）简答题分点书写，尽量使用教材术语（如“类囊体腔”“筛管—伴胞复合体”“双重负调控”）；（5）留出时间复查易混点，特别是水势符号、光周期与春化的感受部位、C₄ 与 CAM 的分离方式、光呼吸与呼吸作用的区别。附录：知识库教材索引本总纲的章节体系与知识点取舍得自下列教材，均可在五个生物竞赛知识库中检索到全书或分册扫描件。主教材用于确定知识边界与术语规范，国外教材用于补充机制细节与定量数据，国内其他版本用于比较不同表述与补充缺素症、应用技术等内容。版本与编者在本书中的作用序号植物生理学教材王小菁主编，第 8 版，高等教育出版社主教材，确定八篇框架与术语Plant Physiology（中译本）Taiz 与 Zeiger 主编，第5版补充机制细节、信号通路与定量数据现代植物生理学李合生主编，第 3 版补充缺素诊断、代谢生理与农业应用植物生理学王宝山主编，第 3 版补充与中学生物学衔接的内容与习题角度植物生理学张立军、刘新主编，第 2版补充细胞生理、信号转导与逆境章节植物生理学及其学习指导潘瑞炽主编（王小菁等修订）补充要点提示、术语解释与典型例题使用建议：复习时以本总纲为骨架，遇到需要深入的条目再回到上表对应教材的相应章节精读；若不同教材表述有差异（如必需元素是否包含镍、光饱和点的具体数值），以最新版主教材与竞赛真题的表述为准，并在笔记中标注差异来源，避免在考场上因版本不同而失分。"}]
window.KG_BOOK["10"]=[{"id":"1.1","t":"行为的定义与判断标准","s":3,"c":"1. 动物行为学的基本概念","x":"动物行为（animal behavior）指动物在特定环境条件下由自身神经系统与内分泌系统发动、可被外部识别的动作、姿态、体色改变、发声、化学物质释放以及群体活动过程，也把学习、记忆、动机等内部状态的外在表现包含在内。尚玉昌给出的操作性表述是\"动物所做的有利于眼前自身存活和未来基因存活的任何事情\"，这一表述把行为的适应本质点了出来。判断某一现象是否属于行为，关键看它是否由动物自身发动并具有生物学意义：绿头鸭用喙梳理羽毛是行为，被风吹动的羽毛不是行为；含羞草叶片闭合是感震运动，也不属于动物行为学的研究对象。"},{"id":"1.2","t":"行为的种特异性与个体差异","s":3,"c":"1. 动物行为学的基本概念","x":"每一种动物都有自己的一套行为装备，动作的形态、时序和释放条件高度稳定，这可作为分类与亲缘关系判断的辅助依据，称为行为的种特异性。三刺鱼（Gasterosteus aculeatus）求偶时的\"之\"字形舞（zigzag dance）与雄鱼腹部的红色婚装，是其他鱼种不会混淆的信号。同一种内又存在稳定的个体差异（animal personality），如黑猩猩在攻击性、探索性上的个性差异可重复测量且与皮质醇水平相关，这类差异是近年行为学的新兴考点。"},{"id":"1.3","t":"行为的层次性与顺序性","s":3,"c":"1. 动物行为学的基本概念","x":"行为可以按复杂度分为若干层次：最简单的单元是反射（reflex），其上是固定动作模式，再上是行为序列（behavior sequence），最高层是贯穿生活史的行为策略。行为序列内部有严格的先后顺序，前一动作的完成往往是后一动作的释放条件。三刺鱼繁殖期雄鱼先占据领域、再筑巢、再形成婚装、再以\"之\"字舞把雌鱼引向巢口，任一环缺失则整个序列中断；灰雁（Anser anser）在求偶中把理羽动作逐步仪式化为\"胜利仪式\"，正是序列被重组进化的证据。"},{"id":"1.4","t":"描述行为学与实验行为学","s":3,"c":"1. 动物行为学的基本概念","x":"描述行为学（descriptive ethology）通过长期野外观察编制行为谱、比较近缘种的行为差异，回答\"是什么\"；实验行为学（experimental ethology）通过控制变量、使用模型和假体，回答\"为什么这样反应\"。法布尔（J.-H. Fabre）观察狩猎蜂拖猎物入巢属于描述阶段，而用模型替换刺激源则进入实验阶段。经典例子是沙蜂（Ammophila）运食实验：实验者在蜂入洞检查时把猎物移开几厘米，蜂出洞后会把猎物重新拖到洞口再进洞检查，如此反复，说明这是一段不能被\"看到猎物已在洞口\"所终止的固定动作序列。"},{"id":"1.5","t":"动物行为学的研究领域与交叉学科","s":2,"c":"1. 动物行为学的基本概念","x":"行为学内部已分化为生态行为学（行为生态学）、动物社会学、行为生理学（含神经行为学与行为内分泌学）、行为遗传学、行为系统发育与个体发育研究等分支。行为生态学关心觅食、领域、婚配制度的适应意义（如最适觅食模型）；行为内分泌学关心睾酮与攻击性、催乳素与育幼的关系；生物声学专门研究鸟鸣、鲸歌与昆虫鸣声的频率结构与功能。当代研究多在这些分支之间做整合，如\"鸟鸣\"一个题目就同时牵动神经核团 HVC 的发育、睾酮的季节变化、方言的地理分化与雌性选择的偏好。"},{"id":"1.6","t":"反射、动性、趋性与横定向","s":3,"c":"1. 动物行为学的基本概念","x":"反射是最简单的定型反应，如蚯蚓对机械刺激的屈曲。动性（kinesis）是不具方向性的整体运动，动物只改变速度或转向频率而不朝向刺激，如潮虫（Porcellio）在干燥处移动加快、转向频繁，从而在随机运动中聚集于潮湿处。趋性（taxis）是朝向或背离刺激源的定向运动，如眼虫的正趋光、蛾类的趋光飞行。横定向（transverse orientation）是身体长轴与刺激源保持固定角度的运动，如夜间飞蛾使月光始终落在身体一侧从而保持直线航向。四者的区别在于\"有无方向性\"和\"是否定向于刺激源\"，是选择题的高频陷阱。行为型是否有方向性与刺激源的关系典型实例反射无局部、定型蚯蚓受触后屈曲动性无只改变速度或转向频率潮虫在干处快速转向趋性有朝向或背离刺激源眼虫正趋光、蛾趋光横定向有与刺激源保持固定角度飞蛾借月光保持航向"},{"id":"1.7","t":"动机与欲求行为、完成行为","s":3,"c":"1. 动物行为学的基本概念","x":"动机（motivation）是动物表现某一行为的内部倾向强度，它决定行为被释放的阈值。一个完整的行为过程常分为两段：欲求行为（appetitive behavior）是可变的、探索性的搜索阶段，完成行为（consummatory act）是刻板的、终结性的动作。处于繁殖期的三刺鱼雄鱼会四处巡游寻找合适巢址（欲求行为），一旦找到便挖掘砂底、做成定型动作（完成行为）；饥饿的鹗在空中盘旋搜索水面（欲求行为）与俯冲抓鱼后吞咽（完成行为）也构成同一种分段。理解这一区分，才能解释\"同样饥饿的动物在不同环境下表现不同\"这类题目。"},{"id":"1.8","t":"行为阈值、空放行为与行为疲劳","s":3,"c":"1. 动物行为学的基本概念","x":"行为的释放阈值随动机水平升降：饥饿程度越高，对食物相关刺激的阈值越低，鸫类在饱食时对红色浆果模型几乎不反应，饥饿后同一模型即可引发啄食。当动机极高而适当刺激长期缺失时，会出现空放行为（vacuum activity），即无刺激也完成整套动作，如隔离饲养的椋鸟仍会做出完整的捕飞虫动作，洛伦茨（K. Lorenz）观察到灰雁在蛋被取走后仍完成把蛋滚回巢的整套动作。与之相对的是行为疲劳：同一无关刺激反复呈现，反应强度逐次下降，如鸟群对反复出现的无害模型逐渐不再惊飞，这是习惯化的基础。"},{"id":"2.1","t":"近因与终极原因的基本区分","s":3,"c":"2. Tinbergen 四问：近因与终极原因","x":"解释一个行为可以站在两个时间尺度上：近因（proximate cause）回答\"这一行为在个体身上如何被发动\"，涉及神经、激素、感觉与发育，时间尺度是秒到一生；终极原因（ultimate cause）回答\"这一行为在进化史上为何被自然选择保留\"，涉及适应功能与系统发育，时间尺度是世代。雄性鸣禽在春季鸣唱，近因是长日照引起睾酮升高、作用于脑内歌曲控制核团 HVC 与 RA；终极原因是鸣唱能宣示领域、吸引雌性从而提高繁殖成功。把两者混为一谈是竞赛中最常见的失分点。"},{"id":"2.2","t":"Tinbergen 四问的完整框架","s":3,"c":"2. Tinbergen 四问：近因与终极原因","x":"廷伯根（N. Tinbergen）1963 年在《On aims and methods of ethology》中把两个时间尺度各分两问，形成四个互补的问题：机制（mechanism）、个体发育（ontogeny）、系统发育（phylogeny）与适应功能（adaptive function）。四问的回答互不排斥、不可互相替代，只有四问都有答案，才算对一个行为给出完整解释。考试中给出一个现象要求\"分别从四个角度提问\"，必须严格区分\"如何发生\"（前两问）与\"为何存在\"（后两问）。层次问题归属以白冠带鹀鸣唱为例机制何种生理过程发动行为近因睾酮作用于 HVC，激发鸣肌运动程序个体发育行为在一生中如何形成近因幼鸟在敏感期模仿同种成鸟的曲目系统发育行为在类群演化中如何变化终极近缘种曲目结构可重建出共同祖先的方言适应功能行为如何提高适合度终极鸣唱宣示领域、吸引雌鸟，提高繁殖成功"},{"id":"2.3","t":"机制层次：神经、激素、基因与感觉","s":3,"c":"2. Tinbergen 四问：近因与终极原因","x":"机制研究追踪从刺激到反应的完整通路，包括感受器的选择性与阈值、中枢的整合与模式发生器、效应器的执行。蝗虫飞行由胸神经节的中央模式发生器（central pattern generator, CPG）产生节律输出，切断感觉输入后仍能维持基本节律，说明节律是\"内生\"的；蜜蜂工蜂的年龄分工（age polyethism）随保幼激素滴度升高而由巢内哺育转为外出采集，是激素调节行为转换的范例。答机制题时要写出\"感受—整合—输出\"三段，而不是只说\"由基因决定\"。"},{"id":"2.4","t":"个体发育层次：行为在一生中如何形成","s":3,"c":"2. Tinbergen 四问：近因与终极原因","x":"个体发育问的是行为从受精卵到成体的建构过程，强调基因与经验的交互。白冠带鹀（Zonotrichia leucophrys）幼鸟在孵出后约 10～50 天内必须听到同种成鸟的鸣唱才能学会正常的\"方言\"，错过该敏感期则学成异常曲目；人类语言的习得也有类似的时间窗。蜜蜂的发育研究显示，同日龄工蜂的职能可因群体年龄结构被人为改变而提前或推迟，说明发育程序具有可塑性，并非固定的时刻表。"},{"id":"2.5","t":"系统发育层次：行为的演化历史","s":2,"c":"2. Tinbergen 四问：近因与终极原因","x":"系统发育问的是行为在类群演化树上的起源、丢失与修饰，常用近缘种比较与\"行为特征映射到分子系统树\"的方法重建。鸥科鸟类的护巢攻击（mobbing）在多个近缘类群中都有表现，可推断该行为源自较近的共同祖先；织雀科鸟类的巢结构从简单杯状到复杂编织的系列，被用来重建筑巢行为的演化序列。这类研究的难点在于行为不能形成化石，必须借助\"遗痕行为\"（如化石足迹、钻孔痕迹）与近缘种比较间接推断。"},{"id":"2.6","t":"适应功能层次：行为如何提高适合度","s":3,"c":"2. Tinbergen 四问：近因与终极原因","x":"功能研究把行为视为一种表型性状，追问它在生存与繁殖上的收益与代价。莱克（D. Lack）关于窝卵数的假说认为，鸟类的窝卵数被自然选择调整到\"能养活的最大雏数\"，他在欧鸲与大三雀上的补卵、减卵实验支持了\"最适窝卵数\"的存在；廷伯根对黑头鸥（Larus ridibundus）移走破蛋壳行为的解释也是典型的功能假说：白亮的内壳面会暴露巢址、提高被乌鸦等捕食者发现的概率。功能假说必须能被检验，否则只是\"讲故事\"。"},{"id":"2.7","t":"四问的整合：以挖洞蜂为例","s":2,"c":"2. Tinbergen 四问：近因与终极原因","x":"阿尔科克（J. Alcock）研究荒漠独居蜂 Centris pallida 时发现，体形大的雄蜂在土表挖掘、把羽化中的雌蜂挖出后立刻交配，体形小的雄蜂则在已经挖开的洞口附近守候、伺机\"偷配\"。机制层面，两种雄蜂靠视觉与嗅觉定位雌蜂羽化点；发育层面，幼虫期的食量决定成体体型与所采用的策略；系统发育层面，近缘种中也存在同类二型策略；功能层面，大蜂与偷配者的繁殖成功在特定密度下大致相当。一个现象由四问共同支撑，正是整合性研究的范例。"},{"id":"2.8","t":"从四问到可检验假说：功能假说的检验策略","s":3,"c":"2. Tinbergen 四问：近因与终极原因","x":"功能假说要被接受，必须给出可反驳的预测并加以检验，常用三条路径。其一是观察相关：若破蛋壳确实招引捕食者，则巢区附近壳多的地方被捕食率应更高，实测确实如此。其二是比较：不同巢型的鸟类壳色与移壳行为的强弱应相匹配。其三是实验操纵：把真卵涂成白色或杂色分别放置，白卵被捕食率显著升高，这才真正区分了\"移壳是为了保持 camouflage\"与\"移壳是为了防止蛋滚出\"的竞争假说。竞赛中凡是出现\"某假说已被证明\"的表述，都要追问其预测与对照。"},{"id":"3.1","t":"达尔文：行为的比较研究与性选择","s":3,"c":"3. 动物行为学的学科发展史","x":"达尔文（C. Darwin）1872 年出版《人类和动物的情感表达》，用比较法论证人类的表情与动物的情绪表达同源，开创了行为进化的研究传统；1871 年《人类的由来及性选择》提出性选择（sexual selection）理论，解释孔雀尾屏、鹿角这类不利于生存却有利于繁殖的性状。达尔文的方法论遗产是\"把行为当作可遗传的表型，在系统树上比较\"，这一思路至今仍是行为进化的基本工具。"},{"id":"3.2","t":"法布尔与昆虫本能的早期观察","s":2,"c":"3. 动物行为学的学科发展史","x":"法布尔（J.-H. Fabre）以《昆虫记》记录了大量膜翅目昆虫的本能行为，如狩猎蜂把猎物麻痹后拖入巢、泥蜂按固定程序封巢。他的贡献在于揭示本能的刻板性与\"盲目性\"：当实验者移动猎物位置，蜂仍按固定顺序完成后续动作。局限在于他倾向于用拟人化语言解释行为，缺少对照实验，因此其结论多需后人重新检验。"},{"id":"3.3","t":"比较心理学派：从桑代克到斯金纳","s":3,"c":"3. 动物行为学的学科发展史","x":"北美比较心理学派（comparative psychology）以实验室研究为主，关注学习的一般规律。桑代克（E. Thorndike）用迷箱研究猫的试错学习，提出效果律；巴甫洛夫（I. Pavlov）建立经典条件反射；斯金纳（B. F. Skinner）建立操作条件反射与强化程序，用鸽子、大鼠做出大量精细的行为控制实验。该学派的贡献是把行为量化、把学习机制化，局限是物种单一、环境简化，容易忽视行为的进化历史与生态背景。"},{"id":"3.4","t":"冯·弗里施与蜜蜂舞蹈通讯","s":3,"c":"3. 动物行为学的学科发展史","x":"冯·弗里施（K. von Frisch）用玻璃观察巢、标记蜜蜂、训练到指定饲喂点的方法，破译了蜜蜂的舞蹈语言：食物在近处时跳圆舞（round dance），较远时跳摆尾舞（waggle dance），摆尾阶段的持续时间编码距离，摆尾轴线相对于重力垂线的夹角编码相对于太阳方位的方向。他还证明蜜蜂能辨别颜色与偏振光、具有\"时间记忆\"（定时到饲喂点）。他因这项研究与洛伦茨、廷伯根共同获得 1973 年诺贝尔生理学或医学奖，是行为学史上唯一一次以行为学研究获奖。"},{"id":"3.5","t":"洛伦茨与本能理论、印随现象","s":3,"c":"3. 动物行为学的学科发展史","x":"洛伦茨（K. Lorenz）通过灰雁的印随（imprinting）实验确立了\"关键期\"概念：孵出后数十小时内看到的移动物体被固定为\"母亲\"，此后不可逆，且性印记会影响成年后的择偶对象。他提出本能行为的四个特征：先天具备、种特异、由特定信号刺激触发、具有自发冲动（action-specific energy）。他与廷伯根共同奠定了经典行为学（ethology）的理论框架，代表作《所罗门王的指环》也是行为学的通俗经典。"},{"id":"3.6","t":"廷伯根与实验行为学的建立","s":3,"c":"3. 动物行为学的学科发展史","x":"廷伯根（N. Tinbergen）把行为学从描述推进到实验阶段。他与学生用硬纸卡模型研究雏银鸥的啄击反应，发现\"红色斑点 + 细长形状 + 下倾姿态\"是触发啄击的关键特征，进一步做出\"超常刺激\"（supernormal stimulus）：三根红条纹的细长棒比真鸟喙更能引发啄击；他用蜡质红腹模型证明三刺鱼雄鱼攻击的是\"红色腹部\"这一信号，而非\"入侵的雄鱼\"本身。他的四问框架与《动物的社会行为》一书成为此后行为学的共同语言。"},{"id":"3.7","t":"汉密尔顿与广义适合度、亲缘选择","s":3,"c":"3. 动物行为学的学科发展史","x":"汉密尔顿（W. D. Hamilton）1964 年提出广义适合度（inclusive fitness）与亲缘选择（kin selection），给出著名的 Hamilton 法则 rB >C：只要受益者的收益 B 乘以亲缘系数 r 大于利他者的代价 C，编码利他行为的基因就能在群体中扩散。他用膜翅目的单倍二倍体（haplodiploidy）解释工蜂不育现象：姐妹间亲缘系数为 3/4，母女间仅 1/2，故工蜂帮助母亲抚养妹妹比自己生育更\"划算\"。这一理论把利他行为纳入自然选择框架，是行为学最重要的理论革命。"},{"id":"3.8","t":"特里弗斯与互惠利他、亲代投资、亲子冲突","s":3,"c":"3. 动物行为学的学科发展史","x":"特里弗斯（R. Trivers）在 1971—1974 年间连续提出三个奠基性概念。互惠利他（reciprocal altruism）指出非亲属间的利他可在\"日后得到回报\"的条件下进化，需具备长期重复互动、个体识别与欺骗惩罚三个条件；亲代投资（parental investment）理论说明两性因初始投资差异而在择偶、竞争策略上分化；亲子冲突（parent–offspring conflict）指出亲代与子代对\"断乳时间\"的最适点不同，因而在哺乳后期必然出现对抗性行为，如哺乳动物的断乳期\"讨价还价\"。"},{"id":"3.9","t":"社会生物学与行为生态学的兴起","s":2,"c":"3. 动物行为学的学科发展史","x":"威尔逊（E. O. Wilson）1975 年《社会生物学》系统整合了利他、社群、分工的进化解释，引发激烈争论（尤其关于人类行为的遗传决定程度）；克雷布斯与戴维斯（Krebs & Davies）1978 年起的行为生态学教科书把最优性模型、ESS、博弈论引入行为研究。中国方面，尚玉昌 2005 年出版《动物行为学》，是国内第一部系统教材，此后又著《行为生态学》，成为国内竞赛命题的主要依据之一。"},{"id":"4.1","t":"野外观察的基本原则","s":3,"c":"4. 观察法、实验法与比较法","x":"观察是行为研究的第一手段，三条原则必须遵守。其一是熟悉研究对象并长期跟踪，如对非洲狮、狒狒的个体识别研究往往需要数年；其二是尽量不被动物觉察，可采用隐蔽帐、伪装、让动物习惯化（habituation）或使用自动摄像；其三是个体识别，可借助自然特征（斑纹、角形）或人为标记（环志、剪趾、无线电颈圈）。忽略个体识别，就无法区分\"群体中谁做了什么\"，许多早期结论因此被推翻。"},{"id":"4.2","t":"行为取样方法","s":3,"c":"4. 观察法、实验法与比较法","x":"按记录目的可分为四种取样：随意取样（ad libitum）不做限制、用于初步描述；焦点动物取样（focal sampling）连续记录一个个体一段时间内的全部行为，适合计算时间预算；扫描取样（scan sampling）按固定间隔快速记录群体中每个个体的即时状态，适合群体活动节律；全事件取样（alloccurrence sampling）记录某类特定事件的全部发生，适合研究攻击、交配等稀有而重要的事件。取样方法必须与研究问题匹配，否则数据无法回答提出的问题。取样方法记录对象优点局限与适用随意取样不限便于建立行为谱无法定量，只能作预观察焦点取样单个个体连续可得完整行为序列与时间预算一次只能看一个个体扫描取样全群瞬时状态高效获得群体活动节律易漏掉短暂事件全事件取样特定事件全部稀有事件数据完整需先明确事件定义"},{"id":"4.3","t":"行为记录技术与新型手段","s":2,"c":"4. 观察法、实验法与比较法","x":"现代行为研究大量借助技术手段：红外触发相机与无人机用于隐蔽物种的分布与活动节律；GPS/北斗项圈与地理定位仪（geolocator）揭示迁徙路线与停歇地；加速度计（actigraphy）可判断休息、飞行、潜水的比例；无线电遥测用于小型兽类与鸟类的家域测算；声谱分析（spectrogram）把鸟鸣、鲸歌转成可视的频率—时间图，用于个体识别与方言比较。技术手段改变了数据密度，但不改变研究逻辑：仍须先明确行为定义与测量单位。"},{"id":"4.4","t":"实验法：控制变量与模型实验","s":3,"c":"4. 观察法、实验法与比较法","x":"实验法的核心是主动操纵自变量并设置对照。常用手段包括模型替换（用硬纸卡、蜡质模型、3D 打印假体替换活体）、回放实验（playback，播放不同鸣声观察反应）、假体操纵（给雏鸟装不同颜色的喙）、去除实验（切除或遮蔽某一感觉通道）。廷伯根用纸卡模型分离出\"红点\"这一关键特征，就是通过系统变化颜色、形状、位置并观察啄击频率实现的；现代鸟鸣研究用回放实验证明雌鸟偏好复杂曲目与低频率鸣唱。"},{"id":"4.5","t":"比较法：从近缘种差异推断进化","s":3,"c":"4. 观察法、实验法与比较法","x":"比较法通过比较不同物种（或同一物种不同种群）在同一行为上的差异，结合它们的系统关系推断行为的演化路径与适应意义。三刺鱼的不同种群在捕食压力不同的水体中，求偶炫耀的强度与体色鲜艳度不同；岛屿鸟类因捕食者缺失而丧失惊飞反应，被引入捕食者后又可恢复，这类\"自然实验\"是比较法的典型素材。比较法必须建立在可靠的系统树上，否则\"相似\"可能来自趋同而非共同祖先。"},{"id":"4.6","t":"系统发育比较分析与独立对比","s":2,"c":"4. 观察法、实验法与比较法","x":"传统比较法的问题是物种不被视为独立数据点：亲缘相近的物种往往性状相似，直接做相关统计会高估适应性关联。系统发育独立对比（phylogenetically independent contrasts, PIC）通过计算系统树上每一对姐妹节点的差值，把数据转换为相互独立的对比值再做回归。研究灵长类脑容量与群体大小的关系、鸟类巢寄生与卵色的关系时，是否做系统发育校正往往得出完全不同的结论，这是现代行为生态学的方法底线。"},{"id":"4.7","t":"假说—演绎法与竞争假说的区分","s":3,"c":"4. 观察法、实验法与比较法","x":"行为研究的标准流程是：观察现象、提出若干可替代假说、由每个假说推出不同的可检验预测、设计能区分预测的实验或观察、据结果保留或否证假说。移走破蛋壳至少有三种解释（保持伪装、防止蛋滚出巢、减少巢内寄生虫），廷伯根通过\"白卵 vs 杂色卵被捕食率\"的实验区分出伪装假说。答题时写出\"若…则…\"的预测句，是拿满分的关键。"},{"id":"4.8","t":"交叉抚育、交叉收养与共同花园实验","s":2,"c":"4. 观察法、实验法与比较法","x":"要区分遗传与环境的作用，常用交叉抚育（cross-fostering）：把一种鸟的卵换给另一种鸟孵育，若子代行为随养父母改变则说明经验重要，若仍表现生父母特征则说明遗传重要。共同花园实验（common garden）把不同种群个体放在同一环境中饲养，以排除环境差异；交互移植实验把个体互换到对方生境，检验局域适应。黑顶莺（blackcap）的迁徙方向研究显示，笼养条件下未经迁徙经历的个体仍表现特定朝向的\"迁徙不安\"（Zugunruhe），说明方向性有强烈遗传基础。"},{"id":"4.9","t":"数据的统计处理与常见陷阱","s":2,"c":"4. 观察法、实验法与比较法","x":"行为数据多为计数或比例，常不满足正态假设，需用非参数检验或广义线性模型；同一动物反复测量属于重复测量，不能当作独立样本；个体差异往往大于处理效应，需要大样本个体数而非仅大样本次数。此外要警惕拟人化（anthropomorphism）与目的论（teleology）表述，如\"蚂蚁为了群体的利益而牺牲自己\"应为\"该行为在特定条件下提高了广义适合度\"。竞赛简答题中若出现目的论句子，通常要扣分。"},{"id":"5.1","t":"行为谱的概念与作用","s":3,"c":"5. 行为谱、行为记录与动物伦理","x":"行为谱（ethogram）是一个物种或一个个体全部正常行为的完整名录，每一行为条目应有明确的形态描述与判定标准。行为谱是定量研究的前提：只有先定义\"攻击\"从何开始到何结束，才能统计攻击次数与持续时间。编制良好的行为谱还可用于近缘种比较，为行为系统发育提供性状矩阵。"},{"id":"5.2","t":"行为谱的编制步骤","s":2,"c":"5. 行为谱、行为记录与动物伦理","x":"编制一般分四步：（1）预观察，用随意取样记录所有可见动作并录像；（2）切分与归类，按形态特征把连续动作切分为离散单元，去除重复与过渡态；（3）定义操作标准，写明每种行为的起止标志、身体部位与姿态；（4）信度检验，由两名观察者独立编码同一批录像，计算一致率，一般要求 Kappa值达 0.8 以上。缺少信度检验的行为谱，其后续统计结果不可靠。"},{"id":"5.3","t":"行为分类的形态标准与功能标准","s":2,"c":"5. 行为谱、行为记录与动物伦理","x":"行为可按形态（motor pattern）分类，如\"啄\"\"抓\"\"跳跃\"，客观可辨；也可按功能（function）分类，如\"觅食\"\"防御\"\"求偶\"\"育幼\"。同一动作在不同情境下功能不同，如雏鸟的\"啄\"在求食与攻击中都用；同一功能可由不同动作实现，如多种鸟类用不同方式整理羽毛。规范做法是以形态为基本单位、以功能为归类框架，两者并用并在方法中说明。"},{"id":"5.4","t":"行为谱实例：三刺鱼的繁殖行为谱","s":3,"c":"5. 行为谱、行为记录与动物伦理","x":"三刺鱼繁殖期雄鱼的行为可依次列为：占据领域（territory takeover）、驱赶入侵者（chasing）、收集巢材（gluing）、钻巢（creeping through）、形成婚装（nuptial coloration）、之字舞（zigzag dance）、引向巢口（leading）、授精（fertilization）、扇卵（fanning）、护卵（guarding）。这套行为谱的优点是每个条目都有明确触发条件与外部形态，可直接用于回放与模型实验，也是尚玉昌教材反复引用的范例。"},{"id":"5.5","t":"时间预算与行为量化指标","s":3,"c":"5. 行为谱、行为记录与动物伦理","x":"时间预算（time budget）指一个个体在观察期内各行为类别所占时间比例，常用焦点取样计算。除时间外，常用指标还有发生频次（frequency）、持续时间（duration）、潜伏期（latency）、强度（intensity，如啄击速率）与事件顺序（sequence）。研究觅食与警戒的权衡时，常计算\"每次抬头之间的取食时长\"，以此衡量捕食风险与能量收益的平衡，如岩松鼠在人为逼近时的取食间隔显著缩短。"},{"id":"5.6","t":"动物伦理的三 R 原则","s":3,"c":"5. 行为谱、行为记录与动物伦理","x":"涉及脊椎动物的实验须遵循三 R 原则：替代（Replacement，尽量用无脊椎动物、细胞或模型替代活体脊椎动物）、减少（Reduction，用合理设计与统计把动物用量降到最低）、优化（Refinement，改进操作与饲养以减轻痛苦）。教学中使用活体动物还需遵守\"不造成痛苦\"的底线，如观察蚯蚓趋性时用湿润滤纸而非针刺。"},{"id":"5.7","t":"动物福利与\"五大自由\"","s":2,"c":"5. 行为谱、行为记录与动物伦理","x":"动物福利（animal welfare）关注动物在饲养与实验条件下的心理与生理状态，英国农场动物福利委员会提出的\"五大自由\"是通行标准：免于饥渴、免于不适、免于疼痛伤害与疾病、免于恐惧与焦虑、享有表达天性的自由。养殖场中母猪的刻板行为（stereotypy，如空嚼、咬栏）正是\"表达天性的自由\"被剥夺的行为学指标，也是行为学应用于生产的直接证据。"},{"id":"5.8","t":"野外研究的伦理与法规","s":2,"c":"5. 行为谱、行为记录与动物伦理","x":"野外研究的原则是\"观察不干扰、捕捉最小化\"。具体包括：不接近巢区以免引起弃巢（猛禽与燕鸥尤其敏感）、夜间照明与回放实验须控制时长与强度、环志与标记须由持证人员操作并定期复查、濒危物种研究须取得许可、避免引入外来物种与病原。行为学研究对保护的最大贡献之一是识别\"人为干扰的阈值距离\"，如为保护区设定观鸟与观鲸的最小接近距离。第二篇 行为的遗传与进化"},{"id":"6.1","t":"行为遗传学的核心问题与遗传力","s":3,"c":"6. 行为的遗传基础","x":"行为遗传学研究行为差异中由遗传决定的部分，核心问题是\"某一行为特征的变异有多少可归因于基因差异\"。遗传力（heritability, h²）指在特定群体的表型变异中由遗传变异解释的比例，是一个群体统计量，随环境与群体而变，绝不能说\"某行为有 60% 由基因决定\"。研究还须区分基因型适应（可遗传，如天蛾幼虫的趋光爬行）与表现型适应（个体一生中获得的适应性反应，如鸥类学会识别自己的卵），前者可进化，后者不能直接传给后代。"},{"id":"6.2","t":"评估遗传决定性的常用方法","s":3,"c":"6. 行为的遗传基础","x":"判断行为是否有遗传基础，常用五类方法：（1）人工选择实验，若按行为指标连续选择若干代能得到分化品系，则遗传变异存在；（2）杂交实验，观察F1、F2 与回交后代的分离比，推断基因数目与显隐性；（3）交叉抚育，分离生父母与养父母的影响；（4）同卵双生与寄养分析，用于人类与灵长类；（5）分子手段，寻找与行为相关的基因位点。单一方法往往不足以定论，规范研究需两种以上方法互证。方法做法能得出的结论经典实例人工选择按行为指标选育多代遗传变异存在、可快速响应选择Tryon 明暗大鼠迷宫品系杂交F1、F2、回交分离比基因数目、显隐性蜜蜂卫生行为的两位点模型交叉抚育卵或幼体互换抚养区分遗传与经验黑顶莺迁徙方向隔离饲养隔绝学习机会行为是否先天具备灰雁滚蛋、椋鸟捕虫分子定位关联分析、基因编辑具体基因与神经机制果蝇 period 基因"},{"id":"6.3","t":"单基因效应与行为的遗传结构","s":2,"c":"6. 行为的遗传基础","x":"少数行为差异确实由单一位点主导，但多数行为是多基因性状。单基因效应的经典例子是蜜蜂的卫生行为（hygienic behavior）：工蜂先咬开含病死幼虫的蜡盖（由隐性位点 u 控制），再把幼虫拖出巢房（由隐性位点 r 控制），只有两个位点同时隐性纯合时才表现完整个体卫生行为，Rothenbuhler 的杂交实验给出了清晰的分离比。果蝇的 period（per）基因影响昼夜节律与求偶鸣唱的节律，per 突变会同时改变羽化时刻与鸣唱周期，说明一个基因可多效地影响多种行为。"},{"id":"6.4","t":"黑顶莺迁徙方向的遗传基础","s":3,"c":"6. 行为的遗传基础","x":"黑顶莺（Sylvia atricapilla）欧洲种群秋季迁徙方向存在稳定的种群差异：中欧种群向西南（经意大利、西班牙），东欧种群向东南。Berthold 把两组鸟在完全隔离、从未见过迁徙的条件下笼养，秋季仍出现定向的\"迁徙不安\"（Zugunruhe），且笼中定向与亲代一致；杂交子代的定向介于两亲本之间，F2 出现分离。这组结果同时证明了迁徙方向与迁徙冲动具有强烈遗传基础、由多基因控制，并且可以快速进化（实验室内选择数代即出现定向改变）。"},{"id":"6.5","t":"基因影响行为的生理途径","s":2,"c":"6. 行为的遗传基础","x":"基因并不直接\"编码行为\"，而是通过影响感觉器官、神经回路、激素合成与代谢酶来改变行为。蜜蜂的 for 基因（foraging）编码 cGMP 依赖的蛋白激酶，表达量高的工蜂更早外出采集、对蔗糖的敏感度更高；小鼠的 fosB 基因缺失会导致母性育幼行为严重缺陷；狗的 DRD4 基因多态性与探索性、冲动性相关。理解这一\"基因—蛋白—神经元—行为\"的链条，才能在题目给出具体基因时推出正确的行为表型。"},{"id":"6.6","t":"人工选择实验：从大鼠迷宫到银狐驯化","s":3,"c":"6. 行为的遗传基础","x":"Tryon 从 1940 年代起按\"迷宫中犯错误次数\"选育大鼠，经多代得到\"迷宫聪明\"与\"迷宫迟钝\"两个品系，证明学习能力有可加性遗传变异。更著名的是苏联 Belyaev 自 1959 年起对银狐的驯化选择：只按\"对人是否温顺\"一个标准选育，四十代后出现了攻击性下降、尾部卷曲、花斑毛色、耳朵下垂、繁殖季节延长等一整套\"驯化综合征\"。这说明选择单一行为性状会因基因多效性而带出一系列形态与生理变化，也是\"行为驯化先于形态驯化\"的重要证据。"},{"id":"6.7","t":"行为的遗传力测定与解释","s":2,"c":"6. 行为的遗传基础","x":"遗传力常用同胞分析、亲子回归或选择响应（R = h²S，即选择响应等于遗传力乘选择差）估计。若某行为 h² 很高，说明该群体中该行为的变异主要由遗传决定，对环境改变响应较慢；h² 低则说明环境方差大、表型可塑性强。要注意 h² 不是固定常数：在环境条件均一的实验室中 h² 往往偏高，在野外异质环境中偏低，这是\"遗传力依赖于环境\"的经典现象。"},{"id":"6.8","t":"基因—环境交互与反应规范","s":3,"c":"6. 行为的遗传基础","x":"同一基因型在不同环境下可表现不同的行为表型，其函数关系称反应规范（reaction norm）。刺鱼的护卵攻击强度、大鼠的应激反应、人类儿童的攻击性都表现出明显的基因—环境交互，即不同基因型对环境变化的敏感度不同。竞赛题中若给出\"某行为在不同饲养条件下差异显著\"的数据，正确结论通常是\"行为受环境影响，且遗传基础决定了反应的范围与敏感度\"，而不是\"该行为与基因无关\"。"},{"id":"6.9","t":"行为的遗传基础与保护应用","s":1,"c":"6. 行为的遗传基础","x":"圈养繁殖与再引入常遇到\"行为遗传基础被削弱\"的问题：人工环境下失去天敌，选择压力改变，胆大、不怕人的个体更易存活繁殖，数代后群体丧失反捕食行为。美洲的麝牛、澳洲的兔耳袋狸都出现过再引入后因缺乏反捕食经验而大量死亡的情况，因此现代再引入项目强调\"行为训练\"（如用模型天敌训练幼体）与亲本选择。"},{"id":"7.1","t":"本能行为的定义与判别特征","s":3,"c":"7. 本能与固定动作模式","x":"本能（instinct）指先天具备、由特定刺激触发、在种内表现一致、且不经学习即可完整执行的行为。洛伦茨归纳出四个特征：先天遗传、种特异性、由信号刺激触发、具有自发冲动与阈值变化。判别一个行为是否为本能，常用\"隔离饲养实验\"（Kaspar Hauser experiment）：把幼体单独饲养、隔绝学习机会，若仍能表现该行为，即可判定为本能，如雏鸥的啄击、蜘蛛结网、蜜蜂筑巢。"},{"id":"7.2","t":"固定动作模式（FAP）","s":3,"c":"7. 本能与固定动作模式","x":"固定动作模式（fixed action pattern, FAP）是本能的执行单元，是一段高度刻板、一旦启动便趋于完成、不轻易被外部反馈打断的动作序列。FAP 有两个关键性质：其一是\"全或无\"式启动，阈值达到即整段执行；其二是\"完成倾向\"，即使目标已消失仍会做完，如灰雁滚蛋时蛋被取走仍把空气滚回巢。FAP不受即时结果校正，这一点使它区别于工具性学习行为。"},{"id":"7.3","t":"FAP 的判据与典型实例","s":3,"c":"7. 本能与固定动作模式","x":"判定 FAP 需同时满足三个条件：动作形态可被清晰辨认且种内一致；由特定的简单刺激（信号刺激）触发；在刺激被移除后仍完成动作。经典实例有三：灰雁把滚出巢的蛋用喙内侧推回巢的\"滚蛋\"动作（蛋被中途拿走仍做完）；雏银鸥对亲鸟下喙红点的啄击（用硬纸卡即可触发）；蟾蜍对横穿视野的细长物体弹出舌头的捕食反应（只对沿长轴移动的物体有效）。"},{"id":"7.4","t":"本能行为的等级组织与冲动","s":2,"c":"7. 本能与固定动作模式","x":"本能行为常按层级组织：一个总倾向（如繁殖）下分若干阶段（占域、筑巢、求偶、护卵），每阶段由不同刺激触发，最终落实为 FAP。洛伦茨用\"心理流体\"（action-specific energy）比喻动机的积累，认为能量积累到阈值以上即使无刺激也会表现空放行为，遇到适当刺激则\"溢流\"完成动作。现代研究用\"动机—阈值\"模型取代了流体隐喻，但阈值随动机升降这一事实仍被广泛接受，如饥饿的椋鸟对红色模型的啄击率显著高于饱食个体。"},{"id":"7.5","t":"固定动作模式与趋性的区别","s":3,"c":"7. 本能与固定动作模式","x":"FAP 与趋性（taxis）常被混淆，区别有三：（1）FAP 是一段有固定时序的动作程序，趋性是持续朝向或背离刺激的定向运动；（2）FAP 由信号刺激\"触发\"后自主完成，趋性依赖持续的刺激输入不断校正方向，去掉刺激即停止；（3）FAP 的完成不依赖反馈，趋性必须依赖反馈。例如雏鸥的啄击是FAP（啄中红点后即完成吞食反应），而蛾类保持与月光固定角度的飞行是横定向；若把光源换成近处的灯，蛾因无法保持固定角度而螺旋撞灯，正说明趋性需要连续反馈。这是历年联赛中区分度最高的一道辨析。"},{"id":"7.6","t":"本能并非绝对僵硬","s":3,"c":"7. 本能与固定动作模式","x":"FAP 的\"刻板\"是指动作形态，不是指行为完全不能调整。研究发现 FAP 的触发阈值可随经验改变，执行过程也常被感觉反馈修饰：织雀的筑巢被归为高度本能，但幼鸟第一次筑巢常失败、第二三次逐渐规范，说明本能程序需要在发育中\"校准\"。因此现代行为学更强调\"本能与学习的连续谱\"，而不是把行为切成\"先天\"与\"后天\"两类（详见第 19 章）。"},{"id":"7.7","t":"学习本能（instinct to learn）","s":2,"c":"7. 本能与固定动作模式","x":"某些看似学习的行为实际上是\"被遗传程序规定的学习内容\"，称学习本能。白冠带鹀幼鸟必须在敏感期内听到同种鸣唱才能学会正常曲目，且只能在有限的时间窗内学、只倾向于学同种的曲目，这是一种\"被引导的学习\"（guided learning）。同理，松鼠的埋藏行为、蜜蜂对花形与颜色的偏好，都是遗传规定了\"学什么、何时学、学到什么程度\"。"},{"id":"7.8","t":"隔离饲养与\"卡斯帕·豪泽\"实验的设计","s":2,"c":"7. 本能与固定动作模式","x":"隔离饲养实验用于剥离学习效应，但设计上有三个必须控制的因素：隔离必须彻底（听觉、视觉、社会接触）、必须与正常个体做同龄对照、必须排除母体效应与饲养环境的非特异性影响。早期对\"猴子怕蛇\"的研究显示，实验室饲养的猕猴起初不怕蛇，但看到同伴的恐惧反应后即学会怕蛇，说明某些\"本能恐惧\"其实需要社会学习。这类结果提醒：隔离实验的阴性结果（隔离后仍表现）比阳性结果更有说服力，阳性结果往往意味着\"需要某种经验\"。"},{"id":"8.1","t":"关键刺激与信号刺激","s":3,"c":"8. 信号刺激与释放者","x":"在触发某一行为的所有刺激中，只有少数几个特征真正起作用，这些起决定作用的特征称关键刺激（key stimulus）；当关键刺激被简化、夸张或人工模拟后仍能有效触发行为时，这个简化刺激称信号刺激（sign stimulus）。雏银鸥啄击亲鸟喙的关键刺激是\"下喙的红色斑点 + 喙的细长轮廓 + 亲鸟头向下倾\"；三刺鱼雄鱼攻击入侵者的关键刺激是\"腹部的红色\"。信号刺激的概念把\"复杂对象\"压缩为\"少数特征\"，是行为学研究刺激—反应关系的核心工具。"},{"id":"8.2","t":"刺激过滤机制","s":3,"c":"8. 信号刺激与释放者","x":"动物并非被动接收全部刺激，而是通过外周过滤（感受器只对特定频率、波段敏感）与中枢过滤（脑内\"注意\"机制抑制无关输入）筛出关键特征。蛙的视网膜神经节细胞中有专门的\"昆虫探测器\"（bug detector），只对沿长轴运动的小物体产生强反应，对静止或大范围移动的物体不反应；夜蛾的听觉神经元对蝙蝠超声波的高频扫描特别敏感。刺激过滤使动物能在复杂环境中快速做出判断，代价是可能被\"伪造的特征\"欺骗。"},{"id":"8.3","t":"释放者与仪式化","s":3,"c":"8. 信号刺激与释放者","x":"释放者（releaser）是进化形成的、专门用于传递信息的信号结构或动作，如雄性孔雀的尾屏、三刺鱼的红色婚装、鸥类雏鸟的橙色喙、萤火虫的闪光节律。释放者多由日常动作经仪式化（ritualization）演化而来：原本具有实用功能的动作（如理羽、取食、筑巢）在求偶情境中重复出现，逐步夸张、简化、定型，最终失去原功能而成为纯信号，如灰雁的\"胜利仪式\"源自威胁动作的组合。"},{"id":"8.4","t":"超常刺激","s":3,"c":"8. 信号刺激与释放者","x":"超常刺激（supernormal stimulus）是超出自然刺激范围的夸张信号，能引发比天然刺激更强的反应。廷伯根用一根细长的红色木棒、末端画三条白环，发现雏银鸥对它的啄击频率高于真实亲鸟的喙；灰雁偏好比自己蛋更大更圆的模型蛋，甚至把排球般大的假蛋往巢里拖；某些鸣禽偏好回放中比自然曲目更长、更复杂的歌声。超常刺激证明动物对信号的\"评价\"是按特征强度而非按\"真实性\"进行的，这也解释了人类对高糖高脂食物的偏好。刺激类型定义实例关键刺激触发行为所必需的特征银鸥下喙红点、刺鱼红色腹部信号刺激简化或人工模拟的关键刺激硬纸卡上的红点条带释放者进化形成的专门信号结构孔雀尾屏、雏鸟橙色喙超常刺激超出自然范围的夸张信号三环红棒、巨型模型蛋"},{"id":"8.5","t":"刺激累积与阈下刺激总和","s":2,"c":"8. 信号刺激与释放者","x":"行为的释放不一定依赖单一刺激达到阈值，多个阈下刺激可以累积并共同触发行为，称刺激累积（stimulus summation）。雄性刺鱼同时看到红色腹部与入侵者靠近巢口时，攻击强度大于单独呈现任一刺激；雌性蟋蟀对鸣声的偏好随鸣叫时长与强度的累积而提高。这一原理说明\"释放者\"的作用是概率性的，行为输出是连续量而非开关量，答题时应避免\"有刺激就一定有行为\"的绝对化表述。"},{"id":"8.6","t":"释放者的欺骗性利用","s":3,"c":"8. 信号刺激与释放者","x":"由于反应由信号而非\"真实意图\"驱动，释放者可被其他物种\"盗用\"。杜鹃把卵产在大苇莺巢中，其卵的花纹模拟寄主卵，而孵出的杜鹃雏鸟具有鲜艳的橙红色张口与乞食叫声，构成超常刺激，使寄主超量喂食、甚至把亲生雏鸟挤出巢外；澳洲的光萤科甲虫 Photuris 雌虫模仿 Photinus 雌虫的闪光节律，诱来雄虫后捕食。这是\"信号—反应\"系统必然被利用的证明，也是共进化军备竞赛的经典素材。"},{"id":"8.7","t":"先天释放机制（IRM）","s":2,"c":"8. 信号刺激与释放者","x":"先天释放机制（innate releasing mechanism, IRM）指从接收到关键刺激到发动 FAP 之间的神经环节，其作用相当于\"特征检测器 + 阈值门\"。初孵的雏鸥对红色斑点做出啄击，说明 IRM 无需学习即可工作；但随着经验积累，雏鸟会逐渐偏好自己亲鸟的喙形与头部特征，说明 IRM 之上叠加了学习成分。IRM 概念的价值在于把\"先天\"落到具体的神经机制上，而非笼统归为\"本能\"。"},{"id":"8.8","t":"人类的释放者与\"可爱反应\"","s":1,"c":"8. 信号刺激与释放者","x":"人类同样对特定信号高度敏感：婴儿的大头、圆脸、大眼睛构成一套释放者，能引发成人的照料与微笑反应，这被称为\"可爱反应\"（baby schema），实验表明把成人照片的婴儿化特征加强后，被试更愿意照料并评价其\"更可爱\"。人类对蛇、蜘蛛的快速恐惧学习、对面孔的优先加工，也被视为具有先天基础的注意偏向，但具体表达强烈受文化经验调节。"},{"id":"9.1","t":"行为进化的证据来源","s":3,"c":"9. 行为的进化与比较系统发育","x":"行为不能形成化石，其进化证据来自五类间接材料：（1）化石与遗痕行为，如恐龙足迹显示群居与奔跑速度、贝壳上的钻孔显示捕食策略；（2）行为个体发育的重演，如幼体保留祖先行为特征；（3）遗痕行为（vestigial behavior），如家养动物保留已无功能的祖先动作；（4）驯化与人工选择造成的快速变化；（5）近缘种比较与行为特征在系统树上的映射。其中近缘种比较是最主要的路径。"},{"id":"9.2","t":"行为的适应辐射","s":3,"c":"9. 行为的进化与比较系统发育","x":"适应辐射指同一祖先在不同环境中分化出多样的行为与形态，加拉帕戈斯地雀是经典：不同岛屿的种子大小与硬度不同，地雀的喙形与取食行为随之分化，粗喙者咬碎硬籽、细喙者啄食小籽或吸蜜。1977 年大旱后，达夫尼岛的中地雀因小籽耗尽而只余大硬籽，喙深较大的个体存活率显著更高，两年内群体平均喙深增加约 4%，是\"自然选择在野外可被直接观测\"的最著名证据。"},{"id":"9.3","t":"行为的趋同进化","s":2,"c":"9. 行为的进化与比较系统发育","x":"亲缘关系远的类群在相似环境中可演化出相似行为，称趋同进化。欧亚的莺类与夏威夷的蜜旋木雀（Drepanidinae）在彼此隔离的群岛上分别演化出取食昆虫、吸蜜、咬碎硬籽的多种喙形与相应取食行为，形态与行为高度相似却并非近亲；新世界的蜂鸟与旧世界的太阳鸟都演化出悬停吸蜜的行为与相应的翅型。趋同是\"环境塑造行为\"的最强证据，但在做比较分析时必须与共同祖先的影响区分开。"},{"id":"9.4","t":"仪式化的过程","s":3,"c":"9. 行为的进化与比较系统发育","x":"仪式化一般经历三步：原本具有实用功能的动作在冲突或求偶情境中反复出现（意图动作，intention movement）；该动作被同伴注意并被自然选择强化；动作被夸张、简化、定型，并发展出专门的支持结构（如鲜艳色彩、羽饰）。绿头鸭的\"以喙理背部羽毛\"动作演化为求偶中的\"抖羽炫耀\"，犬科动物的威吓动作来自攻击与退缩两种倾向的冲突，都是意图动作仪式化的典型。"},{"id":"9.5","t":"遗痕行为与\"丢失的进化\"","s":2,"c":"9. 行为的进化与比较系统发育","x":"遗痕行为是已失去原有功能但仍被保留的祖先行为，如家鸡仍做短距离飞行前的热身动作、家养豚鼠仍表现逃逸前的惊跳。行为也可以\"丢失\"：岛屿上缺乏捕食者的鸟类常丧失惊飞反应，达尔文在加拉帕戈斯观察到鹰不怕人、可直接用手抓住，此类行为一旦丢失，在引入捕食者（猫、鼠、蛇）后往往导致种群崩溃。这说明行为性状的维持依赖选择压力的持续存在。"},{"id":"9.6","t":"行为进化的速率与镶嵌进化","s":2,"c":"9. 行为的进化与比较系统发育","x":"行为可以进化得很快：银狐的驯化在四十代内完成，黑顶莺的迁徙方向在实验室内数代即可改变，城市鸟类对人工光源、噪声的适应在数十年内出现（如城市大山雀更早鸣唱、频率更高以避开低频噪声）。同时，\"镶嵌进化\"（mosaic evolution）指不同行为特征以不同速率进化，如求偶炫耀的形态已大变而筑巢动作仍保守，因此不能假设一套行为整体同步演化。"},{"id":"9.7","t":"适应价值的检验：比较与实验并用","s":3,"c":"9. 行为的进化与比较系统发育","x":"判定一个行为是否具有适应价值，需要三条证据链：该行为在自然情境中确实提高存活或繁殖（功能证据）；该行为在近缘种中与生态条件相关（比较证据）；操纵该行为或条件后适合度随之改变（实验证据）。燕科鸟类的巢型（洞巢 vs 开放式）与巢寄生率、雏鸟存活率相关，而人为改变巢型可改变被捕食率，这类研究把三条链凑齐，说明巢型选择具有适应意义。"},{"id":"9.8","t":"个体适合度与广义适合度","s":3,"c":"9. 行为的进化与比较系统发育","x":"个体适合度（direct fitness）指个体通过自身繁殖贡献给下一代的基因量；广义适合度（inclusive fitness）还包括通过帮助亲属繁殖而间接传递的基因量（indirect fitness）。汉密尔顿指出，自然选择最大化的不是个体繁殖数而是广义适合度，这解释了不育工蜂、帮助者（helper）与警报呼叫等看似\"自我牺牲\"的行为。计算时常用 r 表示亲缘系数：亲子、全同胞 0.5（膜翅目姐妹 0.75），祖孙、半同胞 0.25，表亲 0.125。"},{"id":"9.9","t":"行为的进化特征","s":2,"c":"9. 行为的进化与比较系统发育","x":"具有进化基础的行为通常表现出三个特征：种特异性（近缘种相似但可区分）、适应性（在自然情境中提高适合度）、可遗传性（存在遗传变异并响应选择）。不具备这三点的行为差异往往是个体经验或环境造成的短期调整。答题时把这三条作为\"该行为是否为进化产物\"的判据，比空泛地说\"这是长期进化的结果\"更得分。"},{"id":"10.1","t":"最适性模型的基本逻辑","s":3,"c":"10. 最适性模型与行为经济学分析","x":"最适性模型（optimality model）假设在给定约束下，自然选择倾向于保留使适合度最大化的行为策略。标准做法是：定义决策变量（吃什么、在哪觅食、停留多久）、定义货币（currency，如净能量摄入率）、定义约束（处理时间、消化道容量、被捕食风险）、求解最优值、再与实测值比较。模型的价值不在于\"动物真会计算\"，而在于给出可检验的定量预测。"},{"id":"10.2","t":"代价—收益分析与净收益","s":3,"c":"10. 最适性模型与行为经济学分析","x":"行为的经济学分析把每个行为的收益（能量、配偶、安全）与代价（时间、能量、风险）折算到同一货币上比较，选择净收益最大者。冠纹山雀在喂食器与掩体之间往返时，往返次数随距离增加而减少；狮群猎取大型猎物虽收益高但受伤风险与追捕耗能大，因而在中等体型猎物丰富时优先选择中等猎物。凡涉及\"为什么不多做一点\"的问题，都应从\"边际收益递减、边际代价递增\"入手。"},{"id":"10.3","t":"边际分析的基本思路","s":3,"c":"10. 最适性模型与行为经济学分析","x":"最优解出现在\"边际收益等于边际代价\"处，而不是\"总收益最大\"处。以觅食为例，动物延长在一个斑块内的停留时间，瞬时摄入率随资源耗尽而下降，当下降到低于环境中平均摄入率时即应离开（边际值定理，详见第 20 章）；以警戒为例，每次抬头观察的收益随抬头频率提高而递减，最优抬头频率出现在\"少抬头一次所增加的被捕食风险\"等于\"多取食一口所获得的能量\"之处。"},{"id":"10.4","t":"约束条件与不完美的最适","s":3,"c":"10. 最适性模型与行为经济学分析","x":"动物的行为很少达到理论最优，原因在于三类约束：形态约束（喙形限制了可处理的种子大小）、生理约束（消化道容量、解毒能力）、信息约束（动物对环境的了解不完整，只能做\"贝叶斯式\"的近似估计）。因此实测值常低于模型预测，正确结论是\"模型给出了上限，实际行为受约束限制\"，而不是\"最适性理论被否证\"。这一点在竞赛的模型分析题中几乎每年出现。"},{"id":"10.5","t":"频率依赖选择","s":3,"c":"10. 最适性模型与行为经济学分析","x":"当某一行为的收益取决于群体中其他个体的行为时，称频率依赖选择（frequency-dependent selection）。若一种策略在稀少时收益高、普遍时收益低，则该策略无法被固定，群体中会维持多种策略共存。侧斑蜥蜴（Uta stansburiana）三种雄性的\"石头剪刀布\"是最佳实例：橙色型好斗、守住大领域与多只雌性；蓝色型守卫型、专一护配偶，能避开橙色型的攻击；黄色型拟雌、 sneaker，偷配蓝色型的配偶。三者循环更替，任何一型都不能长期独占。"},{"id":"10.6","t":"风险敏感性与方差选择","s":3,"c":"10. 最适性模型与行为经济学分析","x":"动物的选择不仅看期望收益，还看收益的方差，称风险敏感性（risksensitive foraging）。饥饿的动物倾向于选择变异大的食物，因为只有高方差选项才可能立刻达到能量阈值；饱食的动物则偏好稳定的选项。黄蜂与蜂鸟在\"稳定获得少量糖水\"与\"一半概率获得大量糖水\"之间做选择时，饥饿个体显著偏好后者，饱食个体偏好前者，这一结果被称为能量预算规则。研究风险敏感性时必须同时报告个体的能量状态，否则同一物种可得出相反结论。"},{"id":"10.7","t":"经济分析的\"货币\"选择","s":2,"c":"10. 最适性模型与行为经济学分析","x":"同一行为可用不同货币衡量：以能量率衡量觅食、以存活概率衡量警戒、以繁殖值衡量择偶、以时间衡量领域巡视频率。货币选错会导致结论反转，如以\"单位时间摄入能量\"衡量时动物应只吃大而近的猎物，但若以\"单位时间净收益扣除被捕食风险\"衡量，则结果与实测更吻合。因此在读题时要先确认研究者用的是哪种货币。"},{"id":"10.8","t":"最适性模型的检验步骤","s":2,"c":"10. 最适性模型与行为经济学分析","x":"检验通常分五步：（1）明确观察到的行为与决策变量；（2）提出适合度货币与约束条件；（3）由模型推出定量预测（含\"最优值\"与\"对参数变化的敏感性\"）；（4）用独立数据检验预测，最好在不同环境、不同物种中重复；（5）若偏离，先检查约束是否遗漏，再考虑修改模型或否证。只做一步\"数据与预测相符\"就宣布模型成立，是最常见的方法学错误。"},{"id":"11.1","t":"进化稳定策略的概念","s":3,"c":"11. 进化稳定策略与博弈论","x":"进化稳定策略（evolutionarily stable strategy, ESS）是 Maynard Smith 与 Price 于 1973 年提出的概念：若群体中绝大多数个体采用策略 I，任何稀有的突变策略 J 进入后都不能获得更高的适合度，则 I 是 ESS。ESS 是一个\"抗入侵\"的均衡概念，描述的是策略在群体中的动态稳定性，而非个体的理性选择。"},{"id":"11.2","t":"ESS 与最优策略的区别","s":3,"c":"11. 进化稳定策略与博弈论","x":"最优策略是在给定环境中使个体适合度最大的策略，ESS 则要求该策略在群体中不被其他策略入侵，二者并不等价：可能存在多个 ESS（多重均衡），也可能一个 ESS 都不是全局最优（因为个体无法\"集体改换\"策略）。鹰鸽博弈中，\"全体和平\"看似群体最优，却不是 ESS，因为一只鹰进入即可获利。混淆\"最优\"与\"ESS\"是概念题最高频的错误。"},{"id":"11.3","t":"鹰鸽博弈的收益矩阵","s":3,"c":"11. 进化稳定策略与博弈论","x":"设资源价值为 V，战斗至重伤的代价为 C（C>V）。两只鹰相遇各以 1/2概率获胜得 V、1/2 概率重伤付 C，期望收益 (V−C)/2；鹰遇鸽，鹰胜得 V；鸽遇鹰，鸽退让得 0；鸽遇鸽，各以 1/2 得 V，期望 V/2。若 V>C，纯鹰是ESS；若 V<C，纯策略都不稳定，混合策略中鹰的频率为 V/C，此时鹰与鸽的期望收益相等。对手策略我方为鹰我方为鸽对手为鹰(V−C)/2对手为鸽V V/2"},{"id":"11.4","t":"混合策略 ESS 的计算","s":3,"c":"11. 进化稳定策略与博弈论","x":"当 V<C 时，设鹰在群体中的频率为 p，鹰的期望收益W(H)=p(V−C)/2+(1−p)V，鸽的期望收益 W(D)=(1−p)V/2。令二者相等可解得 p=V/C。此时群体达到平衡：鹰的比例低于 V/C 时鹰占优、高于 V/C 时鸽占优，故平衡稳定。计算题只要抓住\"两策略期望收益相等\"这一个条件即可，注意 C 必须大于 V 才有混合均衡。"},{"id":"11.5","t":"消耗战与\"等待\"博弈","s":2,"c":"11. 进化稳定策略与博弈论","x":"消耗战（war of attrition）描述双方通过持续投入（等待、展示、鸣叫）竞争一个不可分割的资源，先退出者失败但免于代价。模型预测投入时间的分布呈指数型，且当资源价值相对代价越高时，平均投入越长。粪蝇雄性在粪堆上等待雌蝇、蛙类长时间鸣叫争夺鸣叫位、蜣螂在洞口对峙，都可用消耗战分析。这就是\"耐力展示\"型竞赛（如雄性马鹿长时间吼叫）的理论来源。"},{"id":"11.6","t":"非对称博弈与\"所有者—入侵者\"规则","s":3,"c":"11. 进化稳定策略与博弈论","x":"当博弈双方在资源价值或持有成本上不对称时（如领域所有者在自家门口作战代价更低），ESS 往往表现为简单的\"规则\"而非复杂计算。Bourgeois 策略（\"是我的就死守，不是我的就退让\"）在所有者与入侵者角色不对称时是ESS，这解释了动物界普遍存在的\"所有者总是获胜\"现象：领域争夺中入侵者绝大多数在仪式化对峙后撤退，很少发生真正搏斗，因为所有者的作战代价更低、获胜期望更高。"},{"id":"11.7","t":"频率依赖与多态维持","s":2,"c":"11. 进化稳定策略与博弈论","x":"ESS 概念可解释群体内多种行为型的稳定共存：不同策略的收益随频率反比变化，交点即为平衡点。除了侧斑蜥蜴的三型循环，雄性鲑鱼的\"钩鼻型\"与\"拟雌型\"（satellite）在特定密度下繁殖成功相当；杜鹃寄生的\"鹰—鸽\"式对抗（寄主识别 vs 寄生者伪装卵色）也表现为振荡均衡。这类共存是\"选择不导向单一最优\"的重要证据。"},{"id":"11.8","t":"博弈论与合作演化","s":3,"c":"11. 进化稳定策略与博弈论","x":"囚徒困境中，若双方都合作收益为 R，都背叛为 P，单方背叛得 T、单方被背叛得 S（T>R>P>S），则背叛是单次博弈的占优策略，但重复博弈中\"以牙还牙\"（tit-for-tat）可稳定合作：先合作、之后模仿对方上一步。Axelrod 的计算机竞赛显示，以牙还牙在\"善意、可报复、宽容、清晰\"四条上占优，这为互惠利他的进化提供了机制。现实中清洁鱼与客户鱼的互动、吸血蝙蝠的反哺，都是带\"欺骗惩罚\"的重复博弈。"},{"id":"11.9","t":"ESS 理论的局限","s":2,"c":"11. 进化稳定策略与博弈论","x":"ESS 假设群体大、随机相遇、收益矩阵固定、遗传与表型一一对应；现实中种群结构（空间聚集、亲属群体）、状态依赖（体况、年龄）、学习与文化传递都会使均衡偏离模型预测。此外 ESS 只说明\"不能被入侵\"，不说明\"如何到达\"，一个系统可能长期停留在非均衡状态。理解这些局限，才能在题目出现\"实测与预测不符\"时给出合理解释。"},{"id":"12.1","t":"行为适应的判定标准","s":3,"c":"12. 行为的适应意义、代价与收益","x":"判定某一行为是适应（adaptation）需满足：该行为在自然条件下确实提高适合度；该行为是可遗传的、能被选择塑造；该行为在近缘种中与生态条件呈现相关格局。相反，\"适应\"一词不能滥用于任何有用处的性状，因为许多性状的有用性是附带结果（exaptation）或发育约束的副产物。竞赛中区分\"适应\"与\"适应结果\"是常见的论述题要求。"},{"id":"12.2","t":"权衡（trade-off）是行为分析的核心","s":3,"c":"12. 行为的适应意义、代价与收益","x":"几乎所有行为决策都是权衡：觅食与警戒、繁殖与存活、当前繁殖与未来繁殖、自身投资与子代投资。权衡的存在意味着\"任何一个行为都不可能同时最优\"，因此实测行为常处于中间值。产卵数的权衡最典型：窝卵数增加会提高当前繁殖输出，但降低每只雏鸟的质量与亲鸟的存活率，Lack 的补卵实验显示雏鸟出飞数与窝卵数呈\"先升后降\"的曲线，峰值即为该环境下的最适窝卵数。"},{"id":"12.3","t":"捕食风险与觅食的权衡","s":3,"c":"12. 行为的适应意义、代价与收益","x":"动物在觅食时通过降低取食率、增加警戒、选择更安全的微生境来降低风险。岩松鼠在人为逼近时取食间隔缩短、抬头频率升高；雀类在鹰模型飞过时放弃大而暴露的喂食器，转向有遮蔽的小喂食器；反刍动物在开阔草地取食时更频繁抬头。这类研究常用\"给食—干扰\"实验量化\"风险的距离阈值\"（如 flight initiation distance），在保护生物学中直接用于设定观鸟、观鲸的接近距离。"},{"id":"12.4","t":"繁殖与存活的权衡","s":2,"c":"12. 行为的适应意义、代价与收益","x":"当前繁殖投入越大，亲鸟的存活与未来繁殖越受影响，这一权衡决定了首殖年龄、窝卵数、断乳时间等生活史特征。小型雀形目鸟类窝卵数多但成鸟死亡率高，海鸟窝卵数少（多为 1 枚）但寿命长，正是\"当前繁殖 vs 未来繁殖\"权衡的两个极端。行为层面的表现是：高风险年份亲鸟减少育幼投入以保全自身，如食物匮乏时部分鸟类弃巢。"},{"id":"12.5","t":"展示行为的能量代价与免疫代价","s":3,"c":"12. 行为的适应意义、代价与收益","x":"性炫耀、鸣唱、领域巡逻都消耗大量能量：雄性的鸣唱耗氧量可达基础代谢的数倍，孔雀维持巨型尾屏需要额外的能量与钙。扎哈维（A. Zahavi）的累赘原理（handicap principle）指出，只有真正高质量的个体才能承担高代价的展示，因而展示是\"诚实的信号\"；后续研究补充了免疫代价这一维度，即睾酮升高会抑制免疫，故只有抗寄生虫能力强的雄性才能长期维持高睾酮与强展示（Hamilton–Zuk 假说）。"},{"id":"12.6","t":"免疫状态与行为的交互","s":2,"c":"12. 行为的适应意义、代价与收益","x":"寄生虫与病原体可改变宿主行为：感染弓形虫的小鼠丧失对猫尿的恐惧、活动增加，从而提高被猫捕食的机会，有利于寄生虫完成生活史；感染疟疾的鸟类鸣唱强度下降、羽色变暗，使雌性可通过展示质量判断其健康状态。这一维度把行为学与寄生生物学、免疫学连接起来，是近年竞赛中\"跨模块综合题\"的常见切入点。"},{"id":"12.7","t":"表型可塑性与行为的适应","s":3,"c":"12. 行为的适应意义、代价与收益","x":"表型可塑性（phenotypic plasticity）指同一基因型在不同环境下产生不同表型的能力，行为是最具可塑性的性状。迁徙鸟类可根据风向调整出发时间，鱼类可根据捕食者存在发育出不同的体形与躲避行为（如孔雀鱼在高捕食压力下更早成熟、产仔更多、更倾向成群）。可塑性本身也是适应的产物，且其范围受遗传限制，这构成反应规范的概念。"},{"id":"12.8","t":"适应主义与\"想当然的故事\"","s":3,"c":"12. 行为的适应意义、代价与收益","x":"适应主义（adaptationism）倾向把每个性状都解释为自然选择的产物，古尔德与勒沃汀批评这类解释容易变成\"恰巧如此的故事\"（just-so story），即无法被否证。规范做法是提出多个可替代假说并给出可区分的预测（第 4.7节）；对行为研究而言，尤其要排除发育约束、系统发育惯性、遗传漂变等非适应解释。竞赛论述题若只给一个适应解释而不提替代假说，往往得不到高分。第三篇 行为的生理与发育"},{"id":"13.1","t":"神经系统的演化与行为的复杂化","s":2,"c":"13. 神经系统与行为","x":"行为的能力受神经系统的结构与规模制约。腔肠动物只有神经网，行为以局部反射与整体收缩为主；扁形动物出现脑神经节与纵神经索，能完成趋光与简单的捕食序列；节肢动物具有分节的链状神经节与发达的脑（昆虫的蕈形体与学习记忆相关）；脊椎动物出现脑的分区与皮层，行为的时间整合能力与灵活性显著提高。比较不同类群的神经结构与行为复杂度，是\"机制层次\"研究的基础材料。"},{"id":"13.2","t":"神经元、突触与行为的输出通路","s":3,"c":"13. 神经系统与行为","x":"行为的最终执行依赖运动神经元对肌肉的控制，而行为的选择发生在突触层面。同一运动程序可由不同的中间神经元组合激活，突触的兴奋性与抑制性平衡决定动作的强度与时序；神经调质（如血清素、多巴胺、章鱼胺）不直接传递信息，而是改变回路的\"增益\"，从而改变行为倾向。螯虾的血清素注射实验显示，注射后个体更易采取上位姿态、退缩行为减少，说明一个调质即可改变整套社会行为的表达概率。"},{"id":"13.3","t":"感觉与知觉：行为的入口","s":3,"c":"13. 神经系统与行为","x":"动物只能对自身感觉系统能够接收的信息做出反应，其\"可感知世界\"称环境界（umwelt）。蜜蜂能看见紫外光但看不见红光，因此许多虫媒花的紫外\"蜜导\"对人类不可见而对蜜蜂显著；蝙蝠的听觉覆盖 20～100 kHz，能\"看见\"超声；蛇的颊窝能感知红外辐射；象鼻鱼（Gnathonemus）以微弱电脉冲感知周围电场。理解 umwelt 可以解释\"为什么同一环境对不同动物意味着不同的刺激\"。"},{"id":"13.4","t":"感受器的选择性与刺激过滤","s":3,"c":"13. 神经系统与行为","x":"感受器是对特定能量形式高度敏感的生物换能器，具有专一的\"标记线\"（labeled line）与阈值。蛙视网膜的神经节细胞中有一类\"昆虫探测器\"，只对在小视野内沿长轴运动的小物体强烈放电，对静止物体、横向大幅度移动的物体反应很弱；夜蛾的 A1 听觉神经元对 20～60 kHz 的蝙蝠回声样扫描最敏感。感受器的这种选择性就是外周层面的刺激过滤，它决定了哪些刺激能成为\"信号刺激\"。"},{"id":"13.5","t":"中央模式发生器与节律行为","s":3,"c":"13. 神经系统与行为","x":"许多节律性行为由位于中枢的神经网络自发产生，不需要逐次的感觉触发，这类网络称中央模式发生器（central pattern generator, CPG）。蝗虫飞行时翅的运动节律由胸神经节 CPG 产生，即使切断感觉输入仍能维持基本节律；七鳃鳗的游泳、蟾蜍的抓握、小鼠的咀嚼都由 CPG 驱动，感觉反馈只负责调节幅度与相位。CPG 的存在解释了\"行为可以自行发动\"这一现象，也是\"空放行为\"的机制基础。"},{"id":"13.6","t":"命令神经元与行为的选择","s":2,"c":"13. 神经系统与行为","x":"行为之间的切换常由少数\"命令神经元\"（command neuron）控制：这些神经元放电即启动整套行为程序。蟋蟀的召唤鸣叫由脑内特定中间神经元驱动，螳螂的捕食 strike 由一对巨型中间纤维触发，海兔的缩鳃反射受 LPl 等中间神经元调制。命令神经元的概念说明行为的\"开关\"可以是局部的，但现代研究强调它是\"分布式决策\"的极端简化表述，多数行为由群体编码而非单一细胞决定。"},{"id":"13.7","t":"神经递质、神经调质与行为倾向","s":3,"c":"13. 神经系统与行为","x":"不同的化学信号系统对应不同的行为维度：多巴胺与奖赏预期、运动启动相关；血清素与社会地位、攻击抑制、情绪稳定相关；去甲肾上腺素与警觉；章鱼胺在昆虫中与觅食、探索相关。果蝇的 for 基因影响 cGMP 通路，进而影响取食倾向；无脊椎动物的血清素系统与脊椎动物的功能高度类似，这是神经系统功能保守性的证据。"},{"id":"13.8","t":"脑区与行为：海马与空间记忆","s":3,"c":"13. 神经系统与行为","x":"海马（hippocampus）在脊椎动物中与空间学习、食物储藏的记忆密切相关。储藏食物的星鸦（Nucifraga columbiana）要在数千个分散地点找回种子，其海马体积显著大于不储藏的近缘种类，且储藏量越大的个体海马越大；伦敦出租车司机在掌握\"知识\"（The Knowledge）后，海马后部灰质体积增大，且与从业年限正相关。这两项研究常被用来说明\"行为需求塑造脑结构，脑结构又限制行为能力\"的双向关系。"},{"id":"13.9","t":"神经行为学的研究方法","s":2,"c":"13. 神经系统与行为","x":"常用手段包括：电生理记录（单细胞放电、局部场电位）、损毁与电刺激（定位脑区功能）、药理学干预（注射激动剂或拮抗剂）、即刻早基因标记（c-fos、ZENK 反映近期神经活动）、神经影像（fMRI、PET）与光遗传学、化学遗传学（精确开关特定神经元）。鸟鸣研究是方法整合的典范：损毁HVC 使鸣唱失去正常序列，ZENK 表达定位对同种鸣唱的响应脑区，光遗传学可诱发特定音节。"},{"id":"14.1","t":"激素作用的两种方式：激活效应与组织效应","s":3,"c":"14. 内分泌激素与行为","x":"激素对行为的作用分两类。激活效应（activational effect）是成体中激素水平的短期变化引起行为改变，可逆，如睾酮升高使雄鸟在春季鸣唱、攻击性增强；组织效应（organizational effect）发生在发育的关键窗口，激素\"永久性\"地塑造神经回路与器官，决定成年后对激素的反应能力，如哺乳动物胚胎期睾酮决定雄性化的脑与行为潜能。经典实验是给新生雌鼠注射睾酮，成年后其攻击与爬跨行为显著高于对照，且不再对雌激素产生正常的性行为反应。"},{"id":"14.2","t":"睾酮与攻击、鸣唱","s":3,"c":"14. 内分泌激素与行为","x":"睾酮（testosterone）在多数脊椎动物中促进雄性竞争性行为：雄鸟春季睾酮升高，鸣唱频率、领域攻击强度随之上升；雄鹿在繁殖季睾酮升高，颈部肌肉增厚、好斗性增强。但睾酮与攻击性的关系并非线性，\"挑战假说\"（challenge hypothesis）指出睾酮主要在面临社会挑战时短期升高，繁殖季维持基础水平，以降低免疫抑制与能量消耗的代价；去势后攻击性下降、补充睾酮后恢复，是激活效应的标准证据。"},{"id":"14.3","t":"雌激素、孕激素与母性行为","s":3,"c":"14. 内分泌激素与行为","x":"母性行为（筑巢、舔舐、哺乳、护幼）受雌激素、孕激素与催乳素的时序调控。大鼠妊娠后期孕激素下降、雌激素与催乳素上升，触发筑巢与舔幼；在非妊娠雌鼠中注射相应激素组合也可诱发筑巢与育幼，说明这是一套可被激素\"人工启动\"的行为程序。催乳素（prolactin）在鸟类中与孵卵、嗉囊乳分泌相关，在哺乳动物中与泌乳、育幼动机相关，是跨类群保守的\"育幼激素\"。"},{"id":"14.4","t":"催产素、加压素与社会依恋","s":3,"c":"14. 内分泌激素与行为","x":"催产素（oxytocin）与加压素（vasopressin）调节社会识别、配偶依恋与亲代照料。草原田鼠（Microtus ochrogaster）为单配制，配偶间形成稳定依恋，其脑内加压素 V1a 受体与催产素受体密度显著高于多配制的山地田鼠（M. montanus）；向草原田鼠脑内注射催产素可加速配对依恋形成，注射拮抗剂则阻止依恋形成。人类鼻喷催产素可提高信任与合作倾向（结果有争议），说明这一系统在哺乳动物中功能保守，但\"催产素即信任激素\"的简化说法并不准确。"},{"id":"14.5","t":"保幼激素与昆虫的行为发育","s":3,"c":"14. 内分泌激素与行为","x":"保幼激素（juvenile hormone, JH）决定昆虫幼虫性状的保持与变态进程，同时调节成虫的行为分工。蜜蜂工蜂随日龄从巢内哺育转为巢外采集，其血淋巴 JH 滴度在转为采集前显著升高；人为提高幼蜂的 JH 滴度可使其提前外出采集，去除采集蜂使群体年龄结构改变时，剩余个体的 JH 滴度与职能也会相应调整。这一\"激素—行为\"对应关系说明昆虫的行为发育同样受内分泌调控，而非纯由日龄决定。"},{"id":"14.6","t":"蜕皮激素与变态中的行为改变","s":2,"c":"14. 内分泌激素与行为","x":"蜕皮激素（ecdysone，20-羟基蜕皮酮）触发蜕皮与变态，同时带来行为的整体重组。蚕的末龄幼虫以取食与爬行为主，化蛹后行为程序被\"关闭\"；羽化为蛾后，取食行为消失、性信息素释放与搜索行为出现。这种\"整套行为程序的替换\"是激素在发育中重新设定神经回路的结果，说明行为的改变可以不是渐变而是阶段性的。"},{"id":"14.7","t":"应激激素与行为","s":3,"c":"14. 内分泌激素与行为","x":"糖皮质激素（皮质醇、皮质酮）在短期应激中提高血糖、增强警觉，具有适应意义；长期升高则抑制繁殖、损害免疫与海马、增加刻板行为。动物园中的圈养动物常表现慢性应激：皮质酮基线升高、刻板行为增加、繁殖成功率下降。研究设计上要注意基线水平与应激响应的区别，且采血本身会造成应激，故多用粪便激素代谢物做非损伤监测。"},{"id":"14.8","t":"激素—环境—行为的相互作用","s":3,"c":"14. 内分泌激素与行为","x":"激素不是行为的单向\"开关\"，而是环境与行为之间的中介：长日照经视网膜—下丘脑—垂体—性腺轴升高睾酮，睾酮促进鸣唱，而鸣唱引起的社会互动（雌性靠近、雄性挑战）又反过来升高睾酮，形成反馈环。这是\"环境→激素→行为→环境\"的闭环，答题时若只写\"睾酮引起鸣唱\"而漏掉社会反馈，会被视为机制理解不完整。"},{"id":"14.9","t":"行为内分泌学的研究方法与判据","s":2,"c":"14. 内分泌激素与行为","x":"经典方法是\"去除—补充\"：去除腺体（去势、切除甲状腺）观察行为缺失，再补充相应激素观察恢复，并设置假手术对照。现代方法还包括放射免疫测定与质谱测激素、受体原位杂交与免疫组化定位、基因敲除与受体拮抗剂。判定\"某激素调节某行为\"需满足三条：时间上激素变化先于行为变化、剂量—反应关系存在、阻断受体可取消该行为。"},{"id":"15.1","t":"生物节律的类型","s":3,"c":"15. 昼夜节律与生物钟","x":"按周期长短可分为：近日节律（circadian，约 24 h，如睡眠—觉醒、活动—休息）、潮汐节律（约 12.4 h，如招潮蟹的体色变化与活动、滨蟹的觅食）、月节律（约 29.5 d，如珊瑚同步产卵、加州银汉鱼随大潮上滩产卵）与年节律（如迁徙、冬眠、繁殖季节）。周期在 24 h 以上但非整日的称超日节律，短于 24 h 的称亚日节律。判断某节律类型要看周期长度，而非\"是否与光照有关\"。"},{"id":"15.2","t":"昼夜节律的三大特征","s":3,"c":"15. 昼夜节律与生物钟","x":"内源性昼夜节律（circadian rhythm）有三个标志性特征：（1）在恒定条件下（持续黑暗或持续光照）仍能自由运转（free-running），周期接近但不等于 24 h，如仓鼠在恒黑中约 23.8 h；（2）具有温度补偿，即环境温度变化 10 ℃ 时周期变化很小（Q10 接近 1），这与一般生化反应的 Q10≈2 形成对照；（3）可被授时因子（zeitgeber）重置相位，从而与外界周期同步。三者合起来才能证明\"节律由内源生物钟驱动\"，而不是对环境的被动反应。"},{"id":"15.3","t":"生物钟的分子机制","s":3,"c":"15. 昼夜节律与生物钟","x":"核心是转录—翻译的负反馈环。以果蝇为例，period（per）与 timeless（tim）基因的产物在夜间积累、与时钟蛋白 CLK/CYC 结合并抑制自身的转录，白天被光或激酶降解，从而形成约 24 h 的振荡；哺乳动物中对应的基因是Per1/2/3、Cry1/2、Clock、Bmal1。突变 per 基因会同时改变羽化节律与求偶鸣唱的节律性，这是\"一个时钟基因控制多种节律行为\"的经典证据。"},{"id":"15.4","t":"生物钟的解剖定位","s":2,"c":"15. 昼夜节律与生物钟","x":"在哺乳动物中，主钟位于下丘脑视交叉上核（suprachiasmatic nucleus,SCN），损毁 SCN 后饮水和活动节律消失，移植胎儿 SCN 可恢复；SCN 通过自主神经与褪黑素（melatonin，由松果体在暗期分泌）向全身发出\"时间信号\"。鸟类具多钟系统（松果体、视网膜、视交叉上核）；果蝇的钟分布在脑与复眼中。外周组织也有自身时钟，但需 SCN 同步，这与\"倒时差\"时各器官节律不同步的现象一致。"},{"id":"15.5","t":"授时因子与相位重置","s":3,"c":"15. 昼夜节律与生物钟","x":"授时因子是能把内源节律同步到环境周期的时间线索，最重要的为光（经视网膜—SCN 通路），此外还有温度、食物可获得时间（food-entrainable oscillator）、社会线索与活动节律。相位响应曲线（phase response curve,PRC）描述不同时刻给光造成相位提前或延迟的规律：主观夜前半段给光使相位延迟，后半段给光使相位提前，这正是跨时区飞行后\"倒时差\"方向的机制基础。"},{"id":"15.6","t":"生物钟的适应意义","s":3,"c":"15. 昼夜节律与生物钟","x":"生物钟使动物能\"预测\"而非仅\"反应\"环境变化。蜜蜂经训练可在固定时刻到饲喂点采食，且在恒温恒暗条件下仍保持这一\"时间记忆\"；捕食者与猎物的活动节律错开可降低相遇概率；许多虫媒花在特定时段分泌花蜜，与传粉者的活动高峰精确对应。预测能力带来的收益是效率与安全的双重提升，这解释了生物钟在几乎所有类群中的普遍存在。"},{"id":"15.7","t":"潮汐节律与月节律","s":2,"c":"15. 昼夜节律与生物钟","x":"潮汐节律由月相引起的潮汐周期塑造，周期约 12.4 h：招潮蟹在恒定的实验室条件下仍保持与原地潮汐同步的体色变化与活动节律；滨蟹在退潮时外出觅食、涨潮时躲藏，即使移到无潮的海域也能维持数周。月节律的典型是珊瑚的同步产卵（大堡礁珊瑚在满月后特定夜晚同时释放配子）与加州银汉鱼的产卵（随大潮在高潮线沙滩产卵）。这类节律多以光（月光）为主要授时因子。"},{"id":"15.8","t":"人工光照、时差与节律紊乱","s":2,"c":"15. 昼夜节律与生物钟","x":"人造光污染会改变野生动物的节律与物候：城市鸟类提前晨鸣、夜间迁徙鸟类被灯光吸引而撞楼、海龟幼体因岸上灯光而偏离海面方向。人类倒班工作者长期处于节律错位状态，代谢与免疫疾病风险升高。行为学的研究价值在于提供\"光照强度—行为改变\"的定量关系，用于制定暗夜保护标准（如迁徙季的照明管理）。"},{"id":"16.1","t":"迁徙的定义与类型","s":3,"c":"16. 迁徙、洄游与导航","x":"迁徙（migration）指动物在生活史中周期性地、定向地在繁殖区与越冬区（或觅食区）之间长距离移动，且通常伴随返回。按媒介分为飞行（候鸟、帝王蝶）、游泳（鲸、鲑、鳗）、陆行（角马、驯鹿）；按方向分为南北向、东西向与垂直迁徙（山地兽类随雪线上下移动）；按行为主体分为完全迁徙、部分迁徙与差异迁徙（同种内部分个体迁徙）。洄游（migration of fishes）是鱼类迁徙的特称，可分为生殖洄游、索饵洄游与越冬洄游。"},{"id":"16.2","t":"迁徙的诱发因素与迁徙不安","s":3,"c":"16. 迁徙、洄游与导航","x":"迁徙的启动由内在节律与外部线索共同决定：光周期变化是主要\"日历\"信号，温度、食物丰度、风向与天气则作为\"出发窗口\"的调节因素。笼养候鸟在迁徙季表现定向的躁动与夜间振翅，称迁徙不安（Zugunruhe），这是研究迁徙遗传与定向的最重要窗口。黑顶莺的笼养实验证明迁徙时间（何时开始）与迁徙方向（朝哪走）都可遗传，且两者的遗传基础可以相互独立。"},{"id":"16.3","t":"迁徙的代价与收益","s":3,"c":"16. 迁徙、洄游与导航","x":"收益包括利用季节性爆发的高纬度资源、避开严寒与食物短缺、降低寄生与捕食压力；代价包括极高的能量消耗（候鸟跨海飞行前可积累超过体重 40%的脂肪）、途中被捕食与天气灾害的风险、导航失误与人类设施（高压线、风机、玻璃幕墙）造成的死亡。迁徙是否进化出来取决于\"繁殖收益—死亡风险\"的净差，这解释了为什么许多物种采取部分迁徙（部分个体留居），也解释了热带地区的\"垂直迁徙\"与游牧型移动。"},{"id":"16.4","t":"定向与导航的区分","s":3,"c":"16. 迁徙、洄游与导航","x":"定向（orientation）指个体在移动中保持某一方向的能力，可依靠指南针机制；导航（navigation）指个体在偏离路线后仍能确定自身相对于目标的位置并修正路线，需要\"地图\"信息。把马恩岛鹱（Manx shearwater）从英国威尔士运到美国波士顿放飞后，它仍能跨越大西洋返回原巢，说明其具备真正的导航能力；而仅具定向能力的动物被移位后会沿原方向继续飞行而不返回，如被移位的欧洲知更鸟在笼中仍朝原迁徙方向定向。这一区分是行为学最经典的问答之一。"},{"id":"16.5","t":"太阳罗盘与时间补偿","s":3,"c":"16. 迁徙、洄游与导航","x":"太阳的位置随时间移动，因此以太阳为罗盘必须同时知道\"现在几点\"，这称为时间补偿（time compensation）。Kramer 的椋鸟实验显示，椋鸟在笼中对太阳的定向角度随一天中的时刻而改变；给鸟做\"时钟位移\"（用人工光周期把生物钟提前或推后数小时）后，其定向角度随之偏转相应的角度，从而证明太阳罗盘与生物钟耦合使用。蜜蜂的舞蹈通讯中方向的传递也依赖太阳方位与时间的计算。"},{"id":"16.6","t":"星象罗盘","s":3,"c":"16. 迁徙、洄游与导航","x":"夜间迁徙的鸟类以星空为罗盘，且利用的是星空的\"旋转中心\"而非具体星座。Emlen 把靛蓝彩鹀（Passerina cyanea）置于天文馆中，发现其在秋季迁徙期朝特定方向躁动；当把投影星空旋转，鸟的定向方向随之改变；让幼鸟从未见过星空的旋转，只见过静止星空，则定向混乱；而在出生后早期短暂观看旋转星空的幼鸟，即使此后不再见星空，仍能正确定向。这说明星象罗盘包含\"学习星座绕北极旋转\"的成分，且存在敏感期。"},{"id":"16.7","t":"地磁定向","s":3,"c":"16. 迁徙、洄游与导航","x":"地磁定向（magnetoreception）在细菌、昆虫、鱼类、鸟类、海龟中均有证据。鸟类与海龟利用的不是磁极方向，而是磁倾角（inclination）与磁场强度构成\"磁地图\"；信鸽上喙与鲑鱼嗅上皮中存在磁铁矿（magnetite）晶体，被认为是磁感受器之一；另有\"自由基对\"假说，认为视网膜中的隐花色素（cryptochrome）在蓝光下形成寿命受磁场影响的自由基对，从而把磁信息转化为视觉信号，欧洲知更鸟在蓝光下才能正常定向、射频场可干扰其定向，都支持这一假说。"},{"id":"16.8","t":"地标与嗅觉导航","s":2,"c":"16. 迁徙、洄游与导航","x":"地标导航（landmark navigation）依赖对显著地形特征的记忆，蜜蜂、黄蜂能以地标组合精确定位巢口，灰雁与信天翁可利用地形定向。嗅觉导航的证据主要来自信鸽：遮蔽嗅觉后归巢表现下降，且在不同风向条件下归巢路线会相应改变，但该结论仍有争议，主流看法是鸽子以地磁与视觉为主、嗅觉为辅助。海鸟（管鼻类）被认为能利用海洋的\"气味景观\"定位，如信天翁可循二甲基硫的气味找到生产力高的海域。"},{"id":"16.9","t":"鱼类洄游的定向机制","s":3,"c":"16. 迁徙、洄游与导航","x":"鲑科鱼类出生在淡水溪流，入海育肥后溯河产卵，其归巢依赖对\"家乡水体气味\"的印记：幼鱼在降海前对出生溪流的化学特征形成记忆，成鱼在上溯时据此选择支流，实验者用吗啉等人工气味处理幼鱼后，成鱼会趋向该气味的水流，这是嗅觉印记最直接的证据。欧洲鳗鲡则相反，在淡水生长、到马尾藻海产卵，幼体经数年的洋流输运回到欧洲沿岸，其定向依赖洋流与地磁的组合。海龟的跨洋导航被认为以磁倾角与磁强度构成\"磁地图\"，其幼体可记住出生海滩的磁特征。"},{"id":"17.1","t":"学习的定义与判断标准","s":3,"c":"17. 学习行为的主要类型","x":"学习（learning）指由经验引起的行为或行为潜能的相对持久改变，且这种改变不是由疲劳、成熟、感觉适应或损伤造成的。判断学习需要排除三个混淆：成熟（随年龄自然出现，如幼鸟羽翼硬化后能飞）、疲劳（暂时性反应下降，休息后恢复）、感觉适应（感受器敏感性下降）。只有设置了\"无经验对照\"并能重复出现的行为改变，才能归为学习。"},{"id":"17.2","t":"习惯化","s":3,"c":"17. 学习行为的主要类型","x":"习惯化（habituation）是对重复出现的无关刺激反应逐渐减弱的学习形式，是最简单、最普遍的学习。海兔（Aplysia）的缩鳃反射是细胞机制研究的经典材料：反复轻触水管引起缩鳃，多次重复后反应减弱，其机制是感觉神经元到运动神经元的突触递质释放减少（突触压抑）；若给以强刺激（如电击尾部）则出现敏感化，恢复并增强反应。习惯化的适应意义是\"忽略无用信息、节省注意力与能量\"，如农田边的鸟群对无害的稻草人逐渐不再惊飞。"},{"id":"17.3","t":"敏感化与厌恶学习的区分","s":2,"c":"17. 学习行为的主要类型","x":"敏感化（sensitization）是与习惯化相反的过程，一个强刺激使动物对后续弱刺激的反应增强，如乌贼受电击后对轻微水流也强烈喷墨。习惯化与敏感化都是非联合学习（single-event learning），不需要建立刺激之间的关联；而经典条件反射、操作条件反射属于联合学习（associative learning）。区分两者的判据是\"是否存在两个刺激的关联\"。"},{"id":"17.4","t":"经典条件反射","s":3,"c":"17. 学习行为的主要类型","x":"经典条件反射（classical conditioning）由巴甫洛夫建立：无条件刺激（US，如食物）引起无条件反应（UR，如唾液分泌），与中性刺激（CS，如铃声）反复配对后，单独呈现 CS 即可引起条件反应（CR）。形成的关键是CS 对 US 的\"预测性\"，而非简单的时间接近：CS 先于 US 且能可靠预测 US 时学习最快。蜜蜂的伸喙反射（proboscis extension reflex, PER）是昆虫版的经典模型：以气味为 CS、蔗糖水为 US，数次配对后单独给气味即可引起伸喙，这一范式被广泛用于研究蜜蜂的嗅觉学习与记忆。"},{"id":"17.5","t":"操作条件反射","s":3,"c":"17. 学习行为的主要类型","x":"操作条件反射（operant conditioning）指动物通过自身行为的结果来改变该行为的发生概率，斯金纳（Skinner）用\"斯金纳箱\"系统研究了强化程序。正强化（给奖励）提高行为频率，负强化（撤除厌恶刺激）同样提高行为频率，惩罚则降低频率。鸽子啄键获取食物、大鼠压杆获得水、海豚跳跃穿过圆环获取鱼，都是操作条件反射的实例。它与经典条件反射的区别在于：前者是\"行为→结果\"，动物主动；后者是\"刺激→反应\"，动物被动接受刺激关联。学习类型关键特征经典实例习惯化重复无关刺激，反应减弱海兔缩鳃反射、鸟群对稻草人敏感化强刺激使弱刺激反应增强乌贼受电击后强烈喷墨经典条件反射CS 预测 US，被动关联巴甫洛夫的狗、蜜蜂 PER操作条件反射行为后果改变行为概率鸽子啄键、大鼠压杆潜在学习无强化也形成认知地图Tolman 大鼠迷宫顿悟学习突然重组问题表征黑猩猩苏丹叠箱取香蕉模仿学习观察他人后习得新行为日本猕猴洗红薯、山雀开奶瓶"},{"id":"17.6","t":"试错学习","s":3,"c":"17. 学习行为的主要类型","x":"试错学习（trial-and-error learning）指动物在多次尝试中逐渐保留有效动作、淘汰无效动作，桑代克用迷箱研究猫的逃脱，提出\"效果律\"：带来满意结果的动作被强化。其特征是学习曲线呈逐步下降的错误率，而非突然的\"理解\"。章鱼打开玻璃瓶盖取食蟹、乌鸦解开多层机关取食，都包含试错成分，但若动物第一次即成功且不需多次尝试，则应考虑顿悟或模仿。"},{"id":"17.7","t":"潜在学习与认知地图","s":3,"c":"17. 学习行为的主要类型","x":"潜在学习（latent learning）指在没有强化的情况下发生的学习，只有在需要时才表现出来。Tolman 与 Honzik 的大鼠迷宫实验显示，始终不给奖励的组在迷宫中没有表现优势，但一旦给予奖励，其错误率立刻大幅下降，说明此前已经形成了\"认知地图\"（cognitive map）。这一结果反驳了\"学习必须依赖强化\"的行为主义主张，也支持动物具有内部表征能力。星鸦储藏种子的位置记忆、蜜蜂对地形地标的组合记忆，都是认知地图的实例。"},{"id":"17.8","t":"顿悟学习","s":3,"c":"17. 学习行为的主要类型","x":"顿悟（insight learning）指动物在看似没有逐步试错的情况下，通过重新组织对问题的表征而突然解决问题。苛勒（W. Köhler）对黑猩猩的经典研究：苏丹（Sultan）在够不到香蕉时，先是无效地跳跃，随后突然把两个短杆接成长杆、或把箱子叠起来站上去取到香蕉；一旦解决，重复时几乎立即成功。判据是\"第一次成功的突然性 + 可迁移到类似问题\"，但要注意排除偶然成功，需多次试验与不同情境的验证。"},{"id":"17.9","t":"模仿、社会学习与文化行为","s":3,"c":"17. 学习行为的主要类型","x":"模仿（imitation）指观察者复制示范者的动作以达到相同结果，需与\"局部增强\"（只是被吸引到同一地点）和\"刺激增强\"（只是对某物体更感兴趣）区分。日本猕猴伊莫（Imo）洗红薯的行为在群体中由幼体向母体、由同龄向老年扩散，扩散模式符合社会学习而非个体发现；英国大山雀学会啄开奶瓶盖取奶油，短时间内跨地区传播，速度与种群密度相关，是社会学习的经典案例。当行为在群体中代际传递并累积改进时，称文化行为（cultural behavior），如黑猩猩用不同工具钓白蚁、座头鲸的歌曲传播与更新、新喀鸦制作钩形工具。"},{"id":"17.10","t":"玩耍与工具使用","s":2,"c":"17. 学习行为的主要类型","x":"玩耍（play）是缺乏明显即时功能、以自身为目的、在安全情境中反复出现的行为，多见于幼年哺乳动物与部分鸟类。其功能假说包括锻炼运动技能、练习社会规则、促进脑发育，支持证据是玩耍被剥夺的幼鼠在成年后社会行为与运动协调较差。工具使用（tool use）指使用外部物体以达成目的，如新喀鸦（Corvus moneduloides）削枝成钩取食幼虫、黑猩猩用草茎钓白蚁、海獭用石块敲开贝壳、埃及兀鹫用石块砸蛋。工具使用常与创新、问题解决能力相关，是动物 cognition 的重要指标。"},{"id":"18.1","t":"印随的特征","s":3,"c":"18. 印随、敏感期与行为发育","x":"印随（imprinting）是幼体在出生后极短的时间内对某一对象形成快速、牢固且往往不可逆的依恋，洛伦茨的灰雁实验是其经典证明：孵出后最初见到的移动物体被当作\"母亲\"，此后跟随该物体而不认亲生母亲。印随有三个特征：发生于特定时间窗内、一经形成极难改变、具有\"自我强化\"性质（不需要食物奖励）。印随的对象可以是非同种个体甚至无生命物体，说明它是一种\"被遗传规定时机的学习\"。"},{"id":"18.2","t":"印随的敏感期与机制","s":3,"c":"18. 印随、敏感期与行为发育","x":"印随的敏感期很短，雏鸭约在孵出后 13～16 h 最强，数天后迅速减弱；敏感期的起止受神经发育与经验共同调节。其神经基础涉及端脑的视顶盖—前脑通路，幼体在敏感期内对\"移动物体\"的注意被高度增强。要注意\"敏感期\"（sensitive period）比\"关键期\"（critical period）更准确：窗口内的学习效果最佳，窗口外并非绝对不可能，只是极难。"},{"id":"18.3","t":"性印记与择偶","s":3,"c":"18. 印随、敏感期与行为发育","x":"幼年的印随会影响成年后的择偶偏好，称性印记（sexual imprinting）。若把雄性斑胸草雀（Taeniopygia guttata）与异种个体一起养大，成年后它更偏好养母物种的雌性；若与同种但羽色被人为改变的个体一起养大，则偏好被改变后的表型。这一现象说明\"择偶标准\"部分由早期经验设定，也解释了杂交种在择偶上的混乱。人类的研究也提示早期家庭环境会影响面孔偏好，但因果强度远低于鸟类实验。"},{"id":"18.4","t":"敏感期的比较：鸟鸣与语言","s":3,"c":"18. 印随、敏感期与行为发育","x":"鸟鸣学习与人类语言习得具有高度相似的时间结构：婴儿在出生后数月至数年内对语音对比高度敏感，此后逐渐收窄到母语；白冠带鹀在孵出后约 10～50 天的\"记忆期\"听到同种鸣唱，随后进入\"感觉运动练习期\"，逐步把记忆中的曲目调整为自己的歌声。两者都表现为\"早期暴露 + 后期练习 + 窗口关闭后难以完全习得\"，因此鸟鸣被视为语言习得的动物模型。"},{"id":"18.5","t":"鸟鸣发育的阶段与机制","s":3,"c":"18. 印随、敏感期与行为发育","x":"鸣禽的鸣唱发育可分四个阶段：记忆积累（听并记住同种曲目）、感觉运动练习（发出不稳定的\"亚歌\" subsong，逐步匹配记忆模板）、模板固化（crystalized song，结构稳定）、维持（依赖睾酮与听觉反馈）。斑胸草雀的歌曲由若干音节组成固定序列，幼鸟学唱时先\"复制\"再\"裁剪\"；若在练习期致聋，歌声将停留在粗糙的亚歌阶段，说明听觉反馈是校准的必要条件。脑内HVC→RA→nXIIts 的通路在学唱期显著增生，窗口关闭后增生停止，这是\"敏感期的结构性基础\"。"},{"id":"18.6","t":"早期经验与神经发育","s":3,"c":"18. 印随、敏感期与行为发育","x":"哈洛（Harlow）的恒河猴实验把幼猴与\"绒布妈妈\"\"铁丝妈妈\"隔离饲养，结果显示幼猴大部分时间依偎在能提供接触安慰的绒布妈妈身上、只在吃奶时靠近铁丝妈妈，且成年后社会行为严重异常、育幼能力缺失。这证明\"依恋\"不仅由食物供给决定，接触安慰与社会互动对行为发育不可替代。人类方面，罗马尼亚孤儿院儿童的追踪研究显示早期剥夺导致社会认知与情绪调节的长期缺陷，但若在 2 岁前被收养，多数可显著恢复，这与敏感期的概念一致。"},{"id":"18.7","t":"行为的发育稳态","s":2,"c":"18. 印随、敏感期与行为发育","x":"发育稳态（developmental homeostasis）指行为在发育过程中对环境扰动具有一定的缓冲能力，最终形成稳定的成体表型。例如不同饲养条件下的大鼠在成年后的基本运动与社交模式大体一致，只有在极端剥夺时才会偏离。这一概念解释了两个现象：一是\"遗传程序具有稳健性\"，二是\"极端环境才能暴露行为的可塑性边界\"，因此用常规饲养条件的差异来论证\"某行为完全由环境决定\"是不成立的。"},{"id":"18.8","t":"昆虫与鱼类的行为发育","s":2,"c":"18. 印随、敏感期与行为发育","x":"果蝇的行为发育与神经发育同步：幼虫以取食与趋化为主，化蛹后行为程序关闭，成虫出现求偶、趋光与昼夜节律行为，per 基因突变会改变求偶鸣唱的节律。蜜蜂的行为发育表现为年龄分工：幼蜂清洁巢房与哺育，中期转为筑巢与加工花蜜，后期外出采集，这一序列受 JH 与蜂王信息素共同调节，且可因群体需要而\"逆转\"（如采集蜂可回到哺育岗位）。慈鲷等鱼类在早期经历捕食者可塑性影响反捕食行为与形态（第 12.7 节）。"},{"id":"18.9","t":"行为衰老与经验积累","s":2,"c":"18. 印随、敏感期与行为发育","x":"行为随年龄退化：老年灵长类的探索行为减少、对新事物回避增加，老年鸟类的鸣唱曲目简化、迁徙准时性下降；另一方面，经验积累可提高某些行为的表现，如老年雌象对水源位置的记忆在干旱期对群体存活至关重要。因此行为衰老是\"生理退化\"与\"经验积累\"两条相反趋势的叠加，答题时不宜简单写成\"越老越差\"。"},{"id":"19.1","t":"\"先天与后天\"是一个伪二分","s":3,"c":"19. 本能与学习的关系","x":"任何行为都需要基因与环境的共同参与：没有基因就没有神经系统，没有环境就没有发育所需的输入。因此\"某行为是本能还是学习\"的正确问法是\"该行为的表现需要哪些具体经验、在发育的哪个阶段需要、遗传提供了什么样的学习规则\"。经典的反例是\"鸟鸣\":既需要有遗传规定的学习窗口与模板，也需要听到同种鸣唱；两者缺一不可，任何一方都不能单独\"决定\"。"},{"id":"19.2","t":"学习的预备性","s":3,"c":"19. 本能与学习的关系","x":"动物并非对所有刺激—结果关联都能同样容易地学习，遗传规定了\"易学什么\"，称学习的预备性（preparedness）。Garcia 的味觉厌恶实验：大鼠只要一次就能把\"特定味道\"与随后的恶心联系起来（即使间隔数小时），却很难把\"声音或光\"与恶心联系起来；反之，对电击则容易与声音、光联系而非味道。这种\"选择性联想\"违背了行为主义\"所有刺激等价\"的假设，说明学习受进化塑造的\"模块\"约束。"},{"id":"19.3","t":"本能中的学习成分","s":3,"c":"19. 本能与学习的关系","x":"许多被归为本能的行为包含不可省略的学习步骤。雏鸥的啄击是先天FAP，但精准度随练习提高；松鼠的埋藏行为是先天程序，但埋藏地点的记忆与选择依赖经验；织雀的筑巢动作是先天的，但巢的完成质量随练习改善。这种\"被遗传引导的学习\"（instinct to learn）说明本能提供的往往是\"框架\"而非\"成品\"。"},{"id":"19.4","t":"学习中的本能成分","s":2,"c":"19. 本能与学习的关系","x":"即使是最\"高级\"的学习，也依赖先天的能力与偏好：黑猩猩学习钓白蚁需要先天的精细操作能力与对\"白蚁丘\"的兴趣；人类婴儿学习语言依赖先天的语音范畴感知与统计学习机制。因此学习能力的进化本身是自然选择的结果，学习不应被看作\"反本能\"的力量，而是一种更灵活的本能。"},{"id":"19.5","t":"学习能力的生态适应","s":3,"c":"19. 本能与学习的关系","x":"学习能力的高低与生态需求相关。Lefebvre 等对鸟类\"创新行为\"（新食物、新取食技巧）的全球数据库分析显示，创新频率高的类群（鸦科、鹦鹉、燕雀类）相对脑容量（尤其执行脑区）较大，且在城市环境中更易定殖；储藏食物的鸟类空间记忆强、海马大；寄生性鸟类（杜鹃）在宿主识别上的学习能力与其寄生策略匹配。这说明\"智力\"不是单一维度，而是被具体生态问题塑造的一组能力。"},{"id":"19.6","t":"文化传递与累积文化","s":3,"c":"19. 本能与学习的关系","x":"当行为通过社会学习在个体间传递并跨代保持，即形成文化。黑猩猩不同群落使用不同的工具组合（钓白蚁的不同探杆、砸坚果的不同石砧），行为差异无法用生态差异完全解释，符合\"文化\"判据；座头鲸的歌曲在数年间由西向东传播并不断被\"改编\"，传播速度与种群连通度相关；新喀鸦的工具制作需多年练习，属\"累积文化\"（cumulative culture）的候选。人类文化被认为是累积文化的极端形式。"},{"id":"19.7","t":"学习、本能与保护实践","s":2,"c":"19. 本能与学习的关系","x":"理解本能与学习的边界对保护至关重要：若某一行为是本能，则圈养个体放归后仍能表现（如筑巢、迁徙冲动）；若依赖学习（如识别天敌、选择食物），则必须在放归前进行训练。中国的麋鹿、普氏野马再引入项目都包含\"野化训练\"环节，其中最重要的一项是用天敌模型与活体猎物训练幼体的反捕食与觅食技能。行为学在这里直接变成保护工具。"},{"id":"19.8","t":"\"本能—学习连续谱\"的应试应用","s":3,"c":"19. 本能与学习的关系","x":"面对\"判断下列行为属于本能还是学习\"的题目，正确策略是三步：先看该行为是否需要特定经验才能正常表现（需要则含学习成分）；再看该行为是否在隔离条件下仍能完整出现（能则为先天框架）；最后看该行为在种内的变异程度与可塑性（变异大则经验贡献大）。由于几乎所有行为都落在连续谱上，答题时应写明\"以先天为主，但需…经验校准\"这类表述，避免绝对化。第四篇 主要行为类型"},{"id":"20.1","t":"觅食行为的组成与食性特化","s":3,"c":"20. 觅食行为","x":"觅食行为包括搜索、识别、捕获（或采集）、处理与摄入五个环节，每一环节都有可被选择塑造的决策。食性特化（dietary specialization）在动物界十分普遍：考拉几乎只吃桉树叶、大熊猫以竹为主食、食蚁兽专食蚁类，特化降低了对识别与处理多种食物的神经与机械成本，但提高了对单一资源的依赖风险。传粉者与植物的协同特化更精细，达尔文曾根据马达加斯加一种长距彗星兰的花距长度预测存在长喙的天蛾，后被 Xanthopan morganii 的发现所证实。"},{"id":"20.2","t":"最适觅食理论的基本框架","s":3,"c":"20. 觅食行为","x":"最适觅食理论（optimal foraging theory）以\"单位时间净能量收益最大化\"为基本货币，把觅食决策分为四类：吃什么（食谱宽度）、在哪吃（斑块选择）、吃多久（斑块停留时间）、何时走（迁移决策）。模型的基本假设是动物对资源有遗传或经验形成的\"收益率排序\"，并能以近似最优的方式行动。理论的价值在于给出定量预测，如\"当高收益食物密度下降时，食谱应放宽\"，这类预测已在多种鸟类与鱼类中得到验证。"},{"id":"20.3","t":"最适食谱宽度模型","s":3,"c":"20. 觅食行为","x":"食谱宽度模型（diet breadth model）的判据是\"收益率阈值\"：某类食物是否应被摄入，取决于它的收益率（能量/处理时间）是否高于环境中所有可获得食物的平均收益率（含搜索时间）。由此推出两个反直觉的预测：（1）当高收益食物非常丰富时，动物应只吃高收益食物，即使低收益食物随手可得；（2）当高收益食物变稀有时，食谱应放宽。大西洋鳕、大山雀与刺鱼的实验都支持这一点：提高高收益食物的密度后，动物反而更\"挑食\"。"},{"id":"20.4","t":"边际值定理","s":3,"c":"20. 觅食行为","x":"边际值定理（marginal value theorem, MVT）解决\"在斑块中停留多久\"：随着在斑块内取食，瞬时收益率因资源耗尽而下降，当瞬时收益率降到\"环境平均收益率\"（含斑块间移动时间）时即应离开。推论是：斑块间旅行时间越长，动物在每个斑块中停留越久、离开时的收益率越低。常见的检验是给蜜蜂或山雀设置不同间距的喂食器，实测停留时间与预测相符；MVT 也被用于解释狮、狼在猎物尸体旁的取食时间与离开决策。"},{"id":"20.5","t":"猎物转换与频率依赖","s":3,"c":"20. 觅食行为","x":"猎物转换（prey switching）指捕食者随猎物相对丰度的变化而改变取食比例，且转换幅度往往超过丰度变化本身，形成\"正频率依赖\"的选择。机制包括\"搜索像\"（search image）的形成：捕食者一旦熟悉某种猎物的外观，就更容易发现它，从而进一步提高对该猎物的取食率。蓟马与螨类的捕食性天敌、雀类对两种种子的选择实验都观察到转换现象。生态学意义在于：转换可为稀有猎物提供\"避难所\"，有助于多物种共存与群落稳定。"},{"id":"20.6","t":"理想自由分布与觅食地选择","s":3,"c":"20. 觅食行为","x":"理想自由分布（ideal free distribution, IDF）模型预测：当个体可自由选择觅食斑块且各斑块质量不同时，个体分布会使各斑块获得的收益相等（即\"按资源比例分配\"）。实验用两处投食量不同的喂食器与鸭、刺鱼、蜜蜂检验，实测比例常接近\"按比例分配\"，但存在\" undermatching\"（分配比资源更平均）的偏离，原因是竞争、干扰与信息不完整。IDF 是理解\"个体分布—资源分布\"关系的基本模型，也是干扰竞争研究的起点。"},{"id":"20.7","t":"储藏食物与空间记忆","s":3,"c":"20. 觅食行为","x":"储藏（caching）是应对食物季节性短缺的策略，分集中储藏（larder hoarding，如橡实啄木鸟把数千枚橡实塞进一株树的树皮缝）与分散储藏（scatter hoarding，如星鸦把种子分散埋藏在数平方公里内、每处一两枚）。分散储藏者必须精确回忆成百上千个埋藏点，其海马体积显著大于不储藏的近缘种（第 13.8 节），且储藏点常按几何规则分布以减少重叠、便于记忆。盗窃压力也塑造行为：被同类偷过的个体此后会选择更隐蔽的地点或重新搬运。"},{"id":"20.8","t":"协同捕食与群体狩猎","s":3,"c":"20. 觅食行为","x":"协同捕食（cooperative hunting）指多只个体配合完成单只个体难以完成的捕食。狼群围猎麋鹿与马鹿时，成功率随群体规模上升，但单只个体的分食量在大群中反而下降，故存在\"最适群体规模\"；座头鲸的\"气泡网\"（bubblenet feeding）由数头鲸协作形成气泡幕驱赶鲱鱼，是哺乳动物中最复杂的协同捕食之一；鹈鹕在水面围成半圆驱赶鱼群、非洲野犬的长距离接力追逐，也属此类。协同捕食的进化需要\"收益分享\"机制，否则偷食者会入侵。"},{"id":"20.9","t":"觅食技能与捕食策略","s":3,"c":"20. 觅食行为","x":"常见策略包括伏击（螳螂、变色龙、豹）、追逐（猎豹、游隼）、陷阱（蚁狮的沙坑、球网蛛的网）、工具（新喀鸦的钩枝、黑猩猩的钓蚁杆）、群体围捕（第 20.8 节）与偷窃寄生（kleptoparasitism，军舰鸟追击鲣鸟迫使吐出食物、贼鸥抢食）。同一物种也可灵活切换策略，如苍鹭在浅水静立（伏击）与主动搅水驱鱼（驱赶）之间依猎物密度切换，这种\"策略库\"是行为可塑性的体现。"},{"id":"20.10","t":"觅食竞争：利用性竞争与干扰性竞争","s":2,"c":"20. 觅食行为","x":"竞争分两类：利用性竞争（exploitation competition）指个体通过更快耗尽资源间接影响他人，如蜂群在花期高峰抢采；干扰性竞争（interference competition）指个体通过攻击、占据优质位置直接排挤他人，如蜂鸟守卫喂食器、猕猴霸占果树。干扰使 IDF 的\"按比例分配\"发生偏离，因为强势个体的收益不再与资源量成正比，这也是\"理想专制分布\"（ideal despotic distribution）概念的由来。"},{"id":"21.1","t":"防御行为的类型与分级","s":3,"c":"21. 防御行为","x":"防御行为可粗分为初级防御（primary defense）与次级防御（secondary defense）：初级防御在捕食者发现之前起作用，包括伪装、警戒色、拟态、躲避生境的选择、群体生活；次级防御在捕食者已经发现或接近时起作用，包括逃逸、假死、威吓、反击、自割、释放化学物质、群体围攻。此外还可按机制分为\"降低被发现的概率\"\"降低被攻击的概率\"\"降低被捕获的概率\"三层，这一框架在答题时比罗列名词更得分。典型方式实例初级防御防御层次被发现前作用时机伪装、警戒色、拟态、隐蔽生境竹节虫拟枝、箭毒蛙警戒色次级防御被发现后逃逸、假死、威吓、自割负鼠假死、蜥蜴断尾群体防御被捕食压力大时围攻、稀释效应、集体警戒鸦群围攻猫头鹰、麝牛环形防御"},{"id":"21.2","t":"伪装（crypsis）","s":3,"c":"21. 防御行为","x":"伪装使动物与背景难以区分，手段包括保护色（与背景同色）、破坏性体色（disruptive coloration，用斑块打断身体轮廓）、拟态背景（模仿叶片、树皮、鸟粪）、反荫蔽（countershading，背深腹浅以抵消光照造成的立体感）。桦尺蛾（Biston betularia）的工业黑化是经典案例：工业烟尘使树干变黑后，黑色型比例上升，把浅色型迁到污染区则被捕食率显著升高，这是自然选择可观测的直接证据。比目鱼、乌贼还能主动改变体色与纹理以匹配底质。"},{"id":"21.3","t":"警戒色（aposematism）","s":3,"c":"21. 防御行为","x":"警戒色是醒目的配色（红黑、黄黑、蓝黑）与毒性、刺、臭味等防御能力相联系，使捕食者在一次不愉快经历后回避同类。箭毒蛙的鲜艳体色与皮肤生物碱毒性对应，蜜蜂、黄蜂的黑黄条纹与螫针联系，臭鼬的黑白配色与喷液联系。警戒色的进化难点在于\"第一个突变个体如何存活\"，主流解释是亲缘选择（同窝个体共同受益）与捕食者的\"谨慎学习\"（捕食者对新奇颜色的回避倾向）。"},{"id":"21.4","t":"贝氏拟态（Batesian mimicry）","s":3,"c":"21. 防御行为","x":"贝氏拟态指无毒、可食的物种（拟态者）模仿有毒或危险的物种（模型），从而获得保护，模型与拟态者的关系是\"寄生性\"的。经典例子是非洲燕尾蝶（Papilio dardanus）的雌性，同一物种的雌性可分别模仿数种不同有毒凤蝶的花纹（多型拟态），而无毒蝇类模仿蜂类的现象更为普遍。贝氏拟态的关键预测是：拟态者的比例越高、模型越稀少，保护效果越差，因此拟态者比例必须低于某一阈值才能维持。"},{"id":"21.5","t":"缪氏拟态（Müllerian mimicry）","s":3,"c":"21. 防御行为","x":"缪氏拟态指两个或多个都有防御能力的物种互相模仿、共享同一警戒信号，从而\"分摊\"捕食者学习的代价，双方均受益，是互利关系。热带的美洲帝王蝶与副王蛱蝶长期被作为缪氏拟态的范例（副王蛱蝶本身也含毒素）；不同种类的熊蜂、黄蜂、有毒蛙在同一地区趋同的配色，也属此类。贝氏与缪氏的区别在于\"拟态者是否有毒\"与\"双方是否互利\"，这是选择题的固定考点，判断时只看\"模型与模仿者是否都具有防御能力\"。"},{"id":"21.6","t":"拟态的其它形式","s":2,"c":"21. 防御行为","x":"除贝氏与缪氏，还有攻击性拟态（aggressive mimicry），即捕食者模拟猎物或无害物体以接近目标，如鮟鱇用背鳍特化的\"钓饵\"、某些萤火虫雌虫模拟他种雌虫的闪光以诱食雄虫；以及巢寄生的\"卵拟态\"（杜鹃卵模拟寄主卵的花纹，寄主则演化出识别异卵的能力，形成军备竞赛）。拟态系统的共同逻辑是\"信号被第三方利用\"，其稳定性取决于频率与代价的平衡。"},{"id":"21.7","t":"假死、自割与威吓","s":3,"c":"21. 防御行为","x":"假死（thanatosis）是突然不动、肢体僵直、甚至排出异味物质的行为，如负鼠被逼近时倒地不动、某些甲虫与蛙的强直反应；其功能是降低捕食者的攻击动机（许多捕食者只对运动物体反应）。自割（autotomy）指主动舍弃身体一部分以逃脱，如蜥蜴断尾、章鱼断腕、蜘蛛断足，代价是运动能力下降与再生耗能。威吓（threat display）通过夸张体型与武器展示逼迫对方退让，如猫的竖毛弓背、蟾蜍的鼓胀、大猩猩的捶胸，多数威吓是\"仪式化对抗\"，实际打斗反而少见。"},{"id":"21.8","t":"群体防御与稀释效应","s":3,"c":"21. 防御行为","x":"群体生活降低被捕食风险有三条途径：稀释效应（dilution effect，群体越大，任一个体被选中的概率越低）、集体警戒（many eyes，更多个体同时监视，警戒总时间增加而每个个体的取食时间不减）、群体反击（mobbing，鸦群围攻猫头鹰、蜂群攻击入侵者、麝牛围成环形以角对外保护幼体）。围攻的收益是驱离捕食者，代价是受伤风险与能量消耗，因此围攻强度随\"子代在场\"而显著提高，这正是\"代价—收益\"逻辑的直接体现。"},{"id":"21.9","t":"化学防御与\"借毒\"","s":2,"c":"21. 防御行为","x":"化学防御包括自身合成（臭鼬的硫醇、蝽类的醛类、蚁酸的喷洒）与\"借毒\"（sequestration，从食物中获取毒素并储存）。帝王蝶幼虫取食马利筋获得强心苷，成蝶体内毒素浓度足以使鸟类呕吐；海蛞蝓取食水螅后把刺细胞完整吞入并转移到自己的背突中；某些蚜虫从寄主植物获得萜类。借毒的进化前提是对毒素的耐受机制，因此这类动物往往与特定寄主高度绑定，构成\"化学生态\"的经典研究系统。"},{"id":"21.10","t":"反捕食的权衡与风险分配","s":3,"c":"21. 防御行为","x":"动物不会在一切时刻都表现最大警戒，而是按\"风险分配\"（risk allocation）原则调整：捕食风险高的时段与微生境加强防御，风险低时放松以提高觅食效率。风险分配模型预测，动物在\"被迫在危险时段取食\"后会补偿性地减少后续风险，实测中饥饿的鸟在鹰模型出现后短暂隐蔽即迅速返回取食，而饱食个体长时间不返回。这一原则把\"防御\"与\"觅食\"\"繁殖\"统一到同一决策框架中，是行为生态学的核心思想之一。"},{"id":"22.1","t":"领域、巢域与核域","s":3,"c":"22. 领域行为","x":"领域（territory）指动物以防御方式排除同种（有时也排除异种）个体进入的固定区域；巢域（home range）指动物日常活动所覆盖的全部区域，不必然防御；核域（core area）是巢域中利用强度最高、通常包含巢与主要食物资源的部分。三者的关系是\"巢域 ⊇ 核域 ⊇ 领域（若存在）\"，答题时必须区分\"防御\"这一判据，不能把巢域直接当作领域。"},{"id":"22.2","t":"领域的类型","s":3,"c":"22. 领域行为","x":"按功能可分为交配领域（仅用于求偶交配，如雷鸟的求偶场）、筑巢领域（仅保护巢址，如许多海鸟的巢位）、取食领域（保护食物来源，如蜂鸟守卫花丛）、越冬领域（保护越冬资源，如一些鸟类冬季的取食领域）与全年生活领域（全部资源，如许多灵长类群体的领域）。同一种动物在不同季节可拥有不同类型与大小的领域，如歌带鹀繁殖期领域小而严密集，冬季则扩大为取食领域。"},{"id":"22.3","t":"领域大小与体重、食性的关系","s":3,"c":"22. 领域行为","x":"领域面积随体重增加而增大，近似呈幂函数关系（面积与体重的 1.0～1.4次方成正比），因为单位体重能量需求与体重呈异速关系；同一体重下，食肉动物的领域远大于植食动物，因为猎物能量密度低且分布稀疏。蜂鸟的领域可以只有几十平方米，而虎的领域可达数百平方公里。领域大小还随生境质量变化：资源越贫瘠，为满足能量需求所需面积越大。"},{"id":"22.4","t":"领域的经济可防御性","s":3,"c":"22. 领域行为","x":"Brown 提出\"经济可防御性\"（economic defendability）概念：领域行为只在\"防御的收益超过防御的代价\"时出现。收益是独占资源带来的额外能量与繁殖机会，代价包括巡防时间与能量、与邻居冲突的风险、以及因巡防而减少的觅食时间。模型预测：当资源高度集中、可预测、且入侵者频繁时，领域性最易演化；当资源分散或极为丰盛（如大群昆虫同时羽化）时，领域性消失。这一框架把领域行为纳入最适性分析，是论述题的标准答案结构。"},{"id":"22.5","t":"领域的保卫方式与信号","s":3,"c":"22. 领域行为","x":"保卫方式分仪式化对抗与直接打斗：多数鸟类以鸣唱宣示（dawn chorus在黎明集中鸣唱，因清晨空气稳定、传播远且湿度利于发声）、以边界对峙与替换攻击（replacement attack）驱赶入侵，真正打斗少见；哺乳类多用气味标记（犬科排尿、猫科蹭擦与抓痕、河马粪堆）、面部表情与体态威吓。仪式的意义在于降低双方代价，这也是第 11.6 节\"所有者—入侵者\"规则的现实表现。"},{"id":"22.6","t":"领域的代价与收益","s":3,"c":"22. 领域行为","x":"收益包括独占食物、配偶与巢址，降低被捕食风险（熟悉地形与逃路）、降低寄生与疾病传播（减少与陌生个体接触）。代价包括防御耗能、暴露于捕食者（鸣唱与巡防都吸引注意）、受伤风险、以及失去在其他区域觅食的机会。移除实验是检验收益的常用手段：把领域所有者移除后，新个体迅速填补，说明领域具有可量化的价值；若同时补充食物，则领域面积缩小，说明面积由资源决定。"},{"id":"22.7","t":"领域的标记与个体识别","s":2,"c":"22. 领域行为","x":"标记的功能是\"减少直接冲突\"：把\"我已在此\"的信息提前传达，避免双方耗费。气味标记需要稳定的化学性质与规律的重访频率，犬科动物通过排尿频率与位置调整标记强度；鸣唱标记需要个体特异性，鸟类能通过鸣声识别邻居个体，并表现\"亲爱的敌人效应\"（dear enemy effect）——对熟悉的邻居反应较弱、对陌生入侵者反应强烈。个体识别能力是领域系统稳定运行的前提。"},{"id":"22.8","t":"种间领域与生态位分化","s":2,"c":"22. 领域行为","x":"领域防御通常针对同种，但资源需求高度重叠的异种之间也会发生种间领域（interspecific territoriality）。两种鹟在同一片林地划分区域、相互驱赶，会加剧竞争并可能排斥一方；而生态位分化（如取食高度、喙形差异）可减弱种间领域，从而允许共存。研究种间领域是理解群落结构与竞争排斥的重要行为学途径。"},{"id":"22.9","t":"领域性与集群的权衡","s":2,"c":"22. 领域行为","x":"领域性与集群是两种对立的资源利用策略：领域性独占资源但需支付防御成本，集群共享信息与安全但需承受竞争。当资源不可防御或捕食压力极高时，动物放弃领域而集群（如冬季的雀群、风暴中的海鸟）；当资源集中且可防御时，领域性占优。同一物种可在不同季节在两种策略间切换，这种\"策略柔性\"本身就是适应性的表现。"},{"id":"23.1","t":"栖息地选择与出生地偏好","s":3,"c":"23. 栖息地选择与时空行为","x":"栖息地选择（habitat selection）是动物对环境特征的主动偏好，常表现为对特定植被结构、坡度、水源距离、巢址类型的非随机利用。幼年经验可塑造偏好，称\"出生地偏好诱导\"（natal habitat preference induction）：在某一类型生境中出生的个体，成年后更倾向选择同类生境，即使该生境并非最优。这一机制可解释\"源—汇\"动态与再引入失败（把圈养个体放到不熟悉的生境类型中存活率低）。"},{"id":"23.2","t":"栖息地选择的线索","s":3,"c":"23. 栖息地选择与时空行为","x":"动物利用的线索包括自身直接评估（食物量、遮蔽度、天敌密度）与社会信息（同种个体的存在、叫声、巢的成功率）。利用他人成功信息称\"公共信息\"（public information）：巢址选择中，个体倾向在邻近同类巢成功的地点筑巢，而在失败地点附近回避；燕、崖沙燕的集群巢址选择即受此影响。此外还有异种吸引（heterospecific attraction）：迁移中的鸟类倾向与已经定居的异种混群，以快速判断生境质量。"},{"id":"23.3","t":"家域、活动节律与时空格局","s":3,"c":"23. 栖息地选择与时空行为","x":"动物的活动在时间和空间上都高度结构化：家域的形状反映资源分布与地形，灵长类的日活动路线常有\"重复利用\"的核心路径；活动节律受光照、温度、捕食风险与人类干扰共同塑造，许多原本夜行的兽类在人类活动区转向夜间或晨昏活动（如城市中的貉、野猪）。研究时空格局需要无线电遥测、GPS与相机网格，所得\"占用率\"（occupancy）是保护规划的基础数据。"},{"id":"23.4","t":"扩散、游牧与日常移动","s":3,"c":"23. 栖息地选择与时空行为","x":"扩散（dispersal）指个体从出生地或繁殖地单向迁出并定居他处，是基因交流与种群扩张的主要途径，通常表现性别偏倚（哺乳类多雄性扩散、鸟类多雌性扩散，与避免近亲繁殖、减少配偶竞争有关）。游牧（nomadism）指无固定路线的随机移动，常见于荒漠与极地资源不可预测的地区（如澳洲内陆的斑胸长脚鹬随降雨在盐湖之间辗转、非洲的牛羚追随降雨带移动）。日常移动（commuting）则是每日在巢与觅食地之间的往返，如海鸟的远洋觅食行程。"},{"id":"23.5","t":"集群的时空动态","s":2,"c":"23. 栖息地选择与时空行为","x":"集群类型包括繁殖群（海鸟的繁殖群、鹭的混合群）、越冬群（蝙蝠洞穴群、蛇的冬眠群）、防御群（麝牛、狒狒）与信息群（秃鹫跟随同伴寻找尸体）。集群的时间动态表现为\"日出离群、日落归群\"或\"季节性聚集\"，空间动态表现为\"聚集中心随资源移动\"。集群的规模受\"收益（安全、信息）—代价（竞争、疾病、被一网打尽）\"平衡决定。"},{"id":"23.6","t":"昼夜活动分配与环境梯度","s":2,"c":"23. 栖息地选择与时空行为","x":"动物的活动时段由光照与温度决定，并受捕食风险调节：沙漠啮齿类以夜行为主以避开高温与天敌，蜥蜴通过晨昏晒太阳调节体温、在正午躲入阴处；高纬度地区夏季的\"白夜\"使许多动物延长日活动时间。行为性体温调节（behavioral thermoregulation，如选择晒太阳、挤在一起、改变姿势）是动物应对温度最经济的方式，也是行为学与生理学交叉的常见考点。"},{"id":"23.7","t":"生境破碎化与行为响应","s":3,"c":"23. 栖息地选择与时空行为","x":"生境破碎化（habitat fragmentation）通过缩小斑块面积、增加隔离度、加剧边缘效应改变动物行为：领域面积被迫缩小、密度局部升高、扩散成功率下降、巢寄生与捕食率在边缘升高。行为学指标（领域大小、扩散距离、觅食行程）常被用作破碎化效应的早期指示。廊道（corridor）建设与\"行为连通性\"评估是缓解措施，其有效性常用个体的穿越率与基因流来检验。"},{"id":"23.8","t":"气候变化与物候错配","s":3,"c":"23. 栖息地选择与时空行为","x":"气候变暖使春季提前，若不同营养级响应速度不同，就会出现物候错配（phenological mismatch）。荷兰的大山雀研究是经典：毛虫高峰随温度提前，而大山雀产卵期提前幅度较小，导致育雏期与毛虫高峰错开、雏鸟体重与存活率下降；但由于产卵期本身可塑性存在，部分个体能通过\"跟踪\"线索调整，选择压力因而作用于可塑性本身。迁徙鸟类到达时间与当地资源高峰的错配也是当前保护生物学的热点。"},{"id":"24.1","t":"通讯的定义与信号、线索的区别","s":3,"c":"24. 通讯行为","x":"通讯（communication）指发送者产生的、经进化形成的信号（signal）改变了接收者行为，且平均而言对双方都有利的过程。信号与线索（cue）的区别是关键：信号是被选择塑造\"用于传递信息\"的特征（如孔雀尾屏、蜜蜂舞蹈），对发送者有利；线索只是被接收者利用的信息（如猎物的体温、寄生蜂利用的宿主气味），不一定对发送者有利。判断某特征是否为信号，标准是\"它是否具有为传递信息而被选择塑造的形态与行为特征\"。"},{"id":"24.2","t":"通讯的功能分类","s":3,"c":"24. 通讯行为","x":"按功能可分为：物种识别（避免杂交，如蛙的种特异性鸣叫）、个体识别（如\"亲爱的敌人效应\"）、性别与繁殖状态宣告（如雌蛾的性信息素）、社会等级维持（如灵长类的体态与面部表情）、警报（如鸟类的报警叫声、猴的三种报警声分别对应豹、鹰、蛇）、招募与引导（如蜜蜂舞蹈、蚂蚁踪迹）、乞食与喂食（如雏鸟的张口与啄击）、同步化（如珊瑚的产卵同步、蝉的集体羽化）、维持社会联系（如灵长类的理毛、象的触摸）。"},{"id":"24.3","t":"视觉通讯","s":3,"c":"24. 通讯行为","x":"视觉信号适合昼行、开阔环境，传递速度快但易被遮挡、易被捕食者发现。常见形式有体色与婚装（三刺鱼红腹、孔雀尾屏）、姿态与动作（招潮蟹挥螯、犬的摇尾、猿的露齿）、发光（萤火虫的种特异闪光节律、深海鱼的光器）、体色快速改变（乌贼、变色龙的色素细胞调控）。视觉信号的\"仪式化\"程度往往最高，也最容易被做成模型与回放实验。"},{"id":"24.4","t":"听觉通讯","s":3,"c":"24. 通讯行为","x":"听觉信号可穿越植被与障碍、作用距离远，但暴露位置且能耗高。昆虫以摩擦发声（蟋蟀、螽斯）或振动（蝉的鼓膜器），蛙类以鸣囊放大鸣声形成合唱，鸟类以鸣唱宣示领域与吸引配偶，鲸类以低频歌声进行远距离通讯（低频在海水中衰减慢），象能用 14～24 Hz 的次声交流数公里。蝙蝠则在通讯之外演化出回声定位（echolocation），用高频超声构建\"声学图像\"。"},{"id":"24.5","t":"化学通讯","s":3,"c":"24. 通讯行为","x":"化学信号（信息素，pheromone）稳定、传播广、难以伪造，适合夜间与远距离，但传递慢、难以即时停止。家蚕雌蛾释放蚕蛾醇（bombykol），雄蛾用触角上大量嗅觉受体在数公里外探测；蚂蚁以踪迹信息素标记路线，招募同伴并随食物耗尽逐渐停止分泌；蜂王信息素抑制工蜂卵巢发育；哺乳类以尿液与腺体分泌物标记领域与繁殖状态。信息素的\"专一性\"与\"可分解性\"是它能作为可靠信号的两个前提。"},{"id":"24.6","t":"触觉与振动通讯","s":2,"c":"24. 通讯行为","x":"触觉信号要求个体接触或近距，适合黑暗与水下环境：蚂蚁用触角相碰交换食物与信息，灵长类以理毛维持联盟，蜜蜂在巢内跳舞时，跟随蜂用触角与身体接触舞者、感知其振动与朝向（舞蹈的\"触觉—振动\"成分是近年研究重点）。振动通讯（seismic communication）见于蜘蛛的网振动、蝉的枝振动与鼹鼠的地面敲击。"},{"id":"24.7","t":"电通讯","s":2,"c":"24. 通讯行为","x":"电通讯见于能产生电场的鱼类（电鳗、电鲇、象鼻鱼、裸背电鳗），它们以电器官产生放电（electric organ discharge, EOD），用体表的电感受器感知自身电场的畸变，实现\"电定位\"；同时通过改变放电频率与波形传递物种、性别、个体与状态信息。电通讯的优势是在浑浊、黑暗的水中不受能见度限制，缺点是作用距离仅数米、且易被同类窃听与干扰（jamming）。"},{"id":"24.8","t":"蜜蜂舞蹈通讯的完整机制","s":3,"c":"24. 通讯行为","x":"蜜蜂的舞蹈（dance language）是唯一被完整破译的\"符号通讯\"。食物在50～100 m 内时，采集蜂跳圆舞（round dance），只传达\"附近有食物\"而不编码方向；距离更远时跳摆尾舞（waggle dance），在巢脾上走\"8\"字形，直线段的摆尾时长编码距离（时间越长距离越远），直线段相对于重力垂线的夹角编码相对于太阳方位的方向（\"上\"即朝向太阳），舞蹈的节奏、振动幅度也携带信息，舞者体表附着的花香则提示食物种类。1950 年代冯·弗里施的结论曾受质疑（Wenner 认为蜜蜂靠气味搜索），后续用机械\"机器蜂\"在黑暗巢内精确复现舞蹈角度与振动的实验证实了舞蹈编码的有效性。"},{"id":"24.9","t":"鸟鸣的方言、个体识别与噪音适应","s":3,"c":"24. 通讯行为","x":"许多鸟类的鸣唱存在地理变异，形成方言（dialect）：白冠带鹀在同一地区内不同群体有稳定的曲目差异，方言通过幼鸟学习传承，可降低群体间的基因交流并被雌性用作择偶线索。鸟鸣还能编码个体身份（邻居识别）与体型（低频鸣唱对应大体型，故雌性偏好低频）。城市化带来的低频谱噪声使大山雀等鸟类提高鸣唱最低频率与音量（\"伦巴第效应\"的鸟类版本），成为\"人类活动驱动行为快速进化\"的经典案例。"},{"id":"24.10","t":"信号的诚实性与欺骗","s":3,"c":"24. 通讯行为","x":"信号为何可信？累赘原理（handicap principle）主张高代价的展示只有高质量个体能承担，因而信号诚实；\"索引信号\"（index signal）则认为某些信号（如低频鸣叫对应大体型）受物理约束而无法伪造，因而必然诚实。欺骗信号则是在\"接收者无法立即核查\"时出现的寄生策略，如 Photuris 雌虫模拟他种闪光诱食雄虫、杜鹃雏鸟的超常乞食信号、无毒的贝氏拟态者。判断某一信号是否稳定，取决于\"欺骗的收益\"与\"接收者反欺骗的代价\"之间的军备竞赛。"},{"id":"24.11","t":"通讯的代价与私密通道","s":2,"c":"24. 通讯行为","x":"通讯对发送者有利也可能招致捕食者与竞争者窃听（eavesdropping），因此演化出\"私密通道\"（private channel）：紫外反射（许多鸟类与昆虫能见、多数捕食者不能）、高频超声（啮齿类与蛾类用于近距离求偶，蝙蝠之外的天敌听不到）、快速衰减的化学信号、定向振动。信号通道的选择本质上是\"有效传播\"与\"隐蔽性\"的权衡，这一权衡决定了不同类群在不同生境中的主流通讯方式：开阔昼行环境以视觉为主，密林与夜间以听觉与化学为主，水下以化学、电与声为主。"},{"id":"25.1","t":"两性差异的根源：配子与亲代投资","s":3,"c":"25. 择偶与性选择","x":"雌雄差异的起点是配子大小的不对称：卵大而少、精子小而多，因而雌性的初始投资高于雄性。特里弗斯据此提出亲代投资（parental investment）理论：投资多的一方（通常是雌性）在择偶上更挑剔、在竞争配偶上更被动；投资少的一方（通常是雄性）在配偶竞争上更激烈。这一逻辑可解释性二型的普遍方向，也解释了\"性角色逆转\"：当雄性承担主要育幼（如水雉、瓣蹼鹬）时，雌性反而更大、更艳丽、更好斗。"},{"id":"25.2","t":"性选择的定义与两类机制","s":3,"c":"25. 择偶与性选择","x":"性选择（sexual selection）指由于繁殖成功差异而产生的选择，作用对象是与获取配偶直接相关的性状，其效果可能牺牲生存（如孔雀的尾屏）。机制有两类：性内选择（intrasexual selection），即同性个体间的竞争（打斗、展示耐力、精子竞争）；性间选择（intersexual selection），即一方（多为雌性）对另一方特征的偏好。自然选择与性选择并不矛盾，性选择是自然选择的一个子类，其\"适应度\"以繁殖成功而非存活为度量。"},{"id":"25.3","t":"雄性竞争的方式","s":3,"c":"25. 择偶与性选择","x":"雄性竞争包括仪式化打斗（马鹿的吼叫与角斗、海滩上雄性海象的体形对抗）、占有资源以吸引雌性（园丁鸟修建并装饰求偶亭、织雀筑巢）、耐力展示（蛙长时间鸣叫）、偷配与拟雌（侧斑蜥蜴的黄色型、鲑鱼的拟雌小型雄鱼）、精子竞争（蜻蜓交配前清除竞争者精子、交配后守卫）。竞争方式的分布取决于\"资源是否可防御\"与\"打斗代价\"，这与第 11 章的博弈分析直接对应。"},{"id":"25.4","t":"性二型与性比的进化","s":3,"c":"25. 择偶与性选择","x":"性二型（sexual dimorphism）指雌雄在体形、色彩、武器上的差异，其程度与婚配制度的竞争强度相关：一雄多雌程度越高，雄性体形相对越大、武器越发达（如马鹿、海象、大猩猩）；单配制种类的雌雄差异小。性比方面，费希尔（Fisher）的性比理论指出，在随机交配群体中，父母对儿子与女儿的总投资应相等，故性比趋向 1:1；局部配偶竞争（local mate competition）会使偏雌性比在群体内被选择，如许多寄生蜂的偏雌性比。"},{"id":"25.5","t":"雌性选择的证据","s":3,"c":"25. 择偶与性选择","x":"雌性选择（female choice）的实验证据主要来自\"操纵雄性特征\"的经典研究。安德松（M. Andersson）对长尾寡妇鸟（Euplectes progne）的野外实验：把雄鸟尾羽剪短或加长，结果尾更长的雄鸟获得的巢与雌性显著更多，直接证明雌性偏好长尾。孔雀鱼（Poecilia reticulata）中，雌性偏好橙色斑块大的雄鱼，而高捕食压力种群中雄鱼色彩变淡，说明性选择与自然选择在\"醒目\"这一性状上相互对抗。"},{"id":"25.6","t":"选择的直接收益","s":3,"c":"25. 择偶与性选择","x":"直接收益（direct benefit）指雌性从择偶中立即获得的资源，包括食物与领地（雄鸟的领域质量）、nuptial gift（婚礼物，如舞蹈蝇用丝包裹的猎物、蟋蟀的精包）、保护（免受其他雄性骚扰）、优质巢址与育幼协助。直接收益模型预测雌性应偏好\"资源持有者\"而非\"装饰最华丽者\"，这在资源匮乏、雄性参与育幼的物种中尤为明显：雌性大山雀偏好能提供优质巢洞与喂食的雄鸟。"},{"id":"25.7","t":"间接收益：好基因假说","s":3,"c":"25. 择偶与性选择","x":"间接收益（indirect benefit）指雌性通过择偶提高子代的遗传质量。好基因假说（good genes hypothesis）认为炫耀性状真实反映雄性的遗传品质；汉密尔顿与祖克（Hamilton & Zuk）提出寄生虫假说：只有抗寄生虫能力强的雄性才能承担昂贵的展示，故雌性偏好艳丽者即获得抗性基因，其预测是\"寄生虫丰富的地区，性二型更显著\"。支持证据包括：对称性高（波动不对称低）的家鸡雄性存活率与交配成功率更高；被寄生感染的雄鸟羽色暗淡、鸣唱简化，雌性回避。"},{"id":"25.8","t":"费希尔失控与\"性感儿子\"","s":3,"c":"25. 择偶与性选择","x":"费希尔（R. A. Fisher）提出失控选择（runaway selection）：若雌性普遍偏好某一雄性特征，则选择该特征的雌性会生出\"更受偏爱的儿子\"，从而获得额外繁殖收益；这一偏好与特征相互强化，形成正反馈，使特征不断夸张直至被自然选择制止。该模型的预测是\"偏好与特征在系统树上协同演化\"，并且即使特征与生存力无关，也能因\"性感儿子效应\"（sexy son hypothesis）而扩散。它与好基因假说的区别在于：失控模型不要求特征诚实反映品质，只需要\"大家都喜欢\"。"},{"id":"25.9","t":"感觉偏好与感觉偏倚","s":3,"c":"25. 择偶与性选择","x":"感觉偏倚（sensory bias）假说认为，某些偏好并非为择偶而演化，而是既有感觉系统的副产物。剑尾鱼的雌性偏好\"带长剑\"的雄性，实验显示她们同样偏好被人为延长下尾鳍的雄鱼，甚至偏好非鱼类的长形物体，提示偏好源于对\"长而摆动的物体\"的先天注意倾向；某些蛙的雌性偏好低频鸣叫，而低频恰是\"大体型\"的物理指标（索引信号）。这一假说提醒我们：不能把一切偏好都解释为\"为了好基因\"。"},{"id":"25.10","t":"择偶标准的诚实性判据","s":2,"c":"25. 择偶与性选择","x":"判断某择偶标准是否诚实，可看三条：该特征的表达是否与个体条件（营养、健康、年龄）正相关；该特征的维持是否代价高昂（累赘原理）；该特征是否受物理约束而难以伪造（索引信号）。鹿角大小受营养与年龄限制、鸟类羽色受类胡萝卜素摄取量限制、鸣唱频率受体形限制，都使这些特征难以被低质量个体\"假装\"。反例是某些炫耀可被欺骗性放大，此时接收者会演化出核查机制。"},{"id":"25.11","t":"性冲突与拮抗共进化","s":3,"c":"25. 择偶与性选择","x":"性冲突（sexual conflict）指雌雄在最适交配次数、配偶数、投资分配上存在分歧，一方的适应会降低另一方适合度，从而引发\"军备竞赛\"。果蝇雄性精液中的附属腺蛋白（Acp）可提高雄性精子竞争力，却缩短雌性寿命，雌性则演化出抗性；水黾（Gerris）雄性强行交配，雌性演化出抵抗结构；某些昆虫的\"性食同类\"（sexual cannibalism）也是冲突的表现。性冲突是解释\"为何存在看似有害的性状\"的重要框架，与\"为了物种利益\"的旧解释截然不同。"},{"id":"26.1","t":"婚配制度的类型与判定","s":3,"c":"26. 婚配制度","x":"婚配制度（mating system）描述一个繁殖季内个体与配偶的结合方式，分为单配（monogamy，一雄一雌）、一雄多雌（polygyny）、一雌多雄（polyandry）与混交（promiscuity，无稳定配对）。判定不能只看\"是否成对出现\"，而要看实际交配与繁殖贡献，现代研究常用分子亲子鉴定，发现许多\"社会性单配\"的鸟类存在高比例婚外父权（extra-pair paternity），因而有\"社会婚配制度\"与\"遗传婚配制度\"之分。婚配制度特征典型实例关键生态条件单配一雄一雌，常有育幼分工许多海鸟、长臂猿育幼需双亲、配偶难寻一雄多雌一雄多雌，雄性竞争激烈马鹿、海象、园丁鸟雌性成簇分布、资源可防御一雌多雄一雌多雄，性角色常逆转水雉、瓣蹼鹬雄性主导育幼、雌性竞争混交无稳定配对，群体竞争黑猩猩、多数昆虫配偶难守卫、精子竞争"},{"id":"26.2","t":"单配制的进化条件","s":3,"c":"26. 婚配制度","x":"单配制多在三种条件下演化：其一，育幼必须双亲合作（如许多海鸟需一亲孵卵、一亲觅食，雏鸟才能存活）；其二，配偶的\"可获得性\"低（密度低、搜寻成本高），守住一个配偶比另寻更划算（配偶守卫假说）；其三，雌性能够有效惩罚不忠或雄性通过\"配偶守卫\"降低被戴绿帽的风险。单配制常伴随较高的婚外父权，说明\"社会单配\"更多是合作育幼的安排，而非绝对的一对一交配。"},{"id":"26.3","t":"一雄多雌的三种途径","s":3,"c":"26. 婚配制度","x":"按 Emlen 与 Oring 的框架，一雄多雌通过三条途径实现：资源保卫型（resource defense polygyny），雄性控制雌性所需的资源（食物、巢址）从而吸引多雌，如红翅黑鹂守卫沼泽中的巢区；雌性保卫型（female defense polygyny，harem），雄性直接围守成群雌性，如海象、大猩猩；雄性支配型（male dominance polygyny，lek），雄性在求偶场集中展示、由雌性选择，如尖尾松鸡、园丁鸟。三者的共同前提是\"雌性在时间或空间上可被雄性控制\"。"},{"id":"26.4","t":"求偶场（lek）的悖论与解释","s":3,"c":"26. 婚配制度","x":"求偶场（lek）指雄性聚集在固定的小区域进行展示、不提供资源与育幼、由雌性自由选择的繁殖方式，其悖论是\"为何雄性要聚集而不是分散\"以及\"为何少数雄性获得绝大多数交配\"。解释包括：hotshot 假说（聚集在成功者周围可\"蹭\"到注意力）、hotspot 假说（聚集点本身是雌性必经之地）、blackhole假说（聚集提高整体吸引力）；而\"少数雄性垄断\"源于雌性偏好的一致性，偏好一致又使选择的遗传收益下降（lek paradox），主流解释是突变—选择平衡与基因—环境交互维持了遗传变异。"},{"id":"26.5","t":"一雌多雄与性角色逆转","s":3,"c":"26. 婚配制度","x":"一雌多雄（polyandry）多见于雄性承担主要育幼的类群。水雉（Jacana spinosa）雌性体形更大、具距、保卫领地并依次与多只雄性配对，雄性独自孵卵与护雏；瓣蹼鹬（Phalaropus）雌性在繁殖后即离开，雄性孵卵。性角色逆转的生态前提是\"雄性育幼能力成为限制资源\"，此时雌性间的竞争加剧，性二型方向随之反转，是\"性选择逻辑\"最有说服力的验证。"},{"id":"26.6","t":"婚外父权与精子竞争","s":3,"c":"26. 婚配制度","x":"分子亲子鉴定显示，社会性单配的鸟类中婚外父权比例可从 0 到 70% 以上，篱雀、蓝山雀都是高值物种。婚外配的收益包括获取更优基因、提高遗传多样性、保险（insurance against infertility）；代价是失去配偶的育幼投入、被惩罚、感染性病。雄性应对策略包括交配后守卫、提高交配频率、交配栓、精子竞争（精子数量与速度的竞争），这些策略的强度可预测婚外父权的比例。"},{"id":"26.7","t":"婚配制度与生态因素：雌性分布模型","s":3,"c":"26. 婚配制度","x":"Emlen 与 Oring 提出：婚配制度取决于\"雌性在时间与空间上的分布\"，而雌性分布又取决于资源分布与其可防御性。若资源均匀且不可防御，雌性分散，雄性无法垄断，倾向单配；若资源斑块化且可防御，雌性聚集于雄性的领域内，倾向一雄多雌；若雄性提供育幼而雌性可自由移动，则可能出现一雌多雄。这一模型把\"生态—行为—婚配制度\"串成因果链，是竞赛论述题的高分框架。"},{"id":"26.8","t":"岩鹦（dunnock）的婚配可塑性","s":3,"c":"26. 婚配制度","x":"岩鹦（Prunella modularis）是婚配制度研究的经典材料：同一群体中同时存在单配、一雄多雌、一雌多雄与多雄多雌，取决于领域内雌性与雄性的数量比与领域质量。雌性在多个雄性领域重叠处可获得更多帮助与保护，雄性则通过\"追随雌性\"决定是否留守。更关键的是，雄性对后代的投入与其\"父权确定性\"正相关：与雌性交配次数越多的雄性喂食越勤，这直接支持了\"父权确定性—育幼投入\"假说。"},{"id":"26.9","t":"婚配制度的测量与常见误区","s":2,"c":"26. 婚配制度","x":"测量婚配制度需要三类数据：社会配对关系（观察）、实际交配（行为观察或遗传标记）、繁殖贡献（亲子鉴定与巢内卵数归属）。常见误区有三：把\"成对出现\"等同于单配；把\"雄性领域内有多雌\"等同于一雄多雌（可能雌性并不与该雄交配）；把\"一季内的制度\"当作物种的固定属性（同种在不同年份、不同密度下可变）。答题时应强调\"婚配制度是生态条件的产物，具有可塑性\"。"},{"id":"27.1","t":"亲代投资与两性差异","s":3,"c":"27. 亲代抚育与亲缘选择","x":"亲代投资（parental investment）指亲代对单个子代的任何投入（配子、育幼、保护、喂食），其代价是亲代未来繁殖能力的下降。由于雌性初始投资大，其\"每个子代已投入的成本\"更高，因而更倾向继续投资；雄性则倾向\"再找下一个配偶\"。这一不对称解释了三件事：雌性更挑剔、雄性更易离弃、雌雄在育幼分工上的冲突。注意\"投资\"以\"对子代的作用\"和\"对亲代未来繁殖的代价\"共同定义，不能只看投入的时间长短。"},{"id":"27.2","t":"亲代抚育的类型","s":3,"c":"27. 亲代抚育与亲缘选择","x":"抚育形式包括：产卵前的准备（选巢址、筑巢）、孵卵（鸟类、部分爬行类）、护卵与护幼（慈鲷、章鱼）、喂食（鸟类、哺乳类）、清洁与保暖、教导（食肉兽教捕猎、黑猩猩教用工具）。无抚育者靠\"数量策略\"（多数鱼类与昆虫产大量卵），有抚育者靠\"质量策略\"（少而精）。海龟产卵后即离去、章鱼守巢不食直至死亡、帝企鹅雄性孵卵数月不食，是三种极端对比。"},{"id":"27.3","t":"亲子识别的机制","s":3,"c":"27. 亲代抚育与亲缘选择","x":"亲子识别（parent–offspring recognition）在\"子代混杂\"风险高的物种中最发达。机制包括：气味（绵羊凭气味识别自己的羔羊，若在产后数小时内分离则识别失败）、声音（企鹅、海豹在数千个体的集群中凭叫声定位自己的幼体）、视觉（灵长类凭面部）、巢位（多数鸟类只喂自己巢中的雏鸟，以\"巢\"代替\"个体\"）。识别失败会导致\"错养\"或\"弃养\"，因此识别机制的精确度与集群密度、子代移动能力相关。"},{"id":"27.4","t":"亲子冲突理论","s":3,"c":"27. 亲代抚育与亲缘选择","x":"特里弗斯的亲子冲突（parent–offspring conflict）指出：亲代对\"当前子代\"的投资最适点与子代对\"自身获得\"的需求最适点不同，因为子代与亲代、与同胞的亲缘系数只有 0.5；子代期望的抚育量约为亲代愿意提供量的两倍。这一理论预测冲突在断乳、离巢、同胞竞争阶段最明显，并预测当父权不确定或同胞年龄差大时冲突更强。它是\"家庭内部也有进化冲突\"的核心论点，与\"亲代总是为子代牺牲\"的直觉相反。"},{"id":"27.5","t":"亲子冲突的实例","s":3,"c":"27. 亲代抚育与亲缘选择","x":"断乳冲突（weaning conflict）在哺乳动物中普遍：幼兽在母兽再次怀孕后仍频繁索乳，母兽以回避、拒绝姿势应对，形成持续数周的\"拉锯\"。妊娠冲突（gestational conflict）指胎儿通过胎盘激素提高母体血糖供给，母体则以胰岛素抵抗调节，人类妊娠糖尿病被视为这一冲突的\"副作用\"。此外，雏鸟的超常乞食信号（第 8.6 节）与亲代的\"配额喂食\"也是冲突表现。"},{"id":"27.6","t":"Hamilton 法则与亲缘选择","s":3,"c":"27. 亲代抚育与亲缘选择","x":"亲缘选择（kin selection）指通过帮助携带相同基因的亲属而间接传递基因的过程，其判据是 Hamilton 法则：rB > C，其中 r 为亲缘系数、B 为受益者获得的繁殖收益、C 为利他者付出的代价。计算题的关键是正确取 r：亲子与全同胞 0.5，祖孙与半同胞 0.25，表亲 0.125，膜翅目姐妹 0.75。例：一只工蜂放弃产 10 个自己的子代（C=10）去帮助母亲多产 30 个姐妹（B=30），因 r(姐妹)=0.75、r(子代)=0.5，得 0.75×30=22.5 > 0.5×10=5，故该行为被选择保留。"},{"id":"27.7","t":"亲缘识别的机制","s":3,"c":"27. 亲代抚育与亲缘选择","x":"动物如何\"知道\"谁是亲属？常见机制有：空间线索（在同一巢、同一领域出生者视为亲属，如许多鸟类与蜂类的\"巢口气味\"）、表型匹配（\"绿须效应\"式的自我参照识别，如小鼠的 MHC 气味、蜜蜂的巢友气味）、熟悉度（一起长大即视为亲属）、认知推断（灵长类可通过母亲的社会关系推断母系亲属）。由于识别机制可能出错，寄生者（如杜鹃雏鸟、社会性昆虫的寄生者）常利用这些线索\"骗取\"抚育。"},{"id":"27.8","t":"巢寄生与反寄生的军备竞赛","s":3,"c":"27. 亲代抚育与亲缘选择","x":"巢寄生（brood parasitism）指寄主代为孵育寄生者的子代。杜鹃、牛鹂是专性寄生者，其卵在颜色与斑点上模拟寄主卵，雏鸟孵出早、生长快、并具有超常的乞食信号，甚至把寄主卵或雏鸟推出巢外。寄主的反适应包括：识别并弃置异卵（大苇莺对花纹差异大的卵有较高弃置率）、攻击成体寄生者（群起围攻杜鹃）、缩小产卵窗口、选择更隐蔽的巢址。双方的适应相互追逐，形成军备竞赛，这一系统是\"共进化\"的最佳教学案例。"},{"id":"27.9","t":"同胞竞争与\"窝内淘汰\"","s":2,"c":"27. 亲代抚育与亲缘选择","x":"同胞竞争（sib–sib competition）指同一窝内子代对亲代投资的争夺，表现形式包括乞食强度竞赛、抢占有利位置、甚至同胞相残（siblicide）。鲣鸟的\" facultative / obligate siblicide\"中，先孵出的雏鸟会攻击后孵者，在食物短缺时后者死亡；鲨鱼在子宫内即相互捕食；鹰、鹳的\"窝内淘汰\"使亲代得以在食物不足时只养大一只。亲代常通过\"差别喂食\"调节，说明同胞竞争的结果受亲代策略影响。"},{"id":"27.10","t":"亲代抚育的权衡：数量与质量","s":3,"c":"27. 亲代抚育与亲缘选择","x":"亲代抚育的核心权衡是\"子代数量 vs 子代质量\"。Lack 的窝卵数假说预测最适窝卵数使\"出飞雏鸟数\"最大，补卵实验显示超过最适值后出飞数下降（雏鸟质量差、亲鸟耗竭）。另一个权衡是\"当前窝 vs 未来窝\"：在食物匮乏或自身状况差时，亲鸟应减少投入以保全未来繁殖，这解释了\"弃巢\"与\"减少喂食\"等现象。理解这两条权衡，才能正确解释\"为什么窝卵数不无限增加\"。"},{"id":"28.1","t":"社会组织的构成要素","s":3,"c":"28. 社会组织与社会生活","x":"社会组织（social organization）由四个要素描述：群体的规模与年龄性别结构、群体的时空稳定性、婚配制度、个体间的分工与等级。按社会性程度可分为： solitary（独居）、aggregation（临时聚集）、群居（social group）、合作繁殖群体与真社会性（eusociality）。判断社会性程度的关键指标是\"生殖分工\"与\"世代重叠\"以及\"合作育幼\"，这三条正是真社会性的判据。"},{"id":"28.2","t":"社会生活的收益","s":3,"c":"28. 社会组织与社会生活","x":"群居的收益有六条：降低被捕食风险（稀释效应、集体警戒、群体反击）、提高觅食效率（信息共享，如秃鹫跟随同伴、鸦群发现尸体）、便于寻找配偶（减少搜寻成本）、协作育幼（帮助者提高雏鸟存活）、协作防御领域与资源、行为性体温调节（挤在一起减少散热，如企鹅群、蝙蝠群）。收益的大小随环境变化，这是\"群居程度可塑性\"的基础。"},{"id":"28.3","t":"社会生活的代价","s":3,"c":"28. 社会组织与社会生活","x":"群居的代价包括：资源竞争加剧（同一领域内个体分摊食物）、疾病与寄生虫传播加快（密度效应，如蜂群中的螨害）、生殖干扰与杀婴（新雄狮接管群后杀死前雄的子代）、错配与\"被迫合作\"（被强势个体霸占资源）、被\"一网打尽\"的风险（集群易被天敌集中攻击）。群居的进化取决于收益与代价的净差，因此同一物种在不同季节可聚可散。"},{"id":"28.4","t":"优势等级与啄序","s":3,"c":"28. 社会组织与社会生活","x":"优势等级（dominance hierarchy）指群体内稳定的、可预测的资源优先序列，最初在鸡群中被描述为\"啄序\"（peck order）。等级的测量依赖\"定向攻击与退让\"的方向性，可用 David 分数或胜率矩阵量化，要求等级具有跨时间的稳定性与跨情境的一致性。灵长类的等级影响食物、理毛伙伴与繁殖机会；等级并非固定不变，可通过结盟、年龄增长与\"政治\"操作改变。"},{"id":"28.5","t":"等级的形成与维持机制","s":3,"c":"28. 社会组织与社会生活","x":"等级由三类因素维持：个体属性（体形、年龄、武器）、社会关系（联盟与支持，如狒狒通过理毛建立联盟，雌性狒狒的地位常继承母系）、以及\"记忆与仪式\"（胜者效应、失败者效应，通过仪式化威吓避免反复打斗）。冲突后的和解（reconciliation，如黑猩猩冲突后互相理毛、拥抱）与安慰（consolation，第三方理毛受害者）是维持群体稳定的重要机制，可降低冲突升级的成本。"},{"id":"28.6","t":"领域性群体与巢群","s":2,"c":"28. 社会组织与社会生活","x":"许多社会性动物组成\"领域性群体\"：群体共同保卫一片领域并排斥其他群体，如长臂猿的家庭群、狼群、黑猩猩群落。海鸟与蜂类则形成\"巢群\"，个体各自繁殖但共享\"群体防御\"的好处，如崖海鸦的密集巢群使捕食者难以定位单个巢。群体边界常通过\"边界巡逻与合唱\"维持（长臂猿的晨鸣、狼的集体嚎叫），这既是宣示也是减少实际冲突的仪式。"},{"id":"28.7","t":"无脊椎动物的社会","s":3,"c":"28. 社会组织与社会生活","x":"腔肠动物的群体（如僧帽水母）是\"个体组成的群体\"，分工靠形态分化；社会性昆虫（蚂蚁、蜜蜂、黄蜂、白蚁）具真社会性：生殖分工（蜂王与工蜂）、世代重叠、合作育幼，工蜂/工蚁承担巢内与巢外的不同职能（年龄分工）。白蚁与蚂蚁独立起源，白蚁是二倍体、蚂蚁与蜜蜂是单倍二倍体，说明真社会性可在不同遗传体系下多次起源，是\"趋同进化\"的重要例证。"},{"id":"28.8","t":"脊椎动物的社会","s":2,"c":"28. 社会组织与社会生活","x":"鱼类以集群为主，形成\"等级—领域\"的简单结构；两栖类多为短期聚集（繁殖场）；爬行类中鳄类有母性护幼、蜥蜴有领域与等级；鸟类社会最复杂，从繁殖群、越冬群到合作繁殖；哺乳动物的社会包括母系群（象、鬣狗）、父系群（大猩猩的部分群体）、配对家庭群（长臂猿）与真社会性的裸鼹鼠。社会结构的类型与\"资源分布、捕食压力、育幼需求\"三大生态因素相关。"},{"id":"28.9","t":"社会网络与联盟政治","s":2,"c":"28. 社会组织与社会生活","x":"把群体视为\"网络\"可量化个体间的互动强度（理毛、靠近、支持），并计算个体的\"中心度\"与\"连接度\"。研究发现，中心度高的雄性狒狒获得更多繁殖机会，且其\"社会关系质量\"影响后代存活；黑猩猩的联盟具有\"政治\"性质：雄性通过结盟挑战首领，联盟的稳定性取决于双方能否\"惩罚背叛\"。社会网络分析把行为学与网络科学结合，是近年研究热点。"},{"id":"29.1","t":"利他行为的定义与分类","s":3,"c":"29. 利他与合作","x":"利他行为（altruism）指降低自身适合度、提高他人适合度的行为。按受益者分为亲缘利他（受益者为亲属，由亲缘选择解释）与互惠利他（受益者为非亲属，由未来回报解释）。判定\"是否利他\"必须核算行为者的适合度代价，而不能只看\"是否看起来无私\"：蜜蜂螫针攻击入侵者致死，因受益者是姐妹，可被亲缘选择解释；而雄狮赶走竞争者后占有雌性，虽然\"勇敢\"，却不属利他。"},{"id":"29.2","t":"Hamilton 法则的定量计算","s":3,"c":"29. 利他与合作","x":"计算步骤是：确定行为者与受益者的亲缘系数 r、估计行为者因该行为减少的子代数 C、估计受益者因此增加的子代数 B，代入 rB > C 判断是否成立。例一：一只鸟放弃自己巢中的 2 个卵（C=2）去帮助全同胞姐妹养活 5 个额外雏鸟（B=5，r=0.5），0.5×5=2.5>2，行为可扩散。例二：帮助半同胞兄弟（r=0.25），则需 B>8 才划算。注意 B 与 C 必须用\"繁殖量\"而非\"行为次数\"衡量，且要扣除行为本身的存活风险。"},{"id":"29.3","t":"亲缘选择与真社会性的起源","s":3,"c":"29. 利他与合作","x":"真社会性（eusociality）的判据是：生殖分工（部分个体不育）、世代重叠、合作育幼。其起源至少有四条路径，分别由不同机制解释：（1）单倍二倍体使姐妹间 r=0.75，帮助母亲养妹妹比自己生育更有利（膜翅目）；（2）近亲繁殖提高全群体平均亲缘度（白蚁、裸鼹鼠）；（3）生态约束使独立建巢极难，帮助成为\"次优选择\"（合作繁殖鸟类）；（4）父母操控（parental manipulation）使子代被迫留下帮助。竞赛中常要求\"任举两例并说明机制\"，正确做法是明确配对物种与机制。"},{"id":"29.4","t":"单倍二倍体假说","s":3,"c":"29. 利他与合作","x":"膜翅目的性别决定为单倍二倍体：雌性由受精卵发育（二倍体），雄性由未受精卵发育（单倍体）。由此，姐妹间共享父本全部基因、母本基因各半，亲缘系数 r=3/4；姐妹与兄弟 r=1/4；母女 r=1/2。因此工蜂/工蚁帮助母亲生产\"更多姐妹\"的遗传收益高于自己生育，且群体投资应偏向雌性（性比投资3:1），这一预测在多种蚂蚁中得到验证（Trivers & Hare）。该假说不能解释白蚁与裸鼹鼠的真社会性，故只是\"多条路径之一\"，不能当作唯一原因。"},{"id":"29.5","t":"生态约束与近交假说","s":2,"c":"29. 利他与合作","x":"生态约束假说（ecological constraint hypothesis）认为真社会性的前提是\"独立繁殖极难\"：裸鼹鼠生活在东非硬土中，挖掘极耗能、食物块茎分散且巨大，单个个体无法既挖掘又觅食，故留在群体中帮助成为最优；白蚁以木质为食，需肠道共生菌，幼体必须由成体\"接种\"才能取食，形成不可分离的合作。近交假说则指出，长期近交使群体成员亲缘度整体升高，从而使帮助行为对任何成员都\"划算\"。这两条解释共同说明：真社会性不只靠亲缘系数，还要靠\"生态上无法单干\"。"},{"id":"29.6","t":"互惠利他与囚徒困境","s":3,"c":"29. 利他与合作","x":"互惠利他（reciprocal altruism）要求三个条件：个体重复相遇、能识别个体并记住历史、能惩罚欺骗。其逻辑与重复囚徒困境一致：在单次博弈中背叛占优，但重复博弈中\"以牙还牙\"能稳定合作（第 11.8 节）。互惠利他的难点是\"初始利他者如何不被剥削\"与\"如何防止最后一次性背叛\"，现实中的对策包括\"以牙还牙 + 宽容\"、声誉机制、\"市场效应\"（援助稀缺时价格提高）。"},{"id":"29.7","t":"互惠利他的经典实例","s":3,"c":"29. 利他与合作","x":"吸血蝙蝠（Desmodus rotundus）的反哺是最佳实例：夜间吸不到血的个体（约 60% 的夜晚会失败，饥饿 60 小时即死亡）会向同巢个体乞食，饱食者吐出部分血餐；反哺在同巢个体间频繁，且\"给予者\"与\"接受者\"在长期内趋于平衡，符合互惠利他的预测，非亲属间也存在。清洁鱼（Labroides dimidiatus）与客户鱼的互动则是\"服务—背叛\"模型：清洁鱼有时咬客户的组织（欺骗），客户则通过更换清洁站或追咬报复，形成\"以牙还牙\"式的稳定。"},{"id":"29.8","t":"警报呼叫、稀释效应与旁观者效应","s":3,"c":"29. 利他与合作","x":"警报呼叫（alarm call）是典型的\"看似利他\"行为：发出者暴露位置、吸引捕食者注意，却使同伴逃脱。解释有三：亲缘选择（受益者为亲属）、互利（群体混乱降低捕食效率，发出者亦受益）、以及\"操纵\"视角（发出者借同伴的逃窜掩护自己）。稀释效应（dilution effect）说明群体越大，任一个体被吃掉的概率越低，是一种\"被动受益\"的合作机制，与主动利他不同。旁观者效应（bystander effect）在动物中指冲突中第三方的反应：第三方常介入支持一方以维持群体稳定（policing），或在冲突后安慰受害者（consolation），其方向取决于与双方的关系与自身地位。"},{"id":"29.9","t":"绿须效应与表型匹配","s":2,"c":"29. 利他与合作","x":"\"绿须效应\"（greenbeard effect）是道金斯提出的思想实验：若存在一个基因同时导致\"长绿须\"\"识别绿须\"\"帮助绿须者\"，则该基因可稳定扩散，不需要亲缘关系。真实案例稀少：火蚁的 Gp-9 基因多态影响群体气味识别与社会型，被认为是接近绿须的机制；黏菌的 csA 黏附基因使携带者优先聚合。绿须概念的价值在于说明\"亲缘识别\"本质上可以是\"基因识别\"，但现实中绝大多数合作仍依赖空间与熟悉度线索。"},{"id":"29.10","t":"合作繁殖与帮助者","s":3,"c":"29. 利他与合作","x":"合作繁殖（cooperative breeding）指非亲代个体（通常是成年的后代或亲属）帮助育幼，见于佛罗里达灌丛鸦、白翅澳鸦、獴、狼与多种热带鸟类。帮助者的收益包括：间接适合度（帮助亲属）、获得育幼经验、继承领域与地位（\"排队\"等待繁殖位）、群体防御与信息。生态限制假说认为，帮助者的出现是因为\"无空位可独立繁殖\"（生境饱和），因此帮助是\"次优策略\"而非\"最适策略\"；这一解释得到了\"补充空位后帮助者立即独立繁殖\"的实验支持。"},{"id":"30.1","t":"自组织与局部规则","s":3,"c":"30. 群体决策与集体行为","x":"集体行为（collective behavior）指大量个体依循简单局部规则相互作用而涌现出群体层面的有序模式，无需中央指挥，称自组织（self-organization）。鱼群的同步转向、椋鸟群的\"星形\"变形、蚁群的路径选择都属此类。研究方法是\"个体基础模型\"（individual-based model）：设定每个个体只感知邻近个体的方向与距离、遵循\"对齐—吸引—排斥\"三条规则，即可重现群体的整体形态，说明复杂源于简单规则的迭代。"},{"id":"30.2","t":"鱼群的同步与反捕食队形","s":3,"c":"30. 群体决策与集体行为","x":"鱼群（schooling）的形成依赖侧线机械感受与视觉，个体间距、朝向与游速高度同步，反应延迟极短（约数十毫秒）。面对捕食者时出现典型动作：闪光扩张（flash expansion，群体瞬间四散）、喷泉效应（fountain effect，从中间分开再在后方汇合）、真空泡（vacuole，绕开捕食者形成空洞）。这些队形既降低个体被捕食概率（稀释与混乱效应），也提高了捕食者的\"目标模糊性\"，是集体防御的力学机制。"},{"id":"30.3","t":"蚁群的信息素路径与双桥实验","s":3,"c":"30. 群体决策与集体行为","x":"蚂蚁外出觅食时在路径上留下踪迹信息素，返程时加强，短路径因往返更快而积累更多信息素，形成正反馈，使群体逐步收敛到最短路径。Deneubourg 的\"双桥实验\"（Goss 等）把巢与食物用两条不等长的桥连接，起初蚂蚁随机选择，数分钟后绝大多数走短桥；若人为把短桥\"堵塞\"，群体又迅速转向长桥，体现\"正反馈 + 负反馈\"的平衡。这一机制已成为蚁群优化算法的原型。"},{"id":"30.4","t":"蜂群选址的法定人数机制","s":3,"c":"30. 群体决策与集体行为","x":"分蜂时，侦察蜂分别考察候选巢址并回巢跳摆尾舞，舞蹈的强度与时长与巢址质量成正比，同时用头部振动\"叫停\"其他舞者。当某候选点的支持者达到约 15～20 只（quorum）时，赞成该点的侦察蜂开始发出\"召集信号\"，群体迅速收敛并整体迁往该点。Seeley 的研究证明蜂群决策兼具\"独立评估（避免从众偏差）\"与\"法定人数（避免僵持）\"两个特性，是集体智慧研究的范式。"},{"id":"30.5","t":"集体智慧的条件","s":3,"c":"30. 群体决策与集体行为","x":"群体决策优于个体决策需要满足：成员判断相对独立（不相互复制）、个体准确率高于随机、群体规模适度、聚合规则合理（如多数票）。若成员相互观察过多，会产生\"信息级联\"（information cascade）与\"群体极化\"，反而降低准确率；若群体过大而个体差异被稀释，也可能出现\"群体愚蠢\"。秃鹫的聚集、鱼群的选择、蜂群的选址都被用来说明\"独立 + 聚合\"这一条件的重要性。"},{"id":"30.6","t":"领导者与追随者","s":2,"c":"30. 群体决策与集体行为","x":"群体中常出现稳定的\"领导者—追随者\"结构：领导者是对资源分布更有经验或更有动机的个体，如象群中的年长雌象凭记忆带领群体找水源、领头雁在编队前方破风（并周期性轮换以分摊代价）。领导权的形成可以是\"个体属性决定\"（年龄、经验），也可以是\"状态依赖\"（饥饿者更倾向移动）。领导者的判据是\"其行为先于群体、且群体的方向由之决定\"，可用\"集体决策的先动者分析\"量化。"},{"id":"30.7","t":"群体决策的失误","s":2,"c":"30. 群体决策与集体行为","x":"集体行为也会出错：行军蚁（Eciton）在失去信息素轨迹时会形成\"死亡螺旋\"（circular mill），成群绕圈直至力竭而死；前一路径的信息素过强会使蚁群固守次优路线（\"路径锁定\"）；信息级联可导致整个群体选择危险巢址。这些失误的共同原因是\"正反馈过强而缺乏独立信息\"，与 30.5 的条件正好相反，因此\"自组织\"不等于\"总能把事做对\"。"},{"id":"30.8","t":"集体行为与仿生应用","s":1,"c":"30. 群体决策与集体行为","x":"集体行为的机制被大量移植到工程领域：蚁群优化算法用于路径规划与网络路由，粒子群优化用于参数搜索，蜂群决策模型用于分布式传感网络与机器人集群，鱼群模型用于无人机编队与水下航行器协同。反过来，工程模型也帮助行为学家检验假设，如用\"机器蜂\"验证舞蹈编码、用\"机器鱼\"验证鱼群的局部规则。这一双向互动是行为学应用价值的典型体现。第五篇 应用与备考"},{"id":"31.1","t":"行为学与再引入、野化训练","s":3,"c":"31. 动物行为学的应用","x":"再引入（reintroduction）失败的主要原因往往不是生境，而是行为缺陷：圈养个体不会识别天敌、不会选择天然食物、不会躲避人类。因此现代项目把\"行为训练\"写入流程，如用天敌模型与活体猎物训练幼兽、用\"反捕食训练\"（把捕食者与警报声配对）提高存活率；中国的麋鹿、普氏野马、朱鹮再引入都包含类似环节。行为学指标（警戒距离、觅食成功率、领域建立）已成为放归前的\"合格标准\"。"},{"id":"31.2","t":"行为学与就地保护","s":3,"c":"31. 动物行为学的应用","x":"行为研究为保护提供三类参数：最小接近距离（flight initiation distance，用于设定观鸟、观鲸、徒步路线）、关键生境要素（巢址、越冬洞穴、求偶场的位置）、以及干扰的阈值强度（噪声、光照、人流）。例如对繁殖期燕鸥的接近距离若小于其\"孵卵中断阈值\"，会导致弃巢与捕食率上升；对蝙蝠冬眠洞穴的温度与湿度扰动会使唤醒次数增加、能耗加剧。这些都是把行为数据直接转为管理规则。"},{"id":"31.3","t":"有害动物的行为学防治","s":3,"c":"31. 动物行为学的应用","x":"行为学提供了\"不用毒药\"的防治路径：性信息素诱捕与迷向（干扰交配，如梨小食心虫的迷向丝）、聚集信息素诱杀（如松墨天牛）、驱避剂与视觉威慑（反光带、鹰形风筝驱鸟）、行为干扰（超声波驱鼠、声光驱鸟）、以及\"诱集植物\"（trap crop）把害虫吸引到非作物区集中处理。这些手段的共同思路是\"利用动物的感觉与决策弱点\"，比广谱杀虫剂更专一、更少抗性。"},{"id":"31.4","t":"养殖中的行为需求与福利","s":3,"c":"31. 动物行为学的应用","x":"集约化养殖常剥夺动物的\"天性表达\"，导致刻板行为（stereotypy）：母猪的空嚼与咬栏、笼养蛋鸡的假沙浴与啄羽、犊牛的无目的舔舐。解决途径是环境丰容（enrichment，如提供稻草、栖架、泥浴、玩具），研究显示丰容可显著降低刻板行为与皮质醇水平。行为指标（活动量、争斗频次、异常行为比例）是评估福利最直接的工具，比单纯的生产性能更敏感。"},{"id":"31.5","t":"社会等级与混群管理","s":2,"c":"31. 动物行为学的应用","x":"养殖与动物园管理中，混群会引起激烈的等级争夺，造成伤害与生长抑制。行为学建议：缩小个体体形差异、提供躲避与分区、在混群前进行\"熟悉化\"（隔栏相望数日）、避免在夜间或高温时段混群。猪的混群研究显示，提前熟悉可显著降低打斗次数与皮质醇峰值，这直接来自\"等级形成需要记忆与熟悉\"的行为学原理。"},{"id":"31.6","t":"传粉者行为与农业","s":2,"c":"31. 动物行为学的应用","x":"作物产量高度依赖传粉者的行为：蜜蜂的\"花恒常性\"（flower constancy，一次只访问同种花）提高授粉效率，其舞蹈通讯决定了采集的斑块选择；熊蜂的\"振动采粉\"（buzz pollination）是番茄等作物授粉的关键。农业上通过配置诱集植物、调整花期、减少农药在蜜蜂活动高峰期的使用来保护传粉服务；温室内则需人工释放熊蜂。授粉行为的效率研究直接关系到粮食安全。"},{"id":"31.7","t":"仿生学与行为算法","s":2,"c":"31. 动物行为学的应用","x":"动物行为为工程提供算法原型：蚁群优化（路径规划、网络路由）、蜂群决策（分布式传感网络、机器人集群）、鱼群与鸟群模型（无人机编队、水下航行器协同）、蝙蝠回声定位（声呐与超声成像）、昆虫复眼（广角视觉传感器）、鸟类迁徙地磁感知（新型磁传感器）。仿生的正确用法是\"抽象机制\"而非\"复制外形\"，如蚁群算法抽象的是\"信息素正反馈 + 挥发负反馈\"。"},{"id":"31.8","t":"行为学与人类健康","s":2,"c":"31. 动物行为学的应用","x":"行为学与医学的交叉已形成\"进化医学\"：昼夜节律紊乱与倒班工作者的代谢、免疫疾病风险相关（第 15.8 节）；人类对高糖高脂食物的偏好可用超常刺激解释；恐惧与焦虑的\"预备性学习\"（对蛇、蜘蛛的快速恐惧）可用学习的预备性解释；宠物的行为问题（分离焦虑、刻板行为）则需按行为需求评估。这类题目常以\"用行为学原理分析下列现象\"的形式出现。"},{"id":"31.9","t":"行为与生物入侵","s":3,"c":"31. 动物行为学的应用","x":"入侵种的扩散常伴随\"行为综合征\"：胆大、探索性强、对 novelty 的恐惧低，这类个体更易被运输并定殖；同时入侵地的本地种因缺乏共进化历史而缺乏反捕食反应（\"天真猎物\"），导致被大量捕食。管理上的启示是：监测\"行为表型\"（如对陷阱的回避速度）可提前预警扩散风险，而\"行为训练\"本地濒危种识别新捕食者也是一条保护途径。"},{"id":"32.1","t":"近因与终极原因混淆","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"典型错法是把\"为了繁殖\"当作近因、把\"睾酮升高\"当作终极原因。正确表述：雄鸟春季鸣唱的近因是长日照→睾酮升高→HVC 激活，终极原因是鸣唱提高领域占有与配偶获得从而提高适合度。凡题目出现\"为什么\"时可两答并用，出现\"如何\"时只能答近因，\"为何被保留\"时只能答终极原因。"},{"id":"32.2","t":"FAP 与趋性的区别","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"错法是把\"朝光飞\"当作 FAP。FAP 是触发后自主完成的定型动作序列，不依赖持续反馈；趋性必须依赖持续的刺激输入不断校正方向。判据：去掉刺激后动作是否继续完成。雏鸥啄红点是 FAP（啄完即完成吞咽程序），飞蛾趋光是被动保持固定角度的定向（把光源移走即转向）。"},{"id":"32.3","t":"关键刺激、信号刺激、释放者、超常刺激的分辨","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"四者常被混用。关键刺激是\"触发行为所必需的特征\"（银鸥喙上的红点）；信号刺激是\"被简化或人工模拟的关键刺激\"（硬纸卡上的红点条带）；释放者是\"进化形成的、专门用于通讯的信号结构\"（孔雀尾屏，属个体身上的结构或动作）；超常刺激是\"超出自然范围的夸张刺激\"（三环红棒、巨型模型蛋）。判断关键是看\"它是自然特征、模型、专门信号，还是夸张版本\"。"},{"id":"32.4","t":"习惯化、感觉适应与疲劳的区分","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"三者都表现为反应减弱，但机制不同。习惯化是中枢学习（对特定刺激特异、可被强刺激解除而\"去习惯化\"），感觉适应是感受器敏感性下降（对同通道所有刺激都减弱、恢复快），疲劳是效应器能力下降（休息后恢复、与刺激特异性无关）。判据：换一个同通道的新刺激若反应恢复则为习惯化，若仍不反应则为适应或疲劳。"},{"id":"32.5","t":"经典条件反射与操作条件反射的区别","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"错法是把\"动物做动作得奖励\"一律叫经典条件反射。经典条件反射是\"刺激—刺激\"关联，动物被动，反应多为自主反应（唾液、心率、伸喙）；操作条件反射是\"行为—结果\"关联，动物主动，反应多为骨骼肌动作（压杆、啄键）。蜜蜂的 PER 是经典条件反射，鸽子啄键取食是操作条件反射，两者都靠强化但关联的方向不同。"},{"id":"32.6","t":"印随与\"关键期\"的表述误用","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"错法是把印随说成\"在关键期内学会认母\"。规范表述：印随是在敏感期（sensitive period）内对特定对象形成的快速、牢固、难以逆转的依恋，且不需要食物强化；\"关键期\"（critical period）指完全不可逆的窗口，现代研究更倾向用敏感期。另外印随与\"亲子识别\"不同：印随是子代对亲代（或替代物）的定向，亲子识别是亲代辨认子代。"},{"id":"32.7","t":"学习类型判断的常见错误","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"错法一：把\"第一次成功\"都叫顿悟（须排除偶然，需多次验证与迁移）；错法二：把\"群体中扩散\"都叫模仿（须区分局部增强、刺激增强与真正的动作复制）；错法三：把\"没有奖励也在探索\"叫无学习（可能是潜在学习）；错法四：把\"反应增强\"叫习惯化（那是敏感化）。判断时先问\"是否存在两个刺激的关联\"\"是否有动作复制\"\"是否能被强化改变\"。"},{"id":"32.8","t":"激素的激活效应与组织效应混淆","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"错法是把\"胚胎期睾酮使脑雄性化\"说成激活效应。激活效应是可逆的短期调节（成体去势后攻击性下降、补睾酮后恢复）；组织效应发生在发育窗口，永久改变结构与反应潜能（新生期注射睾酮使雌鼠成年后表现雄性行为）。判据：改变是否可逆、是否依赖发育时间窗。"},{"id":"32.9","t":"生物钟的判据与\"温度补偿\"","s":3,"c":"32. 高频考点与易错辨析（一）：概念与机制","x":"错法是把\"动物随光照改变活动时间\"当作存在生物钟。证明内源节律必须有三条证据：恒温恒暗下仍自由运转、周期接近但非精确 24 h、具温度补偿（Q10 接近 1）。若某节律在恒暗下消失，则它只是对光的被动反应。此外\"周期 24 h\"不等于\"由外界驱动\"，恰恰相反，自由运转周期通常偏离 24 h 才说明是内源钟。"},{"id":"33.1","t":"ESS 不等于最优","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是把 ESS 说成\"群体适合度最大的策略\"。ESS 是\"抗入侵\"的稳定性概念，可以不是全局最优（全体鸽在鹰鸽博弈中群体收益最高，但不是 ESS）；也可存在多个 ESS。答题时应写\"该策略在群体中被普遍采用时，任何稀有突变策略都不能获得更高适合度\"，而不是\"该策略使群体总收益最大\"。"},{"id":"33.2","t":"Hamilton 法则的计算错误","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"三类常见错误：r 取错（膜翅目姐妹是 0.75 而非 0.5；父子、母女都是0.5；半同胞 0.25）；把\"个体数\"当作\"繁殖量\"（应折算为后代数或繁殖值）；漏算行为者自身的存活代价。规范写法是先列 r、B、C 三个量，再代入rB>C，最后给出结论句\"因此该行为可被选择保留/不保留\"。"},{"id":"33.3","t":"利他与互惠的区分","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是把\"互相帮助\"都叫互惠利他。互惠利他要求受益者是非亲属、且行为者当下付出代价、未来获得回报，并需具备长期重复互动、个体识别、欺骗惩罚三条件。若受益者是亲属则为亲缘利他（用 rB>C 计算）；若行为者当下不受损（如稀释效应中的群体成员）则只是\"被动受益\"，不构成利他。"},{"id":"33.4","t":"\"为了物种的利益\"谬误","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是用\"为了种群延续\"\"为了生态平衡\"解释行为。自然选择作用于个体（及基因），不为物种谋利：老龄雄狮被驱逐、杀婴、过度捕食都可能发生。正确表述是把收益落到\"个体或基因的适合度\"上。若某行为确实使群体受益而个体受损，必须用亲缘选择、互惠或群体选择（有争议、需严格条件）来解释。"},{"id":"33.5","t":"性选择与自然选择的关系","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是把二者对立，说\"孔雀尾屏违反自然选择所以不是适应\"。性选择是自然选择的组成部分，只是度量的是繁殖成功而非存活；当性选择与\"生存选择\"方向相反时，性状停留在二者平衡点（如孔雀尾屏不至于过长而影响飞行）。答题时应写\"性选择与生存选择共同决定该性状的平衡值\"。"},{"id":"33.6","t":"广义适合度与个体适合度的混算","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是把\"帮助者抚养的雏鸟数\"直接加进自己的个体适合度。个体适合度只计自身繁殖；广义适合度 = 个体适合度 + 通过亲属获得的间接适合度（按 r折算）。计算时要写清\"该个体自身繁殖 X 个 + 帮助抚养 Y 个 × r\"，不能简单相加。"},{"id":"33.7","t":"贝氏拟态与缪氏拟态","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"判据只有一条：拟态者是否也具有防御能力。无防御者模仿有防御者为贝氏拟态（寄生性，拟态者比例高时保护下降）；双方都有防御能力、共享警戒信号为缪氏拟态（互利，分摊捕食者学习成本）。非洲燕尾蝶雌性模仿有毒凤蝶是贝氏，帝王蝶与副王蛱蝶是缪氏。错法是把\"颜色相似\"一律称贝氏拟态。"},{"id":"33.8","t":"最适模型的\"否证\"判断","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是把\"实测值低于模型预测\"当作模型被否证。正确逻辑：先检查约束是否遗漏（形态、生理、信息）、货币是否选错、研究尺度是否匹配；只有排除这些之后，\"预测方向与实测相反且重复出现\"才算否证。模型给出的是上限或方向性预测，不是精确值。"},{"id":"33.9","t":"频率依赖与\"最优策略\"","s":3,"c":"33. 高频考点与易错辨析（二）：进化与适合度","x":"错法是把\"某策略在群体中占多数\"当作该策略最优。频率依赖下，策略的收益随自身频率下降，因而占多数时往往已不最优，群体可能维持在混合均衡。判断时要问\"该策略的收益是否取决于他人策略\"，若是，则不能用单一最优解分析，必须用 ESS 与博弈矩阵。"},{"id":"34.1","t":"领域、巢域与核域","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"错法是把\"活动范围\"都叫领域。领域必须\"被防御并排斥他人\"，巢域是全部活动范围（不必然防御），核域是巢域中利用最强的部分。三者关系为\"巢域⊇ 核域 ⊇ 领域（若存在）\"。若题目只说\"某兽的活动范围为 5 km²\"而未提防御，就不能判定为领域。"},{"id":"34.2","t":"一雄多雌与一雌多雄的判定","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"判据是\"实际繁殖贡献\"而非\"群体中雌雄数量\"。一只雄性领域内有 5 只雌性，但若只有 1 只与其交配，则不构成一雄多雌；水雉中雌性保卫领域并与多雄配对、由雄孵卵，是一雌多雄的典型。答题时须指出\"性角色是否逆转\"与\"何方承担育幼\"。"},{"id":"34.3","t":"社会单配与遗传单配","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"错法是把\"成对生活\"当作单配。社会单配只描述配对与育幼关系，遗传单配需亲子鉴定证明无婚外父权。许多鸟类社会单配而遗传多配（婚外父权可达30% 以上）。答题时应写明\"依据何种证据判断\"，避免把观察到的配对关系当作遗传关系。"},{"id":"34.4","t":"警戒色、伪装与拟态的区分","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"伪装是\"不被发现\"（与背景相似）；警戒色是\"被看见并被告知我有毒\"（醒目配色 + 真实防御）；拟态是\"模仿另一对象的信号\"（贝氏/缪氏/攻击性拟态）。错法是把\"颜色鲜艳\"一律叫警戒色（孔雀尾屏是性炫耀，不是警戒色），或把\"像树叶\"叫拟态（那是伪装）。"},{"id":"34.5","t":"迁徙、扩散与游牧","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"迁徙是周期性、定向、往返的移动（候鸟、鲑的生殖洄游）；扩散是单向、一次性的迁出与定居（亚成年个体的离巢）；游牧是无固定路线的随机移动（荒漠鸟类追随降雨）。判据是\"是否周期性往返\"\"是否有固定方向与终点\"。错法是把\"幼兽离巢\"叫迁徙。"},{"id":"34.6","t":"定向与导航","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"定向是在移动中保持方向（可只用指南针机制）；导航是在偏离后仍能确定自身与目标的相对位置并修正（需要\"地图\"）。判据实验是\"位移实验\"：移位后仍能返回巢者为导航（海燕），移位后沿原方向继续者为仅具定向（知更鸟）。错法是把所有\"能找到家\"都叫导航。"},{"id":"34.7","t":"信号与线索","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"信号是\"为传递信息而被选择塑造、平均对双方有利\"的特征（孔雀尾屏、蜜蜂舞蹈）；线索只是被接收者利用的信息（猎物体温、宿主气味）。错法是把\"捕食者利用猎物气味\"叫通讯。判断标准是\"该特征是否具有为通讯而被塑造的形态与代价\"。"},{"id":"34.8","t":"稀释效应与群体防御","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"稀释效应是\"群体越大，任一个体被选中的概率越低\"的被动统计效应，无需个体主动行为；群体防御是主动行为（围攻 mobbing、集体反击、警戒呼叫）。二者常同时存在，但在题目中必须区分\"被动稀释\"与\"主动防御\"，否则会把统计效应误答为\"合作行为\"。"},{"id":"34.9","t":"真社会性的三条判据","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"真社会性必须同时满足：生殖分工（存在不育或部分不育的个体）、世代重叠（至少两代同堂）、合作育幼。错法是把\"群居\"或\"有等级\"当作真社会性（狼群、狒狒群不是真社会性）。蜜蜂、蚂蚁、白蚁、裸鼹鼠是真社会性的代表，其中白蚁与裸鼹鼠是二倍体，说明单倍二倍体不是必要条件。"},{"id":"34.10","t":"求偶场（lek）与资源保卫型一雄多雌","s":3,"c":"34. 高频考点与易错辨析（三）：行为类型与比较","x":"求偶场中雄性不提供资源与育幼，只提供基因，雌性自由选择，雄性聚集在传统展示点；资源保卫型中雄性控制雌性所需的食物或巢址，雌性因资源而聚集。判据是\"雄性是否提供资源\"与\"雌性的聚集是否由资源引起\"。尖尾松鸡是lek，红翅黑鹂是资源保卫型。"},{"id":"35.1","t":"各类通讯方式对比","s":3,"c":"35. 速查表","x":"不同通道在传播距离、穿透性、速度、可伪造性上各有优劣，选择取决于生境与生活方式。答题时可先判断\"环境是开阔还是密闭、昼行还是夜行、水下还是陆地\"，再推出主流通道。优势局限视觉通讯方式快速、方向性强、信息量大需光照、易被遮挡与窃听孔雀尾屏、招潮蟹挥螯、萤火虫闪光典型实例听觉远距离、穿透植被、夜间可用暴露位置、能耗高鸟鸣、蛙合唱、鲸歌、蝉鸣化学持久、可远距、难以伪造传递慢、难以即时停止蚕蛾醇、蚂蚁踪迹信息素、犬尿标记触觉近距离精确、黑暗可用必须接触、范围极小蚂蚁触角相碰、灵长类理毛电浑浊水中可用、私密性高距离仅数米、易被干扰电鳗、象鼻鱼放电"},{"id":"35.2","t":"婚配制度对比","s":3,"c":"35. 速查表","x":"四种婚配制度的判别要点在\"配偶数、育幼分工、性二型方向、生态条件\"，考试中常给出一段描述要求判断类型并说明理由。制度配偶关系育幼性二型实例单配一雄一雌常双亲弱多数海鸟、长臂猿一雄多雌一雄多雌多由雌性雄性更大更艳马鹿、海象、园丁鸟一雌多雄一雌多雄多由雄性雌性更大更好斗水雉、瓣蹼鹬混交无稳定配对多无强弱不一黑猩猩、多数昆虫"},{"id":"35.3","t":"学习类型对比","s":3,"c":"35. 速查表","x":"判断学习类型的三个抓手：是否存在两个刺激的关联、是否存在行为与结果的关联、是否需要观察他人。类型关键机制是否需要强化实例习惯化重复刺激致反应减弱否海兔缩鳃、鸟群对稻草人敏感化强刺激致反应增强否乌贼受电击后强反应经典条件反射CS 预测 US是（US）巴甫洛夫狗、蜜蜂 PER操作条件反射行为→结果是（奖惩）鸽子啄键、大鼠压杆潜在学习无强化形成表征否Tolman 大鼠认知地图顿悟重组问题表征否黑猩猩苏丹叠箱模仿观察后复制动作否猕猴洗红薯、山雀开奶瓶"},{"id":"35.4","t":"防御方式对比","s":3,"c":"35. 速查表","x":"按\"作用时机\"排列最清晰：被发现前（伪装、警戒色、拟态）、被发现后（逃逸、假死、威吓、自割）、群体层面（稀释、围攻、集体警戒）。方式作用机制代价实例伪装降低被发现概率需与背景匹配、限制活动竹节虫、桦尺蛾、比目鱼警戒色使捕食者一次学习后回避醒目易被初学者攻击箭毒蛙、蜂类、臭鼬贝氏拟态借模型之名获保护模型稀少时失效非洲燕尾蝶雌性、食蚜蝇缪氏拟态与有毒者共享信号需自身确有防御帝王蝶与副王蛱蝶假死降低攻击动机失去逃跑机会负鼠、部分甲虫群体围攻驱离捕食者受伤与耗能鸦群围攻猫头鹰、蜂群攻击"},{"id":"35.5","t":"定向与导航机制对比","s":3,"c":"35. 速查表","x":"按\"利用何种信息\"分类，并注意各自的证据实验，是记忆与推断兼顾的考点。机制利用的信息关键证据代表动物太阳罗盘太阳方位 + 生物钟时钟位移后定向角偏转椋鸟、蜜蜂星象罗盘星空旋转中心天文馆旋转星空实验靛蓝彩鹀地磁磁倾角与磁强度蓝光依赖、射频干扰知更鸟、海龟、信鸽嗅觉家乡水体或海洋气味人工气味印记实验鲑科鱼类、管鼻海鸟地标显著地形与地物地标移动实验蜜蜂、黄蜂"},{"id":"35.6","t":"Tinbergen 四问速查","s":3,"c":"35. 速查表","x":"任何行为题只要涉及\"解释\"，都应先把它放进四问的格子里，再决定答哪一类证据。四问一句话常用证据以蜜蜂舞蹈为例机制如何被发动神经、激素、感觉实验重力感知与振动感知的编码个体发育一生中如何形成隔离、交叉抚育幼蜂跟随舞蹈学习角度解读系统发育演化中如何变化近缘种比较无蛰刺蜂的舞蹈更简单适应功能为何被保留操纵与适合度测量提高采集效率与回报率"},{"id":"36.1","t":"三轮复习的时间分配","s":3,"c":"36. 复习路线与应试策略","x":"第一轮以本总纲的★★★条目为主线，逐章复述\"定义 + 实例 + 机制/功能\"，目标是能合上书讲出每一章 8 个知识点；第二轮做专题横向串联，把\"近因—终极\"\"代价—收益\"\"频率依赖\"三条主线贯穿全书，并整理自己的对比表；第三轮以真题与模拟题为主，限时训练并回归错题。三轮的时间比约为 5:3:2，切忌第一轮就陷入细节。"},{"id":"36.2","t":"概念题的答题模板","s":3,"c":"36. 复习路线与应试策略","x":"概念题按\"定义 + 判据 + 实例 + 易混对比\"四段写：先给中英文术语与一句定义，再给可操作的判据（如\"是否被防御\"），然后举一个具体物种的实例，最后用一句话点出与最易混淆概念的差别。四段齐全的答案几乎不会失分；只写定义通常只得一半分。"},{"id":"36.3","t":"实验分析题的四步法","s":3,"c":"36. 复习路线与应试策略","x":"第一步，找出自变量、因变量与对照（是否有假处理、是否有重复）；第二步，写出作者要检验的假说与\"若…则…\"的预测；第三步，判断结果支持哪一个假说、能否排除替代假说；第四步，指出该实验的外推限度（物种、实验室与野外差异）。竞赛的实验题多改编自经典研究（银鸥红点、破蛋壳、蜜蜂舞蹈、白冠带鹀学唱），熟悉原始设计是根本。"},{"id":"36.4","t":"计算题的常见类型","s":3,"c":"36. 复习路线与应试策略","x":"四类计算必须熟练：Hamilton 法则（rB>C，注意膜翅目 r=0.75）、ESS混合均衡（鹰频率 = V/C）、广义适合度（自身繁殖 + 亲属繁殖 × r）、边际值定理的\"离开阈值\"（斑块瞬时收益率 = 环境平均收益率）。答题时先写公式，再代数，最后写结论句；只给数字不给结论句会丢分。"},{"id":"36.5","t":"论述题的框架","s":3,"c":"36. 复习路线与应试策略","x":"论述题建议按\"现象—四问—代价收益—比较—结论\"五段展开：先用一句话界定现象；再从机制、发育、系统发育、功能四个角度各给一句；然后用代价与收益说明平衡点；接着做一次近缘种或性角色比较；最后给出\"因此该行为在特定生态条件下是适应的\"这一结论。这个框架能覆盖绝大多数 8～12 分的论述题。"},{"id":"36.6","t":"常见低分原因","s":3,"c":"36. 复习路线与应试策略","x":"五类高频失分：只写定义不举例；用\"为了物种利益\"解释行为；把近因当终极原因；实验题不写对照与预测；对比题只列差异不写判据。此外书写不规范也会丢分，如把\"固定动作模式\"写成\"固定行为\"、把\"缪氏拟态\"写成\"缪勒拟态\"、把\"广义适合度\"写成\"总适合度\"。术语务必用规范译名并附英文。"},{"id":"36.7","t":"拓展阅读与真题使用","s":2,"c":"36. 复习路线与应试策略","x":"在掌握本总纲后，可选读尚玉昌《动物行为学》的觅食、通讯、生殖三章原文，Rubenstein & Alcock 第 1、2、5、8 章的整合案例，以及 Ridley 关于机制与发育的章节；国内竞赛讲义（如苏宏鑫《高中生物奥赛讲义》行为学部分、各省冬令营讲义）可作为题型参考。真题使用原则是\"先分类、再限时、后归因\"：把历年行为学题按知识点归类，找出重复率最高的 20 个知识点，再针对错题写出错因。附录：知识库教材索引本总纲的体系与案例主要取自以下教材，均可在五个生物竞赛知识库中检索到原文。表中\"对应篇目\"指该教材内容在本总纲中的主要落点，便于回查与扩展阅读。教材版本/作者主要贡献对应篇目动物行为学尚玉昌，北京大学出版社（第 2 版）国内第一部系统教材；行为谱、研究方法、觅食、时空行为、社会生活与通讯、学习的分类体系全书骨架，尤以第一篇、第三篇、第四篇为主Animal Behavior Rubenstein &Alcock，第 11 版（牛津大学出版社）以近因/终极两层次整合全书；挖洞蜂、鸟鸣等整合案例第二篇（四问）、第三篇（机制与发育）Animal Behavior: An Introduction to Behavioral Mechanisms,Development and Ecology普通生物学Mark Ridley机制、发育与生态三分的框架第三篇、第四篇（觅食与防御）陈阅增（第 3/4/5 版）本能行为、学习行为、印随、社群生活与通讯的基础表述第一篇（基本概念）、第三篇（学习）、第四篇（社会与通讯）行为生态学尚玉昌最适觅食、领域、婚配制度、社会行为的经济学分析第二篇（最适模型与ESS）、第四篇高中生物奥赛讲义（中册）苏宏鑫，第 7 版竞赛题型与考点密度参考第五篇（易错辨析与速查）生态学与动物行为学（冬令营讲义）浙江赛区生物学联赛讲义先天与后天行为、社群通讯的竞赛化表述第三篇、第五篇使用建议：复习到某一章时，先用本总纲建立框架，再回到上表对应的教材章节核对细节与原始实验数据；对教材中出现的英文术语，优先记忆拉丁学名与英文术语，因为竞赛题干常直接使用英文原词（如 fixed action pattern、sign stimulus、kin selection、reciprocal altruism、handicap principle、evolutionarily stable strategy）。"}]
window.KG_BOOK["11"]=[{"id":"1.1","t":"生态学的经典定义","s":3,"c":"1. 生态学的定义与层次","x":"生态学（ecology）一词由希腊文 oikos（住所、家）与 logos（学问）合成，1866 年由德国博物学家 Haeckel 首次提出，其定义为\"研究生物与其环境之间相互关系的科学\"。此定义包含两层含义：一是以生物为主体、以环境为客体的相互作用，二是这种作用既包括环境对生物的塑造（选择与限制），也包括生物对环境的改造（反馈与调节）。现代教材进一步表述为\"研究生物圈中生物与生物、生物与环境相互作用规律及其机制的科学\"。"},{"id":"1.2","t":"生态学的六个组织层次","s":3,"c":"1. 生态学的定义与层次","x":"生态学按生物组织层次划分为个体、种群、群落、生态系统、景观、生物圈六级，这是本学科区别于其他生物学分支的根本架构。个体层次研究生物对环境的适应；种群层次研究数量变动与调节；群落层次研究物种组成、结构与演替；生态系统层次研究能量流动与物质循环；景观层次研究缀块—廊道—基质的格局与过程；生物圈层次研究全球尺度的生物地球化学循环。层次之间不可还原，高层次的规律（如种群调节）不能由低层次的规律（如个体生理）直接推出。核心问题代表模型或方法个体组织层次单个生物及其适应研究对象生态因子如何限制与塑造适应耐受曲线、有效积温法则种群同种个体的集合数量为何波动、如何调节dN/dt=rN、逻辑斯蒂模型、生命表群落多个种群的集合物种组成、结构、演替与多样性Shannon 指数、演替模型、排序生态系统生物群落加非生物环境能量流动与物质循环Lindeman 效率、生物地球化学循环景观异质缀块镶嵌体空间格局如何影响生态过程缀块—廊道—基质、尺度推绎生物圈地球上全部生物与环境全球变化的生态后果碳循环模型、气候情景模拟"},{"id":"1.3","t":"生态学与相关学科的关系","s":2,"c":"1. 生态学的定义与层次","x":"生态学上承生理学、遗传学、行为学，下接地理学、地质学、气象学、土壤学，横向与经济学、社会学交叉，因此它具有明显的综合性与交叉性。生态学与生理学的关系可由\"生态生理学\"体现（如植物的耐旱生理），与遗传学的关系由\"群体遗传学与分子生态学\"体现（如基因流与遗传漂变），与环境科学的关系表现为生态学是环境科学的理论基础。生态学的这一特点决定了它既有野外描述性，又有实验与模型推演性。"},{"id":"1.4","t":"生态学的分支学科","s":3,"c":"1. 生态学的定义与层次","x":"按生物组织层次分为个体生态学、种群生态学、群落生态学、生态系统生态学、景观生态学、全球生态学；按生物类群分为植物生态学、动物生态学、微生物生态学；按生境分为森林生态学、草地生态学、湿地生态学、海洋生态学、土壤生态学；按交叉学科分为生态生理学、生态遗传学、化学生态学、数学生态学、分子生态学、进化生态学；按应用目的分为农业生态学、恢复生态学、污染生态学、保护生物学、城市生态学、资源生态学。分支的划分只是视角的划分，同一对象常被多个分支同时研究。"},{"id":"1.5","t":"生态学的研究对象：生物种","s":2,"c":"1. 生态学的定义与层次","x":"生态学研究的基本单位是生物种（species），生物学种的概念强调\"能在自然条件下相互交配并产生可育后代的个体群\"，而生态学更关注种作为生态位的承担者和进化的基本单元。李博《生态学》第二章第一节把\"生物种的概念\"单列讨论，正是强调种在个体生态学中的起点地位：同一物种的不同种群因所处环境不同，可分化出不同的生态型与地理宗，这正是\"种内变异具有生态意义\"的体现。"},{"id":"1.6","t":"生态学的核心问题","s":3,"c":"1. 生态学的定义与层次","x":"现代生态学围绕四个核心问题展开：一是分布问题，即何种生物分布在何处、为何如此分布；二是数量问题，即种群密度为何稳定或波动；三是多样性问题，即群落中为何有如此多的物种；四是功能问题，即生态系统的物质循环与能量流动如何维持。这四问分别对应个体与种群、种群、群落、生态系统四个层次，竞赛中的综合题常以此为设问框架。"},{"id":"1.7","t":"生态学与进化生物学的接口","s":2,"c":"1. 生态学的定义与层次","x":"生态学解释\"此时此地的格局\"，进化生物学解释\"历时的成因\"，二者由自然选择连接：生态因子构成选择压力，适应的结果又改变生态位。这一接口的重要产物是协同进化、生活史对策和表型可塑性的研究。竞赛中常见的\"为什么某性状在该环境中更有利\"一类题目，本质上要求同时给出 proximate（近因，即生理机制）与 ultimate（远因，即进化适应）两种解释。"},{"id":"2.1","t":"萌芽时期（17 世纪以前）","s":2,"c":"2. 生态学发展史","x":"生态学的知识积累始于生产实践：古希腊 Theophrastus 关于植物与生境关系的记述、Aristotle 关于动物习性的大量观察，中国先秦典籍《诗经》《管子·地员篇》关于土壤与植物关系的记载、《齐民要术》关于轮作与物候的经验总结，均属生态学思想的萌芽。这一时期的特点是经验性强、缺少定量与理论概括。"},{"id":"2.2","t":"建立时期（17 世纪至 19 世纪末）","s":3,"c":"2. 生态学发展史","x":"此期的标志是生态学从博物学中分化出来并获得定量描述：1807 年Humboldt《植物地理学随笔》论述气候与植被分布的关系；1859 年 Darwin《物种起源》以生存斗争与环境选择奠定进化生态学基础；1866 年 Haeckel提出\"生态学\"一词；1895 年 Warming《以植物生态地理学为基础的植物分布学》与 1898 年 Schimper《以生理学为基础的植物地理学》标志植物生态学成为独立学科。1899 年 Cowles 关于密歇根湖沙丘植被的研究提出演替系列概念。"},{"id":"2.3","t":"发展时期（20 世纪初至 20 世纪 50 年代）","s":3,"c":"2. 生态学发展史","x":"此期形成若干学派并建立核心理论：Clements（1916）提出群落演替的单元顶极学说与\"群落是一个有机体\"的观点；Tansley（1935）提出生态系统（ecosystem）概念；Lindeman（1942）以湖泊研究提出营养级间能量传递的\"十分之一定律\"；Thienemann、Elton 分别从食物链与生态位角度推动动物生态学。种群生态学方面，Pearl（1920）提出逻辑斯蒂方程，Lotka（1925）与 Volterra（1926）建立种间竞争的数学模型，Gause（1934）以草履虫实验验证竞争排斥原理。"},{"id":"2.4","t":"现代生态学时期（20 世纪 50 年代以后）","s":3,"c":"2. 生态学发展史","x":"1953 年 Odum《生态学基础》以系统论组织全书，标志生态系统生态学的成熟；1964—1974 年国际生物学计划（IBP）推动全球尺度生产力测定；1967 年 MacArthur 与 Wilson 提出岛屿生物地理学理论；1971 年 Odum 提出\"生态工程\"概念；1972 年联合国人类环境会议、1987 年《我们共同的未来》提出可持续发展，1992 年《生物多样性公约》签署。此期的特征是定量化、模型化、全球化，并与资源环境问题紧密结合。"},{"id":"2.5","t":"中国生态学的发展","s":2,"c":"2. 生态学发展史","x":"我国生态学由李继侗、仲崇信、曲仲湘等在 20 世纪 30 年代开创植物群落研究，侯学煜建立中国植被分区与指示植物研究体系，马世骏提出\"生态工程\"与\"社会—经济—自然复合生态系统\"理论，孙儒泳系统开展种群能量生态学研究。1988 年中国生态系统研究网络（CERN）建立，2004 年起国家野外科学观测研究站体系整合运行，长期定位研究由此获得制度保障。"},{"id":"2.6","t":"生态学范式的演进","s":2,"c":"2. 生态学发展史","x":"生态学经历了三次范式转移：从博物学的描述范式，到 20 世纪中期的系统论与能量学范式，再到 20 世纪后期的进化与尺度范式。当代生态学强调格局—过程—尺度的统一、多因子交互作用、以及全球变化背景下的预测能力，因此模型模拟与长期观测成为不可替代的方法。"},{"id":"3.1","t":"观察法与描述研究","s":3,"c":"3. 研究方法","x":"观察法是生态学最基础的方法，包括野外踏查、定位观测、样方调查与遥感观测，其产物是格局与相关关系。观察法的优点是不干扰系统、可获得真实状态，局限是无法直接确定因果关系，因此观察得到的相关必须由实验或机制模型进一步检验。群落调查（样方法、样线法）与物候观测是最典型的观察研究。"},{"id":"3.2","t":"控制实验与野外实验","s":3,"c":"3. 研究方法","x":"控制实验通过人为操纵一个或少数因子并保持其他因子一致，从而分离出该因子的独立效应；野外实验在自然生境中进行操纵，兼具真实性与因果性，但受尺度与重复数限制。经典范例包括 Gause 的草履虫竞争实验、Paine 去除海星 Pisaster 的潮间带实验、Connell 的藤壶移植实验、以及 Bormann 与Likens 的 Hubbard Brook 森林采伐实验（采伐后硝酸盐输出增加约 60倍）。"},{"id":"3.3","t":"自然实验与比较研究","s":2,"c":"3. 研究方法","x":"当无法操纵因子时，可利用自然形成的处理（如岛屿面积、火山熔岩年龄、纬度梯度、城市热岛）做\"自然实验\"，通过配对比较推断因子效应。比较研究的关键是控制混杂变量与选择恰当的空间替代时间（chronosequence，空间序列代替时间序列）方法，例如以不同年龄的沙丘或冰川退缩地为序列研究原生演替。"},{"id":"3.4","t":"数学模型与模拟","s":3,"c":"3. 研究方法","x":"生态模型分为文字模型、图解模型、矩阵模型和微分方程模型。微分方程模型（如 dN/dt=rN）用于刻画连续过程，矩阵模型（如 Leslie 矩阵）用于年龄结构种群，基于个体的模型（IBM）与系统模拟用于多因子复杂系统。模型的价值在于推演假设的后果、生成可检验的预言，而非代替真实系统；Beverton-Holt 与 Ricker 模型是渔业种群离散增长的经典形式。"},{"id":"3.5","t":"长期定位研究","s":3,"c":"3. 研究方法","x":"长期定位研究（long-term ecological research）用于揭示慢过程与稀有事件的作用，观测周期常达十年以上。国外以美国 LTER（1980 年启动）为代表，国内以 CERN（1988 年）为代表，覆盖农田、森林、草地、荒漠、水体等类型。其不可替代性体现在：土壤碳周转、演替进程、种群周期、气候变化响应等过程在短期研究中无法观测，且长期数据可区分趋势与波动。"},{"id":"3.6","t":"现代技术手段","s":2,"c":"3. 研究方法","x":"遥感与地理信息系统用于获取景观尺度的格局信息并计算景观指数；稳定同位素技术（δ¹³C、δ¹⁵N、δ¹⁸O）用于追踪食物来源、营养级位置与水分来源；分子标记（微卫星、SNP）与 DNA 条形码用于分析遗传多样性、基因流与物种鉴定；涡度相关法用于测定生态系统尺度的碳通量；无人机与红外相机用于大范围物种监测。技术手段的进步直接扩展了可研究的尺度范围。"},{"id":"3.7","t":"实验设计的基本要求","s":3,"c":"3. 研究方法","x":"严格的生态学实验必须满足四项要求：设置对照（含空白对照与处理对照）、随机化分配、足够重复（一般不少于 3~5 个）、以及控制混杂变量。统计上需报告效应量与置信区间而不只是 P 值，并注意伪重复（pseudoreplication）陷阱，即把同一处理内的多个取样点当作独立重复。竞赛中出现的\"该实验设计有何缺陷\"类题目，答题要点通常从对照缺失、重复不足、未随机化、单一尺度四个方面切入。"},{"id":"4.1","t":"尺度的概念与类型","s":3,"c":"4. 尺度与格局","x":"尺度指研究所涉及的空间范围与时间跨度，以及分辨率（粒度）。生态学尺度分为空间尺度（从叶片厘米级到生物圈万公里级）、时间尺度（从秒级的生理反应到百万年的演化）与组织尺度（个体到生物圈）。观测粒度与观测范围共同决定可检出的格局，同一现象在小尺度上表现为随机、在大尺度上表现为聚集（或相反），此即尺度依赖性。"},{"id":"4.2","t":"格局与过程","s":3,"c":"4. 尺度与格局","x":"格局指生态学变量在空间或时间上的非随机分布，过程指产生该格局的机制（扩散、竞争、捕食、扰动、环境梯度）。生态学研究的核心命题是\"格局—过程关系\"：由格局推断过程称为反演，由过程预测格局称为正演。同一格局可由多种过程产生（如聚集分布既可由繁殖方式造成，也可由生境异质性造成），因此仅凭格局无法唯一确定过程。"},{"id":"4.3","t":"空间异质性与缀块性","s":2,"c":"4. 尺度与格局","x":"空间异质性指系统属性在空间上的非均匀性，可分解为缀块的数量、大小、形状、边界与连结度等要素。异质性提高生境多样性，从而常提高物种多样性；但同时使个体迁移受阻。缀块（patch）、廊道（corridor）与基质（matrix）构成景观的基本模式，即缀块—廊道—基质模式，是景观生态学的核心概念框架。"},{"id":"4.4","t":"等级理论与尺度推绎","s":2,"c":"4. 尺度与格局","x":"等级理论（hierarchy theory）认为生态系统由若干等级层次组成，每一层次由低层次组成、受高层次约束，且不同层次具有不同的特征时间与空间尺度。尺度推绎（scaling）指把某一尺度上的结论外推到另一尺度，包括尺度上推（聚合）与尺度下推（分解），其困难在于非线性关系与阈值的存在使得简单外推常常失效。竞赛中\"小样方结果能否代表整个群落\"一类问题，实质是尺度推绎的可靠性问题。"},{"id":"4.5","t":"取样尺度与最小表现面积","s":3,"c":"4. 尺度与格局","x":"群落调查的样方面积直接影响结论：面积过小会遗漏稀有种并低估多样性，面积过大则浪费工作量。确定方法是用\"种—面积曲线\"，即逐步扩大样方面积并记录新出现的物种数，曲线趋于平缓时的面积即最小表现面积。经验值：温带森林乔木层约 400~1 000 m²、灌木层约 25~100 m²、草本层约 1~4 m²；热带雨林需 2 500 m² 以上。样方形状以正方形或长方形（长宽比不超过2:1）为宜，以减少边缘效应；样线法适用于生境梯度明显的过渡带。"},{"id":"4.6","t":"景观尺度的格局指标","s":2,"c":"4. 尺度与格局","x":"景观格局用景观指数定量，常用指标包括：缀块数（NP）、缀块平均面积（MPS）、缀块密度（PD）、边缘密度（ED）、形状指数（LSI）、蔓延度（CONTAG）、香农多样性指数（SHDI）与香农均匀度（SHEI）、以及连通性指数。这些指数分别刻画\"破碎化程度\"（NP、MPS、PD）、\"边缘效应强度\"（ED）、\"聚集或分散\"（CONTAG）与\"组成多样性\"（SHDI）。使用景观指数的注意事项是：多数指数对尺度（粒度与范围）敏感，且指数之间高度相关，因此一篇研究中不宜堆砌指数，而应选择与研究问题对应的少数指标。"},{"id":"4.7","t":"边界与生态交错区","s":2,"c":"4. 尺度与格局","x":"生态系统之间的界线往往不是突变而是过渡带，称为生态交错区（ecotone）。边界的确定具有尺度依赖性：在细尺度上边界清晰，在粗尺度上模糊。交错区常具有高于相邻群落的物种丰富度与密度，即边缘效应，但边缘效应并非普遍存在，对于内部种（interior species）而言边缘反而是质量低劣的生境。第二篇 个体生态与环境"},{"id":"5.1","t":"环境与环境的类型","s":3,"c":"5. 生态因子及其分类","x":"环境（environment）指某一主体周围一切要素的总和，生态学中的环境以生物为主体，指影响生物生存、生长、繁殖与分布的全部外界条件的总和。环境可分为自然环境（无机环境与生物环境）与人工环境；按范围可分为宇宙环境、地球环境（大气圈、水圈、岩石圈、土壤圈、生物圈）与区域环境；按主体可分为种群环境与个体环境。"},{"id":"5.2","t":"生态因子的概念与分类","s":3,"c":"5. 生态因子及其分类","x":"生态因子（ecological factor）指环境中对生物有直接或间接影响的环境要素，其中生物生存所不可缺少的称生存因子或限制因子。按性质分为气候因子（光、温、水、风、火）、土壤因子（质地、pH、养分、盐分）、地形因子（海拔、坡度、坡向、经纬度）、生物因子（捕食、竞争、寄生、共生、他感）与人为因子。按作用方式分为直接因子与间接因子，按与密度的关系分为密度制约因子与非密度制约因子。分类依据类别举例备注性质气候因子光、温度、降水、风、火影响最广、变化最大性质土壤因子质地、pH、有机质、盐分兼有物理与化学性质性质地形因子海拔、坡向、坡度多为间接因子性质生物因子竞争、捕食、寄生、共生随密度变化性质人为因子采伐、污染、引种、放牧强度大、速度快作用方式直接因子光照强度、土壤水分直接作用于生理过程作用方式间接因子海拔、坡向、经纬度通过改变气候而起作用与密度关系密度制约因子食物、天敌、传染病种群调节的主要因子与密度关系非密度制约因子寒潮、台风、火烧造成突发性死亡"},{"id":"5.3","t":"生态因子作用的一般特征","s":3,"c":"5. 生态因子及其分类","x":"生态因子作用具有五个一般特征：（1）综合性，多个因子同时作用且相互影响，某一因子的作用效果随其他因子而改变；（2）主导因子性，在诸因子中必有一个或少数几个起决定作用，如干旱区的水分、寒带的温度；（3）直接性与间接性，地形、纬度多为间接因子；（4）阶段性，生物不同发育阶段对同一因子的需求与耐受不同，繁殖期通常最敏感；（5）不可替代性与部分可调节性，光温水等生存因子不可互相替代，但在一定范围内可部分补偿，如增加CO₂ 可提高水分利用效率。"},{"id":"5.4","t":"主导因子与限制因子","s":3,"c":"5. 生态因子及其分类","x":"主导因子指在特定条件下对生物起决定性作用的因子，其改变会引起其他因子或整个生境的显著变化；限制因子指接近或超过生物耐受极限、从而限制生物生存与分布的因子。二者关系是：主导因子常是限制因子，但并非所有限制因子都是主导因子。区分二者的实践意义在于，生态管理应优先调控限制因子（如淡水藻华先控磷）。"},{"id":"5.5","t":"生物对环境的反作用","s":2,"c":"5. 生态因子及其分类","x":"生物不是被动接受环境，而是主动改造环境：植物根系改善土壤结构与有机质含量，森林蒸腾增加区域降水，蚯蚓与白蚁改变土壤孔隙度，珊瑚与藻类建造礁体，人类活动则在大尺度上改变大气组成与土地利用。这种反作用使环境与生物构成反馈回路，是生态系统自我调节能力的基础。"},{"id":"5.6","t":"生态因子的交互作用","s":2,"c":"5. 生态因子及其分类","x":"两因子的联合效应可大于、等于或小于各自效应之和，分别表现为协同、相加与拮抗。典型例子：高温与干旱同时出现时植物死亡率远高于各自单独作用（协同）；钙可减轻重金属毒害（拮抗）；氮磷同时充足才使藻类爆发（相加至协同）。交互作用是竞赛实验中\"两因素交叉设计\"题目的理论依据，判断时必须看是否存在显著的交互项。"},{"id":"6.1","t":"Liebig 最小因子定律","s":3,"c":"6. 限制因子与耐受定律","x":"1840 年 Liebig 在研究作物产量时提出：植物的生长取决于处于最小量状态的营养物质，即\"最小因子定律\"。该定律有两个前提：系统处于稳态（物质输入输出平衡），且各因子之间无替代作用。定律的现代形式是限制因子原理：任何接近或超过生物耐受极限的因子都可成为限制因子，而不限于营养元素。农业施肥的配方诊断、水体富营养化的控磷或控氮策略均以此为依据。"},{"id":"6.2","t":"Shelford 耐受定律","s":3,"c":"6. 限制因子与耐受定律","x":"1911 年 Shelford 提出耐受定律：每一种生物对每一个生态因子都有一个耐受范围，即上限与下限，二者之间为耐受区间，其中部为最适区；当因子超出耐受范围时，生物即不能生存。耐受区间的宽窄决定该生物的分布广度：耐受范围宽的称广适性生物（如广温性、广盐性），窄的称狭适性生物（如狭温性、狭盐性）。该定律把 Liebig 的\"最小量\"扩展为\"上下限\"的双侧限制。"},{"id":"6.3","t":"生态幅及其测定","s":3,"c":"6. 限制因子与耐受定律","x":"生态幅（ecological amplitude）指一种生物对某个生态因子耐受范围的大小，耐受范围越宽生态幅越大。生态幅可通过实验测定：设置因子梯度（如温度 5、10、15、20、25、30、35 ℃），测定各梯度下的存活率、生长速率或光合速率，绘制反应曲线，曲线与零值线的交点即耐受上下限，峰值位置即最适点。反应曲线通常不对称，向不利一侧下降更陡。"},{"id":"6.4","t":"生理分布与实际分布","s":3,"c":"6. 限制因子与耐受定律","x":"由生理耐受限度决定的分布范围称生理分布（基础分布），而自然界的实际分布往往小于生理分布，原因包括竞争排斥、捕食压力、扩散限制与生境不连续。经典例子是潮间带藤壶 Chthamalus 的分布：其生理耐受可覆盖整个潮间带，但因受 Balanus 竞争而在实际中只限于高潮区。该概念是\"为什么生物不生活在它能生活的地方\"这一竞赛常考题的标准答案。"},{"id":"6.5","t":"耐受定律的补充与限制","s":2,"c":"6. 限制因子与耐受定律","x":"耐受定律需补充四点：（1）生物在实际中最适区未必数量最多，因为在最适区往往竞争最激烈；（2）生物在繁殖期的耐受范围通常窄于非繁殖期，因此繁殖期分布受限更严；（3）经过长期驯化，生物可改变其耐受范围（驯化与适应不同，前者不涉及遗传改变）；（4）因子之间存在交互作用，一个因子的耐受限度可因其他因子适宜而拓宽。因此耐受定律只给出可能性边界，不直接决定实际分布。"},{"id":"6.6","t":"耐受定律的应用","s":2,"c":"6. 限制因子与耐受定律","x":"耐受定律可用于解释与预测：（1）引种驯化，需比较原产地与引入地的因子是否落在耐受范围内；（2）指示生物选择，狭适性生物对污染或环境变化敏感，适合作指示种，如地衣对 SO₂ 敏感、蜉蝣目幼虫对溶解氧要求高；（3）物种保护，了解耐受限度可预测气候变化下分布区迁移方向；（4）污染治理，了解生物的耐受阈值可确定排放标准。"},{"id":"6.7","t":"生态幅与入侵潜力的关系","s":2,"c":"6. 限制因子与耐受定律","x":"广适性物种通常具有更强的入侵潜力，因为其能耐受更宽的环境梯度并利用更多类资源；但生态幅宽并不等于入侵性强，后者还取决于繁殖能力、扩散能力与天敌释放等因素。例如互花米草具有广盐性与耐淹性，在我国滨海湿地迅速扩张；而一些狭适性特有种即便引入新区域也难以定殖。"},{"id":"7.1","t":"光质的生态作用","s":3,"c":"7. 光因子与生物的适应","x":"太阳辐射中可见光（380~760 nm）是光合有效辐射（PAR），其中红光（600~700 nm）与蓝紫光（400~500 nm）被叶绿素吸收最多，绿光吸收最少。光质影响植物的形态建成：红光促进茎的伸长与种子萌发，蓝光抑制伸长并促进气孔开放与向光性，紫外光（UV-B，280~320 nm）可损伤 DNA 并诱导类黄酮等保护物质合成。水体中光质随深度发生选择性衰减，长波先被吸收，因此深水藻类多含藻红素等适应绿光的色素。"},{"id":"7.2","t":"光照强度与光补偿点、光饱和点","s":3,"c":"7. 光因子与生物的适应","x":"光照强度影响光合速率，二者关系呈饱和曲线。光补偿点指光合速率等于呼吸速率时的光强，此时净光合为零；光饱和点指光合速率不再随光强增加而升高时的光强。阳生植物的光补偿点较高（约 10~20 μmol·m⁻²·s⁻¹ 以上）、光饱和点也高（可达 1 500~2 000 μmol·m⁻²·s⁻¹）；阴生植物两者均低（光补偿点可低于 5 μmol·m⁻²·s⁻¹，光饱和点约 200~500 μmol·m⁻²·s⁻¹）。阴生植物在弱光下量子效率更高，但在强光下易发生光抑制。阳生植物阴生植物光补偿点项目较高（约 10~20 μmol·m⁻²·s⁻¹）很低（可低于 5 μmol·m⁻²·s⁻¹）光饱和点高（1 500~2 000μmol·m⁻²·s⁻¹）低（约 200~500 μmol·m⁻²·s⁻¹）叶片特征厚、角质层发达、栅栏组织多层薄、叶面积大、栅栏组织不发达叶绿素含量较低，a/b 比值较大较高，a/b 比值较小呼吸速率高低强光下表现正常生长光抑制、叶绿素降解"},{"id":"7.3","t":"阳生植物与阴生植物的适应","s":3,"c":"7. 光因子与生物的适应","x":"阳生植物叶片厚、角质层与蜡质发达、气孔小而密、栅栏组织多层、叶绿体较小且基粒少，具有较高的光饱和点与蒸腾能力，能在全光照下正常生长而在荫蔽处生长不良。阴生植物叶片薄而大、栅栏组织不发达、叶绿体大且基粒多、叶绿素 b 比例高，能高效利用散射光，但在强光下易光抑制。群落中的层间分化正是这两类适应在垂直结构上的表现：林冠层为阳生叶，林下为阴生叶。"},{"id":"7.4","t":"光周期现象","s":3,"c":"7. 光因子与生物的适应","x":"光周期指一昼夜中光照与黑暗的交替，生物对光周期变化的反应称光周期现象。1920 年 Garner 与 Allard 通过烟草试验发现光周期控制开花，据此把植物分为长日植物（需日照长于临界日长，如小麦、菠菜）、短日植物（需日照短于临界日长，如大豆、菊花）、日中性植物（如番茄）与长短日植物。关键变量是临界日长而非绝对日长，且真正被感知的是连续暗期的长度，暗期被短暂光照打断可逆转短日植物的开花。"},{"id":"7.5","t":"光周期与动物行为","s":2,"c":"7. 光因子与生物的适应","x":"动物的繁殖、迁徙、换毛、滞育多由光周期触发，因为光周期是四季中最稳定的信号。温带鸟类春季长日照促进性腺发育与迁徙，秋季短日照触发换羽与脂肪积累；昆虫以短日照诱导滞育。人工延长光照可使鸡产蛋增加、使菊花延迟开花（长日条件下短日植物不开花），这是光周期在生产中的直接应用。"},{"id":"7.6","t":"光照强度的其他生态效应","s":2,"c":"7. 光因子与生物的适应","x":"光照强度影响植物的分枝与冠形（强光下分枝多、冠幅大）、影响动物的活动节律与垂直迁移（浮游动物昼夜垂直移动以避开强光捕食）、影响水体的分层与温跃层形成。森林中光照强度随冠层深度呈指数衰减，符合 Beer-Lambert 定律（I=I0·e^{-kL}），其中 L 为叶面积指数，这解释了林下光照为何极弱以及为什么林下植物多具阴生叶。"},{"id":"8.1","t":"地球上温度的分布规律","s":3,"c":"8. 温度因子与生物的适应","x":"太阳辐射随纬度与季节变化，导致温度呈纬度地带性：年均温随纬度升高而递减，赤道附近约 26 ℃，极地可低于 -20 ℃。海拔每升高 100 m 气温平均下降约 0.6 ℃（干空气 1 ℃、湿空气 0.6 ℃），这一递减率造成山地植被的垂直带谱。水体因比热大、热传导慢而温度变化幅度远小于陆地，故水生生物的温度耐受范围常较窄，海洋温度的年较差通常仅数摄氏度。"},{"id":"8.2","t":"三基点温度与有效积温法则","s":3,"c":"8. 温度因子与生物的适应","x":"每一种生物的生命活动都有最低温度、最适温度与最高温度三个基点，称三基点温度；在最适温度下发育最快，偏离则减慢，超出上下限即停止或死亡。有效积温法则指生物完成某一发育阶段所需的有效温度总量为常数：K=N（T-C），其中 K 为有效积温（℃·d）、N 为发育天数、T 为平均温度、C 为发育起点温度，T-C 称有效温度。该法则用于预测害虫发生世代数、作物生育期与物候期，但当温度超过最适或存在滞育时法则失效。"},{"id":"8.3","t":"极端温度的适应","s":3,"c":"8. 温度因子与生物的适应","x":"植物对低温的适应包括细胞内积累可溶性糖与脯氨酸降低冰点、膜脂不饱和脂肪酸比例升高保持流动性、形成抗冻蛋白抑制冰晶生长、以及通过深的过冷状态（supercooling）避免结冰。动物对低温的适应包括增加产热（寒战与非寒战产热、棕色脂肪）、增加隔热（羽毛、毛、皮下脂肪）、降低体温（冬眠、日蛰伏）、以及行为调节（集群、筑巢、迁地）。对高温的适应包括增加散热（出汗、喘息、蒸发）、减少吸热（浅色、夜行）、以及进入夏眠或滞育。"},{"id":"8.4","t":"贝格曼规律与艾伦规律","s":3,"c":"8. 温度因子与生物的适应","x":"贝格曼规律（Bergmann's rule）指同种或近缘种的内温动物在寒冷地区个体体型较大，因为单位体重表面积较小、散热较慢。艾伦规律（Allen's rule）指寒冷地区的内温动物四肢、耳、尾等突出部分较短，以减少散热；炎热地区则相反。两条规律适用于内温动物且为统计趋势，存在例外（如候鸟因迁徙需求体型差异不显著），竞赛中常以\"是否适用于变温动物\"作为陷阱，答案是不适用。"},{"id":"8.5","t":"温度与物候","s":2,"c":"8. 温度因子与生物的适应","x":"物候指生物季节性现象的发生时间，如发芽、开花、落叶、迁徙、羽化。物候由温度与光周期共同驱动，其中春季事件主要由积温控制，秋季事件主要由光周期控制。物候对气候变暖极为敏感，观测显示北半球春季物候平均每十年提前约 2~3 天，由此产生的\"物候错配\"（如鸟类孵化期与毛虫高峰期不吻合）是气候变化的生态后果之一。"},{"id":"8.6","t":"温度与生物分布的上限","s":2,"c":"8. 温度因子与生物的适应","x":"温度常是物种分布的高纬与高海拔界限的决定因子：低温通过直接冻害与缩短生长季限制分布，因此树木分布上限常对应于生长季长度阈值（如最热月均温 10 ℃ 等温线是北方针叶林与苔原的界线）。海洋中温度还通过影响溶解氧与繁殖期限制鱼类分布。理解这一点可以解释为何气候变暖下物种分布普遍向高纬、高海拔迁移，而迁移速率受扩散能力限制常滞后于气候变化。"},{"id":"9.1","t":"水的生态作用","s":3,"c":"9. 水因子、土壤因子与生物的适应","x":"水是原生质的溶剂与反应介质，参与光合作用与全部水解代谢，也是物质运输与温度调节的载体。陆生生物的水分状况取决于降水、蒸发与土壤持水能力三者的平衡，其中降水与蒸发的比值决定干湿区划分：年降水量与年蒸发量之比即湿润度指数。全球降水呈纬度地带性：赤道多雨、副热带少雨、中纬多雨、极地少雨，由此形成森林—荒漠—草原—苔原的分布格局。"},{"id":"9.2","t":"植物对水分的适应与生活型","s":3,"c":"9. 水因子、土壤因子与生物的适应","x":"按对水分的适应，植物分为水生植物、湿生植物、中生植物与旱生植物。旱生植物又分两类：一类是逃旱型（短命植物、一年生荒漠植物在雨季完成生活史），另一类为耐旱型（肉质植物储水、硬叶植物角质层厚与气孔下陷、深根植物根系深入地下水）。Raunkiaer 以休眠芽的位置把植物划分为五类生活型：高位芽（乔木、灌木）、地上芽、地面芽、隐芽（球茎、根茎）、一年生。生活型谱可反映气候：热带雨林高位芽植物占比极高（可超过 60%），荒漠则以一年生与地面芽植物为主。生活型休眠芽位置典型植物指示气候高位芽植物距地面 25 cm 以上乔木、灌木、附生植物温暖湿润地上芽植物距地面 25 cm 以内半灌木、垫状植物寒冷或干旱地面芽植物地表，有枯叶保护多年生草本温带草原隐芽植物地下或水面以下根茎、球茎、水生植物严寒或干热一年生植物以种子越冬荒漠短命植物、作物极端干旱"},{"id":"9.3","t":"动物对水的适应","s":3,"c":"9. 水因子、土壤因子与生物的适应","x":"荒漠动物通过减少失水与增加得水适应干旱：昆虫具厚的上表皮蜡层、以代谢水为水源、排出尿酸而非尿素（节省水）；爬行动物与鸟类排尿酸；哺乳动物如更格卢鼠可仅靠干种子与代谢水生存，其尿液浓缩能力极强（肾髓质厚）。行为适应包括夜行、穴居（洞内湿度较高）、夏眠。水生动物则面对渗透压问题：淡水鱼排出大量稀尿并主动摄取盐分，海水鱼饮水并排出浓盐（通过鳃的氯细胞），洄游鱼类在降海或溯河时发生渗透调节的转变。"},{"id":"9.4","t":"土壤的物理性质及其生态作用","s":3,"c":"9. 水因子、土壤因子与生物的适应","x":"土壤由矿物质、有机质、水分、空气与生物组成，其物理性质包括质地（砂土、壤土、黏土）、结构、孔隙度、通气性与持水性。砂土通气好、保水差、养分少；黏土保水保肥但通气差；壤土兼具二者优点，故农业上最理想。土壤质地影响根系分布与土壤动物区系：孔隙直径决定何种生物可栖居，直径小于 0.2 mm 的孔隙中细菌难以被原生动物捕食，形成\"孔隙避难所\"。土壤温度与湿度还决定分解速率，进而影响碳周转。"},{"id":"9.5","t":"土壤的化学性质及其生态作用","s":3,"c":"9. 水因子、土壤因子与生物的适应","x":"土壤 pH 决定养分有效性：pH 5.5~7.0 时多数大量元素有效性最高；酸性条件下磷被铁铝固定、钼有效性下降，碱性条件下铁锰锌有效性下降。土壤盐分通过降低水势造成生理干旱，盐生植物通过积累渗透调节物质（脯氨酸、甜菜碱）、具盐腺泌盐或肉质化适应。土壤有机质含量决定阳离子交换量与保肥能力。指示植物可反映土壤性质：铁芒萁、杜鹃指示酸性土，碱蓬、柽柳指示盐碱土，蜈蚣草、南天竹常见于钙质土。"},{"id":"9.6","t":"植物对土壤的适应与菌根","s":2,"c":"9. 水因子、土壤因子与生物的适应","x":"植物对贫瘠土壤的适应方式包括形成深根或浅而广的根系、形成菌根、分泌有机酸活化难溶磷、以及食虫（如猪笼草在氮贫乏的酸性泥炭中捕虫补充氮）。菌根分为外生菌根（针叶树、栎类，真菌在根外形成菌套）与丛枝菌根（AM，约 80% 的维管植物，真菌菌丝进入皮层细胞内），后者显著提高磷的吸收效率。豆科植物与根瘤菌的共生固氮是氮输入的重要途径。"},{"id":"9.7","t":"土壤生物与土壤形成","s":2,"c":"9. 水因子、土壤因子与生物的适应","x":"土壤生物包括细菌、真菌、放线菌、藻类、原生动物、线虫、螨、弹尾目、蚯蚓、白蚁、马陆等，它们参与有机质分解、养分矿化、土壤结构形成与生物扰动。蚯蚓被称为\"土壤工程师\"，其活动可显著提高孔隙度与团聚体稳定性，达尔文估算英国农田每年可经蚯蚓翻动形成数毫米厚的表土。土壤生物多样性与地上生物多样性相互耦合，土壤食物网的能量传递遵循碎屑食物链途径。"},{"id":"10.1","t":"生物因子的类型","s":3,"c":"10. 生物因子与生态适应","x":"生物因子指影响某一生物的其他生物，包括同种个体（种内关系）与异种个体（种间关系）。按作用方式分为竞争、捕食、寄生、互利共生、偏利共生、他感作用（化感作用），按结果可分为对双方有利、有害或中性。生物因子属于密度制约因子，其作用强度随种群密度增加而增强，因此是种群调节与群落结构形成的主要动力。与气候因子的最大区别是：生物因子具有主动性与相互适应性，可产生协同进化。"},{"id":"10.2","t":"他感作用","s":2,"c":"10. 生物因子与生态适应","x":"他感作用（allelopathy）指植物或微生物向环境释放化学物质而抑制（或促进）其他生物的现象。典型例子包括黑胡桃分泌胡桃醌抑制周围植物、豚草分泌倍半萜内酯抑制作物、桉树叶挥发物抑制林下草本、以及某些藻类释放毒素引发赤潮。他感作用在农业上造成连作障碍（如西瓜、三七连作减产），在群落演替中可促进自我替代（如杂草早期占位抑制后来者）。"},{"id":"10.3","t":"形态适应","s":3,"c":"10. 生物因子与生态适应","x":"形态适应指生物在体型、构造、体色上对环境的适应。植物方面包括叶的变态（刺、卷须、鳞片、肉质叶）、根系类型（深根、须根、气生根、板根）、树冠形状（塔形、伞形）、以及落叶与常绿的选择。动物方面包括体色（保护色、警戒色、拟态）、体型（贝格曼规律）、附肢比例（艾伦规律）、以及穴居与树栖的体型特化。形态适应是竞赛识图题的常见考点，判断标准是\"该结构是否提高了特定环境下的适合度\"。"},{"id":"10.4","t":"生理适应","s":3,"c":"10. 生物因子与生态适应","x":"生理适应指代谢与调节机制上的适应，包括渗透调节（淡水鱼、海水鱼、盐生植物）、体温调节（外温与内温）、水分利用（CAM 与 C4 光合途径）、抗逆物质积累（脯氨酸、可溶性糖、抗冻蛋白、热激蛋白）、以及解毒酶系统（细胞色素 P450、金属硫蛋白）。C4 途径通过 PEP 羧化酶先在叶肉细胞固定CO₂，再在维管束鞘细胞脱羧，形成 CO₂ 浓缩机制，从而在高光高温干旱条件下具有更高的水分利用效率。"},{"id":"10.5","t":"行为适应","s":2,"c":"10. 生物因子与生态适应","x":"行为适应指通过行为调节减少环境胁迫，包括迁徙（鸟类、鲸类、蝗虫、驯鹿）、洄游（鲑鱼、鳗鲡）、昼夜活动节律、穴居、集群、领地行为与社会等级。迁徙与洄游依赖于导航能力，可利用地磁、太阳方位、星象、嗅觉与地形标记。行为适应的优势是响应速度快（可在小时内完成），局限是需要神经系统支持且耗能。"},{"id":"10.6","t":"生态型与生态宗","s":3,"c":"10. 生物因子与生态适应","x":"生态型（ecotype）指同一物种因长期适应不同环境而形成的、在形态生理上可区分的遗传变异类群，由 Turesson 于 1922 年提出，并通过移栽实验验证其遗传基础（在原产地表现差异在共同园圃中仍保留）。同一物种的不同生态型之间可以杂交，故仍属同一物种，这与亚种不同。生态宗（ecological race）常指适应特定寄主或生境的种群，如寄生蜂的不同寄主宗。生态型的分化是物种形成的起点。"},{"id":"10.7","t":"渐变群与表型可塑性","s":2,"c":"10. 生物因子与生态适应","x":"渐变群（cline）指性状沿环境梯度呈连续渐变的现象，如随纬度升高体色变浅、随海拔升高植株变矮。渐变群反映选择压力的连续变化与基因流的平滑作用。表型可塑性（phenotypic plasticity）指同一基因型在不同环境下表现不同表型的现象，是不涉及遗传改变的环境响应，如阴生叶与阳生叶的差异、水毛茛水下叶与气生叶的形态差异。可塑性的极端形式是 polyphenism（环境决定的不同形态型），如蚜虫的翅型、蝗虫的散居型与群居型。"},{"id":"10.8","t":"趋同适应与趋异适应","s":2,"c":"10. 生物因子与生态适应","x":"趋同适应指不同类群的生物在相似环境中形成相似的形态或生理特征，如仙人掌（仙人掌科）与 Euphorbia 的肉质刺状茎、沙漠植物的肉质化、水生哺乳动物的流线型体型。趋异适应指同一类群在不同环境中形成不同特征，如蔷薇科植物在高山呈垫状、在森林呈乔木。趋同适应是\"生境决定形态\"的证据，趋异适应是\"物种辐射\"的证据，二者的共同基础是自然选择的作用。"},{"id":"11.1","t":"生活史与能量分配权衡","s":3,"c":"11. 生活史对策与休眠、滞育","x":"生活史（life history）指生物从出生到死亡所经历的全部发育与繁殖过程，其关键参数包括个体大小、发育速度、首次繁殖年龄、每次繁殖的后代数量、繁殖次数与寿命。由于可用于生长繁殖的能量有限，各参数之间存在权衡（trade-off）：投入当前繁殖的能量多于则剩余给生长与存活者少，反之亦然。权衡是生活史对策多样性的根本原因，\"没有对所有环境都最优的生活史\"是竞赛常考的判断。"},{"id":"11.2","t":"r 选择与 K 选择","s":3,"c":"11. 生活史对策与休眠、滞育","x":"MacArthur 与 Wilson（1967）提出 r-K 选择理论：在不稳定、密度远低于 K 的环境中，选择有利于高增殖率（大 r）、早熟、单次繁殖、后代多而小、寿命短的类群，称 r 对策者（如昆虫、一年生杂草、啮齿类）；在稳定、接近 K 的环境中，选择有利于竞争能力强、晚熟、多次繁殖、后代少而大、有亲代抚育、寿命长的类群，称 K 对策者（如大型哺乳动物、多年生乔木）。二者是连续谱的两端，中间为 r-K 连续统，绝大多数生物处于中间位置。特征r 对策者K 对策者种群动态剧烈波动，常爆发相对稳定，接近 K发育速度快，早熟慢，晚熟寿命短长体形小大繁殖方式单次，后代多而小多次，后代少而大亲代抚育无或极少有存活曲线多为 III 型多为 I 型种内竞争弱，主要受气候控制强，主要受密度制约代表类群昆虫、一年生杂草、细菌大型兽类、乔木、鲸"},{"id":"11.3","t":"Grime 的 CSR 三角对策","s":3,"c":"11. 生活史对策与休眠、滞育","x":"Grime（1974）以\"胁迫\"（限制光合与生长的资源不足）与\"干扰\"（生物量被破坏）两个维度提出三种植物对策：竞争型 C（低胁迫低干扰，资源丰富稳定，如荨麻、芦苇）、胁迫耐受型 S（高胁迫低干扰，如高山植物、荒漠植物、苔藓）、杂草型 R（低胁迫高干扰，如一年生农田杂草）。三者构成 CSR三角，实际植物多位于三角形内部的中间型（如 CS、CR）。CSR 与 r-K 的对应关系是：R 近似 r 对策，C 与 S 近似 K 对策的不同侧面。"},{"id":"11.4","t":"繁殖格局与繁殖成本","s":2,"c":"11. 生活史对策与休眠、滞育","x":"一次繁殖（semelparity，如竹类、鲑鱼、龙舌兰、一年生植物）与多次繁殖（iteroparity，如多数多年生植物与多次产仔的兽类）是两种基本格局。一次繁殖把全部资源投入一次繁殖，代价是寿命终止；多次繁殖通过分散风险提高终身繁殖成效。繁殖成本表现为存活率下降、后续繁殖力降低、生长受抑，例如多年生植物大量结实后次年生长量下降。繁殖价值（reproductive value）指个体在某一时刻对将来种群的相对贡献，是判断\"何时首次繁殖最优\"的理论工具。"},{"id":"11.5","t":"休眠与滞育","s":3,"c":"11. 生活史对策与休眠、滞育","x":"休眠（dormancy）是生物在不利环境下主动降低代谢、停止生长的状态，包括冬眠、夏眠与种子休眠。滞育（diapause）是昆虫等对外界不良条件的预告信号（主要是短日照与低温）作出的遗传性、程序化的发育停滞，具有固定的滞育期，不能由条件改善立即解除；而静育（quiescence）是直接由不利条件引起的被动停滞，条件改善即恢复。这一区别是竞赛的高频考点：滞育由光周期诱导且需经历低温解除（vernalization 型），静育由温度湿度直接决定，直接解除。"},{"id":"11.6","t":"种子休眠与萌发策略","s":2,"c":"11. 生活史对策与休眠、滞育","x":"种子休眠可避免在不利季节萌发，其机制包括种皮不透水不透气（硬实）、胚未成熟、存在萌发抑制物（ABA）、以及需要低温层积或光照（光敏素介导）打破。土壤种子库是植物种群的重要缓冲：休眠种子可在土壤中存活数年（如杂草种子可达数十年），使群落在干扰后迅速恢复。萌发时机的最优策略是\"在可预测的良好季节开始生长\"，因此温带植物多以低温层积作为春化信号。"},{"id":"11.7","t":"复杂生活周期与世代交替","s":1,"c":"11. 生活史对策与休眠、滞育","x":"许多生物具有复杂生活周期：植物与藻类的世代交替（孢子体与配子体），寄生生活史中的多个宿主（如疟原虫在人蚊之间、肝吸虫在螺与鱼之间），以及周期性出现的形态型。复杂生活周期的适应意义在于分散风险、利用不同资源、以及规避寄主免疫或天敌。理解这一点有助于解释为何某些物种难以人工培养（如需要特定中间宿主）以及为何消灭中间宿主可阻断疾病传播。"},{"id":"12.1","t":"生态位的三种定义","s":3,"c":"12. 生态位概念","x":"生态位（niche）概念经历三次演化：Grinnell（1917）强调空间与生境需求，把生态位视为物种在群落中所占据的基本\"地址\"（空间生态位）；Elton（1927）强调功能地位，把生态位视为物种在食物链中的角色与对资源的利用方式（功能生态位）；Hutchinson（1957）提出超体积生态位，把生态位定义为一个 n 维资源空间中的体积，每一维对应一个影响该物种生存繁殖的环境变量。现代生态学普遍采用 Hutchinson 定义，因为它可定量、可比较。"},{"id":"12.2","t":"Hutchinson 超体积生态位","s":3,"c":"12. 生态位概念","x":"在 n 维环境空间中，每一点代表一个环境条件组合；使物种能够维持正增长的条件集合构成一个 n 维超体积，即该物种的基础生态位。维度可包括温度、湿度、光照、食物粒径、活动时间等，维数取决于研究目的。由于超体积难以直接可视化，实际研究中常降维为二维或三维，或用生态位模型（如MaxEnt）以气候变量描述生态位。该概念的优点是使\"生态位宽度\"\"生态位重叠\"获得了可计算的几何含义。"},{"id":"12.3","t":"基础生态位与实际生态位","s":3,"c":"12. 生态位概念","x":"基础生态位（fundamental niche）指在没有竞争与捕食等生物限制条件下物种可占据的全部生态位空间，由生理耐受决定；实际生态位（realized niche）指在存在竞争与捕食时实际占据的较小生态位空间。二者的差异即\"生物限制\"的度量。经典例证是 Connell 的藤壶实验：Chthamalus 的基础生态位覆盖整个潮间带，但受 Balanus 竞争后实际生态位仅限高潮区；去除Balanus 后 Chthamalus 可向下扩展。"},{"id":"12.4","t":"生态位宽度及其测度","s":3,"c":"12. 生态位概念","x":"生态位宽度（niche breadth）指物种利用资源的总范围，反映其特化程度。常用 Levins 指数：B=1/Σp_i²，其中 p_i 为第 i 类资源的利用比例；B 值越小表示越特化，越大表示越泛化。另一个常用指标是 Shannon 型宽度 B=Σp_i·ln p_i。宽度大的物种称泛化种，抗干扰能力强但竞争能力弱；宽度小的称特化种，竞争效率高但适应性差。竞赛中常给出资源利用比例表要求计算并比较。"},{"id":"12.5","t":"生态位重叠与分化","s":3,"c":"12. 生态位概念","x":"生态位重叠（niche overlap）指两个物种对同一资源的共同利用程度，可用 Pianka 指数 O=Σp_ij p_ik/√(Σp_ij²·Σp_ik²) 计算，取值 0~1。重叠并不必然导致竞争，因为资源可能过剩；但资源有限时重叠大的物种竞争激烈，自然选择将促使其发生生态位分化（resource partitioning），如在同一株树上取食不同部位、在不同时间活动、取食不同粒径的食物。分化后重叠下降，共存成为可能，这是\"竞争排斥\"与\"多样性共存\"之间的关键环节。"},{"id":"12.6","t":"生态位释放与性状替换","s":2,"c":"12. 生态位概念","x":"当竞争者被移除后，物种可扩展到原有基础生态位中此前被占据的部分，称生态位释放（niche release）。长期隔离后，同域分布的近缘种常表现出性状替换（character displacement），即在与竞争者共存地区形态差异比在异域地区更大，如达尔文雀的喙深、招潮蟹的螯形。性状替换是生态位分化的进化证据，也是\"竞争导致性状演化\"的直接观测。"},{"id":"12.7","t":"生态位与物种共存机制","s":2,"c":"12. 生态位概念","x":"解释多物种共存的主要机制有：（1）生态位分化（资源分割）；（2）中性理论（随机漂变与扩散限制，物种在生态等价时共存）；（3）储藏效应（storage effect，环境波动与生活史缓冲使不同年份的优胜者不同）；（4）捕食与干扰抑制竞争者；（5）斑块动态与集合种群效应（定殖—竞争权衡）。竞赛题若问\"为何热带雨林能容纳如此多物种\"，应答应同时包含生态位分化、空间异质性与干扰动态，而非单一因素。第三篇 种群生态学"},{"id":"13.1","t":"种群的定义与基本认识","s":3,"c":"13. 种群概念与数量特征","x":"种群（population）指在一定时间内占据一定空间的同种生物个体的集合，是物种存在与进化的基本单位。种群具有个体所不具备的群体特征：密度、出生率、死亡率、年龄结构、性别比、空间格局、遗传组成。对植物与营固着生活的动物需区分基株（genet，由合子发育的遗传个体）与分株（ramet，营养繁殖形成的构件），因为按分株计数会高估遗传个体数，这一区别在克隆植物研究中至关重要。"},{"id":"13.2","t":"种群密度","s":3,"c":"13. 种群概念与数量特征","x":"密度指单位面积或体积内的个体数，分粗密度（单位总空间的个体数）与生态密度（单位有效生境的个体数）。测定方法包括：（1）总数量调查，适用于大型稀少的动物；（2）样方法，适用于植物与固着动物；（3）标志重捕法，适用于活动动物，估计式为 N=M·C/R，其中 M 为标志个体数、C 为第二次捕获数、R 为其中标志个体数；（4）去除取样法；（5）粪便计数与足迹计数等间接法。标志重捕法的前提是标志不影响存活与行为、种群封闭、标志个体充分混合。"},{"id":"13.3","t":"出生率与死亡率","s":3,"c":"13. 种群概念与数量特征","x":"出生率分最大出生率（绝对出生率，在理想条件下）与实际出生率（生态出生率，实际条件下的出生率），后者总小于前者。死亡率同样分最低死亡率（仅由生理寿命决定）与实际死亡率。出生率与死亡率均以单位时间内每千个体的出生或死亡数表示（‰）。二者之差构成种群的内禀增长能力，实际增长还须加上迁入率、减去迁出率，即 dN/dt=(b-d)+(i-e)N。"},{"id":"13.4","t":"迁入与迁出的意义","s":2,"c":"13. 种群概念与数量特征","x":"迁入（immigration）与迁出（emigration）是开放种群数量变动的重要成分，在小种群与破碎化生境中甚至成为主导因素。迁入可缓解近交衰退并补充\"救援效应\"（rescue effect），迁出则可能导致源种群数量下降。人类活动造成的生境破碎化显著降低了斑块间迁移率，因此集合种群理论（第 18 章）把迁移率作为核心参数。"},{"id":"13.5","t":"种群的空间分布格局","s":3,"c":"13. 种群概念与数量特征","x":"种群个体的水平分布有三种基本格局：随机分布（个体独立、环境均质，方差/均值比 S²/m≈1，可用 Poisson 分布检验）、均匀分布（个体相互排斥，S²/m<1，常由竞争、他感作用或人工栽植造成）、聚集分布（个体成群，S²/m>1，由繁殖方式、环境异质性、社会行为造成，是自然界最常见的格局）。检验方法为计算方差均值比并对 1 作 t 检验，或用 χ² 拟合 Poisson 分布。格局类型方差/均值比成因举例随机分布≈1环境均质、个体独立森林中某些分散的乔木均匀分布<1竞争、他感作用、人工栽植荒漠灌木、人工林、领域性动物聚集分布>1繁殖方式、环境异质、社会行为克隆植物、鱼群、鸟巢群"},{"id":"13.6","t":"种群统计学的基本参数","s":3,"c":"13. 种群概念与数量特征","x":"种群统计学（demography）研究种群的出生、死亡、迁移与年龄结构，其基本参数包括：x（年龄或龄期）、n_x（该龄期开始时的存活个体数）、l_x（存活率，l_x=n_x/n_0）、d_x（死亡数）、q_x（死亡率，q_x=d_x/n_x）、L_x（该龄期平均存活数）、T_x（x 龄期后的总个体年数）、e_x（期望寿命，e_x=T_x/n_x）、m_x（该龄期每雌产雌数）、l_x·m_x（该龄期的繁殖贡献）。这些参数构成生命表，是计算内禀增长率的基础。"},{"id":"13.7","t":"种群的遗传特征","s":2,"c":"13. 种群概念与数量特征","x":"种群是遗传变异的基本储存单位，其遗传特征包括基因频率、基因型频率、遗传多样性（杂合度、等位基因丰富度）与遗传结构（种群间分化Fst）。小种群因遗传漂变与近交而丧失遗传多样性，等位基因丰富度的下降快于杂合度，因此保护遗传学强调不仅要维持个体数，还要维持有效种群大小（Ne），Ne 通常只有实际个体数的 10%~50%。"},{"id":"14.1","t":"生命表的类型","s":3,"c":"14. 生命表与存活曲线","x":"生命表（life table）是系统记录种群各龄期存活与死亡情况的表格，分两类：动态生命表（同生群生命表，cohort life table）跟踪同一批同时出生的个体直至全部死亡，适用于寿命较短的生物；静态生命表（现时生命表，timespecific life table）在某一时刻统计各龄期的存活个体数，由年龄结构推算存活与死亡，适用于寿命长、难以跟踪的生物，但前提是种群稳定且各龄期死亡率不变。"},{"id":"14.2","t":"生命表的编制与计算","s":3,"c":"14. 生命表与存活曲线","x":"编制步骤为：确定龄期划分，记录各龄期开始时的存活数 n_x，计算l_x=n_x/n_0、d_x=n_x-n_{x+1}、q_x=d_x/n_x、L_x=(n_x+n_{x+1})/2、T_x=ΣL_x、e_x=T_x/n_x，并记录 m_x。示例：若 n_0=1000、n_1=200、n_2=50，则 l_1=0.200、q_0=0.800；说明该种群早期死亡率极高。生命表的关键用途是识别\"关键龄期\"（key factor analysis），即死亡率最高或变异最大的龄期，这决定保护或防治的切入时间。"},{"id":"14.3","t":"存活曲线的三种类型","s":3,"c":"14. 生命表与存活曲线","x":"以 l_x 对 x 作图得存活曲线。I 型（凸型）：早期死亡率低，后期集中死亡，如人类、大型哺乳动物、具亲代抚育的鸟类，对应 K 对策；II 型（对角线型）：各龄期死亡率恒定，如许多鸟类、某些蜥蜴、水螅，年死亡率约 50%；III 型（凹型）：早期死亡率极高、后期存活者死亡率低，如鱼类、多数无脊椎动物、多数植物、海洋浮游生物，对应 r 对策。竞赛常给曲线图要求判断类型并推断该物种的生活史对策与繁殖方式。死亡率特征代表生物I型类型凸型曲线形状幼体低、老年高人类、象、鲸少生优育，K 对策II 型对角线各龄期大致恒定鸟类、水螅、某些蜥蜴中等，多为多次繁殖III 型凹型幼体极高、成体低鱼类、牡蛎、多数多生少育，r 对策生活史对策植物"},{"id":"14.4","t":"净生殖率与世代时间","s":3,"c":"14. 生命表与存活曲线","x":"净生殖率 R_0=Σl_x·m_x，表示一个雌体在一生中所产生的雌性后代数；R_0>1 种群增长，R_0=1 稳定，R_0<1 下降。世代时间T=Σx·l_x·m_x/Σl_x·m_x，即从出生到子代出生的平均时间。由 R_0 与 T 可估算内禀增长率 r≈lnR_0/T，这是计算 r 的近似公式（精确值需解 EulerLotka 方程 Σl_x·m_x·e^{-rx}=1）。"},{"id":"14.5","t":"内禀增长率 r_m","s":3,"c":"14. 生命表与存活曲线","x":"内禀增长率（intrinsic rate of increase，r_m）指在无资源限制、无天敌、无疾病、年龄结构稳定的理想条件下种群所能达到的最大瞬时增长率，由遗传决定，是物种的基本生物学属性。r_m 的数值范围：细菌与某些昆虫可达1 d⁻¹ 以上，小型啮齿类约 0.01 d⁻¹，大型哺乳动物可低至 0.001 d⁻¹。r_m 越大，种群恢复能力越强，但竞争能力通常越弱，这正是 r-K 权衡的量化表现。"},{"id":"14.6","t":"周限增长率 λ","s":3,"c":"14. 生命表与存活曲线","x":"周限增长率（finite rate of increase，λ）指经过一个单位时间后种群数量为原来的倍数，N_{t+1}=λ·N_t。它与瞬时增长率 r 的关系为 λ=er，等价地r=lnλ。λ>1 表示增长，λ=1 表示稳定，λ<1 表示下降。对离散繁殖的生物（一年生植物、季节性繁殖的昆虫），λ 比 r 更直观；Leslie 矩阵的最大特征值即λ，对应特征向量为稳定年龄分布。"},{"id":"14.7","t":"生命表在保护中的应用","s":2,"c":"14. 生命表与存活曲线","x":"生命表可用于：（1）识别关键龄期，把有限的保护资源投到死亡率最高或弹性（elasticity）最大的参数上；（2）计算种群趋势指数，预测未来数量；（3）评估不同管理措施（如人工孵化、幼体放流、成体保护）的相对效果，其中\"保护成体存活率\"通常比\"提高幼体存活率\"更能提升 λ，因为成体存活率对 λ的弹性更大。这一结论是海龟保护策略由\"保护卵\"转向\"保护成体\"的理论依据。"},{"id":"15.1","t":"指数增长模型","s":3,"c":"15. 种群增长模型","x":"在资源无限、无环境限制的理想条件下，种群按恒定的瞬时增长率增长：dN/dt=rN，积分得 N_t=N_0·e^{rt}。若为离散繁殖，则 N_t=N_0·λt，其中λ=er。指数增长的特征是\"增长率与当前数量成正比\"，故曲线呈 J 型，倍增时间 t_d=ln2/r≈0.693/r。指数增长只出现在种群建立初期或资源突然释放时，如细菌在新鲜培养基中、外来种入侵初期、藻类在富营养化水体中。"},{"id":"15.2","t":"逻辑斯蒂增长模型","s":3,"c":"15. 种群增长模型","x":"当资源有限时，增长率随密度上升而下降，Verhulst（1838）与 Pearl（1920）提出逻辑斯蒂方程：dN/dt=rN(K-N)/K，其中 K 为环境容纳量，积分得 N_t=K/(1+e^{a-rt})。模型的关键特征：当 N=K/2 时增长率最大，为rK/4；曲线呈 S 型，分为开始期（增长缓慢）、加速期（近似指数增长）、转折期（N≈K/2，增长最快）、减速期（增长放慢）、稳定期（N→K，增长趋于 0）。"},{"id":"15.3","t":"环境容纳量 K 的含义","s":3,"c":"15. 种群增长模型","x":"K 指在特定环境条件下种群所能维持的最大数量，由资源、空间、天敌、疾病等共同决定，因此 K 不是固定常数，而是随环境改变的变量：改善环境可提高 K（如施肥、增温、人工投饵），恶化环境则降低 K（如污染、生境破碎）。K 也不是\"种群必然达到的水平\"，因为种群常因扰动、时滞或捕食而低于或超过 K。竞赛中\"K 值是固定不变的\"是一个经典错误选项。"},{"id":"15.4","t":"逻辑斯蒂模型的评价与修正","s":2,"c":"15. 种群增长模型","x":"逻辑斯蒂模型的优点是把密度制约引入增长过程，可解释 S 型曲线与稳定平衡；其局限包括：（1）假设 r 与 K 恒定，忽略时滞与环境波动；（2）假设密度效应即时且线性，实际常为非线性并存在时滞；（3）未区分不同龄期的贡献；（4）对\"Allee 效应\"（低密度时增长率下降）无法描述。修正形式包括引入时滞的时滞逻辑斯蒂方程、Beverton-Holt 与 Ricker 模型、以及含 Allee效应的模型。"},{"id":"15.5","t":"离散型增长与混沌","s":2,"c":"15. 种群增长模型","x":"对离散繁殖且世代不重叠的种群，用差分方程N_{t+1}=N_t[1+r(1-N_t/K)] 描述。May（1976）发现：当 r<2 时种群趋于稳定点；2<r<2.57 时出现稳定的两点或多点周期振荡；r>2.57 后进入倍周期分岔；r 超过约 2.69 后进入混沌（chaos），即由确定性方程产生不可长期预测的非周期波动。这一结果说明\"简单的确定性规则也能产生复杂动态\"，是生态学中非线性思维的经典例证。"},{"id":"15.6","t":"模型参数的实际估算","s":2,"c":"15. 种群增长模型","x":"实际研究中 r 由生命表估算（r≈lnR_0/T 或解 Euler-Lotka 方程），K由长期平均密度或资源换算估算。对野外种群常用去除取样法或标志重捕数据拟合增长曲线；对资源受限的种群，K 也可由\"每消耗单位资源所支持的个体数×资源总量\"估算。估算的可靠性取决于时间序列长度与是否覆盖环境波动，短期数据往往严重高估 r 与 K。"},{"id":"15.7","t":"种群增长的实例与人类种群","s":2,"c":"15. 种群增长模型","x":"典型案例包括：（1）引入澳大利亚的兔在缺乏天敌条件下迅速增长，随后受疾病与竞争抑制；（2）美国圣保罗岛引入驯鹿后先爆发后崩溃，说明超过 K后种群可能急剧下降至远低于 K；（3）世界人口 1804 年约 10 亿，1927 年 20亿，1960 年 30 亿，1974 年 40 亿，1987 年 50 亿，1999 年 60 亿，2011 年70 亿，2022 年约 80 亿，增长率在 1960 年代达峰值约 2.1% 后持续下降，呈现\"增长但增速递减\"的过渡型特征。"},{"id":"16.1","t":"种内竞争与密度效应","s":3,"c":"16. 种内竞争与种群调节","x":"种内竞争指同种个体因共同资源有限而相互抑制，其强度随密度上升而增强，表现为存活率下降、生长变慢、繁殖力降低、个体变小。种内竞争有两种作用方式：干扰型（直接相互排斥，如领域争斗、他感作用）与利用型（间接消耗资源）。与种间竞争不同，种内竞争不导致\"一方胜出\"，而是通过密度制约使种群稳定在 K 附近，因此它是种群调节的核心机制。"},{"id":"16.2","t":"最后产量恒值法则","s":3,"c":"16. 种内竞争与种群调节","x":"Kira 等（1953）发现，在密度很大且生长条件一致时，作物的最终产量（单位面积总干重 Y）与密度 N 无关，近似为常数：Y=W·N=常数，其中 W为平均单株重。其原因是高密度下资源被完全利用，无论个体数多少，单位面积可固定的总能量相近，只是分配在个体数与个体大小之间不同。该法则在密度超过一定阈值后成立，在低密度下不成立。"},{"id":"16.3","t":"-3/2 自疏法则","s":3,"c":"16. 种内竞争与种群调节","x":"当种群密度过高时，部分个体死亡使密度下降、个体增大，这一过程称自疏（self-thinning）。Yoda 等（1963）发现自疏过程中平均单株重与密度满足 W=C·N^{-3/2}，两边取对数得 lgW=lgC-(3/2)lgN，即在双对数图上斜率为-1.5 的直线，故称 -3/2 自疏法则。其含义是：密度每增加 4 倍，平均个体重降至 1/8。自疏斜率在不同物种间接近 -1.5（多数报道在 -1.3 至 -1.8 之间），是植物种群密度的\"上限边界\"。"},{"id":"16.4","t":"密度制约与非密度制约","s":3,"c":"16. 种内竞争与种群调节","x":"密度制约因子指作用强度随种群密度变化而变化的因子，如食物、天敌、传染病、种内竞争，其对出生率与死亡率的影响构成负反馈，是种群调节的主要机制。非密度制约因子指作用强度与密度无关的因子，如寒潮、台风、火烧、农药，其作用造成突发性、非选择性的死亡，不能单独维持种群的稳定，但可造成数量的大幅波动。实际种群的数量变动总是二者共同作用的结果。"},{"id":"16.5","t":"种群调节的主要学说","s":3,"c":"16. 种内竞争与种群调节","x":"（1）气候学派（Bodenheimer、Andrewartha 与 Birch）：认为种群数量主要由气候等非密度制约因子决定，种群很少达到 K，密度制约只是偶然发生，以蓟马与澳大利亚昆士兰果蝇研究为据。（2）生物学派（Nicholson）：认为种群受密度制约的生物因子（竞争、捕食、寄生、疾病）调节，能自我维持在平衡点。（3）食物因素学说：强调食物量的限制，但食物量本身受种群消耗影响，故属密度制约。（4）自动调节学说：包括行为调节（Wyatt 的领域性）、内分泌调节（Christian 的应激假说，高密度下肾上腺皮质活动增强、生殖受抑）、遗传调节（Chitty 的遗传多态假说，高密度选择攻击性强的基因型）。"},{"id":"16.6","t":"内分泌调节与行为调节","s":2,"c":"16. 种内竞争与种群调节","x":"Christian 的内分泌调节假说认为：高密度造成社会应激，通过下丘脑—垂体—肾上腺轴使肾上腺皮质激素升高，抑制促性腺激素分泌，导致生殖力下降、死亡率上升，从而使密度回落。行为调节则通过领域性与社会等级限制实际参与繁殖的个体数，如许多鸟类只有占据领域的个体才能繁殖，因而密度上升时繁殖个体数受限而种群稳定。二者都属于\"内部自我调节\"，其共同点是调节信号来自种群自身密度而非外部资源量。"},{"id":"16.7","t":"综合调节观点","s":2,"c":"16. 种内竞争与种群调节","x":"现代观点认为种群调节是多因子综合作用：在低密度时非密度制约的气候因子占主导，在高密度时密度制约的食物、天敌与种内竞争占主导；不同因子在不同密度区间的作用强度不同（\"多因子调节\"或\"综合调节\"）。这一观点解释了为何单一因子实验常难以精确预测野外种群动态，也是\"取食限制与捕食限制的相对重要性\"这一生态学长期争论的来源。"},{"id":"17.1","t":"年龄结构与三种类型","s":3,"c":"17. 年龄结构、性别比与种群波动","x":"年龄结构指种群中各龄期个体所占比例，用年龄金字塔表示，分为三种基本类型：增长型（幼体比例高、老年少，金字塔呈下宽上窄的正金字塔，出生率大于死亡率，种群将增长）、稳定型（各龄期比例适中，钟形，出生率约等于死亡率）、衰退型（幼体少、老年多，壶形，出生率小于死亡率，种群将下降）。年龄结构可预测种群未来趋势，因此在渔业与保护生物学中用\"幼体比例\"判断种群健康状况。"},{"id":"17.2","t":"年龄结构与 Leslie 矩阵","s":2,"c":"17. 年龄结构、性别比与种群波动","x":"Leslie 矩阵把年龄结构与存活率、繁殖力结合为矩阵形式：n_{t+1}=L·n_t，其中 L 的第一行为各龄期的繁殖力（F_x），次对角线为存活率（P_x）。矩阵的最大特征值即周限增长率 λ，对应特征向量为稳定年龄分布。当种群达到稳定年龄分布后，各龄期比例不再变化，整体按 λ 等比增长，这一性质解释了为何用 λ 可准确预测长期趋势。Leslie 矩阵还可计算生殖价与弹性分析。"},{"id":"17.3","t":"性别比及其类型","s":3,"c":"17. 年龄结构、性别比与种群波动","x":"性别比有三种：第一性比（受精时的性别比例，理论为 1:1）、第二性比（出生时的比例）、第三性比（成熟个体或繁殖群体的比例）。Fisher 的频率依赖选择理论预言，在父母对两性投入相等时，进化上稳定的性别比为 1:1。实际性别比常偏离 1:1，原因包括局域配偶竞争（LMC，如许多寄生蜂的偏雌比）、亲子冲突、环境性决定（如鳄鱼与龟的孵化温度决定性别）、以及人类偏好的社会因素。"},{"id":"17.4","t":"种群的季节波动与年际波动","s":2,"c":"17. 年龄结构、性别比与种群波动","x":"季节波动由繁殖季节性、世代周期与季节性资源变化造成，表现为一年内的规律起伏，如温带昆虫的世代数、浮游动物的春秋高峰。年际波动由气候、食物、天敌的年际差异造成，幅度可相差数十倍。判断波动是否具有周期性需长于 10 年的连续数据，因为短序列易把随机波动误判为周期。"},{"id":"17.5","t":"周期性波动与种群周期","s":3,"c":"17. 年龄结构、性别比与种群波动","x":"某些北方种群呈现明显的周期性波动：旅鼠与田鼠的 3~4 年周期，雪兔与加拿大猞猁的 9~10 年周期（基于毛皮收购记录的经典数据），以及某些昆虫的周期性爆发。解释假说包括食物耗竭、天敌追随、植物防御物质周期变化、以及内因的遗传或内分泌振荡。竞赛中常以猞猁—雪兔数据考查\"捕食者与猎物数量的相位关系\"，标准答案是猎物峰值先于捕食者峰值（相位滞后）。"},{"id":"17.6","t":"种群爆发与生态入侵","s":3,"c":"17. 年龄结构、性别比与种群波动","x":"种群爆发指种群数量在短期内急剧上升并造成危害，如东亚飞蝗、松毛虫、赤潮藻类。爆发的条件通常包括：气候适宜、天敌缺失、食物丰富、繁殖力强、扩散能力强。生态入侵是爆发的特殊形式，指外来种在新区域建立种群并迅速扩张、造成生态或经济损失。我国主要入侵种包括紫茎泽兰、飞机草、水葫芦（凤眼蓝）、加拿大一枝黄花、互花米草、松材线虫、美国白蛾、红火蚁、福寿螺等。"},{"id":"17.7","t":"种群波动的成因分析框架","s":2,"c":"17. 年龄结构、性别比与种群波动","x":"分析种群波动的成因可按四步：一是判断波动是否具有周期性（时间序列分析）；二是判断是否密度制约（回归 lnN_t 对 lnN_{t-1}，斜率显著为负即密度制约）；三是识别关键因子（关键因子分析，找与总死亡率变异最相关的龄期）；四是区分内因与外因（内因指行为、内分泌、遗传调节，外因指气候、食物、天敌）。这一框架是竞赛综合分析题的标准答法。"},{"id":"18.1","t":"集合种群的概念","s":3,"c":"18. 集合种群","x":"集合种群（meta-population）指由若干空间上相互隔离、但通过个体迁移相互联系的局部种群（local population）构成的总体。其核心思想是：即使每个局部种群都有灭绝风险，只要迁入率足够高，整个集合种群仍可长期存续。这一概念由 Levins（1969）提出，是生境破碎化条件下保护生物学的理论基础。"},{"id":"18.2","t":"Levins 模型","s":3,"c":"18. 集合种群","x":"Levins 模型描述被占据斑块比例 P 的动态：dP/dt=cP(1-P)-eP，其中 c为定殖率、e 为局部灭绝率。平衡时 P*=1-e/c。模型的推论是：只要 c>e，集合种群可长期存在；生境斑块减少或隔离度上升会降低 c、提高 e，使 P* 下降；当 e≥c 时 P*=0，集合种群崩溃。模型的局限是假设所有斑块等价（实际上大斑块更不易灭绝、更易被定殖），故后续发展出结构化的集合种群模型。"},{"id":"18.3","t":"集合种群的四种结构类型","s":2,"c":"18. 集合种群","x":"Boorman 与 Levitt 提出四种类型：（1）大陆—岛屿型（mainlandisland），存在一个不会灭绝的大陆种群，岛屿种群靠迁入维持；（2）核心—卫星型（core-satellite），少数大种群稳定、周围小种群易灭绝并靠迁入重建；（3）缀块性种群（patchy population），斑块间迁移频繁、局部灭绝极少，实质是单一功能种群；（4）非平衡集合种群（non-equilibrium），灭绝率高于定殖率、整体处于衰退。判断类型的关键是迁移率与局部灭绝率的相对大小。"},{"id":"18.4","t":"源—汇种群","s":3,"c":"18. 集合种群","x":"源种群（source）指出生率大于死亡率、有净迁出的种群；汇种群（sink）指死亡率大于出生率、靠迁入维持的种群。源—汇结构的存在使\"某地有该物种\"不等于\"该地是其适宜生境\"，因此保护规划必须识别源种群所在的生境。判断方法是比较不同生境的 λ：λ>1 为源，λ<1 为汇。竞赛中\"某保护区内的种群持续下降但物种未消失\"的题型，答案常指向该地实为汇、需保护外部源种群。"},{"id":"18.5","t":"灭绝—定殖平衡与岛屿生物地理学的关系","s":2,"c":"18. 集合种群","x":"集合种群理论中的\"定殖率与灭绝率的平衡\"与岛屿生物地理学中的\"种数平衡\"在数学结构上同源：二者都以平衡方程描述动态，都是\"局部过程与区域过程\"的组合。区别在于尺度与对象：岛屿理论讨论的是物种数（群落层次），集合种群讨论的是种群被占据的斑块比例（种群层次）。竞赛常以此为跨章节综合题的连接点。"},{"id":"18.6","t":"集合种群理论的应用","s":3,"c":"18. 集合种群","x":"应用包括：（1）生境破碎化评估，破碎化降低了斑块面积与连通性，从而同时降低 c 与提高 e；（2）生态廊道设计，廊道提高迁移率即提高 c，但要注意廊道也可能传播疾病与入侵种、增加被捕食风险；（3）自然保护区网络设计，强调\"多斑块+连通\"优于\"单一大斑块\"之外还需兼顾总面积；（4）再引入与种群重建，需保证引入点之间距离小于物种的迁移能力。"},{"id":"18.7","t":"集合种群与保护优先序","s":2,"c":"18. 集合种群","x":"保护优先序的判断原则：（1）面积大、生境质量高的斑块优先，因其灭绝率低；（2）距离其他斑块近、位于网络中心的斑块优先，因其定殖率高、可作为传播枢纽；（3）斑块间的\"踏脚石\"（stepping stone）可用于缩短有效距离；（4）对于非平衡集合种群，单纯保护不能逆转衰退，必须同时改善生境质量以提高 c、降低 e。这一原则是\"为什么有些保护区建立了却无法阻止物种消失\"的标准解释。"},{"id":"19.1","t":"最小存活种群的概念","s":3,"c":"19. 最小存活种群与灭绝漩涡","x":"最小存活种群（minimum viable population，MVP）指在给定时间内以给定概率存活的种群最小规模。Shaffer 给出两个常用标准：短期内（100年）以 99% 概率存活，或长期内（1 000 年）以 99% 概率存活。MVP 不是一个固定数字，取决于物种寿命、繁殖力、遗传多样性、环境波动与灾害频率，因此必须逐种估算。"},{"id":"19.2","t":"50/500 法则","s":3,"c":"19. 最小存活种群与灭绝漩涡","x":"Soulé（1980）提出 50/500 法则：短期避免近交衰退需有效种群大小Ne≥50，长期维持遗传变异需 Ne≥500。该法则后被修正为 50/500 之外的更大数值（如某些学者提出 100/1 000 或更高），因为新突变与遗传漂变的长期效应被低估。使用该法则时必须注意它指的是有效种群大小 Ne 而非实际个体数，且 Ne 通常远小于 N。"},{"id":"19.3","t":"种群统计随机性与环境随机性","s":3,"c":"19. 最小存活种群与灭绝漩涡","x":"小种群的灭绝风险来自四类随机性：（1）统计随机性（demographic stochasticity），即个体出生死亡的随机差异，种群越小影响越大；（2）环境随机性（environmental stochasticity），即气候与资源的年际波动，使增长率方差增大；（3）遗传随机性，即近交衰退与遗传漂变导致的适合度下降；（4）灾害随机性（catastrophes），即火灾、台风、疫病等小概率大影响事件。四类随机性的方差叠加决定了灭绝概率。"},{"id":"19.4","t":"灭绝漩涡","s":3,"c":"19. 最小存活种群与灭绝漩涡","x":"灭绝漩涡（extinction vortex）指小种群陷入的一系列正反馈式恶化：种群变小→近交与漂变加剧→遗传多样性下降与有害基因表达→适合度下降（繁殖力、抗病力、幼体存活率降低）→种群更小。同时伴随 Allee 效应（低密度时寻找配偶困难、群体防御失效、传粉不足），使增长率在低密度时进一步降低甚至为负。灭绝漩涡一经启动很难逆转，因此保护的关键是\"在进入漩涡之前干预\"。"},{"id":"19.5","t":"Allee 效应","s":3,"c":"19. 最小存活种群与灭绝漩涡","x":"Allee 效应指种群密度过低时，个体适合度随密度下降而下降的现象，与密度制约的负反馈方向相反。其机制包括：配偶寻找困难、群体捕食警戒失效、群体调节小气候能力下降、传粉者吸引力不足、社会性昆虫群体规模不足。Allee 效应使低密度下的增长率为负，形成\"临界密度\"或\"灭绝阈值\"，逻辑斯蒂模型无法描述这一现象，需在模型中增加 Allee 项。"},{"id":"19.6","t":"种群生存力分析","s":2,"c":"19. 最小存活种群与灭绝漩涡","x":"种群生存力分析（population viability analysis，PVA）是用模型定量评估种群在一定时间内灭绝概率的方法，其输入包括初始种群大小与结构、出生率与死亡率及其方差、灾害频率、迁移率、遗传参数，输出为灭绝概率与最小存活种群。PVA 的价值在于比较不同管理方案的相对效果，局限在于参数不确定性大，故必须做敏感性分析与情景分析。"},{"id":"19.7","t":"小种群保护对策","s":3,"c":"19. 最小存活种群与灭绝漩涡","x":"对策包括：（1）增加生境面积与质量，直接提高 K；（2）建立廊道或人工迁移以增加基因流，缓解近交；（3）迁地保护与人工繁殖，作为遗传资源的\"备份\"；（4）再引入与种群重建，但需保证遗传多样性与当地适应；（5）控制捕食、疾病与入侵种；（6）长期监测，用 PVA 动态调整；（7）保护\"源\"生境而非仅保护个体。这些对策共同服务于一个目标：把 Ne 维持在阈值以上，避免进入灭绝漩涡。第四篇 种间相互作用"},{"id":"20.1","t":"竞争的类型与判断标准","s":3,"c":"20. 种间竞争","x":"种间竞争指两种或多种生物因争夺共同的有限资源（食物、空间、光、养分、水）而相互抑制的现象。按作用方式分为干扰型竞争（直接排斥，如他感作用、攻击、覆盖）与利用型竞争（间接消耗共同资源使对方获取量减少）。按资源性质分为资源竞争与相互干扰竞争。判断是否存在竞争需满足三个条件：资源有限、共同利用、且使用导致任一方适合度下降。"},{"id":"20.2","t":"高斯假说与竞争排斥原理","s":3,"c":"20. 种间竞争","x":"Gause（1934）以双小核草履虫（Paramecium aurelia）与尾草履虫（P. caudatum）混合培养实验发现：两种竞争同一资源时，生长快的一方最终使另一方灭绝。由此提出竞争排斥原理（Gause 假说）：生态位相同的两个物种不能在同一地区长期共存，必然以一方灭绝或生态位分化而告终。该原理的前提是环境稳定、资源有限、无其他因子干扰；在自然界的波动环境中，竞争排斥常被干扰抑制而共存得以维持。"},{"id":"20.3","t":"Lotka-Volterra 竞争模型","s":3,"c":"20. 种间竞争","x":"模型形式为：dN_1/dt=r_1N_1(K_1-N_1-α_{12}N_2)/K_1，dN_2/dt=r_2N_2(K_2-N_2-α_{21}N_1)/K_2，其中 α_{12} 为物种 2 对物种 1 的竞争系数（即 1 个个体 2 相当于多少个个体 1）。四类结果：（1）K_1>K_2/α_{21} 且 K_2<K_1/α_{12}，物种 1 胜；（2）相反则物种 2胜；（3）双方均可侵入对方，出现不稳定共存（取决于初始数量）；（4）双方均不能侵入对方，稳定共存。判别方法可直接比较 K 值与 K/α 的大小关系。条件结果稳定性K1>K2/α21 且 K2<K1/α12物种 1 获胜，物种 2 灭绝稳定K1<K2/α21 且 K2>K1/α12物种 2 获胜，物种 1 灭绝稳定K1>K2/α21 且 K2>K1/α12双方均可侵入，共存不稳定，取决于初始数量K1<K2/α21 且 K2<K1/α12双方均不能侵入，共存稳定"},{"id":"20.4","t":"竞争系数与竞争能力的度量","s":2,"c":"20. 种间竞争","x":"竞争系数 α 表示一个物种个体对另一物种的抑制效应相当于自身个体的倍数，α>1 表示抑制效应大于自身。α 可通过等产量线实验、取代实验（de Wit）或添加系列实验估算。竞争能力的构成包括资源利用效率、生长速率、耐受低资源能力（Tilman 的 R* 理论：R* 最低者在低资源条件下胜出）与干扰能力。R* 理论的优点是把竞争结果与资源水平定量联系，能解释\"施肥改变竞争结果\"的现象。"},{"id":"20.5","t":"生态位分化与资源分割","s":3,"c":"20. 种间竞争","x":"同域共存的近缘种通常通过资源分割降低重叠：MacArthur 的莺类研究显示五种林莺在同一株树上分占不同取食部位；Lack 的达尔文雀研究显示不同物种取食不同大小的种子。分化的维度包括食物类型与粒径、取食高度、活动时间、巢址、微生境。分化程度可用生态位重叠指数定量，一般认为重叠低于0.5~0.6 即可稳定共存（经验值，非普遍规律）。"},{"id":"20.6","t":"竞争排斥的反例与共存条件","s":2,"c":"20. 种间竞争","x":"自然界中生态位明显重叠的物种共存并不少见，解释包括：（1）环境波动与干扰阻止竞争进行到底（干扰假说）；（2）捕食者优先捕食优势竞争者，缓解竞争（Paine 的关键种实验）；（3）空间异质性与斑块动态使\"定殖—竞争权衡\"成立；（4）资源并非持续有限，存在过剩期；（5）中性过程与扩散限制。因此\"竞争排斥\"是趋势而非定律，竞赛中\"生态位重叠必然导致一方灭绝\"是错误的绝对化表述。"},{"id":"20.7","t":"种内竞争与种间竞争的关系","s":2,"c":"20. 种间竞争","x":"种内竞争与种间竞争常同时存在。当种内竞争强于种间竞争时，两个物种可共存并使各自生态位分化（因为个体更易与同种个体争夺相似资源）；反之当种间竞争更强时，则出现排斥。这一\"竞争强度比较\"是理解\"生态位分化为何发生\"的关键，也解释了为何群落中同属物种常表现出更明显的形态差异（性状替换）。竞争结果还受环境梯度影响，形成\"竞争—耐受权衡\"沿梯度替代的格局。"},{"id":"21.1","t":"捕食的概念与类型","s":3,"c":"21. 捕食作用","x":"广义捕食（predation）指一种生物取食另一种生物的部分或全部躯体，包括：食肉（carnivory，捕食者杀死并吃掉猎物）、食草（herbivory，取食植物部分组织）、寄生（parasitism，寄生物生活在宿主体上或体内并消耗其营养而不立即杀死）、拟寄生（parasitoid，寄生于宿主体内并最终杀死宿主，主要见于膜翅目与双翅目）。四类在\"是否立即杀死\"与\"消耗比例\"上形成连续谱，是竞赛分类题的常考点。"},{"id":"21.2","t":"Holling 功能反应","s":3,"c":"21. 捕食作用","x":"功能反应（functional response）指单个捕食者在单位时间内的捕获量随猎物密度的变化，Holling 分为三型：I 型为线性上升至饱和（滤食性动物，无学习行为）；II 型为凸型曲线，上升后逐渐饱和，符合N_a=aT·N/(1+aT_h·N)，其中 a 为攻击率、T_h 为处理时间（无脊椎动物与多数捕食者）；III 型为 S 型曲线，低密度时捕食率低（因猎物难发现或有替代食物、存在学习效应），中密度迅速上升后饱和（脊椎动物、可转换食谱的捕食者）。III 型具有\"低密度避难\"效应，可对被猎物种种群起稳定作用。"},{"id":"21.3","t":"数值反应与总反应","s":3,"c":"21. 捕食作用","x":"数值反应（numerical response）指捕食者自身密度随猎物密度上升而变化（通过迁入或繁殖），二者结合形成总反应。总反应的意义：功能反应与数值反应叠加可能使总捕食压力在中等猎物密度处最高，从而产生\"临界密度\"现象，这是害虫生物防治中\"释放天敌能否奏效\"的理论依据。竞赛常要求根据给定曲线判断是功能反应还是数值反应。"},{"id":"21.4","t":"Lotka-Volterra 捕食者—猎物模型","s":3,"c":"21. 捕食作用","x":"模型形式为：dN/dt=rN-aNP（猎物），dP/dt=baNP-mP（捕食者），其中 a 为攻击率、b 为转化效率、m 为捕食者死亡率。平衡点为 N*=m/(ba)、P*=r/a。模型预言种群数量呈中性环振荡（振幅由初始条件决定），无稳定平衡点。模型的重要推论是：捕食者平衡密度取决于猎物的增长率 r 与攻击率a，猎物平衡密度取决于捕食者的死亡率 m 与转化效率，即\"减少捕食者死亡率会降低猎物平衡数量\"。"},{"id":"21.5","t":"模型的修正与稳定条件","s":2,"c":"21. 捕食作用","x":"实际种群很少表现为中性环，因为存在密度制约与功能反应。修正包括：（1）加入猎物密度制约项（-cN²）使系统获得稳定焦点；（2）使用 Holling II 型功能反应会出现\"悖论富化\"（ paradox of enrichment），即提高环境容纳量反而使系统不稳定、振幅增大；（3）III 型功能反应提供低密度避难，增强稳定性；（4）加入捕食者种内竞争与空间异质性。理解这些修正有助于解释为何实验室的简单系统易振荡而野外系统较稳定。"},{"id":"21.6","t":"最优觅食理论","s":3,"c":"21. 捕食作用","x":"最优觅食理论假定自然选择使觅食行为趋向净能量收益最大化，模型包括：（1）食谱宽度模型（MacArthur 与 Pianka），决策规则是\"当遇到某食物的收益率低于平均收益率时即忽略它\"；（2）边际值定理（Charnov），解释在斑块间的停留时间，最佳离开点是斑块收益率降至生境平均收益率时；（3）中心觅食理论，解释把食物运回巢的装载量决策。理论预言：食物丰富时食谱变窄，食物贫乏时食谱变宽，这一预言已被多例实验证实。"},{"id":"21.7","t":"捕食对群落的影响","s":3,"c":"21. 捕食作用","x":"捕食可通过\"自上而下\"（top-down）控制改变群落结构：Paine（1966）去除潮间带海星 Pisaster 后，贻贝占据空间并排挤其他物种，物种数由 15 种降至 8 种，由此提出关键种（keystone species）概念。捕食还可：（1）抑制优势种、提高多样性；（2）产生\"恐惧效应\"改变猎物行为与生境利用；（3）形成营养级联（trophic cascade），如狼—鹿—植被的三级级联。竞赛中\"移除顶级捕食者后多样性上升还是下降\"取决于优势竞争者是否被释放，多数情况为下降。"},{"id":"22.1","t":"寄生的类型与特征","s":3,"c":"22. 寄生、拟寄生与共生","x":"寄生指一种生物（寄生物）生活在另一种生物（宿主）的体表或体内，从中获取营养并造成损害的关系。按位置分体外寄生与体内寄生；按寄主范围分单主寄生与多主寄生；按寄生程度分专性寄生与兼性寄生；按对象分动物寄生、植物寄生与微生物寄生。寄生物通常具有高度特化的适应：吸器、吸盘、钩、角质层抗消化、生殖系统发达、生活史与宿主同步。寄生关系对宿主有害（+/-），但通常不立即杀死宿主，这与捕食不同。"},{"id":"22.2","t":"寄生对宿主种群的影响","s":3,"c":"22. 寄生、拟寄生与共生","x":"寄生物可显著调节宿主种群密度，是密度制约因子。经典例证包括：（1）澳大利亚引进黏液瘤病毒控制兔种群，短期内死亡率达 90% 以上，随后病毒毒力与兔抗性协同演化至中等水平；（2）爱尔兰马铃薯晚疫病（Phytophthora infestans）导致 1845—1849 年大饥荒；（3）荷兰榆树病由真菌与媒介甲虫共同传播。寄生物还会改变宿主的竞争能力，从而间接影响群落结构。"},{"id":"22.3","t":"植物寄生与半寄生","s":2,"c":"22. 寄生、拟寄生与共生","x":"植物寄生者包括全寄生（无叶绿素，完全依赖宿主，如菟丝子 Cuscuta、列当 Orobanche、蛇菰）与半寄生（有叶绿素可光合，但靠吸器从宿主获取水分与无机盐，如槲寄生、桑寄生）。寄生植物通过吸器与宿主维管束相连，是农业上的重要杂草（向日葵列当、大豆菟丝子）。菌根真菌与植物之间则属互利共生而非寄生，因为双方均有净收益。"},{"id":"22.4","t":"拟寄生及其生物防治应用","s":3,"c":"22. 寄生、拟寄生与共生","x":"拟寄生昆虫（多为膜翅目的姬蜂、茧蜂、小蜂与双翅目的寄蝇）把卵产于宿主体内或体表，幼虫取食宿主组织并最终杀死宿主。其重要特征是\"一寄主一寄生物\"的紧密关系与\"寄生后必致死\"的结局，因此行为上更接近捕食。拟寄生蜂被广泛用于生物防治，如赤眼蜂防治玉米螟、丽蚜小蜂防治粉虱。拟寄生蜂的性比常偏雌（局域配偶竞争），且能调节寄主龄期选择，是行为生态学的经典材料。"},{"id":"22.5","t":"互利共生","s":3,"c":"22. 寄生、拟寄生与共生","x":"互利共生指双方均从关系中获益（+/+），可分为专性（obligate，离开对方不能生存）与兼性（facultative）。典型例证：地衣（真菌与藻类或蓝细菌）、菌根（真菌与植物根）、根瘤（根瘤菌与豆科）、榕树与榕小蜂（专性传粉）、丝兰与丝兰蛾、白蚁与肠道鞭毛虫（分解纤维素）、珊瑚与虫黄藻（提供光合产物，换取庇护与营养）。互利共生的稳定性依赖于\"防止作弊者\"的机制，如宿主对无效共生体的惩罚。"},{"id":"22.6","t":"偏利共生与原始协作","s":2,"c":"22. 寄生、拟寄生与共生","x":"偏利共生（commensalism，+/0）指一方获益、另一方不受影响，如附生植物附生于树干、鮣鱼附着于鲨鱼、鸟类在大型兽类惊起的昆虫中取食、以及动物传播种子（部分情形属互利）。原始协作（protocooperation）指双方均可获益但并非必需，如寄居蟹与海葵、蚂蚁与蚜虫。偏利与互利的界线在于是否可证明对方也获益，实验中需通过去除一方观察另一方适合度变化来判定。"},{"id":"22.7","t":"共生关系的进化与作弊者","s":2,"c":"22. 寄生、拟寄生与共生","x":"互利共生在进化上易被作弊者利用（作弊者获益但不回报），因此稳定共生需要：（1）伙伴的垂直传播（如蚜虫与 Buchnera 细菌），使双方利益绑定；（2）宿主对无效伙伴的识别与惩罚（如豆科植物对不固氮根瘤菌降低供氧）；（3）空间隔离与结构约束（如共生体被包裹在特化结构中）。这一理论解释了为何许多共生关系表现出高度专一性，也解释了为何人为接种低效菌株常导致共生失败。"},{"id":"23.1","t":"协同进化的概念与类型","s":3,"c":"23. 协同进化与防御","x":"协同进化（coevolution）指两个或多个物种在进化过程中相互作用、相互选择、彼此适应的过程，由 Ehrlich 与 Raven（1964）在研究蝶类与植物关系时系统提出。类型包括：一对一协同进化（如榕树—榕小蜂）、扩散协同进化（diffuse coevolution，多物种参与，如整个植食者群落与植物防御体系）、以及军备竞赛式协同进化（antagonistic coevolution）。"},{"id":"23.2","t":"红皇后假说","s":3,"c":"23. 协同进化与防御","x":"Van Valen（1973）提出红皇后假说：在持续对抗的协同进化中，每个物种都必须不断进化才能维持相对适应度，正如《爱丽丝镜中奇遇》中红皇后所说\"必须拼命奔跑才能留在原地\"。该假说解释了有性生殖的维持（重组产生新基因型以应对寄生物）、免疫系统的多样性以及毒性—抗性军备竞赛的持续。竞赛中\"为什么有性生殖在无性生殖更高效的情况下仍普遍存在\"的标准答案之一即红皇后假说。"},{"id":"23.3","t":"植物的组成型防御","s":3,"c":"23. 协同进化与防御","x":"组成型防御指植物持续存在的防御结构与化学物质。物理防御包括刺、皮刺、蜡质、硅质细胞、叶硬度、茸毛。化学防御包括：（1）生物碱（烟碱、咖啡因、奎宁），作用于神经系统；（2）萜类与挥发油（薄荷醇、松节油），干扰代谢与信息传递；（3）酚类与单宁，与蛋白质结合降低消化率（缩合单宁在瘤胃中可\"鞣制\"蛋白质）；（4）氰苷（苦杏仁苷），水解后释放 HCN；（5）芥子油苷（十字花科），水解为异硫氰酸盐；（6）蛋白酶抑制剂，抑制昆虫消化酶。代表物质作用机制代表植物含氮次生代谢物防御类型生物碱、氰苷、非蛋白氨基酸神经毒性、抑制呼吸链烟草、夹竹桃、苦杏仁萜类单萜、倍半萜、精油干扰代谢、驱避、毒杀薄荷、桉树、松树酚类单宁、木质素、黄酮与蛋白结合降低消化率栎树、茶树含硫化合物芥子油苷、蒜氨酸水解产异硫氰酸盐、大蒜素十字花科、大蒜蛋白酶抑制剂胰蛋白酶抑制剂抑制昆虫肠道蛋白酶豆类、番茄"},{"id":"23.4","t":"诱导型防御与信号转导","s":3,"c":"23. 协同进化与防御","x":"诱导型防御指植物在遭受取食或病原侵染后新合成的防御物质，其优点是节省成本、避免自毒。信号通路主要有三条：茉莉酸（JA）途径响应咀嚼式昆虫与机械损伤，水杨酸（SA）途径响应病原与刺吸式昆虫，乙烯（ET）途径参与协同调节。诱导防御具有\"预警\"特征：损伤部位释放的挥发物（如绿叶挥发物 GLV）可诱导邻近植株或同株其他叶片提前启动防御。诱导的代价是存在时滞，因此诱导型防御多见于可预测的、重复发生的取食压力下。"},{"id":"23.5","t":"动物的防御适应","s":3,"c":"23. 协同进化与防御","x":"动物防御包括：（1）初级防御，即无论是否遭遇捕食者都存在的防御，如保护色、警戒色、拟态、坚硬外壳、棘刺、毒素、群居；（2）次级防御，即遭遇捕食者时才表现的行为，如逃跑、装死、威吓、喷射、自割、围成一圈。警戒色（aposematism）以鲜艳色彩与毒性相联，需捕食者通过学习识别，因此常与群居相伴以加速学习。贝次拟态（Batesian mimicry）指无毒物种模仿有毒物种（欺骗型）；缪勒拟态（Müllerian mimicry）指多个有毒物种相互模仿（共享警戒信号，双方均获益）。"},{"id":"23.6","t":"化学防御的代价与权衡","s":2,"c":"23. 协同进化与防御","x":"防御物质的生产需要消耗碳、氮与能量，因此在资源充足、取食压力小时，高防御品系生长较慢。这种\"生长—防御权衡\"解释了为何植物防御水平存在地理变异（如高纬度或贫瘠生境的植物防御更强）与个体变异（幼叶防御强、老叶防御弱，因幼叶价值高）。资源分配假说（carbon-nutrient balance hypothesis）与生长分化平衡假说（growth-differentiation balance hypothesis）是解释该权衡的两个主要理论。"},{"id":"23.7","t":"协同进化的证据与检验","s":2,"c":"23. 协同进化与防御","x":"检验协同进化的方法包括：（1）系统发育比对，检验双方的系统树是否一致（如榕树与榕小蜂的共成种）；（2）地理镶嵌假说（geographic mosaic theory of coevolution），预测不同地区双方的选择强度与结果不同，形成\"热点\"与\"冷点\"；（3）交互移植实验，检验本地植物—本地植食者的相互适应程度（本地配对常表现更强的相互适应）；（4）分子证据，检测防御基因与解毒基因的正选择信号。竞赛中常以\"某地引入天敌后效果不佳\"考查本地适应与地理镶嵌概念。"},{"id":"24.1","t":"种间关系的六种基本类型","s":3,"c":"24. 种间关系的判断与实验设计","x":"按相互作用对双方适合度的影响（+ 有利、- 有害、0 无影响），种间关系可分为六类：竞争（-/-）、捕食（+/-）、寄生（+/-）、互利共生（+/+）、偏利共生（+/0）、偏害作用（-/0，如他感作用）。判断关系类型的关键是\"两个方向的净效应\"，而不是\"是否接触\"：两种生物接触不一定存在相互作用，两种生物不接触也可能通过资源间接作用。竞赛中常以\"下列实例属于何种关系\"考查对净效应的判断。关系类型物种 1物种 2典型实例竞争--两种草履虫争夺食物、作物与杂草争光捕食+-狼与兔、瓢虫与蚜虫寄生+-菟丝子与大豆、蛔虫与人、寄生蜂与毛虫互利共生++地衣、菌根、榕树与榕小蜂偏利共生+附生植物与乔木、鮣鱼与鲨鱼偏害作用-黑胡桃分泌胡桃醌抑制其他植物"},{"id":"24.2","t":"判断种间关系的实验方法","s":3,"c":"24. 种间关系的判断与实验设计","x":"（1）去除实验：去除一方，观察另一方的密度、存活率或生长是否改变，若改变则存在相互作用的方向与强度；（2）添加实验：人工增加一方密度，观察另一方响应；（3）围栏与半透膜实验：允许某些通路（如根系、菌丝、化学物质）而阻断其他通路，用于分离竞争与化学作用；（4）同位素标记与示踪：追踪物质流向以确认寄生或共生关系；（5）交叉移植与共同培养：Gause 式的实验室混合培养可直接观察竞争结果。"},{"id":"24.3","t":"竞争与捕食的区分难点","s":2,"c":"24. 种间关系的判断与实验设计","x":"野外观察到的\"一方减少\"可能来自捕食、寄生或竞争，区分方法是：（1）看是否有直接取食证据（胃含物、咬痕、寄生体）；（2）去除实验的响应形式，竞争导致的减少通常缓慢且与密度相关，捕食导致的减少常呈突发性；（3）是否可通过补充资源逆转，若补充资源即缓解则支持竞争；（4）是否出现行为回避（捕食风险下的生境转移）。这一区分是\"取食限制与捕食限制之争\"的方法论核心。"},{"id":"24.4","t":"竞争系数的实验估算","s":2,"c":"24. 种间关系的判断与实验设计","x":"竞争系数 α 的经典估算方法是 de Wit 取代系列实验：以不同比例混合两种植物（如 100:0、75:25、50:50、25:75、0:100），测定总产量与各组分产量，通过等产量线（相对产量总和 RYT）判断：RYT=1 表示资源互补无竞争，RYT<1 表示竞争，RYT>1 表示互利或促进。另一种方法是添加系列实验，比较单种与混种在相同总密度下的表现，从而计算竞争重要度（competitive importance）。"},{"id":"24.5","t":"Gause 式实验的设计要点","s":3,"c":"24. 种间关系的判断与实验设计","x":"以微生物或小型动物做竞争实验时须注意：（1）控制初始密度与比例，因为 Lotka-Volterra 竞争的结果依赖于初始条件（尤其在不稳定共存情形）；（2）使用相同培养基与更新速率，避免资源随时间改变导致结果漂移；（3）设置单种对照以确定各自的 K 与 r；（4）延长观察时间，短期结果可能只是暂时的优势而非最终排斥；（5）区分\"竞争排斥\"与\"一方未被引入\"这两种情形，需做双向去除验证。"},{"id":"24.6","t":"野外实验的局限与外推风险","s":2,"c":"24. 种间关系的判断与实验设计","x":"野外实验的外推风险包括：（1）尺度不匹配，小样方结果难以外推到景观尺度；（2）时间不足，慢过程（演替、土壤变化）在短期实验中不显现；（3）围栏与处理本身产生人为效应（围栏阻碍迁移、改变微气候）；（4）重复数受限导致统计功效不足；（5）单点研究的地理特殊性。因此生态学结论通常需要\"多地点重复 + 多方法互证\"，这也是荟萃分析（meta-analysis）在生态学中日益重要的原因。"},{"id":"24.7","t":"从相关到因果的推断框架","s":2,"c":"24. 种间关系的判断与实验设计","x":"判断\"是否存在相互作用\"的推断框架可归纳为四步：一是建立格局（相关），二是提出机制假说，三是设计可区分的实验（关键是用不同假说做出不同的预言），四是多地点多时间验证。典型误区是把\"共同出现的物种\"直接判定为互利、\"互不重叠的分布\"直接判定为竞争排斥，因为二者也可能仅由相同或不同的生境需求造成。竞赛中\"以下结论是否成立\"类题目，答案常指向\"相关不能证明因果\"。第五篇 群落生态学"},{"id":"25.1","t":"生物群落的概念","s":3,"c":"25. 群落概念与基本特征","x":"生物群落（community）指在一定时间内居住在一定区域或生境中的各种生物种群的集合，包括植物、动物与微生物。群落是生态系统中的生物成分，其研究以物种组成为入口、以结构与动态为核心。群落概念包含两个要点：一是\"多种种群的集合\"而非单个种群，二是\"具有一定结构与功能\"而非随机堆集。李博《生态学》第六章把群落概念与\"群落的基本特征\"\"群落的性质\"并列讨论，强调这两点。"},{"id":"25.2","t":"群落的基本特征","s":3,"c":"25. 群落概念与基本特征","x":"群落具有六个基本特征：（1）具有一定的物种组成，包括物种的数目、种类与比例，这是群落最本质的特征；（2）具有一定的结构，包括垂直结构、水平结构与时间结构；（3）形成群落环境，即群落内部的小气候与土壤条件被生物改造；（4）具有一定的动态，包括季节变化、年际变化与演替；（5）具有一定的分布范围与边界；（6）具有边界的过渡性，群落之间常以交错区相连而非截然分开。"},{"id":"25.3","t":"机体论与个体论之争","s":3,"c":"25. 群落概念与基本特征","x":"机体论（Clements）认为群落是一个有组织的\"超有机体\"，具有明确的边界、发育阶段与顶极状态，物种间高度协同，因而可像物种一样分类。个体论（Gleason）认为群落只是个体分布沿环境梯度的偶然叠加，物种各自独立响应环境，因此群落无明确边界、无\"顶极\"、只有连续变化的植被 continuum。现代观点倾向于\"连续体\"立场：在环境渐变处植被连续，在环境突变处（如土壤界线、水陆交界）则边界清晰，二者并不矛盾。"},{"id":"25.4","t":"群落的性质与尺度依赖","s":2,"c":"25. 群落概念与基本特征","x":"群落的\"实体性\"取决于尺度：在细尺度（如 1 m² 样方）内，物种间相互作用明显、结构可辨；在粗尺度上，群落更多表现为环境梯度的映射。因此\"群落是否为真实存在的实体\"这一争论的答案应加尺度限定。群落的范围由研究者依研究目的界定（如森林群落、林下草本群落），这种\"人为界定性\"是群落研究与种群研究的显著差别。"},{"id":"25.5","t":"群落的命名与识别","s":1,"c":"25. 群落概念与基本特征","x":"群落通常以优势种或建群种命名，如\"马尾松—木荷—芒萁群落\"（乔木层优势种—亚层优势种—草本层优势种），或按植被型命名为\"亚热带常绿阔叶林\"。识别群落的操作步骤为：确定边界、设置样方、统计种类组成与数量特征、确定优势种、按分类系统归类。命名规则的统一是群落分类可比较的前提。"},{"id":"25.6","t":"群落与生态系统的区别","s":3,"c":"25. 群落概念与基本特征","x":"群落仅指生物成分（植物、动物、微生物的集合），生态系统则包括生物成分与非生物环境（土壤、大气、水）并强调能量流动与物质循环。二者的研究侧重不同：群落生态学关注物种组成、结构与多样性，生态系统生态学关注功能与过程（生产力、分解、循环）。同一片森林既是群落研究的对象，也是生态系统研究的对象，但问题不同、方法不同、尺度不同。竞赛中混淆这两个概念是常见失分点。"},{"id":"25.7","t":"群落的物种饱和与群落构建","s":2,"c":"25. 群落概念与基本特征","x":"群落构建（community assembly）研究\"哪些物种能进入并留在群落中\"，涉及四个过程：扩散（区域物种库的供给）、环境筛选（abiotic filtering，只有耐受当地条件的物种能存活）、生物相互作用（竞争、捕食、共生决定相对多度）、以及随机漂变。四过程的相对重要性可用 β 多样性分解、系统发育结构（亲缘聚集表示环境筛选，亲缘发散表示竞争排斥）等方法推断。"},{"id":"26.1","t":"种类组成的性质分析","s":3,"c":"26. 物种组成与优势种","x":"性质分析指对群落物种进行区系成分、科属组成、地理成分、生活型与生态类群的统计，目的是揭示群落的区系来源与性质。例如热带雨林的科属组成以樟科、桑科、大戟科等为主且含大量特有科，而北方针叶林以松科、桦木科为主。地理成分分析（如泛热带成分、北温带成分）可反映历史渊源，生活型谱可反映气候。性质分析不涉及数量，属定性描述。"},{"id":"26.2","t":"种类组成的数量特征","s":3,"c":"26. 物种组成与优势种","x":"数量特征包括：（1）多度（abundance），个体数目，可用 Drude 多度级（Soc、Cop3、Cop2、Cop1、Sp、Sol、Un）表示；（2）密度，单位面积个体数；（3）盖度（coverage），分投影盖度与基部盖度，用百分数表示；（4）频度（frequency），某物种出现的样方数占全部样方数的比例，Raunkiaer 频度定律指出 A（1%~20%）>B（21%~40%）>C（41%~60%）>D（61%~80%）<E（81%~100%）；（5）显著度（dominance），以胸高断面积表示；（6）高度与体积。"},{"id":"26.3","t":"优势种与建群种","s":3,"c":"26. 物种组成与优势种","x":"优势种（dominant species）指群落中数量最多、盖度最大、对群落环境影响最显著的物种；建群种（ edificator）指在优势层中起主要建造作用的物种，其存在决定群落的外貌与结构。一个群落可有多层优势种（乔木层优势种、灌木层优势种、草本层优势种），但建群种通常只有一个或少数几个。伴生种指数量较少但常见且不决定群落性质的物种，偶见种指出现频率很低的物种。"},{"id":"26.4","t":"重要值及其计算","s":3,"c":"26. 物种组成与优势种","x":"重要值（importance value，IV）是综合密度、频度与优势度的相对指标，用于确定优势种。常用公式为 IV=（相对密度+相对频度+相对优势度）/3，其中相对密度=该种密度/全部种密度之和×100%，相对频度=该种频度/全部种频度之和×100%，相对优势度=该种胸高断面积/全部种胸高断面积之和×100%。草本群落中常以相对盖度代替相对优势度。IV 最高者即为该层的优势种，IV 之和为 300%（若三项各占 100%）。"},{"id":"26.5","t":"物种多样性指数","s":3,"c":"26. 物种组成与优势种","x":"Shannon-Wiener 指数：H'=-ΣP_i·lnP_i（P_i 为第 i 种的个体数或生物量比例），值域一般 0~5，越大表示多样性越高。Simpson 指数：D=1-ΣP_i²（Gini-Simpson），表示随机取两个个体属于不同种的概率；其倒数 1/ΣP_i²称 Simpson 多样性指数。均匀度指数：Pielou J=H'/lnS（S 为物种数），取值 0~1。三者关系：H' 与 D 同时受物种丰富度与均匀度影响，物种丰富度（S）只反映数目，因此竞赛题常要求\"判断多样性高低须同时看 S 与均匀度\"。指数物种丰富度 S公式含义特点最直观忽略多度分布Shannon 指数 H'物种数目-ΣP_i lnP_i信息熵，不确定性对稀有种较敏感Simpson 指数 D 1-ΣP_i²随机两体异种概率对优势种较敏感Pielou 均匀度 J H'/lnS多度分配的均匀程度取值 0~1"},{"id":"26.6","t":"种间关联","s":2,"c":"26. 物种组成与优势种","x":"种间关联指两个物种在样方中共同出现或相互排斥的倾向，用 2×2 列联表与 χ² 检验判断：a（两者均出现）、b（仅甲出现）、c（仅乙出现）、d（两者均不出现）。正关联（a、d 偏多）暗示相互依存或共同的生境需求，负关联（b、c 偏多）暗示竞争或不同的生境需求。注意关联不等于因果关系，正关联可能仅由共同的生境偏好造成，需实验验证。"},{"id":"26.7","t":"常见种的判定与稀有种的意义","s":2,"c":"26. 物种组成与优势种","x":"群落中物种多度常呈对数正态分布或\"少种多量\"的格局，即少数物种多度极高、多数物种多度极低。稀有种虽然个体数少，但对多样性指数的贡献不可忽略，且常是特有种与保护对象。稀有种的生态功能尚有争议：有研究认为稀有种功能冗余，也有研究显示稀有种在环境变化后可能成为优势种（\"稀有种保险\"）。因此在保护实践中不能仅以多度判定保护价值。"},{"id":"27.1","t":"群落的垂直结构","s":3,"c":"27. 群落结构","x":"垂直结构指群落中不同物种在垂直方向上的分层现象，是群落最重要的结构特征。森林群落的典型分层为：乔木层（可再分第一、第二乔木亚层）、灌木层、草本层、地被层（苔藓、地衣），地下部分亦有根系分层。分层的生态意义是提高光能与土壤资源利用效率、降低竞争强度、创造多样微生境。层片（synusia）指由同一生活型或相似生态需求的物种组成的结构单元，是分层的组成成分。"},{"id":"27.2","t":"成层现象的形成原因","s":3,"c":"27. 群落结构","x":"成层现象的根本动因是光在冠层中的指数衰减（I=I_0·e^{-kL}），使不同高度的光强差异可达数十倍。植物依光需求分层：上层为阳生植物、中层为耐阴植物、下层为阴生植物。动物也随之分层：林冠层鸟类与昆虫、树干层啄木鸟与树栖兽、地面层雉类与鼠类、土壤层线虫与蚯蚓。水生群落的成层表现为浮游植物在上层、浮游动物有昼夜垂直移动、底栖生物在底部，且受光、温、氧的垂直梯度控制。"},{"id":"27.3","t":"群落的水平结构","s":2,"c":"27. 群落结构","x":"水平结构指群落在水平方向上的镶嵌性，表现为斑块（patch）与斑块间的过渡。成因包括：（1）地形起伏导致的水分与养分差异；（2）土壤性质的局部变化；（3）生物因素，如树倒形成林窗（gap）、动物穴居改变土壤、克隆植物的斑块状扩张、他感作用形成\"抑制环\"。林窗动态（gap dynamics）是森林维持多样性的重要机制，林窗大小决定更新树种的组成。"},{"id":"27.4","t":"群落的时间结构","s":3,"c":"27. 群落结构","x":"时间结构指群落结构与外貌随时间的规律变化，最典型的是季相（aspect）：温带落叶林春季萌发、夏季郁闭、秋季落叶、冬季休眠，各季外貌迥异；草原的季相变化表现为不同季节的优势种更替。动物的时间结构表现为候鸟的季节迁入迁出、昆虫的世代更替、以及昼夜活动的分化。时间结构的存在使同一空间在不同时间可被不同物种利用，从而提高整体资源利用效率。"},{"id":"27.5","t":"群落外貌与生活型谱","s":2,"c":"27. 群落结构","x":"群落外貌由优势种的生活型、叶型（阔叶、针叶、革质叶、肉质叶）、叶面积与高度决定。Raunkiaer 生活型谱是描述外貌的定量方法，以各类生活型所占百分比表示。热带雨林高位芽植物占 60% 以上、叶大而常绿、具板根与气生根；荒漠以一年生与地面芽为主、叶小而肉质；苔原以地面芽与隐芽为主、植株矮小垫状。外貌是群落分类的重要依据（如\"常绿阔叶林\"即以外貌命名）。"},{"id":"27.6","t":"群落交错区与边缘效应","s":3,"c":"27. 群落结构","x":"群落交错区（ecotone）指两个或多个群落之间的过渡带，其宽度可从数米到数公里。边缘效应（edge effect）指交错区中物种数目与个体密度高于相邻群落的趋势，成因包括生境异质性高、两群落物种重叠、以及边缘提供额外资源。经典例证是森林与农田交界处鸟类与昆虫多样性升高。但边缘效应并非普遍正效应：对内部种而言，边缘意味着更高的捕食风险、更强的风与光照胁迫，故\"边缘效应总是提高多样性\"是错误的绝对化表述。"},{"id":"27.7","t":"影响群落结构的因素","s":2,"c":"27. 群落结构","x":"主要因素包括：（1）生物因素，如竞争、捕食、共生决定相对多度与分层；（2）干扰，中等强度干扰（中间干扰假说，Connell 1978）可维持最高多样性，因为既阻止竞争排斥又不过度清除生物量；（3）空间异质性，异质性越高微生境越多，多样性越高；（4）岛屿面积与隔离度；（5）环境梯度与胁迫。这些因素常交互作用，因此同一群落在不同年份的结构可能有明显差异。"},{"id":"28.1","t":"生物多样性的三个层次","s":3,"c":"28. 生物多样性与多样性指数","x":"生物多样性包括遗传多样性（种内基因与基因型变异）、物种多样性（群落或区域内物种的丰富度与均匀度）、生态系统多样性（生境、生物群落与生态过程的多样性）。三个层次相互关联：遗传多样性是物种适应与进化的基础，物种多样性是生态系统功能的载体，生态系统多样性提供生境异质性。部分文献还加入\"景观多样性\"作为第四层次。竞赛中常以\"三个层次\"作为简答题的固定答题框架。"},{"id":"28.2","t":"α、β、γ 多样性","s":3,"c":"28. 生物多样性与多样性指数","x":"α 多样性指某一特定群落或生境内的物种多样性（生境内多样性）；β 多样性指不同群落之间物种组成的差异程度（生境间多样性，反映环境梯度与生境异质性）；γ 多样性指一个大区域（如一个岛屿、一个省）的总物种多样性。三者关系常用 Whittaker 公式表达：β=γ/ᾱ（ᾱ 为各群落平均 α 多样性），或 β=(S/ᾱ)-1。理解要点：γ 多样性高可以由 α 高造成，也可以由 β 高造成，因此保护策略不同（前者保护单点，后者保护生境异质性）。类型含义常用测度保护含义α 多样性生境内物种多样性Shannon、Simpson、丰富度保护高质量单点生境β 多样性生境间物种更替程度β=γ/ᾱ、(S/ᾱ)-1、Jaccard 距离保护生境异质性与梯度γ 多样性区域总物种多样性区域物种数保护大尺度物种库"},{"id":"28.3","t":"Shannon 与 Simpson 指数的计算与比较","s":3,"c":"28. 生物多样性与多样性指数","x":"设群落有 S 个物种，第 i 种个体数占总数比例为 P_i。Shannon 指数 H'=ΣP_i·lnP_i；若用 log₂ 则单位为 bit。Simpson 指数 D=1-ΣP_i²。举例：若两群落 S 相同，一个各物种个体数相等（P_i 均为 0.25），另一个一个种占0.9、其余三种共占 0.1，则前者 H'=1.386、D=0.75，后者 H'≈0.44、D≈0.19，说明均匀度对两指数影响巨大。Shannon 对稀有种变化较敏感，Simpson 对优势种变化较敏感，这是\"同一数据不同指数给出不同排序\"的原因。"},{"id":"28.4","t":"物种多样性的空间梯度","s":3,"c":"28. 生物多样性与多样性指数","x":"主要梯度包括：纬度梯度（热带最高，向极地递减，是陆地和海洋中最普遍的格局）、海拔梯度（常呈中海拔最高的单峰格局，因低海拔干热、高海拔低温）、水深梯度（浅海最高，深海降低）、以及半岛效应与面积效应。梯度成因的假说包括：（1）时间假说，热带群落历史悠久、演化时间长；（2）面积假说，热带面积大、种群大、灭绝率低；（3）生产力假说，能量输入高可支持更多物种；（4）气候稳定假说，稳定环境减少灭绝；（5）中间干扰假说；（6）捕食假说，热带捕食压力大抑制竞争排斥。"},{"id":"28.5","t":"种—面积关系","s":3,"c":"28. 生物多样性与多样性指数","x":"物种数与面积的关系常表示为 S=cAz，取对数得 lgS=lgc+z·lgA，即双对数图上为直线。z 值的经验范围：大陆内部约 0.12~0.17，岛屿约 0.25~0.35。z 值的意义在于可预测生境丧失导致的物种丧失：若 z=0.25，生境面积减少90%，则物种数降至原来的 0.10.25≈56%，即丧失约 44% 的物种。这一估算被广泛用于评估森林砍伐与栖息地破碎化的后果。"},{"id":"28.6","t":"多样性的测度与取样问题","s":2,"c":"28. 生物多样性与多样性指数","x":"多样性测度依赖取样：样方面积不足会低估 S 与 H'，因此需先确定最小表现面积。为消除取样强度差异，常用稀疏化（rarefaction）曲线或外推估计（Chao1、Jackknife）比较不同样本的多样性。此外，个体数计数对体型差异大的类群不公平，故对昆虫等常用生物量或能量替代个体数，并可采用 Hill数（q=0 为 S、q=1 为 e^{H'}、q=2 为 1/D）统一量纲。"},{"id":"28.7","t":"多样性与生态系统功能","s":2,"c":"28. 生物多样性与多样性指数","x":"多样性与生态系统功能（生产力、稳定性、养分循环）的关系存在三种假说：冗余假说（功能冗余，物种数超过一定值后功能饱和，故少数物种丧失不影响功能）、铆钉假说（每个物种都是\"铆钉\"，丧失任一都会削弱功能）、特有种假说（功能主要由少数关键种决定）。大量草地实验（如 Cedar Creek 的BioDIV）显示生产力随物种数增加而上升且趋于饱和，同时多样性提高时间稳定性（\"保险效应\"），因此主流观点支持\"多样性对功能有正效应但存在饱和\"。"},{"id":"29.1","t":"演替的概念与基本类型","s":3,"c":"29. 群落演替","x":"演替（succession）指某一地段上一个群落被另一个群落依次替代的过程，是群落动态中最重要的形式。按起始条件分原生演替（primary succession，始于无植被、无土壤的裸地，如裸岩、沙丘、冰川退缩地、火山熔岩）与次生演替（secondary succession，始于原有植被被破坏但土壤与种子库尚存的地段，如火烧迹地、采伐迹地、弃耕地）。按基质分旱生演替系列与水生演替系列；按方向分进展演替与逆行演替。"},{"id":"29.2","t":"原生演替的典型系列","s":3,"c":"29. 群落演替","x":"旱生演替系列（裸岩）：地衣阶段（壳状地衣→叶状地衣）→苔藓阶段→草本植物阶段（一年生→多年生）→灌木阶段→乔木阶段（先锋树种→顶极树种），全程需数百年至千年。水生演替系列（湖泊）：裸底阶段→沉水植物阶段（眼子菜、金鱼藻）→浮叶根生植物阶段（睡莲）→挺水植物阶段（芦苇、香蒲）→湿生草本阶段→木本植物阶段，湖泊逐渐填塞、沼泽化并最终成林。沙丘演替以耐埋植物（如沙草、柳）为先锋。"},{"id":"29.3","t":"次生演替的特点","s":3,"c":"29. 群落演替","x":"次生演替起点已有土壤、种子库与部分繁殖体，因此速度远快于原生演替：弃耕地演替一般 1~2 年为一年生杂草、3~10 年为多年生草本、10~30 年为灌木、30~100 年为乔木，形成森林可能需 100~200 年。次生演替常具有\"多途径\"特征，即同一地段可沿不同途径恢复（取决于繁殖体来源、土地利用历史与干扰类型），因此演替不是单一确定的路线。"},{"id":"29.4","t":"演替顶极的三种学说","s":3,"c":"29. 群落演替","x":"（1）单元顶极学说（Clements）：在同一气候区内，演替最终都达到同一个气候顶极（climatic climax），该顶极由气候唯一决定，前顶极、后顶极、亚顶极都是偏离。（2）多元顶极学说（Tansley）：顶极可有多条路径与多个终点，气候顶极之外还有土壤顶极、地形顶极、火顶极等，因为局部因子可使演替停留在非气候顶极状态。（3）顶极格局假说（Whittaker）：顶极不是离散的类型，而是沿环境梯度的连续格局（climax pattern），各顶极类型在空间上渐变过渡。三者的区别在于\"顶极是单一还是多元\"\"是离散类型还是连续格局\"。单元顶极论学说提出者Clements多元顶极论顶极格局假说核心观点对顶极的理解气候唯一决定，最终汇于一个气候顶极单一、离散Tansley土壤、地形、火等可形成多种顶极多个、离散Whittaker顶极沿环境梯度连续变化连续、格局化"},{"id":"29.5","t":"控制演替的因素","s":3,"c":"29. 群落演替","x":"控制演替的五类因素：（1）植物繁殖体的迁移、散布与动物活动性，决定谁能到达；（2）群落内部环境的变化，如光照减弱、土壤加厚，使后来的物种更有利；（3）种内与种间关系的改变，如竞争排斥、捕食与共生；（4）外界环境条件的变化，如气候变迁、河流改道、海平面上升；（5）人类活动，包括采伐、放牧、火烧、开垦、引种与污染。人类活动可加速、延缓或改变演替方向，是当代最重要的演替驱动力。"},{"id":"29.6","t":"演替过程中的功能变化","s":2,"c":"29. 群落演替","x":"随演替进行，群落的功能指标呈现规律变化：生物量与现存量增加、净生产率先升后降（在演替中期最高）、总生产量与呼吸量之比（P/R）由大于 1趋于 1、物种多样性先升后略降、养分循环由开放（流失多）转向闭合（循环紧密）、土壤有机质与持水力增加、食物链由简单趋向复杂。这些趋势构成\"生态系统发育\"的判据，可用于评价恢复工程的成功程度。"},{"id":"29.7","t":"演替方向的判定与逆行演替","s":2,"c":"29. 群落演替","x":"判断演替方向（进展或逆行）的指标包括：物种多样性变化、生物量与盖度变化、土壤肥力变化、群落结构复杂化程度、以及乡土种与外来种的比例。逆行演替指在过度放牧、反复火烧、严重污染等强干扰下，群落由高级阶段退向低级阶段（如草原退化至荒漠），其本质是干扰强度超过了系统的恢复力。恢复生态学的目标即通过消除干扰与人工辅助使逆行演替转为进展演替。"},{"id":"30.1","t":"演替的三种机制模型","s":3,"c":"30. 演替机制与岛屿生物地理学","x":"Connell 与 Slatyer（1977）提出三种演替机制模型：（1）促进模型（facilitation），早期物种改变环境使之更适合后来者，后来者依赖早期物种才能定居，如固氮植物改良土壤、地衣分解岩石成土；（2）抑制模型（inhibition），早期物种抑制后来者，演替能否推进取决于干扰是否创造空缺，如克隆草本占据空间排斥木本；（3）耐受模型（tolerance），早期物种对后来者既无促进也无抑制，后来者凭更强的资源利用能力在成熟群落中直接定殖并取代。三种模型并非互斥，同一演替过程不同阶段可分别以不同机制为主。模型早期物种对后来者的作用演替的动力典型情形促进有利，改善环境早期物种创造条件裸岩→地衣→苔藓→草本抑制有害，阻碍定居干扰创造空缺克隆草本或密集灌木占位耐受中性，无显著影响竞争能力差异成熟林中耐阴树种直接更新"},{"id":"30.2","t":"三种模型的判别方法","s":2,"c":"30. 演替机制与岛屿生物地理学","x":"判别方法包括：（1）去除实验，去除早期物种后观察后来者能否定居，若不能定居支持促进模型，若能则不支持；（2）移植实验，把后来者种子直接播入早期群落，观察萌发与存活；（3）时间序列观测，追踪物种替代与实际环境变化的时间关系。判别时要区分\"相关\"与\"因果\"：演替中环境改善与物种替代常同时发生，需实验分离。"},{"id":"30.3","t":"岛屿生物地理学理论","s":3,"c":"30. 演替机制与岛屿生物地理学","x":"MacArthur 与 Wilson（1967）提出：岛屿上的物种数取决于新物种的定殖率与已有物种的灭绝率的动态平衡。定殖率随岛上物种数增加而下降（物种库被逐渐\"用完\"），灭绝率随物种数增加而上升（竞争加剧、种群变小），两曲线交点即平衡物种数 S*。推论：（1）面积效应，大岛灭绝率低，故 S* 高；（2）距离效应，近岛定殖率高，故 S* 高；（3） turnover，即便 S 稳定，物种组成仍在不断更替。"},{"id":"30.4","t":"平衡模型的数学表达与检验","s":2,"c":"30. 演替机制与岛屿生物地理学","x":"平衡种数可写作 S*=cAz 形式的经验关系，或由定殖率 I=(P-S)λ 与灭绝率E=Sμ 得 S*=λP/(λ+μ)，其中 P 为物种库大小、λ 为单位时间定殖概率、μ 为灭绝概率。检验方法包括：红树林小岛灭菌后重定殖实验（Wilson 与Simberloff 的佛罗里达红树林岛实验）、火山岛（Krakatau）重建观测、以及自然岛屿的种数与面积回归分析。检验普遍支持面积与距离效应的方向，但turnover 速率常低于理论预期。"},{"id":"30.5","t":"岛屿理论在保护区设计中的应用","s":3,"c":"30. 演替机制与岛屿生物地理学","x":"应用原则：（1）面积越大越好，因大保护区可容纳更多物种与更大种群；（2）形状越接近圆形越好，因同样的面积下圆形边缘最短、边缘效应最小；（3）多个保护区优于单个同等面积保护区（在无法设大保护区时），因分散可降低一次性灾害风险；（4）保护区之间应设廊道以维持迁移；（5）保护区应尽量靠近物种源区。SLOSS 争论（Single Large Or Several Small）至今未有定论：大保护区利于内部种与大型动物，小保护区集合可覆盖更多生境类型，实际规划需依类群而定。"},{"id":"30.6","t":"岛屿理论对生境破碎化的启示","s":3,"c":"30. 演替机制与岛屿生物地理学","x":"把生境斑块视为\"陆地岛屿\"，则破碎化的后果可预测：斑块面积减小使灭绝率上升（种—面积关系）、隔离度增加使定殖率下降、边缘比例上升使边缘效应加剧、廊道缺失使迁移受阻。这些推论共同解释了\"为何破碎化生境的物种数在数十年内持续下降\"，也解释了\"灭绝债务\"（extinction debt）概念，即生境丧失后物种的消失存在时间滞后。"},{"id":"30.7","t":"平衡说与非平衡说","s":2,"c":"30. 演替机制与岛屿生物地理学","x":"平衡说认为群落结构由竞争等生物相互作用维持于稳定平衡（如热带雨林、珊瑚礁）；非平衡说认为群落常处于干扰与恢复的过程中，结构由干扰频率、扩散限制与历史偶然性决定（如干旱区溪流、潮间带）。检验方法是看群落是否具有可重复的演替终点、物种组成是否随时间收敛。现代观点认为二者构成连续谱，且随尺度变化：小尺度短时间偏向非平衡，大尺度长时间偏向平衡。"},{"id":"31.1","t":"群落分类的原则与单位","s":2,"c":"31. 群落分类、排序与稳定性","x":"群落分类以群落的种类组成、外貌、结构、生态地理特征与动态为依据。中国植物群落分类系统采用三级主要单位：植被型（vegetation type，依据生活型与外貌，如常绿阔叶林）、群系（formation，依据建群种或共建种，如青冈林）、群丛（association，依据层片结构与优势种组合，如青冈—木荷—芒萁群丛）。辅助单位有群系组、群丛组、亚群系等。"},{"id":"31.2","t":"主要分类学派","s":2,"c":"31. 群落分类、排序与稳定性","x":"（1）中国学派：以植被型—群系—群丛为骨干，强调综合特征与生态地理原则。（2）法瑞学派（Braun-Blanquet）：以\"特征种\"（character species）确定群丛，强调区系组成与严谨的样地记录，建立了层片与盖度—多度（Braun-Blanquet 六级）系统。（3）英美学派：早期以动态演替与顶极为基础，后期转向数量方法。（4）苏联学派：以生物地理群落为核心概念。不同学派对同一植被可能给出不同名称，这是群落分类的可比性难题。"},{"id":"31.3","t":"群落的数量分类","s":2,"c":"31. 群落分类、排序与稳定性","x":"数量分类用多元统计方法对样方进行分类，主要方法包括：关联分析、组平均法（UPGMA）、TWINSPAN（双向指示种分析）、以及非度量多维标度（NMDS）。基本流程是：构建样方×物种矩阵→计算相似性（BrayCurtis、Jaccard）或距离→聚类→确定分类等级并找出指示种。数量分类的优点是可重复、可处理大样本，局限是结果依赖相似性指标与聚类算法，且不自动具备生态学意义，需结合专业知识解释。"},{"id":"31.4","t":"群落排序","s":2,"c":"31. 群落分类、排序与稳定性","x":"排序（ordination）把样方按物种组成相似性排列在少数几个轴上，以揭示群落沿环境梯度的连续变化。分为间接梯度分析（只用物种数据，如 DCA、PCA、NMDS）与直接梯度分析（同时使用环境变量约束排序，如 CCA、RDA）。排序的产物是排序图，样方在图上的位置反映其生态相似性，环境向量表示因子与排序轴的相关性。排序与分类互补：分类强调离散类型，排序强调连续变化。"},{"id":"31.5","t":"群落稳定性的两个成分","s":3,"c":"31. 群落分类、排序与稳定性","x":"稳定性包括抵抗力（resistance，系统抵抗扰动而保持结构与功能不变的能力）与恢复力（resilience，受扰后恢复到原状态的速度与程度）。二者常呈权衡：热带雨林抵抗力强（结构复杂、缓冲能力大）但恢复力弱（一旦破坏极难恢复）；温带草地抵抗力弱（易被干旱与过牧破坏）但恢复力强（数年即可恢复）。因此\"某群落稳定性高\"必须指明是抵抗力还是恢复力，否则表述不严谨。"},{"id":"31.6","t":"多样性与稳定性的关系","s":3,"c":"31. 群落分类、排序与稳定性","x":"早期观点（Elton、MacArthur）认为多样性越高稳定性越高，理由是食物网复杂、替代路径多。May（1972）用随机矩阵模型证明：在随机参数下，系统越复杂（物种越多、连接度越高）越不稳定，只有当相互作用强度足够弱时复杂性才与稳定性相容。此后形成多种调和假说：冗余假说（功能冗余使系统对物种丧失不敏感）、铆钉假说（每个物种都重要）、关键种假说（少数物种决定稳定性）、以及\"多样性提高稳定性（时间稳定性）但未必提高抵抗力\"的实验结论（BioDIV 等）。"},{"id":"31.7","t":"群落稳定性与生态系统健康","s":2,"c":"31. 群落分类、排序与稳定性","x":"实践中评价稳定性常用指标：种群变动的变异系数（CV）、群落组成的年际相似度、恢复速率、以及对扰动的阈值（是否发生状态转换）。生态系统健康指系统具有维持结构、自我调节与提供服务的综合能力。需要注意的是稳定性并非\"越好越好\"：高度稳定的系统可能已进入\"僵化\"状态而丧失更新能力，适度的干扰是维持多样性与更新所必需的，这一思想即\"干扰生态学\"与\"生态管理中的干扰模拟\"。第六篇 生态系统生态学"},{"id":"32.1","t":"生态系统的概念","s":3,"c":"32. 生态系统组成与结构","x":"生态系统（ecosystem）由 Tansley 于 1935 年提出，指在一定空间中生物群落与其非生物环境通过能量流动与物质循环相互作用而形成的功能整体。概念的核心有三点：一是包含生物与非生物两部分，二是强调二者之间的相互作用与物质能量联系，三是强调其作为功能单位而非分类单位。生态系统的边界由研究者依研究目的划定（如一个池塘、一片森林、整个生物圈），因此同一地段可划为不同尺度的生态系统。"},{"id":"32.2","t":"生态系统的四个基本成分","s":3,"c":"32. 生态系统组成与结构","x":"（1）非生物环境（abiotic environment），包括气候因子、无机物质（C、N、P、K 等）、有机物质（腐殖质）与基质（土壤、水）；（2）生产者（producer），主要是绿色植物与光合/化能自养微生物，把无机物合成有机物，是生态系统的能量入口；（3）消费者（consumer），包括植食动物（一级消费者）、肉食动物（二级及更高级消费者）、寄生者与食碎屑动物；（4）分解者（decomposer），包括细菌、真菌与部分土壤动物，把有机物分解为无机物并归还环境。四者通过食物关系与物质循环连接成整体。功能代表生物关键特征非生物环境成分提供物质、能量与生存空间光、水、土壤、无机盐决定系统类型的物理基础生产者固定太阳能、合成有机物绿色植物、蓝细菌、化能自养菌能量流动的起点消费者传递能量、调节种群植食动物、肉食动物、寄生生物加快物质循环分解者分解有机物、归还养分细菌、真菌、蚯蚓、螨类物质循环的关键环节"},{"id":"32.3","t":"生态系统的营养结构","s":3,"c":"32. 生态系统组成与结构","x":"营养结构指生物成分之间以食物关系连接成的结构，表现为食物链与食物网，并可按营养级分层。营养结构决定了能量流动的路径与效率，也决定了污染物富集的可能（生物放大）。营养结构的复杂程度通常用物种数、连接数、连接度（connectance）与平均链长衡量，一般陆地系统的食物网连接度约0.1~0.3，平均链长 2~4 级。"},{"id":"32.4","t":"生态系统的类型","s":2,"c":"32. 生态系统组成与结构","x":"按生境分为陆地生态系统（森林、草原、荒漠、苔原、农田、城市）与水域生态系统（淡水：河流、湖泊、沼泽、水库；海洋：河口、浅海、大洋、珊瑚礁、红树林）；按人类干预程度分为自然生态系统、半自然生态系统（如放牧草地）与人工生态系统（农田、城市）。类型划分的依据是生境物理条件与生物群落组成的组合，不同类型的生产力、生物量与周转速率差异极大。"},{"id":"32.5","t":"生态系统的四项基本功能","s":3,"c":"32. 生态系统组成与结构","x":"（1）生物生产，包括初级生产（自养生物固定太阳能）与次级生产（异养生物转化）；（2）能量流动，沿食物链单向传递并逐级递减，遵守热力学第一、第二定律；（3）物质循环，包括生物地球化学循环，物质可被反复利用；（4）信息传递，包括物理信息（光、声、温）、化学信息（信息素、他感物质）、行为信息与营养信息，起调节种间关系与群落结构的作用。四项功能中，能量是单向的、物质是循环的，这一区别是理解生态系统运行的关键。"},{"id":"32.6","t":"生态系统结构的基本特征","s":2,"c":"32. 生态系统组成与结构","x":"生态系统结构具有层次性（空间垂直分层与水平镶嵌）、开放性（与外界交换物质能量）、动态性（随时间演替与季节变化）与自我调节性（通过反馈维持相对稳定）。结构决定功能：结构简化（如单一树种人工林）通常导致功能弱化（抗虫能力差、养分循环不畅），这是\"结构—功能统一\"原则的实践意义。"},{"id":"32.7","t":"生态系统研究的基本途径","s":2,"c":"32. 生态系统组成与结构","x":"三条途径：（1）黑箱途径，只测输入输出，如流域尺度的物质平衡研究（Hubbard Brook 实验）；（2）分室途径，把系统划分为若干分室并测定室间流通率，建立能流与物流模型（如 Odum 的银泉模型）；（3）系统分析途径，用微分方程或模拟模型描述各分室的动态并预测。现代研究还强调多尺度整合（样地—流域—区域—全球）与模型—观测融合（数据同化）。"},{"id":"33.1","t":"牧食食物链","s":3,"c":"33. 食物链、营养级与生态金字塔","x":"牧食食物链（grazing food chain，捕食食物链）以活体生物为起点，从绿色植物到植食动物再到各级肉食动物，如\"草→蝗虫→蛙→蛇→鹰\"。其特点是能量沿活体传递、每一环节都有大量能量以呼吸与排泄形式损失，因此链长通常不超过 4~5 级。牧食链在海洋与草地生态系统中是主要能流通道，在森林中则只占总能流的小部分。"},{"id":"33.2","t":"碎屑食物链","s":3,"c":"33. 食物链、营养级与生态金字塔","x":"碎屑食物链（detrital food chain）以死的有机物质（枯枝落叶、动物尸体、粪便）为起点，经食碎屑动物与分解者转化为无机物，如\"落叶→蚯蚓→鼹鼠→猫头鹰\"或\"落叶→真菌与细菌→原生动物→线虫\"。在森林与湿地生态系统中，90% 以上的能量流经碎屑链，因此碎屑链是这些系统能流的主通道。碎屑链的意义还在于把物质归还环境、维持养分循环，是\"物质循环\"的生物学基础。"},{"id":"33.3","t":"寄生食物链","s":2,"c":"33. 食物链、营养级与生态金字塔","x":"寄生食物链以寄生关系连接，起点常是大型生物，随寄生层次增多而个体变小、数量增多，如\"草→兔→跳蚤→细菌→噬菌体\"。寄生链的特点是能量传递效率极低（因宿主大部分能量未被寄生物利用）且不依赖宿主的死亡。此外还有\"腐食链\"（以尸体为起点）与\"寄生—捕食混合链\"，实际生态系统中各类食物链相互交织成网。"},{"id":"33.4","t":"食物网及其复杂性","s":3,"c":"33. 食物链、营养级与生态金字塔","x":"食物网（food web）指群落中多种食物链相互交错形成的网状结构。食物网的复杂性可用物种数、连接数、连接度、平均链长、隔室化程度（compartmentalization）描述。食物网的现实意义：（1）决定扰动的传播路径，某一节点消失会沿网传播（\"级联效应\"）；（2）决定生物放大效应，营养级越高，脂溶性污染物浓度越高；（3）影响系统稳定性，隔室化程度高（分成相对独立的模块）可阻止扰动扩散，增强稳定性。"},{"id":"33.5","t":"营养级与营养级位","s":3,"c":"33. 食物链、营养级与生态金字塔","x":"营养级（trophic level）指生物在食物链中所处的位置：生产者（植物、自养微生物）为第一营养级，植食动物为第二营养级，一级肉食动物为第三营养级，依次类推。杂食动物的营养级不是整数，可用\"营养级位\"（trophic position）按食物组成的加权平均计算：TP=1+Σ（各食物项所占比例×其营养级位）。这一概念解决了\"同一物种既吃植物又吃肉\"的归属难题，是稳定同位素分析（δ¹⁵N 每升高一个营养级约富集 3.4‰）的理论基础。"},{"id":"33.6","t":"生态金字塔的三种类型","s":3,"c":"33. 食物链、营养级与生态金字塔","x":"（1）能量金字塔：以各营养级所含能量（或生产力）为宽度，永远呈正金字塔，因为能量逐级递减，不可倒置；（2）数量金字塔：以个体数为宽度，可倒置，如\"一棵树→数千只昆虫→数十只鸟\"，或\"一棵橡树→大量毛虫\"；（3）生物量金字塔：以现存量（生物量）为宽度，多数为正金字塔，但在海洋生态系统中常倒置，因为浮游植物周转极快（数天）、现存量小却能支撑现存量大的浮游动物与鱼类。竞赛中\"能量金字塔可倒置\"是经典错误选项。类型度量是否可倒置倒置实例能量金字塔各营养级能量或生产力不可倒置无（违反热力学第二定律）数量金字塔个体数目可倒置一棵树支撑大量昆虫生物量金字塔现存量（干重）可倒置海洋浮游植物现存量小于浮游动物"},{"id":"33.7","t":"营养级数与食物链长度的限制","s":2,"c":"33. 食物链、营养级与生态金字塔","x":"食物链长度受限的原因包括：（1）能量损失，按 10% 效率计算，第五营养级仅剩初始能量的 0.01%，不足以维持可繁殖种群；（2）生态效率与体积约束，顶级捕食者体型大、密度低、灭绝风险高；（3）动态稳定性，长链系统在扰动下更易崩溃。经验规律是陆地食物链平均 3~4 级、海洋可达 5 级（因浮游植物周转快、传递效率较高），这与\"海洋生物量金字塔倒置\"是同一现象的两个侧面。"},{"id":"34.1","t":"初级生产的基本概念","s":3,"c":"34. 初级生产","x":"初级生产（primary production）指自养生物（绿色植物、藻类、蓝细菌、化能自养菌）把无机物合成为有机物的过程，其速率即初级生产力。总初级生产量（GPP）指光合作用固定的有机物总量；净初级生产量（NPP）=GPP-R_A，其中 R_A 为自养呼吸；净生态系统生产量（NEP）=NPPR_H，其中 R_H 为异养呼吸。三者关系为 GPP>NPP>NEP，只有 NEP 才是生态系统可积累的生物量（NEP>0 表示碳汇）。"},{"id":"34.2","t":"全球净初级生产力的数值与分布","s":3,"c":"34. 初级生产","x":"全球陆地 NPP 约 100~110 Pg C/a（1 Pg=10¹⁵ g），海洋约 50~60 Pg C/a，合计约 160 Pg C/a。单位面积生产力最高的是热带雨林（约 2 200 g 干重/(m²·a)）、沼泽湿地、珊瑚礁与河口，最低的是荒漠（小于 100 g/(m²·a)）与大洋（约 125 g/(m²·a)）。陆地 NPP 的空间格局受温度与水分共同限制，海洋受光照（透光层深度）与营养盐（尤其氮、磷、铁）限制，其中\"高营养盐低叶绿素\"（HNLC）海域受铁限制，铁施肥实验可引发藻华。生态系统类型单位面积 NPP（g 干重/(m²·a)）主要限制因子热带雨林约 2 200光（林下）、磷沼泽与湿地约 2 000水位、缺氧珊瑚礁约 2 500光、水温、营养盐低温带森林约 1 200温度、氮温带草原约 600水分荒漠小于 100水分大洋约 125营养盐（氮、铁）、光"},{"id":"34.3","t":"初级生产力的测定方法","s":3,"c":"34. 初级生产","x":"（1）收获量法（直接收割法），适用于陆地草本与农作物，通过定期收割测定生物量增量，缺点是忽略被取食与凋落部分；（2）气体交换法，用红外气体分析仪（IRGA）测 CO₂ 交换，适用于叶片与冠层；（3）黑白瓶法，用溶解氧变化测水生系统的 GPP 与 NPP；（4）14C 同位素法，标记 CO₂ 后测固定量，灵敏度高，适用于水体；（5）叶绿素法，由叶绿素含量与同化数推算；（6）遥感法，用 NDVI、EVI 等植被指数与光能利用率模型（如 CASA、GPP模型）估算区域与全球尺度。不同方法结果常有系统偏差，比较时必须注意方法一致性。"},{"id":"34.4","t":"初级生产的限制因素","s":3,"c":"34. 初级生产","x":"限制因素遵循\"最小因子\"原则：（1）光，随纬度、季节、水深与冠层深度衰减，水体透光层深度决定浮游植物分布深度；（2）温度，影响酶活性，陆地NPP 与年均温显著正相关；（3）水分，干旱区 NPP 与降水呈近线性关系，水分利用效率（WUE）是关键参数；（4）养分，陆地多为氮限制（温带、北方），热带老成土多为磷限制，海洋多为氮或铁限制；（5）CO₂ 浓度，升高可提高 C3 植物光合速率与水分利用效率（\"CO₂ 施肥效应\"）。多因子共同限制时，需用因子交互实验判断主导因子。"},{"id":"34.5","t":"初级生产的生态效率","s":2,"c":"34. 初级生产","x":"初级生产的效率指标包括：（1）光能利用率，即 NPP 或 GPP 占入射太阳辐射的比例，全球陆地平均 GPP 的光能利用率约 0.2%~0.5%，高产农田可达2%~3%；（2）光合效率，即光合器官吸收的光能转化为化学能的比例，理论最大值约 6%（C3）与 8%（C4）；（3）净生产率，即 NPP/GPP，森林约40%~50%，荒漠与极端环境可低于 20%。效率差异主要来自呼吸消耗与环境胁迫，这是\"为什么荒漠虽有强光而生产力极低\"的解释。"},{"id":"34.6","t":"提高初级生产力的途径","s":2,"c":"34. 初级生产","x":"农业与生态工程中的途径包括：优化冠层结构以提高光能截获（合理密植、行株距配置）、改善水分供应与养分平衡（施肥、灌溉、覆膜）、选用高光效品种（C4 作物、株型改良）、减少呼吸消耗与病虫害损失、延长生长季（温室、育苗移栽）、以及提高复种指数。需要注意的是，提高生产力常以增加投入与降低稳定性为代价，因此追求\"最大产量\"与\"可持续产量\"不同。"},{"id":"34.7","t":"初级生产与碳汇","s":2,"c":"34. 初级生产","x":"NEP>0 的生态系统是碳汇。全球陆地碳汇约 2~3 Pg C/a（吸收人为排放的约 30%），海洋碳汇约 2~2.5 Pg C/a。森林是最重要的陆地碳汇，其中幼龄林与恢复中的森林固碳速率最高（可达 5~10 t C/(ha·a)），成熟林 NEP 接近零但仍储存大量碳。理解 GPP、NPP、NEP 与碳源汇的关系是分析\"植树造林能否抵消排放\"这类问题的关键，答案取决于时间尺度与基线（采伐、火灾、土壤碳损失都需计入）。"},{"id":"35.1","t":"次级生产的过程","s":3,"c":"35. 次级生产与分解","x":"次级生产（secondary production）指异养生物（消费者与分解者）利用初级生产产物进行同化、生长与繁殖的过程。能量收支式为 C=A+F_U，其中 C 为摄食量、A 为同化量、F_U 为粪便与排泄损失；A=P+R，其中 P 为净生产量（生长与繁殖）、R 为呼吸消耗。故 P=C-F_U-R。次级生产量的单位通常为 g 干重/(m²·a) 或 kJ/(m²·a)。次级生产不仅包括现存量增加，还包括被取食与死亡的部分，因此实际测定需按世代累加。"},{"id":"35.2","t":"次级生产量的测定","s":2,"c":"35. 次级生产与分解","x":"测定方法：（1）按世代累加，P=Σ（各龄期平均个体重增量×个体数）；（2）用 P/B 系数法估算，P=B×（P/B），其中 P/B 为生产量与生物量之比，浮游动物可达 10~50/a，鱼类约 0.5~2/a；（3）用去除法，连续取样测定种群生物量的增长与损失（含被捕食、死亡、迁出）；（4）用能量收支法，由摄食量与同化效率推算。P/B 系数与寿命密切相关：寿命越短、世代数越多，P/B越大。"},{"id":"35.3","t":"次级生产的生态效率","s":3,"c":"35. 次级生产与分解","x":"次级生产涉及三种效率：（1）同化效率 A/C，肉食动物约 80%（食物易消化），植食动物约 20%~50%（含大量纤维素与木质素），碎屑食性动物约10%~30%；（2）生产效率 P/A，内温动物约 1%~3%（大量能量用于维持体温），外温动物约 10%~40%，微生物可达 30%~60%；（3）生态生长效率P/C，即生产效率与同化效率之积。由于植食动物的同化效率低而内温动物生产效率低，所以\"食草—食肉\"两个环节的能量损失都很大，这是营养级数目受限的生理基础。"},{"id":"35.4","t":"分解作用的性质与阶段","s":3,"c":"35. 次级生产与分解","x":"分解作用（decomposition）指有机物质被物理破碎、化学淋溶与生物代谢逐步转化为无机物的过程，通常分为三个阶段：（1）淋溶与机械破碎，可溶性物质被水淋洗、大型动物与冻融使残体破碎；（2）生物化学分解，由胞外酶把大分子水解为小分子；（3）有机化与矿化，微生物同化部分碳形成微生物生物量，其余以 CO₂、NH₄⁺、PO₄³⁻ 等形式释放。分解速率的常用指标是凋落物失重率（%）与分解常数 k（Olson 指数衰减模型 M_t=M_0·e^{-kt}，周转时间约 1/k）。"},{"id":"35.5","t":"分解者类群","s":3,"c":"35. 次级生产与分解","x":"分解者包括：（1）细菌与放线菌，分解易利用的糖类、蛋白质，数量最大；（2）真菌，分泌胞外酶分解纤维素、半纤维素与木质素，是木质残体分解的主力，外生菌根真菌与腐生真菌在森林物质循环中作用关键；（3）土壤动物，分为微型（线虫、原生动物）、中型（螨、跳虫）、大型（蚯蚓、马陆、白蚁），其作用是把残体破碎、增大表面积、并把微生物带入新基质（\"微生物接种效应\"）。白蚁肠道共生体可分解木质素，是热带分解的关键类群。"},{"id":"35.6","t":"资源质量与分解速率","s":3,"c":"35. 次级生产与分解","x":"凋落物质量决定分解速率，主要指标是 C/N 比、木质素含量与单宁含量。C/N 比约 25:1 是微生物 Demand 与供给的平衡点：C/N 高于 25 时微生物需从环境中摄取氮，分解变慢；低于 25 时氮充足，分解加快。木质素与单宁难以降解且抑制酶活性，因此针叶林凋落物（高木质素、高 C/N）分解慢、易形成厚凋落物层与酸性腐殖质；阔叶林凋落物分解快，养分周转快。竞赛中\"为什么针叶林土壤酸性且有机质积累多\"的答案即在此。"},{"id":"35.7","t":"理化环境对分解的影响与碳周转","s":3,"c":"35. 次级生产与分解","x":"分解速率随温度升高而加快（Q10 约 2~3），随湿度增加而加快但过湿缺氧会抑制（因此湿地与泥炭地分解极慢、碳积累多），通气良好则加速。典型碳周转时间：热带雨林凋落物分解常数 k 可达 1~2/a，周转时间不到 1 年；温带落叶林约 2~4 年；北方针叶林 5~10 年；泥炭与冻原可达数十年至数百年。这一差异解释了为何全球土壤碳库（约 1 500~2 400 Pg C）主要分布在高纬湿地与冻土区，也解释了为何永久冻土融化会形成强大的碳释放正反馈。"},{"id":"36.1","t":"能量流动的热力学基础","s":3,"c":"36. 能量流动与生态效率","x":"能量流动遵守热力学第一定律（能量守恒，生态系统中能量既不产生也不消灭，只转换形式）与第二定律（能量转换必然伴随熵增，即部分能量以热的形式散失，无法再被利用）。因此生态系统必须不断接受太阳辐射输入，能量流动是单向的、不可逆的、逐级递减的，这与物质循环的往复性形成根本区别。第二定律是\"能量金字塔不可倒置\"的理论根据。"},{"id":"36.2","t":"能量流动的路径与特点","s":3,"c":"36. 能量流动与生态效率","x":"能量流动路径为：太阳辐射→生产者（光合固定）→消费者（摄食传递）→分解者（分解残体）→以热的形式散失，每一环节都伴随呼吸消耗与排泄损失。其特点：（1）单向流动、不可循环；（2）逐级递减，传递效率约 10%；（3）流动速率在不同系统中差异大（森林周转慢、海洋与草地周转快）；（4）能量流动与物质循环相伴发生，物质是能量的载体，能量是物质循环的动力。"},{"id":"36.3","t":"Lindeman 十分之一定律","s":3,"c":"36. 能量流动与生态效率","x":"Lindeman（1942）在研究湖泊生态系统时提出：能量在营养级之间传递的效率平均约为 10%，即后一营养级只获得前一营养级能量的约 10%（范围约5%~20%）。因此若生产者固定 10 000 kJ，则第二营养级约 1 000 kJ、第三约100 kJ、第四约 10 kJ，这解释了食物链为何一般不超过 4~5 级。必须注意：10% 是\"营养级间传递效率\"的平均值，不是任何具体系统的固定常数，也不是\"能量利用了 10%\"；不同系统的传递效率可在 5%~20% 之间变化，海洋可达15%~20%，陆地森林常低于 10%。"},{"id":"36.4","t":"生态效率的四种类型","s":3,"c":"36. 能量流动与生态效率","x":"（1）同化效率 A/I（A 同化量，I 摄入量）；（2）生产效率 P/A（P 净生产量）；（3）消费效率 I/P_{n-1}（后一营养级摄入量占前一营养级生产量的比例）；（4）Lindeman 效率（营养级间能量传递效率），等于消费效率×同化效率×生产效率。四种效率的乘积决定能量沿食物链的衰减速度，竞赛中\"提高某一效率能否增加顶级捕食者能量\"需逐项分析。效率类型定义式同化效率A/I生产效率P/A消费效率I/P(n-1) Lindeman 效率P(n)/P(n-1)典型数值影响因素肉食 80%，植食20%~50%内温动物 1%~3%，外温10%~40%多在 20%~60%食物可消化性平均约10%（5%~20%）上述三者之积体温调节耗能取食强度、逃避能力"},{"id":"36.5","t":"食物链层次上的能流分析","s":2,"c":"36. 能量流动与生态效率","x":"以食物链为对象测定各营养级的能量收支，可揭示能量在传递中的损失部位。经典结论：植食动物摄入的能量中约 50%~80% 以粪便排出（未同化），同化能量中又有 60%~80% 用于呼吸，因此净生产量仅占摄入量的很小比例；肉食动物粪便损失少但呼吸消耗占比更高。这一分析解释了\"为什么顶级捕食者数量稀少且需要大面積巢域\"。"},{"id":"36.6","t":"生态系统层次的能流模型","s":3,"c":"36. 能量流动与生态效率","x":"Odum（1957）对美国佛罗里达银泉的经典研究给出了完整的能流数据：总太阳辐射 410 000 kcal/(m²·a)，生产者固定的 GPP 为 20 810（约占5%），NPP 为 8 833，草食动物同化 3 368，肉食动物同化 383。该模型首次以统一的能量单位定量刻画整个生态系统，是生态系统能流研究的范式。现代研究以碳通量（涡度相关）与遥感估算替代热量单位，但基本框架不变。"},{"id":"36.7","t":"异养生态系统的能流","s":2,"c":"36. 能量流动与生态效率","x":"异养生态系统（如洞穴、深海热液口、城市）不依赖当地光合作用，能量来自外部输入的有机物质（洞穴的蝙蝠粪便、深层水体沉降的碎屑）或化能合成（深海热液口的硫氧化细菌）。深海热液口生态系统以化能自养为初级生产基础，支持管虫、蛤类等高生物量群落，说明\"无光也可有初级生产\"，这是对\"生态系统必须依赖太阳能\"的重要补充。"},{"id":"37.1","t":"生物地球化学循环的概念","s":3,"c":"37. 物质循环","x":"生物地球化学循环（biogeochemical cycle）指化学元素在生物圈、大气圈、水圈与岩石圈之间往复迁移与转化的过程，包括生物过程（吸收、同化、分解）与非生物过程（风化、溶解、沉降、火山活动）。生态系统中的物质循环有两条基本路径：生物循环（在生物与土壤/水体之间短周期循环）与地质循环（经岩石风化与沉积的长周期循环）。物质循环的驱动力是太阳辐射与重力，物质可被反复利用，因此与能量的单向流动本质不同。"},{"id":"37.2","t":"库、流通率与周转率","s":3,"c":"37. 物质循环","x":"库（pool）指某一元素在特定储库中的储存量；流通率（flow rate）指单位时间内通过某一界面的物质量；周转率（turnover rate）=流通率/库量，周转时间（turnover time）=库量/流通率=1/周转率。例如大气碳库约 850 Pg C，光合固定约 120 Pg C/a，则大气碳的周转时间约 7 年；海洋碳库约 38 000 Pg C，周转时间达数百年。周转率的大小决定该库对扰动的响应速度，是判断\"某物质是否易被生物利用\"的关键指标。"},{"id":"37.3","t":"气态型循环与沉积型循环","s":3,"c":"37. 物质循环","x":"气态型循环（ gaseous type）指主要储库为大气或水体的循环，元素以气态形式在大气中迁移，循环速度快、全球性强，包括碳、氮、氧、水（以及硫的部分）。沉积型循环（sedimentary type）指主要储库为岩石与土壤的循环，元素以固态形式存在，循环速度慢、区域性强、易受局部地质过程影响，包括磷、钙、钾、钠、硫（主要为沉积型）。区分两者的意义是：气态型元素易在全球扩散，因此局部排放具有全球后果（如 CO₂、CFC）；沉积型元素易在局部积累，因此局部开采与排放造成区域性短缺或污染（如磷矿、重金属）。循环类型主要储库循环速度代表元素环境问题的特点气态型大气、海洋快（年~百年）碳、氮、氧、水全球性（温室效应、臭氧层）沉积型岩石、土壤慢（千年~百万年）磷、钙、钾、硫区域性（水体富营养化、矿质短缺）"},{"id":"37.4","t":"水循环","s":3,"c":"37. 物质循环","x":"水循环由蒸发（海洋约 86%、陆地约 14%）、水汽输送、降水（海洋约78%、陆地约 22%）、径流与下渗构成，全球年蒸发量与降水量相等（约 496 000 km³）。生物圈中的水循环包括植物蒸腾（森林蒸腾量可占降水的 50% 以上）、截留与土壤持水。植被通过蒸腾影响区域降水（\"生物地理物理反馈\"），因此大规模毁林会减少当地降水，这一机制在亚马逊流域已被观测与模拟证实。"},{"id":"37.5","t":"碳循环","s":3,"c":"37. 物质循环","x":"碳的主要储库：岩石（约 6.5×10⁷ Pg C，最大但周转极慢）、海洋（约38 000 Pg C）、土壤与有机质（约 1 500~2 400 Pg C）、大气（约 850~880 Pg C，对应约 415 μL/L CO₂）、陆地植被（约 550~650 Pg C）、化石燃料（约 4 000~5 000 Pg C）。主要流通：光合固定约 120 Pg C/a，自养与异养呼吸各约 60 Pg C/a，海气交换约 90 Pg C/a 双向，人为排放约 10 Pg C/a（化石燃料 9~10 + 土地利用 1~1.5）。人类活动使大气 CO₂ 由工业革命前约 280μL/L 升至 2020 年代约 415 μL/L，其中约一半被海洋与陆地吸收。"},{"id":"37.6","t":"氮循环","s":3,"c":"37. 物质循环","x":"氮循环包括五个关键过程：（1）固氮作用（nitrogen fixation），把 N₂还原为 NH₃，生物固氮约 140 Tg N/a，工业 Haber-Bosch 合成氨约 150 Tg N/a（已超过自然固氮总量），高能固氮（闪电）约 5 Tg N/a；（2）氨化作用（ammonification），有机氮矿化为 NH₄⁺；（3）硝化作用（nitrification），NH₄⁺→NO₂⁻→NO₃⁻，由 Nitrosomonas 与Nitrobacter 等化能自养菌完成；（4）反硝化作用（denitrification），NO₃⁻→N₂/N₂O，由反硝化细菌在缺氧条件下完成；（5）同化作用，植物与微生物吸收 NH₄⁺ 与 NO₃⁻。氮是温带陆地与多数海域的首要限制元素，人类固氮量翻倍已造成氮沉降、水体富营养化与 N₂O（强温室气体，GWP 约 273）排放。"},{"id":"37.7","t":"磷循环与硫循环","s":3,"c":"37. 物质循环","x":"磷循环是典型的沉积型循环：无气相，主要储库为岩石与沉积物，靠风化缓慢释放，被植物吸收后经食物链传递，以遗体与粪便形式归还，部分随径流进入水体并沉积，形成\"单向流失\"格局，因此磷在长期尺度上是不可再生资源，也是淡水水体的首要限制因子。硫循环兼有气态与沉积型：岩石与化石燃料中的硫经风化、燃烧释放为 SO₂，微生物还原产生 H₂S 与 DMS（二甲基硫，海洋排放约 20 Tg S/a，影响云凝结核），最终以硫酸盐形式沉降或沉积。人类燃煤使 SO₂ 排放剧增，是酸雨的主因。过程氮循环磷循环硫循环主要储库大气（N₂）岩石、沉积物岩石、沉积物、大气关键转化固氮、硝化、反硝化风化溶解、沉淀氧化、还原、酯化生物参与固氮菌、硝化菌、反硝化菌菌根与磷酸酶硫氧化菌、硫酸盐还原菌限制性温带陆地首要限制淡水首要限制局部限制人类干扰固氮倍增、氮沉降磷矿开采、富营养化燃煤 SO₂、酸雨"},{"id":"38.1","t":"生态平衡的概念","s":3,"c":"38. 生态平衡与反馈调节","x":"生态平衡指生态系统在一定时间内结构与功能处于相对稳定状态，表现为物种组成相对稳定、生物量与生产力接近多年平均、物质输入输出大体平衡、能量流动与物质循环通畅。生态平衡是动态的、相对的，不是静止的，也不是\"绝对不变的原始状态\"；系统在平衡点附近存在允许的波动范围（阈值内的振荡），只有超出阈值才发生状态转换。"},{"id":"38.2","t":"负反馈调节","s":3,"c":"38. 生态平衡与反馈调节","x":"负反馈指系统输出偏离目标时引起相反的调节作用，使系统回到平衡点，是生态平衡得以维持的基本机制。生态学例证包括：（1）密度制约，种群密度升高→资源不足→出生率下降与死亡率上升→密度回落；（2）捕食调节，猎物增多→捕食者增多→猎物减少→捕食者减少；（3）CO₂ 施肥效应，大气 CO₂升高→植物光合增强→吸收更多 CO₂；（4）温度调节，升温→蒸发增加→云量增加→降温（部分抵消）。"},{"id":"38.3","t":"正反馈与失稳","s":3,"c":"38. 生态平衡与反馈调节","x":"正反馈指输出偏离目标时引起同向的进一步偏离，使系统远离平衡，最终导致状态转换。生态学例证：（1）富营养化，磷输入→藻类爆发→死亡分解耗氧→底泥释放磷→藻类更盛；（2）气候变暖的正反馈，升温→冰雪融化→反照率下降→吸收更多热量→进一步升温；升温→永久冻土融化→释放 CO₂ 与CH₄；（3）种群爆发的初期，密度升高→天敌尚未响应→密度更高；（4）植被—大气反馈，毁林→降水减少→植被更难恢复。"},{"id":"38.4","t":"抵抗力、恢复力与阈值","s":3,"c":"38. 生态平衡与反馈调节","x":"抵抗力（resistance）指系统抵抗扰动而保持结构与功能不变的能力，恢复力（resilience）指受扰后恢复到原状态的能力，二者常呈权衡。生态阈值（ecological threshold）指系统状态发生突变或不可逆转变的临界条件；当扰动强度超过阈值，系统可能跨越到另一个稳定状态（alternative stable state），如浅水湖泊由\"清水草型\"转为\"浊水藻型\"，即使削减营养盐也难以恢复，因为底泥磷释放与鱼类群落形成内稳机制。"},{"id":"38.5","t":"生态平衡的判据","s":2,"c":"38. 生态平衡与反馈调节","x":"判断生态系统是否处于平衡可用以下判据：结构与组成的年际相似度高、生物量/生产力接近多年平均且波动小、输入输出通量大致相等（如碳的固定与释放平衡）、关键种群数量在 K 附近波动、养分循环较闭合（流失少）。需要注意的是\"未受人类干扰\"不等于\"平衡\"，自然系统本身存在波动与演替，因此判断必须在适当的时间尺度上进行。"},{"id":"38.6","t":"生态系统健康与稳态转换","s":2,"c":"38. 生态平衡与反馈调节","x":"生态系统健康（ecosystem health）指系统具有维持组织性、自我调节与提供服务能力的综合状态，评价指标包括活力（生产力与代谢）、组织性（多样性与结构）、恢复力与减少外部输入依赖性。稳态转换（regime shift）指系统在两个稳定状态之间的突然转变，触发因子常是缓慢变化的驱动因子（营养盐累积、温度上升、捕捞压力）与随机扰动共同作用。管理启示是：应监测早期预警信号（临界慢化，critical slowing down，即扰动后恢复速率下降、方差与自相关上升），在阈值之前干预。"},{"id":"38.7","t":"反馈调节在生态系统管理中的应用","s":2,"c":"38. 生态平衡与反馈调节","x":"应用包括：（1）利用负反馈设计可持续管理，如渔业配额依据种群反馈（配额低于 MSY 以留出安全余量）；（2）抑制有害正反馈，如控制外源磷输入以阻断富营养化循环、减少化石燃料以打断气候正反馈；（3）构建人工湿地与缓冲带以增强系统对氮磷的滞留能力；（4）在生态修复中先修复\"反馈结构\"（如重建植被—土壤—水分之间的相互促进），再追求物种数，因为功能反馈不建立则修复不稳定。第七篇 生物圈与全球变化"},{"id":"39.1","t":"生物群系的概念","s":3,"c":"39. 生物群系与气候带","x":"生物群系（biome）指以优势植被类型与相应动物群落为标志、由气候条件决定的大尺度生态系统类型，如热带雨林、温带草原、荒漠、苔原。生物群系的分布由温度与水分两个主导气候因子共同决定，把年均温与年降水量作坐标即可得到\"气候—植被\"对应图（如 Whittaker 的群系分布图）。生物群系不是分类学单位，而是生态功能单位，同一群系在不同大陆可出现在不同的植物区系背景下。"},{"id":"39.2","t":"陆地生态系统的水平地带性","s":3,"c":"39. 生物群系与气候带","x":"（1）纬度地带性：随纬度升高依次出现热带雨林→亚热带常绿阔叶林→温带落叶阔叶林→北方针叶林→苔原，主导因子是温度。（2）经度地带性（干湿度地带性）：在同一纬度内随经度变化由海洋性湿润区向大陆性干旱区过渡，依次出现森林→草原→荒漠，主导因子是水分。我国北方自东向西的森林—草原—荒漠格局是经度地带性的典型，我国东部自南向北的常绿阔叶林—落叶阔叶林—针阔混交林—针叶林则是纬度地带性的典型。水平地带主导因子我国实例群系序列纬度地带性热量（年均温）东部自南向北常绿阔叶林→落叶阔叶林→针阔混交→针叶林经度地带性水分（降水量）北方自东向西森林→草原→荒漠垂直地带性海拔（温度与降水）山地自下而上基带→阔叶林→针叶林→高山灌丛→草甸→冰雪带"},{"id":"39.3","t":"垂直地带性及其规律","s":3,"c":"39. 生物群系与气候带","x":"随海拔升高，气温按每 100 m 约 0.6 ℃ 递减、降水先增后减（最大降水带常在某一高度），因此植被呈带状更替。垂直带谱的基带与所在水平带一致（如热带山地基带为热带雨林），带谱的复杂程度取决于山体高度与所处纬度（低纬高山带谱最复杂）。\"山顶与极地相似\"是常见的类比，但并不完全相同：高山的紫外辐射强、风大、土壤薄、昼夜温差大，且面积小、物种迁移受限，因此高山植物多为矮小垫状、寿命长、克隆繁殖，与苔原植物既有相似又有差异。"},{"id":"39.4","t":"主要陆地生物群系","s":3,"c":"39. 生物群系与气候带","x":"（1）热带雨林：年均温 25~27 ℃、年降水 2 000~4 000 mm、无旱季，物种极丰富、层次复杂、有板根与气生根、年 NPP 最高，土壤养分多在生物体内、土壤本身贫瘠。（2）热带稀树草原：明显干湿季、火烧频繁、C4 草与散生乔木。（3）温带草原：降水 250~800 mm、以多年生草本为主、土壤肥沃（黑土）、是主要农业区。（4）荒漠：降水小于 250 mm、蒸发强、植被稀疏、多年生植物深根或肉质、一年生植物雨后短命。（5）北方针叶林（泰加林）：冬季严寒、生长季短、以云杉、冷杉、落叶松、松为主、凋落物难分解、土壤酸性。（6）苔原（冻原）：最热月均温低于 10 ℃、无乔木、有永久冻土、生长季 2~3 个月、以苔藓、地衣、矮灌木为主。群系热带雨林年均温25~27 ℃年降水2 000~4 000 mm优势植物净初级生产力常绿阔叶乔木、藤本、附生约 2 200 g/(m²·a)温带落叶阔叶林8~12 ℃北方针叶林-5~5 ℃600~1 500 mm栎、山毛榉、槭约 1 200 g/(m²·a) 300~600 mm云杉、冷杉、落叶松约 800 g/(m²·a)温带草原5~10 ℃250~800 mm针茅、羊草等多年生草本约 600 g/(m²·a)荒漠大温差小于 250 mm仙人掌、梭梭、短命植物小于 100 g/(m²·a)苔原最热月小于 10 ℃200~300 mm苔藓、地衣、矮桦、苔草约 140 g/(m²·a)"},{"id":"39.5","t":"水域生态系统的主要类型","s":2,"c":"39. 生物群系与气候带","x":"淡水生态系统包括流水（河流、溪流，具连续流动与上下游物质输移）与静水（湖泊、池塘，具明显的沿岸带、亚沿岸带、深水带分区）以及沼泽湿地。海洋生态系统包括河口（盐度波动大、生产力高、是鱼类育幼场）、岩岸与沙岸潮间带（有明显的垂直分带，受潮汐控制）、浅海（大陆架，生产力高）、珊瑚礁（共生虫黄藻、生产力与多样性极高、对温度敏感）、红树林（热带河口耐盐木本植物群落、防浪护岸）、大洋（占海洋面积约 90%，生产力低但总面积大）。"},{"id":"39.6","t":"我国植被分布的基本格局","s":2,"c":"39. 生物群系与气候带","x":"我国植被受季风气候与青藏高原隆起的双重控制：（1）东部湿润区呈纬度地带性，自南向北为热带季雨林与雨林、亚热带常绿阔叶林、温带落叶阔叶林、温带针阔混交林、寒温带针叶林；（2）西北干旱区呈经度地带性，为草原与荒漠；（3）青藏高原为高寒植被（高寒草甸、高寒草原、高寒荒漠）。这一\"三向分异\"格局是我国植被最显著的特征，也是竞赛区域生态题的基本框架。"},{"id":"39.7","t":"生物群系与人类活动","s":2,"c":"39. 生物群系与气候带","x":"人类活动正在改变生物群系的分布：农田与城市替代了原始森林与草原（全球约 40% 的陆地被改造为农业与城市用地），气候变暖使林线与树线上升、北方森林向苔原扩张（\"绿化的北极\"），荒漠化在干旱区扩展。生物群系的改变不仅改变生产力，也改变碳储、水循环与生物多样性，因此\"生物群系制图与监测\"是全球变化研究的核心内容之一。"},{"id":"40.1","t":"温室效应的物理机制","s":3,"c":"40. 全球气候变化","x":"太阳短波辐射穿过大气到达地表，地表以长波（红外）辐射向上散失热量；大气中的温室气体（CO₂、H₂O、CH₄、N₂O、O₃、CFC）吸收特定波长的长波辐射并再向各方向发射，使部分热量返回地表，从而提高地表温度。若无温室效应，地表平均温度将约为 -18 ℃，而实际约 15 ℃，即温室效应使地表增温约 33 ℃。因此温室效应本身是自然现象、是生命存在的前提；当前的\"全球变暖\"是人类活动增强温室效应所致的额外增温。"},{"id":"40.2","t":"主要温室气体及其贡献","s":3,"c":"40. 全球气候变化","x":"按浓度增长与辐射强迫排序：（1）CO₂，浓度由工业革命前约 280 μL/L升至约 415 μL/L，是最主要的长期强迫因子；（2）CH₄，浓度由约 700 nL/L升至约 1 900 nL/L，百年尺度 GWP 约 28~30，来源包括湿地、反刍动物、水稻、垃圾填埋与冻土；（3）N₂O，GWP 约 273，主要来自化肥施用与牲畜粪便；（4）卤代烃（CFC、HCFC），GWP 可达数千至上万，同时破坏臭氧层；（5）水汽是最主要的温室气体但起反馈作用而非直接强迫。竞赛常以GWP（全球增温潜势）比较不同气体的相对贡献。"},{"id":"40.3","t":"碳源、碳汇与全球碳收支","s":3,"c":"40. 全球气候变化","x":"碳源指向大气净释放碳的过程（化石燃料燃烧、土地利用变化、土壤呼吸超过固定），碳汇指净吸收碳的过程（森林生长、海洋溶解、泥炭积累）。全球人为排放约 10~11 Pg C/a，其中约 45% 留在大气、约 25%~30% 被海洋吸收、约 30% 被陆地生态系统吸收（\"残留陆地汇\"）。碳汇的强度不是恒定的：随温度升高、干旱加剧与火灾增多，陆地碳汇可能减弱甚至转为碳源，这一\"碳汇饱和\"是气候预测的最大不确定性来源之一。"},{"id":"40.4","t":"气候变化的观测事实","s":3,"c":"40. 全球气候变化","x":"观测事实包括：（1）全球平均地表温度较工业化前上升约 1.1 ℃（近十年单年已出现超过 1.4 ℃ 的记录），且升温速率在加快；（2）海平面上升约 20 cm（20 世纪以来），主要因热膨胀与冰川融化；（3）北半球积雪与海冰面积减少，北极海冰夏季面积显著缩减；（4）极端高温、强降水与干旱事件的频率与强度增加；（5）海洋酸化，表层海水 pH 已下降约 0.1（相当于氢离子浓度增加约 30%）；（6）物候提前与物种分布迁移。"},{"id":"40.5","t":"气候变化的生态后果","s":3,"c":"40. 全球气候变化","x":"后果包括：（1）物候错配，春季事件提前程度不同导致鸟类孵化与毛虫高峰不吻合；（2）分布区迁移，物种向高纬与高海拔移动（陆地约每十年数公里、海洋更快），迁移慢的物种（如高山特有种、土壤生物）面临\"无路可退\"；（3）珊瑚白化，海水升温 1~2 ℃ 即使珊瑚排出虫黄藻，持续高温导致大面积死亡；（4）生产力与碳储变化，高纬可能增产而低纬与干旱区减产；（5）病害与虫害扩展，冬季变暖使害虫越冬存活率上升；（6）海平面上升淹没滨海湿地与低地。"},{"id":"40.6","t":"关键反馈过程","s":3,"c":"40. 全球气候变化","x":"（1）冰—反照率正反馈，冰雪融化使反照率由约 0.8 降至 0.2，吸收更多辐射，加速升温；（2）永久冻土碳反馈，冻土融化使有机碳暴露并被微生物分解，释放 CO₂ 与 CH₄（CH₄ 在厌氧条件下大量产生），全球冻土碳约 1 400~1 600 Pg，是大气碳库的近两倍；（3）水汽反馈（正），升温使大气持水量增加；（4）云反馈（不确定，正负取决于云型与高度）；（5）碳施肥负反馈，CO₂ 升高促进光合从而增加碳吸收；（6）海洋吸收负反馈，但伴随酸化。"},{"id":"40.7","t":"减缓与适应对策","s":2,"c":"40. 全球气候变化","x":"减缓（mitigation）指减少温室气体排放或增加碳汇，途径包括：能源结构转型（可再生、核能）、提高能效、碳捕集与封存（CCS）、造林与再造林、保护泥炭与湿地、减少非 CO₂ 温室气体（甲烷回收、改进施肥）、碳定价与碳交易。适应（adaptation）指降低系统对气候变化的脆弱性，途径包括：培育耐旱耐热品种、调整种植制度与播期、建设海堤与退耕还湿、建立保护区网络与气候避难所、建立早期预警与保险机制。两者不可互相替代，实际政策需\"减缓与适应并重\"。"},{"id":"41.1","t":"臭氧层的形成与作用","s":3,"c":"41. 臭氧层、酸雨与氮沉降","x":"平流层臭氧（O₃）集中在海拔 15~35 km，最大浓度约在 20~25 km，通过氧分子的光解与三体反应（O₂+hν→2O，O+O₂+M→O₃+M）形成。臭氧层吸收 200~315 nm 的紫外线（UV-B、UV-C），保护生物免受 DNA 损伤。臭氧总量用 Dobson 单位（DU）表示，全球平均约 300 DU，南极春季曾低至约100 DU。"},{"id":"41.2","t":"臭氧层破坏的机制","s":3,"c":"41. 臭氧层、酸雨与氮沉降","x":"氯氟烃（CFC）在对流层稳定、进入平流层后经紫外线分解释放氯自由基，氯原子催化臭氧分解：Cl+O₃→ClO+O₂，ClO+O→Cl+O₂，一个氯原子可循环破坏约 10⁵ 个臭氧分子。南极\"臭氧空洞\"的形成需要三个条件：极低平流层温度形成极地平流层云（PSC）、PSC 表面发生的非均相反应把惰性氯活化、以及极夜涡旋的隔离。因此臭氧空洞具有强烈的季节性与地域性（南半球春季最严重）。"},{"id":"41.3","t":"臭氧层破坏的生态后果与治理","s":2,"c":"41. 臭氧层、酸雨与氮沉降","x":"后果包括：UV-B 增强抑制浮游植物光合（海洋初级生产力下降）、损伤植物 DNA 与光合系统（作物减产）、引起人类皮肤癌与白内障、抑制免疫、损伤动物幼体（如蛙卵）。治理措施为 1987 年《蒙特利尔议定书》及后续修正案，逐步淘汰 CFC 与 HCFC，这是国际环境治理最成功的案例，臭氧层已出现恢复迹象。需要注意的是 CFC 同时是强温室气体，因此臭氧治理对气候也有协同效益。"},{"id":"41.4","t":"酸雨的成因","s":3,"c":"41. 臭氧层、酸雨与氮沉降","x":"酸雨指 pH 小于 5.6 的降水（5.6 为大气 CO₂ 平衡时的背景值）。主要成因是人类排放的 SO₂ 与 NOx 在大气中经气相与液相氧化生成 H₂SO₄ 与HNO₃，随降水沉降。SO₂ 主要来自燃煤，NOx 主要来自机动车与高温燃烧。酸雨的分布与排放源高度相关，我国西南、华中曾是重酸雨区（因高硫煤），欧洲与北美东北部也是历史重灾区。酸度还受碱性粉尘中和影响，因此同样排放量下不同地区的降水 pH 可差异很大。"},{"id":"41.5","t":"酸雨的生态影响","s":3,"c":"41. 臭氧层、酸雨与氮沉降","x":"影响包括：（1）土壤酸化，使盐基离子（Ca²⁺、Mg²⁺、K⁺）淋失、铝离子活化（Al³⁺ 毒害根系）；（2）水体酸化，pH 降至 5 以下时鱼类繁殖失败、甲壳类与螺类消失，且铝浓度升高加剧毒性；（3）森林衰退，根系受损、养分失衡、抗逆性下降（欧洲\"森林死亡\"现象）；（4）腐蚀建筑物与文物；（5）间接影响，酸化改变微生物活性与分解速率。治理措施包括烟气脱硫脱硝、改用低硫燃料、施用石灰中和、以及国际公约（如《长距离越界空气污染公约》）。"},{"id":"41.6","t":"氮沉降及其生态效应","s":3,"c":"41. 臭氧层、酸雨与氮沉降","x":"氮沉降指大气中的活性氮（NHx 与 NOy）以湿沉降（降水）与干沉降（气体、颗粒）形式进入生态系统，全球总量已由工业革命前的约 30 Tg N/a增至约 200 Tg N/a。中国部分地区的氮沉降速率可达 20~50 kg N/(ha·a)，超过临界负荷。生态效应包括：（1）氮饱和，过量氮使森林不再受氮限制，转而出现磷、钾或镁限制；（2）土壤酸化与盐基淋失；（3）生物多样性下降，草地实验显示氮添加使物种数显著减少（竞争优势种扩张、抑制耐贫瘠的稀有种）；（4）水体富营养化与藻华；（5）N₂O 排放增加。"},{"id":"41.7","t":"氮沉降的临界负荷与管理","s":2,"c":"41. 臭氧层、酸雨与氮沉降","x":"临界负荷（critical load）指生态系统不产生有害效应的最大氮沉降量，欧洲森林多在 10~20 kg N/(ha·a)，苔原与贫营养水体更低（5 kg N/(ha·a) 以下）。管理措施包括：优化施肥量与施用时期、减少畜禽密度、改进污水与粪污处理、恢复湿地作为氮汇、以及设置缓冲区。监测方法包括沉降缸法、叶片氮含量与 δ¹⁵N 指示、以及生物指示（喜氮植物扩张、地衣群落退化）。"},{"id":"42.1","t":"生物多样性丧失的现状","s":3,"c":"42. 生物多样性丧失与保护","x":"当前物种灭绝速率比背景灭绝率（约 0.1~1 种/百万种·年）高 100~1 000倍，被称为\"第六次大灭绝\"。IUCN 红色名录评估显示约 28% 的已评估物种受威胁（其中两栖类约 41%、珊瑚约 33%、哺乳类约 25%、鸟类约 14%）。种群层面的下降更为普遍（脊椎动物种群数量半个世纪内平均下降约 68%，即\"生命行星指数\"），说明即使物种未灭绝，其生态功能也可能已大幅削弱。"},{"id":"42.2","t":"生物多样性丧失的原因","s":3,"c":"42. 生物多样性丧失与保护","x":"主要原因常用 HIPPO 概括：H（Habitat loss，生境丧失与破碎化，是首要原因）、I（Invasive species，外来种入侵）、P（Pollution，污染）、P（Population，人口增长与资源消耗）、O（Overharvest，过度捕猎与采伐）。此外还有气候变化与疾病。生境丧失的影响遵循种—面积关系：面积减少 90% 时（z=0.25）预计丧失约一半物种；破碎化还通过边缘效应与隔离效应加剧丧失，且存在\"灭绝债务\"的时间滞后。"},{"id":"42.3","t":"生物多样性热点地区","s":3,"c":"42. 生物多样性丧失与保护","x":"热点地区（biodiversity hotspot）由 Myers 提出，标准是：含有至少 1 500 种特有维管植物（占全球 0.5% 以上），且原始植被已丧失 70% 以上。全球共认定 36 个热点，覆盖陆地面积约 2.3%（原始面积约 16%），却包含约43% 的维管植物特有种与 35% 的脊椎动物特有种。我国属于\"山地中国\"（Mountains of Southwest China）热点，涵盖横断山区等区域。"},{"id":"42.4","t":"IUCN 濒危等级体系","s":3,"c":"42. 生物多样性丧失与保护","x":"等级由高到低为：灭绝（EX）、野外灭绝（EW）、极危（CR）、濒危（EN）、易危（VU）、近危（NT）、无危（LC）、数据缺乏（DD）、未评估（NE）。\"受威胁\"指 CR、EN、VU 三级。评级依据五条标准：A 种群规模下降速率、B 分布区小且破碎或下降、C 小种群且持续下降、D 种群极小、E定量分析显示野外灭绝概率高（如 20 年内 10% 以上）。理解标准的关键是\"任一条满足即可定级\"。"},{"id":"42.5","t":"就地保护","s":3,"c":"42. 生物多样性丧失与保护","x":"就地保护指在物种原生生境中保护其种群与生态系统，主要形式是自然保护区与各类保护地。我国自然保护地体系包括国家公园、自然保护区、自然公园三类，实行\"核心区—缓冲区—实验区\"分区管理：核心区禁止人为活动，缓冲区仅允许科研监测，实验区可开展可持续利用。就地保护的优势是维持生态过程与协同进化关系，局限是面对气候变化时物种可能\"无处迁移\"。"},{"id":"42.6","t":"迁地保护","s":3,"c":"42. 生物多样性丧失与保护","x":"迁地保护指把物种移出其原生境进行人工保存，形式包括动物园、水族馆、植物园、种子库、超低温保存（冷冻胚、精子、芽）、以及离体组织培养。迁地保护的作用是\"保险\"与\"补充\"：为极小种群提供遗传备份，为再引入提供个体来源。其局限包括：样本量小导致遗传多样性丢失与选择适应（适应人工环境后失去野外适应力）、成本高、无法保存生态系统过程、以及多数无脊椎动物与真菌难以迁地保存。"},{"id":"42.7","t":"自然保护区设计原则","s":3,"c":"42. 生物多样性丧失与保护","x":"依据岛屿生物地理学与集合种群理论，设计原则为：（1）面积尽可能大，以降低灭绝率并容纳大型动物与内部种；（2）形状尽量接近圆形，以减少边缘效应（同面积下周长最小）；（3）在无法建大保护区时，多个保护区网络优于单一孤立保护区，但需以廊道连接；（4）廊道应足够宽并避免\"生态陷阱\"（如引导个体进入劣质生境或传播疾病）；（5）保护区应包含完整的环境梯度与生境类型，并靠近源种群；（6）设置缓冲区以隔离外部干扰。SLOSS 争论提示：最优方案取决于目标类群，不能一概而论。"},{"id":"43.1","t":"外来种与入侵种的概念","s":3,"c":"43. 外来种入侵","x":"外来种（alien species）指经人为活动（有意或无意）引入其自然分布范围以外区域的物种；入侵种（invasive species）指外来种在新区域建立种群、迅速扩散并造成生态或经济损失的物种。入侵过程分为四个阶段：引入（transport）、定殖（establishment）、扩散（spread）、影响（impact），每一阶段都存在\"筛选\"，因此\"引入的物种中仅约 10% 能定殖、定殖中仅约 10% 成为入侵种\"（十分之一定律的入侵版本，仅为经验概括）。"},{"id":"43.2","t":"入侵成功的机制","s":3,"c":"43. 外来种入侵","x":"主要假说：（1）天敌释放假说（enemy release），新区域缺乏专性天敌，使资源可更多用于生长繁殖；（2）资源富集与波动资源假说，入侵种善于利用突发资源；（3）空生态位与生态位机会，新区域缺乏占据相似生态位的本土种；（4）竞争力优势与化感作用，如入侵植物分泌化感物质抑制本土种；（5）繁殖与扩散特性，如高种子产量、无性繁殖、短世代；（6）杂交与遗传变异，多次引入增加遗传多样性；（7）本土种的\"天真诚实\"，缺乏与入侵种共同进化的防御或识别能力。"},{"id":"43.3","t":"入侵的生态影响","s":3,"c":"43. 外来种入侵","x":"影响包括：（1）竞争排斥与本土种濒危，如入侵种与本土近缘种竞争食物或巢址；（2）改变群落结构与生态系统过程，如改变火 regime（旱雀麦使火频率上升）、改变水文（柽柳耗水）、改变土壤养分；（3）遗传影响，与本土近缘种杂交导致遗传侵蚀；（4）传播疾病，如外来蚊虫传播疾病、松材线虫引起松树萎蔫；（5）经济损失与公共健康危害。入侵种被认为是物种濒危的第二位原因（仅次于生境丧失），在岛屿生态系统中尤为严重。"},{"id":"43.4","t":"我国主要入侵种","s":2,"c":"43. 外来种入侵","x":"我国已记录的外来入侵物种数百种，代表性种类包括：紫茎泽兰与飞机草（西南草地与林地）、水葫芦（凤眼蓝，南方水体）、加拿大一枝黄花（华东荒地与路边）、互花米草（滨海湿地，虽曾用于护岸但破坏滩涂生态）、薇甘菊（华南）、松材线虫（马尾松毁灭性病害，由媒介天牛传播）、美国白蛾（阔叶树食叶害虫）、红火蚁（华南，攻击性强）、福寿螺（水稻与水生作物）、克氏原螯虾（局部危害堤坝与稻田）。"},{"id":"43.5","t":"入侵的易感生境与气候变化的交互","s":2,"c":"43. 外来种入侵","x":"易被入侵的生境特征：干扰频繁（路边、河岸、农田、城市）、物种组成简单（岛屿、人工林）、资源过剩（富营养化水体）、天敌缺乏（隔离岛屿）。气候变化通过三条路径促进入侵：一是使原本过冷的地区变得可定殖（向极扩张）；二是极端事件创造空缺资源；三是改变本土种与入侵种的竞争平衡。因此\"气候变化与生物入侵\"被视为相互放大的双重威胁。"},{"id":"43.6","t":"入侵的防控策略","s":3,"c":"43. 外来种入侵","x":"防控遵循\"预防优于 early detection 优于 eradication 优于长期控制\"的层级：（1）预防，包括风险评估、检疫、压舱水处理、禁止随意放生与引种；（2）早期监测与快速响应（eradication），在种群尚小时彻底清除的成功率最高；（3）物理防治（机械清除、火烧、围栏）；（4）化学防治（除草剂、杀虫剂，需注意非靶效应）；（5）生物防治（引入专性天敌，需严格风险评估，避免\"天敌变入侵者\"）；（6）生态修复，恢复本土植被以增强群落对入侵的抗性（\"生物抗性\"）。"},{"id":"43.7","t":"生物防治的风险与经典教训","s":2,"c":"43. 外来种入侵","x":"经典教训是 1935 年澳大利亚引入蔗蟾（cane toad）防治甘蔗甲虫失败，蔗蟾本身成为严重入侵种，毒杀本土捕食者。因此现代生物防治要求：（1）严格的寄主专一性测试（在非靶本土近缘种上测试）；（2）评估气候适应性以防天敌自身扩散失控；（3）在隔离条件下先行试验；（4）建立监测与撤除机制。生物防治的成功案例也很多，如澳洲用病毒控制兔、用寄生蜂控制粉虱，但\"成功的生物防治\"与\"天敌入侵\"往往只有一线之隔。"},{"id":"44.1","t":"生态系统服务的概念与分类","s":3,"c":"44. 生态系统服务与可持续发展","x":"生态系统服务（ecosystem services）指生态系统为人类提供的各种惠益，MA（千年生态系统评估，2005）将其分为四类：（1）供给服务，食物、淡水、木材、纤维、燃料、药物与遗传资源；（2）调节服务，气候调节、水文调节、水质净化、授粉、病虫害控制、防洪；（3）支持服务，土壤形成、养分循环、初级生产、生物多样性维持（是其他服务的基础）；（4）文化服务，审美、休闲旅游、教育与精神价值。四类之间存在权衡，如提高粮食供给常牺牲调节与文化服务。服务类型内容举例与生物多样性的关系供给服务提供物质产品粮食、木材、淡水、药材依赖物种与遗传资源调节服务调节环境过程气候调节、洪水调蓄、授粉依赖群落结构与功能群支持服务维持其他服务的基础土壤形成、养分循环、初级生产依赖物种组成与土壤生物文化服务提供精神与体验价值旅游、审美、科研教育依赖景观与物种吸引力"},{"id":"44.2","t":"生态系统服务的价值评估","s":2,"c":"44. 生态系统服务与可持续发展","x":"评估方法包括：（1）市场价值法，直接按市场价格计算产品；（2）替代成本法，按人工替代工程的成本估算（如森林涵养水源的价值按水库成本计）；（3）旅行费用法与条件价值法（CVM），用于文化服务；（4）当量因子法，按不同生态系统的单位面积价值当量乘以面积。Costanza 等（1997）估算全球生态系统服务年价值约 33 万亿美元（约为当年全球 GNP 的 1.8倍），此后多项研究给出更高估计。评估的争议在于价格的主观性与\"不可替代性\"的处理。"},{"id":"44.3","t":"生态足迹与生物承载力","s":3,"c":"44. 生态系统服务与可持续发展","x":"生态足迹（ecological footprint）指维持某一人口消费水平与消纳其废弃物所需的生物生产性土地与水域面积，单位为全球公顷（gha）。把消费折算为耕地、草地、林地、渔业水域、建设用地与碳足迹六类。生物承载力指区域可提供的生物生产性面积。当生态足迹超过生物承载力即形成\"生态赤字\"。全球人均生态足迹约 2.7 gha，而人均生物承载力约 1.6 gha，已处于赤字状态；我国人均足迹高于全球平均而人均承载力较低，赤字明显。生态足迹的局限是未考虑土地退化与不可再生资源耗竭。"},{"id":"44.4","t":"环境承载力与人口","s":2,"c":"44. 生态系统服务与可持续发展","x":"环境承载力指在不损害生态系统前提下所能支撑的最大人口数量或活动强度，其大小取决于技术水平、消费模式与贸易。同一区域在不同消费模式下承载力差异可达数倍，因此\"承载力不是固定数字\"。人口增长与消费增长的双重压力是生物多样性丧失的深层原因（HIPPO 中的 P），人口转变理论显示随着经济发展与教育提升，生育率下降，全球人口预计在本世纪中叶后趋于稳定或缓慢下降，但人均消费与资源消耗仍在上升。"},{"id":"44.5","t":"可持续发展的概念与原则","s":3,"c":"44. 生态系统服务与可持续发展","x":"1987 年《我们共同的未来》（布伦特兰报告）提出定义：\"既满足当代人的需要，又不损害后代人满足其需要的能力的发展。\"其三大支柱为经济发展、社会公平与环境保护（三重底线）。基本原则包括：公平性原则（代内公平与代际公平）、持续性原则（不超载再生能力与环境容量）、共同性原则（全球伙伴关系）。2015 年联合国通过 17 项可持续发展目标（SDGs），涵盖了消除贫困、粮食安全、清洁能源、气候行动、水下与陆地生物等。"},{"id":"44.6","t":"千年生态系统评估的结论","s":2,"c":"44. 生态系统服务与可持续发展","x":"MA（2005）的核心结论有四：（1）过去 50 年人类对生态系统的改变速度与规模超过历史上任何时期，主要为了满足快速增长的食物、淡水、木材与燃料需求；（2）这些改变带来了净收益，但代价是许多服务的退化（约 60%的服务正在退化或不可持续使用）；（3）服务退化将在未来几十年显著加剧，尤其对贫困人口影响最大，是消除贫困与实现 SDGs 的障碍；（4）扭转退化在技术上可行，但需要重大政策与制度变革。这一评估是\"生态学进入政策领域\"的标志性成果。"},{"id":"44.7","t":"生态补偿与市场化机制","s":2,"c":"44. 生态系统服务与可持续发展","x":"生态补偿（payment for ecosystem services，PES）指通过经济手段使生态服务的提供者获得补偿，从而激励保护行为，如退耕还林补助、流域上下游横向补偿、碳汇交易、湿地占补平衡。机制设计的关键是：明确服务与受益者、可测量的服务量、条件性支付（未达标不支付）与避免\"泄漏\"（保护一处导致他处破坏）。我国的生态保护红线、国家公园体制与\"两山\"理念是这一机制在制度层面的体现。第八篇 应用生态学"},{"id":"45.1","t":"农业生态系统的特征","s":3,"c":"45. 农业生态与生物防治","x":"农业生态系统是人工生态系统，其特点为：（1）目标单一，以获取人类所需的农产品为目的，物种组成被人为简化（多数农田只有 1~2 种作物）；（2）能量与物质投入高，依赖化石能源（农机、化肥、农药）与灌溉；（3）稳定性差，因结构简单、天敌缺乏，病虫害易爆发；（4）需要持续的人为调控（耕作、施肥、除草、防治），一旦停止投入即发生次生演替；（5）养分循环不闭合，大量养分随产品输出与径流流失。这些特点决定了农业生态学的基本任务是\"以生态学原理降低投入、提高稳定性\"。"},{"id":"45.2","t":"生态农业的原理与模式","s":3,"c":"45. 农业生态与生物防治","x":"生态农业以生态学的物质循环再生与生物多样性原理组织生产，核心是\"减量投入、循环利用、结构优化\"。典型模式包括：（1）种养结合，畜禽粪污还田替代部分化肥；（2）稻田养鱼、稻鸭共作，利用动物除虫除草并提供粪肥；（3）沼气工程，把粪污转化为能源与肥料，实现物质多级利用；（4）农林复合（agroforestry），乔木与作物间作以利用光与养分的时间空间互补；（5）立体种养，如\"桑基鱼塘\"（桑—蚕—鱼—塘泥—桑）构成闭合循环。生态农业的评价指标包括能效比、养分利用率、农药减量与经济效益。"},{"id":"45.3","t":"间作套种与轮作的生态学基础","s":3,"c":"45. 农业生态与生物防治","x":"间作套种的生态学依据包括：（1）生态位互补，深根与浅根、高秆与矮秆、喜光与耐阴作物搭配，提高光与养分利用效率；（2）共生固氮，豆科与禾本科间作可通过根际互作提高氮利用（\"生物多样性效应\"）；（3）边行效应，行间通风与光照改善；（4）病虫害稀释，非寄主植物打断病原与害虫的扩散、提高天敌多样性（\"资源集中假说\"的反面）；（5）减少水土流失，覆盖度提高。轮作的作用是打断连作障碍（病原积累、他感物质积累、养分偏耗）并改善土壤结构。"},{"id":"45.4","t":"生物防治的类型与方法","s":3,"c":"45. 农业生态与生物防治","x":"生物防治指利用生物或其产物控制有害生物，包括：（1）天敌释放，捕食性天敌（瓢虫、草蛉、捕食螨）与寄生性天敌（赤眼蜂、丽蚜小蜂、寄生蝇）；（2）微生物农药，苏云金芽孢杆菌（Bt，其 Cry 蛋白对鳞翅目幼虫特异）、白僵菌、绿僵菌、核多角体病毒；（3）农用抗生素，阿维菌素、多杀菌素；（4）性信息素与聚集信息素，用于诱杀与干扰交配（迷向法）；（5）昆虫不育技术（SIT），释放辐照不育雄虫；（6）植物源农药，印楝素、除虫菊酯。生物防治的优点是选择性强、无残留，局限是见效慢、受环境条件影响大、需专业知识。"},{"id":"45.5","t":"综合有害生物管理（IPM）","s":3,"c":"45. 农业生态与生物防治","x":"IPM（integrated pest management）指综合运用农业、物理、生物、化学措施，把有害生物控制在经济允许水平以下，而不是\"彻底消灭\"。其原则为：（1）以生态学为基础，监测种群动态；（2）设定经济阈值（economic threshold）与经济损害水平，仅在超过阈值时干预；（3）优先采用非化学措施；（4）化学农药作为最后手段，并选择选择性药剂、轮换用药以防抗性；（5）保护天敌与生物多样性。IPM 的生态学意义在于承认\"少量害虫可容忍\"，避免过度干预导致的次要害虫上升与抗性演化。"},{"id":"45.6","t":"土壤退化与防治","s":2,"c":"45. 农业生态与生物防治","x":"土壤退化包括水蚀、风蚀、盐碱化、酸化、板结、有机质下降与污染。水蚀的防治措施有等高耕作、梯田、覆盖作物、免耕与退耕还林还草；风蚀的防治有防护林带、留茬与秸秆覆盖；盐碱化的防治有排水洗盐、种植耐盐植物、施用有机肥改良结构。我国东北黑土有机质下降、西北土地荒漠化与华北地下水超采是典型问题。土壤形成速率极慢（约每厘米数百至上千年），因此\"土壤是不可再生资源\"是土壤保护的基本判断。"},{"id":"45.7","t":"有害生物防治中的抗性与次要害虫问题","s":2,"c":"45. 农业生态与生物防治","x":"长期单一使用化学农药会导致：（1）抗性演化，害虫种群在选择压力下富集抗性基因（抗药性机制包括靶标位点突变、解毒酶活性升高、表皮穿透性下降）；（2）次要害虫上升，广谱杀虫剂杀死天敌后，原本不重要的害虫（如叶螨、蚜虫）爆发为\"再增猖獗\"；（3）害虫 resurgence 与食物链污染。应对措施包括轮换用药、混合用药、庇护所策略（种植非转基因寄主供敏感个体存活）、以及提高天敌作用。这一现象是\"负反馈被破坏\"的典型案例。"},{"id":"46.1","t":"恢复生态学的概念与目标","s":3,"c":"46. 恢复生态学与污染生态","x":"恢复生态学研究退化生态系统恢复的机理与方法。相关术语有区别：恢复（restoration）指使系统回到接近原有结构与功能的状态；修复（remediation）多指去除污染或改善理化条件；重建（rehabilitation）指部分恢复功能但结构可能不同；再植（revegetation）仅指恢复植被覆盖。恢复的目标通常参照\"参照生态系统\"（reference ecosystem），其核心指标包括物种组成与多样性、结构复杂度、生态过程（生产力、分解、养分循环）与稳定性。"},{"id":"46.2","t":"恢复的途径与阶段","s":3,"c":"46. 恢复生态学与污染生态","x":"恢复的基本途径包括：（1）消除干扰（停止放牧、停止排污、控制采伐）；（2）改造立地条件（整地、施肥、改良土壤 pH、控制水位）；（3）引入繁殖体（播种、植苗、土壤种子库利用、接种菌根与固氮菌）；（4）生物调控（引入关键种、控制入侵种）。恢复的过程通常遵循演替规律：先建立先锋植被覆盖、再改善土壤、最后引入目标群落物种，因此\"先固土后造林\"是干旱区恢复的基本原则。"},{"id":"46.3","t":"恢复成功的判据与评价","s":2,"c":"46. 恢复生态学与污染生态","x":"判据包括：（1）结构指标，物种数、乡土种比例、生活型谱、层次结构；（2）功能指标，生物量、生产力、土壤有机质、养分循环闭合度、土壤微生物活性；（3）稳定性指标，抗入侵能力、对干旱等扰动的恢复力；（4）景观指标，与参照系统的连通性。常用的定量方法是\"轨迹分析\"，即把恢复样地与参照样地在排序图上比较，判断是否沿正确轨迹接近参照。"},{"id":"46.4","t":"污染物的生态效应","s":3,"c":"46. 恢复生态学与污染生态","x":"污染物的生态效应取决于剂量、暴露时间、化学形态与生物敏感性。主要类型包括：（1）重金属（Hg、Cd、Pb、Cr、As），不可降解、可生物富集与生物放大，通过食物链危害高营养级；（2）持久性有机污染物（POPs，如DDT、二噁英、多氯联苯），脂溶性、难降解、易在脂肪中积累；（3）农药，急性毒性与亚致死效应（影响行为、繁殖、免疫）；（4）氮磷，造成富营养化；（5）酸化物质与石油烃。生物放大（biomagnification）与生物积累（bioaccumulation）是竞赛高频概念，前者指沿食物链浓度递增，后者指个体内累积。"},{"id":"46.5","t":"生物修复的类型","s":3,"c":"46. 恢复生态学与污染生态","x":"生物修复（bioremediation）指利用生物代谢去除或降低污染物毒性，包括：（1）微生物修复，通过好氧或厌氧降解去除石油烃、有机氯，常需添加营养盐与电子受体（生物刺激）或接种特效菌（生物强化）；（2）植物修复，分植物提取（phytoextraction，超富集植物吸收并收获地上部，如蜈蚣草富集砷、东南景天富集锌镉）、植物稳定（phytostabilization，根系固定污染物防扩散）、植物挥发（phytovolatilization，如硒、汞）、根际降解（rhizodegradation，根系分泌物促进微生物降解）；（3）真菌修复，利用白腐真菌的木质素降解酶系统降解多环芳烃与染料。生物修复的优点是成本低、原位可行、环境友好，局限是周期长、受环境条件限制、可能产生有毒中间产物。"},{"id":"46.6","t":"生物监测与指示生物","s":3,"c":"46. 恢复生态学与污染生态","x":"生物监测指用生物的反应推断环境质量，其优势是能反映长期、综合的污染效应，弥补理化监测的瞬时性。常用指示生物：（1）地衣与苔藓，对 SO₂与其他大气污染物敏感，可用于大气质量分级（地衣多样性指数）；（2）底栖大型无脊椎动物，用 EPT 类群（蜉蝣、襀翅、石蛾）比例评价水质，污染水体中寡毛类与摇蚊幼虫占优；（3）藻类，用硅藻指数评价水体营养状态；（4）鱼类，用畸形率与种群结构评价；（5）土壤动物与微生物，用群落结构与酶活性评价土壤污染；（6）生物标志物，如乙酰胆碱酯酶活性（有机磷与氨基甲酸酯暴露）、金属硫蛋白、CYP450 活性、DNA 加合物。"},{"id":"46.7","t":"水体富营养化与赤潮","s":3,"c":"46. 恢复生态学与污染生态","x":"富营养化（eutrophication）指氮磷等营养盐输入过量导致藻类大量繁殖、水质恶化的过程。发展阶段为贫营养→中营养→富营养→超富营养，评价指标包括总氮、总磷、叶绿素 a、透明度与溶解氧。后果包括：水华（蓝藻形成浮沫并释放藻毒素）、水体缺氧（藻体分解耗氧，形成\"死区\"）、鱼类死亡、生物多样性下降、饮用水安全风险。赤潮指海域中浮游生物（甲藻、硅藻、夜光藻）暴发性增殖使海水变色的现象，成因包括富营养化、适宜水温与光照、以及水文条件（如上升流、封闭海湾），部分赤潮藻产毒素（麻痹性贝毒）可经贝类富集危害人体。治理措施包括控源截污、生态清淤、水生植物恢复、以及应急处置（打捞、黏土絮凝）。"},{"id":"47.1","t":"生态工程的概念与原理","s":3,"c":"47. 生态工程与环境影响评价","x":"生态工程（ecological engineering）由 Odum 与马世骏分别提出，指运用生态学原理与系统工程方法，设计、建造与调控人工生态系统，以实现资源高效利用与环境保护。马世骏将其概括为\"整体、协调、循环、再生\"四原则，并强调\"社会—经济—自然复合生态系统\"的分析框架。生态工程区别于传统环境工程的关键在于：以生物为主体、以太阳能为动力、以物质循环为机制，而非以高能耗的物理化学处理为主。"},{"id":"47.2","t":"生态工程的典型模式","s":3,"c":"47. 生态工程与环境影响评价","x":"（1）桑基鱼塘，桑—蚕—鱼—塘泥—桑的闭合循环，物质多级利用、能量高效转化；（2）人工湿地，通过基质吸附、植物吸收与微生物降解去除氮磷与有机物，处理污水成本低、有生态景观价值；（3）农业废弃物资源化，秸秆还田、沼气发酵、菌渣利用；（4）矿区生态修复，尾矿库覆土植被重建、酸性废水人工湿地处理；（5）防护林体系，农田防护林、防风固沙林、水源涵养林；（6）城市生态工程，屋顶绿化、雨水花园、海绵城市设施。评价指标包括污染物去除率、能效比、投资与运行成本、生态效益。"},{"id":"47.3","t":"生态规划的基本内容","s":2,"c":"47. 生态工程与环境影响评价","x":"生态规划指以生态学原理为指导，对区域的土地利用、产业布局、生态保护与建设进行空间安排。李博《生态学》第十六章把生态规划与生态风险评估并列为应用内容，其工作程序为：生态要素调查与评价→环境容量与生态适宜度分析→生态功能区划→土地利用与产业布局→生态保护与建设规划→规划实施的保障措施。核心方法包括生态适宜度分析（用网格法、加权模型评估某类用地的适宜程度）与生态敏感性分析。"},{"id":"47.4","t":"环境影响评价（EIA）","s":3,"c":"47. 生态工程与环境影响评价","x":"环境影响评价指对拟议的建设项目或规划实施后可能造成的环境影响进行分析、预测与评估，并提出预防或减轻措施的制度性程序。基本流程为：编制评价大纲→现状调查与监测→影响预测（大气、水、噪声、生态）→提出减缓措施→编制报告书→审批与公众参与→施工期与运营期跟踪监测（后评价）。生态影响评价特别关注：生境占用与破碎化、珍稀濒危物种、生态保护红线、以及累积效应与间接效应。竞赛中\"环评的意义\"应强调其\"预防为主\"与\"决策支持\"功能。"},{"id":"47.5","t":"生态风险评价","s":2,"c":"47. 生态工程与环境影响评价","x":"生态风险评价指评估暴露于一种或多种胁迫因子下产生不利生态效应的可能性与程度，四步框架为：（1）问题形成，明确评价终点与概念模型；（2）暴露评价，确定胁迫因子的时空分布与生物接触量；（3）剂量—效应评价，建立浓度与效应的定量关系（如 LC50、NOEC、ECx）；（4）风险表征，用商值法（PEC/PNEC）或概率法（联合概率曲线）给出风险水平，并进行不确定性分析。生态风险评价与人体健康风险评价的区别在于终点是\"种群、群落、生态系统\"而非个体健康。"},{"id":"47.6","t":"生态监测与遥感应用","s":2,"c":"47. 生态工程与环境影响评价","x":"生态监测指对生态系统结构、功能与过程的长期系统观测，包括样地监测（森林、草地、湿地固定样地）、通量观测（涡度相关塔）、遥感监测（植被指数、土地覆盖、火点、叶面积指数）与模型模拟。指标可分为压力指标（污染排放、土地利用变化）、状态指标（NDVI、生物量、物种数）、响应指标（物候变化、群落退化）。遥感的价值在于提供大范围、多时相、空间显式的信息，弥补样地\"点\"观测的不足，二者的结合即为\"尺度推绎\"的实践路径。"},{"id":"47.7","t":"生态工程与绿色基础设施","s":2,"c":"47. 生态工程与环境影响评价","x":"绿色基础设施指以自然或半自然生态系统为主体、提供生态服务的基础设施网络，包括城市绿地系统、湿地网络、生态廊道与雨洪管理设施。其功能包括调蓄雨洪、降低热岛、净化空气与水质、提供休闲与生物多样性栖息地。与灰色基础设施（管网、混凝土堤防）相比，绿色基础设施投资低、多功能、有生态协同效益，但占地在城市中受限、效果受气候影响。海绵城市即是绿色基础设施理念在城市雨洪管理中的应用。"},{"id":"48.1","t":"生态系统管理的定义与目标","s":3,"c":"48. 生态系统管理与收获理论","x":"生态系统管理（ecosystem management）指基于生态学知识与社会目标的整合，对生态系统进行长期的、适应性的调控，以维持其结构、功能与服务。与传统资源管理的区别在于：（1）以生态系统整体而非单一物种或产品为对象；（2）考虑长期与多尺度；（3）强调人类是生态系统的组成部分而非外部干扰；（4）强调适应性管理与多方参与。目标通常包括维持生物多样性、维持生产力与生态过程、维持生态系统服务与社会公平。"},{"id":"48.2","t":"最大持续产量（MSY）","s":3,"c":"48. 生态系统管理与收获理论","x":"最大持续产量指在不损害种群再生能力前提下可长期维持的最大收获量。在逻辑斯蒂增长模型中，种群增长速率在 N=K/2 时最大，为 rK/4，因此MSY=rK/4，对应的种群水平为 N=K/2。MSY 的政策含义是把种群维持在 K/2附近即可获得最大持续收获，但实践中的困难包括：K 与 r 难以准确估计、环境波动使 K 变动、捕捞选择性强（先捕大个体导致种群结构改变）、以及\"经济与政治压力导致过度捕捞\"。联合国海洋法公约与各国渔业法普遍以 MSY 为管理目标，但 1990 年代以来更多倡导\"基于生态系统的渔业管理\"（EAF）与预防性原则。"},{"id":"48.3","t":"MSY 的局限与过度捕捞","s":3,"c":"48. 生态系统管理与收获理论","x":"MSY 的实践失败被称为\"MSY 的悲剧\"，原因包括：（1）参数不确定性，估计值偏高会导致系统性过度捕捞；（2）环境波动，按固定配额在低产年份会造成过度捕捞；（3）选择性捕捞导致种群结构小型化与早熟化（渔业诱导演化）；（4）混捕与丢弃，非目标种被误捕；（5）经济驱动的\"捕捞竞赛\"；（6）补贴与非法捕捞。改进措施包括：设定低于 MSY 的目标（如0.8×MSY）、设置海洋保护区（禁捕区）、采用个体可转让配额（ITQ）、按生态系统阈值设定捕捞上限、以及动态调整。"},{"id":"48.4","t":"收获理论的其他模型","s":2,"c":"48. 生态系统管理与收获理论","x":"除逻辑斯蒂型 MSY 外，常用模型还包括：（1）Beverton-Holt 模型与Ricker 模型，用于描述亲体—补充量关系（stock-recruitment），当亲体量过低时补充量急剧下降（\"补充限制\"）；（2）产量—努力量模型，用单位努力捕获量（CPUE）作为种群丰度的指标，CPUE 持续下降是过度捕捞的早期信号；（3）年龄结构模型（虚拟种群分析 VPA），用于评估各年龄组的捕捞死亡系数；（4）管理策略评价（MSE），通过模拟不同管理规则在不同不确定性下的表现来选择稳健策略。"},{"id":"48.5","t":"适应性管理与监测","s":3,"c":"48. 生态系统管理与收获理论","x":"适应性管理（adaptive management）指把管理措施当作\"实验\"，通过监测结果不断修正管理方案的学习型管理方式。其循环为：明确目标→建立模型与备选方案→实施并监测→评估与修正。适应性管理的两个层次：被动适应（边做边学，事后修正）与主动适应（有意设计不同处理以加速学习）。实施障碍包括监测经费不足、时间滞后、以及利益相关方对\"试验\"的抵触。竞赛中\"生态系统管理为何要强调监测\"的答案即在于不确定性与学习的必要性。"},{"id":"48.6","t":"自然保护地体系与管理","s":2,"c":"48. 生态系统管理与收获理论","x":"我国自然保护地体系分为三类：国家公园（以保护具有国家代表性的自然生态系统为目的，实行最严格保护）、自然保护区（保护典型生态系统、珍稀物种与自然遗迹，分核心区、缓冲区、实验区）、自然公园（含森林公园、地质公园、海洋公园、湿地公园，兼顾保护与利用）。管理要点包括：划定边界与功能区、建立监测与巡护体系、社区共管与生态补偿、旅游容量控制、以及跨区域协调。国际上还有\"其他有效区域保护措施\"（OECM）与生物圈保护区（核心区—缓冲区—过渡区）模式。"},{"id":"48.7","t":"生态红线与国土空间管控","s":2,"c":"48. 生态系统管理与收获理论","x":"生态保护红线指在生态空间范围内具有特殊重要生态功能、必须强制性严格保护的区域，包括水源涵养、生物多样性维护、水土保持、防风固沙、海岸防护等功能区与生态敏感脆弱区。管控要求是\"红线内禁止不符合主体功能定位的开发建设活动\"。与之配套的是\"三区三线\"（城镇空间、农业空间、生态空间；城镇开发边界、永久基本农田、生态保护红线）的国土空间规划体系。生态红线的生态学依据是：关键生态功能区不可替代、且其丧失具有不可逆性。第九篇 备考"},{"id":"49.1","t":"概念性错误（第 1~8 条）","s":3,"c":"49. 高频易错辨析","x":"（1）\"K 值是固定不变的\"——错。K 由资源、空间、天敌、疾病共同决定，随环境改变而改变，改善环境可提高 K。（2）\"r 对策者繁殖力强所以竞争力强\"——错。r 对策者在高密度下竞争能力弱，其优势在于快速占领空缺生境。（3）\"竞争排斥意味着必然有一方灭绝\"——错。排斥的前提是环境稳定、资源有限、生态位完全重叠；自然界的干扰、捕食与空间异质性常使重叠物种共存。（4）\"生态位重叠必然导致竞争\"——错。只有资源有限时重叠才转化为竞争，资源过剩时重叠可无竞争。（5）\"生态位就是生境\"——错。生境是\"地址\"，生态位是\"多维度资源利用与功能角色\"。（6）\"群落就是生态系统\"——错。群落只含生物成分，生态系统还包括非生物环境并强调能流与物质循环。（7）\"种群是由同种个体随机堆集而成\"——错。种群具有密度、年龄结构、性别比、空间格局等群体特征，且是进化的基本单位。（8）\"物种丰富度越高，多样性一定越高\"——错。多样性同时取决于丰富度与均匀度，S 高但极度不均匀时 H' 可能低于 S 低而均匀的群落。"},{"id":"49.2","t":"数值与公式错误（第 9~16 条）","s":3,"c":"49. 高频易错辨析","x":"（9）\"10% 定律是精确常数\"——错。Lindeman 效率是营养级间传递效率的平均值，范围约 5%~20%，海洋偏高、陆地森林常偏低。（10）\"10% 定律指能量利用了 10%\"——错。它指后一营养级生产量占前一营养级生产量的比例，而非同化率或利用率。（11）\"逻辑斯蒂增长在 N=K 时增长最快\"——错。增长最快在 N=K/2，速率为 rK/4；N=K 时增长率为 0。（12）\"内禀增长率 r越大，种群最终数量越大\"——错。r 决定增长速度，K 决定最终数量，二者独立。（13）\"λ 与 r 是同一个参数\"——错。λ=er，λ 是周限（离散）增长率，r是瞬时增长率。（14）\"-3/2 自疏法则的斜率是 -1.5 时，密度增加 4 倍个体重降为 1/2\"——错。应为降为 1/8（4^-1.5=1/8）。（15）\"生物量金字塔可以倒置所以能量金字塔也可以倒置\"——错。能量金字塔不可倒置，因违反热力学第二定律；数量与生物量金字塔可倒置。（16）\"种—面积关系中 z 值是固定的\"——错。大陆约 0.12~0.17，岛屿约 0.25~0.35，随类群与尺度变化。"},{"id":"49.3","t":"过程与机制错误（第 17~26 条）","s":3,"c":"49. 高频易错辨析","x":"（17）\"碳循环属沉积型\"——错。碳循环主要储库是大气与海洋，属气态型；磷循环无气相，属典型沉积型。（18）\"磷循环与碳循环一样可全球快速循环\"——错。磷靠岩石风化缓慢释放，循环慢且区域性强，是淡水首要限制因子。（19）\"氮循环中硝化作用是把硝酸盐还原为氮气\"——错。硝化是NH₄⁺→NO₂⁻→NO₃⁻（氧化），反硝化才是 NO₃⁻→N₂/N₂O（还原）。（20）\"固氮作用只能由根瘤菌完成\"——错。还有自生固氮菌（Azotobacter）、蓝细菌（念珠藻）、放线菌（Frankia）与共生体系（如满江红与鱼腥藻）。（21）\"演替顶极只有一个\"——错。单元顶极论认为只有一个气候顶极，多元顶极论与顶极格局假说分别主张多顶极与连续格局，三种学说并存。（22）\"原生演替一定比次生演替快\"——错。原生演替始于无土壤裸地，需先成土，速度远慢于次生演替。（23）\"促进模型、抑制模型、耐受模型互斥\"——错。同一演替过程的不同阶段可以不同机制为主，三者可共存。（24）\"岛屿面积越大物种数越多是因为定殖率更高\"——错。面积主要降低灭绝率，距离才主要影响定殖率。（25）\"臭氧层空洞是全球均匀的\"——错。南极春季最严重，因极低平流层温度、极地平流层云与极涡隔离三个条件共同作用。（26）\"温室效应是人为造成的污染现象\"——错。温室效应是自然现象，是生命存在的前提；人类活动是\"增强\"了温室效应。"},{"id":"49.4","t":"判断类错误（第 27~34 条）","s":3,"c":"49. 高频易错辨析","x":"（27）\"能量金字塔与数量金字塔都不可以倒置\"——错。能量金字塔不可倒置；数量金字塔可倒置（一棵树—大量昆虫）；生物量金字塔也可倒置（海洋浮游植物现存量小于浮游动物）。（28）\"海洋生物量金字塔倒置说明能量传递效率超过 100%\"——错。原因是浮游植物周转极快（数天），现存量小但年生产量大，倒置是\"现存量\"而非\"能量\"的倒置。（29）\"滞育与休眠是同一概念\"——错。滞育由光周期等预告信号诱导、有固定期限、需特定条件解除；休眠与静育是条件不利时的被动停滞，条件改善即恢复。（30）\"贝格曼规律适用于所有动物\"——错。仅适用于内温动物（鸟类与哺乳类），变温动物不适用。（31）\"生态入侵成功说明入侵种适应能力强\"——错。成功更多源于天敌释放、资源过剩、空生态位与繁殖扩散特性，\"适应能力强\"只是其中一个可能因素。（32）\"边缘效应总是提高物种多样性\"——错。对内部种而言边缘是劣质生境，边缘效应可能为负。（33）\"多样性越高系统越稳定\"——错。May 的模型显示随机参数下复杂性降低稳定性，实际关系取决于相互作用强度与功能冗余，需区分抵抗力与恢复力。（34）\"最大持续产量就是最大产量\"——错。MSY 是在不损害再生能力前提下的最大可持续收获，对应 N=K/2、产量 rK/4，短期最大产量可能远高于 MSY 但不可持续。"},{"id":"49.5","t":"易混术语对照表","s":3,"c":"49. 高频易错辨析","x":"（35）竞争排斥 vs 生态位分化：前者是竞争的结果（一方被排除），后者是共存的结果（重叠降低）。（36）基础生态位 vs 实际生态位：前者由生理耐受决定，后者受生物相互作用压缩。（37）集合种群 vs 源—汇种群：前者强调斑块间灭绝—定殖动态，后者强调斑块内出生率与死亡率的差异。（38）初级生产 vs 次级生产：前者是自养固定，后者是异养转化。（39）GPP vs NPP vs NEP：GPP 是总固定，NPP=GPP-自养呼吸，NEP=NPP-异养呼吸。（40）生物积累 vs 生物放大：前者是个体内累积，后者是沿食物链浓度递增。（41）抵抗力 vs 恢复力：前者抗扰动不变，后者受扰后恢复快，二者常权衡。（42）富营养化 vs 赤潮：前者是水体营养盐过量导致的藻类过度繁殖过程，后者是海域中浮游生物暴发性增殖的现象（可由富营养化引起）。（43）生态型 vs 亚种：生态型是适应不同环境的遗传变异类群且可杂交，亚种有地理分化且常为分类单位。（44）就地保护 vs 迁地保护：前者在原生生境保护生态系统与种群，后者移出生境人工保存。"},{"id":"49.6","t":"计算题与实验题中的高频陷阱（第 45~48 条）","s":3,"c":"49. 高频易错辨析","x":"（45）\"标志重捕法中 N=MC/R 可以直接使用\"——需加前提：种群封闭、标志不影响存活、标志个体与未标志个体混合均匀；若标志导致死亡率升高，则 R 偏小、N 被高估。（46）\"生命表中 l_x 是死亡率\"——错。l_x 是存活率，q_x 才是死亡率（q_x=d_x/n_x），二者互补关系为 l_x+q_x 的前期累积并不等于 1。（47）\"Lindeman 效率可用同化量之比直接计算\"——需明确比较对象，效率应统一用\"生产量/生产量\"或\"同化量/同化量\"，分子分母指标不同会造成错误。（48）\"物种数相同的两个群落多样性相同\"——错。即使 S 相同，多度分配不同则 H' 与 D 显著不同，须同时计算均匀度。"},{"id":"50.1","t":"种群增长模型对照表","s":3,"c":"50. 速查表","x":"八种常用增长模型的表达式、假设与平衡点集中对照，判断题目类型时先看\"有无密度制约项\"与\"是否有饱和\"。模型表达式假设条件曲线形状平衡点指数增长（连续）dN/dt=rN，N_t=N_0ert资源无限、无密度制约J型无（N→∞）指数增长（离散）N_t=N_0λt，λ=er世代不重叠、资源无限阶梯上升无逻辑斯蒂增长dN/dt=rN(K-N)/K密度制约线性、无时滞S型N=K（稳定）离散逻辑斯蒂N_(t+1)=N_t[1+r(1-N_t/K)] dN/dt=rN(1-N/K) (N/A-1) dN1/dt=r1N1(K1N1-αN₂)/K1离散繁殖周期或混沌随 r 变化低密度适合度下降有灭绝阈值N=K 与 N=A竞争系数恒定四种结局依K与α捕食者—猎物dN/dt=rN-aNP；dP/dt=baNP-mP无密度制约、无饱和中性环N=m/(ba)，P=r/a集合种群（Levins）dP/dt=cP(1-P)-eP斑块等价单调趋平衡P*=1-e/c含 Allee 效应种间竞争"},{"id":"50.2","t":"种间关系速查表","s":3,"c":"50. 速查表","x":"按\"+\"、\"-\"、\"0\"两个方向记忆六类关系的符号组合，再用实例反查，是选择题最快的判定路径。举例关键判断竞争关系-/-符号有害对种群 1有害对种群 2两种草履虫、作物与杂草资源有限且共同利用捕食+/-有利有害狼与兔、瓢虫与蚜虫直接杀死并取食寄生+/-有利有害菟丝子、蛔虫、寄生蜂寄生于体内外，不立即杀死互利共生+/+有利有利地衣、菌根、榕树与榕小蜂双方适合度均升高偏利共生+/0有利无影响附生植物、鮣鱼与鲨鱼一方获益一方不受影响偏害作用-/0有害无影响胡桃醌抑制其他植物他感作用中性0/0无影响无影响同域但无资源重叠需实验验证"},{"id":"50.3","t":"主要生物群系速查表","s":3,"c":"50. 速查表","x":"八个群系按\"气候—植被—动物—土壤\"四要素对照，注意土壤肥沃程度与有机质积累方向的相反关系。植被特征动物特征土壤热带雨林群系高温多雨无旱季气候特征常绿阔叶、多层、板根、藤本附生树栖、多样、色彩鲜艳贫瘠、酸性、养分在生物体内热带稀树草原干湿季分明C4 草与散生乔木、大型植食兽与猛兽有干季淋溶火适应亚热带常绿阔叶林温暖湿润革质常绿叶、结构较简单多样性中等红壤、酸性温带落叶阔叶林四季分明夏绿、季相明显有冬眠与迁徙棕壤、较肥沃北方针叶林冬季严寒、生长季短针叶、塔形、凋落物难分解驼鹿、貂、狼灰化土、强酸性温带草原降水 250~800 mm多年生草本、深根穴居啮齿、大型有蹄类黑土、最肥沃荒漠降水小于 250 mm、温差大稀疏、肉质或深根、短命植物夜行、节水贫瘠、盐碱化苔原最热月小于 10℃、冻土苔藓地衣矮灌木、无乔木驯鹿、旅鼠、候鸟有机质积累、缺氧"},{"id":"50.4","t":"物质循环速查表","s":3,"c":"50. 速查表","x":"五种元素的循环类型是判断\"全球性还是区域性环境问题\"的关键，碳、氮、水为气态型，磷为沉积型。主要储库关键过程限制性人类干扰碳元素气态型循环类型岩石、海洋、大气光合、呼吸、溶解、沉积光、氮、磷化石燃料、毁林氮气态型大气（N₂）固氮、硝化、反硝化、氨化温带陆地首要工业固氮、氮沉降磷沉积型岩石、沉积物风化、吸收、沉淀淡水首要磷矿开采、富营养化硫气态兼沉积型岩石、化石燃料氧化、还原、DMS 排放局部燃煤 SO₂、酸雨水气态型海洋、大气、冰川蒸发、降水、径流、蒸腾干旱区首要灌溉、水库、毁林"},{"id":"50.5","t":"生态效率与生产力的关键数值","s":3,"c":"50. 速查表","x":"本表数值均为教材通行值，竞赛判断题常直接考数量级，建议记到\"十倍以内\"即可判断选项真伪。项目数值说明全球陆地 NPP约 100~110 Pg C/a 1 Pg=10¹⁵ g全球海洋 NPP约 50~60 Pg C/a受营养盐与光限制Lindeman 效率平均约 10%（5%~20%）营养级间传递效率同化效率（肉食）约 80%食物易消化同化效率（植食）约 20%~50%含纤维素与木质素生产效率（内温动物）约 1%~3%大量能量用于维持体温生产效率（外温动物）约 10%~40%无需维持体温大气 CO₂ 浓度约 415 μL/L工业化前约 280大气碳库约 850 Pg C周转时间约 7 年土壤碳库约 1 500~2 400 Pg C高纬湿地与冻土为主"},{"id":"50.6","t":"群落与演替速查表","s":3,"c":"50. 速查表","x":"群落结构、多样性指数、演替系列与顶极学说的要点集中于此，适合考前一周快速过一遍。项目内容关键数值或判断群落基本特征物种组成、结构、群落环境、动态、分布范围、边界过渡性六项，最本质是物种组成垂直结构乔木层、灌木层、草本层、地被层光强随深度指数衰减 I=I0·e^-kL频度定律A>B>C>D<E五级各占 20% 时为标准格局重要值三者之和为 300% Shannon 指数（相对密度+相对频度+相对优势度）/3 H'=-ΣP_i·lnP_i Simpson 指数D=1-ΣP_i²对优势种敏感均匀度J=H'/lnS取值 0~1β 多样性β=γ/ᾱ 或 (S/ᾱ)-1反映生境间更替种—面积关系S=cAz原生演替（旱生）地衣→苔藓→草本→灌木→乔木大陆 z 约 0.12~0.17；岛屿约0.25~0.35需数百年至千年原生演替（水生）裸底→沉水→浮叶→挺水→湿生草本→木本湖泊填塞沼泽化次生演替一年生杂草→多年生草本→灌木→乔木森林恢复约 100~200 年演替三机制促进、抑制、耐受Connell 与 Slatyer 1977顶极三学说单元顶极、多元顶极、顶极格局岛屿平衡模型定殖率下降、灭绝率上升的交点Clements、Tansley、Whittaker面积效应与距离效应对稀有种敏感"},{"id":"51.1","t":"三阶段复习路线","s":3,"c":"51. 复习路线与答题策略","x":"第一阶段（约 6 周）通读本总纲第一篇至第六篇，目标是建立层次框架与模型清单，每章只记\"3 个公式 + 3 个数值 + 1 个经典实验\"。第二阶段（约 4周）精读第七篇与第八篇，把全球变化与应用生态的名词与机制做成卡片，并练习\"给现象找机制\"的题目。第三阶段（约 3 周）集中攻克第九篇的 48 条易错辨析与 6 张速查表，配合历年真题做专项纠错。全程建议每两天做一次\"闭卷复述\"：任选一个知识点，白纸写出定义、机制、数值、例证四要素。"},{"id":"51.2","t":"计算题的常考类型与解法","s":3,"c":"51. 复习路线与答题策略","x":"常考计算类型：（1）种群增长，指数增长用 N_t=N_0ert，倍增时间0.693/r；逻辑斯蒂用 N_t=K/(1+exp(a-rt))，注意拐点 N=K/2、最大速率rK/4；（2）生命表计算，l_x、q_x、R_0=Σl_xm_x、T=Σxl_xm_x/Σl_xm_x、r≈lnR_0/T；（3）标志重捕，N=MC/R，注意标志个体需充分混合；（4）能量传递，按 Lindeman 效率逐级相乘，注意区分\"生产量\"与\"同化量\"；（5）种—面积关系，用 S=cAz 与对数形式求物种丧失比例；（6）竞争模型判定，比较 K1 与 K2/α21、K2 与 K1/α12；（7）多样性与均匀度，Shannon 与Simpson 按比例计算；（8）-3/2 自疏，用 W=C·N^-1.5 求个体重变化。计算题的共同陷阱是单位与量纲，务必先统一单位再代入。"},{"id":"51.3","t":"实验设计题的答题模板","s":3,"c":"51. 复习路线与答题策略","x":"答题模板分五步：（1）提出问题与假设，要写成可检验的陈述句，并指明预测方向；（2）确定自变量、因变量与控制变量，自变量需设置梯度（一般3~5 个水平）；（3）设置对照与重复，说明对照类型（空白、处理、相互对照）与重复数（不少于 3）；（4）说明观测指标与记录方法，指标要客观可测（存活率、生物量、物种数、叶绿素含量）；（5）预期结果与结论的对应关系，明确\"若结果为 A 则支持假设 1，若为 B 则支持假设 2\"。若题目要求评价他人实验，从\"对照缺失、重复不足、未随机化、单一尺度、混杂变量未控制、统计方法不当\"六个角度逐条检查。"},{"id":"51.4","t":"图表题的判读要点","s":3,"c":"51. 复习路线与答题策略","x":"（1）先看坐标轴与单位，明确自变量与因变量，注意是否为对数坐标（对数坐标下直线表示指数关系）；（2）看曲线的关键点，如起点、拐点（K/2 处增长最快）、饱和点（光饱和点或捕食饱和）、交点（补偿点、竞争平衡点）；（3）看曲线的斜率，斜率即速率（增长率、分解速率、光合速率）；（4）看曲线的相位关系，捕食者峰值滞后于猎物峰值；（5）注意曲线的可倒置性（数量金字塔与生物量金字塔可倒置，能量金字塔不可）；（6）警惕\"看起来相关就断定因果\"的选项，尤其是仅有一条曲线而无对照的题目。"},{"id":"51.5","t":"简答题的得分结构","s":3,"c":"51. 复习路线与答题策略","x":"简答题的得分点通常分布为\"概念—机制—数值或实例—意义\"四段。以\"为什么能量金字塔不能倒置\"为例：先答能量流动的单向性与逐级递减（概念），再答热力学第二定律与呼吸消耗（机制），再答 10% 效率的数值（数值），最后答营养级数受限与顶级捕食者稀少的现实意义（意义）。答题时应分点书写（用（1）（2）（3）），每点一句话到位，避免长段落堆砌；若时间紧，宁可少写点也要写全关键词，因为阅卷按关键词给分。"},{"id":"51.6","t":"常见命题陷阱清单","s":3,"c":"51. 复习路线与答题策略","x":"（1）绝对化表述，\"必然\"\"一定\"\"总是\"\"完全\"多为错误选项；（2）概念替换，把\"群落\"换成\"生态系统\"、把\"生物量\"换成\"能量\"、把\"同化量\"换成\"生产量\"；（3）方向反转，把\"正反馈\"与\"负反馈\"、\"气态型\"与\"沉积型\"、\"抵抗力\"与\"恢复力\"对调；（4）单位陷阱，g/(m²·a) 与 kg/(ha·a) 混用，kJ 与 cal混用；（5）前提缺失，竞争排斥原理省略\"环境稳定、资源有限\"的前提即为错；（6）张冠李戴，把 Lindeman 的效率说成 Elton 的、把岛屿理论说成集合种群理论；（7）因果倒置，把\"边缘多样性高\"当成\"边缘效应必然为正\"的证据。"},{"id":"51.7","t":"学科交叉与前沿要点的准备","s":2,"c":"51. 复习路线与答题策略","x":"近年竞赛的生态学部分常与下列内容交叉：（1）与进化生物学结合，如红皇后假说、性选择、协同进化、生活史权衡；（2）与生理学结合，如植物的耐旱与耐盐机制、动物的渗透调节与体温调节；（3）与分子生物学结合，如eDNA 监测、分子标记与遗传多样性、稳定同位素分析；（4）与全球变化结合，如碳源汇、海洋酸化、物候错配、生态系统稳态转换；（5）与数学结合，如模型稳定性分析、矩阵模型、集合种群方程。建议在复习时对每个交叉点准备\"一个机制 + 一个实例 + 一个数值\"，即足以应对综合题。附录：知识库教材索引本总纲的体系与内容依据以下五部教材整理，均取自五个生物竞赛知识库中的原文，章节对应关系如下表。凡教材表述有差异之处（如 Lindeman 效率的具体数值范围、演替顶极学说的表述、群落分类学派名称），本总纲均采用通行教材的表述，并在正文中保留了可比较的关键数据。教材版本与出版信息主要对应篇章本总纲采用的体系李博主编《生态学》高等教育出版社，面向21 世纪课程教材，共 16章第一篇至第六篇主教材骨架，章序按个体—种群—群落—生态系统—景观展开孙儒泳等《基础生态学》第 3 版，高等教育出版社，共 17 章第一篇至第七篇六部分结构（有机体与环境、种群、群落、生态系统、应用、现代发展）Smith & Smith《Elements of Ecology》第 9 版，Pearson，第二篇、第五篇、第七篇物理环境—适应—种群—相互作用—群落—生态系统—生物地理的层次框架Begon 等《Essentials of Ecology》第 4 版，Wiley，2014第三篇、第四篇、第八篇进化视角下的生活史、种间关系与应用生态学组织方式吴相钰、陈阅增《普通生物学》第 4 版，高等教育出版社，生态学与动物行为篇第一篇、第五篇、第六篇中学生物学教材衔接的概念表述与知识深度教材与章的具体对应：（1）生态学定义与层次、发展史、研究方法对应李博第一章与孙儒泳绪论；（2）生态因子、限制因子与耐受定律对应李博第二章第三、四节与孙儒泳第 1 章 1.3；（3）光、温度、水、土壤因子对应孙儒泳第2 章与第 3 章（\"能量环境\"与\"物质环境\"的划分方式）；（4）生活史对策与休眠滞育对应李博第四章与孙儒泳第 6 章；（5）生态位与种间关系对应李博第五章与孙儒泳第 7 章；（6）生命表、增长模型、种群调节、集合种群对应李博第三章与孙儒泳第 4 章；（7）群落组成、结构、多样性对应李博第六章与孙儒泳第 8 章；（8）群落动态、演替顶极学说对应李博第七章与孙儒泳第 9 章；（9）群落分类与排序对应李博第八章与孙儒泳第 10 章（数量分类与间接/直接梯度分析）；（10）生态系统组成、食物链、生态金字塔、生态效率对应李博第九章与孙儒泳第 11 章；（11）初级生产、次级生产、分解、能流对应李博第十章与孙儒泳第 12 章；（12）物质循环对应李博第十一章与孙儒泳第 13 章（含\"气体型循环\"与\"沉积型循环\"的划分）；（13）陆地与水域生态系统类型对应李博第十二、十三章与孙儒泳第 14 章；（14）景观、尺度与格局对应李博第十四章与孙儒泳第 17 章；（15）全球变化、生物多样性保护、可持续发展对应李博第十五章与孙儒泳第 15 章；（16）生态风险与生态规划对应李博第十六章；（17）应用生态学中的农业生态、有害生物防治、收获理论、生态系统管理对应孙儒泳第 15 章 15.3、15.7、15.8、15.6 各节。使用本索引时可以按\"竞赛考点—教材章节\"双向检索：准备某一专题时先查本总纲的知识点编号，再回到上表定位教材章节精读原文；反之精读教材某章后，可用本总纲的星级标注判断该内容的竞赛权重，从而决定投入时间。凡本总纲与教材表述不一致之处，建议以教材原文为准，并在笔记中标注差异，这也是竞赛备考中\"以一本教材为准、多本教材互补\"的基本策略。补充说明：上述教材中李博《生态学》与孙儒泳《基础生态学》的中文名词体系基本一致，英文教材（Smith & Smith、Begon）在部分概念上有不同侧重，例如英文教材更强调\"生态学是科学的（scientific）而非仅描述性的\"、更早引入\"生态系统服务\"与\"气候变化\"的内容，并把\"生活史与进化\"置于种群生态学之前。本总纲在编排上兼顾了两类体系：主线按中文教材的层次框架，但在相应知识点中补充了英文教材的概念（如营养级位 trophic position、生态效率的四种类型、适应性与非平衡观点），以便应对竞赛中出现的英文术语与图示题。本总纲共九篇五十一章，覆盖个体生态、种群生态、种间关系、群落生态、生态系统、生物圈与全球变化、应用生态与备考八个板块。建议读者以\"章\"为单位组织复习单元，每章配一张手绘思维导图与一组自测题，形成\"读—写—测\"闭环。凡涉及数值的内容（K 值、Lindeman 效率、NPP、碳库、50/500 法则、z 值）务必记到数量级，因为竞赛的判断题与计算题高度依赖对数量级的敏感度。"}]
window.KG_BOOK["12"]=[{"id":"1.1","t":"系统学的三项任务","s":3,"c":"1. 系统学的任务与范畴","x":"系统学的任务可概括为三项彼此衔接的工作：鉴定（identification，判断一份标本属于哪个已命名的类群）、分类（classification，把物种归入按阶元排列的等级体系并命名）、系统发生（phylogeny，重建类群间的分支关系与演化历史）。三者不可互相替代：鉴定只需\"对号入座\"，分类要求体系的稳定与信息含量，系统发生则追问\"为什么这样分\"。竞赛题中常见\"鉴定即分类\"\"分类即系统发生\"的错误等同，须以任务对象与产出物加以区分。任务回答的问题主要产出常用方法鉴定这份标本是什么物种名称或待定名检索表、模式标本比对、DNA 条形码分类它在体系中处于何位置阶元归属、学名、志书条目性状分析、单系群划分、命名法规系统发生它与其他类群如何相关系统树、分支图、分歧时间支序分析、分子数据建树"},{"id":"1.2","t":"分类学的信息容器功能","s":2,"c":"1. 系统学的任务与范畴","x":"分类系统是生物学最大的信息检索系统：一个学名一旦确定，就自动携带该物种的形态描述、分布、生活史、遗传数据与文献出处。分类修订（revision）之所以重要，是因为它同时改写了信息的\"索引号\"，使此后的所有研究共享同一检索入口。因此分类学的价值并不在\"起名字\"，而在于建立可累积、可全球共享的知识索引。"},{"id":"1.3","t":"鉴定与分类的逻辑区别","s":3,"c":"1. 系统学的任务与范畴","x":"鉴定是\"由个体到类群\"的收敛过程，其判据是检索特征是否吻合；分类是\"由类群到体系\"的建构过程，其判据是类群的单系性与阶元的合理性。一个人可以熟练鉴定而不懂分类学（如按图鉴使用检索表），但不可能在不懂分类学的前提下作可靠鉴定，因为检索表本身建立在分类修订之上。分子鉴定同样需要分类学背景：数据库中的参考序列若源自错误鉴定的凭证标本，条形码只会把错误放大。"},{"id":"1.4","t":"系统发生学的研究对象","s":3,"c":"1. 系统学的任务与范畴","x":"系统发生学研究的是类群之间的分支关系（branching relationships），而不是\"谁更进步\"\"谁更高等\"。分支关系由共同祖先的远近决定，用节点与分支表达；\"高等/低等\"是承载价值判断的旧术语，在现代系统学中应代之以\"衍生的/原始的（apomorphic/plesiomorphic）\"或\"冠部的/基部的（crownward/basal）\"。必须牢记：系统发生关系只谈相对近缘，不谈绝对优劣。"},{"id":"1.5","t":"分类阶元的信息编码作用","s":2,"c":"1. 系统学的任务与范畴","x":"阶元（category）本身不携带演化信息，只提供等级化的容器；但它通过\"同一科内物种共享科级特征\"这一约定，间接编码了大量比较信息，使分类系统在无数据库时代即可用于推断。这也解释了为什么支序分类学派反对随意调整阶元——一旦阶元与分支顺序脱节，体系的信息含量即下降。"},{"id":"1.6","t":"系统学与邻近学科的关系","s":1,"c":"1. 系统学的任务与范畴","x":"系统学与演化生物学共享\"共同祖先\"这一前提，但前者关注格局（pattern），后者关注过程（process）；与生态学共享物种作为研究单元，但系统学提供的是历史维度；与遗传学的关系在分子系统学中尤为紧密，溯祖理论（coalescent theory）即为二者的接口。现代系统学还大量借用统计学与计算机科学，其建树算法本质上是组合优化与贝叶斯推断问题。"},{"id":"1.7","t":"系统学工作的标准流程","s":2,"c":"1. 系统学的任务与范畴","x":"一次完整的系统学工作大致按以下顺序推进：采集与凭证保存、性状与分子数据获取、同源判定与性状编码、极性判定（外群比较）、矩阵构建与比对、建树与支持度评估、假设检验与稳健性检查、分类处理与命名。流程中任一环节出错都会传导至结论，其中\"同源判定\"与\"极性判定\"是最易被忽略、后果最严重的两步。"},{"id":"1.8","t":"系统学结论的检验标准","s":2,"c":"1. 系统学的任务与范畴","x":"系统学假说的检验依赖三条：可重复性（数据与参数公开，他人可重跑）、稳健性（换数据、换方法、换取样后拓扑不崩）、可反驳性（支持度低的分支应明确标注为未解决，而非强行合并）。一个只有单一基因、单一方法、无支持度值的树，在竞赛材料题中应被判为证据不足。"},{"id":"2.1","t":"史前与古代的分类实践","s":1,"c":"2. 分类学史","x":"人类早期的分类以用途为标准，如《神农本草经》按三品分药、亚里士多德按\"有血/无血\"与运动方式分动物。这一阶段的分类是\"人为分类\"（artificial classification），其判据是实用而非亲缘。理解这一点有助于说明：分类系统并非天然存在，而是人为建构并被证据不断修正的模型。"},{"id":"2.2","t":"林奈与《自然系统》","s":3,"c":"2. 分类学史","x":"林奈（C. Linnaeus）在《自然系统》（Systema Naturae，第 10 版1758）与《植物种志》（Species Plantarum，1753）中确立了三项遗产：双名法、阶元等级体系、以及以模式标本为名称载体的实践。动物命名法规以1758 年 1 月 1 日为起点，植物命名法规以 1753 年 5 月 1 日为起点，正是对这两部著作的追认。林奈的分类以\"雄蕊数目\"等人为性状分纲，属典型的人为分类。"},{"id":"2.3","t":"林奈体系的人为性","s":2,"c":"2. 分类学史","x":"林奈的分纲标准（如植物按雄蕊数目与着生方式）导致大量亲缘关系很远却\"数目相同\"的类群被合并，例如把雄蕊数目相同的不同科放在同一纲。这说明分类的可靠性取决于所选性状是否同源、是否稳定，而非体系是否整齐。后人称其为\"性系统\"（sexual system），正是对其人为性的评价。"},{"id":"2.4","t":"达尔文与自然分类的思想转折","s":3,"c":"2. 分类学史","x":"《物种起源》（1859）提出共同祖先与自然选择，使\"自然分类\"有了理论依据：真正的自然分类应反映血统，而非表面相似。达尔文指出分类学家的分组\"若血统不同则不成其为自然\"，这一论断把分类从\"整理\"变成\"假说检验\"。自此，相似性不再是终点，而成为推断亲缘的证据之一。"},{"id":"2.5","t":"进化论之后的分类困境","s":2,"c":"2. 分类学史","x":"达尔文之后近百年，分类学在\"依据相似性\"与\"依据血统\"之间缺少可操作的方法：分类学家依靠经验判断\"总体相似\"，导致同一类群在不同作者笔下范围不一。困境的实质是：相似性既可能来自共同祖先（同源），也可能来自趋同（同功），而当时缺乏区分二者的程序化手段。"},{"id":"2.6","t":"Hennig 与支序学的诞生","s":3,"c":"2. 分类学史","x":"德国昆虫学家 W. Hennig 在《系统发生系统学》（Phylogenetic Systematics，1950 年德文版、1966 年英文版）中提出：只有共享的衍生性状（synapomorphy，共同衍征）才能证明单系群，而共享的原始性状（symplesiomorphy）不能。他由此确立了\"性状极性判定—分支分析—仅命名单系群\"的完整程序，被称为支序学（cladistics）或系统发生系统学。这是分类学史上从\"相似性排序\"到\"分支关系推断\"的方法论革命。"},{"id":"2.7","t":"数值分类学的兴起","s":2,"c":"2. 分类学史","x":"20 世纪 60 年代，Sokal 与 Sneath 出版《数值分类学原理》（Principles of Numerical Taxonomy，1963），主张把尽可能多的性状等权编码，用相似系数与聚类算法自动生成分类，以避免主观加权。数值分类推动了计算机在分类学中的应用，并催生了表相图（phenogram）；但其\"等权、总体相似\"的前提，恰恰被支序学派批评为混淆同源与同功。"},{"id":"2.8","t":"分子系统学的兴起","s":3,"c":"2. 分类学史","x":"20 世纪 60 年代蛋白质电泳与免疫学开启了分子层面的比较；70—80 年代DNA 杂交与序列测定使系统学进入\"字符\"时代；1985 年后 PCR 与自动测序普及，rDNA、mtDNA 序列成为常规数据；21 世纪以来基因组、转录组与超保守元件（UCE）数据的应用，使系统发生基因组学（phylogenomics）成为主流。分子数据提供了大量独立于形态的字符，也带来了模型选择、饱和、长枝吸引等新问题。"},{"id":"3.1","t":"表征分类学派的主张","s":3,"c":"3. 三大分类流派与现代地位","x":"表征分类（phenetics，又称数值分类）主张按总体表型相似性分类，不对性状加权、不区分同源与同功，用相似系数与聚类算法（如 UPGMA、邻接法）生成树状图，并认为分类应只反映可观测的相似性、不涉及演化推测。其优点是客观、可重复、计算透明；缺点是趋同性状会被误当作亲缘证据，且\"等权\"本身也是一种未被证明的假设。"},{"id":"3.2","t":"支序分类学派的主张","s":3,"c":"3. 三大分类流派与现代地位","x":"支序分类（cladistics）主张只依据共同衍征建立类群，分类必须与分支图严格对应，只承认单系群为有效类群，姐妹群在等级上应并列。其优点是判据明确、可反驳、与演化理论一致；实践困难在于：树常有分辨率不足与支持度不高之处，且\"等级必须与分支顺序同步\"会造成大量阶元升降，影响名称稳定性。"},{"id":"3.3","t":"进化分类学派的主张","s":3,"c":"3. 三大分类流派与现代地位","x":"进化分类（evolutionary classification，代表人物 Simpson、Mayr）主张分类应同时反映两项信息：共同祖先（分支关系）与后续的分化程度（适应性进化量），因此容许并系群存在，如把爬行纲与鸟纲并列，理由是鸟类在形态与生态上已发生巨大跃迁。其优点是保留了传统体系的稳定性与信息直观性；缺点是被支序学派批评为判据不明确、无法检验。"},{"id":"3.4","t":"三派分歧的焦点","s":3,"c":"3. 三大分类流派与现代地位","x":"三派之争可归结为三问：性状是否加权（表征分类不加、进化分类隐性加、支序分类只承认衍征）、是否容许并系群（支序分类不容许）、分类与系统树是否必须一一对应（支序分类要求严格对应）。三派在今天并未\"一方胜出\"：日常分类实践中大量沿用进化分类的传统阶元，而所有新类群的合法性论证已普遍采用支序学语言。项目表征分类支序分类进化分类性状处理尽可能多、等权区分祖征与衍征，重衍征区分，并考虑进化量是否容许并系群容许（不自知）不容许容许聚类依据总体相似系数共同衍征血统 + 分化程度与树的关系表相图不等于系统树Sokal & Sneath 1963分类必须与树一致Hennig 1966可部分脱节代表文献Simpson 1961、Mayr"},{"id":"3.5","t":"单系原则的实践后果","s":2,"c":"3. 三大分类流派与现代地位","x":"若严格执行单系原则，传统\"爬行纲\"必须或并入鸟纲、或拆分为多个纲；\"鱼纲\"必须拆分为盲鳗纲、七鳃鳗纲、软骨鱼纲、辐鳍鱼纲、肉鳍鱼纲等；\"原生生物\"必须拆散到多个高阶层元。这些调整不是\"折腾\"，而是单系原则的逻辑结果。竞赛材料题常以\"某某传统类群是否单系\"设问，答题时应指出其并系或多系的具体原因。"},{"id":"3.6","t":"支序分类的等级处理争议","s":2,"c":"3. 三大分类流派与现代地位","x":"以 Hennig 命名法（顺序命名）为例，作者通过数字编号表达分支顺序（如 1、2.1、2.2…），以摆脱阶元束缚；而 PhyloCode（国际系统发生命名法规，2020）则尝试以\"节点命名\"取代阶元。这些方案在稳定性与可操作性上仍有争议，目前《国际动物命名法规》与《国际藻类、真菌和植物命名法规》仍以阶元体系为运行基础，故竞赛与教材仍使用传统阶元。"},{"id":"3.7","t":"系统学的现代地位","s":2,"c":"3. 三大分类流派与现代地位","x":"系统学是生物学的基础设施：生物多样性编目、保护优先区划定、入侵种与检疫对象识别、药物与基因资源的开发、乃至医学上的病原鉴定，都以准确的分类为前提。分子技术并未取代系统学，反而放大其重要性，因为序列数据的生物学意义必须挂靠在鉴定可靠的凭证标本与分类框架之上。"},{"id":"3.8","t":"DNA 条形码与系统学的普及","s":3,"c":"3. 三大分类流派与现代地位","x":"2003 年 Hebert 等提出以线粒体 cox1（COI）基因 5′端约 648 bp 片段作为动物\"条形码\"，随后 CBOL 推动全球条形码计划与 BOLD 数据库建设；植物因 cox1 变异过慢而改用 rbcL + matK（2009 年 CBOL 植物工作组建议）并辅以 ITS2、trnH-psbA。条形码把鉴定工作从\"专家依赖\"部分转为\"数据库比对\"，但也带来新风险：种内变异与种间变异重叠时阈值法失效，参考序列的错误鉴定会导致系统性误判。第二篇 分类学基础"},{"id":"4.1","t":"双名法的构成与书写","s":3,"c":"4. 分类阶元与学名","x":"学名（scientific name）由属名（首字母大写）与种加词（全小写）组成，印刷时整体斜体，命名人姓氏正体且动物中不缩写（如 Homo sapiens Linnaeus, 1758）、植物中按标准缩写（如 Oryza sativa L.）。分类学地位变动导致属名改变时，原命名人加括号（动物）或将原命名人置于括号内（植物），如 Panthera leo (Linnaeus, 1758) 表示该种最初置于其他属。常见错误包括：种加词首字母大写、命名人姓名斜体、把命名年份写在植物学名后（植物学名一般不写年份）。"},{"id":"4.2","t":"三名法与亚种","s":3,"c":"4. 分类阶元与学名","x":"当需要表示亚种时使用三名法（trinomen）：属名 + 种加词 + 亚种加词，如 Homo sapiens sapiens、Columba livia domestica 式的写法须注意家养型与亚种的区别。三名法只适用于种下具有地理分化且被正式命名的单元；亚种加词同样小写、同样斜体。动物学中三名法由 ICZN 规范，植物学中\"亚种\"（subsp.）与\"变种\"（var.）为不同等级，须用等级缩写标明，如Pinus sylvestris var. mongolica。"},{"id":"4.3","t":"基本阶元序列","s":3,"c":"4. 分类阶元与学名","x":"基本阶元自上而下为：界（Kingdom）、门（Phylum，植物称Division）、纲（Class）、目（Order）、科（Family）、属（Genus）、种（Species）。记忆口诀为\"界门纲目科属种\"；科名在动物中多由模式属词干加 -idae（如 Homo → Hominidae），植物中加 -aceae（如 Rosa →Rosaceae），目名动物加 -ida、植物加 -ales，均为规律性构词而非任意。"},{"id":"4.4","t":"辅助阶元与常用级别","s":2,"c":"4. 分类阶元与学名","x":"在基本阶元之间可插入辅助阶元，动物中常见\"总科（superfamily,oidea）、亚科（subfamily,-inae）、族（tribe,-ini）、亚属、亚种\"，植物中常见\"亚门、亚纲、亚目、族（-eae）、系（series）、变种（var.）、变型（f.）\"。使用辅助阶元的原则是\"不改变基本阶元的信息含义\"，其数量应尽量少，否则体系臃肿。需注意\"总科\"必须放在科之上、\"亚科\"之下，不可颠倒。"},{"id":"4.5","t":"阶元的非可比性","s":3,"c":"4. 分类阶元与学名","x":"同一阶元在不同类群中不代表等量的进化分化：哺乳纲内部的形态差异远大于某些昆虫的一个科，这说明阶元只是人为容器，不携带\"进化距离\"刻度。因此不能因两个类群\"同为科\"就推断其分化时间或遗传距离相近；跨类群比较分化程度必须用分支长度或分歧时间，而不能用阶元高低。"},{"id":"4.6","t":"动物与植物阶元术语差异","s":2,"c":"4. 分类阶元与学名","x":"差异有三处最易失分：门在植物中习称\"division\"；科、目的构词后缀不同（动物 -idae/-ida，植物 -aceae/-ales，细菌 -aceae）；植物有\"变种var.\"与\"变型 f.\"，动物不设这两级而用亚种，动物的\"变种\"仅用于家养动物与历史用法。疫苗株、栽培品种等则完全不属阶元体系。"},{"id":"4.7","t":"命名人引证的规范","s":2,"c":"4. 分类阶元与学名","x":"命名人引证用于标明名称的出处与责任者，其规范为：动物写命名人姓（有时加缩写）与年份，属级调整时加括号；植物写标准缩写（如 L.、DC.、Maxim.）并可附\"ex\"表示他人代为发表。使用\"ex\"与\"in\"有严格含义：\"ex\"表示命名人提出但由他人有效发表，\"in\"表示发表于他人著作中。竞赛常考\"括号的含义\"，答案只有一个：括号表示该种已被移出原属。"},{"id":"4.8","t":"同名与异物同名","s":2,"c":"4. 分类阶元与学名","x":"同名（homonym）指同一名称被用于两个不同类群，后发表者为\"异物同名\"（junior homonym），永久无效，必须重新命名；而\"同物异名\"（synonym）指同一类群被命名两次，后名降为异名。这两组术语极易混用：同名的对立面是\"不同物同名\"，同物异名的对立面是\"同物多名\"。判别要点在于：名相同 → 查同名关系；物相同 → 查异名关系。"},{"id":"4.9","t":"俗名与学名的关系","s":1,"c":"4. 分类阶元与学名","x":"俗名（common name）不受法规管辖，同一物种可有多个俗名、同一俗名也可指不同物种（如\"杜鹃\"既可指鸟也可指植物），因此学术交流必须使用学名。学名的稳定性来自法规与模式标本的双重约束，而俗名的生命力来自日常使用；在科普与教学中应\"俗名先行、学名随附\"，在科研与检疫中则必须\"学名为准\"。"},{"id":"5.1","t":"三大命名法规的管辖范围","s":3,"c":"5. 命名法规","x":"现行有三部独立法规：《国际动物命名法规》（ICZN，第 4 版 1999 年，2000 年 1 月 1 日生效）管动物；《国际藻类、真菌和植物命名法规》（ICN，前身为 ICBN，现行为 2018 年深圳法规）管藻类、真菌与植物；《国际原核生物命名法规》（ICNP）管细菌与古菌。三者互不干涉，故同名可合法地分别用于动物与植物，如 Oenothera（植物）与某动物名相同并不违法；但同一法规内同名绝对禁止。"},{"id":"5.2","t":"优先律","s":3,"c":"5. 命名法规","x":"优先律（principle of priority）规定：同一分类单元的有效名称是最早符合法规发表的名称，以各自法规的起点文献为界（动物 1758 年 1 月 1 日，植物 1753 年 5 月 1 日）。优先律保证名称唯一与可追溯，但也可能使长期通用的名称因发现更早的旧名而被替换，故法规设\"保留名称（nomen conservandum）\"与\"废弃名称（nomen rejiciendum）\"机制，由国际委员会裁定。"},{"id":"5.3","t":"有效发表与合格发表","s":3,"c":"5. 命名法规","x":"动物法规要求名称须\"有效发表\"（published in a manner that is public and permanent，需在一定印量以上公开发行、可永久保存，且不得仅见于未公开的学位论文或会议摘要），植物法规要求\"有效发表\"（有效发行）加\"合格发表\"（legitimate，须符合双名法、有拉丁描述或特征集要、指定模式、符合命名人引证规则等）。二者的共同点是：手稿、私人通信、网络草稿都不是有效发表；电子出版自 2012 年起被有条件承认（需有 ISSN/ISBN 与 PDF 版式），但仍须在注册库登记。"},{"id":"5.4","t":"名称的拉丁化与性一致","s":2,"c":"5. 命名法规","x":"学名须拉丁化，属名的语法性别决定种加词的词尾：阴性属名配 -a/-ae 结尾的种加词，阳性配 -us/-i，中性配 -um。当种加词为名词同位语（如人名、地名作名词）时不随属名变性，只首字母处理按规则。常见错误是把纪念人名的 -i（男）与 -ae（女）用错，或把形容词性种加词改成名词性。"},{"id":"5.5","t":"名称的保留与废弃","s":2,"c":"5. 命名法规","x":"当严格遵守优先律会破坏稳定性时，可向国际委员会申请：把通用名称列入\"保留名称\"名录（nomina conservanda），把冲突旧名列入\"废弃名称\"（nomina rejicienda）。植物法规还提供\"合格发表\"的例外条款（如nomina nuda、nomina dubia 的处理）。保留与废弃属于\"法规内的例外\"，须有正式裁定，个人不得自行宣布某名称无效。"},{"id":"5.6","t":"属级变更与组合","s":3,"c":"5. 命名法规","x":"当一物种被移入另一属时，原种加词保留（若与新区属内已有种加词冲突则须改名），形成\"新组合\"（new combination，植物记作 comb. nov.），原命名人置于括号内。属被拆分时，模式种保留原名，其余种另立新属；属被合并时，最早发表的属名优先。掌握此规则即可解释大量\"同种异名\"现象，也是考试中判断\"哪个名称有效\"的核心依据。"},{"id":"5.7","t":"栽培品种与法规外的名称","s":2,"c":"5. 命名法规","x":"栽培植物（cultivar）依《国际栽培植物命名法规》（ICNCP）命名，写作属名 + 品种加词且品种加词加单引号、正体，如 Malus domestica 'Fuji'；品种名不受 ICN 管辖，也不适用优先律。家养动物的品种（breed）同样不受ICZN 管辖，如 Canis lupus familiaris 指家犬这一亚种/类群，而\"拉布拉多\"只是品种名。竞赛中若把\"品种\"当作分类阶元即错。"},{"id":"5.8","t":"命名注册系统","s":2,"c":"5. 命名法规","x":"为便于核查，各领域建立了注册库：动物学 ZooBank，植物 IPNI（国际植物名称索引）与 Index Fungorum、MycoBank（真菌），原核生物由IJSEM 的名录与 LPSN 维护。新名称发表时须提供注册号（如 Zoobank LSID），这已成为电子出版时代的硬性要求。注册号的意义在于把\"发表\"与\"可检索\"绑定，减少无效名称。"},{"id":"5.9","t":"名称稳定性的现实意义","s":2,"c":"5. 命名法规","x":"名称变更会牵动检疫名单、保护名录、药典、教材与数据库，故法规以\"稳定优先、更改为例外\"为原则：只有当分类学证据明确且按程序裁定后才改名。这也解释了为何一批\"明知并系\"的传统名称（如 Reptilia、Pisces）在教材中仍被保留，而改用加注说明的方式处理。"},{"id":"6.1","t":"模式标本的概念","s":3,"c":"6. 模式标本与模式产地","x":"模式标本（type specimen）是学名的永久载体：名称依附于某一具体标本而非\"物种概念\"，故当物种被拆分或合并时，名称跟随模式标本所在的类群。这一\"模式法\"（type method）是命名稳定性的基石，也是初学者最易忽略的关键。凡讨论名称归属，必须先问\"模式标本属于哪个类群\"。"},{"id":"6.2","t":"模式标本的类型序列","s":3,"c":"6. 模式标本与模式产地","x":"动物学模式类型包括：正模（holotype，原始描述所依据的单一标本）、配模（allotype，与正模异性的标本）、副模（paratype，正模以外的同批次标本）、合模（syntype，原描述未指定正模时的多个标本之一）、选模（lectotype，后人为合模指定的模式）、新模（neotype，原模式丢失后另指定）、地模（topotype，采自模式产地的标本，无命名地位）。植物学中\"主模式（holotype）、等模式（isotype）、副模式（paratype）、后选模式（lectotype）、新模式（neotype）\"含义相近但用法有别。类型定义要点是否具命名地位正模/主模式原始描述所依据的唯一标本是副模/等模式同批次的补充标本否（仅辅助）合模原描述未指定正模时的多个标本是（择一后成为选模）选模/后选模式后人从合模中指定是新模/新模式原模式丢失后另指定是地模采自模式产地，非模式否"},{"id":"6.3","t":"模式产地","s":2,"c":"6. 模式标本与模式产地","x":"模式产地（type locality）是正模标本的采集地点，是物种分布记述的法定起点，必须精确到可定位的地理单元（国家、省、县、经纬度、海拔）。当物种被拆分时，新模式产地不随名称自动转移，只有选模或新模的指定可以重新\"锚定\"产地。竞赛题常以\"新种描述未记模式产地\"设错，此时该描述不符合规范。"},{"id":"6.4","t":"模式指定的规范","s":3,"c":"6. 模式标本与模式产地","x":"新种描述必须明确\"正模\"及保藏机构与登记号，并在文中给出鉴别特征（diagnosis）与描述（description），指定词源（etymology）与模式产地；动物学还要求新种名在 ZooBank 注册并给出 LSID。仅写\"模式标本存于作者处\"、无登记号、或模式标本已损毁而未另指定新模，均属不合格。分子研究还需指定\"分子凭证\"（voucher）并使其与形态凭证对应。"},{"id":"6.5","t":"模式标本的保藏","s":2,"c":"6. 模式标本与模式产地","x":"模式标本须永久保藏于公共机构（博物馆、标本馆、大学标本室），并可供他人查阅，私人收藏不能作为模式。国际上以 Index Herbariorum 代码标识标本馆（如 PE 为中国科学院植物研究所标本馆、K 为邱园、USNM 为美国国家自然历史博物馆）。保藏要求既是科学共同体的伦理规范，也是名称合法性的形式条件。"},{"id":"6.6","t":"模式标本的替代","s":2,"c":"6. 模式标本与模式产地","x":"当正模遗失或损毁，且原描述不足以鉴定时，可指定新模（neotype），前提是先证明原模式确已不存在并说明理由；若原模式仍在但损坏，应指定选模而非新模。在未指定新模式前，名称的有效性不受影响，但名称的应用需依据原始描述。这一区分体现了\"名依附于模式、但不等同于模式实物\"的原则。"},{"id":"6.7","t":"模式标本使用的常见错误","s":2,"c":"6. 模式标本与模式产地","x":"常见错误有四类：（1）把\"地模\"当作模式标本引用；（2）未核对模式即发表\"新种\"，导致同物异名；（3）模式标本与分子样品不对应（凭证错配）；（4）以照片、插图代替模式实物指定新模。以上任一错误都会使后续的分类修订与条形码比对失去基础。"},{"id":"6.8","t":"模式与物种概念的绑定关系","s":2,"c":"6. 模式标本与模式产地","x":"物种概念可以变，名称不能随之漂移：当形态种被分子证据拆为两个隐存种时，名称归属由模式标本的分子鉴定结果决定，另一支须另命名。这一操作称为\"模式标定\"（typification of taxa by specimens），是现代整合分类学的标准动作，也是近年大量隐存种被\"重新命名\"的原因。"},{"id":"7.1","t":"鉴定的基本途径","s":3,"c":"7. 鉴定、检索表与凭证标本","x":"鉴定有三条互补途径：形态途径（依据检索表与模式标本比对）、分子途径（DNA 条形码与参考库比对）、以及专家与文献途径（专著、志书、模式照片）。三者应互相印证：形态给出初判，分子用于验证疑难与隐存种，文献用于确认名称的有效性与异名关系。单一途径得出的鉴定在论文中应说明其置信度。"},{"id":"7.2","t":"二歧式检索表的原理","s":3,"c":"7. 鉴定、检索表与凭证标本","x":"二歧式检索表（dichotomous key）每步给出两个互斥的选择，逐步缩小范围至名称，其优点是逻辑严密、篇幅紧凑，缺点是一处判断失误即导致错误终点，且必须从第一条开始。常见格式有\"阶梯式（indented）\"与\"平行式（bracketed/成对式）\"两种，平行式通过编号（1/1′、2/2′）成对排列，便于回退核查。"},{"id":"7.3","t":"多途径检索表","s":2,"c":"7. 鉴定、检索表与凭证标本","x":"多途径检索表（multi-access key，又称多道检索表、打孔卡式检索表）允许使用者从任一易观察性状入手，逐步排除不符合的类群，适合标本残缺或类群庞大的场合；计算机化的交互式检索（如 DELTA、Lucid）即其现代形式。其缺点是难以保证唯一路径的严密性，且性状编码的主观性会累积误差。"},{"id":"7.4","t":"检索表的编写规范","s":3,"c":"7. 鉴定、检索表与凭证标本","x":"编写检索表须遵守五条：对偶两条必须互斥且穷尽（不能有既不属于甲也不属于乙的情形）；同一对偶应使用同一类性状（如都用\"叶形\"而非一为叶形一为果实）；先写最易观察、变异最小的性状；每一步应尽量均衡（两边类群数相近）；术语须与描述部分一致。常见错误是\"对偶不互斥\"（如\"叶有毛 / 叶无毛\"未考虑稀疏短毛的中间状态）与\"以否定式套否定式\"导致无法判断。"},{"id":"7.5","t":"标本采集与制作要点","s":2,"c":"7. 鉴定、检索表与凭证标本","x":"标本是分类学的实物证据，采集须记录时间、地点（含经纬度与海拔）、生境、采集人、采集号与性状（花色、气味等易失性状需现场记录），并压制或固定保存。分子研究须另取组织并干燥保存（硅胶或乙醇），且与形态凭证共用采集号。凭证缺失的标本无法用于命名或分子比对，只能作为参考。"},{"id":"7.6","t":"凭证标本与分子凭证","s":3,"c":"7. 鉴定、检索表与凭证标本","x":"凭证标本（voucher specimen）是被研究、鉴定并存档以备复核的标本；分子凭证指提供 DNA/序列的那份标本或组织，须与形态凭证一一对应并在论文中给出登记号与保藏地。分子系统学论文的可重复性完全依赖于此：无凭证的序列一旦被质疑鉴定错误，整篇结论即无法复核。这也是公共数据库（GenBank）条目要求附 voucher 信息的原因。"},{"id":"7.7","t":"新种描述的规范要素","s":3,"c":"7. 鉴定、检索表与凭证标本","x":"一篇合格的新种描述通常包含：学名与命名人、模式指定（正模、副模、保藏号）、词源、鉴别特征（与近缘种的对比）、形态描述（按统一顺序）、模式产地与分布、生态与物候、讨论（与近缘种区别及分类学依据）、插图或照片、以及注册号。缺任一要素都可能被审稿人或命名委员会判为不合格，进而影响名称的可用性。"},{"id":"7.8","t":"修订与专著的性质","s":2,"c":"7. 鉴定、检索表与凭证标本","x":"修订（revision）是对某一类群全部已知种的系统整理，包括异名考订、模式核查、检索表重编、分布图与系统发生分析，其成果形式为专著（monograph）或志书（如《中国植物志》《中国动物志》、Flora of China）。修订的价值在于把分散的知识\"收敛\"为可检验的假说，也是竞赛材料题常引用的证据来源。项目二歧式检索表多途径检索表起点必须从第一条开始可从任一性状入手容错性低，一步错则全程错较高，可回退排除适合对象类群小、性状完整类群大、标本常残缺现代形式纸本、平行式编号交互式电子检索（DELTA/Lucid）主要风险对偶不互斥性状编码主观性累积第三篇 物种与种下单元"},{"id":"8.1","t":"物种概念为何不唯一","s":3,"c":"8. 物种概念的群与辨析","x":"物种概念（species concept）回答的问题是\"什么样的类群才配称为物种\"，而不同研究者关注的标准不同：有人关注生殖隔离，有人关注形态可辨别，有人关注单系与诊断性，有人关注生态位。因此物种概念不是一个定义问题，而是\"用什么证据划界\"的操作问题。竞赛中若问\"哪种物种概念最正确\"，正确答法是\"没有普适唯一者，应视类群与问题选择\"，而非简单选生物学物种概念。"},{"id":"8.2","t":"生物学物种概念","s":3,"c":"8. 物种概念的群与辨析","x":"Mayr（1942）提出：物种是\"在自然条件下能够相互交配并产生可育后代、与其他此类群体生殖隔离的群体\"。其判据是生殖隔离，优点是抓住了物种形成的本质（基因流中断），缺点是：（1）对无性生殖类群、化石、异域种群无法操作；（2）\"潜在的\"交配能力难以检验；（3）许多\"好种\"在圈养或人为条件下可杂交。因此它适用于有性生殖、同域或邻域的动物，不适用于细菌、部分植物与化石。"},{"id":"8.3","t":"形态学物种概念","s":3,"c":"8. 物种概念的群与辨析","x":"形态学物种概念以\"具有可鉴别的形态差异且差异稳定\"为划界标准，是分类学实践中使用最广的概念，也是检索表的基础。其优点是普适、可操作、对化石可用；缺点是主观（差异\"多大\"算种无客观阈值），且与生物学物种可能不一致（性二型、多型、隐存种、生态可塑性都会导致误判）。"},{"id":"8.4","t":"系统发生学物种概念","s":3,"c":"8. 物种概念的群与辨析","x":"系统发生学物种概念（phylogenetic species concept）有两个版本：诊断型（Cracraft, 1983）认为物种是最小的、具有固定鉴别性状的个体集合；单系型（de Queiroz & Donoghue）认为物种是最小的单系群。优点是可用于无性类群与化石、判据明确；缺点是\"最小单系群\"在取样不足时会把种群亚结构误判为物种，导致物种数目膨胀（taxonomic inflation）。"},{"id":"8.5","t":"演化物种概念","s":2,"c":"8. 物种概念的群与辨析","x":"演化物种概念（evolutionary species concept，Simpson 1961、Wiley 1978）把物种定义为\"具有自身独立演化命运与历史的一个祖先—后代谱系\"，即一条独立演化的支系。它强调时间维度，适合处理化石序列，但\"独立命运\"难以直接观测，操作上仍需借助形态或分子证据。"},{"id":"8.6","t":"生态学物种概念","s":2,"c":"8. 物种概念的群与辨析","x":"生态学物种概念（Van Valen 1976）以\"占据同一适应带（adaptive zone）的最小类群\"为界，判据是生态位差异，适用于解释同域分布近缘种的共存（如宿主专一的植食性昆虫、湖泊鱼类）。其缺点是生态位难以量化，且生态分化未必伴随生殖隔离。"},{"id":"8.7","t":"DNA 条形码物种概念","s":2,"c":"8. 物种概念的群与辨析","x":"Hebert 等以 cox1 序列差异为物种鉴定标准，实践中常以\"种内差异远小于种间差异（barcode gap）\"或固定阈值（约 2%—3% K2P 距离）划界。其优点是快速、可自动化、适合隐存种发现；缺点是阈值无普适性（不同类群变异速率差异大）、种内地理变异与种间杂交会造成重叠、且线粒体基因存在核插入片段（numt）与渐渗干扰。"},{"id":"8.8","t":"统一物种概念与物种形成阶段","s":2,"c":"8. 物种概念的群与辨析","x":"de Queiroz（2007）提出\"统一物种概念\"：所有物种概念其实描述的是同一对象——独立演化的元居群谱系（metapopulation lineage），只是在物种形成的不同阶段侧重不同判据。物种形成是先有基因流中断，后有形态、生态、生殖隔离的分化，故不同概念的分歧多源于\"在哪个阶段划界\"。这一观点解释了为何不同概念给出的物种数目常有出入。"},{"id":"8.9","t":"物种概念的选择策略","s":3,"c":"8. 物种概念的群与辨析","x":"选择物种概念应遵循三条实务原则：先按类群生殖方式定（有性/无性）、再按材料性质定（现生/化石/仅分子数据）、最后按问题目的定（保护、检疫、生态研究）。同一研究内应明确声明所用概念并保持前后一致；若中途更换概念，须重述全部物种划分，否则结论不可比。概念核心判据适用类群主要弱点生物学生殖隔离有性生殖的现生动物无性类群与化石不可用形态学稳定形态差异普适（含化石）阈值主观，易受可塑性干扰系统发生学固定鉴别性状/最小单系群普适取样不足时物种膨胀演化独立演化谱系化石与时间序列\"独立命运\"难观测生态学占据同一适应带同域近缘种生态位难量化DNA 条形码序列差异阈值隐存种筛查阈值不普适、渐渗干扰"},{"id":"9.1","t":"生殖隔离的两大类机制","s":3,"c":"9. 生殖隔离与物种判据","x":"合子前隔离（prezygotic）发生在受精之前，包括生态（生境）隔离、季节（时间）隔离、行为（求偶）隔离、机械隔离与配子隔离；合子后隔离（postzygotic）发生在受精之后，包括杂种不活、杂种不育与杂种衰败（杂种后代适合度低）。合子前隔离更\"经济\"，因为不浪费配子与育幼投入，故在近缘种共存区常被强化（强化效应，reinforcement）。"},{"id":"9.2","t":"生殖隔离的度量","s":2,"c":"9. 生殖隔离与物种判据","x":"隔离强度常用\"生殖隔离指数\"度量：以两类群间杂交率相对种内杂交率的下降幅度表示（0 表示完全随机交配，1 表示完全隔离），也可用多个隔离机制贡献率之和（总隔离）表达。竞赛计算题的常见形式是给出杂交成功率或后代育性数据，要求判断属于合子前还是合子后隔离。"},{"id":"9.3","t":"杂种不育的遗传机制","s":2,"c":"9. 生殖隔离与物种判据","x":"杂种不育常由染色体结构差异（倒位、易位导致减数分裂配对异常）、基因不兼容（Dobzhansky–Muller 模型：两个谱系各自固定不同等位基因，组合后互作失效）或细胞质—核互作引起。D–M 模型的关键在于：不亲和并非\"退化\"，而是两个谱系独立演化后的副产物，因此隔离可以在自然选择\"无意\"的情况下产生。"},{"id":"9.4","t":"物种判据的操作顺序","s":3,"c":"9. 生殖隔离与物种判据","x":"实际操作常按\"形态差异—地理分布—生殖隔离—分子证据\"的顺序检验：先确认形态与地理上有稳定区分，再检验是否存在同域共存而不混合（同域共存是生殖隔离的强证据），最后用分子数据检验基因流与单系性。同域分布且形态稳定、分子上各自成支，是\"好种\"的强证据组合。"},{"id":"9.5","t":"异域种群与\"物种地位\"的判定","s":3,"c":"9. 生殖隔离与物种判据","x":"异域（allopatric）种群无法直接检验生殖隔离，此时判据须降级为\"形态差异的稳定性 + 地理隔离的完整性 + 分子分化程度\"，并明确标注为\"候选种（candidate species）\"。若仅凭分子距离（如 cox1 差异 3%）即命名新种，属于把\"地理变异\"误作\"物种\"，是当前分类实践中最常见的过度拆分。"},{"id":"9.6","t":"杂交与物种界限","s":2,"c":"9. 生殖隔离与物种判据","x":"能杂交不等于同一物种：许多植物（如栎属 Quercus、柳属 Salix）与部分动物（如某些鱼类、鸟类）存在广泛杂交而仍维持物种界限，判断依据是\"杂交带的存在是否导致类群融合\"。若杂交仅限狭窄接触带且两端保持独立，则仍为两个种；若杂交带不断扩展、界限消失，则说明隔离不完全。植物中杂交常伴多倍化，形成同域新种。"},{"id":"9.7","t":"多倍体与物种形成","s":2,"c":"9. 生殖隔离与物种判据","x":"多倍化（polyploidy）可在一步之内造成生殖隔离（染色体数目不同导致后代不育），是同域物种形成的常见机制，在被子植物中尤其普遍（估计约15%—30%的种形成涉及多倍化，蕨类更高）。同源多倍体来自同一物种的染色体加倍，异源多倍体来自杂交后加倍（如小麦的 AABBDD 六倍体），后者兼具两亲本基因组，常表现新表型。"},{"id":"9.8","t":"物种判据的证据权重","s":2,"c":"9. 生殖隔离与物种判据","x":"证据权重取决于其对基因流的指示力：同域共存 > 生殖隔离实验 > 稳定的形态+分子一致性 > 单一分子距离。单一性状（如体色、体长）差异不应作为命名依据；单一基因（尤其 mtDNA）差异应视为提示而非结论。整合分类（integrative taxonomy）要求至少两类独立证据一致。"},{"id":"10.1","t":"亚种的概念与用法","s":3,"c":"10. 种下单元、居群与杂交带","x":"亚种（subspecies）是种内具有地理分化、形态可辨别但未达到生殖隔离的群体，用三名法表示。亚种的实质是\"地理变异的一次人为切片\"，其界限常随取样而变，故亚种的划分标准历来争议较大。动物学中亚种使用较普遍，植物学中更常用变种（var.）表示类似层级的分化。"},{"id":"10.2","t":"变种、变型与品种","s":3,"c":"10. 种下单元、居群与杂交带","x":"变种（variety，var.）指形态上有稳定差异、分布区可重叠或独立的种内群体，需三名法命名；变型（forma，f.）指差异更细微（如花色、毛被）的类型；品种（cultivar）是人工选育的生产单元，依《国际栽培植物命名法规》命名，用单引号且正体。三者不可混用：变种与变型受 ICN 管辖，品种不受；品种不是分类阶元。"},{"id":"10.3","t":"居群与元居群","s":3,"c":"10. 种下单元、居群与杂交带","x":"居群（population）是同一地点、可相互交配的同种个体群，是演化的基本单位；元居群（metapopulation）是由若干局部居群通过迁移连接的集合，存在局部灭绝与再定殖的动态。系统学研究中\"居群取样\"不足是常见缺陷：只取每地一个个体无法估计种内变异，会系统性低估种内差异、高估种间差异。"},{"id":"10.4","t":"地理变异与渐变群","s":3,"c":"10. 种下单元、居群与杂交带","x":"地理变异常呈渐变群（cline）形式，即性状沿地理梯度连续变化而无明显界限，如体长随纬度增大（Bergmann 规律的一种表现）。渐变群的存在说明\"亚种界限\"多为人为切分；若两个性状的渐变群在不同地点急剧转折（阶梯状渐变），则提示可能存在隔离或二次接触。"},{"id":"10.5","t":"环物种","s":3,"c":"10. 种下单元、居群与杂交带","x":"环物种（ring species）指一系列沿地理环分布的居群，相邻居群可杂交，但环的末端在重叠区已生殖隔离，如加州蝾螈 Ensatina eschscholtzii 与环北极的银鸥复合体（传统例证）。环物种的意义在于证明\"物种界限可以是连续过程的人为截断\"，同时暴露生物学物种概念在异域链条上的操作困难。"},{"id":"10.6","t":"隐存种与复合种","s":3,"c":"10. 种下单元、居群与杂交带","x":"隐存种（cryptic species）指形态上难以区分但生殖隔离或分子上显著分化的物种，在蛙类、昆虫、真菌、藻类中极为常见；复合种（species complex）指一群近缘、界限不清、常被笼统当作一个种的类群。隐存种的大量发现是分子分类的主要贡献之一，也意味着\"形态种数目\"长期低估了真实多样性。"},{"id":"10.7","t":"杂交带与渗入","s":3,"c":"10. 种下单元、居群与杂交带","x":"杂交带（hybrid zone）是两个分化类群接触并产生杂种的地理带，可分为\"张力带\"（tension zone，由选择维持、位置稳定）与\"混合带\"（由扩散维持、逐渐扩张）。渗入（introgression）指杂种与亲本回交导致基因单向或双向导入，可用分子标记检测。杂交带是研究物种界限与选择作用的天然实验室。"},{"id":"10.8","t":"种下单元的命名与法规要求","s":2,"c":"10. 种下单元、居群与杂交带","x":"种下单元命名同样受法规约束：动物亚种用三名法且必须指定模式标本；植物变种与变型须给出等级缩写（var.、f.）并合格发表。种下名称也适用优先律，但作者常忽略\"同一亚种加词已被用于该种下其他亚种\"的情形，造成同名。竞赛材料中若出现\"亚种名首字母大写\"或\"品种名用斜体\"即为错误。第四篇 分类性状与证据"},{"id":"11.1","t":"形态性状的地位","s":3,"c":"11. 形态、解剖与发育性状","x":"形态性状是分类学最传统、最普适的证据来源，其优势是可直接观察、可对化石使用、可与模式标本比对；劣势是易受环境塑形（表型可塑性）与趋同演化干扰。现代系统学并未抛弃形态，而是要求形态性状经同源判定与极性分析后才进入矩阵。在分子数据普及的今天，形态仍是新种描述与野外鉴定的法定依据。"},{"id":"11.2","t":"同源判定的三条准则","s":3,"c":"11. 形态、解剖与发育性状","x":"Remane 提出判定同源的三条准则：位置准则（器官在身体中的相对位置一致）、特殊质量准则（结构细节、发育来源等特殊性质一致）、连续性准则（存在中间过渡类型或系列渐变）。三条准则合用可显著降低误判；但\"同源\"最终是演化假说，须接受系统发生检验——若某性状在树上需多次起源，则其同源性可疑。"},{"id":"11.3","t":"同源与同功的区分","s":3,"c":"11. 形态、解剖与发育性状","x":"同源（homology）指源自共同祖先的相同结构（如人臂、蝙蝠翼、鲸鳍），同功（analogy/homoplasy）指功能相似但起源独立（如鸟翼与昆虫翅）。区分依据是形态发生来源、位置关系与系统发生检验，而不是功能相似或名称相似。必须强调：同功在支序分析中表现为\"同塑性\"（homoplasy），会增加树长并降低 CI 值。"},{"id":"11.4","t":"系列同源与特殊同源","s":2,"c":"11. 形态、解剖与发育性状","x":"系列同源（serial homology）指同一个体内沿体轴重复的结构（如脊椎、体节附肢），特殊同源（special homology）指不同个体/类群间的对应结构。区分二者的意义在于：系列同源的结构不能作为\"不同类群近缘\"的证据，因为它们在同一个体内就重复出现；而体节数目、附肢分化样式等\"系列同源的变化模式\"才是可用的分类性状。"},{"id":"11.5","t":"性状极性的判定方法","s":3,"c":"11. 形态、解剖与发育性状","x":"性状极性（polarity）指确定某一状态是祖先状态（plesiomorphy）还是衍生状态（apomorphy）。常用方法有：外群比较法（最常用，见第 15章）、化石法（地层顺序与最早化石状态）、个体发育法（重演律的弱化版本，个体发育早期的状态可能较原始）、性状相关法（与已知极性性状连锁变化）。四法冲突时以外群比较为准。"},{"id":"11.6","t":"胚胎与发育性状","s":2,"c":"11. 形态、解剖与发育性状","x":"胚胎学性状在动物高级阶元分类中曾起决定作用：卵裂方式（螺旋式/辐射式）、体腔形成方式（裂体腔/肠体腔）、胚孔命运（原口/后口）、幼虫类型（担轮幼虫、面盘幼虫）。现代发育生物学进一步提供\"发育机制性状\"，如Hox 基因表达域、体轴决定方式，这类性状同源性更可靠但获取成本高。植物中胚珠、胚囊类型（蓼型、贝母型）亦为常用性状。"},{"id":"11.7","t":"性状编码的规范","s":3,"c":"11. 形态、解剖与发育性状","x":"形态性状进入矩阵前须编码：定性性状按状态编码（0/1/2），有序多状态用\"有序编码\"（如 0<1<2），无序多状态须声明为无序，连续性状（长度、计数）应离散化或改用比值并说明依据。常见错误是把连续变量随意二分（如\"体长>10 mm 记 1\"）而无依据，或把同一性状的不同表述重复编码（冗余性状导致隐性加权）。"},{"id":"11.8","t":"性状可靠性评估","s":2,"c":"11. 形态、解剖与发育性状","x":"性状可靠性取决于四点：遗传基础是否明确（受单基因控制者较稳定）、发育稳定性（是否易受环境塑形）、类群内变异幅度（是否与类群间差异重叠）、以及同塑性程度（在已知系统树上需多次起源者应降权）。可靠的分类性状通常是\"多部位、多层次、且在不同地理种群中稳定\"的组合，而非单一醒目特征。"},{"id":"12.1","t":"染色体数目性状","s":3,"c":"12. 细胞与生化性状","x":"染色体数目（2n，二倍体；n，单倍体）是最早用于分类的细胞学性状之一，如人 2n=46、黑猩猩 2n=48、果蝇 2n=8，小麦为六倍体 2n=42。数目变化常与物种形成相关（多倍化、罗伯逊易变导致的融合与裂解），但数目相同不代表近缘，数目不同也可能仅为种内多态（如 B 染色体），故须结合核型结构判断。"},{"id":"12.2","t":"核型与带型","s":3,"c":"12. 细胞与生化性状","x":"核型（karyotype）指染色体的数目、大小、形态（着丝粒位置：中着丝粒、亚中着丝粒、近端着丝粒、端部着丝粒）与随体、次缢痕等的组合；带型指经 G 带、C 带、N 带、Q 带、荧光原位杂交（FISH）等处理后的条带格局。带型可揭示倒位、易位等结构重排，是动物与植物细胞分类学（如斑马鱼、啮齿类、葱属 Allium）的重要证据。"},{"id":"12.3","t":"染色体结构变异作为分类证据","s":2,"c":"12. 细胞与生化性状","x":"倒位与易位一旦固定，即成为类群的\"共有衍征\"，可用于推断分支关系（如黑腹果蝇种组（Drosophila melanogaster subgroup）的倒位系统、人类 2 号染色体由两条猿类染色体融合而成）。使用该证据的前提是确认重排为\"同一事件\"而非平行发生，故需结合带型与序列断点验证。"},{"id":"12.4","t":"基因组大小与倍性","s":2,"c":"12. 细胞与生化性状","x":"基因组大小（C 值）在类群间差异极大（\"C 值悖论\"），但同一科内常相对稳定，可用于辅助判断；倍性水平（二倍体、四倍体、六倍体）与多倍化历史则直接关系物种形成与命名（如小麦属 Triticum 的 AABBDD）。流式细胞术可快速测定 DNA 含量，是筛选多倍体与隐存种的高效手段。"},{"id":"12.5","t":"次生代谢产物性状","s":2,"c":"12. 细胞与生化性状","x":"次生代谢物（黄酮类、生物碱、萜类、氰苷、芥子油苷等）曾广泛用于植物化学分类学：如芥子油苷与白花菜目（现十字花目）相关，苯丙烷类化合物分布有系统学意义，某些生物碱局限于特定科属。其优点是化学稳定、可定量；缺点是受发育阶段与环境强烈影响，且合成途径可独立起源，故一般作为辅助证据，需与形态、分子证据互证。"},{"id":"12.6","t":"同工酶与等位酶","s":3,"c":"12. 细胞与生化性状","x":"同工酶（isozyme）指功能相同而结构不同的酶，等位酶（allozyme）指同一基因座的不同等位基因产物，用凝胶电泳可检测其迁移率差异。同工酶分析在 20 世纪 70—80 年代是居群遗传学与系统学的主力（如估算遗传距离 Nei距离、杂合度），其优点是共显性、成本低；缺点是可检测位点少、变异水平低、且部分酶受组织与发育阶段影响。"},{"id":"12.7","t":"血清学与免疫学性状","s":1,"c":"12. 细胞与生化性状","x":"血清学方法（沉淀反应、免疫扩散、酶联免疫）通过抗原—抗体交叉反应程度估计蛋白同源性，曾在 20 世纪中期用于动物亲缘关系研究（如 Goodman的灵长类白蛋白免疫距离）。其优点是可用于远缘比较；缺点是交叉反应易受抗体质量与定量方式影响，结果仅为相似性度量而非同源字符，现已基本被序列数据取代。"},{"id":"12.8","t":"细胞学性状的局限","s":2,"c":"12. 细胞与生化性状","x":"细胞学性状的根本局限是\"性状数目少\"：一个物种通常只能提供数目、核型、带型等少数几项信息，独立性状少于形态与序列，故易受同塑性影响；且带型判读受制片质量与操作者经验制约。因此细胞学证据常用于\"提出假设\"，而非\"单独定论\"，在整合分类中多作为形态与分子之间的独立验证。"},{"id":"13.1","t":"分子性状的类型","s":3,"c":"13. 分子、行为生态与地理证据","x":"分子性状可分为序列类（DNA/RNA/蛋白质序列）、片段长度类（RFLP、AFLP、ISSR）、重复序列类（微卫星 SSR、ISSR）、单核苷酸多态类（SNP）与结构变异类（存在/缺失、拷贝数）。序列类信息量最大、最易存档比较；片段与重复类通量高但同源性判断困难；SNP 适合居群水平；结构变异适合近缘种与种下分析。"},{"id":"13.2","t":"分子性状的优点与陷阱","s":3,"c":"13. 分子、行为生态与地理证据","x":"优点是字符数量大、可跨类群直接比较、演化模型可参数化、数据可永久存档复核。陷阱有三：（1）基因树不等于物种树（溯祖、谱系分选、渐渗会造成不一致）；（2）不同基因进化速率差异大，选错标记会\"抹平\"或\"夸大\"分化；（3）同源性判定错误（旁系同源、核线粒体片段 numt）会造成系统性偏差。"},{"id":"13.3","t":"行为性状的分类价值","s":2,"c":"13. 分子、行为生态与地理证据","x":"鸣声（鸟类、蛙类、昆虫）、求偶行为、筑巢方式、通信信号在近缘种识别中极为有效，如蛙类广告鸣声的差异常与生殖隔离直接对应，蟋蟀的鸣声节律是隐存种鉴别关键。行为性状的优点是直接关联生殖隔离；缺点是需活体观察、记录手段要求高、且部分行为有学习成分（如鸟类鸣唱），遗传基础不明确。"},{"id":"13.4","t":"生态与寄主性状","s":2,"c":"13. 分子、行为生态与地理证据","x":"寄主专一性、食性、生境选择、物候期等生态性状在昆虫与寄生生物分类中价值极高（如瘿蜂、蚜虫、寄生蜂的寄主记录），且常与生殖隔离相关（同域成种的重要途径）。使用限制是：生态性状易观察误差、可塑性大（\"寄主转移\"可在少数世代内发生），故须有实验验证或分子证据支持。"},{"id":"13.5","t":"地理分布证据","s":3,"c":"13. 分子、行为生态与地理证据","x":"分布格局提供两类证据：替代分布（vicariance，近缘种互为地理替代，如东亚—北美间断分布）与重叠分布（同域共存）。前者提示共同祖先曾连续分布后被隔离，后者是生殖隔离的直接证据。此外，\"分布区边缘的形态渐变\"可提示亚种界限的位置。使用分布证据必须核查采集记录的可信度，避免把\"采集不足\"误读为\"间断分布\"。"},{"id":"13.6","t":"生物地理学推断方法","s":2,"c":"13. 分子、行为生态与地理证据","x":"历史生物地理学用系统树与分布格局推断祖先分布区：常用方法有简约法（parsimony analysis of endemicity）、似然法与贝叶斯法（如BioGeoBEARS 的 DEC、DIVALIKE 模型）、以及分歧时间校准后的扩散—隔离分析。其核心逻辑是\"把分布区当作性状编码到树上\"，因此结论依赖于树与时间标定的可靠性。"},{"id":"13.7","t":"性状加权与其争议","s":3,"c":"13. 分子、行为生态与地理证据","x":"加权（weighting）指按性状可靠性赋予不同权重，分\"先验加权\"（依经验在分析前设定，如给同塑性低的性状更高权重）与\"后验加权\"（依分析结果反复调整）。支序学派主流倾向\"不加权或仅作敏感性分析\"，因为先验加权主观、后验加权有循环论证之嫌；但实践中对高度同塑性的性状（如寄主、体色）作降权仍被广泛接受，须在方法中明确声明。"},{"id":"13.8","t":"性状证据的整合原则","s":3,"c":"13. 分子、行为生态与地理证据","x":"整合原则有四：独立性（不同证据应来源独立，不能把同一形态特征的不同表述重复计入）、可重复性（编码标准与原始数据须公开）、一致性检验（不同数据集拓扑冲突时应作 ILD 或分区分析，而非简单拼接）、以及证据权重透明（任何加权与取舍都须说明理由）。只有满足这四条，\"多证据一致\"才构成真正的支持，否则只是同一偏误的重复。第五篇 系统发生与支序分析"},{"id":"14.1","t":"系统树的构成要素","s":3,"c":"14. 系统树的基本概念","x":"系统树（phylogenetic tree，分支图 cladogram）由根、节点（node）、分支（branch）与末端（叶）构成：末端代表被研究的操作分类单元（OTU，可为物种、个体或居群），内部节点代表假想的最近共同祖先，分支长度可表示时间、遗传距离或性状变化数。读树的第一原则是：内部节点是\"假想的祖先\"，绝不是一个现生类群。"},{"id":"14.2","t":"姐妹群与亲缘关系","s":3,"c":"14. 系统树的基本概念","x":"两个直接源于同一节点的分支互为姐妹群（sister group），它们之间的亲缘关系比与任何其他类群都近。因此\"人与其最近的姐妹群（黑猩猩与倭黑猩猩）关系最近\"是正确表述，而\"人由黑猩猩演化而来\"是错误表述——两者是同一祖先的两个后代支，而非祖—裔关系。"},{"id":"14.3","t":"拓扑结构与旋转","s":3,"c":"14. 系统树的基本概念","x":"拓扑结构（topology）指分支的连接方式，是系统树的核心信息；在节点处旋转分支（swapping）不改变拓扑，也不改变亲缘关系。读图时\"谁离谁近\"只取决于最近共同节点的位置，与图上左右、上下、间距无关。考试常见的\"看图判断亲缘远近\"题目，干扰项多利用视觉邻近性设错。"},{"id":"14.4","t":"有根树与无根树","s":2,"c":"14. 系统树的基本概念","x":"无根树只表达类群间的分组关系（拓扑），不指示演化方向；有根树通过指定根来确定时间方向与\"祖先—后代\"关系。距离法（如邻接法）通常先产生无根树，再用外群或中点法赋根；简约法与似然法在建树时可指定外群直接生成有根树。因此同一无根拓扑可对应多个有根版本，讨论\"谁最原始\"必须先确定根。"},{"id":"14.5","t":"赋根的方法","s":3,"c":"14. 系统树的基本概念","x":"赋根（rooting）常用三法：（1）外群法（outgroup rooting），以确定的外群所在分支与内群之间的枝为根，最可靠；（2）中点法（midpoint rooting），假设各支演化速率相近，把根置于最长路径的中点，适用于无外群且速率近似恒定的数据；（3）分子钟法，用时间校准点定根。外群选错是最常见的赋根错误，会整体颠倒演化方向。"},{"id":"14.6","t":"冠群与干群","s":3,"c":"14. 系统树的基本概念","x":"冠群（crown group）指某类群所有现生成员及其最近共同祖先构成的整体；干群（stem group）指与该冠群同源、但位于冠群之外已灭绝的支系（如兽孔类之于哺乳类冠群）。这一区分解决了\"化石类群放在哪里\"的表述难题，是现代系统学描述化石位置的标准语言，也解释了为何\"最早的鸟类\"往往不在鸟纲冠群之内。"},{"id":"14.7","t":"枝长的含义","s":2,"c":"14. 系统树的基本概念","x":"枝长可表示三类量：时间（绝对年代或相对时间）、遗传距离（每位点期望替换数）、性状变化数（简约法中的步数）。同一张图上不同含义不可混用；若枝长表示替换数，则长枝不代表\"更古老\"，只代表\"变化更多\"。竞赛中见\"枝越长越古老\"的说法即为错误。"},{"id":"14.8","t":"树的不确定性表达","s":3,"c":"14. 系统树的基本概念","x":"不确定性有两种表达：多歧分支（polytomy，节点未解决）与支持度数值（节点旁的数字）。多歧分为\"硬多歧\"（数据本身支持多个分支同时起源，如真实的快速辐射）与\"软多歧\"（数据不足，无法解决）。规范做法是把支持度低的二分分支塌缩为多歧，而不是强行给出一条低支持的拓扑。术语含义常见误解内部节点假想的最近共同祖先误当作现生类群姐妹群源自同一节点的两支误按图上距离判断冠群现生成员及其最近共同祖先与\"干群\"混用干群冠群之外的已灭绝近缘支系误称\"祖先类群\"多歧分支关系未解决误当作同时起源"},{"id":"15.1","t":"单系群的判据","s":3,"c":"15. 单系、并系、多系与性状极性","x":"单系群（monophyletic group，clade）指包含最近共同祖先及其全部后代的类群。判据可操作化为：在系统树上\"一刀剪下\"该群时，剪下的部分必须是连通的一个子树，且不遗漏祖先的任何后代。等价表述是\"该群可由共同衍征定义\"。任何单系群都是合法的分类单元，反之则不是。"},{"id":"15.2","t":"并系群的判据","s":3,"c":"15. 单系、并系、多系与性状极性","x":"并系群（paraphyletic group）指包含最近共同祖先、但排除了一个或多个后代支系的类群，典型如\"爬行纲\"（排除鸟类）、\"鱼纲\"（排除四足类）、\"原生生物\"（排除后生动物与真菌）。形态上的表现是\"共有祖征的组合\"：成员共享原始性状，而把衍生的一支排除在外。"},{"id":"15.3","t":"多系群的判据","s":3,"c":"15. 单系、并系、多系与性状极性","x":"多系群（polyphyletic group）指依据趋同性状（同功）拼合起来的类群，其成员在树上不构成连通子树，最近共同祖先不属于该群，典型如\"恒温动物\"（鸟+哺乳类）、旧分类中的\"飞行动物\"、\"藻类\"作为整体。判别口诀：单系剪一刀、并系剪两刀、多系剪不出一刀。类型是否含最近共同祖先是否含全部后代依据的性状例单系含含共同衍征哺乳纲、鸟纲、被子植物并系含否（排除部分）共同祖征爬行纲、鱼纲、原生生物多系不含否同功/趋同恒温动物、旧\"藻类\"、飞行动物"},{"id":"15.4","t":"共有衍征与共有祖征","s":3,"c":"15. 单系、并系、多系与性状极性","x":"共有衍征（synapomorphy）是某单系群成员共享的衍生性状，是支持该群的证据；共有祖征（symplesiomorphy）是继承自更早祖先的原始性状，虽为成员共享却不能证明它们构成单系群（因为外群也有）。独有衍征（autapomorphy）只出现在单个末端，不能用于分组，只能证明该末端的独立性。三个概念构成支序分析的概念核心。"},{"id":"15.5","t":"性状极性的外群比较","s":3,"c":"15. 单系、并系、多系与性状极性","x":"外群比较法（outgroup comparison）的逻辑是：若某性状在内群中有两态，而一个或多个外群中只出现其中一态，则该态被推断为祖先态，另一态为衍生态。使用时须满足：外群确为内群的近缘类群（而非远缘）、且外群的极性本身不必再判（若需递归则改用多个外群的一致性）。外群选得太远会引入错误极性。"},{"id":"15.6","t":"同塑性与树长","s":3,"c":"15. 单系、并系、多系与性状极性","x":"同塑性（homoplasy）指同一性状状态在树上需多次起源或发生回复，表现为\"额外步数\"。简约法的树长等于所有性状变化步数之和，同塑性越多，树长越长、一致性指数越低。同塑性来源包括趋同、平行演化、回复突变与编码错误；减少同塑性的手段是增加独立性状、剔除可疑性状、并检查编码一致性。"},{"id":"15.7","t":"单系原则带来的分类调整","s":2,"c":"15. 单系、并系、多系与性状极性","x":"按单系原则，传统\"鱼纲\"须拆为盲鳗纲、七鳃鳗纲、软骨鱼纲、辐鳍鱼纲、肉鳍鱼纲与四足类；\"爬行纲\"或并入鸟纲（成为 Sauropsida 的一部分）或被拆解；\"双子叶植物\"须拆出基部群（ANA 与木兰类），只保留真双子叶（eudicots）。这些调整的逻辑一致：凡排除后代的类群都必须修正，否则分类与演化历史不符。"},{"id":"15.8","t":"支序图与进化时间轴的区别","s":3,"c":"15. 单系、并系、多系与性状极性","x":"支序图（cladogram）只表达分支顺序，不代表时间刻度：末端的相对高低、左右位置都没有时间含义；即使某末端在图上报\"更早分出\"，也不等于它是\"更古老的现生类群\"。只有经过时间标定（化石校准、分子钟）的\"时间树\"（chronogram）才具备年代信息。把支序图当时间轴读，是最典型的概念性错误。"},{"id":"16.1","t":"最大简约法的原理","s":3,"c":"16. 简约法与距离法","x":"最大简约法（maximum parsimony, MP）选择使全部性状总变化步数（树长）最小的拓扑作为最优树。其哲学依据是\"奥卡姆剃刀\"，统计上的合理性在于：当性状变化概率较低时，最少变化的解释具有最大似然性；但当变化频繁（长枝、饱和）时，这一优势消失。MP 不需要指定替换模型，这是其主要优点，也是其在长枝情形下易受系统误差影响的原因。"},{"id":"16.2","t":"Fitch 算法","s":3,"c":"16. 简约法与距离法","x":"Fitch（1971）算法用于无序性状（任意状态间转换代价相同）的树长计算，分两步：下行（downpass）自末端向根求每个节点的状态集合（子节点集合交集若为空则取并集，且步数加一）；上行（uppass）自根向末端确定最优状态。算法的输出是该树的最小步数与各节点状态的最优（最简）重建，时间复杂度与性状数和节点数成线性关系。"},{"id":"16.3","t":"Sankoff 算法与加权","s":2,"c":"16. 简约法与距离法","x":"Sankoff 算法允许不同状态间转换代价不同（如转换/颠换代价不同、有序性状按级差计价），通过动态规划求最小代价，是 Fitch 算法的推广。其意义在于使简约法可处理\"加权性状\"与\"有序多状态性状\"，但也意味着结论依赖于代价矩阵的设定，必须作敏感性分析。"},{"id":"16.4","t":"树搜索策略","s":2,"c":"16. 简约法与距离法","x":"最优树的搜索分三类：穷举法（exhaustive，适用于末端数很少的情形）、分支限界法（branch-and-bound，可保证最优但耗时）、启发式搜索（heuristic，逐步加入末端并做分支交换，但不能保证全局最优）。常用分支交换算法有最近邻互换（NNI）、子树修剪嫁接（SPR）与树二分重连（TBR），其彻底程度依次增强。启发式搜索必须报告重复次数与随机起始树数量，否则不可重复。"},{"id":"16.5","t":"距离法与邻接法","s":3,"c":"16. 简约法与距离法","x":"距离矩阵法先把序列差异转换为遗传距离，再依距离聚类建树：UPGMA假设速率恒定（分子钟），适用于种下与近缘种；邻接法（neighborjoining, NJ）不要求速率恒定，通过逐步合并使总枝长最小的邻居对建树，速度快，常用于大数据集初探。距离法的共同弱点是\"以距离代替字符\"，丢失了位点信息，且对模型与比对错误敏感。"},{"id":"16.6","t":"距离校正与模型","s":2,"c":"16. 简约法与距离法","x":"原始差异（p-distance）会低估真实替换数，因多次打击（multiple hits）使同一位置发生多次替换却只记录一次差异。常用校正包括 JC 校正与K2P 距离公式，其校正幅度随距离增大而急剧放大，超过饱和点后距离估计不再可信。因此序列差异 >15%—20% 时，未经校正的 p 距离只宜作粗略比较。"},{"id":"16.7","t":"简约法的系统误差","s":3,"c":"16. 简约法与距离法","x":"简约法在两类情形下会系统性出错：长枝吸引（long branch attraction,LBA，Felsenstein 1978）与碱基组成偏倚。LBA 的机制是：两条长枝上的同塑性变化被简约法误当作共享衍征而聚在一起，即使二者并不近缘。识别方法是检查长枝是否总被聚到一起、删除可疑类群后拓扑是否改变；缓解手段包括改用似然法/贝叶斯法、增加分类单元取样、剔除高变异位点。"},{"id":"16.8","t":"方法选择的实务原则","s":2,"c":"16. 简约法与距离法","x":"实务上可按数据规模与问题层级选择：末端多、需快速初探用 NJ；性状少、形态数据用 MP；序列数据、需明确模型用 ML；需处理不确定性、数据量中等用贝叶斯；近期分化、存在基因流则考虑网络法（如 split network）。规范研究应至少用两种方法互证，并报告拓扑冲突的具体节点。方法UPGMA距离+等速率依据否是否需模型快速直观优点速率不等时错误主要风险邻接法 NJ距离最小化否（可选校正）快，适合大数据丢失位点信息最大简约 MP字符，步数最小否直观、无模型假设长枝吸引、同塑性最大似然 ML字符，概率最大是统计基础强计算慢、依赖模型贝叶斯后验概率是支持度易得后验概率偏高"},{"id":"17.1","t":"最大似然法的原理","s":3,"c":"17. 最大似然与贝叶斯推断","x":"最大似然法（maximum likelihood, ML；Felsenstein 1981）在所有可能的拓扑与枝长中，寻找使\"观测到当前数据\"的概率（似然值）最大的组合。似然值需在给定替换模型与枝长下，对所有可能的祖先状态求和（而不是取最优单一状态），这是它与简约法的本质区别。ML 的计算复杂度高，需依赖启发式搜索与高效算法（如剪枝算法 pruning）。"},{"id":"17.2","t":"替换模型的作用","s":3,"c":"17. 最大似然与贝叶斯推断","x":"替换模型规定碱基/氨基酸状态间的替换速率结构，决定\"同一差异值\"在不同模型下对应的替换数。模型越接近真实，估计越准；模型过简（如用 JC 拟合高变异数据）会系统性低估长枝、加剧 LBA；模型过繁（参数过多）则方差增大。因此\"模型选择\"是 ML 与贝叶斯分析的必要步骤，常用 AIC、BIC 与似然比检验比较。"},{"id":"17.3","t":"贝叶斯推断的流程","s":3,"c":"17. 最大似然与贝叶斯推断","x":"贝叶斯系统发生推断（Rannala & Yang 1996）先设定树、枝长与模型参数的先验分布，再通过马尔可夫链蒙特卡洛（MCMC）抽样近似后验分布，从样本中统计各分支出现的频率即为后验概率（BPP）。实践要点包括：多条独立链（通常 4 条）以检验收敛、弃置预热样本（burn-in）、用平均标准差（ASDSF <0.01）与 ESS 值判断收敛、并报告所用先验。收敛未达标的链不能用。"},{"id":"17.4","t":"后验概率的解读","s":3,"c":"17. 最大似然与贝叶斯推断","x":"后验概率（posterior probability）表示\"在给定数据与模型下该分支成立的概率\"，其数值通常高于自展支持度，二者不可直接比较：同一分支bootstrap 70% 与 BPP 0.95 并不等价。原因是先验的引入使 BPP 倾向于高估支持度（尤其短枝、取样不足时）。因此论文中应并列报告两种支持度，并谨慎解释\"高 BPP + 低 bootstrap\"的分支。"},{"id":"17.5","t":"ML 与贝叶斯的异同","s":2,"c":"17. 最大似然与贝叶斯推断","x":"相同点：都以显式替换模型为基础、都需搜索树空间、都对模型误设敏感。不同点：ML 求单一最优点估计（点估计），不能直接给出分支概率；贝叶斯求后验分布，天然给出不确定性与参数区间；贝叶斯计算通常比同等 ML更快（因可同时抽样树与参数），但对先验与收敛诊断更敏感。"},{"id":"17.6","t":"模型比较准则","s":2,"c":"17. 最大似然与贝叶斯推断","x":"常用准则有三：似然比检验（LRT，需嵌套模型，用卡方近似）、AIC（Akaike 信息准则，惩罚参数数目，适合预测）、BIC（贝叶斯信息准则，惩罚更强，适合大样本）。实践中以 AIC/BIC 最小者为优，但差异小于 2 时视为无实质差别；若不同模型给出冲突拓扑，应报告这种冲突而非只报最优模型的结果。"},{"id":"17.7","t":"分区与混合模型","s":2,"c":"17. 最大似然与贝叶斯推断","x":"多基因或\"基因+密码子位置\"数据常需分区（partitioning），使不同分区使用不同模型与参数；分区方案可用贪婪算法或 BIC 比较（如PartitionFinder）。过度分区会使参数暴增、方差增大，分区过少则模型误设；因此需在\"拟合度\"与\"参数简约\"间取平衡。混合模型（如 CAT）则用分布代替离散类别，适合大矩阵。"},{"id":"18.1","t":"一致性指数与保留指数","s":3,"c":"18. 树的支持、比较与转为分类","x":"一致性指数 CI = m/s（m 为性状最小可能步数之和，s 为实际树长），衡量性状与树的吻合程度，CI 越小说明同塑性越多；但其值受性状数目与末端数目强烈影响，且随末端增加而系统性下降，故不宜跨数据集比较。保留指数 RI= (g − s)/(g − m)（g 为星状树的步数，即完全不解析时的最大步数），衡量树相对随机状态的改善程度，通常比 CI 更稳健。二者常合称\"树的拟合度量\"，须与支持度分开报告。"},{"id":"18.2","t":"自展支持与衰减指数","s":3,"c":"18. 树的支持、比较与转为分类","x":"自展（bootstrap；Felsenstein 1985）通过有放回重抽样字符（通常1000 次），统计各分支在重抽样树中出现的频率，作为该分支的支持度。经验上 >70% 视为较强支持（Hillis & Bull 1993），但该阈值并非绝对。衰减指数（Bremer support/decay index）指为拆散某分支需增加的最小步数，直接表达\"证据余量\"，与自展互补：衰减指数高而自展低，提示性状少但一致。"},{"id":"18.3","t":"其他支持度度量","s":2,"c":"18. 树的支持、比较与转为分类","x":"常用者还有：自减法（jackknife，半数位点剔除）、近似无偏检验（AU检验）、贝叶斯后验概率、以及四分支支持（quartet support，如 IQ-TREE的 aLRT）。不同度量回答的问题略不同：自展与自减法是\"数据扰动下的稳定性\"，衰减指数是\"证据余量\"，后验概率是\"模型下的概率\"。写作时应说明所用度量，不可笼统称\"支持率高\"。"},{"id":"18.4","t":"一致树与冲突处理","s":3,"c":"18. 树的支持、比较与转为分类","x":"当存在多棵同等最优树时，用一致树（consensus tree）概括共同信息：严格一致树只保留所有树共有的分支；50% 多数一致树保留出现频率超过半数的分支；半严格一致树容许某分支在一部分树上存在。若不同数据集（如线粒体与核基因）拓扑冲突，应先检验冲突是否显著（ILD 检验、Templeton 检验），再决定联合分析或分别报告，而不是强行拼接。"},{"id":"18.5","t":"树的比较","s":2,"c":"18. 树的支持、比较与转为分类","x":"比较两棵树常用 Robinson–Foulds 距离（对称差，统计两树中不共享的分支数），以及基于分支长度的加权比较。在协同进化研究中，用\"宿主树—寄生物树\"的配对比较（cophylogeny）检验共成种、宿主转移与重复寄生事件（工具如 TreeMap、Jane）。树比较的前提是两树的末端集合一致，且分类单元对应关系明确。"},{"id":"18.6","t":"树与分类的对应规则","s":3,"c":"18. 树的支持、比较与转为分类","x":"把系统树转为分类须遵守四条：只命名单系群；同一节点的姐妹群应处于同一阶元；阶元的升降须与分支顺序一致（不允许出现\"某科嵌套于另一科之内\"）；命名须符合相应法规并指定模式。违反第一条即产生并系群，违反第三条即产生\"等级不一致\"，后者是传统分类体系中最常见的形式缺陷。"},{"id":"18.7","t":"分类处理的三种策略","s":2,"c":"18. 树的支持、比较与转为分类","x":"面对\"传统类群并系\"的结论，实务上有三种处理：拆分（split，把并系群拆为若干单系群，如把鱼纲拆为多个纲）、合并（lump，把衍生支并入母群，如把鸟类并入爬行类所在支系）、以及保留加注（保留传统名称但注明其并系性质，教材最常用）。三者各有代价：拆分增加名称数量、合并破坏习惯用法、保留则牺牲逻辑一致性。"},{"id":"18.8","t":"系统发生命名法","s":2,"c":"18. 树的支持、比较与转为分类","x":"PhyloCode（2020 年生效）主张以\"节点命名\"（node-based）、\"分支命名\"（branch-based）与\"衍征命名\"（apomorphy-based）取代阶元，使名称直接锚定在树上，避免升降阶元带来的名称变动。其优点是与分支严格对应、不受阶元约束；缺点是名称稳定性依赖于树的变化、与传统文献衔接困难，目前尚未取代 ICZN/ICN，竞赛中只要求知道其存在与基本主张。第六篇 分子系统学"},{"id":"19.1","t":"分子标记选择的总原则","s":3,"c":"19. 分子标记与序列获取","x":"选择标记须同时考虑四因素：演化速率是否与所要解决的分化层级匹配（深→慢、浅→快）、是否易于通用引物扩增（有无保守侧翼区）、是否存在旁系同源与假基因干扰、以及数据库参考序列是否充足。一句话概括：深分化用保守基因（rRNA 基因），近缘种用快速演化区（ITS、cox1 非编码侧翼），居群水平用高变标记（微卫星、SNP）。"},{"id":"19.2","t":"16S rRNA 基因","s":3,"c":"19. 分子标记与序列获取","x":"16S rRNA 基因（约 1540 bp）是细菌与古菌分类的\"金标准\"，含 9 个高变区（V1—V9）与保守区交替排列，保守区用于设计通用引物（如 27F/1492R），高变区提供分类信息。其优点是所有原核生物同源可比、数据库庞大（如SILVA、Greengenes）；缺点是分辨率一般只到属—种之间，且多拷贝拷贝间存在微小差异（intragenomic heterogeneity）。"},{"id":"19.3","t":"18S rDNA 与 rRNA 基因家族","s":3,"c":"19. 分子标记与序列获取","x":"真核生物的核糖体基因以串联重复形式存在（18S—5.8S—28S），其中18S rDNA 约 1800 bp，适合科—纲级比较；28S（LSU）变异较高，常用于属—种级；5.8S 很短，主要与 ITS 联用。这类基因的优点是拷贝数高、易扩增、有通用引物；缺点是存在拷贝间不均一（concerted evolution 不完全）与假基因，须在分析前检查是否为\"干净\"的单一序列。"},{"id":"19.4","t":"ITS 区","s":3,"c":"19. 分子标记与序列获取","x":"ITS（internal transcribed spacer）指 18S 与 28S 之间的转录间隔区，含 ITS1、5.8S、ITS2，其中 ITS2 在植物与真菌中应用最广，真菌条形码首选ITS（ITS1+5.8S+ITS2）。ITS 演化快、分辨率高，适合近缘种与种下分析；但由于长度变异大、存在多拷贝与二级结构，多重比对困难，且易出现\"ITS 假基因\"导致的错误分组。"},{"id":"19.5","t":"线粒体基因与 cox1","s":3,"c":"19. 分子标记与序列获取","x":"动物线粒体基因（cox1、cytb、ND2、12S/16S rRNA）具有母系遗传、无重组、拷贝数高、演化快等优点，广泛用于种下与近缘种分析。cox1（COI）5′端约 648 bp 片段自 Hebert 等（2003）起成为动物 DNA 条形码标准区，其优点是多数动物类群可用通用引物扩增、种内变异通常小于种间；缺点是存在核线粒体片段（numt）、Wolbachia 感染导致的遗传多样性下降，以及在部分类群（如珊瑚、部分软体动物）变异速率异常。"},{"id":"19.6","t":"叶绿体基因与植物条形码","s":3,"c":"19. 分子标记与序列获取","x":"植物线粒体基因变异过慢，故条形码转向叶绿体基因：rbcL（编码Rubisco 大亚基，保守、易扩增、分辨率较低）与 matK（编码成熟酶，演化快、分辨率高但通用引物扩增成功率较低）被 CBOL 植物工作组（2009）建议为组合核心，常辅以 trnH-psbA 间隔区与 ITS2。叶绿体基因组为母系遗传、结构保守、无重组，适合深—中层级系统发生；但母系遗传意味着杂交与渐渗时叶绿体树可能偏离物种树。"},{"id":"19.7","t":"高通量标记","s":2,"c":"19. 分子标记与序列获取","x":"二代测序带来的常用标记包括：微卫星（SSR，共显性、多态性高、适合居群遗传）、SNP（全基因组或简化基因组如 RAD-seq、GBS）、超保守元件（UCE，适用于博物馆标本与远缘类群）、以及靶序列富集（anchored hybrid enrichment）。选择依据是样本 DNA 质量（降解样本优先 UCE）、所需系统发生层级（深→UCE/转录组，浅→SNP/SSR）与预算。"},{"id":"19.8","t":"序列获取的实验流程","s":2,"c":"19. 分子标记与序列获取","x":"标准流程为：凭证标本取样（组织干燥或乙醇保存）→ DNA 提取 → 引物选择与 PCR 扩增 → 电泳检验 → 双向测序 → 拼接与校对（Chromatogram 检查双峰）→ 提交 GenBank 并附凭证号。质量控制要点：阴性对照排除污染、双向测序消除单侧错误、杂合位点用 IUPAC 简并碱基标注。任何环节记录缺失都会损害可重复性。"},{"id":"19.9","t":"序列数据的规范提交","s":2,"c":"19. 分子标记与序列获取","x":"提交公共数据库须包含：序列本身、物种名（经凭证核实）、凭证标本号与保藏地、采集地与采集人、引物信息、以及是否为全长/部分序列。GenBank 等数据库的\"错误鉴定\"是条形码误判的主要来源之一，故使用公共数据时应优先选择标注 voucher 的条目，并对关键结论做重新核对。"},{"id":"20.1","t":"序列比对的目标与类型","s":3,"c":"20. 序列比对与替代模型","x":"序列比对（alignment）的目标是判定位点的同源性（ positional homology），使不同序列的同一列对应同一祖先位点。类型包括：双序列全局比对（Needleman–Wunsch）、局部比对（Smith–Waterman）、多重比对（三条以上序列）、以及结构比对（按二级结构对齐 rRNA）。比对是同源判定的操作化，其错误会直接生成\"假性状\"，是系统发生分析中最常见的系统性误差来源。"},{"id":"20.2","t":"比对算法","s":2,"c":"20. 序列比对与替代模型","x":"渐进式算法（如 Clustal 系列）先对最相似序列两两比对再逐步加入，速度快但对初始顺序敏感；迭代式算法（如 MUSCLE、MAFFT 的 L-INS-i）反复优化，准确性更高；隐马尔可夫与概率比对（如 PAGAN、BAli-Phy）可在比对同时考虑树的不确定性。RNA 基因应按二级结构比对（如使用 SSUALIGN），否则高变区易错配。"},{"id":"20.3","t":"空位与模糊区的处理","s":3,"c":"20. 序列比对与替代模型","x":"空位（gap）的处理有三种常见策略：完全忽略（pairwise deletion）、把空位作为第五种状态、或按 indel 模型处理；模糊区（ambiguous alignment）常被剔除。规范做法是：先保留全部位点作主分析，再用剔除高变异区的数据重复分析，比较拓扑是否改变（敏感性分析）；若结论随空位处理而剧烈变化，说明数据本身支持不足，不应只报\"最好看\"的结果。"},{"id":"20.4","t":"替代模型的结构","s":3,"c":"20. 序列比对与替代模型","x":"DNA 替代模型由三部分构成：各碱基频率（可设为相等或取经验值）、各替换类型的相对速率（如转换/颠换比 κ）、以及速率在位点间的分布。基础模型包括 JC（1969，单参数，所有替换等速、频率相等）、K2P（Kimura 1980，区分转换与颠换）、F81（频率不等）、HKY85（频率不等+转换颠换不等）、TN93、以及最一般的 GTR（六种替换速率自由，加经验频率）。"},{"id":"20.5","t":"速率异质性参数","s":3,"c":"20. 序列比对与替代模型","x":"位点间速率差异用离散 Gamma 分布刻画（+Γ，形状参数 α 越小表示异质性越强，α→∞ 时退化为等速），不变位点比例用 +I 表示。规范写法如GTR+Γ+I 表示\"GTR 替换结构 + Gamma 速率异质性 + 不变位点\"。实践中 α通常 0.1—1.5；模型选择时应比较 +Γ 与 +Γ+I 的拟合（+I 与 +Γ 部分重复，同用需谨慎，现多推荐 +Γ 或 +I+Γ 由 AIC 决定）。"},{"id":"20.6","t":"模型选择的方法","s":2,"c":"20. 序列比对与替代模型","x":"常用工具（jModelTest、ModelTest-NG、PartitionFinder）按AIC/BIC 排序候选模型。要点有三：模型选择应在同一数据集、同一比对版本下进行；结果差异小于 2 个 AIC 单位时视为等价，可优先选参数少的模型；不同分区（密码子位置、基因）应分别选模型。模型误设的典型后果是长枝被系统性拉长（JC 拟合高变数据时尤为明显）。"},{"id":"20.7","t":"饱和与碱基组成偏倚","s":3,"c":"20. 序列比对与替代模型","x":"饱和（saturation）指随分歧增大，观测差异不再随之增加（多次打击使差异被掩盖），可用转换/颠换对分歧作散点图判断；转换通常先饱和。碱基组成偏倚（base composition bias）指不同类群的 GC 含量显著不同，会使不近缘的类群因组成相似而聚在一起，可用 LogDet 距离或组成异质性模型缓解。两者都是\"数据质量评估\"（如用 DAMBE、MEGA 作图）的必查项目。"},{"id":"20.8","t":"长枝吸引的识别与消除","s":3,"c":"20. 序列比对与替代模型","x":"长枝吸引（LBA）的典型征兆是：两条（或多条）枝长显著大于其他的末端在树中聚为一支，且删除其中之一后拓扑显著改变。消除手段包括：改用对LBA 较稳健的似然法/贝叶斯法（含合理模型）、增加分类单元取样以打断长枝、剔除高变异位点、使用组成异质性模型、以及检查是否存在远缘外群（远外群易自成长枝）。"},{"id":"21.1","t":"分子钟假说","s":3,"c":"21. 分子钟、基因组学与条形码","x":"Zuckerkandl 与 Pauling（1962、1965）提出：分子演化速率在一定范围内近似恒定，故序列差异可与分歧时间成正比。分子钟使\"没有化石的类群\"也能估算分歧时间，但严格恒速在绝大多数类群中并不成立：不同基因、不同位点、不同支系的速率差异可差数倍，故现代实践普遍使用\"宽松分子钟\"（relaxed clock）。"},{"id":"21.2","t":"时间标定与校准点","s":3,"c":"21. 分子钟、基因组学与条形码","x":"估算绝对时间必须有校准：化石校准（最早化石的层位给出最小年龄）、地质事件校准（如巴拿马地峡闭合、岛屿形成）、或次级校准（其他研究的速率）。校准应置于可辩护的节点，并给出先验分布（如对数正态）而非固定点，因为\"最早化石\"只是最小年龄。校准点选择不当是分歧时间研究最主要的错误来源，其后果比建树方法的选择更大。"},{"id":"21.3","t":"严格钟与宽松钟","s":2,"c":"21. 分子钟、基因组学与条形码","x":"严格分子钟假设所有支系速率相同，用单一速率参数；宽松钟容许速率在支系间变化，常见实现有不相关对数正态（uncorrelated lognormal）与随机局部钟（random local clock）。检验是否可用严格钟的办法是：先用宽松钟估计，若各支速率变异系数很小，则严格钟可接受。软件实现以BEAST/BEAST 2 为代表，输出为带置信区间的 time tree。"},{"id":"21.4","t":"分歧时间与地质年代的对应","s":2,"c":"21. 分子钟、基因组学与条形码","x":"把分歧时间与地质年代对应时须注意：节点的年龄是\"谱系分歧\"的估计，不等于\"类群起源的最早化石\"；分子估计常比化石记录更早，原因包括谱系分选（lineage sorting）与化石保存偏差。写作规范是给出\"平均值 + 95% 最高后验密度区间（HPD）\"，而不是单一数字。"},{"id":"21.5","t":"系统发生基因组学","s":3,"c":"21. 分子钟、基因组学与条形码","x":"系统发生基因组学（phylogenomics）用数百至数千个基因座重建系统树，其核心问题不再是\"数据不够\"，而是\"数据冲突\"：不同基因的树可能因不完全谱系分选（ILS）、基因重复与丢失、水平基因转移、渐渗而互相矛盾。处理方法包括串联法（concatenation）、基于溯祖的合并法（如 ASTRAL）、以及同时估计物种树与基因树的方法（如 *BEAST）。"},{"id":"21.6","t":"基因树与物种树的冲突","s":3,"c":"21. 分子钟、基因组学与条形码","x":"基因树不等于物种树，冲突来源有四：不完全谱系分选（ILS，尤其在大种群、快速辐射时常见）、基因重复与丢失导致的旁系同源错误、水平基因转移（HGT，原核生物尤为普遍）、以及杂交与渐渗。判断方法：检查冲突是否集中在短内部枝（ILS 的典型征兆）、是否与基因功能类别相关、是否能用网络法解释。忽视这一区分会把\"基因树冲突\"误读为\"数据错误\"。"},{"id":"21.7","t":"DNA 条形码的标准流程","s":3,"c":"21. 分子钟、基因组学与条形码","x":"标准流程为：凭证取样 → DNA 提取 → 标准区段扩增（动物 cox1 5′端、植物 rbcL+matK、真菌 ITS）→ 双向测序与拼接 → 与参考库（BOLD、GenBank）比对 → 依 barcode gap 或阈值给出鉴定结论 → 附凭证信息入库。规范要求样品与凭证一一对应、序列长度与质量达标、并报告相似度与覆盖度；对新种或疑难类群，条形码只能提示\"候选新种\"，需形态与多基因证据确认。"},{"id":"21.8","t":"条形码的阈值争议与整合","s":2,"c":"21. 分子钟、基因组学与条形码","x":"固定阈值（如 3%）在实践中屡遭挑战：不同类群的种内变异可从 0.1%到10%以上，且种间差异可能小于种内差异（近期分化类群）。因此现代趋势是\"不用单一阈值，而用 barcode gap 的存在性 + 多基因 + 形态\"作整合判断。分子数据与形态数据的整合原则是：形态提供可检验的假说与鉴定接口，分子提供独立的字符与分化度量，二者冲突时应重新检视物种概念与取样，而非简单取一方。第七篇 生物分类系统与多样性"},{"id":"22.1","t":"五界系统","s":3,"c":"22. 三域系统与五界之争","x":"Whittaker（1969）提出五界系统：原核生物界（Monera）、原生生物界（Protista）、真菌界（Fungi）、植物界（Plantae）、动物界（Animalia），其划分依据是细胞结构（原核/真核）与营养方式（吸收、光合、摄食）。五界系统在 20 世纪 70—80 年代的教材中占主流，其贡献是把真菌从植物中独立出来；局限是把并系的\"原生生物\"当作一个界。"},{"id":"22.2","t":"三域系统","s":3,"c":"22. 三域系统与五界之争","x":"Woese 与 Fox（1977）依据 16S rRNA 序列比较发现原核生物分为两支——细菌（Bacteria）与古菌（Archaea），且古菌与真核生物在多个分子特征上更近；Woese 等（1990）正式提出三域系统：细菌域、古菌域、真核域（Eukarya）。三域系统的革命性在于：它把\"原核生物\"这一形态学概念拆开，证明\"原核 vs 真核\"是并系式划分。"},{"id":"22.3","t":"六界与其他方案","s":2,"c":"22. 三域系统与五界之争","x":"六界系统（如 Cavalier-Smith 的方案）把三域中的细菌与古菌各自独立为界，即真细菌界、古细菌界、原生生物界、真菌界、植物界、动物界，实质是三域与传统界的折中。此外还有二域方案（如把真核生物并入古菌支系，因Asgard 古菌与真核生物同源）与\"域上加界\"的方案。教材与竞赛通常要求掌握五界与三域两套体系及其证据差异。"},{"id":"22.4","t":"三域划分的分子证据","s":3,"c":"22. 三域系统与五界之争","x":"支持三域的证据包括：16S rRNA 序列差异（三支各自单系）、细胞膜脂质类型（细菌与真核为酯键直链脂肪酸，古菌为醚键类异戊二烯）、细胞壁成分（细菌为肽聚糖，古菌无肽聚糖而多为假肽聚糖或蛋白表层）、RNA 聚合酶亚基结构、以及翻译起始因子的同源性。这些\"分子共衍征\"比形态更可靠地支持了三域划分。"},{"id":"22.5","t":"二域假说与真核生物的起源","s":2,"c":"22. 三域系统与五界之争","x":"二域假说认为真核生物不是与古菌并列的域，而是从古菌的一个支系（Asgard 古菌，如洛基古菌 Lokiarchaeota）内部衍生出来的，因此生命应分为细菌与古菌两域。支持证据是 Asgard 古菌携带大量\"真核特征蛋白\"（如细胞骨架、膜泡运输相关基因）。该假说目前仍在讨论中，竞赛只要求理解\"三域 vs 二域\"的争论焦点在于真核生物的归属。"},{"id":"22.6","t":"内共生学说与真核细胞起源","s":3,"c":"22. 三域系统与五界之争","x":"线粒体源于 α-变形菌、叶绿体源于蓝细菌的内共生（endosymbiotic theory，Margulis 系统化），证据包括：双层膜、自有环状 DNA、70S 核糖体、与细菌相似的繁殖方式（二分）、以及基因大量转移至核基因组。这一学说解释了真核生物内\"基因组拼盘\"的现象，也是理解藻类多系（不同藻类获得叶绿体的次数不同）的关键。"},{"id":"22.7","t":"界级划分的困难","s":2,"c":"22. 三域系统与五界之争","x":"界级划分的困难有三：（1）原核与真核之间、单细胞与多细胞之间存在大量过渡形态（如黏菌、领鞭虫）；（2）并系的\"原生生物界\"无法用单系标准维持；（3）水平基因转移使\"树\"在微生物层面部分失效，需用网络表达。因此现代分类倾向于在界之上设域、在界之下增设门级支系，而不强求\"界必须单系且均质\"。"},{"id":"22.8","t":"分类系统的选择与教学","s":2,"c":"22. 三域系统与五界之争","x":"教学与竞赛中应把握\"两套体系、一个原则\"：五界系统便于描述营养方式与细胞结构差异，三域系统反映真实的亲缘关系；一个原则是\"凡并系群须加注说明\"。答题时若被问\"原生生物是否是自然类群\"，应回答\"不是，它是并系群，现多拆入若干真核超群\"。"},{"id":"23.1","t":"病毒的分类地位","s":3,"c":"23. 病毒与原核生物分类","x":"病毒无细胞结构、无自主代谢、无核糖体，只能在宿主细胞内复制，因此不属于三域中的任何一域，也不被现行细胞生物命名法规管辖。国际病毒分类委员会（ICTV）自 2020 年起采用与细胞生物类似但独立的等级：域（realm）、亚域、界、门、纲、目、科、属、种，其划分依据是基因组类型、复制方式与序列相似性。"},{"id":"23.2","t":"病毒的基因组类型与巴尔的摩分类","s":3,"c":"23. 病毒与原核生物分类","x":"Baltimore 分类（1971）按基因组类型与 mRNA 产生方式把病毒分为七类：双链 DNA（dsDNA）、单链 DNA（ssDNA）、双链 RNA（dsRNA）、正单链 RNA（+ssRNA）、负单链 RNA（−ssRNA）、逆转录病毒（RNA→DNA）、以及 DNA 逆转录病毒（dsDNA→RNA→DNA）。这一分类直接对应复制策略，比宿主类群更能反映病毒的本质差异。"},{"id":"23.3","t":"病毒是否\"有生命\"的争论","s":2,"c":"23. 病毒与原核生物分类","x":"争论焦点是\"生命\"的定义：若以自主代谢与细胞结构为标准，病毒不是生命；若以拥有遗传物质、能演化与复制为标准，病毒是\"生活在边缘的生命\"。巨型病毒（如 Mimivirus、Pandoravirus）的发现使界限更模糊，因其基因组规模与部分代谢基因超过某些寄生细菌。竞赛中应回答\"病毒是介于生命与非生命之间的复制实体\"，并说明理由。"},{"id":"23.4","t":"病毒与宿主基因组的整合","s":2,"c":"23. 病毒与原核生物分类","x":"逆转录病毒与部分 DNA 病毒可将基因组整合进宿主生殖细胞，形成内源病毒序列（ERV），并在宿主演化中留下\"分子化石\"，如人类基因组中约 8%来源于 ERV。整合既是病毒传播策略，也是宿主新基因的来源（如合胞素syncytin 参与胎盘形成）。这一现象说明病毒在系统发生研究中既是干扰（污染序列），也是信息（共同演化标记）。"},{"id":"23.5","t":"原核生物分类的多相方法","s":3,"c":"23. 病毒与原核生物分类","x":"原核生物分类采用\"多相分类\"（polyphasic taxonomy）：以 16S rRNA序列相似性（常用属级阈值 95%、种级 98.7%）为主，结合全基因组平均核苷酸一致性（ANI，种级阈值约 95%—96%）、DNA-DNA 杂交（历史方法）、G+C 含量、脂肪酸组成、生理生化与生态特征。单凭 16S 一条基因不足以界定种，这是与原核分类相关的常见考点。"},{"id":"23.6","t":"细菌与古菌的高级阶元","s":2,"c":"23. 病毒与原核生物分类","x":"细菌域已知 30 个以上门（如变形菌门 Proteobacteria、厚壁菌门Firmicutes、放线菌门 Actinobacteria、蓝细菌门 Cyanobacteria、拟杆菌门 Bacteroidetes），其划分主要依 16S rRNA 系统发生而非形态。古菌域传统分广古菌门（Euryarchaeota）与泉古菌门（Crenarchaeota），现扩展为TACK 与 DPANN 等超门，其中 Asgard 古菌与真核生物起源相关。"},{"id":"23.7","t":"原核生物命名的特殊性","s":2,"c":"23. 病毒与原核生物分类","x":"原核生物命名依《国际原核生物命名法规》（ICNP），与动物、植物法规不同：新种必须在《国际系统与进化微生物学杂志》（IJSEM）的有效发表名录中公布才算合格，且须保藏于两个不同国家的菌种保藏中心。名称的\"有效发表\"与\"合格发表\"在细菌学中依赖名录确认，这一程序性要求是竞赛易错点。"},{"id":"23.8","t":"原核生物多样性认识的方法依赖","s":2,"c":"23. 病毒与原核生物分类","x":"传统\"可培养\"方法只能认识不到 1%的微生物，故现代分类与多样性估计高度依赖免培养技术（16S 扩增子测序、宏基因组）。这意味着\"未培养微生物\"（microbial dark matter）在命名上长期缺位，且数据库偏向可培养类群。理解这一点，才能正确解读\"某环境中有多少未知门\"的报告。"},{"id":"24.1","t":"原生生物的并系性","s":3,"c":"24. 原生生物与真菌","x":"原生生物（Protista）指除真菌、植物、动物以外的真核生物，是典型的并系群（甚至多系群），因为其成员不包括后生动物、真菌与陆生植物的祖先。现代系统学把真核生物划分为若干超群：挖掘虫类（Excavata）、SAR（不等鞭毛类+囊泡虫类+有孔虫类）、古虫界（Discoba 等）、变形虫界（Amoebozoa）、后鞭毛界（Opisthokonta，含真菌与动物）、以及原始色素体生物（Archaeplastida，含红藻、绿藻与陆生植物）。"},{"id":"24.2","t":"藻类的多系性","s":3,"c":"24. 原生生物与真菌","x":"\"藻类\"不是单系群：蓝藻是细菌（蓝细菌门），红藻与绿藻属原始色素体生物，硅藻与褐藻属不等鞭毛类（Stramenopiles），甲藻属囊泡虫类（Alveolata），隐藻与裸藻则来自二次内共生。因此\"藻类\"只能作为生态—形态描述性术语，不能作为分类单元。判断某\"藻\"的亲缘，须看其质体的膜层数与色素组成（一次/二次/三次内共生的痕迹）。"},{"id":"24.3","t":"原生动物与\" Protozoa\"的处置","s":2,"c":"24. 原生生物与真菌","x":"原生动物（Protozoa）同样不是单系群，涵盖变形虫、纤毛虫、鞭毛虫、孢子虫等分属完全不同超群的类群。现代教材多按超群排列，把原先的\"原生动物门\"拆解；但在动物学教学中仍保留\"原生动物\"作为形态—功能层次的称呼，须注明其非单系性质。"},{"id":"24.4","t":"真菌界的范围与特征","s":3,"c":"24. 原生生物与真菌","x":"真菌界（Fungi）属后鞭毛界，其特征为：几丁质细胞壁、吸收式营养（分泌胞外酶）、糖原储存、无叶绿体、多数具分枝菌丝、孢子繁殖。真菌与动物互为姐妹群（均属 Opisthokonta），而非与植物近缘——这是分子系统学纠正传统观念的重要结论，也解释了真菌与动物在信号通路、代谢调控上的相似性。"},{"id":"24.5","t":"真菌的门级分类","s":3,"c":"24. 原生生物与真菌","x":"现行真菌界主要门类包括：微孢子虫门（Microsporidia，或与Rozellomycota 相关）、壶菌门（Chytridiomycota，具游动孢子）、芽枝霉门（Blastocladiomycota）、新美鞭菌门（Neocallimastigomycota，厌氧肠道真菌）、球囊菌门（Glomeromycota，形成丛枝菌根）、毛霉门（Mucoromycota）与捕虫霉门（Zoopagomycota，二者取代了并系的接合菌门 Zygomycota）、子囊菌门（Ascomycota，具子囊与子囊孢子）、担子菌门（Basidiomycota，具担子与担孢子）。子囊菌与担子菌合称\"高等真菌\"。"},{"id":"24.6","t":"地衣与共生体的分类","s":2,"c":"24. 原生生物与真菌","x":"地衣是真菌（共生菌 mycobiont）与藻类或蓝细菌（光合共生体photobiont）的稳定共生体，其分类与命名以真菌为准（即地衣学名是共生菌的名称），因为共生菌决定形态结构。这意味着同一地衣中的光合共生体可能与其他地衣共享，故\"一种地衣=一个物种\"的直觉并不严格成立。"},{"id":"24.7","t":"真菌与植物的关系","s":2,"c":"24. 原生生物与真菌","x":"真菌在植物登陆与演化中作用关键：丛枝菌根（球囊菌门）与大多数陆生植物共生，协助磷吸收；外生菌根（多为担子菌与子囊菌）与林木共生；内生真菌影响宿主抗虫与抗逆。系统学上这些共生关系可用于推断类群间的协同演化，但共生关系的特异性差异很大，不能直接当作分类性状。"},{"id":"24.8","t":"真菌分类的分子修订","s":2,"c":"24. 原生生物与真菌","x":"分子系统学对真菌分类改动巨大：接合菌门被拆解、微孢子虫从原生动物移入真菌相关类群、隐球菌与部分\"酵母\"的归属被重排、地衣型真菌在多处独立起源。这些修订说明\"形态简单\"（如单细胞酵母）常是简化而非原始，形态相似也可能源于趋同。学习真菌分类应以门级分子框架为骨架，再记关键形态特征。"},{"id":"25.1","t":"传统植物分类的等级框架","s":2,"c":"25. 植物高级阶元与 APG 系统","x":"传统（恩格勒、哈钦森系统）把植物界分为藻类、苔藓、蕨类、裸子植物、被子植物，被子植物再分双子叶与单子叶两纲。这一框架的问题在于：双子叶是并系群（单子叶嵌套于其内），藻类是多系群，而\"蕨类\"作为整体也非单系。理解这些\"传统类群的并系性质\"，是回答植物系统题的基本功。"},{"id":"25.2","t":"APG 系统的原则","s":3,"c":"25. 植物高级阶元与 APG 系统","x":"APG（Angiosperm Phylogeny Group）系统自 1998 年第一版起，完全以分子系统发生（rbcL、matK、atpB 等多基因）为依据，只承认单系群，取消\"双子叶纲\"等并系阶元，改用\"支系名称\"（如真双子叶 eudicots、蔷薇类rosids、菊类 asterids）而不强行指派阶元。APG IV（2016）共承认 64 目、416 科，是目前被子植物分类的国际标准。"},{"id":"25.3","t":"被子植物的基部支系","s":3,"c":"25. 植物高级阶元与 APG 系统","x":"被子植物最基部的三个目依次为无油樟目（Amborellales，仅无油樟Amborella trichopoda 一种，新喀里多尼亚特有）、睡莲目（Nymphaeales）、八角目（Austrobaileyales），合称 ANA 支。ANA 的顺序说明\"最原始\"的被子植物是水生或木本小乔木而非草本；无油樟因处于基部位置，成为研究被子植物祖先状态的关键物种。"},{"id":"25.4","t":"木兰类与单子叶植物","s":3,"c":"25. 植物高级阶元与 APG 系统","x":"木兰类（magnoliids）含木兰目、樟目、胡椒目、白桂皮目，为双子叶式胚但非真双子叶；单子叶植物（monocots）为单系群，特征为子叶一枚、平行脉、散生维管束、花部三轮，含泽泻目、百合目、天门冬目与鸭跖草类（棕榈目、姜目、禾本目）。禾本目即禾本科所在，是单子叶中经济价值最高的一支。"},{"id":"25.5","t":"真双子叶与核心支系","s":3,"c":"25. 植物高级阶元与 APG 系统","x":"真双子叶（eudicots）以三沟型花粉为共有衍征，含毛茛目、山龙眼目、石竹目等基部群，及两大核心支：蔷薇类（rosids，含豆目、蔷薇目、壳斗目、锦葵目、十字花目、葫芦目等）与菊类（asterids，含菊目、川续断目、伞形目、杜鹃花目、茄目、唇形目等）。十字花科（含拟南芥）属蔷薇类十字花目，菊科属菊类菊目，这一归属常被考到。"},{"id":"25.6","t":"裸子植物与蕨类的系统位置","s":2,"c":"25. 植物高级阶元与 APG 系统","x":"现存裸子植物含苏铁类、银杏、松柏类与买麻藤类（Gnetales）；分子证据表明买麻藤类嵌套于松柏类内部（与松科近缘），故\"松柏纲\"若排除买麻藤类即为并系。蕨类含石松类（lycophytes，含石松、卷柏、水韭）与广义蕨类（ferns，含木贼、松叶蕨、合囊蕨、水龙骨类）。苔藓植物中角苔类与维管植物关系最近，苔藓整体是否单系仍有讨论。"},{"id":"25.7","t":"植物分类的形态证据与 APG 的互补","s":2,"c":"25. 植物高级阶元与 APG 系统","x":"APG 虽以分子为依据，但其目、科仍以形态共衍征加以描述（如三沟花粉、胚珠被、花被分化），故分子框架与形态特征并非对立，而是互为验证。竞赛中常见\"APG 完全抛弃形态\"的说法，这是误解：APG 抛弃的是并系阶元，不是形态证据。"},{"id":"25.8","t":"科级鉴定的关键性状","s":2,"c":"25. 植物高级阶元与 APG 系统","x":"植物科级鉴定常用性状包括：花被分化与轮数、雄蕊数目与着生方式、子房位置（上位/下位）、心皮数目与合生情况、胚珠类型、果实类型、叶序与托叶、分泌组织与化学成分。这些性状的同源性须按第 11 章准则判定，且应以\"组合性状\"而非单一性状鉴定，避免因个别变异导致误判。"},{"id":"26.1","t":"侧生动物与真后生动物","s":3,"c":"26. 动物的门级分类","x":"后生动物（Metazoa）分为侧生动物（Parazoa，含多孔动物门 Porifera与扁盘动物门 Placozoa，无真正组织器官）与真后生动物（Eumetazoa，有真正的上皮组织、神经与肌肉）。海绵虽无神经，但其细胞可分化、有细胞识别，故为多细胞动物；扁盘动物仅有数种，体形扁平、无体腔与器官，是研究动物早期演化的模式类群。"},{"id":"26.2","t":"动物基部关系之争","s":2,"c":"26. 动物的门级分类","x":"分子系统学提出的关键问题是：栉水母（Ctenophora）与海绵谁先分出？部分基因组分析（如 Dunn 等 2008、Ryan 等 2013）支持栉水母位于最基部，这将意味着神经与肌肉或曾独立起源或曾丢失；另一部分研究支持海绵最基部。争论未定，原因是快速分化导致的短内部枝、模型选择敏感与长枝吸引。竞赛中应回答\"尚未定论，两种假说各有分子证据\"。"},{"id":"26.3","t":"两侧对称与原口/后口","s":3,"c":"26. 动物的门级分类","x":"两侧对称动物（Bilateria）分两大支：原口动物（Protostomia，胚孔发育为口）与后口动物（Deuterostomia，胚孔发育为肛门，口次生形成）。后口动物含棘皮动物门、半索动物门与脊索动物门（另有 Xenoturbellida、Ambulacraria 等），其共有衍征包括辐射卵裂、肠体腔法形成体腔、以及三胚层体制。原口与后口之分是动物学最重要的高阶元划分。"},{"id":"26.4","t":"冠轮动物","s":3,"c":"26. 动物的门级分类","x":"冠轮动物（Lophotrochozoa；Aguinaldo 等 1997）包含具触手冠（lophophore）或担轮幼虫（trochophore）的类群：扁形动物门、纽形动物门、软体动物门、环节动物门、腕足动物门、外肛动物门、内肛动物门、轮形动物门等。其共有特征为螺旋卵裂与担轮幼虫（部分类群次生丢失），分子证据（18S rDNA 等）支持其为单系群。"},{"id":"26.5","t":"蜕皮动物","s":3,"c":"26. 动物的门级分类","x":"蜕皮动物（Ecdysozoa）包括线虫动物门、线形动物门、曳鳃动物门、动吻动物门、铠甲动物门、缓步动物门与节肢动物门，其共有衍征为几丁质角质层与周期性蜕皮（ecdysis），表皮细胞无纤毛。分子证据把原先按体腔划分的\"假体腔动物\"拆散，这是\"体腔类型不能作为高阶元判据\"的典型例证。"},{"id":"26.6","t":"节肢动物的内部系统","s":3,"c":"26. 动物的门级分类","x":"节肢动物门（Arthropoda）传统分三/四亚门：螯肢亚门（Chelicerata，含蜘蛛、蝎、鲎）、甲壳亚门（Crustacea，虾蟹等）、六足亚门（Hexapoda，昆虫等）、多足亚门（Myriapoda，蜈蚣、马陆）。分子与神经解剖证据支持\"泛甲壳类\"（Pancrustacea）：六足类嵌套于甲壳类之内，与昆虫近缘的是鳃足类等，因此\"昆虫纲\"与\"甲壳纲\"的并列并不反映分支关系。"},{"id":"26.7","t":"后口动物的主要门","s":3,"c":"26. 动物的门级分类","x":"后口动物中，棘皮动物门（Echinodermata）成体五辐射对称、具水管系统与管足，幼虫为两侧对称，是\"个体发育揭示祖先状态\"的经典例证；半索动物门（Hemichordata）具鳃裂与口索，如柱头虫；脊索动物门（Chordata）以脊索、背神经管、咽鳃裂、肛后尾为共有衍征，含尾索动物、头索动物与脊椎动物三个亚门。"},{"id":"26.8","t":"门级划分的依据与争议","s":2,"c":"26. 动物的门级分类","x":"门级划分依据包括：体制与对称性、胚层与体腔、卵裂与胚胎发育、幼虫类型、附肢与分节方式、以及分子系统发生。争议主要来自三点：（1）体腔类型（无体腔、假体腔、真体腔）曾是高阶元主判据，现证明多次独立演化；（2）小型门（如动吻、铠甲动物）取样困难、序列易受污染；（3）快速辐射导致短内部枝，拓扑不稳定。"},{"id":"26.9","t":"无脊椎动物门数概览","s":2,"c":"26. 动物的门级分类","x":"Brusca 等《Invertebrates》按现代系统排列约三十余个门，其中种类最多的是节肢动物门（约占动物总种数的四分之三以上）、软体动物门、线虫动物门、环节动物门与扁形动物门。学习时应\"抓大放小\"：重点掌握十余个主要门的体制、胚层、体腔、幼虫与代表性类群，其余门记名称与关键特征即可。类群对称/体制胚层与体腔卵裂/幼虫代表多孔动物无对称无真正胚层无海绵刺胞动物辐射对称二胚层无水螅、珊瑚扁形动物两侧对称三胚层、无体腔螺旋卵裂涡虫环节动物两侧对称、分节三胚层、真体腔螺旋卵裂、担轮幼虫蚯蚓、沙蚕节肢动物两侧对称、分节三胚层、混合体腔表面卵裂昆虫、虾、蜘蛛棘皮动物成体五辐射三胚层、真体腔辐射卵裂、两侧对称幼虫海星"},{"id":"27.1","t":"系统生物学的定义","s":3,"c":"27. 系统生物学方法简介","x":"系统生物学（systems biology）研究生物系统中各组分（基因、蛋白、代谢物）之间的相互作用与整体行为，强调\"整体大于部分之和\"的涌现性（emergence），其方法是\"组学测量 + 网络构建 + 数学建模 + 扰动验证\"。须与本书主线的\"系统学（systematics）\"严格区分：前者问\"系统如何运作\"，后者问\"类群如何演化与如何分类\"。"},{"id":"27.2","t":"组学数据的层次与整合","s":2,"c":"27. 系统生物学方法简介","x":"主要组学层次包括：基因组（DNA 序列与变异）、转录组（RNA 表达）、蛋白组（蛋白丰度与修饰）、代谢组（小分子）、以及表观组与表型组。多组学整合（multi-omics integration）的目标是把不同层次的测量在同一统计框架下关联，常用方法有网络融合、矩阵分解与基于通路的整合；其最大挑战是样本量小、噪声大、批次效应强。"},{"id":"27.3","t":"网络分析的基本概念","s":2,"c":"27. 系统生物学方法简介","x":"生物网络把分子/基因表示为节点、把相互作用表示为边，常见类型有蛋白—蛋白互作网络、基因调控网络、代谢网络与信号网络。核心概念包括：度分布（生物网络常呈\"尺度自由\"的幂律分布）、枢纽节点（hub，高度连接者，多为必需基因）、模块（module，功能相关的紧密子图）、以及网络基序（motif）。分析方法是\"先建网、再找模块与枢纽、最后做功能富集与扰动验证\"。"},{"id":"27.4","t":"动力学建模","s":2,"c":"27. 系统生物学方法简介","x":"动力学建模用数学方程描述系统随时间的变化：常微分方程（ODE）适合连续变化的浓度（如代谢物、mRNA）、布尔网络适合定性描述基因开关逻辑、约束基础模型（如通量平衡分析 FBA）适合基因组尺度代谢网络、随机模型适合小分子数体系（如基因表达噪声）。建模的关键步骤是结构确定、参数估计与模型验证，其中参数估计常依赖实验数据拟合。"},{"id":"27.5","t":"系统生物学的典型成果","s":1,"c":"27. 系统生物学方法简介","x":"代表性成果包括：酵母细胞周期与代谢网络的系统解析、人类蛋白互作图谱、疾病网络（disease network，把表型相关的基因映射到网络模块）、以及基于网络的药物靶点与副作用预测。这些成果说明\"网络位置\"可以解释单基因分析无法解释的现象，如为什么不同基因突变会产生相似表型（同一模块内）。"},{"id":"27.6","t":"系统生物学与系统学的关系","s":2,"c":"27. 系统生物学方法简介","x":"二者有三点接口：（1）系统发生的比较框架为组学数据提供\"历史校正\"，如比较基因组学须在有根树上做 ancestral state reconstruction；（2）网络方法可用于系统发生分析（如分割网络 split network 表达冲突信号）；（3）系统发生本身可视为一种\"历史网络\"，其节点为祖先、边为谱系。但二者的核心问题、典型方法与成果形态完全不同，竞赛中不可混称。"},{"id":"27.7","t":"方法局限与常见误用","s":2,"c":"27. 系统生物学方法简介","x":"主要局限有：相关不等于因果（网络边多为相关性推断）、组学测量的噪声与偏差、模型参数不可辨识（多组参数拟合同一曲线）、以及\"涌现\"概念的滥用（把无法解释的现象一律称为涌现并非科学解释）。规范做法是\"预测—扰动—验证\"闭环：模型给出的预测须经基因敲除、药物抑制等实验检验。第八篇 系统学的应用与备考"},{"id":"28.1","t":"生物多样性编目与志书","s":3,"c":"28. 系统学的应用","x":"编目（inventory）与志书（flora/fauna）是系统学最基础的应用：前者回答\"某地区有多少种\"，后者提供分类修订、检索表、描述与分布图。我国代表性成果包括《中国植物志》（Flora of China 为其英文修订版）、《中国动物志》、《中国孢子植物志》，国际上有 Flora of China、Fauna Europaea等。编目数据的质量取决于凭证标本与分类修订水平，而非名录的长短。"},{"id":"28.2","t":"进化显著单元","s":3,"c":"28. 系统学的应用","x":"进化显著单元（evolutionary significant unit, ESU）是保护生物学中用于确定保护单元的种下单位：Ryder（1986）提出该概念，Moritz（1994）给出可操作定义——线粒体 DNA 单系且核等位基因频率显著分化。ESU 的意义在于把\"遗传独特性\"纳入保护决策，避免仅按物种名录保护而遗漏种下独特谱系；与之并列的\"管理单元（MU）\"则强调种群统计与生态交换。"},{"id":"28.3","t":"检疫与入侵种鉴定","s":3,"c":"28. 系统学的应用","x":"检疫与入侵种管理依赖快速、准确的鉴定：形态鉴定受虫态（卵、幼虫）限制，条形码与特异性 PCR 可弥补这一不足，如对检疫性实蝇、天牛、象甲、杂草种子的分子鉴定已有标准流程。鉴定错误会导致两种后果：把非检疫种误判为检疫种（贸易损失）或漏检（生态与农业风险），因此参考数据库的凭证可靠性至关重要。"},{"id":"28.4","t":"法医与食品溯源","s":2,"c":"28. 系统学的应用","x":"法医生物学用 DNA 条形码鉴定涉案生物检材（如走私野生动物制品、昆虫幼虫、毛发、鱼翅），食品溯源用条形码或 SNP 检测掺假（如鱼类制品以廉价种冒充名贵种、肉类掺混）。这类应用对\"标准化\"要求极高：需有公认的条形码区段、参考库、阈值与结果解释规范，且检验过程须留痕可复核。"},{"id":"28.5","t":"CITES 与贸易管制","s":2,"c":"28. 系统学的应用","x":"《濒危野生动植物种国际贸易公约》（CITES）以附录形式管制国际贸易：附录Ⅰ禁止商业贸易，附录Ⅱ需许可，附录Ⅲ为区域性保护。CITES 的管制单位是\"物种\"及其\"易于混淆的相似种\"，因此在鉴定上常要求区分近缘种与制品（如象牙、龟甲、鳄鱼皮），这正是分子鉴定发挥作用之处。"},{"id":"28.6","t":"教学与科普功能","s":1,"c":"28. 系统学的应用","x":"系统学为生物学教学提供\"统一坐标系\"：生理、生态、遗传的研究对象都需要准确的物种名称与系统位置才能比较。科普层面上，系统树是解释\"演化\"最有效的可视化工具，但也最易被误读（如读成\"进步阶梯\"）。因此教学应强调读树三原则：节点是祖先、旋转不改关系、枝长非时间。"},{"id":"28.7","t":"数据库与信息基础设施","s":2,"c":"28. 系统学的应用","x":"常用基础设施包括：GenBank（序列）、BOLD（条形码）、GBIF（分布记录）、IPNI/Index Fungorum（名称）、LPSN（原核名称）、以及各国标本馆数据库。使用这些数据的两条铁律是：核对凭证与鉴定来源、记录检索日期与版本，因为数据库内容会随修订而变化。"},{"id":"28.8","t":"分类学能力建设的现实问题","s":1,"c":"28. 系统学的应用","x":"当前存在\"分类学 impediment\"（分类学障碍）：传统分类学家减少、类群专家断层、而物种灭绝速度加快。应对措施包括 DNA 条形码与图像识别辅助鉴定、公民科学参与记录、以及把分类学纳入保护与检疫的常规预算。理解这一背景，有助于回答\"分子技术是否会取代分类学\"一类论述题。"},{"id":"29.1","t":"单系群与并系群的判据","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是把\"有共同祖先\"当作单系标准：并系群同样\"有共同祖先\"，错在排除部分后代。正确判据是\"含最近共同祖先及其全部后代\"。检验方法：在树上剪一刀，能否恰好剪出该群——能则为单系，不能则为并系或多系。"},{"id":"29.2","t":"并系与多系的区分","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是二者混用。并系群包含最近共同祖先但排除部分后代（如爬行纲排除鸟类）；多系群不包含最近共同祖先，其成员因趋同而被拼合（如\"恒温动物\"）。判别要点：问\"该群的最近共同祖先是否属于该群\"——属于为并系，不属于为多系。"},{"id":"29.3","t":"同源与同功的区分","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是按功能或名称判断同源。正确做法是看形态发生来源、相对位置与系统发生检验：人臂与蝙蝠翼同源（同一胚胎原基），鸟翼与昆虫翅同功（独立起源）。同功在支序分析中表现为同塑性，会增加树长，而不是\"另一种同源\"。"},{"id":"29.4","t":"祖征与衍征的极性判断","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是\"默认常见性状为祖征\"或\"默认简单性状为祖征\"。极性必须通过外群比较、化石、个体发育等方法判定，且是相对某个内群而言的：同一性状在A 群为衍征、在 B 群可能为祖征。脱离内群范围谈\"祖征/衍征\"无意义。"},{"id":"29.5","t":"支序图不等于进化时间轴","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是按图上左右或高低读\"谁先出现\"。支序图只表达分支顺序，节点的高低不代表时间；旋转节点不改变关系。只有经时间标定（化石校准、分子钟）的时间树才有年代含义。"},{"id":"29.6","t":"共同祖先不是现生类群","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是说\"人由黑猩猩演化而来\"\"某现生类群是另一现生类群的祖先\"。正确表述是二者共享共同祖先、互为姐妹群。现生类群都是演化树的末端，不是内部节点；内部节点代表已灭绝的祖先种群。"},{"id":"29.7","t":"简约法不等于\"最真\"","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是把\"步数最少\"当作\"最可能为真\"。简约法是一种推断准则，其合理性依赖于性状变化概率低这一前提；在长枝、饱和、速率异质的情形下会系统性出错（如长枝吸引）。因此需要多方法互证，并用支持度与敏感性分析评估稳健性。"},{"id":"29.8","t":"物种概念不能通用全体生物","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是拿生物学物种概念去判定细菌、无性生殖的藻类、化石。生物学物种概念依赖生殖隔离，对无性类群与化石不可操作；此时应改用系统发生学、形态学或生态学物种概念，并明确声明。"},{"id":"29.9","t":"\"原生生物\"\"藻类\"\"鱼\"\"爬行类\"的性质","s":3,"c":"29. 高频易错辨析（一）：概念与术语","x":"易错点是把这些传统类群当成单系群。原生生物、藻类、鱼纲、爬行纲、双子叶植物、接合菌门均为并系（或多系）群；在现代分类中或已拆分，或保留但须加注\"并系\"。判断依据见第 15 章。"},{"id":"30.1","t":"一致性指数与保留指数的含义","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是把 CI 当作\"支持度\"。CI = m/s 衡量性状与树的吻合程度，受性状数与末端数影响大，不能跨数据集比较，也不是分支支持度；RI =(g−s)/(g−m) 衡量相对随机状态的改善，较稳健。分支支持度须用自展、后验概率或衰减指数表达。"},{"id":"30.2","t":"自展值与后验概率不可直接比较","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是认为\"bootstrap 95% 比 BPP 0.90 更可信\"。二者定义不同：bootstrap 是重抽样下分支重现频率，BPP 是模型下的后验概率，后者通常偏高。规范做法是并列报告并说明方法，而不是把两个数值放在同一尺度上比较。"},{"id":"30.3","t":"支持度低不等于假说被否","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是\"支持度小于 50%即该分支不存在\"。低支持度只表示数据不足以解决该节点，应表达为多歧（未解决），而不是断言\"两支不近缘\"。同时，高支持度也可能来自系统性偏差（如长枝吸引），故支持度与稳健性需分开评估。"},{"id":"30.4","t":"外群选择与赋根的正确做法","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是随便取一个远缘类群作外群，或直接用中点法定根。外群应是与内群近缘、且自身极性明确的类群；外群过远会自成长枝，诱发 LBA 并给出错误极性。中点法仅在各支速率近似相等时可用，且不能替代外群比较来确定性状极性。"},{"id":"30.5","t":"分子距离与物种界限","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是用固定阈值（如 cox1 差异 3%）直接定种。种内变异幅度因类群而异，种间差异也可能小于种内差异（近期分化、渐渗）。正确做法是检验barcode gap 是否存在，并结合形态、生态、多基因证据。"},{"id":"30.6","t":"基因树与物种树的混同","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是\"一个基因的树就是物种树\"。基因树受不完全谱系分选、基因重复、HGT、渐渗影响，可能与物种树不一致。规范做法是多基因/基因组数据、明确区分串联法与溯祖法、并在冲突显著时报告冲突。"},{"id":"30.7","t":"比对与空位处理的随意性","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是选一个\"看起来整齐\"的比对就直接建树，或随意删除空位区而不报告。比对即同源判定，其错误会生成假性状；空位处理应作敏感性分析（保留/剔除/按 indel 模型），并报告结论是否随处理改变。"},{"id":"30.8","t":"模型选择的误区","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是\"总用 GTR+Γ+I 最保险\"或\"模型越复杂越好\"。模型应经 AIC/BIC比较选定；过度参数化会增大方差，过简会系统性低估长枝。不同分区应分别选模型，并报告所选模型与选择准则。"},{"id":"30.9","t":"分子钟与分歧时间的误用","s":3,"c":"30. 高频易错辨析（二）：方法与判据","x":"易错点是把\"序列差异除以速率\"直接当年代，或用一个校准点推出全部节点年代。分歧时间估计须有多重校准与先验分布，且须报告置信区间；单校准点、严格钟假设与错误速率都会导致系统性偏差。"},{"id":"31.1","t":"学名书写规范","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点有五：属名首字母未大写、种加词首字母大写、学名未用斜体（或命名人用了斜体）、在动物学名后随意加命名年份以外信息、把亚种加词写成种加词。规范为：属名首字母大写、种加词全小写、整体斜体、命名人正体，动物加逗号与年份，植物用标准缩写并可省略年份。"},{"id":"31.2","t":"命名人括号的含义","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是以为括号表示\"亚属\"或\"修订者\"。括号只表示该种已被移出原属（原组合改变），如 Panthera leo (Linnaeus, 1758)。植物学中括号用法类似，且可在括号后加\"comb. nov.\"标明新组合。"},{"id":"31.3","t":"有效发表与合格发表","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是认为\"网上发布\"\"学位论文\"\"会议摘要\"即可发表名称。动物要求有效发表（公开、可永久保存、符合印量与日期要求），植物要求在有效发表基础上再满足合格发表的条件（拉丁描述/特征集要、模式指定等）。电子出版须符合特定条件并注册。"},{"id":"31.4","t":"优先律与起点文献","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是认为\"优先律从林奈全部著作起算\"。动物以 1758 年 1 月 1 日《自然系统》第 10 版为起点，植物以 1753 年 5 月 1 日《植物种志》为起点，且优先律只在同一法规、同一阶元内适用（种加词优先不影响属名优先）。"},{"id":"31.5","t":"同名与同物异名","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是二者混用。同名（homonym）是\"同名不同物\"，后名永久无效；同物异名（synonym）是\"同物不同名\"，后名为异名。记忆口诀：名同查同名、物同查异名。"},{"id":"31.6","t":"模式标本的类型与地位","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是把副模、地模当作模式标本，或认为\"模式产地随名称自动转移\"。只有正模（主模式）、选模、新模等具命名地位；副模仅辅助，地模无地位；模式产地以正模采集地为准。"},{"id":"31.7","t":"品种不是分类阶元","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是把栽培品种（cultivar）写成三名法或当作亚种，或把品种名用斜体。品种依《国际栽培植物命名法规》命名，品种加词用单引号、正体，不受 ICN 与优先律管辖；家养动物品种亦不受 ICZN 管辖。"},{"id":"31.8","t":"凭证标本与序列的对应","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是发表序列时不提供凭证信息，或凭证与组织样本错配。规范要求给出凭证号、保藏机构与采集地，使他人能复核鉴定；无凭证的序列在分类学上不能作为命名或模式标定的依据。"},{"id":"31.9","t":"公共数据库的使用","s":3,"c":"31. 高频易错辨析（三）：学名、法规与数据","x":"易错点是直接信任 GenBank/BOLD 条目的物种名。数据库中存在错误鉴定、名称过时、凭证缺失等条目；使用时应优先选择有 voucher 与文献支持者，并对关键结论回溯原始文献或重新测序。"},{"id":"32.1","t":"分类阶元速查","s":3,"c":"32. 速查表与复习路线","x":"下表汇总基本阶元与其构词规律，用于快速判断名称所属阶元（看到-aceae 即科、-ales 即目等），并注意动物与植物的后缀差异。阶元动物后缀例植物后缀例备注界Animalia Plantae植物\"门\"称 division门Chordata Magnoliophyta细菌科名亦用 -aceae纲Mammalia Magnoliopsida传统双子叶纲为并系目Primates Rosales动物 -ida，植物 -ales科Hominidae Rosaceae名称由模式属词干构成属Homo Rosa首字母大写、斜体种Homo sapiens Rosa chinensis种加词小写、斜体"},{"id":"32.2","t":"三大分类流派对比速查","s":3,"c":"32. 速查表与复习路线","x":"下表把三派的核心主张压缩为可背诵的对照，重点记\"是否容许并系群\"与\"性状是否加权\"两项，这两项是辨析题的常考点。项目表征分类支序分类进化分类分类依据总体表型相似共同衍征血统+分化程度性状加权不加权只承认衍征隐性加权并系群容许不容许容许分类与树不必一致可部分不一致代表人物Sokal、Sneath必须一致Hennig Simpson、Mayr"},{"id":"32.3","t":"物种概念对比速查","s":3,"c":"32. 速查表与复习路线","x":"下表用于材料题\"应选哪种物种概念\"的判断：先看生殖方式，再看材料性质（现生/化石/仅分子），最后看研究目的。概念判据适用不适用生物学生殖隔离有性现生动物无性类群、化石形态学稳定形态差异普适隐存种、可塑性强的类群系统发生学固定鉴别性状/最小单系群普适、支序框架取样不足时膨胀演化独立演化谱系化石序列难以直接观测生态学同一适应带同域近缘种生态位难量化DNA 条形码序列差异/barcode gap隐存种筛查阈值不普适"},{"id":"32.4","t":"分子标记用途速查","s":3,"c":"32. 速查表与复习路线","x":"下表按\"解决层级—常用标记—注意点\"组织，答题时先判层级再选标记，可避免\"用 ITS 解科级关系\"\"用 18S 解种内分化\"一类错误。层级常用标记注意点域—门16S/18S rDNA、保守核基因分辨率有限，需多样本科—属18S、28S、rbcL、matK注意拷贝间异质与假基因属—种ITS、cox1、cytb、trnH-psbA需查 barcode gap种内—居群微卫星、SNP、RAD-seq需足够样本量与位点数"},{"id":"32.5","t":"主要门特征速查","s":3,"c":"32. 速查表与复习路线","x":"下表用于动物学部分的快速回忆：按\"对称—胚层—体腔—卵裂/幼虫\"四栏记忆，可覆盖大多数门级判断题，并注意\"体腔类型不能作高阶元判据\"。门对称体腔卵裂与幼虫备注多孔动物无无无侧生动物，细胞分化刺胞动物辐射无真体腔无二胚层，刺细胞扁形动物两侧无螺旋卵裂冠轮动物软体动物两侧真体腔（退化）螺旋、担轮幼虫冠轮动物节肢动物两侧混合体腔表面卵裂蜕皮动物，泛甲壳类棘皮动物成体五辐射真体腔辐射卵裂后口，水管系统脊索动物两侧真体腔不定脊索、背神经管、鳃裂"},{"id":"32.6","t":"复习路线与时间安排","s":3,"c":"32. 速查表与复习路线","x":"建议三轮推进。第一轮（约两周）打通主链：第 4—7 章（命名与鉴定）＋第 8—10 章（物种）＋第 14—15 章（读树与单系判据），目标是能独立解释\"为什么爬行纲是并系群\"\"为什么学名要斜体\"。第二轮（约三周）攻方法：第11—13 章（性状）＋第 16—18 章（建树与支持度）＋第 19—21 章（分子），目标是能手算 Fitch 算法、解释 CI/RI 差异、说明 LRT 与 AIC 的用途。第三轮（约一周）固系统与应用：第 22—26 章（分类系统）＋第 28 章（应用）＋第 29—31 章（易错辨析），目标是形成\"看到类群就能说出其系统位置与并系问题\"的条件反射。考前两天只看第 32 章的五张速查表与第 29—31 章的 27 条辨析，不再开新内容。附录：知识库教材索引本总纲的体系与事实依据取自以下五种馆藏教材，正文中的方法论框架主要对应第 1 本，分类学与类群系统的事实主要对应第 2—5 本。检索与引用时请注意版本差异：同名教材不同版次的分类系统可能不同（尤以被子植物与动物门级系统为甚）。序号教材主要用途对应篇章黄原《分子系统发生学》系统树、比对、进化模型、距离法/简约法/最大似然法/贝叶斯法、可靠性与长枝吸引、多源数据集第五、六篇陆树刚《植物分类学》（第 2 版）分类阶元、命名法规（ICN）、模式标本、检索表、植物高级阶元与APG 系统第二、七篇刘凌云、郑光美《普通动物学》（分类部分）动物门级分类、胚层与体腔、幼虫类型、各门代表类群第七篇陈阅增《普通生物学》（生物多样性篇）五界与三域、生物多样性编目、演化与分类的通论性表述第一、七篇Brusca、Giribet、Moore《Invertebrates》无脊椎动物各门系统位置、冠轮动物与蜕皮动物、泛甲壳类第七篇使用说明：以上五种教材在类群划分上存在版次差异（如 Brusca 第 4 版采用的动物门级系统与国内教材略有出入），备考时应以竞赛指定教材的表述为准，同时理解差异的来源是\"分类修订\"而非\"教材错误\"。凡本书与指定教材表述不一致处，建议按\"教材表述 + 修订依据\"两句话作答，既得分又显专业。"}]